  }
  $: if (plugins) plugins.publishState(pluginState)

  function showPluginNotification(message: string, kind: PluginNotificationKind = 'info') {
    const id = ++pluginToastSerial
    pluginToasts = [...pluginToasts, { id, message, kind }]
    const timer = setTimeout(() => {
      pluginToasts = pluginToasts.filter((toast) => toast.id !== id)
      pluginToastTimers.delete(timer)
    }, 5000)
    pluginToastTimers.add(timer)
  }
  let paintColor = '#ffab19'
  let secondaryPaintColor = '#ffffff'
  let paintGradient: 'solid' | 'horizontal' | 'vertical' | 'radial' = 'solid'
  // Transparent paint toggles (Scratch Paint parity: transparent is `null`,
  // independent from the hex picker so untoggling restores the last opaque
  // color instead of resetting it).
  let fillTransparent = false
  let secondaryTransparent = false
  let strokeTransparent = false
  let strokeColor = '#0f172a'
  // Independent stroke second color + gradient (Scratch Paint parity: the
  // outline keeps its own primary/secondary/gradient, separate from the fill
  // side, so fill and stroke ramps never share stops or ids).
  let strokeSecondaryColor = '#ffffff'
  let secondaryStrokeTransparent = false
  let strokeGradient: 'solid' | 'horizontal' | 'vertical' | 'radial' = 'solid'
  let strokeWidth = 4
  let vectorOpacity = 100
  // Selection-linked paint summary (scratch-paint fill/stroke/MIXED parity):
  // read-only, derived from the current SVG text + selection. Selection
  // changes never rewrite the artwork; the summary only drives MIXED badges.
  // `vectorStyleDirty` tracks fields the user explicitly changed since the
  // last successful Apply, so Apply touches only those fields and never
  // flattens a mixed value the user did not edit. Each dirty field carries an
  // owner: the selection set key observed when it was marked. A `none` owner
  // means "prepared while deselected" (preset flow) and survives selection
  // changes; any other owner is selection-derived and is discarded as soon as
  // the selection set changes (A->B, multi add/remove, marquee, select-all),
  // so stale A intent can never leak into B's Apply. Escape / artwork-switch
  // clear (`clearVectorObjectSelection`) still resets everything, including
  // presets. Undo/redo drops selection-owned entries even when the selection
  // key itself survives the artwork restore (see `restoreHistoryEntry`).
  let vectorStyleDirty: string[] = []
  let vectorStyleDirtyOwner: Record<string, string> = {}
  const VECTOR_STYLE_DESELECTED_KEY = '-1|'
  function vectorStyleSelectionKeyFor(index: number, indices: readonly number[]): string {
    return `${index}|${[...indices].sort((a, b) => a - b).join(',')}`
  }
  function currentVectorStyleSelectionKey(): string {
    return vectorStyleSelectionKeyFor(selectedVectorObjectIndex, selectedVectorObjectIndices)
  }
  function markVectorStyleDirty(field: string) {
    if (costumeEditMode !== 'vector') return
    if (!vectorStyleDirty.includes(field)) vectorStyleDirty = [...vectorStyleDirty, field]
    try {
      vectorStyleDirtyOwner[field] = currentVectorStyleSelectionKey()
    } catch {
      vectorStyleDirtyOwner[field] = VECTOR_STYLE_DESELECTED_KEY
    }
  }
  function clearVectorStyleDirty() {
    if (vectorStyleDirty.length > 0) vectorStyleDirty = []
    vectorStyleDirtyOwner = {}
  }
  function dropSelectionOwnedVectorStyleDirty() {
    if (vectorStyleDirty.length === 0) {
      if (Object.keys(vectorStyleDirtyOwner).length > 0) vectorStyleDirtyOwner = {}
      return
    }
    const kept = vectorStyleDirty.filter(
      (field) => (vectorStyleDirtyOwner[field] ?? VECTOR_STYLE_DESELECTED_KEY) === VECTOR_STYLE_DESELECTED_KEY,
    )
    if (kept.length === vectorStyleDirty.length) return
    vectorStyleDirty = kept
    const next: Record<string, string> = {}
    for (const field of kept) next[field] = VECTOR_STYLE_DESELECTED_KEY
    vectorStyleDirtyOwner = next
  }
  function consumeVectorStyleDirty(field: string) {
    if (vectorStyleDirty.includes(field)) vectorStyleDirty = vectorStyleDirty.filter((item) => item !== field)
    if (field in vectorStyleDirtyOwner) {
      const next = { ...vectorStyleDirtyOwner }
      delete next[field]
      vectorStyleDirtyOwner = next
