    const w = bitmapCanvas?.width ?? bitmapArtboard.width
    const h = bitmapCanvas?.height ?? bitmapArtboard.height
    const fallbackStage = selectedTarget?.isStage ?? bitmapArtboard.isStage
    return { originX: 0, originY: 0, canvasCenterX: w / 2, canvasCenterY: h / 2, isStage: fallbackStage, resolution: bitmapArtboard.resolution > 0 ? bitmapArtboard.resolution : fallbackStage ? 1 : 2, refused: false }
  }

  // True Scratch center in live canvas px, distinct from canvas.width/2.
  // The union canvas can be wider than the artboard (1000x100 res2 at
  // center 280,50 -> 1200px union: true center 480 vs width/2 600), so drag
  // snap AND the BitmapEditor guide must share this tracked value, never the
  // apparent middle. The pure math lives in bitmap-snap-center.ts
  // (resolveBitmapTrueCenter, unit-tested); these thin wrappers only adapt the
  // Editor's owner/target shapes. Rotation-handle drags keep this anchor
  // unchanged (they never snap); scale drags reuse the same settled guard.
  function computeBitmapTrueCenter(
    artboard: typeof bitmapArtboard,
    canvasWidth: number,
    canvasHeight: number,
    owner: typeof bitmapWorkspaceOwner,
    pending: typeof bitmapWorkspacePending,
    serial: number,
    revision: number,
    target: ScratchTarget | undefined,
  ): { x: number; y: number } | undefined {
    if (!target) return undefined
    return resolveBitmapTrueCenter({
      artboard,
      canvasWidth,
      canvasHeight,
      owner,
      pending,
      serial,
      revision,
      target: { targetId: stableTargetId(target), index: target.currentCostume ?? 0 },
    })
  }

  // (reactive guide state is declared after the workspace lets below)

  // Drag-time variant: same tracked anchor plus the drag-owner check so a
  // stale drag (target/costume switched mid-gesture, different res asset
  // reloaded under it) can never snap to the new artwork's center.
  function bitmapTrueCenterForDrag(drag: { targetName: string; costumeIndex: number } | undefined): { x: number; y: number } | undefined {
    try {
      if (!drag) return undefined
      if (!selectedTarget) return undefined
      if (selectedTarget.name !== drag.targetName) return undefined
      if ((selectedTarget.currentCostume ?? 0) !== drag.costumeIndex) return undefined
      if (!bitmapCanvas) return undefined
      if (bitmapArtboard.width !== bitmapCanvas.width || bitmapArtboard.height !== bitmapCanvas.height) return undefined
      return computeBitmapTrueCenter(
        bitmapArtboard,
        bitmapCanvas.width,
        bitmapCanvas.height,
        bitmapWorkspaceOwner,
        bitmapWorkspacePending,
        bitmapCanvasReloadSerial,
        assetPreviewRevision,
        selectedTarget,
      )
    } catch {
      return undefined
    }
  }

  function storedBitmapResolutionOf(target: ScratchTarget | undefined, index: number): number {
    const costume = target?.costumes[index]
    const res = costume?.bitmapResolution
    if (typeof res === 'number' && Number.isFinite(res) && res > 0) return res
    return target?.isStage ? 1 : 2
  }

  function bitmapPendingTransformDragActive(): boolean {
    return Boolean(bitmapPendingMoveDrag) || Boolean(bitmapPendingScaleDrag) || Boolean(bitmapPendingRotateDrag)
  }

  function bitmapPendingMoveScaleSession(): ReturnType<NonNullable<ReturnType<typeof ensureBitmapPendingController>>['get']> | undefined {
    try {
      if (!BITMAP_PENDING_UI_ENABLED) return undefined
      if (costumeEditMode !== 'bitmap') return undefined
      if (bitmapTool !== 'rect' && bitmapTool !== 'oval') return undefined
      const session = ensureBitmapPendingController()?.get()
      if (!session) return undefined
      if (!session.snapshot().hasPending) return undefined
      return session
    } catch {
      return undefined
    }
  }

  function startBitmapPendingMove(point: { x: number; y: number }, event: MouseEvent): boolean {
    try {
      if (!BITMAP_PENDING_UI_ENABLED) return false
      if (bitmapPendingTransformDragActive() || bitmapPendingPainting) return false
      if (bitmapMoveDrag || bitmapScaleDrag || bitmapRotateDrag) return false
      if (costumeEditMode !== 'bitmap' || (bitmapTool !== 'rect' && bitmapTool !== 'oval')) return false
      if (eyedropperActive) return false
      const session = bitmapPendingMoveScaleSession()
      if (!session) return false
      const shape = session.getPendingShape()
      if (!shape) return false
      if (!selectedTarget || !bitmapCanvas) return false
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        refuseStaleBitmapWorkspace('Bitmap move')
        return false
      }
      if (!bitmapSelection || !pointInBitmapRect(point, bitmapSelection)) return false
      const clampedStart = clampPointerIntoBounds(point, { left: 0, top: 0, right: bitmapCanvas.width, bottom: bitmapCanvas.height })
      bitmapPendingMoveDrag = {
        pointerId: (event as PointerEvent).pointerId ?? 0,
        startPoint: { ...clampedStart },
        startBox: { ...shape.box },
        startAffine: readStagedAffine(shape as never),
        appliedDx: 0,
        appliedDy: 0,
        targetName: selectedTarget.name,
        costumeIndex: gidx,
        guideOpacity: 0,
      }
      bitmapStrokeOwner = { targetId: gid, index: gidx, loadSerial: bitmapCanvasReloadSerial, generation: bitmapWorkspaceGeneration }
      isBitmapPainting = true
      status = 'Moving bitmap selection'
      return true
    } catch {
      bitmapPendingMoveDrag = undefined
      return false
    }
  }

  function moveBitmapPendingMove(event: PointerEvent): void {
    const drag = bitmapPendingMoveDrag
    if (!drag || !bitmapCanvas) return
    if (event.pointerId !== drag.pointerId) return
    try {
      const session = bitmapPendingMoveScaleSession()
      if (!session) {
        bitmapPendingMoveDrag = undefined
        return
      }
      const cur = currentBitmapIdentity()
      if (!cur || (selectedTarget && selectedTarget.name !== drag.targetName) || (selectedTarget && (selectedTarget.currentCostume ?? 0) !== drag.costumeIndex) || Boolean(bitmapWorkspacePending) || !isBitmapWorkspaceSettledFor(cur.targetId, cur.index)) {
        bitmapPendingMoveDrag = undefined
        refuseStaleBitmapWorkspace('Bitmap move')
        return
      }
      const rect = bitmapCanvas.getBoundingClientRect()
      const surfaceScale = rect.width > 0 && bitmapCanvas.width > 0 ? rect.width / bitmapCanvas.width : costumeViewportScale
      const rawPoint = bitmapPoint(event)
      const point = clampPointerIntoBounds(rawPoint, { left: 0, top: 0, right: bitmapCanvas.width, bottom: bitmapCanvas.height })
      const rawDx = point.x - drag.startPoint.x
      const rawDy = point.y - drag.startPoint.y
      const shiftKey = event.shiftKey === true
      const projected = shiftKey ? projectDeltaToStep({ x: rawDx, y: rawDy }) : { x: rawDx, y: rawDy }
      let dx = projected.x
      let dy = projected.y
      const snapCenter = bitmapTrueCenterForDrag({ targetName: drag.targetName, costumeIndex: drag.costumeIndex })
      if (!shiftKey && snapCenter && Number.isFinite(surfaceScale) && surfaceScale > 0) {
        try {
          const selectionCenter = { x: drag.startBox.x + drag.startBox.width / 2, y: drag.startBox.y + drag.startBox.height / 2 }
          const threshold = bitmapSnapThresholdCanvasPx(clampMoveViewportScale(costumeViewportScale))
          const measuredThreshold = 4 / surfaceScale
          const useThreshold = Number.isFinite(measuredThreshold) && measuredThreshold > 0 ? measuredThreshold : threshold
          const snap = resolveCenterSnap({ selectionCenter, dragVector: { x: projected.x, y: projected.y }, artCenter: snapCenter, thresholdPaper: useThreshold })
          if (snap.snapped && snap.snapVector) {
            dx = snap.snapVector.x
            dy = snap.snapVector.y
          }
        } catch {
          // Safe fail: keep the projected delta without snapping.
        }
      }
      // Absolute (not incremental): restart from the frozen startBox every
      // move so repeated moves cannot drift; the session itself re-renders
      // from its frozen base (never live+shape, no trail).
      const totalDx = dx
      const totalDy = dy
      const stepDx = totalDx - drag.appliedDx
      const stepDy = totalDy - drag.appliedDy
      if (Math.abs(stepDx) < 1e-9 && Math.abs(stepDy) < 1e-9) {
        // Still update the guide so hover feedback tracks the pointer.
        let guideOpacity = 0
        if (!shiftKey && snapCenter && (Math.abs(totalDx) >= 1e-9 || Math.abs(totalDy) >= 1e-9) && Number.isFinite(surfaceScale) && surfaceScale > 0) {
          try {
            const selectionCenter = { x: drag.startBox.x + drag.startBox.width / 2, y: drag.startBox.y + drag.startBox.height / 2 }
            const fade = bitmapFadeDistanceCanvasPx(clampMoveViewportScale(costumeViewportScale))
            const measuredFade = 10 / surfaceScale
            const useFade = Number.isFinite(measuredFade) && measuredFade > 0 ? measuredFade : fade
            const movedBounds: MoveRect = { left: drag.startBox.x + totalDx, top: drag.startBox.y + totalDy, right: drag.startBox.x + drag.startBox.width + totalDx, bottom: drag.startBox.y + drag.startBox.height + totalDy }
            guideOpacity = crosshairOpacityForBounds(movedBounds, { x: selectionCenter.x + projected.x, y: selectionCenter.y + projected.y }, snapCenter, useFade)
          } catch {
            guideOpacity = 0
          }
        }
        bitmapPendingMoveDrag = { ...drag, guideOpacity }
        return
      }
      const result = session.moveBy(stepDx, stepDy)
      if (!result.ok) {
        const reason = (result as { reason?: string }).reason ?? ''
        if (reason === 'owner-mismatch' || reason === 'superseded' || reason === 'invalid-scope') {
          bitmapPendingMoveDrag = undefined
          bitmapStrokeOwner = undefined
          isBitmapPainting = false
          status = 'live canvas left untouched (draft owner changed or uncertain; reloader owns pixels)'
          return
        }
        if (reason === 'history-gap' || reason === 'quarantine-full') {
          bitmapPendingMoveDrag = undefined
          bitmapStrokeOwner = undefined
          isBitmapPainting = false
          return
        }
        return
      }
      if (result.kind === 'unchanged') return
      drag.appliedDx = totalDx
      drag.appliedDy = totalDy
      let guideOpacity = 0
      if (!shiftKey && snapCenter && (Math.abs(totalDx) >= 1e-9 || Math.abs(totalDy) >= 1e-9) && Number.isFinite(surfaceScale) && surfaceScale > 0) {
        try {
          const selectionCenter = { x: drag.startBox.x + drag.startBox.width / 2, y: drag.startBox.y + drag.startBox.height / 2 }
          const fade = bitmapFadeDistanceCanvasPx(clampMoveViewportScale(costumeViewportScale))
          const measuredFade = 10 / surfaceScale
          const useFade = Number.isFinite(measuredFade) && measuredFade > 0 ? measuredFade : fade
          const movedBounds: MoveRect = { left: drag.startBox.x + totalDx, top: drag.startBox.y + totalDy, right: drag.startBox.x + drag.startBox.width + totalDx, bottom: drag.startBox.y + drag.startBox.height + totalDy }
          guideOpacity = crosshairOpacityForBounds(movedBounds, { x: selectionCenter.x + projected.x, y: selectionCenter.y + projected.y }, snapCenter, useFade)
        } catch {
          guideOpacity = 0
        }
      }
      bitmapPendingMoveDrag = { ...drag, appliedDx: totalDx, appliedDy: totalDy, guideOpacity }
      status = 'Moving bitmap selection'
    } catch {
      // Fail-closed: keep the staged pending, drop only the drag.
      bitmapPendingMoveDrag = undefined
    }
  }

  function endBitmapPendingMove(event: PointerEvent): boolean {
    const drag = bitmapPendingMoveDrag
    if (!drag) return false
    if (event.pointerId !== drag.pointerId) return false
    const endType = (event as PointerEvent | MouseEvent | undefined)?.type
    if (endType === 'pointercancel' || endType === 'lostpointercapture') {
      cancelBitmapPendingTransformDrag(drag, 'Bitmap move')
      return true
    }
    // pointerup keeps the shape staged (no commit, no history, no VM write).
    // The overlay already shows `base + moved shape` from the last moveBy.
    if (selectedTarget) {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        cancelBitmapPendingTransformDrag(drag, 'Bitmap move')
        refuseStaleBitmapWorkspace('Bitmap move')
        return true
      }
    }
    bitmapPendingMoveDrag = undefined
    bitmapStrokeOwner = undefined
    isBitmapPainting = false
    status = 'Moving bitmap selection'
    return true
  }

  function startBitmapPendingScale(event: PointerEvent, handle: BitmapFloatingScaleHandle = 'se'): boolean {
    try {
      if (!BITMAP_PENDING_UI_ENABLED) return false
      if (bitmapPendingTransformDragActive() || bitmapPendingPainting) return false
      if (bitmapMoveDrag || bitmapScaleDrag || bitmapRotateDrag) return false
      if (costumeEditMode !== 'bitmap' || (bitmapTool !== 'rect' && bitmapTool !== 'oval')) return false
      if (eyedropperActive) return false
      const validHandle: BitmapFloatingScaleHandle =
        handle === 'nw' || handle === 'n' || handle === 'ne' || handle === 'e' ||
        handle === 'se' || handle === 's' || handle === 'sw' || handle === 'w'
          ? handle
          : 'se'
      const session = bitmapPendingMoveScaleSession()
      if (!session) return false
      const shape = session.getPendingShape()
      if (!shape) return false
      if (!selectedTarget || !bitmapCanvas || !bitmapSelection) return false
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        refuseStaleBitmapWorkspace('Bitmap scale')
        return false
      }
      const rect = bitmapCanvas.getBoundingClientRect()
      if (!(rect.width > 0) || !(rect.height > 0)) return false
      const pointerX = ((event.clientX - rect.left) / rect.width) * bitmapCanvas.width
      const pointerY = ((event.clientY - rect.top) / rect.height) * bitmapCanvas.height
      if (!Number.isFinite(pointerX) || !Number.isFinite(pointerY)) return false
      try {
        ;(event.currentTarget as Element | null)?.setPointerCapture?.(event.pointerId)
      } catch {
        // Pointer capture is best-effort; the drag still tracks by pointer id.
      }
      const stagedRotation =
        (shape as { rotation?: unknown } | undefined)?.rotation
      const frozenRotation =
        typeof stagedRotation === 'number' && Number.isFinite(stagedRotation) ? stagedRotation : 0
      // Exact affine path for rotated/skewed shapes: freeze the START screen
      // box (existing AABB bounds), choose the opposite pivot (or the START
      // center for Alt), and resolve screen-axis scale with default
      // uniform/max, Shift free, Alt center, mirror. Axis-aligned shapes keep
      // the legacy retarget path byte-for-byte.
      const scaleUi = beginPendingScaleUi(
        shape as never,
        validHandle,
        { x: pointerX, y: pointerY },
        { altKey: event.altKey === true },
      )
      if (scaleUi.kind === 'affine') {
        bitmapPendingScaleDrag = {
          pointerId: event.pointerId,
          handle: validHandle,
          startPoint: { x: pointerX, y: pointerY },
          startBox: { ...shape.box },
          rotatedState: undefined,
          affineState: scaleUi.state,
          startAffine: scaleUi.startAffine,
          useAffine: true,
          targetName: selectedTarget.name,
          costumeIndex: gidx,
        }
      } else {
        const rotatedState = beginPendingRotatedScaleDrag(
          { ...shape.box },
          { x: pointerX, y: pointerY },
          frozenRotation,
          validHandle,
        )
        if (!rotatedState) return false
        bitmapPendingScaleDrag = {
          pointerId: event.pointerId,
          handle: validHandle,
          startPoint: { x: pointerX, y: pointerY },
          startBox: { ...shape.box },
          rotatedState,
          affineState: undefined,
          startAffine: readStagedAffine(shape as never),
          useAffine: false,
          targetName: selectedTarget.name,
          costumeIndex: gidx,
        }
      }
      bitmapStrokeOwner = { targetId: gid, index: gidx, loadSerial: bitmapCanvasReloadSerial, generation: bitmapWorkspaceGeneration }
      isBitmapPainting = true
      status = 'Scaling bitmap selection'
      event.preventDefault()
      return true
    } catch {
      bitmapPendingScaleDrag = undefined
      return false
    }
  }

  function moveBitmapPendingScale(event: PointerEvent): void {
    const drag = bitmapPendingScaleDrag
    if (!drag || !bitmapCanvas) return
    if (event.pointerId !== drag.pointerId) return
    try {
      const session = bitmapPendingMoveScaleSession()
      if (!session) {
        bitmapPendingScaleDrag = undefined
        return
      }
      const cur = currentBitmapIdentity()
      if (!cur || (selectedTarget && selectedTarget.name !== drag.targetName) || (selectedTarget && (selectedTarget.currentCostume ?? 0) !== drag.costumeIndex) || Boolean(bitmapWorkspacePending) || !isBitmapWorkspaceSettledFor(cur.targetId, cur.index)) {
        bitmapPendingScaleDrag = undefined
        refuseStaleBitmapWorkspace('Bitmap scale')
        return
      }
      const rect = bitmapCanvas.getBoundingClientRect()
      if (!(rect.width > 0) || !(rect.height > 0)) return
      const pointerX = ((event.clientX - rect.left) / rect.width) * bitmapCanvas.width
      const pointerY = ((event.clientY - rect.top) / rect.height) * bitmapCanvas.height
      if (!Number.isFinite(pointerX) || !Number.isFinite(pointerY)) return
      // Absolute (not incremental): resolve from the frozen drag origin every
      // move. When the staged shape is rotated/skewed the frozen `affineState`
      // measures DIRECT screen-axis ratios about the opposite pivot (or the
      // START center for Alt) and applies `session.stageAffine` (local box +
      // scalar rotation + style stay verbatim, gradients travel via the CTM).
      // Axis-aligned shapes keep the legacy local-frame retarget path.
      if (drag.useAffine && drag.affineState) {
        if (!Number.isFinite(pointerX) || !Number.isFinite(pointerY)) return
        const bounds = { width: bitmapCanvas.width, height: bitmapCanvas.height }
        const matrix = resolvePendingScaleUi(
          drag.affineState,
          { x: pointerX, y: pointerY },
          { shiftKey: event.shiftKey === true, altKey: event.altKey === true },
          bounds,
        )
        if (!matrix) return
        // Zero-delta stays exact with no late writes: the pure model replays
        // `M0` exactly, and the equality check below skips the session call
        // (no repaint, no renderRev, no VM, no history).
        const staged = session.getPendingShape()
        if (staged && isSameAffine(readStagedAffine(staged as never), matrix)) return
        const result = session.stageAffine(matrix)
        if (!result.ok) {
          const reason = (result as { reason?: string }).reason ?? ''
          if (reason === 'owner-mismatch' || reason === 'superseded' || reason === 'invalid-scope') {
            bitmapPendingScaleDrag = undefined
            bitmapStrokeOwner = undefined
            isBitmapPainting = false
            status = 'live canvas left untouched (draft owner changed or uncertain; reloader owns pixels)'
            return
          }
          if (reason === 'history-gap' || reason === 'quarantine-full') {
            bitmapPendingScaleDrag = undefined
            bitmapStrokeOwner = undefined
            isBitmapPainting = false
            return
          }
          return
        }
        if (result.kind === 'unchanged') return
        status = 'Scaling bitmap selection'
        return
      }
      // Absolute (not incremental): resolve from the frozen drag origin every
      // move. The frozen `rotatedState` maps the screen delta into the local
      // frame from the actual pointer-down (`startLocal` + handle anchor, so
      // zero delta replays the anchor with no initial jump), reuses the
      // shared axis-aligned resolver for Alt-center / Shift-uniform / mirror,
      // then re-pins the OPPOSITE screen anchor (`Cn = Cs + R * (Cn0 - Cs)`:
      // a local center shift under rotation would otherwise swing the pinned
      // screen edge). `session.retarget` preserves `rotation` verbatim.
      const frozen = drag.rotatedState
      if (!frozen) return
      const nextBox = resolvePendingRotatedScaleBox(
        frozen,
        { x: pointerX, y: pointerY },
        {
          shiftKey: event.shiftKey === true,
          altKey: event.altKey === true,
        },
      )
      if (!nextBox) return
      const current = session.getPendingShape()?.box
      if (current && current.x === nextBox.x && current.y === nextBox.y && current.width === nextBox.width && current.height === nextBox.height) return
      const result = session.retarget(nextBox)
      if (!result.ok) {
        const reason = (result as { reason?: string }).reason ?? ''
        if (reason === 'owner-mismatch' || reason === 'superseded' || reason === 'invalid-scope') {
          bitmapPendingScaleDrag = undefined
          bitmapStrokeOwner = undefined
          isBitmapPainting = false
          status = 'live canvas left untouched (draft owner changed or uncertain; reloader owns pixels)'
          return
        }
        if (reason === 'history-gap' || reason === 'quarantine-full') {
          bitmapPendingScaleDrag = undefined
          bitmapStrokeOwner = undefined
          isBitmapPainting = false
          return
        }
        return
      }
      if (result.kind === 'unchanged') return
      status = 'Scaling bitmap selection'
    } catch {
      // Fail-closed: keep the staged pending, drop only the drag.
      bitmapPendingScaleDrag = undefined
    }
  }

  function endBitmapPendingScale(event: PointerEvent): boolean {
    const drag = bitmapPendingScaleDrag
    if (!drag) return false
    if (event.pointerId !== drag.pointerId) return false
    const endType = (event as PointerEvent | MouseEvent | undefined)?.type
    if (endType === 'pointercancel' || endType === 'lostpointercapture') {
      cancelBitmapPendingTransformDrag(drag, 'Bitmap scale')
      return true
    }
    if (selectedTarget) {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        cancelBitmapPendingTransformDrag(drag, 'Bitmap scale')
        refuseStaleBitmapWorkspace('Bitmap scale')
        return true
      }
    }
    try {
      ;(event.currentTarget as Element | null)?.releasePointerCapture?.(event.pointerId)
    } catch {
      // Ignore release failures; the drag state is already cleared.
    }
    // pointerup keeps the shape staged (no commit, no history, no VM write).
    bitmapPendingScaleDrag = undefined
    bitmapStrokeOwner = undefined
    isBitmapPainting = false
    status = 'Scaling bitmap selection'
    return true
  }

  function cancelBitmapPendingTransformDrag(
    drag:
      | {
        startBox?: { x: number; y: number; width: number; height: number }
        startRotation?: number
        startAffine?: { a: number; b: number; c: number; d: number; e: number; f: number } | undefined
      }
      | undefined,
    kind: 'Bitmap move' | 'Bitmap scale' | 'Bitmap rotate',
  ): boolean {
    if (!drag) return false
    const wasMove = bitmapPendingMoveDrag !== undefined && drag === (bitmapPendingMoveDrag as unknown)
    const wasScale = bitmapPendingScaleDrag !== undefined && drag === (bitmapPendingScaleDrag as unknown)
    const wasRotate = bitmapPendingRotateDrag !== undefined && drag === (bitmapPendingRotateDrag as unknown)
    if (!wasMove && !wasScale && !wasRotate) return false
    try {
      // Restore the drag-start box/rotation/AFFINE through the session (frozen
      // base + single-pass repaint, no history, no VM). Owner-mismatch leaves
      // the live canvas untouched for the reloader; the staged pending itself
      // is retained (only the drag is cancelled). Scale/move drags restore
      // the FULL original affine (not just the box) so a rotated/skewed
      // `S * R` map returns exactly.
      const session = bitmapPendingMoveScaleSession()
      if (session && wasRotate && typeof drag.startRotation === 'number') {
        const currentRotation = (session.getPendingShape() as { rotation?: unknown } | undefined)?.rotation
        if (typeof currentRotation === 'number' && Math.abs(currentRotation - drag.startRotation) >= 1e-9) {
          try {
            session.rotateTo(drag.startRotation)
          } catch {
            // Best effort: the drag is still cleared below.
          }
        }
      } else {
        const staged = session?.getPendingShape()
        const startBox = (drag as { startBox?: { x: number; y: number; width: number; height: number } }).startBox
        if (session && staged && startBox && (staged.box.x !== startBox.x || staged.box.y !== startBox.y || staged.box.width !== startBox.width || staged.box.height !== startBox.height)) {
          try {
            session.retarget({ ...startBox })
          } catch {
            // Best effort: the drag is still cleared below.
          }
        }
        // Full affine restore (exact, no epsilon): `undefined` clears back to
        // legacy identity; mismatched matrices stage back through the session
        // (frozen base repaint, no history, no VM). Equality skips the call
        // so a zero-delta cancel writes nothing late.
        const startAffine = (drag as { startAffine?: { a: number; b: number; c: number; d: number; e: number; f: number } | undefined }).startAffine
        if (session && (wasMove || wasScale) && 'startAffine' in (drag as object)) {
          try {
            const currentAffine = readStagedAffine(staged as never)
            if (!isSameAffine(currentAffine, startAffine)) {
              session.stageAffine(startAffine as never)
            }
          } catch {
            // Best effort: the drag is still cleared below.
          }
        }
      }
    } catch {
      // Best effort only.
    }
    bitmapPendingMoveDrag = wasMove ? undefined : bitmapPendingMoveDrag
    bitmapPendingScaleDrag = wasScale ? undefined : bitmapPendingScaleDrag
    bitmapPendingRotateDrag = wasRotate ? undefined : bitmapPendingRotateDrag
    if (!bitmapPendingMoveDrag && !bitmapPendingScaleDrag && !bitmapPendingRotateDrag) {
      bitmapStrokeOwner = undefined
      isBitmapPainting = false
    }
    status = 'Bitmap edit cancelled'
    void kind
    return true
  }

  function cancelActiveBitmapPendingTransformDrag(): boolean {
    if (bitmapPendingMoveDrag) return cancelBitmapPendingTransformDrag(bitmapPendingMoveDrag, 'Bitmap move')
    if (bitmapPendingScaleDrag) return cancelBitmapPendingTransformDrag(bitmapPendingScaleDrag, 'Bitmap scale')
    if (bitmapPendingRotateDrag) return cancelBitmapPendingTransformDrag(bitmapPendingRotateDrag, 'Bitmap rotate')
    return false
  }

  function startBitmapPendingRotate(event: PointerEvent): boolean {
    try {
      if (!BITMAP_PENDING_UI_ENABLED) return false
      if (bitmapPendingTransformDragActive() || bitmapPendingPainting) return false
      if (bitmapMoveDrag || bitmapScaleDrag || bitmapRotateDrag) return false
      if (costumeEditMode !== 'bitmap' || (bitmapTool !== 'rect' && bitmapTool !== 'oval')) return false
      if (eyedropperActive) return false
      const session = bitmapPendingMoveScaleSession()
      if (!session) return false
      const shape = session.getPendingShape()
      if (!shape) return false
      if (!selectedTarget || !bitmapCanvas) return false
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        refuseStaleBitmapWorkspace('Bitmap rotate')
        return false
      }
      const rect = bitmapCanvas.getBoundingClientRect()
      if (!(rect.width > 0) || !(rect.height > 0)) return false
      const pointerX = ((event.clientX - rect.left) / rect.width) * bitmapCanvas.width
      const pointerY = ((event.clientY - rect.top) / rect.height) * bitmapCanvas.height
      if (!Number.isFinite(pointerX) || !Number.isFinite(pointerY)) return false
      const rotationRaw = (shape as { rotation?: unknown }).rotation
      const startRotation = typeof rotationRaw === 'number' && Number.isFinite(rotationRaw) ? rotationRaw : 0
      try {
        ;(event.currentTarget as Element | null)?.setPointerCapture?.(event.pointerId)
      } catch {
        // Pointer capture is best-effort; the drag still tracks by pointer id.
      }
      bitmapPendingRotateDrag = {
        pointerId: event.pointerId,
        startPoint: { x: pointerX, y: pointerY },
        center: { x: shape.box.x + shape.box.width / 2, y: shape.box.y + shape.box.height / 2 },
        startRotation,
        moved: false,
        targetName: selectedTarget.name,
        costumeIndex: gidx,
      }
      bitmapStrokeOwner = { targetId: gid, index: gidx, loadSerial: bitmapCanvasReloadSerial, generation: bitmapWorkspaceGeneration }
      isBitmapPainting = true
      status = 'Rotating bitmap selection'
      event.preventDefault()
      return true
    } catch {
      bitmapPendingRotateDrag = undefined
      return false
    }
  }

  function moveBitmapPendingRotate(event: PointerEvent): void {
    const drag = bitmapPendingRotateDrag
    if (!drag || !bitmapCanvas) return
    if (event.pointerId !== drag.pointerId) return
    try {
      const session = bitmapPendingMoveScaleSession()
      if (!session) {
        bitmapPendingRotateDrag = undefined
        return
      }
      const cur = currentBitmapIdentity()
      if (!cur || (selectedTarget && selectedTarget.name !== drag.targetName) || (selectedTarget && (selectedTarget.currentCostume ?? 0) !== drag.costumeIndex) || Boolean(bitmapWorkspacePending) || !isBitmapWorkspaceSettledFor(cur.targetId, cur.index)) {
        bitmapPendingRotateDrag = undefined
        refuseStaleBitmapWorkspace('Bitmap rotate')
        return
      }
      const rect = bitmapCanvas.getBoundingClientRect()
      if (!(rect.width > 0) || !(rect.height > 0)) return
      const pointerX = ((event.clientX - rect.left) / rect.width) * bitmapCanvas.width
      const pointerY = ((event.clientY - rect.top) / rect.height) * bitmapCanvas.height
      if (!Number.isFinite(pointerX) || !Number.isFinite(pointerY)) return
      // Absolute (not incremental): restart from the frozen start rotation
      // every move. Shift snaps the gesture delta to 45 degrees (reference
      // parity); toggling mid-drag recomputes cleanly from the same start.
      const gesture = resolveRotationGesture(drag.center, drag.startPoint, { x: pointerX, y: pointerY }, {
        shiftKey: event.shiftKey === true,
      })
      if (!gesture.valid || gesture.noop || isRotationNoop(gesture.appliedDeltaDegrees)) {
        // Snapped-to-zero / center-press: restore the drag-start rotation when
        // a previous move had previewed, otherwise leave the canvas untouched.
        if (drag.moved) {
          const restored = session.rotateTo(drag.startRotation)
          if (restored.ok) {
            drag.moved = false
            status = 'Rotating bitmap selection'
          } else {
            bitmapPendingRotateDrag = undefined
            bitmapStrokeOwner = undefined
            isBitmapPainting = false
            status = 'live canvas left untouched (draft owner changed or uncertain; reloader owns pixels)'
          }
        }
        return
      }
      const result = session.rotateTo(drag.startRotation + gesture.appliedDeltaDegrees)
      if (!result.ok) {
        const reason = (result as { reason?: string }).reason ?? ''
        if (reason === 'owner-mismatch' || reason === 'superseded' || reason === 'invalid-scope') {
          bitmapPendingRotateDrag = undefined
          bitmapStrokeOwner = undefined
          isBitmapPainting = false
          status = 'live canvas left untouched (draft owner changed or uncertain; reloader owns pixels)'
          return
        }
        if (reason === 'history-gap' || reason === 'quarantine-full') {
          bitmapPendingRotateDrag = undefined
          bitmapStrokeOwner = undefined
          isBitmapPainting = false
          return
        }
        return
      }
      if (result.kind === 'unchanged') return
      drag.moved = true
      status = gesture.snapped
        ? `Rotating bitmap selection (${Math.round(gesture.appliedDeltaDegrees)}°)`
        : 'Rotating bitmap selection'
    } catch {
      // Fail-closed: keep the staged pending, drop only the drag.
      bitmapPendingRotateDrag = undefined
    }
  }

  function endBitmapPendingRotate(event: PointerEvent): boolean {
    const drag = bitmapPendingRotateDrag
    if (!drag) return false
    if (event.pointerId !== drag.pointerId) return false
    const endType = (event as PointerEvent | MouseEvent | undefined)?.type
    if (endType === 'pointercancel' || endType === 'lostpointercapture') {
      cancelBitmapPendingTransformDrag(drag, 'Bitmap rotate')
      return true
    }
    if (selectedTarget) {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        cancelBitmapPendingTransformDrag(drag, 'Bitmap rotate')
        refuseStaleBitmapWorkspace('Bitmap rotate')
        return true
      }
    }
    try {
      ;(event.currentTarget as Element | null)?.releasePointerCapture?.(event.pointerId)
    } catch {
      // Ignore release failures; the drag state is already cleared.
    }
    // pointerup keeps the shape staged (no commit, no history, no VM write).
    bitmapPendingRotateDrag = undefined
    bitmapStrokeOwner = undefined
    isBitmapPainting = false
    status = 'Rotating bitmap selection'
    return true
  }

  // ---- Pending rect/oval session (B-3, feature helpers own the logic) ----
  function bitmapPendingSlotFor(target: ScratchTarget | undefined, index: number): BitmapPendingSlot | undefined {
    if (!target) return undefined
    return {
      targetId: stableTargetId(target),
      costumeIndex: index,
      loadSerial: bitmapCanvasReloadSerial,
      sessionGeneration: bitmapWorkspaceGeneration,
      projectGeneration: readProjectGenerationSafe(),
    }
  }

  function readSelectionEpochSafe(): number | null {
    try {
      const value = (vm as unknown as { getSelectionEpoch?: () => unknown }).getSelectionEpoch?.()
      if (typeof value === 'number' && Number.isInteger(value) && value >= 0) return value
    } catch {
      // Fall through to null below (unknown owner fails closed).
    }
    return null
  }

  /**
   * Reactive hostile snapshot hook (direct-VM fail-closed path).
   *
   * Detects stable identity / projectGeneration / selectionEpoch drift BEFORE
   * any canvas reload/teardown and retains the old staged immutable
   * base+shape OFF CANVAS via the controller. Never touches canvas or VM,
   * never paints old to new, never silently destroys. No-op
   * select/rename-same-bytes (same stable id + index + assetKey +
   * projectGeneration) preserves intentional state with zero writes; unknown
   * owners fail closed (retain conservatively); conflicting projects never
   * overwrite (CAS abort + quarantine, history-gap sticky in recovery).
   */
  function retainBitmapPendingForHostileSnapshot(
    next: { selectedTargetId?: string; project?: { targets?: Array<{ id?: string; name?: string; isStage?: boolean; currentCostume?: number; costumes?: Array<{ md5ext?: string; assetId?: string }> }> } },
    reason: string,
  ): void {
    try {
      if (!BITMAP_PENDING_UI_ENABLED) return
      const controller = bitmapPendingController
      if (!controller) return
      let unsaved = false
      try {
        unsaved = controller.hasUnsavedState()
      } catch {
        unsaved = true
      }
      if (!unsaved) return
      // Live VM readings (independent of the Svelte snapshot timing): the VM
      // is the authority after a direct external call.
      let liveProjectGen = 0
      try {
        liveProjectGen = readProjectGenerationSafe()
      } catch {
        liveProjectGen = 0
      }
      let liveSelEpoch: number | null = null
      try {
        liveSelEpoch = readSelectionEpochSafe()
      } catch {
        liveSelEpoch = null
      }
      const liveTargets = next?.project?.targets ?? []
      const wantId = typeof next?.selectedTargetId === 'string' ? next.selectedTargetId : ''
      const liveSel = liveTargets.find((t) => t.id === wantId) ?? liveTargets.find((t) => !t.isStage) ?? liveTargets[0]
      const liveStableId = typeof liveSel?.id === 'string' && liveSel.id.length > 0 ? liveSel.id : (liveSel?.name ?? '')
      const liveIndex = typeof liveSel?.currentCostume === 'number' ? liveSel.currentCostume : 0
      const liveCostume = liveSel?.costumes?.[liveIndex]
      const liveAssetKey = (liveCostume?.md5ext ?? liveCostume?.assetId ?? '') as string
      void liveSelEpoch
      void liveAssetKey
      void liveStableId
      void liveIndex
      // Fail-closed on unknown owner: retain conservatively, never destroy.
      if (!liveSel || !liveStableId) {
        controller.retainUnsavedForExternalChange(`${reason}:unknown-owner`)
        return
      }
      // In-flight own-write guard: while a stage commit is in flight, a
      // same-slot / same-project snapshot (own `storeAsset`/CAS landing,
      // assetKey bump only) must NOT abort/retain — the CAS identity
      // verification decides (preserved if not committed, gap sticky if
      // committed). Only a real slot/project move retains+aborts.
      try {
        const activeSnap = ((): { commitInFlight?: boolean } | undefined => {
          try {
            return (bitmapPendingController?.get()?.snapshot() ?? undefined) as { commitInFlight?: boolean } | undefined
          } catch {
            return undefined
          }
        })()
        if (activeSnap?.commitInFlight) {
          const oldTargetInFlight = selectedTarget
          const oldStableInFlight = oldTargetInFlight ? stableTargetId(oldTargetInFlight) : ''
          const oldIndexInFlight = oldTargetInFlight?.currentCostume ?? 0
          if (
            oldStableInFlight &&
            oldStableInFlight === liveStableId &&
            oldIndexInFlight === liveIndex &&
            liveProjectGen === bitmapPendingLastProjectGen
          ) {
            return
          }
        }
      } catch {
        // Uncertainty fails closed below.
      }
      // No-op preservation (same stable slot + same bytes + same project):
      // same-target reselect / same-bytes rename must keep the intentional
      // active pending with zero writes (not quarantine). Compare the OLD
      // Svelte selection (pre-swap) against the incoming snapshot; only a
      // real stable-id / index / assetKey / projectGeneration drift retains.
      try {
        const oldTarget = selectedTarget
        const oldStableId = oldTarget ? stableTargetId(oldTarget) : ''
        const oldIndex = oldTarget?.currentCostume ?? 0
        const oldCostume = oldTarget?.costumes[oldIndex]
        const oldAssetKey = (oldCostume?.md5ext ?? oldCostume?.assetId ?? '') as string
        if (
          oldStableId &&
          oldStableId === liveStableId &&
          oldIndex === liveIndex &&
          oldAssetKey === liveAssetKey &&
          liveProjectGen === bitmapPendingLastProjectGen
        ) {
          // No-op external (same slot, same bytes, same project): preserve
          // intentional state, zero writes, zero history. Selection-epoch
          // bumps alone never quarantine.
          return
        }
      } catch {
        // Uncertainty fails closed: fall through to retain below.
      }
      // Track the live generation for the next comparison (init on first use).
      try {
        bitmapPendingLastProjectGen = liveProjectGen
      } catch {
        // Best effort only.
      }
      controller.retainUnsavedForExternalChange(reason)
    } catch {
      // Best effort only: never break the VM event path.
    }
  }

  function ensureBitmapPendingController(): BitmapPendingController | undefined {
    // Incomplete-path kill switch (data-loss fix): the pending rect/oval
    // session is OFF by default. Return before any session creation so the
    // legacy immediate-raster path stays untouched and no pending callbacks
    // fire. Plain constant only: never consult localStorage / query strings.
    if (!BITMAP_PENDING_UI_ENABLED) {
      try {
        bitmapPendingController?.destroy('disabled')
      } catch {
        // Best effort only.
      }
      bitmapPendingController = undefined
      return undefined
    }
    if (!selectedTarget || !bitmapCanvas) return undefined
    if (!bitmapPendingController) {
      bitmapPendingController = new BitmapPendingController(vm as unknown as never, {
        onSelection: (selection) => {
          // The staged pending owns the selection outline: it replaces the
          // legacy committed `bitmapSelection` while pending, and clears it
          // on commit/discard. Non-pending selections (marquee/floating) are
          // untouched when there is no pending.
          try {
            if (bitmapPendingController?.hasPending()) {
              bitmapSelection = selection ? { ...selection } : undefined
            } else if (selection) {
              bitmapSelection = { ...selection }
            }
          } catch {
            // Best effort only.
          }
        },
        onStatus: (text: string) => {
          status = text
        },
        onSnapshot: (snapshot) => {
          bitmapPendingHas = snapshot.hasPending
          bitmapPendingGap = snapshot.historyGap
          // Recovery stays visible even when the live session is empty: the
          // retained off-canvas edit uses the SAME quarantine UI.
          bitmapPendingQuarantined = snapshot.quarantined || bitmapPendingRecoveryQuarantined || bitmapPendingRecoveryHas
          bitmapPendingKind = snapshot.pendingKind
          bitmapPendingMode = snapshot.pendingMode
        },
        onRecoverySnapshot: (recovery) => {
          // Sticky cross-slot gap visibility (silent-loss fix): while the
          // retained recovery carries `historyGap`, the effective gap UI
          // stays on even though the live session shows no gap.
          bitmapPendingRecoveryGap = recovery?.historyGap === true
          // Visible recovery UI (direct-VM hostile path): a retained
          // off-canvas recovery keeps the SAME pending-status + Export UI
          // after the new canvas is selected. Map it into the quarantined
          // display so `pendingStatusCount` / `pendingExportCount` stay
          // green and the status text keeps the `quarantined` keyword.
          bitmapPendingRecoveryHas = recovery?.hasRecovery === true
          bitmapPendingRecoveryQuarantined = recovery?.hasRecovery === true && (recovery?.quarantined === true || recovery?.hasPending === true)
          bitmapPendingRecoveryInFlight = recovery?.commitInFlight === true
          if (recovery?.hasRecovery === true && !bitmapPendingQuarantined) {
            bitmapPendingQuarantined = true
          }
          if (!recovery?.hasRecovery) {
            // Recovery cleared (explicit export/discard path refreshes via
            // ensure): re-derive the live quarantined flag on next snapshot.
          }
          if (recovery?.historyGap === true) {
            status =
              'history-gap: bytes committed without undo entry; explicit acknowledgement required before further paint/export/switch (Undo unavailable for last stroke)'
          }
        },
        peekHistory: async <E,>(): Promise<E | undefined> => {
          if (!selectedTarget) return undefined
          try {
            return (await peekCostumeHistory(selectedTarget, selectedTarget.currentCostume ?? 0)) as unknown as E | undefined
          } catch {
            return undefined
          }
        },
        commitHistory: <E,>(entry: E): boolean => {
          try {
            const before = paintUndoStack.length
            commitPaintHistory(entry as unknown as AssetHistoryEntry)
            // `commitPaintHistory` drops stale guards silently (no push): only
            // report success when the entry actually landed.
            return paintUndoStack.length === before + 1 || paintUndoStack.at(-1) === (entry as unknown)
          } catch {
            return false
          }
        },
        historyDepth: () => {
          try {
            return paintUndoStack.length
          } catch {
            return 0
          }
        },
        historyIsCurrent: () => {
          try {
            if (!selectedTarget) return false
            if (!isBitmapWorkspaceSettledFor(stableTargetId(selectedTarget), selectedTarget.currentCostume ?? 0)) return false
            return true
          } catch {
            return false
          }
        },
        tryRemoveHistory: <E,>(entry: E): boolean => {
          try {
            const index = paintUndoStack.lastIndexOf(entry as unknown as AssetHistoryEntry)
            if (index < 0) return false
            if (index !== paintUndoStack.length - 1) return false
            paintUndoStack = paintUndoStack.slice(0, -1)
            return true
          } catch {
            return false
          }
        },
        readConfig: () => {
          const target = selectedTarget
          const index = target?.currentCostume ?? 0
          const costume = target?.costumes[index]
          // Full-workspace commit: the stored PNG is the whole canvas, so
          // its rotation center is the workspace center (not the old cropped
          // center). Using the old center would shift the reloaded image by
          // the artboard origin and lose the committed edge.
          const centerX = bitmapCanvas ? bitmapCanvas.width / 2 : (typeof costume?.rotationCenterX === 'number' ? costume.rotationCenterX : undefined)
          const centerY = bitmapCanvas ? bitmapCanvas.height / 2 : (typeof costume?.rotationCenterY === 'number' ? costume.rotationCenterY : undefined)
          return {
            storedResolution: storedBitmapResolutionOf(target, index),
            viewportScale: costumeViewportScale,
            bitmapResolution: typeof costume?.bitmapResolution === 'number' ? costume.bitmapResolution : storedBitmapResolutionOf(target, index),
            rotationCenterX: centerX,
            rotationCenterY: centerY,
          }
        },
      })
    }
    const slot = bitmapPendingSlotFor(selectedTarget, selectedTarget.currentCostume ?? 0)
    if (!slot) return undefined
    try {
      // Track the generation the active slot was staged under so the
      // hostile no-op detector can compare exact project identity. Freeze
      // the pre-event target identity baseline (snapshot objects may share
      // live store references, so this frozen copy is the only reliable
      // pre-event truth for add/remove detection).
      try {
        bitmapPendingLastProjectGen = slot.projectGeneration ?? readProjectGenerationSafe()
      } catch {
        // Best effort only.
      }
      try {
        freezeBitmapPendingHostileSeen(vm.snapshot())
      } catch {
        // Best effort only.
      }
      const session = bitmapPendingController.ensure(slot, bitmapCanvas)
      void session
    } catch {
      return undefined
    }
    return bitmapPendingController
  }

  function bitmapPendingStyleNow() {
    return pendingStyleFromEditor({
      paintColor,
      secondaryPaintColor,
      paintGradient,
      fillTransparent,
      secondaryTransparent,
      brushSize,
    })
  }

  function isPendingRectOvalTool(): boolean {
    return bitmapTool === 'rect' || bitmapTool === 'oval'
  }

  /** Commit-first gate for destructive/structural UI ops ( BEFORE state changes). */
  async function guardBitmapPendingCommitFirst(command: string): Promise<boolean> {
    try {
      const controller = ensureBitmapPendingController()
      const session = controller?.get()
      if (!session) return true
      let snap: { hasPending: boolean; commitInFlight: boolean } | undefined
      try {
        snap = session.snapshot()
      } catch {
        return true
      }
      if (!snap || (!snap.hasPending && !snap.commitInFlight)) return true
      let preReloadScope: BitmapReloadCommitScope | undefined = undefined
      try {
        if (selectedTarget) {
          captureBitmapReloadBarrierForSlot(stableTargetId(selectedTarget), selectedTarget.currentCostume ?? 0)
          preReloadScope = captureBitmapReloadCommitScope(stableTargetId(selectedTarget), selectedTarget.currentCostume ?? 0)
        }
      } catch {
        // Best effort only.
      }
      const result = await session.commitPending()
      const preReloadScopeCurrent = preReloadScope ? isBitmapReloadCommitScopeCurrent(preReloadScope) : false
      if (!preReloadScope || (preReloadScope && bitmapPendingCommitBarrier === preReloadScope.barrier)) clearBitmapReloadBarrier()
      if (result.ok) {
        // Keep the committed selection outline cleared; the session already
        // repainted the committed raster exactly once.
        if (result.kind === 'committed' || result.kind === 'committed-without-history' || result.kind === 'nothing-to-commit') {
          if (result.kind !== 'nothing-to-commit') bitmapSelection = undefined
          if (result.kind === 'committed' || result.kind === 'committed-without-history') {
            try {
              if (preReloadScope && preReloadScopeCurrent) {
                const wantId = preReloadScope.targetId
                const index = preReloadScope.index
                if (bitmapWorkspaceOwner && bitmapWorkspaceOwner.targetId === wantId && bitmapWorkspaceOwner.index === index) {
                  const fresh = (vectorWriteTargetById(wantId, selectedTarget.name) ?? vm.getTarget(wantId) ?? vm.getTarget(selectedTarget.name))?.costumes[index] ?? selectedTarget.costumes[index]
                  bitmapWorkspaceOwner = { ...bitmapWorkspaceOwner, assetKey: fresh?.md5ext ?? fresh?.assetId ?? bitmapWorkspaceOwner.assetKey }
                }
                rememberPaintKnown(wantId, index, readLiveSlotIdentity(wantId, index))
                // Proven own write: arm the versioned skip from fresh live so
                // the store-driven reload is skipped only while live still
                // shows these bytes (any external drift fails closed).
                armBitmapReloadSkipFromLive(wantId, index)
              } else {
                clearBitmapReloadSkip()
              }
            } catch {
              // Best effort only.
            }
          }
        }
        if (result.kind === 'committed-without-history') {
          status = 'history-gap: bytes committed without undo entry; explicit acknowledgement required before further paint/export/switch (Undo unavailable for last stroke)'
          await reconcileDeferredBitmapReload()
          return false
        }
        await reconcileDeferredBitmapReload()
        return true
      }
      // Refused: retain the pending, surface the reason, block the op.
      // On ownership loss the session quarantines off-canvas (external wins)
      // while the canvas still shows the stale overlay: reload the rightful
      // live owner's latest bytes (scoped, no-op when already live).
      clearBitmapReloadSkip()
      await reloadBitmapCanvasIfPendingOwnershipLost(result)
      await reconcileDeferredBitmapReload()
      status = `Bitmap shape commit ${(result as { reason?: string }).reason ?? 'refused'} (op ${command} blocked; pending retained)`
      return false
    } catch (error) {
      clearBitmapReloadBarrier()
      clearBitmapReloadSkip()
      await reconcileDeferredBitmapReload()
      status = `Bitmap pending gate failed (${command}); op blocked, original preserved`
      void error
      return false
    }
  }

  /** Discard-first gate for delete/undo (restores base, no history). */
  function guardBitmapPendingDiscardFirst(command: string): boolean {
    try {
      const controller = ensureBitmapPendingController()
      const session = controller?.get()
      if (!session) return true
      let has = false
      try {
        has = session.snapshot().hasPending
      } catch {
        return true
      }
      if (!has) return true
      const result = session.discardForDeleteOrUndo()
      if (result.ok) {
        bitmapSelection = undefined
        status = command === 'paint-undo' ? 'Asset undo' : 'Bitmap shape discarded'
        return true
      }
      status = `Bitmap shape discard refused (${(result as { reason?: string }).reason ?? 'unknown'}); op blocked`
      return false
    } catch {
      status = `Bitmap pending discard failed (${command}); op blocked, original preserved`
      return false
    }
  }

  /** Fail-closed refusal for structural/switch UI while pending/inflight.
   * Captures stable identity + project generation synchronously (no canvas
   * redraw, no VM/history writes, no ensure/attach); disabled path stays
   * untouched (flag false or controller undefined falls through). Checks the
   * whole controller (`hasUnsavedState`/quarantine/gap/recovery) so a missing
   * active with retained recovery still refuses without attaching to the
   * wrong slot. Returns true when the op must be blocked. */
  function isBitmapPendingStructuralBlocked(op: string): boolean {
    try {
      if (!BITMAP_PENDING_UI_ENABLED) return false
      const controller = bitmapPendingController
      if (!controller) return false
      // No `ensure()` here: attaching/creating would mutate slot state and
      // could clear the active reference into recovery, turning a must-block
      // into a false allow. Read-only checks only.
      let unsaved = false
      try {
        unsaved = controller.hasUnsavedState()
      } catch {
        status = `Bitmap pending state unreadable (${op} blocked; op blocked, original preserved)`
        return true
      }
      if (!unsaved) {
        try {
          if (controller.hasQuarantine()) unsaved = true
          else if (controller.hasHistoryGap()) unsaved = true
          else if (controller.hasRecovery()) unsaved = true
        } catch {
          status = `Bitmap pending state unreadable (${op} blocked; op blocked, original preserved)`
          return true
        }
      }
      let snap: { hasPending: boolean; commitInFlight: boolean; historyGap?: boolean; quarantined?: boolean; quarantine?: boolean } | undefined
      let inFlight = false
      try {
        const session = controller.get()
        snap = session?.snapshot() as typeof snap
        if (snap && (snap.hasPending || snap.commitInFlight)) {
          unsaved = true
          inFlight = snap.commitInFlight === true
        }
      } catch {
        status = `Bitmap pending state unreadable (${op} blocked; op blocked, original preserved)`
        return true
      }
      if (!unsaved) {
        // Recovery-only pending (active missing): inspect retained entries
        // without attaching. Any pending/in-flight/gap/quarantine refuses.
        try {
          const recovery = controller.getRecoveryState()
          for (const entry of recovery.entries ?? []) {
            if (entry.hasPending || entry.commitInFlight || entry.historyGap || entry.quarantined) {
              unsaved = true
              if (entry.commitInFlight) inFlight = true
              break
            }
          }
        } catch {
          status = `Bitmap pending state unreadable (${op} blocked; op blocked, original preserved)`
          return true
        }
      }
      if (!unsaved) return false
      // Captured stable identity + project generation: proves the refusal
      // belongs to the live slot and survives a same-name target swap.
      let entryId = ''
      let entryGen = 0
      try {
        entryId = selectedTarget ? stableTargetId(selectedTarget) : ''
        entryGen = readProjectGenerationSafe()
      } catch {
        // Best effort only.
      }
      void entryId
      void entryGen
      status = (snap?.commitInFlight === true || inFlight)
        ? `Bitmap save in flight (${op} blocked; retry after it settles)`
        : `Bitmap edit pending (${op} blocked; press Escape to commit or Delete to discard, then retry; pending retained)`
      return true
    } catch {
      status = `Bitmap pending gate failed (${op}); op blocked, original preserved`
      return true
    }
  }

  /** Leave-pending restyle: in-place parametric restyle, never history. */
  function applyBitmapPendingRestyle(): boolean {
    try {
      const controller = ensureBitmapPendingController()
      const session = controller?.get()
      if (!session) return false
      if (!session.snapshot().hasPending) return false
      if (bitmapPendingRestyleGuard) return true
      bitmapPendingRestyleGuard = true
      try {
        const result = session.restyle(
          {
            fill: bitmapPendingStyleNow().fill,
            secondary: bitmapPendingStyleNow().secondary,
            gradient: bitmapPendingStyleNow().gradient,
            fillTransparent: bitmapPendingStyleNow().fillTransparent,
            secondaryTransparent: bitmapPendingStyleNow().secondaryTransparent,
            brushSize: bitmapPendingStyleNow().brushSize,
          },
          normalizeBitmapShapeMode(bitmapShapeMode),
        )
        if (result.ok && (result.kind === 'updated' || result.kind === 'unchanged')) {
          // The session repaints `base + shape` and pushes the selection via
          // onSelection; keep the explicit saved marker so the preexisting
          // retention test observes continuity without a new history entry.
          if (status !== 'Bitmap edit saved' && !status.includes('history-gap') && !status.includes('quarantin')) {
            status = 'Bitmap edit saved'
          }
          return true
        }
        return false
      } finally {
        bitmapPendingRestyleGuard = false
      }
    } catch {
      return false
    }
  }

  async function exportBitmapPendingQuarantined(): Promise<Uint8Array | undefined> {
    try {
      const controller = ensureBitmapPendingController()
      // Active-session quarantine first (same-slot conflict): byte-exact
      // `base + shape` composite, zero VM writes.
      try {
        const session = controller?.get()
        if (session) {
          const bytes = (await session.exportQuarantinedPng()) ?? (await session.exportPreservedPng()) ?? (await session.exportConflictedPng())
          if (bytes && bytes.byteLength > 0) return new Uint8Array(bytes)
        }
      } catch {
        // Fall through to the retained-recovery path below.
      }
      // Retained off-canvas recovery (direct-VM switch/clear): the SAME
      // byte-exact export via the controller (never paints, never commits).
      try {
        const bytes = await controller?.exportRecoveryPng()
        if (bytes && bytes.byteLength > 0) return new Uint8Array(bytes)
      } catch {
        // Best effort only.
      }
      return undefined
    } catch {
      return undefined
    }
  }

  function discardBitmapPendingQuarantine(): boolean {
    try {
      const controller = ensureBitmapPendingController()
      // Active quarantine first.
      try {
        const session = controller?.get()
        if (session) {
          try {
            const snap = session.snapshot()
            if (Boolean(snap.quarantined ?? snap.quarantine)) {
              const result = session.discardQuarantined()
              try {
                controller?.refresh()
              } catch {
                // Best effort only.
              }
              status = 'Quarantined bitmap shape discarded by explicit user action'
              void result
              return true
            }
          } catch {
            // Fall through to recovery discard below.
          }
        }
      } catch {
        // Fall through to recovery discard below.
      }
      // Retained recovery requires explicit user confirmation; never silent.
      try {
        if (controller?.hasRecovery()) {
          const result = controller.discardRecovery({ confirmed: true })
          if (result.ok) {
            bitmapPendingQuarantined = false
            bitmapPendingRecoveryHas = false
            bitmapPendingRecoveryQuarantined = false
            bitmapPendingRecoveryGap = false
            try {
              controller.refresh()
            } catch {
              // Best effort only.
            }
            status = 'Quarantined bitmap shape discarded by explicit user action'
            return true
          }
          return false
        }
      } catch {
        return false
      }
      return false
    } catch {
      return false
    }
  }

  /**
   * Scoped same-slot external-wins reload (bitmap pending conflict path).
   *
   * A pending commit that settles `external-conflict` / `superseded` (or an
   * ownership-loss refusal) leaves the live canvas showing the stale staged
   * overlay: the in-flight refresh (if any) still carried the pre-commit
   * own-write skip, and the session correctly quarantines the staged red+blue
   * off-canvas without touching pixels (the reloader owns them). This reloads
   * the RIGHTFUL live owner's latest asset bytes (exact green, no old red, no
   * overwrite of the external write) so the canvas matches the store; the
   * quarantined composite stays immutable off-canvas for exact export until an
   * explicit discard. The quarantine/conflict status is intentionally left
   * untouched (still visible until explicit action).
   *
   * Scoping (never an unconditional clear/splat on a fresh canvas):
   * - live truth comes from the VM (`vectorWriteTargetById` over the
   *   quarantined stable slot), never the possibly-lagging Svelte snapshot;
   * - the `shouldReloadBitmapCanvasAfterPendingConflict` decision compares
   *   slot/bytes/generation and skips when the canvas already shows the live
   *   key, a load for it is already pending, or the live slot is unknown;
   * - the own-write skip is consumed first (it was armed for our failed
   *   commit; the live bytes are external and must load);
   * - the draw itself goes through `refreshCostumePreview`, whose
   *   revision/serial guards scope the async decode and let a newer load win,
   *   so a concurrent new-target switch is never cleared by this reload.
   */
  async function reloadBitmapCanvasAfterPendingConflict(reason: string): Promise<void> {
    try {
      if (!BITMAP_PENDING_UI_ENABLED) return
      if (!bitmapCanvas) return
      const session = bitmapPendingController?.get()
      if (!session) return
      let scope: { targetId: string; costumeIndex: number; assetKey: string; writeSeq?: number | null; projectGeneration?: number | null } | undefined
      try {
        const view = session.getQuarantined() ?? session.getPreservedPending() ?? session.getConflicted()
        if (view) scope = view.scope
      } catch {
        return
      }
      if (!scope || typeof scope.targetId !== 'string' || scope.targetId.length === 0) return
      // Live truth, not the Svelte snapshot: the external write landed while
      // the commit was in flight and reactive state may lag the settle by a
      // tick. Stable-id only, never a display-name alias.
      const liveTarget = vectorWriteTargetById(scope.targetId, '')
      if (!liveTarget) return
      const liveId = stableTargetId(liveTarget)
      if (!liveId) return
      const liveIndex = liveTarget.currentCostume ?? 0
      const liveAssetKey = bitmapAssetKeyOf(liveTarget, liveIndex)
      let liveWriteSeq: number | null = null
      try {
        const identity = (vm as unknown as { getCostumeIdentity?: (t: string, i: number) => { writeSeq?: unknown } }).getCostumeIdentity?.(scope.targetId, liveIndex)
        if (identity && typeof identity.writeSeq === 'number' && Number.isInteger(identity.writeSeq)) liveWriteSeq = identity.writeSeq
      } catch {
        liveWriteSeq = null
      }
      const pending = bitmapWorkspacePending
      const verdict = shouldReloadBitmapCanvasAfterPendingConflict(
        {
          targetId: scope.targetId,
          costumeIndex: scope.costumeIndex,
          assetKey: scope.assetKey,
          writeSeq: typeof scope.writeSeq === 'number' ? scope.writeSeq : null,
          projectGeneration: typeof scope.projectGeneration === 'number' ? scope.projectGeneration : null,
        },
        {
          targetId: liveId,
          costumeIndex: liveIndex,
          assetKey: liveAssetKey,
          writeSeq: liveWriteSeq,
          projectGeneration: readProjectGenerationSafe(),
        },
        {
          ownerTargetId: bitmapWorkspaceOwner?.targetId,
          ownerIndex: bitmapWorkspaceOwner?.index,
          ownerAssetKey: bitmapWorkspaceOwner?.assetKey,
          ownerSettled: bitmapWorkspaceOwner ? isBitmapWorkspaceSettledFor(liveId, liveIndex) : false,
          pendingAssetKey: pending?.assetKey,
          pendingIsLiveSlot: pending ? pending.targetId === liveId && pending.index === liveIndex : false,
        },
      )
      if (!verdict.reload) return
      // Consume the own-write skip: it was armed for our (failed) commit, so
      // the external bytes it would swallow must load now.
      try {
        clearBitmapReloadSkip()
      } catch {
        // Best effort only.
      }
      await refreshCostumePreview(liveTarget)
    } catch {
      // Best effort only: the quarantined recovery + conflict status stay
      // intact, so the stale canvas remains explicitly signaled.
    }
    void reason
  }

  /** Ownership-loss refusals that quarantine off-canvas and may leave the canvas stale. */
  function isPendingOwnershipLossReason(reason: unknown): boolean {
    return (
      reason === 'external-conflict' ||
      reason === 'superseded' ||
      reason === 'owner-mismatch' ||
      reason === 'aborted' ||
      reason === 'invalid-scope'
    )
  }

  /**
   * Post-settle repair for ownership-loss commit refusals: when the session
   * quarantined off-canvas (external won), reload the rightful live owner's
   * latest bytes (scoped, no-op when already live). Returns true when a
   * reload was issued. Keeps the three commit-first call sites (guard, save,
   * Escape) to one line each.
   */
  async function reloadBitmapCanvasIfPendingOwnershipLost(
    result: { ok: boolean; reason?: string } | undefined,
  ): Promise<boolean> {
    try {
      const reason = (result as { reason?: string } | undefined)?.reason
      if (result?.ok !== false || !isPendingOwnershipLossReason(reason)) return false
      await reloadBitmapCanvasAfterPendingConflict(String(reason))
      return true
    } catch {
      return false
    }
  }

  function acknowledgeBitmapPendingGap(note?: string): boolean {
    try {
      // Acknowledge via the controller so a gap retained in a recovery
      // session (commit landed cross-slot) is cleared as well; the live-only
      // session path would leave that gap sticky forever.
      const controller = ensureBitmapPendingController()
      if (!controller) return false
      const acked = controller.acknowledgeGap(note)
      if (acked) {
        bitmapPendingGap = false
        bitmapPendingRecoveryGap = false
      }
      return acked
    } catch {
      return false
    }
  }

  function isBitmapEditRefused(): boolean {
    return bitmapArtboard.refused === true
  }

  const BITMAP_REFUSAL_STATUS = 'Image too large to edit safely — original kept unchanged'

  function refuseBitmapOversize(): void {
    status = BITMAP_REFUSAL_STATUS
  }

  /**
   * Real decode + raster + (bounded) encode verification for a freshly drawn
   * bitmap workspace (extreme side-cap guard). The PNG/IHDR layer always
   * carries extreme sides (spec max 2^31-1) and `drawImage` never throws for
   * them, but the Chrome 2D raster silently stays blank past its side limit
   * (observed 65535 -> rasterizes, 65536 -> blank + toBlob null) while the
   * area budget still passes. Saving/converting that blank canvas would
   * silently overwrite the stored asset (blank crop / empty SVG), so a failed
   * probe must refuse with the stored bytes/metadata untouched.
   *
   * Full-coverage evidence (tile-bounded, no unbounded allocation):
   * - canvas readback dims must equal the placed dims;
   * - every pixel of the placed rect is compared chunk-by-chunk: an
   *   independent source readback (sub-rect `drawImage` of the decoded image
   *   onto a tiny tile canvas) vs the live canvas readback of the same
   *   window. Alpha must match exactly (a single dropped opaque pixel
   *   refuses); RGB is ignored when both alphas are 0 (transparent-black
   *   normalisation) and otherwise compared in premultiplied space with a
   *   ±2 tolerance for premultiply/unpremultiply rounding and gamut wobble.
   *   Fractional placements use a full-size reference draw at the same
   *   fractional origin (small artboards only) so filtering matches exactly;
   *   margins outside the placed rect must stay transparent (preview/HMR
   *   pollution refuses);
   * - for small workspaces the full-canvas toBlob probe must encode
   *   (null/throw = the environment cannot write it).
   * Returns true when the workspace is usable, false when it must be refused.
   */
  async function verifyBitmapLiveRaster(
    image: HTMLImageElement,
    decodedWidth: number,
    decodedHeight: number,
    originX: number,
    originY: number,
    canvasWidth: number,
    canvasHeight: number,
  ): Promise<boolean> {
    try {
      if (!bitmapCanvas) return false
      if (isBitmapSourceSizeRefused(decodedWidth, decodedHeight)) return false
      if (isBitmapSourceSizeRefused(canvasWidth, canvasHeight)) return false
      if (bitmapCanvas.width !== canvasWidth || bitmapCanvas.height !== canvasHeight) return false
      const live = bitmapCanvas.getContext('2d')
      if (!live) return false
      // Full-coverage pixel proof lives in the split helper (tile-bounded
      // independent source readback vs live readback + transparent margins);
      // the editor only wires gates, the encode probe, and the verdict.
      // Stale serial/revision gating stays with the caller below.
      const proof = await verifyBitmapPlacedPixels(image, decodedWidth, decodedHeight, originX, originY, canvasWidth, canvasHeight, live)
      if (!proof.ok) return false
      let encodeOk: boolean | undefined
      const area = canvasWidth * canvasHeight
      if (area <= 1_000_000) {
        try {
          const encoded = await new Promise<Blob | null>((resolve) => {
            try {
              bitmapCanvas?.toBlob(resolve, 'image/png')
            } catch {
              resolve(null)
            }
          })
          encodeOk = encoded !== null && encoded.size > 0
        } catch {
          encodeOk = false
        }
      }
      return !isBitmapRasterRefused({
        width: canvasWidth,
        height: canvasHeight,
        readbackWidth: bitmapCanvas.width,
        readbackHeight: bitmapCanvas.height,
        readable: true,
        sourceHasOpaque: proof.sourceHasOpaque,
        liveHasOpaque: proof.sourceHasOpaque,
        ...(encodeOk === undefined ? {} : { encodeOk }),
      })
    } catch {
      return false
    }
  }

  function bitmapAssetKeyOf(target: ScratchTarget | undefined, index: number): string {
    const costume = target?.costumes[index]
    return costume?.md5ext ?? costume?.assetId ?? ''
  }

  function currentBitmapIdentity(): { targetId: string; index: number; assetKey: string } | undefined {
    if (!selectedTarget) return undefined
    const index = selectedTarget.currentCostume ?? 0
    return { targetId: stableTargetId(selectedTarget), index, assetKey: bitmapAssetKeyOf(selectedTarget, index) }
  }

  // Settled = the live canvas pixels were drawn for exactly this asset by the
  // latest load, with no newer load pending and no refused workspace. Every
  // bitmap mutation/save/convert/nudge/paste checks this before touching the
  // canvas or the VM; mismatches refuse with an honest status and leave the
  // stored asset, clipboard source, center, and resolution untouched.
  function isBitmapWorkspaceSettledFor(targetId: string, index: number): boolean {
    if (!bitmapWorkspaceOwner) return false
    if (bitmapWorkspacePending) return false
    if (bitmapWorkspaceOwner.targetId !== targetId || bitmapWorkspaceOwner.index !== index) return false
    if (bitmapWorkspaceOwner.loadSerial !== bitmapCanvasReloadSerial) return false
    if (bitmapWorkspaceOwner.revision !== assetPreviewRevision) return false
    if (isBitmapEditRefused()) return false
    return true
  }

  function isBitmapWorkspaceBusy(): boolean {
    return Boolean(bitmapWorkspacePending)
  }

  function bitmapWorkspaceToken(): string {
    const o = bitmapWorkspaceOwner
    const p = bitmapWorkspacePending
    return `owner=${o ? `${o.targetId}:${o.index}:${o.assetKey}:${o.loadSerial}:${o.generation}` : 'none'} pending=${p ? `${p.targetId}:${p.index}:${p.assetKey}:${p.loadSerial}` : 'none'} serial=${bitmapCanvasReloadSerial} rev=${assetPreviewRevision}`
  }

  function refuseStaleBitmapWorkspace(action: string): void {
    status = `${action}: cancelled (artwork changed — original kept unchanged)`
  }

  // Settle-time repair for the pending-derived `Loading bitmap…` status.
  // Paste entry points set that exact string while `bitmapWorkspacePending`
  // is set; the successful load below must advance it to the settled
  // completion display, but only when the committed owner still identifies
  // the live target/costume slot with matching load serial, preview
  // revision and workspace generation. Any other status (a later user
  // operation, a different target/costume error, the oversize/verify
  // refusal) is left untouched, and a target/costume switch or a late
  // stale load never injects a completion status.
  function maybeResolveBitmapLoadingStatus(): void {
    try {
      if (!selectedTarget) return
      const liveTargetId = stableTargetId(selectedTarget)
      const liveIndex = selectedTarget.currentCostume ?? 0
      const canResolve = shouldResolveBitmapLoadingStatus({
        status,
        owner: bitmapWorkspaceOwner,
        pending: bitmapWorkspacePending,
        serial: bitmapCanvasReloadSerial,
        revision: assetPreviewRevision,
        generation: bitmapWorkspaceGeneration,
        liveTargetId,
        liveIndex,
        refused: bitmapArtboard.refused === true,
      })
      if (!canResolve) return
      status = BITMAP_LOAD_SETTLED_STATUS
    } catch {
      // Status repair never blocks the bitmap load itself.
    }
  }
  let isBitmapPainting = false
  let bitmapStart: { x: number; y: number } | undefined
  let bitmapPreviewBase: ImageData | undefined
  let bitmapShapePreviewDrawn = false
  let bitmapPaperPoints: { x: number; y: number }[] = []
  // Pending rect/oval draft flag: true while a session pointerDown draft is
  // active (routed through `bitmap-pending-session`, not the legacy preview
  // base). `isBitmapPainting` stays true for the BitmapEditor event flow.
  let bitmapPendingPainting = false
  // Incremental stroke budget (O(1) per move, O(total) per stroke): running
  // stamp estimate + cap flag. `bitmapStrokeStamps` mirrors the full-replay
  // total (`sum(max(dx,dy)+1)` with double-counted joints); `bitmapStrokeCapped`
  // latches on the first cap refusal so later moves skip work (no O(N^2)
  // replay) and the commit preserves earlier pixels with an honest status.
  let bitmapStrokeStamps = 0
  let bitmapStrokeCapped = false
  let bitmapPaperModule: typeof paperCore | undefined
  let bitmapPaperScope: paper.PaperScope | undefined
  let bitmapSelection: { x: number; y: number; width: number; height: number } | undefined
  // Floating raster drag (rectangular bitmap selection move / Alt-duplicate).
  // The live canvas stays untouched until the first effective preview; every
  // preview re-renders from the immutable `session.committed` snapshot via
  // source-over compositing (transparent patch pixels preserve the
  // destination, matching Canvas `drawImage`), and only a pointerup with
  // `moved === true` writes one history entry. Esc restores `committed`
  // through `clearCostumeSelection` without saving.
  // Center-snap parity (`move-snap-parity.ts`): `copy` is the PRESS-TIME Alt
  // flag (never refreshed live mid-drag), `shiftAtStart` is informational only
  // (Shift is evaluated live per move for 45-degree projection + snap
  // exclusion), and `guideOpacity` drives the 16px center crosshair
  // (0 = hidden, up to 0.75). Cleared synchronously on
  // pointerup/pointercancel/Escape/target-switch/Undo so a stale guide can
  // never linger on the new artwork.
  let bitmapMoveDrag:
    | {
      session: BitmapFloatingSession
      startPoint: { x: number; y: number }
      startSelection: { x: number; y: number; width: number; height: number }
      copy: boolean
      shiftAtStart: boolean
      pointerId: number
      targetName: string
      costumeIndex: number
      destX: number
      destY: number
      moved: boolean
      guideOpacity: number
    }
    | undefined
  // Floating scale drag for any of the 8 handles. Like the move drag,
  // previews render from the committed snapshot; each move re-scales from
  // the frozen `original` patch (never incrementally) with the diagonal
  // fixed point pinned (Alt pins the selection center instead, Shift frees
  // a corner handle from its default uniform scale, edges scale one axis).
  // Crossing the fixed point mirrors via a negative factor. Previews with
  // no visible change keep the last frame; Esc restores the committed
  // snapshot via `clearCostumeSelection` without history.
  let bitmapScaleDrag:
    | {
      session: BitmapFloatingSession
      original: BitmapFloatingImage
      handle: BitmapFloatingScaleHandle
      pointerId: number
      moved: boolean
    }
    | undefined
  // Arbitrary-angle rotation-handle drag for the bitmap selection. Like the
  // scale drag, every preview restarts from the frozen `original` patch and
  // the immutable `session.committed` snapshot (never incrementally), the
  // patch stays centered on the source rect, Shift snaps the absolute delta
  // to 45 degrees via `resolveRotationGesture`, and Esc restores `committed`
  // without history. Only a pointerup with `moved === true` writes one
  // history entry; clicks, center presses, and snapped-to-zero drags stay
  // undo-clean.
  let bitmapRotateDrag:
    | {
      session: BitmapFloatingSession
      original: BitmapFloatingImage
      center: { x: number; y: number }
      start: { x: number; y: number }
      pointerId: number
      moved: boolean
    }
    | undefined
  // Pending parametric transform drags (rect/oval staged shape, B-3 move/scale/rotate).
  // Unlike the floating raster drags above, these never touch live pixels
  // except through `session.moveBy` / `session.retarget` / `session.rotateTo` (frozen `base +
  // shape` single-pass repaint, no history, no VM, no `saveBitmapCostume`).
  // The drag measures from the frozen `startBox` every move (never
  // incrementally) so repeated moves cannot drift or double-compose; the
  // pointer delta is canvas px via `bitmapPoint` (viewport-scale aware) with
  // the same Shift/center-snap parity as the floating move and the same
  // Alt-center/Shift-uniform parity as the floating scale. `pointerup` keeps
  // the shape staged (no commit); Escape/pointercancel/lostcapture revert to
  // `startBox` via the session (restoring the prior pending overlay) and
  // clear only the drag. Out-of-order events (wrong pointerId, concurrent
  // drag, unsettled workspace, missing pending) are rejected without canvas
  // touch. After pointerup the staged shape stays selected for restyle/commit.
  let bitmapPendingMoveDrag:
    | {
      pointerId: number
      startPoint: { x: number; y: number }
      startBox: { x: number; y: number; width: number; height: number }
      startAffine: { a: number; b: number; c: number; d: number; e: number; f: number } | undefined
      appliedDx: number
      appliedDy: number
      targetName: string
      costumeIndex: number
      guideOpacity: number
    }
    | undefined
  let bitmapPendingScaleDrag:
    | {
      pointerId: number
      handle: BitmapFloatingScaleHandle
      startPoint: { x: number; y: number }
      startBox: { x: number; y: number; width: number; height: number }
      rotatedState: PendingRotatedScaleDragState | undefined
      affineState: PendingAffineScaleDragState | undefined
      startAffine: { a: number; b: number; c: number; d: number; e: number; f: number } | undefined
      useAffine: boolean
      targetName: string
      costumeIndex: number
    }
    | undefined
  // Pending parametric free-rotation drag (rect/oval staged shape, arbitrary
  // angle). Like move/scale above, the overlay repaints from the frozen
  // `base + shape` every move (no history, no VM, no `saveBitmapCostume`).
  // The drag measures ABSOLUTELY: each move recomputes
  // `startRotation + gestureDelta` from the frozen start pointer around the
  // frozen shape center via `resolveRotationGesture` (Shift snaps to 45
  // degrees, toggling mid-drag recomputes cleanly), then `session.rotateTo`
  // stages it — never incrementally, so repeats cannot drift or accumulate
  // resampling. `pointerup` keeps the shape staged (no commit); Escape /
  // pointercancel / lostpointercapture revert to `startRotation` via the
  // session (restoring the prior pending overlay) and clear only the drag.
  let bitmapPendingRotateDrag:
    | {
      pointerId: number
      startPoint: { x: number; y: number }
      center: { x: number; y: number }
      startRotation: number
      moved: boolean
      targetName: string
      costumeIndex: number
    }
    | undefined
  let bitmapClipboard: ImageData | undefined
  // Canvas-pixel origin of `bitmapClipboard` at copy time (same workspace
  // space as `getImageData`). Same-mode bitmap paste ignores it and re-anchors
  // at the live selection (existing behavior); the bitmap -> vector path maps
  // it to SVG units (`origin / sourceResolution + stagger`) so pasting after
  // moving the marquee still lands at the copied position instead of (0,0).
  let bitmapClipboardRect: { x: number; y: number; width: number; height: number } | undefined
  // Copy-time source snapshot bundled with the bitmap clipboard. The canvas
  // pixels were captured at `resolution` (live artboard resolution at copy
  // time = stored asset resolution: 2 for sprite bitmaps, 1 for stage); the
  // origin / canvas-center / rotation-center companions pin the copy-time
  // world frame and `copyPasteOffset` records the reset stagger base (1).
  // The bitmap -> vector paste MUST divide through this source resolution,
  // not the destination vector costume's `bitmapResolution` (which is always
  // 1 after `convertCurrentCostumeToVector`): otherwise a sprite-res2 copy
  // pasted after conversion doubles x/y/width/height. `undefined` means old
  // clipboard state predating the snapshot: the paste falls back to the
  // destination resolution (legacy behavior).
  let bitmapClipboardSource: BitmapClipboardSourceSnapshot | undefined
  let vectorClipboard: string[] = []
  // Sanitized snapshot of the copy-source `<defs>` (gradients / clipPaths).
  // Unit `outerHTML` never carries its companions, and same-document paste
  // resolves refs against the live document — but the vector -> bitmap raster
  // builds a standalone document, so it re-attaches exactly the referenced
  // companions from this snapshot (fail-closed: missing refs rasterize
  // transparent instead of fetching).
  let vectorClipboardDefs = ''
  // Single-clipboard recency (copy-paste-hoc.jsx parity): scratch-paint keeps
  // ONE clipboard shared by both formats, so copying in either mode replaces
  // what paste inserts. The two buffers above are an implementation detail;
  // this stamp records which one was written last, and paste prefers it across
  // modes instead of letting a stale same-mode entry shadow a fresh cross-mode
  // copy (e.g. copy bitmap, convert to vector, paste must embed the bitmap).
  let clipboardRecency: 'bitmap' | 'vector' | undefined
  let pasteOffset = 0
  let skipNextBitmapCanvasReloadKey = ''
  // Version scope for the own-write skip above. The slot-only key alone
  // cannot tell our just-committed bytes from a concurrent external write to
  // the same slot: both share `targetId:index`. The expected asset key/seq
  // below is armed only after a proven successful local write and the
  // consumer skips the reload only while the live slot still shows that
  // exact version. Any drift (external green, same-bytes rename bump,
  // target switch, project load) fails closed to a real reload. Legacy
  // key-only arming is prohibited: an unversioned token never skips (see
  // `bitmap-pending-reload-skip.ts`). The in-flight barrier below covers the
  // `await` window (pre-commit capture, never a skip): while it is armed for
  // the slot, reloads buffer until the flight settles and then reconcile
  // from live, so no external write is swallowed and no stale pre-flight
  // bytes are painted.
  let skipNextBitmapCanvasReloadAssetKey: string | undefined = undefined
  let skipNextBitmapCanvasReloadWriteSeq: number | null | undefined = undefined
  let skipNextBitmapCanvasReloadProjectGen: number | null | undefined = undefined
