      const live = (reader.getTargetById?.(targetId) ?? vectorWriteTargetById(targetId, fallbackTarget?.name ?? '')) ?? fallbackTarget
      if (!live || stableTargetId(live) !== targetId) return
      await refreshCostumePreview(live)
      try {
        const idx = live.currentCostume ?? 0
        const key = live.costumes[idx]?.md5ext ?? live.costumes[idx]?.assetId
        const dataFormat = live.costumes[idx]?.dataFormat ?? 'svg'
        const bytes = key ? await vm.loadAsset(key, dataFormat) : undefined
