  const refresh = (next = vm.snapshot(), source: 'main' | 'worker' = 'main', draw = true) => {
    // Direct-VM hostile hook: retain staged work BEFORE the Svelte snapshot
    // swap triggers any canvas reload/teardown. Detects stable
    // identity/projectGeneration drift via the live VM + incoming snapshot,
    // keeps the old base+shape off-canvas immutable, and routes to the visible
    // recovery UI. Intentionally preserves the external change: never
    // auto-reverts `selectTarget` (an explicit external selection — including
    // `addSprite` auto-select of a brand-new id — is caller intent), never
    // paints the retained old base onto the live canvas (the new owner's
    // canvas reloads from its own bytes; even a shape-free base repaint would
    // mutate the new owner's pixels). No-op selects/renames preserve
    // intentional state. Recovery stays quarantined off-canvas + UI until an
    // explicit export/discard.
    try {
      const prevSnap = snapshot as { selectedTargetId?: unknown; project?: { targets?: Array<{ id?: string; name?: string }> } }
      const nextSnap = next as { selectedTargetId?: unknown; project?: { targets?: Array<{ id?: string; name?: string; isStage?: boolean; currentCostume?: number; costumes?: Array<{ md5ext?: string; assetId?: string; dataFormat?: string }> }> } }
      const prevId = prevSnap?.selectedTargetId
      const nextId = nextSnap?.selectedTargetId
      // Frozen pre-event identity (reliable even when snapshot objects share
      // live store references with the VM): falls back to the live old
      // snapshot only when no frozen baseline exists yet.
      const hasFrozenBaseline = bitmapPendingHostileSeenIds.length > 0 || bitmapPendingHostileSeenSel !== ''
      const frozenIds = hasFrozenBaseline ? bitmapPendingHostileSeenIds : (prevSnap?.project?.targets ?? []).map((t) => (typeof t?.id === 'string' && t.id ? t.id : (t?.name ?? '') as string)).filter((s) => (s as string) !== '')
      const nextTargets = nextSnap?.project?.targets ?? []
      const nextIdStr = typeof nextId === 'string' ? nextId : ''
      const countChanged = nextTargets.length !== frozenIds.length
      if (BITMAP_PENDING_UI_ENABLED && bitmapPendingController && (prevId !== nextId || countChanged)) {
        retainBitmapPendingForHostileSnapshot(
          next as { selectedTargetId?: string; project?: { targets?: Array<{ id?: string; name?: string; isStage?: boolean; currentCostume?: number; costumes?: Array<{ md5ext?: string; assetId?: string }> }> } },
          countChanged ? 'external-structure-change' : 'external-select-change',
