        // No auto-revert, no old-base repaint: the external selection (new
        // or existing target) stands; staged art survives only as off-canvas
        // quarantined recovery + Export/Discard UI. Stale hidden-bitmap
        // cleanup for non-bitmap new owners: the bitmap canvas is hidden for
        // vector/blank and its normal reload path intentionally skips
        // (`dataFormat !== 'svg'` guard), so without cleanup it would keep
        // showing staged red. Clear to transparent blank — never paint the
        // retained old base, never VM/history writes. Bitmap new owners
        // reload from their own bytes via the normal path.
        try {
          const liveSel =
            nextTargets.find((t) => (t?.id ?? t?.name) === nextIdStr) ??
            nextTargets.find((t) => !t?.isStage) ??
            nextTargets[0]
          const liveIdx = typeof liveSel?.currentCostume === 'number' ? liveSel.currentCostume : 0
          const fmt = liveSel?.costumes?.[liveIdx]?.dataFormat
          if (fmt !== undefined && fmt !== 'png') {
            try {
              const canvas = bitmapCanvas
              if (canvas && canvas.width > 0 && canvas.height > 0) {
                canvas.getContext('2d')?.clearRect(0, 0, canvas.width, canvas.height)
              }
            } catch {
              // Best effort only.
            }
          }
