        // (direct `vm.clear` reusing ids, `loadProject` same-shape): still
        // retain before the reload. Cheap: only when unsaved work exists.
        // Same non-bitmap hidden-canvas clear as above (never old base):
        // the fresh canvas belongs to the new project and reloads from its
        // own bytes (bitmap) or stays blank (vector/blank).
        try {
          if (bitmapPendingController.hasUnsavedState()) {
            retainBitmapPendingForHostileSnapshot(
              next as { selectedTargetId?: string; project?: { targets?: Array<{ id?: string; name?: string; isStage?: boolean; currentCostume?: number; costumes?: Array<{ md5ext?: string; assetId?: string }> }> } },
              'external-snapshot-change',
            )
            try {
              const liveSel =
                (nextTargets as Array<{ id?: string; name?: string; isStage?: boolean; currentCostume?: number; costumes?: Array<{ dataFormat?: string }> }>).find(
                  (t) => (t?.id ?? t?.name) === nextIdStr,
                ) ??
                nextTargets.find((t) => !(t as { isStage?: boolean })?.isStage) ??
                nextTargets[0]
              const liveIdx =
                typeof (liveSel as { currentCostume?: unknown })?.currentCostume === 'number'
                  ? (liveSel as { currentCostume: number }).currentCostume
                  : 0
              const fmt = (liveSel as { costumes?: Array<{ dataFormat?: string }> } | undefined)?.costumes?.[liveIdx]?.dataFormat
              if (fmt !== undefined && fmt !== 'png') {
                try {
                  const canvas = bitmapCanvas
                  if (canvas && canvas.width > 0 && canvas.height > 0) {
                    canvas.getContext('2d')?.clearRect(0, 0, canvas.width, canvas.height)
                  }
                } catch {
                  // Best effort only.
                }
              }
            } catch {
              // Best effort only.
