    // exposes per-target queue epoch / active barrier / in-flight tails so
    // browser tests can separate a sync-premise failure (structure never
    // entered) from a barrier deadlock (barrier held, tails never settle)
    // from an async-UI wait issue (barrier released, VM shifted, UI lags).
    try {
      const w = window as unknown as {
        __vectorGateDebug?: {
          epoch: (targetId: string) => number
          state: (targetId: string) => {
            epoch: number
            hasActiveBarrier: boolean
            inFlightTails: number
            hasQueuedStructure: boolean
          }
          slotBusy: (targetId: string, index: number) => boolean
          slotPending: (targetId: string, index: number) => boolean
          lastQuiescence: () => Array<{ targetId: string; index: number; ok: boolean; reason?: 'timeout' | 'barrier'; at: number }>
        }
      }
