      // already part of the editor chunk via the static imports above.
      w.__vectorGateDebug = {
        epoch: (targetId: string) => getTargetVectorEpoch(targetId),
        state: (targetId: string) => debugTargetVectorWriteState(targetId),
        slotBusy: (targetId: string, index: number) => isVectorSlotBarrierBusy(targetId, index),
        slotPending: (targetId: string, index: number) => isVectorSlotWritePending(vectorWriteSlotKey(targetId, index)),
        lastQuiescence: () => [...vectorQuiescenceLog],
      }
    } catch {
      // Test hook only; never blocks the editor.
    }
  }

  function updateStageQuestion(payload: { question?: string | null; questionId?: string | null; answer?: string }) {
    if ('question' in payload) {
      stageQuestionId = payload.questionId ?? `event-${++questionSerial}`
      stageQuestion = payload.question ?? null
    } else if ('answer' in payload) stageQuestion = null
  }

  const unsubscribers = [
    vm.on<{ question?: string | null; questionId?: string | null; answer?: string }>('QUESTION', updateStageQuestion),
    vm.on<{ message?: string }>('ERROR', (payload) => {
      status = payload?.message || 'Runtime error'
    }),
    vm.on<RuntimeSnapshot>('PROJECT_LOADED', (next) => {
      stageQuestion = null
      status = 'Project loaded'
      workspaceTargetId = ''
      deferredBlocklyTargetId = ''
      forcedBlocklyTargetIds = new Set()
      // A freshly loaded project replaces every asset object: drop both
      // histories even when the new selection key happens to collide, and
      // invalidate in-flight peeks so they cannot resurrect stale bytes.
      clearPaintHistory()
      clearSoundHistory()
      refresh(next)
    }),
    vm.on<RuntimeSnapshot>('PROJECT_CHANGED', (next) => {
      status = 'Project changed'
      refresh(next)
    }),
    vm.on<RuntimeSnapshot>('TARGETS_UPDATE', (next) => {
      if (next.running && !runtimeInWorker) refreshRuntimeFrame(next)
      else refresh(next, runtimeInWorker ? 'worker' : 'main')
    }),
    vm.on<RuntimeSnapshot>('WORKSPACE_UPDATE', (next) => refresh(next, runtimeInWorker ? 'worker' : 'main')),
    vm.on<RuntimeSnapshot>('BLOCKS_NEED_UPDATE', (next) => refresh(next, runtimeInWorker ? 'worker' : 'main')),
    vm.on<RuntimeSnapshot>('RUNTIME_STEP', (next) => {
      if (runtimeInWorker) refresh(next, 'main', false)
      else refreshRuntimeFrame(next)
      if (next.running) countRuntimeFrame()
    }),
    vm.on<RuntimeSnapshot>('PROJECT_RUN_START', (next) => {
      status = 'Running'
      resetFps()
      refresh(next)
    }),
    vm.on<RuntimeSnapshot>('PROJECT_RUN_STOP', (next) => {
      status = 'Stopped'
      resetFps()
      refresh(next)
    }),
    vm.on<{ id: string; value: string }>('VISUAL_REPORT', (payload) => {
      showVisualReport(payload.id, payload.value)
    }),
