    const pending = bitmapWorkspacePending
    const serial = bitmapCanvasReloadSerial
    const revision = assetPreviewRevision
    const refused = bitmapArtboard.refused === true
    void owner
    void pending
    void serial
    void revision
    void refused
    if (costumeEditMode !== 'bitmap') return false
    if (!selectedTarget) return false
    try {
