    }
  }
  $: costumeListSignature = selectedTarget ? `${selectedTarget.id ?? selectedTarget.name}:${selectedTarget.costumes.map((costume) => `${costume.name}:${costume.md5ext ?? costume.assetId ?? ''}`).join('|')}` : ''
