    window.removeEventListener('popstate', handleHistoryPop)
    window.removeEventListener('beforeunload', handleBitmapPendingBeforeUnload)
    window.removeEventListener('pagehide', handleBitmapPendingPageHide)
    window.removeEventListener('pageshow', handleBitmapPendingPageShow)
    if (hsvLiveCommitTimer) clearTimeout(hsvLiveCommitTimer)
    hsvLiveCommitTimer = undefined
  })

