  async function loadProject(event: Event) {
    const input = event.currentTarget as HTMLInputElement
    const file = input.files?.[0]
    if (!file) return
    try {
      const pendingSession = ensureBitmapPendingController()?.get()
      if (pendingSession) {
        let snap: { hasPending: boolean; commitInFlight: boolean } | undefined
        try {
          snap = pendingSession.snapshot()
        } catch {
          input.value = ''
          return
        }
        if (snap && (snap.hasPending || snap.commitInFlight)) {
          const ok = await guardBitmapPendingCommitFirst('load-project')
          if (!ok) {
            input.value = ''
            return
          }
        }
      }
    } catch {
      input.value = ''
      return
    }
    try {
      resetProjectUiState()
      // Project replacement: drain every in-flight vector write so a delayed
      // preview cannot land on the new project's assets after the swap.
      await drainAllVectorWrites()
      if (/\.(sb2|sb3)$/i.test(file.name)) {
        await vm.loadProject(new Uint8Array(await file.arrayBuffer()))
        projectTitle = file.name.replace(/\.(json|sb2|sb3)$/i, '')
        projectViewportGeneration = nextProjectViewportGeneration(projectViewportGeneration)
        return
      }
      await vm.importJSON(await file.text())
      projectTitle = file.name.replace(/\.(json|sb2|sb3)$/i, '')
      projectViewportGeneration = nextProjectViewportGeneration(projectViewportGeneration)
    } catch (error) {
      status = error instanceof Error ? error.message : 'Could not load project'
    } finally {
      input.value = ''
    }
  }

  async function importSpriteFile(event: Event) {
    const input = event.currentTarget as HTMLInputElement
    // Fail-closed while pending/inflight: importing would shift targets and
    // orphan the staged slot with no commit.
    try {
      if (isBitmapPendingStructuralBlocked('import-sprite')) {
        input.value = ''
        return
      }
    } catch {
      input.value = ''
      return
    }
    const files = [...(input.files ?? [])]
    if (files.length === 0) return
    try {
      let imported = 0
      for (const file of files) {
        const bytes = new Uint8Array(await file.arrayBuffer())
        if (isImageFile(file)) {
          await addImageSprite(file, bytes)
          imported += 1
        } else {
          const sprite = /\.(sprite2|sprite3|sb2|sb3)$/i.test(file.name) ? vm.importSprite(bytes) : vm.importSprite(new TextDecoder().decode(bytes))
          if (sprite) imported += 1
        }
      }
      status = imported > 0 ? `${imported} sprite${imported === 1 ? '' : 's'} imported` : 'Sprite import skipped'
    } catch (error) {
      status = error instanceof Error ? error.message : 'Could not import sprite'
    } finally {
      input.value = ''
    }
  }

  async function exportProject() {
    try {
      const pendingSession = ensureBitmapPendingController()?.get()
      if (pendingSession) {
        let snap: { hasPending: boolean; commitInFlight: boolean } | undefined
        try {
          snap = pendingSession.snapshot()
        } catch {
          return
        }
        if (snap && (snap.hasPending || snap.commitInFlight)) {
          const ok = await guardBitmapPendingCommitFirst('export-project')
          if (!ok) return
        }
      }
    } catch {
      return
    }
    const blob = new Blob([vm.toJSON()], { type: 'application/json' })
