  async function addLibrarySprite(item: (typeof spriteLibrary)[number] = spriteLibrary[0]) {
    try {
      if (isBitmapPendingStructuralBlocked('add-sprite')) return
    } catch {
      return
    }
    const sprite = vm.addSprite(item.name)
    try {
      for (const [index, costume] of item.costumes.entries()) {
        const response = await fetch(assetUrl(`assets-scratch/images/${costume.md5ext}`))
        if (!response.ok) throw new Error(`Could not load ${costume.name}`)
        const bytes = new Uint8Array(await response.arrayBuffer())
        const target = vm.getTarget(sprite.name)
        const svgText = costume.dataFormat === 'svg' ? new TextDecoder().decode(bytes) : ''
        const normalizedSvg = svgText && target
          ? svgTextForVectorEditor(svgText, target, {
              name: costume.name,
              dataFormat: 'svg',
              rotationCenterX: costume.rotationCenterX ?? 48,
              rotationCenterY: costume.rotationCenterY ?? 48,
            })
          : undefined
        const assetBytes = normalizedSvg ? new TextEncoder().encode(normalizedSvg) : bytes
        const asset = await vm.storeAsset(assetBytes, costume.dataFormat)
        // Respect the Scratch library JSON item metadata (resolution/center)
        // verbatim; fallbacks apply only when the item omits it.
        const libraryMeta = libraryCostumeIntakeMeta(costume, false)
        const meta = {
          name: costume.name,
          dataFormat: costume.dataFormat,
          assetId: asset.assetId,
          md5ext: asset.md5ext,
          bitmapResolution: libraryMeta.bitmapResolution,
          rotationCenterX: libraryMeta.rotationCenterX,
          rotationCenterY: libraryMeta.rotationCenterY,
        }
        if (index === 0) await vm.updateCostume(sprite.name, 0, meta)
        else vm.addCostume(sprite.name, meta)
      }
      for (const sound of item.sounds) {
        const response = await fetch(assetUrl(`assets-scratch/sounds/${sound.md5ext}`))
        if (!response.ok) throw new Error(`Could not load ${sound.name}`)
        const bytes = new Uint8Array(await response.arrayBuffer())
        const asset = await vm.storeAsset(bytes, sound.dataFormat)
        vm.addSound(sprite.name, {
          name: sound.name,
          dataFormat: sound.dataFormat,
          assetId: asset.assetId,
          md5ext: asset.md5ext,
          rate: sound.rate,
          sampleCount: sound.sampleCount,
        })
      }
      status = `${sprite.name} added from library`
    } catch (error) {
      status = error instanceof Error ? error.message : 'Could not add sprite'
    }
  }

  async function addImageSprite(file: File, bytes: Uint8Array) {
    try {
      if (isBitmapPendingStructuralBlocked('import-sprite')) return
    } catch {
      return
    }
    const mime = file.type || mimeFromFilename(file.name)
    const list = await new Promise<any[]>((resolve, reject) => {
      // Promisify the callback-style upload so bitmap dimension decoding
      // failures reject before any sprite/target mutation (non-destructive).
      vmCostumeUpload(
        bytes,
        mime,
        uploadStorage,
        (next) => resolve(next as unknown as any[]),
        (error) => reject(error instanceof Error ? error : new Error(String(error ?? 'Could not import sprite'))),
      )
    })
    const baseName = file.name.replace(/\.[^.]+$/, '') || 'Sprite'
    // Decode once from the uploaded file bytes (honke loadBitmap_: res2,
    // center = image middle). SVG keeps the existing 48,50 forced center.
    let bitmapMeta: { bitmapResolution: number; rotationCenterX: number; rotationCenterY: number } | undefined
    const needsBitmapMeta = list.some((entry) => entry.dataFormat !== 'svg')
    if (needsBitmapMeta) {
      try {
        bitmapMeta = await bitmapUploadIntakeMeta(bytes)
      } catch (error) {
        throw error instanceof Error ? error : new Error('Could not decode image dimensions')
      }
    }
    const sprite = vm.addSprite(baseName)
    for (const [index, costume] of list.entries()) {
      const stored = await vm.storeAsset(assetBytes(costume.asset.data), costume.dataFormat)
      const isSvg = costume.dataFormat === 'svg'
      const meta = isSvg
        ? { bitmapResolution: 1, rotationCenterX: 48, rotationCenterY: 50 }
        : {
            bitmapResolution: bitmapMeta?.bitmapResolution ?? 2,
            rotationCenterX: bitmapMeta?.rotationCenterX ?? 48,
            rotationCenterY: bitmapMeta?.rotationCenterY ?? 50,
          }
      if (index === 0) {
        await vm.updateCostume(sprite.name, 0, {
          name: baseName,
          dataFormat: costume.dataFormat,
          assetId: stored.assetId,
          md5ext: stored.md5ext,
          ...meta,
        })
      } else {
        vm.addCostume(sprite.name, {
          name: `${baseName}${index + 1}`,
          dataFormat: costume.dataFormat,
          assetId: stored.assetId,
          md5ext: stored.md5ext,
          ...meta,
        })
      }
    }
  }

