  async function addLibraryBackdrop(item: (typeof costumeLibrary)[number] = costumeLibrary[0]) {
    try {
      if (isBitmapPendingStructuralBlocked('add-costume')) return
    } catch {
      return
    }
    const target = vm.getStage()
    if (!target) return
    try {
      const response = await fetch(assetUrl(`assets-scratch/images/${item.md5ext}`))
      if (!response.ok) throw new Error(`Could not load ${item.name}`)
      const bytes = new Uint8Array(await response.arrayBuffer())
      const asset = await vm.storeAsset(bytes, item.dataFormat)
      // Respect the Scratch library JSON item metadata (resolution/center):
      // canonical 960x720 PNG backdrops are res2 center 480,360 and must
      // render as an exact full-stage cover (forcing res1/240,180 shows only
      // the top-left quarter). SVG stays at resolution 1.
      const libraryMeta = libraryCostumeIntakeMeta(item, true)
      await drainTargetVectorWrites(stableTargetId(target))
      vm.addCostume(target.name, {
        name: item.name,
        dataFormat: item.dataFormat,
        assetId: asset.assetId,
        md5ext: asset.md5ext,
        bitmapResolution: libraryMeta.bitmapResolution,
        rotationCenterX: libraryMeta.rotationCenterX,
        rotationCenterY: libraryMeta.rotationCenterY,
      })
      vm.selectTarget(target.name)
      selectEditorTab('costumes')
      status = `${item.name} backdrop added`
    } catch (error) {
      status = error instanceof Error ? error.message : 'Could not add backdrop'
    }
  }

