    if (!selectedTarget) return
    const current = selectedTarget.lists[id]
    const name = window.prompt('List name', current?.[0] ?? '')
    if (!name) return
    vm.renameList(selectedTarget.id ?? selectedTarget.name, id, name)
    status = 'List renamed'
  }

  function deleteList(id: string) {
    if (!selectedTarget) return
    vm.deleteList(selectedTarget.id ?? selectedTarget.name, id)
    status = 'List deleted'
  }

  function hideMonitor(id: string) {
    vm.setMonitorVisible(id, false)
    status = 'Monitor hidden'
  }

  function toggleTurboMode() {
    if (runtimeInWorker) runtimeWorker.setTurboMode(!snapshot.turboMode)
    else vm.setTurboMode(!snapshot.turboMode)
    status = snapshot.turboMode ? 'Turbo off' : 'Turbo on'
  }

  function startProject() {
    stageQuestion = null
    const context = ensureRuntimeAudioContext()
    void context.resume()
    if (runtimeInWorker) runtimeWorker.greenFlag()
    else vm.greenFlag()
  }

  function stopProject() {
    stageQuestion = null
    stopRuntimeSounds()
    if (runtimeInWorker) runtimeWorker.stopAll()
    else vm.stopAll()
    resetFps()
  }

  function stepProjectRuntime() {
    const context = ensureRuntimeAudioContext()
    void context.resume()
    if (runtimeInWorker) runtimeWorker.step()
    else {
      try {
        vm.step()
      } catch (error) {
        status = error instanceof Error ? error.message : String(error)
      }
    }
  }

  function toggleStageFullscreen() {
    stageFullscreen = !stageFullscreen
    tick().then(() => {
      if (editorDestroyed) return
      if (workspace) Blockly.svgResize(workspace)
      renderer.requestDraw(snapshot)
    })
  }

  function clampStagePaneWidth(width: number) {
    if (typeof window === 'undefined') return Math.min(820, Math.max(360, width))
    const viewportMax = Math.max(360, window.innerWidth - 420)
    return Math.min(Math.min(820, viewportMax), Math.max(360, width))
  }

  function beginStagePaneResize(event: PointerEvent) {
    if (stageFullscreen) return
    event.preventDefault()
    stagePaneResize = {
      startClientX: event.clientX,
      startWidth: stagePaneWidth,
    }
    document.body.classList.add('is-resizing-stage-pane')
    window.addEventListener('pointermove', dragStagePaneResize)
    window.addEventListener('pointerup', endStagePaneResize, { once: true })
    window.addEventListener('pointercancel', endStagePaneResize, { once: true })
  }

  function dragStagePaneResize(event: PointerEvent) {
    if (!stagePaneResize) return
    stagePaneWidth = clampStagePaneWidth(stagePaneResize.startWidth - (event.clientX - stagePaneResize.startClientX))
    if (workspace) Blockly.svgResize(workspace)
    renderer.requestDraw(snapshot)
  }

  function endStagePaneResize() {
    stagePaneResize = undefined
    document.body.classList.remove('is-resizing-stage-pane')
    window.removeEventListener('pointermove', dragStagePaneResize)
    window.removeEventListener('pointerup', endStagePaneResize)
    window.removeEventListener('pointercancel', endStagePaneResize)
    tick().then(() => {
      if (editorDestroyed) return
      if (workspace) Blockly.svgResize(workspace)
      renderer.requestDraw(snapshot)
    })
  }

  function adjustStagePaneWidth(event: KeyboardEvent) {
    if (event.key !== 'ArrowLeft' && event.key !== 'ArrowRight') return
    event.preventDefault()
    stagePaneWidth = clampStagePaneWidth(stagePaneWidth + (event.key === 'ArrowLeft' ? 24 : -24))
    tick().then(() => {
      if (editorDestroyed) return
      if (workspace) Blockly.svgResize(workspace)
      renderer.requestDraw(snapshot)
    })
  }

  function cycleMonitorMode(id: string) {
    const monitor = project.monitors.find((item) => item.id === id)
    if (!monitor) return
    const modes = monitor.opcode === 'data_listcontents' ? ['list'] : ['default', 'large', 'slider']
    const next = modes[(modes.indexOf(monitor.mode) + 1) % modes.length] ?? 'default'
    setMonitorMode(id, next)
  }

  function setMonitorMode(id: string, mode: string) {
    vm.setMonitorMode(id, mode)
    status = `Monitor ${mode}`
  }

  function editMonitorSliderLimit(id: string, field: 'sliderMin' | 'sliderMax') {
    const monitor = project.monitors.find((item) => item.id === id)
    if (!monitor) return
    const current = field === 'sliderMin' ? monitor.sliderMin ?? 0 : monitor.sliderMax ?? 100
    const label = field === 'sliderMin' ? '最小値' : '最大値'
    const nextText = window.prompt(label, String(current))
    if (nextText === null) return
    const value = Number(nextText)
    if (!Number.isFinite(value)) return
    const min = field === 'sliderMin' ? value : Number(monitor.sliderMin ?? 0)
    const max = field === 'sliderMax' ? value : Number(monitor.sliderMax ?? 100)
    vm.setMonitorSliderRange(id, min, max, monitor.isDiscrete === true)
    status = `Monitor ${label} updated`
  }

  function updateMonitorSlider(id: string, field: 'sliderMin' | 'sliderMax', event: Event) {
    const monitor = project.monitors.find((item) => item.id === id)
    if (!monitor) return
    const value = Number((event.currentTarget as HTMLInputElement).value)
    const min = field === 'sliderMin' ? value : Number(monitor.sliderMin ?? 0)
    const max = field === 'sliderMax' ? value : Number(monitor.sliderMax ?? 100)
    vm.setMonitorSliderRange(id, min, max, monitor.isDiscrete === true)
  }

  async function addCostume() {
    try {
      if (isBitmapPendingStructuralBlocked('add-costume')) return
    } catch {
      return
    }
    if (!selectedTarget) return
    const target = selectedTarget
    const targetId = stableTargetId(target)
    // Append-only: no index shift, so the epoch is preserved. Drain in-flight
    // writes first so the new slot is appended after settled bytes.
    await drainTargetVectorWrites(targetId)
    const live = vectorWriteTargetById(targetId, target.name) ?? vm.getTarget(target.name) ?? target
    vm.addCostume(live.name, {
      name: `costume${live.costumes.length + 1}`,
      dataFormat: 'svg',
      rotationCenterX: live.isStage ? 240 : 48,
      rotationCenterY: live.isStage ? 180 : 50,
    })
    status = 'Costume added'
  }

  async function uploadCostume(event: Event) {
    const input = event.currentTarget as HTMLInputElement
    try {
      if (isBitmapPendingStructuralBlocked('import-costume')) {
        input.value = ''
        return
      }
    } catch {
      input.value = ''
      return
    }
    if (!selectedTarget) return
    const targetId = selectedTarget.id ?? selectedTarget.name
    const targetIsStage = selectedTarget.isStage
    const files = [...(input.files ?? [])]
    if (files.length === 0) return
    try {
      let uploaded = 0
      for (const file of files) {
        const bytes = new Uint8Array(await file.arrayBuffer())
        const mime = file.type || mimeFromFilename(file.name)
        const list = await new Promise<any[]>((resolve, reject) => {
          vmCostumeUpload(
            bytes,
            mime,
            uploadStorage,
            (next) => resolve(next as unknown as any[]),
            (error) => reject(error instanceof Error ? error : new Error(String(error ?? 'Could not upload costume'))),
          )
        })
        // Honke file-uploader/load-costume: bitmaps resolve at resolution 2
        // with the center at the actual image middle. Decode from the file
        // bytes; on failure report via status without mutating stored assets.
        let bitmapMeta: { bitmapResolution: number; rotationCenterX: number; rotationCenterY: number } | undefined
        if (list.some((entry) => entry.dataFormat !== 'svg')) {
          try {
            bitmapMeta = await bitmapUploadIntakeMeta(bytes)
          } catch (error) {
            throw error instanceof Error ? error : new Error('Could not decode image dimensions')
          }
        }
        for (const costume of list) {
          const stored = await vm.storeAsset(assetBytes(costume.asset.data), costume.dataFormat)
          const isSvg = costume.dataFormat === 'svg'
          // SVG keeps the existing forced centers (stage 240,180, sprite 48,48).
          const meta = isSvg
            ? {
                bitmapResolution: 1,
                rotationCenterX: targetIsStage ? 240 : 48,
                rotationCenterY: targetIsStage ? 180 : 48,
              }
            : {
                bitmapResolution: bitmapMeta?.bitmapResolution ?? 2,
                rotationCenterX: bitmapMeta?.rotationCenterX ?? (targetIsStage ? 240 : 48),
                rotationCenterY: bitmapMeta?.rotationCenterY ?? (targetIsStage ? 180 : 48),
              }
          // Costume import (append-only): drain in-flight writes so the new
          // slot lands after settled bytes. No epoch bump: existing indices
          // are unchanged, so active previews stay valid.
          await drainTargetVectorWrites(targetId)
          vm.addCostume(targetId, {
            name: list.length > 1 ? `${file.name.replace(/\.[^.]+$/, '')}${list.indexOf(costume) + 1}` : file.name.replace(/\.[^.]+$/, ''),
            dataFormat: costume.dataFormat,
            assetId: stored.assetId,
            md5ext: stored.md5ext,
            ...meta,
          })
          uploaded += 1
        }
      }
      status = `${uploaded} costume${uploaded === 1 ? '' : 's'} uploaded`
    } catch (error) {
      status = error instanceof Error ? error.message : 'Could not upload costume'
    } finally {
      input.value = ''
    }
  }

  async function selectCostume(index: number) {
    if (!selectedTarget) return
    // Pending rect/oval (B-3): commit-first BEFORE the slot changes; on
    // refusal the switch is blocked and the pending is retained.
    try {
      const pendingSession = ensureBitmapPendingController()?.get()
      if (pendingSession) {
        let snap: { hasPending: boolean; commitInFlight: boolean } | undefined
        try {
          snap = pendingSession.snapshot()
        } catch {
          return
        }
        if (snap && (snap.hasPending || snap.commitInFlight)) {
          // Transactional no-silent-loss (commit-vs-switch race): never
          // auto-commit across a costume switch. A switch-triggered commit
          // that lands just before the scope clear loses its history entry
          // to the switch without a gap signal (silent undo loss); a commit
          // racing the switch gaps the append instead. Refuse this switch
          // while any pending exists or a commit is in flight; the user
          // commits (Escape) or discards (Delete) explicitly, then retries
          // the switch on the settled slot. Prior user data stays intact
          // either way (pending retained, no commit, no clear).
          status = snap.commitInFlight
            ? 'Bitmap save in flight (select-costume blocked; retry after it settles)'
            : 'Bitmap edit pending (select-costume blocked; press Escape to commit or Delete to discard, then retry)'
          return
        }
      }
    } catch {
      return
    }
    const entryTargetId = stableTargetId(selectedTarget)
    const entryIndex = index
    vm.setCurrentCostume(selectedTarget.name, index)
    await tick()
    // A mid-drag switch cancels the reshape drag inside
    // `resetCostumeEditorSelection` (reactive on the selection signature):
    // await its restore so the new preview never observes torn bytes and a
    // concurrent old-asset restore stays the last writer of the old asset.
    await waitForVectorRotateCancel()
    await refreshAssetEditorPreviews()
    // A refused bitmap load sets the explicit refusal status inside
    // `loadCostumeIntoBitmapCanvas`; an unconditional success write here would
    // overwrite it. Preserve the refusal only when it belongs to the
    // just-selected bitmap asset (same target/index/assetKey, settled serial
    // and revision, no pending load). Every other case keeps the success
    // display: owner mismatch (stale/other asset), normal legitimate selects
    // (refused flag false), vector selecting (svg never owns the bitmap
    // workspace), the healthy canary (different target), and async/target-change
    // races (entry no longer matches the live selection) must never surface a
    // stale refusal, nor may a stale select overwrite the newest status.
    try {
      const live = selectedTarget
      if (!live || stableTargetId(live) !== entryTargetId || (live.currentCostume ?? 0) !== entryIndex) return
      if (!isBitmapEditRefused() || bitmapWorkspacePending) {
        status = 'Costume selected'
        return
      }
      const owner = bitmapWorkspaceOwner
      if (
        owner &&
        owner.targetId === stableTargetId(live) &&
        owner.index === (live.currentCostume ?? 0) &&
        owner.index === entryIndex &&
        owner.loadSerial === bitmapCanvasReloadSerial &&
        owner.revision === assetPreviewRevision &&
        owner.assetKey === bitmapAssetKeyOf(live, live.currentCostume ?? 0)
      ) {
        const costume = live.costumes[live.currentCostume ?? 0]
        if (costume && costume.dataFormat !== 'svg') return
      }
    } catch {
      // Fall through to the success display on any guard failure.
    }
    status = 'Costume selected'
  }

  /** Guarded target select (commit-first BEFORE `vm.selectTarget`). */
  async function guardedSelectTarget(name: string): Promise<void> {
    // Synchronous ID capture before any await: the pending commit below
    // yields, and a second switch in between must not re-target this cancel.
    const entryTarget = selectedTarget
    const entryTargetId = entryTarget ? stableTargetId(entryTarget) : ''
    try {
      const pendingSession = ensureBitmapPendingController()?.get()
      if (pendingSession) {
        let snap: { hasPending: boolean; commitInFlight: boolean } | undefined
        try {
          snap = pendingSession.snapshot()
        } catch {
          return
        }
        if (snap && (snap.hasPending || snap.commitInFlight)) {
          // Transactional no-silent-loss (commit-vs-switch race): never
          // auto-commit across a target switch. A switch-triggered commit
          // that lands just before the scope clear loses its history entry
          // to the switch without a gap signal (silent undo loss); a commit
          // racing the switch gaps the append instead. Refuse this switch
          // while any pending exists or a commit is in flight; the user
          // commits (Escape) or discards (Delete) explicitly, then retries
          // the switch on the settled slot. Prior user data stays intact
          // either way (pending retained, no commit, no clear).
          status = snap.commitInFlight
            ? 'Bitmap save in flight (select-target blocked; retry after it settles)'
            : 'Bitmap edit pending (select-target blocked; press Escape to commit or Delete to discard, then retry)'
          return
        }
      }
    } catch {
      return
    }
    // Mid-drag target switch cancels the reshape/rotate/leaf drag BEFORE the
    // swap: retire the gestures synchronously (scoped to the captured entry
    // id) so in-flight preview frames skip via their gesture/selectedTarget
    // guards, then await the barrier restore + drain the old target's queue so
    // the restore stays the last writer of the old asset even though the VM
    // snapshot (and `selectedTarget`) propagates a tick after `vm.selectTarget`.
    // The reactive `resetCostumeEditorSelection` after the swap then finds the
    // drags already cleared (idempotent no-op). Switch-variant restores touch
    // the old slot only through the CAS gate (external same-slot writes win,
    // no history), never editor globals for the new selection.
    if (entryTargetId) {
      try {
        const live = selectedTarget
        if (live && stableTargetId(live) !== entryTargetId) return
      } catch {
        return
      }
      if (vectorPathPointDrag && vectorPathPointDrag.targetId === entryTargetId) {
        const drag = vectorPathPointDrag
        vectorPathPointDrag = undefined
        cancelVectorWriteGesture(drag.gestureId)
        const restoring = restoreVectorPathPointSourceForSelectionSwitch(drag).finally(() => {
          if (vectorRotateCancelPromise === restoring) vectorRotateCancelPromise = undefined
        })
        vectorRotateCancelPromise = restoring
        void restoring
      }
      if (vectorLeafTranslateDrag && vectorLeafTranslateDrag.targetId === entryTargetId) {
        const drag = vectorLeafTranslateDrag
        vectorLeafTranslateDrag = undefined
        cancelVectorWriteGesture(drag.gestureId)
        const restoring = restoreVectorLeafTranslateSourceForSelectionSwitch(drag).finally(() => {
          if (vectorRotateCancelPromise === restoring) vectorRotateCancelPromise = undefined
        })
        vectorRotateCancelPromise = restoring
        void restoring
      }
      if (vectorRotateDrag && vectorRotateDrag.targetId === entryTargetId) {
        const drag = vectorRotateDrag
        vectorRotateDrag = undefined
        cancelVectorWriteGesture(drag.gestureId)
        const restoring = restoreVectorRotateSourceForSelectionSwitch(drag).finally(() => {
          if (vectorRotateCancelPromise === restoring) vectorRotateCancelPromise = undefined
        })
        vectorRotateCancelPromise = restoring
        void restoring
      }
      // Move/resize drags apply live with lazy history: switching only drops
      // their state (mirrors `resetCostumeEditorSelection`), no restore.
      if (vectorDrag && vectorDrag.targetId === entryTargetId) {
        cancelVectorWriteGesture(vectorDrag.gestureId)
        clearVectorGestureIdentity(vectorDrag.gestureId)
        vectorDrag = undefined
      }
      if (vectorResizeDrag && vectorResizeDrag.targetId === entryTargetId) {
        cancelVectorWriteGesture(vectorResizeDrag.gestureId)
        clearVectorGestureIdentity(vectorResizeDrag.gestureId)
        vectorResizeDrag = undefined
      }
      await waitForVectorRotateCancel()
      try {
        await drainTargetVectorWrites(entryTargetId)
      } catch {
        // Best effort only: the restore above already ordered the old slot.
      }
      try {
        const live = selectedTarget
        if (live && stableTargetId(live) !== entryTargetId) return
      } catch {
        return
      }
    }
    vm.selectTarget(name)
    // Fence the worker mirror immediately: host selection is authoritative and
    // the worker only learns it via `sync`. Without this, a stale in-flight
    // WORKER_SYNC (posted before the switch) would revert the host selection
    // right after the swap and strand the new target's UI on the old asset.
    // `sync` bumps the fence id synchronously, so older replies are dropped
    // by the controller guards and the fresh reply carries the new selection
    // (the worker adopts it via `applyHostProjectSnapshot`).
    if (runtimeInWorker) {
      try {
        void runtimeWorker.sync(vm.snapshot())
      } catch {
        // Best effort only: selection already swapped on the host.
      }
    }
    await tick()
    // Same post-swap settle as the costume path: a drag that began during the
    // awaits above is cancelled reactively — await its restore so the new
    // preview never observes torn bytes.
    await waitForVectorRotateCancel()
    await refreshAssetEditorPreviews()
  }

  function renameCostume(index: number) {
    if (!selectedTarget) return
    const target = selectedTarget
    const targetId = stableTargetId(target)
    const current = target.costumes[index]
    const name = window.prompt('Costume name', current?.name ?? '')
    if (!name) return
    // Stable-id route (never the display-name alias), then adopt the
    // post-rename slot version so a pending paint Undo rewinds the drawing
    // while keeping the new name (fail-closed only on real external drift).
    adoptSlotIdentityForUserRename(targetId, index, () => {
      vm.renameCostume(target.id ?? target.name, index, name)
    })
    status = 'Costume renamed'
  }

  function updateCostumeName(index: number, event: Event) {
    if (!selectedTarget) return
    const target = selectedTarget
    const targetId = stableTargetId(target)
    const name = (event.currentTarget as HTMLInputElement).value.trim()
    if (!name || name === target.costumes[index]?.name) return
    adoptSlotIdentityForUserRename(targetId, index, () => {
      vm.renameCostume(target.id ?? target.name, index, name)
    })
    status = 'Costume renamed'
  }

  async function deleteCostume(index: number) {
    try {
      if (isBitmapPendingStructuralBlocked('delete-costume')) return
    } catch {
      return
    }
    if (!selectedTarget) return
    const target = selectedTarget
    const targetId = stableTargetId(target)
    const targetName = target.name
    const doomed = captureVectorDragsForCostumeStructure(targetId)
    // Atomic structural mutation: drain all in-flight vector writes for this
    // target (delayed `vm.updateCostume` re-resolves the numeric index at
    // invocation time, so it must complete BEFORE the array shifts), revert
    // landed deferred previews to pre-drag bytes (slot1 bytes exact), bump
    // the structure epoch so late async preview continuations skip instead of
    // writing shifted artwork. Per-target only; other targets never block.
    await withTargetVectorStructure(targetId, async () => {
      await revertCapturedVectorDragsForStructure(doomed)
      lastDeletedCostume = await currentHistoryEntry({ kind: 'costume', targetName, index, meta: target.costumes[index]!, bytes: new Uint8Array() })
      const live = vectorWriteTargetById(targetId, targetName) ?? vm.getTarget(targetName) ?? target
      lastDeletedCostumeRestore = vm.deleteCostume(live.name, index) ?? undefined
    }, { invalidate: true })
    // Same-slot safety: removing a slot at or before the active one can leave
    // the active index occupied by different artwork.
    clearPaintOnCostumeSlotChange(index)
    status = 'Costume deleted'
  }

  async function restoreDeletedCostume() {
    try {
      if (isBitmapPendingStructuralBlocked('restore-costume')) return
    } catch {
      return
    }
    if (!selectedTarget) return
    const target = selectedTarget
    const targetId = stableTargetId(target)
    const targetName = target.name
    const doomed = captureVectorDragsForCostumeStructure(targetId)
    await withTargetVectorStructure(targetId, async () => {
      await revertCapturedVectorDragsForStructure(doomed)
      if (lastDeletedCostumeRestore) {
        lastDeletedCostumeRestore()
      } else if (lastDeletedCostume) {
        const asset = await vm.storeAsset(lastDeletedCostume.bytes, lastDeletedCostume.meta.dataFormat ?? 'svg')
        const live = vectorWriteTargetById(targetId, targetName) ?? vm.getTarget(targetName) ?? target
        vm.addCostume(live.name, { ...lastDeletedCostume.meta, assetId: asset.assetId, md5ext: asset.md5ext })
      } else {
        return
      }
    }, { invalidate: true })
    lastDeletedCostume = undefined
    lastDeletedCostumeRestore = undefined
    // Re-insertion shifts slots; drop paint history unconditionally (rare op).
    clearPaintHistory()
    status = 'Costume restored'
  }

  async function exportCostume(index: number) {
    if (!selectedTarget) return
    try {
      const pendingSession = ensureBitmapPendingController()?.get()
      if (pendingSession) {
        let snap: { hasPending: boolean; commitInFlight: boolean } | undefined
        try {
          snap = pendingSession.snapshot()
        } catch {
          return
        }
        if (snap && (snap.hasPending || snap.commitInFlight)) {
          const ok = await guardBitmapPendingCommitFirst('export-costume')
          if (!ok) return
        }
      }
    } catch {
      return
    }
    const costume = selectedTarget.costumes[index]
    const key = costume?.md5ext ?? costume?.assetId
    const bytes = key ? await vm.loadAsset(key, costume.dataFormat ?? '') : undefined
    if (!costume || !bytes) return
    const blob = new Blob([new Uint8Array(bytes)], { type: costume.dataFormat === 'svg' ? 'image/svg+xml' : costume.dataFormat === 'png' ? 'image/png' : 'application/octet-stream' })
    const href = URL.createObjectURL(blob)
    const link = document.createElement('a')
    link.href = href
    link.download = `${costume.name}.${costume.dataFormat ?? 'asset'}`
    link.click()
    URL.revokeObjectURL(href)
    status = 'Costume exported'
  }

  async function duplicateCostume(index: number) {
    try {
      if (isBitmapPendingStructuralBlocked('duplicate-costume')) return
    } catch {
      return
    }
    if (!selectedTarget) return
    const target = selectedTarget
    const targetId = stableTargetId(target)
    const targetName = target.name
    const doomed = captureVectorDragsForCostumeStructure(targetId)
    await withTargetVectorStructure(targetId, async () => {
      await revertCapturedVectorDragsForStructure(doomed)
      const live = vectorWriteTargetById(targetId, targetName) ?? vm.getTarget(targetName) ?? target
      return vm.duplicateCostume(live.name, index)
    }, { invalidate: true })
    status = 'Costume duplicated'
  }

  async function moveCostume(index: number, direction: -1 | 1) {
    try {
      if (isBitmapPendingStructuralBlocked('reorder-costume')) return
    } catch {
      return
    }
    if (!selectedTarget) return
    const target = selectedTarget
    const targetId = stableTargetId(target)
    const targetName = target.name
    const doomed = captureVectorDragsForCostumeStructure(targetId)
    await withTargetVectorStructure(targetId, async () => {
      await revertCapturedVectorDragsForStructure(doomed)
      const live = vectorWriteTargetById(targetId, targetName) ?? vm.getTarget(targetName) ?? target
      return vm.reorderCostume(live.name, index, index + direction)
    }, { invalidate: true })
    // Reordering the active target can shift the selected artwork; drop paint
    // history unconditionally (rare op, always safe).
    clearPaintHistory()
    status = 'Costume reordered'
  }

  async function refreshAssetEditorPreviews() {
    if (!selectedTarget) return
    if (selectedTab === 'costumes') await refreshCostumePreview(selectedTarget)
    if (selectedTab === 'sounds') await refreshSoundWaveform(selectedTarget)
  }

  async function refreshCostumePreview(target: ScratchTarget) {
    const revision = assetPreviewRevision
    // Current-scope capture (bounded guards): the reactive `target` snapshot
    // may lag the VM by a TARGETS_UPDATE tick (own red vs external green), so
    // every identity/asset read below is authoritative-live, never snapshot.
    const scopeTargetId = stableTargetId(target)
    const scopeFallbackName = target.name
    const scopeIndex = target.currentCostume ?? 0
    const scopeProject = readProjectGenerationSafe()
    const scopeEpoch = readSelectionEpochSafe()
    const scopeTab = selectedTab
    // Pre-refresh reshape base for stable-identity rebasing below. Mutating
    // reshape paths (style/add/delete/move) pre-publish `vectorObjects`, so
    // this snapshot equals the new artwork there (no-op rebase); undo/redo
    // restores arrive here with the old artwork still in place, so the same
    // code rebases the selection onto the restored anchors.
    const prevReshapeObjectIndex = selectedVectorObjectIndex
    const prevReshapeOwnerPoints = vectorObjects.find((item) => item.index === prevReshapeObjectIndex)?.points
    if (!scopeTargetId) return
    // Authoritative live owner (stable-id only, never a display-name alias).
    // When the snapshot is stale (still shows the own red while the VM
    // already carries the external green) this resolves the live green slot.
    const liveResolved =
      vectorWriteTargetById(scopeTargetId, scopeFallbackName) ?? target
    if (!liveResolved || stableTargetId(liveResolved) !== scopeTargetId) return
    const liveIndex = liveResolved.currentCostume ?? scopeIndex
    // Selection guard: a target/costume switch in between retires this stale
    // refresh — the new selection owns the UI, never the old bytes.
    if (liveIndex !== scopeIndex) return
    if (scopeProject !== readProjectGenerationSafe()) return
    const preIdentity = readLiveSlotIdentity(scopeTargetId, liveIndex)
    const index = liveIndex
    const liveCostumeAtEntry = liveResolved.costumes[index]
    if (!liveCostumeAtEntry) {
      if (costumePreviewUrl) {
        URL.revokeObjectURL(costumePreviewUrl)
        costumePreviewUrl = ''
      }
      costumePreviewSvg = ''
      return
    }
    if (costumePreviewUrl) {
      URL.revokeObjectURL(costumePreviewUrl)
      costumePreviewUrl = ''
    }
    costumePreviewSvg = ''
    const costume = liveCostumeAtEntry
    const key = costume.md5ext ?? costume.assetId
    let bytes = key ? await vm.loadAsset(key, costume.dataFormat ?? '') : undefined
    if (revision !== assetPreviewRevision) return
    if (scopeTab !== selectedTab) return
    if (scopeProject !== readProjectGenerationSafe()) return
    if (!selectedTarget || stableTargetId(selectedTarget) !== scopeTargetId) return
    if ((selectedTarget.currentCostume ?? 0) !== scopeIndex) return
    if (!bytes && key) {
      // SB3 re-import race: the project snapshot can land a tick before the
      // asset store finishes writing the imported bytes. Retry once after a
      // tick instead of permanently clearing to a blank canvas.
      await tick()
      if (revision !== assetPreviewRevision) return
      if (scopeProject !== readProjectGenerationSafe()) return
      if (!selectedTarget || stableTargetId(selectedTarget) !== scopeTargetId) return
      if ((selectedTarget.currentCostume ?? 0) !== scopeIndex) return
      bytes = await vm.loadAsset(key, costume.dataFormat ?? '').catch(() => undefined)
      if (revision !== assetPreviewRevision) return
    }
    // TOCTOU barrier (live-authoritative): a same-slot write that landed
    // while `loadAsset` was in flight leaves `key`/`bytes` stale; painting
    // them would overwrite live pixels from older bytes. Re-read the LIVE
    // slot (never the possibly-stale snapshot object) and reload on drift.
    // Bounded: a single fresh reload, then the newest reactive effect
    // re-runs this refresh if a third write lands in between.
    // Version-aware: `writeSeq` catches metadata-only / same-bytes externals
    // that keep the hash but bump the version.
    const liveAfterLoad = readLiveSlotIdentity(scopeTargetId, index)
    const loadDrifted =
      (liveAfterLoad.md5ext ?? null) !== (preIdentity.md5ext ?? null) ||
      (liveAfterLoad.assetId ?? null) !== (preIdentity.assetId ?? null) ||
      (liveAfterLoad.writeSeq ?? null) !== (preIdentity.writeSeq ?? null)
    let effectiveCostume = liveCostumeAtEntry
    let effectiveIdentity = preIdentity
    if (loadDrifted) {
      if (revision !== assetPreviewRevision) return
      if (scopeProject !== readProjectGenerationSafe()) return
      if (!selectedTarget || stableTargetId(selectedTarget) !== scopeTargetId) return
      if ((selectedTarget.currentCostume ?? 0) !== scopeIndex) return
      const freshOwner =
        vectorWriteTargetById(scopeTargetId, scopeFallbackName) ?? liveResolved
      if (!freshOwner || stableTargetId(freshOwner) !== scopeTargetId) return
      if ((freshOwner.currentCostume ?? 0) !== scopeIndex) return
      const freshCostume = freshOwner.costumes[index]
      const freshKey = freshCostume?.md5ext ?? freshCostume?.assetId
      if (!freshCostume || !freshKey) return
      try {
        const fresh = await vm.loadAsset(freshKey, freshCostume.dataFormat ?? '')
        if (fresh && fresh.length > 0) {
          bytes = fresh
          effectiveCostume = freshCostume
          effectiveIdentity = liveAfterLoad
        } else {
          // Live slot refreshed but bytes unreadable: keep the fresh costume
          // frame so a stale red is never painted over the live green.
          effectiveCostume = freshCostume
          effectiveIdentity = liveAfterLoad
        }
      } catch {
        // Keep the previously loaded bytes on best-effort failure, but still
        // adopt the fresh costume frame below.
        effectiveCostume = freshCostume
        effectiveIdentity = liveAfterLoad
      }
      if (revision !== assetPreviewRevision) return
      if (scopeProject !== readProjectGenerationSafe()) return
      if (!selectedTarget || stableTargetId(selectedTarget) !== scopeTargetId) return
      if ((selectedTarget.currentCostume ?? 0) !== scopeIndex) return
    }
    if (!bytes) {
      // Empty-asset path still honors the live scope: never clear the new
      // selection with an old slot's emptiness (transparent holes: only the
      // verified live slot may clear).
      if (scopeProject !== readProjectGenerationSafe()) return
      if (!selectedTarget || stableTargetId(selectedTarget) !== scopeTargetId) return
      if ((selectedTarget.currentCostume ?? 0) !== scopeIndex) return
      vectorObjects = []
      selectedVectorObjectIndex = -1
      selectedVectorObjectIndices = []
      clearReshapeSelection()
      clearBitmapReloadSkip()
      const emptyOwner = vectorWriteTargetById(scopeTargetId, scopeFallbackName) ?? liveResolved
      await loadCostumeIntoBitmapCanvas(new Uint8Array(), effectiveCostume.dataFormat ?? '', revision, {
        centerX: effectiveCostume.rotationCenterX,
        centerY: effectiveCostume.rotationCenterY,
        isStage: emptyOwner?.isStage ?? target.isStage,
        resolution: effectiveCostume.bitmapResolution,
      }, { targetId: scopeTargetId, index, assetKey: key ?? '' })
      return
    }
    if (effectiveCostume.dataFormat === 'svg') {
      // Decode from the effective (live-revalidated) bytes. The decode is
      // async and long: a same-slot external may land inside it, so the
      // assignment below re-validates the LIVE seq after the decode and
      // before painting — a stale decode never overwrites the latest.
      const liveOwnerForFrame =
        vectorWriteTargetById(scopeTargetId, scopeFallbackName) ?? liveResolved
      const nextSvg = svgTextForVectorEditor(new TextDecoder().decode(bytes), liveOwnerForFrame, effectiveCostume)
      const nextVectorObjects = await paperVectorObjectList(nextSvg)
      if (revision !== assetPreviewRevision) return
      if (scopeTab !== selectedTab) return
      if (scopeProject !== readProjectGenerationSafe()) return
      if (!selectedTarget || stableTargetId(selectedTarget) !== scopeTargetId) return
      if ((selectedTarget.currentCostume ?? 0) !== scopeIndex) return
      // Post-decode live re-validation (bounded, single retry): when the
      // slot moved during the decode, discard this stale frame and paint the
      // newest live bytes instead of letting a lagging red overwrite green.
      const postDecodeIdentity = readLiveSlotIdentity(scopeTargetId, index)
      const postDecodeDrifted =
        (postDecodeIdentity.md5ext ?? null) !== (effectiveIdentity.md5ext ?? null) ||
        (postDecodeIdentity.assetId ?? null) !== (effectiveIdentity.assetId ?? null) ||
        (postDecodeIdentity.writeSeq ?? null) !== (effectiveIdentity.writeSeq ?? null)
      if (postDecodeDrifted) {
        const freshOwner =
          vectorWriteTargetById(scopeTargetId, scopeFallbackName) ?? liveResolved
        if (!freshOwner || stableTargetId(freshOwner) !== scopeTargetId) return
        if ((freshOwner.currentCostume ?? 0) !== scopeIndex) return
        const freshCostume = freshOwner.costumes[index]
        const freshKey = freshCostume?.md5ext ?? freshCostume?.assetId
        if (!freshCostume || !freshKey) return
        try {
          const freshBytes = await vm.loadAsset(freshKey, freshCostume.dataFormat ?? '')
          if (revision !== assetPreviewRevision) return
          if (scopeProject !== readProjectGenerationSafe()) return
          if (!selectedTarget || stableTargetId(selectedTarget) !== scopeTargetId) return
          if ((selectedTarget.currentCostume ?? 0) !== scopeIndex) return
          if (freshBytes && freshBytes.length > 0 && freshCostume.dataFormat === 'svg') {
            const retrySvg = svgTextForVectorEditor(new TextDecoder().decode(freshBytes), freshOwner, freshCostume)
            const retryObjects = await paperVectorObjectList(retrySvg)
            if (revision !== assetPreviewRevision) return
            if (scopeProject !== readProjectGenerationSafe()) return
            if (!selectedTarget || stableTargetId(selectedTarget) !== scopeTargetId) return
            if ((selectedTarget.currentCostume ?? 0) !== scopeIndex) return
            // Final gate: only paint when the retry bytes are still live
            // (a third write in between leaves the paint to the newest
            // reactive effect instead of chasing it here — bounded).
            const finalIdentity = readLiveSlotIdentity(scopeTargetId, index)
            const finalKey = finalIdentity.md5ext ?? finalIdentity.assetId
            if ((finalKey ?? null) !== (freshKey ?? null)) return
            if (
              typeof finalIdentity.writeSeq === 'number' ||
              typeof postDecodeIdentity.writeSeq === 'number'
            ) {
              const freshSeq = readLiveSlotIdentity(scopeTargetId, index).writeSeq
              if (freshSeq !== postDecodeIdentity.writeSeq && freshSeq !== finalIdentity.writeSeq) {
                // Sequence moved again during the retry: do not paint stale.
                return
              }
            }
            costumePreviewSvg = retrySvg
            vectorObjects = retryObjects
            reshapeSelectionSeq += 1
          } else {
            // Fresh live bytes unavailable: drop the stale frame (never paint
            // old red over live green); the newest effect repaints.
            return
          }
        } catch {
          return
        }
      } else {
        costumePreviewSvg = nextSvg
        vectorObjects = nextVectorObjects
        // The artwork is settled: invalidate async selection derivations based
        // on older revisions so a slow resolve never rewrites the rebased state.
        reshapeSelectionSeq += 1
      }
    } else {
      const type = effectiveCostume.dataFormat === 'png' ? 'image/png' : 'application/octet-stream'
      const nextUrl = URL.createObjectURL(new Blob([new Uint8Array(bytes)], { type }))
      if (revision !== assetPreviewRevision) {
        URL.revokeObjectURL(nextUrl)
        return
      }
      if (scopeTab !== selectedTab) {
        URL.revokeObjectURL(nextUrl)
        return
      }
      if (scopeProject !== readProjectGenerationSafe()) {
        URL.revokeObjectURL(nextUrl)
        return
      }
      if (!selectedTarget || stableTargetId(selectedTarget) !== scopeTargetId || (selectedTarget.currentCostume ?? 0) !== scopeIndex) {
        URL.revokeObjectURL(nextUrl)
        return
      }
      // Bitmap post-decode gate: same live-seq discipline so a stale commit
      // preview never overwrites the latest (transparent holes preserved:
      // this only swaps which verified bytes are painted).
      try {
        const postBitmapIdentity = readLiveSlotIdentity(scopeTargetId, index)
        if (
          (postBitmapIdentity.md5ext ?? null) !== (effectiveIdentity.md5ext ?? null) ||
          (postBitmapIdentity.writeSeq ?? null) !== (effectiveIdentity.writeSeq ?? null)
        ) {
          URL.revokeObjectURL(nextUrl)
          return
        }
      } catch {
        URL.revokeObjectURL(nextUrl)
        return
      }
      costumePreviewUrl = nextUrl
      vectorObjects = []
    }
    if (!vectorObjects.some((item) => item.index === selectedVectorObjectIndex)) selectedVectorObjectIndex = -1
    selectedVectorObjectIndices = selectedVectorObjectIndices.filter((index) => vectorObjects.some((item) => item.index === index))
    // Reshape anchor indices shift when handles appear/disappear (curved/pointed,
    // add/delete) and vanish on undo. Slot-stable artwork (moves, paint-only
    // edits: same anchor/handle counts) keeps still-live anchors as before.
    // Structural changes rebase the selection by anchor coordinates — anchors
    // never move for curve/point/add/surviving-delete/undo — and drop whatever
    // is ambiguous, so a reused flat index can never edit another anchor.
    // Either way the group-leaf subselection is re-derived (fail-closed when
    // flattened indices may now name another leaf).
    if (vectorReshapePointIndices.length > 0) {
      const owner = vectorObjects.find((item) => item.index === selectedVectorObjectIndex)
      const livePoints = owner?.points ?? []
      const structural =
        prevReshapeOwnerPoints !== undefined &&
        (prevReshapeOwnerPoints.length !== livePoints.length ||
          prevReshapeOwnerPoints.filter((point) => point.kind !== 'control').length !==
            livePoints.filter((point) => point.kind !== 'control').length)
      if (structural) {
        const rebased = rebaseReshapeSelectionByAnchorCoordinates(
          prevReshapeOwnerPoints!.filter((point) => point.kind !== 'control'),
          livePoints.filter((point) => point.kind !== 'control'),
          vectorReshapePointIndices,
        )
        // Carry handle masks with the same coordinate identity so 5/3 vs 7
        // survives curved/pointed/add/undo instead of upgrading to 7.
        const rebasedMasks = rebaseReshapeHandleMasksByAnchorCoordinates(
          prevReshapeOwnerPoints!.filter((point) => point.kind !== 'control'),
          livePoints.filter((point) => point.kind !== 'control'),
          vectorReshapeHandleMasks,
        )
        // Indices and masks must agree: masks win (they carry provenance),
        // indices are their point-bit projection.
        const maskIndices = reshapeHandleMasksToIndices(rebasedMasks)
        if (JSON.stringify(maskIndices) !== JSON.stringify(rebased)) {
          setReshapeSelectionWithMasks(rebasedMasks)
        } else {
          setReshapeSelection(rebased)
          // setReshapeSelection reset masks to explicit 7; restore curve-aware ones.
          vectorReshapeHandleMasks = rebasedMasks
        }
        void syncReshapeLeavesToPoints()
      } else {
        const live = vectorReshapePointIndices.filter((index) => isReshapeAnchorLive(livePoints, index))
        // Drop masks for vanished anchors (including latent handle-only 2/4/6),
        // keep survivors' exact Paper flags. Prune by live anchors, not by the
        // point-bit projection, so a latent residual on a live anchor survives
        // while any mask naming a vanished anchor is dropped even when the
        // point list still looks live.
        const liveAnchorSet = new Set(
          livePoints.filter((point) => point.kind !== 'control').map((point) => point.index),
        )
        const pruned: ReshapeHandleMasks = {}
        for (const [key, value] of Object.entries(vectorReshapeHandleMasks)) {
          const flat = Number(key)
          if (liveAnchorSet.has(flat)) pruned[flat] = value
        }
        const prunedKeys = Object.keys(pruned).sort()
        const maskKeys = Object.keys(normalizeReshapeHandleMasks(vectorReshapeHandleMasks)).sort()
        const masksStale =
          prunedKeys.length !== maskKeys.length || prunedKeys.some((key, offset) => key !== maskKeys[offset])
        if (live.length !== vectorReshapePointIndices.length || masksStale) {
          setReshapeSelectionWithMasks(pruned)
          clearReshapeLeafSelection()
          void syncReshapeLeavesToPoints()
        }
      }
    } else if (vectorReshapeLeafIndices.length > 0) {
      clearReshapeLeafSelection()
    }
    let shouldSkipReload = false
    {
      // Fail-closed versioned skip + in-flight barrier (never key-only):
      // while our own commit/save is in flight the reload buffers until the
      // flight settles and then reconciles from live; only a proven own
      // committed version (same bytes, same seq, same generation/epoch)
      // skips. Any drift reloads so foreign art is never hidden.
      const liveIdentity = readLiveReloadIdentityForSlot(stableTargetId(target), index)
      const verdict = shouldSkipBitmapCanvasReload(currentReloadSkipToken(), bitmapPendingCommitBarrier, liveIdentity, costume.dataFormat)
      if (verdict.buffered) bitmapReloadDeferredWhileBarrier = true
      shouldSkipReload = verdict.skip
    }
    if (shouldSkipReload) {
      // Own-write skip consumed; live canvas already shows these bytes.
      clearBitmapReloadSkip()
    } else {
      // Buffered-while-in-flight reloads must not paint pre-flight bytes:
      // defer until the flight settles, then reconcile from live (the settle
      // path calls `reconcileDeferredBitmapReload`). A deferred reload that
      // is also the post-settle reconcile itself proceeds (barrier cleared).
      if (bitmapPendingCommitBarrier && bitmapPendingCommitBarrier.key === costumeReloadKey(target, index)) {
        clearBitmapReloadSkip()
        return
      }
      clearBitmapReloadSkip()
      // Vector editing renders the SVG directly. Rasterizing it into the hidden
      // bitmap canvas on every edit is expensive; conversion rasterizes on demand.
      if (effectiveCostume.dataFormat !== 'svg') {
        // Retry once when the reload raced the asset store (blank-canvas
        // guard): a still-missing decode falls back to the artboard clear.
        let reloadBytes: Uint8Array | undefined = bytes
        // Live-revalidated retry key (never a stale snapshot): the effective
        // costume frame already adopted the fresh live slot after the TOCTOU
        // barrier above, so the single bounded retry reuses it.
        const liveRetryKey =
          effectiveCostume.md5ext ?? effectiveCostume.assetId ?? effectiveIdentity.md5ext ?? effectiveIdentity.assetId ?? ''
        const liveRetryFormat = effectiveCostume.dataFormat ?? ''
        if (!reloadBytes || reloadBytes.length === 0) {
          await tick()
          if (revision !== assetPreviewRevision) return
          const retry = liveRetryKey ? await vm.loadAsset(liveRetryKey, liveRetryFormat).catch(() => undefined) : undefined
          if (revision !== assetPreviewRevision) return
          if (retry && retry.length > 0) reloadBytes = retry
        }
        await loadCostumeIntoBitmapCanvas(reloadBytes ?? new Uint8Array(), effectiveCostume.dataFormat ?? '', revision, {
          centerX: effectiveCostume.rotationCenterX,
          centerY: effectiveCostume.rotationCenterY,
          isStage: target.isStage,
          resolution: effectiveCostume.bitmapResolution,
        }, { targetId: stableTargetId(target), index, assetKey: liveRetryKey ?? '' })
      }
    }
  }

  function costumeReloadKey(target: ScratchTarget, index: number) {
    return `${target.id ?? target.name}:${index}`
  }

  // ---- Versioned own-write skip + in-flight barrier (fail-closed) ----
  // The barrier is captured synchronously BEFORE any commit/save `await`
  // (exact pre-flight slot identity + projectGeneration/selectionEpoch) and
  // never authorizes a skip: reloads arriving while it is armed buffer until
  // the flight settles, then reconcile from live. The skip token is armed
  // only AFTER a proven local write from a fresh live read, and the consumer
  // skips only while every field still matches live (same bytes, same seq,
  // same generation/epoch). See `bitmap-pending-reload-skip.ts`.
  function readLiveReloadIdentityForSlot(targetId: string, index: number): BitmapReloadLiveIdentity | undefined {
    try {
      const key = `${targetId}:${index}`
      const identity = (vm as unknown as { getCostumeIdentity?: (t: string, i: number) => { assetId?: unknown; md5ext?: unknown; writeSeq?: unknown } }).getCostumeIdentity?.(targetId, index)
      const assetKey =
        typeof identity?.md5ext === 'string' && identity.md5ext.length > 0
          ? identity.md5ext
          : typeof identity?.assetId === 'string' && identity.assetId.length > 0
            ? identity.assetId
            : ''
      const seqRaw = identity?.writeSeq
      const writeSeq = typeof seqRaw === 'number' && Number.isInteger(seqRaw) && seqRaw >= 0 ? seqRaw : null
      return { key, assetKey, writeSeq, projectGeneration: readProjectGenerationSafe(), selectionEpoch: readSelectionEpochSafe() }
    } catch {
      return undefined
    }
  }
  function captureBitmapReloadBarrierForSlot(targetId: string, index: number): void {
    try {
      const live = readLiveReloadIdentityForSlot(targetId, index)
      if (!live || live.assetKey === '') {
        bitmapPendingCommitBarrier = { key: `${targetId}:${index}`, baseAssetKey: '', baseWriteSeq: null, projectGeneration: readProjectGenerationSafe(), selectionEpoch: readSelectionEpochSafe() }
        return
      }
      bitmapPendingCommitBarrier = { key: live.key, baseAssetKey: live.assetKey, baseWriteSeq: live.writeSeq, projectGeneration: live.projectGeneration, selectionEpoch: live.selectionEpoch }
    } catch {
      // Best effort only: no skip may be armed without a barrier capture.
      try {
        bitmapPendingCommitBarrier = { key: `${targetId}:${index}`, baseAssetKey: '', baseWriteSeq: null, projectGeneration: readProjectGenerationSafe(), selectionEpoch: readSelectionEpochSafe() }
      } catch {
        bitmapPendingCommitBarrier = undefined
      }
    }
  }
  type BitmapReloadCommitScope = { targetId: string; index: number; key: string; projectGeneration: number; selectionEpoch: number | null; barrier: BitmapReloadBarrier | undefined }
  function captureBitmapReloadCommitScope(targetId: string, index: number): BitmapReloadCommitScope {
    let projectGeneration = 0
    try {
      projectGeneration = readProjectGenerationSafe()
    } catch {
      projectGeneration = 0
    }
    let selectionEpoch: number | null = null
    try {
      selectionEpoch = readSelectionEpochSafe()
    } catch {
      selectionEpoch = null
    }
    return { targetId, index, key: `${targetId}:${index}`, projectGeneration, selectionEpoch, barrier: bitmapPendingCommitBarrier }
  }
  function isBitmapReloadCommitScopeCurrent(pre: BitmapReloadCommitScope): boolean {
    try {
      if (!selectedTarget) return false
      if (stableTargetId(selectedTarget) !== pre.targetId) return false
      if ((selectedTarget.currentCostume ?? 0) !== pre.index) return false
      if (bitmapPendingCommitBarrier !== pre.barrier) return false
      let generation = 0
      try {
        generation = readProjectGenerationSafe()
      } catch {
        return false
      }
      if (generation !== pre.projectGeneration) return false
      let epoch: number | null = null
      try {
        epoch = readSelectionEpochSafe()
      } catch {
        epoch = null
      }
      if (pre.selectionEpoch !== null && epoch !== null && epoch !== pre.selectionEpoch) return false
      return true
    } catch {
      return false
    }
  }
  function armBitmapReloadSkipFromLive(targetId: string, index: number): void {
    try {
      const live = readLiveReloadIdentityForSlot(targetId, index)
      if (!live || live.assetKey === '') {
        clearBitmapReloadSkip()
        return
      }
      // Only arm when the flight is still ours: the live generation/epoch
      // must match the pre-flight barrier (a switch/load in between fails
      // closed to no skip). The bytes/version come from the fresh live read
      // itself, so an external write that landed just after the CAS (seq or
      // key drift) is observed here and never skipped.
      const barrier = bitmapPendingCommitBarrier
      if (barrier) {
        // A barrier for another slot must never authorize a skip for this
        // slot: after an await that accepted a new selected owner, the
        // barrier key differs from the requested slot. Fail closed so the
        // new owner's reload is never swallowed.
        if (barrier.key !== live.key) {
          clearBitmapReloadSkip()
          return
        }
        if (barrier.projectGeneration !== live.projectGeneration) {
          clearBitmapReloadSkip()
          return
        }
        if (barrier.selectionEpoch !== null && live.selectionEpoch !== null && barrier.selectionEpoch !== live.selectionEpoch) {
          clearBitmapReloadSkip()
          return
        }
      }
      skipNextBitmapCanvasReloadKey = live.key
      skipNextBitmapCanvasReloadAssetKey = live.assetKey
      skipNextBitmapCanvasReloadWriteSeq = live.writeSeq
      skipNextBitmapCanvasReloadProjectGen = live.projectGeneration
      skipNextBitmapCanvasReloadSelectionEpoch = live.selectionEpoch
    } catch {
      clearBitmapReloadSkip()
    }
  }
  function clearBitmapReloadSkip(): void {
    try {
      skipNextBitmapCanvasReloadKey = ''
      skipNextBitmapCanvasReloadAssetKey = undefined
      skipNextBitmapCanvasReloadWriteSeq = undefined
      skipNextBitmapCanvasReloadProjectGen = undefined
      skipNextBitmapCanvasReloadSelectionEpoch = undefined
    } catch {
      // Best effort only.
    }
  }
  function clearBitmapReloadBarrier(): void {
    try {
      bitmapPendingCommitBarrier = undefined
    } catch {
      // Best effort only.
    }
  }
  function currentReloadSkipToken(): BitmapReloadSkipToken | undefined {
    if (skipNextBitmapCanvasReloadKey === '') return undefined
    if (typeof skipNextBitmapCanvasReloadAssetKey !== 'string' || skipNextBitmapCanvasReloadAssetKey === '') return undefined
    if (typeof skipNextBitmapCanvasReloadProjectGen !== 'number' || !Number.isInteger(skipNextBitmapCanvasReloadProjectGen) || skipNextBitmapCanvasReloadProjectGen < 0) return undefined
    return {
      key: skipNextBitmapCanvasReloadKey,
      assetKey: skipNextBitmapCanvasReloadAssetKey,
      writeSeq: typeof skipNextBitmapCanvasReloadWriteSeq === 'number' ? skipNextBitmapCanvasReloadWriteSeq : null,
      projectGeneration: skipNextBitmapCanvasReloadProjectGen,
      selectionEpoch: typeof skipNextBitmapCanvasReloadSelectionEpoch === 'number' ? skipNextBitmapCanvasReloadSelectionEpoch : null,
    }
  }
  async function reconcileDeferredBitmapReload(): Promise<void> {
    if (!bitmapReloadDeferredWhileBarrier) return
    bitmapReloadDeferredWhileBarrier = false
    try {
      const liveTarget = selectedTarget
      if (!liveTarget) return
      const wantId = stableTargetId(liveTarget)
      const liveIndex = liveTarget.currentCostume ?? 0
      const resolved = vectorWriteTargetById(wantId, liveTarget.name) ?? vm.getTarget(wantId) ?? vm.getTarget(liveTarget.name) ?? liveTarget
      if (stableTargetId(resolved) !== wantId) return
      await refreshCostumePreview(resolved)
    } catch {
      // Best effort only: the next reactive refresh still reconciles.
    }
  }

  // Structural costume-list changes (delete/restore/reorder/duplicate) can
  // leave the same numeric slot occupied by different artwork. Active
  // point/rotate/leaf gestures are abandoned WITHOUT a snapshot restore: the
  // structural write itself is the latest legitimate edit, and restoring old
  // bytes onto a shifted slot would corrupt another asset. Retiring the
  // gesture synchronously also makes late in-flight previews skip their
  // queued write. Rename-safe: renames keep id+index, so they never abandon.
  function abandonVectorGesturesForCostumeStructure() {
    if (vectorPathPointDrag) {
      cancelVectorWriteGesture(vectorPathPointDrag.gestureId)
      clearVectorGestureIdentity(vectorPathPointDrag.gestureId)
      vectorPathPointDrag = undefined
    }
    if (vectorLeafTranslateDrag) {
      cancelVectorWriteGesture(vectorLeafTranslateDrag.gestureId)
      clearVectorGestureIdentity(vectorLeafTranslateDrag.gestureId)
      vectorLeafTranslateDrag = undefined
    }
    if (vectorRotateDrag) {
      cancelVectorWriteGesture(vectorRotateDrag.gestureId)
      clearVectorGestureIdentity(vectorRotateDrag.gestureId)
      vectorRotateDrag = undefined
    }
    // Move is preview-only (no VM writes yet): the rAF preview was already
    // cancelled above; retire the versioned gesture synchronously and drop
    // state so a stale continuation cannot write shifted artwork. Resize
    // applies live with no snapshot to restore: same retire.
    if (vectorDrag) {
      cancelVectorMovePreview(vectorDrag)
      cancelVectorWriteGesture(vectorDrag.gestureId)
      clearVectorGestureIdentity(vectorDrag.gestureId)
      vectorDrag = undefined
    }
    if (vectorResizeDrag) {
      cancelVectorWriteGesture(vectorResizeDrag.gestureId)
      clearVectorGestureIdentity(vectorResizeDrag.gestureId)
      vectorResizeDrag = undefined
    }
  }

  type CapturedVectorDragForStructure = {
    targetId: string
    targetName: string
    costumeIndex: number
    gestureId?: VectorWriteGesture
    historyReady?: Promise<AssetHistoryEntry | undefined>
    pendingEntry?: AssetHistoryEntry
    sourceReady?: Promise<{ targetName: string; costumeIndex: number; svgText: string } | undefined>
  }

  // Sync capture for structural mutations (delete/reorder/duplicate/restore/
  // true pointer DnD drop). Retires gestures synchronously so late async
  // preview continuations never enqueue with the new epoch, clears drag
  // globals so held-pointer moves stop, and returns descriptors for a direct
  // revert inside the structure barrier. Only drags owned by `targetId` are
  // captured; other targets never block.
  function captureVectorDragsForCostumeStructure(targetId: string): CapturedVectorDragForStructure[] {
    const captured: CapturedVectorDragForStructure[] = []
    if (vectorPathPointDrag && vectorPathPointDrag.targetId === targetId) {
      const drag = vectorPathPointDrag
      vectorPathPointDrag = undefined
      cancelVectorWriteGesture(drag.gestureId)
      clearVectorGestureIdentity(drag.gestureId)
      captured.push({
        targetId: drag.targetId,
        targetName: drag.targetName,
        costumeIndex: drag.costumeIndex,
        gestureId: drag.gestureId,
        historyReady: drag.historyReady,
        pendingEntry: drag.pendingEntry,
        sourceReady: drag.sourceReady,
      })
    }
    if (vectorLeafTranslateDrag && vectorLeafTranslateDrag.targetId === targetId) {
      const drag = vectorLeafTranslateDrag
      vectorLeafTranslateDrag = undefined
      cancelVectorWriteGesture(drag.gestureId)
      clearVectorGestureIdentity(drag.gestureId)
      captured.push({
        targetId: drag.targetId,
        targetName: drag.targetName,
        costumeIndex: drag.costumeIndex,
        gestureId: drag.gestureId,
        historyReady: drag.historyReady,
        pendingEntry: drag.pendingEntry,
        sourceReady: drag.sourceReady,
      })
    }
    if (vectorRotateDrag && vectorRotateDrag.targetId === targetId) {
      const drag = vectorRotateDrag
      vectorRotateDrag = undefined
      cancelVectorWriteGesture(drag.gestureId)
      clearVectorGestureIdentity(drag.gestureId)
      captured.push({
        targetId: drag.targetId,
        targetName: drag.targetName,
        costumeIndex: drag.costumeIndex,
        gestureId: drag.gestureId,
        historyReady: drag.historyReady,
        pendingEntry: drag.pendingEntry,
        sourceReady: drag.sourceReady,
      })
    }
    if (vectorDrag && vectorDrag.targetId === targetId) {
      const drag = vectorDrag
      vectorDrag = undefined
      cancelVectorWriteGesture(drag.gestureId)
      clearVectorGestureIdentity(drag.gestureId)
      captured.push({
        targetId: drag.targetId,
        targetName: drag.targetName,
        costumeIndex: drag.costumeIndex,
        gestureId: drag.gestureId,
        historyReady: drag.historyReady,
        pendingEntry: drag.pendingEntry,
      })
    }
    if (vectorResizeDrag && vectorResizeDrag.targetId === targetId) {
      const drag = vectorResizeDrag
      vectorResizeDrag = undefined
      cancelVectorWriteGesture(drag.gestureId)
      captured.push({
        targetId: drag.targetId,
        targetName: drag.targetName,
        costumeIndex: drag.costumeIndex,
        gestureId: drag.gestureId,
        historyReady: drag.historyReady,
        pendingEntry: drag.pendingEntry,
        sourceReady: drag.sourceReady,
      })
    }
    return captured
  }

  // Direct revert of landed deferred previews before the array shifts.
  // Runs INSIDE `withTargetVectorStructure` (after its drain, before `op`,
  // while the per-target barrier is held): the drain already settled
  // in-flight gated `vm.updateCostume` writes, so landed preview mutations
  // are visible here; late continuations were cancelled at capture and skip
  // via epoch/gesture guards. Bypass the queue with direct `vm.updateCostume`
  // (queue writes with the new epoch would wait for this same barrier and
  // deadlock). Best-effort: never blocks the structural mutation itself.
  async function revertCapturedVectorDragsForStructure(
    drags: CapturedVectorDragForStructure[],
  ): Promise<void> {
    for (const drag of drags) {
      try {
        let exact: AssetHistoryEntry | undefined
        if (drag.pendingEntry && drag.pendingEntry.kind === 'costume' && drag.pendingEntry.index === drag.costumeIndex) {
          exact = drag.pendingEntry
        } else if (drag.historyReady) {
          try {
            const awaited = await drag.historyReady.catch(() => undefined)
            if (awaited && awaited.kind === 'costume' && awaited.index === drag.costumeIndex) exact = awaited
          } catch {
            exact = undefined
          }
        }
        const live =
          vectorWriteTargetById(drag.targetId, drag.targetName) ??
          vm.getTarget(drag.targetId) ??
          vm.getTarget(drag.targetName)
        if (!live || stableTargetId(live) !== drag.targetId) continue
        if (!live.costumes[drag.costumeIndex]) continue
        const liveName = (live as { name: string }).name ?? drag.targetName
        if (exact && exact.kind === 'costume' && exact.meta && exact.bytes) {
          // Structural revert owns bytes only: keep the live display name
          // (rename layer), matching the history-restore patch discipline.
          await vm.updateCostume(
            liveName,
            drag.costumeIndex,
            historyCostumeRestorePatch(exact.meta),
            new Uint8Array(exact.bytes as Uint8Array),
          )
          continue
        }
        if (drag.sourceReady) {
          let source: { targetName: string; costumeIndex: number; svgText: string } | undefined
          try {
            source = await drag.sourceReady.catch(() => undefined)
          } catch {
            source = undefined
          }
          if (!source || !source.svgText) continue
          const runtime = vectorRuntimeCostume(source.svgText, live, drag.costumeIndex)
          const bytes = new TextEncoder().encode(runtime.svgText)
          await vm.updateCostume(liveName, drag.costumeIndex, runtime.patch as Partial<ScratchCostume>, bytes)
        }
      } catch {
        // Best-effort only: a missing target/slot or failed load must never
        // block delete/reorder/duplicate/restore.
      }
    }
  }

  function resetCostumeEditorSelection() {
    // Target/costume switch closes the nudge cycle for the old asset first.
    commitNudgePendingSync()
    // A reshape point drag owns live pointer capture: it survives the target
    // / costume switch that this reset reacts to, so cancel it explicitly.
    // The cancel restores the old artwork's pre-drag snapshot to the OLD
    // asset only (never the newly selected one), terminates the pending
    // peeked entry without committing (history/redo untouched), and tracks
    // the async restore on the shared cancel promise so an immediate next
    // edit (or Undo/Redo) awaits the restored bytes instead of racing them.
    // A deleted old target/costume is a safe no-op. The drag state is
    // cleared synchronously so in-flight pointer moves stop immediately.
    if (vectorPathPointDrag) {
      const drag = vectorPathPointDrag
      vectorPathPointDrag = undefined
      cancelVectorWriteGesture(drag.gestureId)
      const restoring = restoreVectorPathPointSourceForSelectionSwitch(drag).finally(() => {
        if (vectorRotateCancelPromise === restoring) vectorRotateCancelPromise = undefined
      })
      vectorRotateCancelPromise = restoring
      void restoring
    }
    if (vectorLeafTranslateDrag) {
      const drag = vectorLeafTranslateDrag
      vectorLeafTranslateDrag = undefined
      cancelVectorWriteGesture(drag.gestureId)
      const restoring = restoreVectorLeafTranslateSourceForSelectionSwitch(drag).finally(() => {
        if (vectorRotateCancelPromise === restoring) vectorRotateCancelPromise = undefined
      })
      vectorRotateCancelPromise = restoring
      void restoring
    }
    // A vector rotation owns an uncommitted snapshot for the OLD asset:
    // restore it there (never the new asset) like the reshape path, so the
    // old artwork is never stranded mid-rotate. Move drags are preview-only
    // (zero VM writes until pointerup), so switching only cancels the rAF
    // preview and drops state + center guide; the new asset preview reload
    // overwrites any painted preview. Resize drags apply live with lazy
    // history, so switching only drops their state + center guide.
    // All clears are synchronous so in-flight pointermove guards stop before
    // any stale write. Bitmap floating previews are uncommitted canvas
    // pixels for the old asset: the new canvas will be reloaded, so drop the
    // drag state without touching pixels here (no stale putImageData).
    if (vectorRotateDrag) {
      const drag = vectorRotateDrag
      vectorRotateDrag = undefined
      cancelVectorWriteGesture(drag.gestureId)
      // Selection-switch restore never touches editor globals: the editor
      // already shows the new asset. Route through the same barrier restore
      // (old slot only) so in-flight previews of this gesture order before it.
      const restoring = restoreVectorRotateSourceForSelectionSwitch(drag).finally(() => {
        if (vectorRotateCancelPromise === restoring) vectorRotateCancelPromise = undefined
      })
      vectorRotateCancelPromise = restoring
      void restoring
    }
    if (vectorDrag) {
      cancelVectorMovePreview(vectorDrag)
      cancelVectorWriteGesture(vectorDrag.gestureId)
      clearVectorGestureIdentity(vectorDrag.gestureId)
      vectorDrag = undefined
    }
    if (vectorResizeDrag) {
      cancelVectorWriteGesture(vectorResizeDrag.gestureId)
      clearVectorGestureIdentity(vectorResizeDrag.gestureId)
      vectorResizeDrag = undefined
    }
    bitmapSelection = undefined
    bitmapMoveDrag = undefined
    bitmapScaleDrag = undefined
    bitmapRotateDrag = undefined
    bitmapStart = undefined
    bitmapPreviewBase = undefined
    bitmapShapePreviewDrawn = false
    bitmapPaperPoints = []
          bitmapStrokeStamps = 0
          bitmapStrokeCapped = false
    isBitmapPainting = false
    bitmapStrokeOwner = undefined
    selectedVectorObjectIndex = -1
    selectedVectorObjectIndices = []
    clearReshapeSelection()
    // A pending pick belongs to the previous artwork; drop it silently so a
    // stale loupe can never tint the new canvas.
    eyedropperActive = false
  }

  function svgTextForVectorEditor(svgText: string, target: ScratchTarget, costume: ScratchCostume) {
    // Trust boundary: sanitize untrusted SVG bytes BEFORE parsing/touching
    // the DOM. The old code returned the raw string when XML parsing failed,
    // which handed unsanitized markup straight to the `{@html}` preview sink.
    // Fail closed to a blank canvas-sized SVG instead.
    const clean = sanitizeSvgForDisplay(svgText)
    const doc = new DOMParser().parseFromString(clean, 'image/svg+xml')
    const svg = doc.documentElement
    if (svg.nodeName.toLowerCase() !== 'svg' || doc.getElementsByTagName('parsererror').length > 0) {
      return blankVectorEditorSvg()
    }
    const stageWidth = 480
    const stageHeight = 360
    const geometry = svgGeometry(svg, target)
    const { width, height } = geometry
    if (target.isStage || (width === stageWidth && height === stageHeight && svg.getAttribute('viewBox') === `0 0 ${stageWidth} ${stageHeight}`)) {
      svg.setAttribute('width', String(stageWidth))
      svg.setAttribute('height', String(stageHeight))
      svg.setAttribute('viewBox', `0 0 ${stageWidth} ${stageHeight}`)
      return sanitizeSvgForDisplay(new XMLSerializer().serializeToString(svg))
    }
    const dx = stageWidth / 2 - (geometry.viewBoxX + (costume.rotationCenterX ?? width / 2))
    const dy = stageHeight / 2 - (geometry.viewBoxY + (costume.rotationCenterY ?? height / 2))
    for (const child of editableSvgChildren(svg)) addTranslate(child, dx, dy)
    svg.setAttribute('width', String(stageWidth))
    svg.setAttribute('height', String(stageHeight))
    svg.setAttribute('viewBox', `0 0 ${stageWidth} ${stageHeight}`)
    return sanitizeSvgForDisplay(new XMLSerializer().serializeToString(svg))
  }

  function blankVectorEditorSvg() {
    return sanitizeSvgForDisplay(
      '<svg xmlns="http://www.w3.org/2000/svg" width="480" height="360" viewBox="0 0 480 360"></svg>',
    ) || SVG_PLACEHOLDER
  }

  function svgIntrinsicSize(svgText: string, target: ScratchTarget) {
    const doc = new DOMParser().parseFromString(svgText, 'image/svg+xml')
    const svg = doc.documentElement
    if (svg.nodeName.toLowerCase() !== 'svg') return { width: target.isStage ? 480 : 96, height: target.isStage ? 360 : 96 }
    const { width, height } = svgGeometry(svg, target)
    return { width, height }
  }

  function svgGeometry(svg: Element, target: ScratchTarget) {
    const viewBox = svg.getAttribute('viewBox')?.trim().split(/[\s,]+/).map(Number)
    const viewBoxX = viewBox && Number.isFinite(viewBox[0]) ? viewBox[0]! : 0
    const viewBoxY = viewBox && Number.isFinite(viewBox[1]) ? viewBox[1]! : 0
    const viewBoxWidth = viewBox && Number.isFinite(viewBox[2]) ? viewBox[2]! : undefined
    const viewBoxHeight = viewBox && Number.isFinite(viewBox[3]) ? viewBox[3]! : undefined
    return {
      viewBoxX,
      viewBoxY,
      width: optionalSvgNumber(svg.getAttribute('width')) ?? viewBoxWidth ?? (target.isStage ? 480 : 96),
      height: optionalSvgNumber(svg.getAttribute('height')) ?? viewBoxHeight ?? (target.isStage ? 360 : 96),
    }
  }

  async function refreshCostumeThumbnails(target: ScratchTarget) {
    const revision = assetPreviewRevision
    const request = ++costumeThumbnailRequest
    const nextEntries: Record<string, CostumeThumbnailEntry> = {}
    const createdUrls: string[] = []
    await Promise.all(target.costumes.map(async (costume, index) => {
      const key = costume.md5ext ?? costume.assetId
      if (!key) return
      const slot = costumeThumbnailKey(target, costume, index)
      const assetKey = `${key}:${costume.dataFormat ?? ''}`
      const previous = costumeThumbnailEntries[slot]
      if (previous?.assetKey === assetKey) {
        nextEntries[slot] = previous
        return
      }
      const bytes = await vm.loadAsset(key, costume.dataFormat ?? '')
      if (request !== costumeThumbnailRequest || revision !== assetPreviewRevision) return
      const url = bytes ? await loadCostumeThumbnail(bytes, costume.dataFormat ?? '') : undefined
      if (!url) {
        if (previous) nextEntries[slot] = previous
        return
      }
      createdUrls.push(url)
      nextEntries[slot] = { assetKey, url }
    }))
    if (request !== costumeThumbnailRequest || revision !== assetPreviewRevision) {
      createdUrls.forEach((url) => URL.revokeObjectURL(url))
      return
    }
    const previousEntries = costumeThumbnailEntries
    costumeThumbnailEntries = nextEntries
    costumeThumbnailUrls = thumbnailUrls(nextEntries)
    await tick()
    const retained = new Set(Object.values(nextEntries).map((entry) => entry.url))
    for (const entry of Object.values(previousEntries)) {
      if (!retained.has(entry.url)) URL.revokeObjectURL(entry.url)
    }
  }

  function refreshTargetThumbnails(items: ScratchTarget[]) {
    const sources = items.flatMap((target) => {
      const costume = target.costumes[target.currentCostume ?? 0]
      const key = costume?.md5ext ?? costume?.assetId
      if (!costume || !key) return []
      const format = costume.dataFormat ?? ''
      return [{ slot: targetThumbnailKey(target), assetKey: `${key}:${format}`, key, format }]
    })
    return targetThumbnails.refresh(sources)
  }

  function costumeThumbnailKey(target: ScratchTarget, _costume: ScratchCostume, index: number) {
    return `${target.id ?? target.name}:${index}`
  }

  function targetThumbnailKey(target: ScratchTarget) {
    return `${target.id ?? target.name}`
  }

  function costumeDisplaySize(target: ScratchTarget | undefined, costume: ScratchCostume) {
    if (target?.isStage) return '480 x 360'
    const resolution = costume.bitmapResolution && costume.bitmapResolution > 0 ? costume.bitmapResolution : 1
    const width = Math.round((costume.rotationCenterX ?? 48) * 2 / resolution)
    const height = Math.round((costume.rotationCenterY ?? 48) * 2 / resolution)
    return `${width} x ${height}`
  }

  async function loadCostumeIntoBitmapCanvas(
    bytes: Uint8Array,
    dataFormat: string,
    revision = assetPreviewRevision,
    placement?: { centerX?: number; centerY?: number; isStage?: boolean; resolution?: number },
    owner?: { targetId: string; index: number; assetKey: string },
  ) {
    // Last-starter-wins serial: rapid sequential restores/saves each trigger
    // an async decode + draw, and a slow earlier decode must never overwrite a
    // newer state (e.g. 8 rapid Undos must end on the oldest entry, not on
    // whichever decode finishes last). Stale loads abort before drawing.
    //
    // Artboard model: the live canvas is the resolution-matched Scratch
    // artboard (480x360 stage units x stored R), NOT the stored PNG pixels.
    // The source is placed verbatim at origin = artCenter(R) - storedCenter
    // with transparent margins, leaving room to paint outside the original
    // bounds. Huge sources expand to union(artboard, source); over the
    // memory cap the helper falls back to the verbatim source rect (never
    // truncated). A `refused` source (area over budget) is never allocated:
    // the edit is rejected explicitly and the stored asset stays untouched.
    //
    // Workspace owner gate: the pending token marks the in-flight decode, the
    // owner token marks the last fully drawn asset. Mutations/saves validate
    // the owner; while pending is set the canvas is unsettled and must not be
    // read as the new asset.
    const reloadSerial = ++bitmapCanvasReloadSerial
    const pendingOwner: BitmapWorkspacePending = {
      targetId: owner?.targetId ?? (selectedTarget ? stableTargetId(selectedTarget) : ''),
      index: owner?.index ?? (selectedTarget?.currentCostume ?? 0),
      assetKey: owner?.assetKey ?? '',
      loadSerial: reloadSerial,
      revision,
    }
    bitmapWorkspacePending = pendingOwner
    // A new load invalidates any in-progress stroke for the previous asset.
    bitmapStrokeOwner = undefined
    if (!bitmapCanvas) {
      if (bitmapWorkspacePending?.loadSerial === reloadSerial) bitmapWorkspacePending = undefined
      return
    }
    if (revision !== assetPreviewRevision) {
      if (bitmapWorkspacePending?.loadSerial === reloadSerial) bitmapWorkspacePending = undefined
      return
    }
    const context = bitmapCanvas.getContext('2d')
    if (!context) {
      if (bitmapWorkspacePending?.loadSerial === reloadSerial) bitmapWorkspacePending = undefined
      return
    }
    const isStage = placement?.isStage ?? selectedTarget?.isStage ?? false
    const storedResolution =
      typeof placement?.resolution === 'number' && Number.isFinite(placement.resolution) && placement.resolution > 0
        ? placement.resolution
        : isStage ? 1 : 2
    const placeEmpty = () => {
      const empty = emptyArtboardCanvas(isStage, storedResolution)
      if (bitmapCanvas.width !== empty.width || bitmapCanvas.height !== empty.height) {
        resizeBitmapCanvas(empty.width, empty.height)
      }
      bitmapArtboard = { originX: empty.originX, originY: empty.originY, canvasCenterX: empty.canvasCenterX, canvasCenterY: empty.canvasCenterY, isStage, width: empty.width, height: empty.height, resolution: empty.resolution, refused: false }
      bitmapArtboardPlacementCenter = { x: empty.canvasCenterX - empty.originX, y: empty.canvasCenterY - empty.originY }
      bitmapArtboardCenterOffset = { x: 0, y: 0 }
    }
    const commitOwner = (assetKey = pendingOwner.assetKey) => {
      bitmapWorkspaceGeneration += 1
      bitmapWorkspaceOwner = {
        targetId: pendingOwner.targetId,
        index: pendingOwner.index,
        assetKey,
        loadSerial: reloadSerial,
        generation: bitmapWorkspaceGeneration,
        revision,
      }
      if (bitmapWorkspacePending?.loadSerial === reloadSerial) bitmapWorkspacePending = undefined
    }
    const publishBitmapFitState = (
      bounds: { x: number; y: number; width: number; height: number } | null,
      surfaceWidth: number,
      surfaceHeight: number,
    ) => {
      bitmapFitState = {
        bounds,
        surfaceWidth,
        surfaceHeight,
        targetId: pendingOwner.targetId,
        index: pendingOwner.index,
        assetKey: pendingOwner.assetKey,
        serial: reloadSerial,
      }
    }
    if (!bytes || bytes.length === 0) {
      placeEmpty()
      await tick()
      if (revision !== assetPreviewRevision || reloadSerial !== bitmapCanvasReloadSerial) return
      bitmapSelection = undefined
      clearBitmapCanvasPreview()
      commitOwner()
      maybeResolveBitmapLoadingStatus()
      publishBitmapFitState(null, bitmapArtboard.width, bitmapArtboard.height)
      return
    }
    if (dataFormat !== 'svg' && dataFormat !== 'png' && dataFormat !== 'jpg' && dataFormat !== 'jpeg') {
      placeEmpty()
      await tick()
      if (revision !== assetPreviewRevision || reloadSerial !== bitmapCanvasReloadSerial) return
      bitmapSelection = undefined
      clearBitmapCanvasPreview()
      commitOwner()
      maybeResolveBitmapLoadingStatus()
      publishBitmapFitState(null, bitmapArtboard.width, bitmapArtboard.height)
      return
    }
    const type = dataFormat === 'svg' ? 'image/svg+xml' : dataFormat === 'jpg' || dataFormat === 'jpeg' ? 'image/jpeg' : 'image/png'
    const url = URL.createObjectURL(new Blob([new Uint8Array(bytes)], { type }))
    try {
      const image = new Image()
      await new Promise<void>((resolve, reject) => {
        image.onload = () => resolve()
        image.onerror = reject
        image.src = url
      })
      if (revision !== assetPreviewRevision) return
      if (reloadSerial !== bitmapCanvasReloadSerial) return
      const decodedWidth = Math.round(image.naturalWidth || image.width || 0)
      const decodedHeight = Math.round(image.naturalHeight || image.height || 0)
      if (!(decodedWidth > 0 && decodedHeight > 0)) {
        placeEmpty()
        await tick()
        if (revision !== assetPreviewRevision || reloadSerial !== bitmapCanvasReloadSerial) return
        bitmapSelection = undefined
        clearBitmapCanvasPreview()
        commitOwner()
        maybeResolveBitmapLoadingStatus()
        publishBitmapFitState(null, bitmapArtboard.width, bitmapArtboard.height)
        return
      }
      const cx = typeof placement?.centerX === 'number' && Number.isFinite(placement.centerX)
        ? (placement.centerX as number)
        : decodedWidth / 2
      const cy = typeof placement?.centerY === 'number' && Number.isFinite(placement.centerY)
        ? (placement.centerY as number)
        : decodedHeight / 2
      const placed = placeSourceOnArtboard(decodedWidth, decodedHeight, cx, cy, isStage, storedResolution)
      if (placed.refused) {
        // Over-budget source: never allocate or truncate. Keep the stored
        // asset byte-identical, clear the live view, and reject explicitly.
        bitmapArtboard = { originX: 0, originY: 0, canvasCenterX: placed.canvasCenterX, canvasCenterY: placed.canvasCenterY, isStage, width: bitmapCanvas.width, height: bitmapCanvas.height, resolution: storedResolution, refused: true }
        bitmapArtboardPlacementCenter = { x: cx, y: cy }
        bitmapArtboardCenterOffset = { x: 0, y: 0 }
        bitmapSelection = undefined
        const stillLive = bitmapCanvas.getContext('2d')
        stillLive?.clearRect(0, 0, bitmapCanvas.width, bitmapCanvas.height)
        clearBitmapCanvasPreview()
        status = 'Image too large to edit safely — original kept unchanged'
        commitOwner()
        publishBitmapFitState(null, bitmapCanvas.width, bitmapCanvas.height)
        return
      }
      if (bitmapCanvas.width !== placed.width || bitmapCanvas.height !== placed.height) {
        resizeBitmapCanvas(placed.width, placed.height)
      }
      bitmapArtboard = { originX: placed.originX, originY: placed.originY, canvasCenterX: placed.canvasCenterX, canvasCenterY: placed.canvasCenterY, isStage, width: placed.width, height: placed.height, resolution: placed.resolution, refused: false }
      bitmapArtboardPlacementCenter = { x: cx, y: cy }
      bitmapArtboardCenterOffset = { x: 0, y: 0 }
      // Always let Svelte flush before drawing (not only after our own
      // resize): a previous overlapping reload may have resized just before
      // us, and its pending `width=` flush would otherwise wipe the pixels
      // we draw now (Chrome resets even on same-value assignment). The
      // serial/revision re-check drops us when a newer load started during
      // the decode+tick window.
      await tick()
      if (revision !== assetPreviewRevision) return
      if (reloadSerial !== bitmapCanvasReloadSerial) return
      // resizeBitmapCanvas resets the raster; drop any selection owned by the
      // previous dimensions before drawing the restored bytes.
      bitmapSelection = undefined
      const live = bitmapCanvas.getContext('2d')
      live?.clearRect(0, 0, bitmapCanvas.width, bitmapCanvas.height)
      live?.drawImage(image, placed.originX, placed.originY, decodedWidth, decodedHeight)
      // Real raster verification: the decode path carries extreme sides but
      // the full-size 2D raster may silently refuse them (blank canvas +
      // null encode while the area budget passes). A blank live canvas fed
      // into Save/convert would overwrite the stored asset with transparent
      // bytes or an empty SVG, so verify readback + sampled ink + encode and
      // refuse with the stored asset untouched when the environment cannot
      // hold the pixels.
      {
        const rasterOk = await verifyBitmapLiveRaster(image, decodedWidth, decodedHeight, placed.originX, placed.originY, placed.width, placed.height)
        if (revision !== assetPreviewRevision) return
        if (reloadSerial !== bitmapCanvasReloadSerial) return
        if (!rasterOk) {
          bitmapArtboard = { originX: 0, originY: 0, canvasCenterX: placed.canvasCenterX, canvasCenterY: placed.canvasCenterY, isStage, width: bitmapCanvas.width, height: bitmapCanvas.height, resolution: storedResolution, refused: true }
          bitmapArtboardPlacementCenter = { x: cx, y: cy }
          bitmapArtboardCenterOffset = { x: 0, y: 0 }
          bitmapSelection = undefined
          clearBitmapCanvasPreview()
          refuseBitmapOversize()
          commitOwner()
          publishBitmapFitState(null, bitmapCanvas.width, bitmapCanvas.height)
          return
        }
      }
      // F1: Scratch fits the opaque hit bounds, not the placed source rect.
      // Scan the live raster read-only (tiled so large canvases never hold a
      // full W*H*4 readback at once) for the minimal alpha !== 0 rect;
      // empty/unreadable publishes null so the fit stays at the base reset.
      // Stale serial/revision (switch/undo/late load) aborts before
      // commit/publish so stale bounds are never emitted. No bitmap
      // data/history write here.
      if (revision !== assetPreviewRevision) return
      if (reloadSerial !== bitmapCanvasReloadSerial) return
      const opaqueBounds = bitmapCanvas ? scanBitmapOpaqueBounds(bitmapCanvas) : undefined
      if (revision !== assetPreviewRevision) return
      if (reloadSerial !== bitmapCanvasReloadSerial) return
      commitOwner()
      maybeResolveBitmapLoadingStatus()
      publishBitmapFitState(
        opaqueBounds ? { x: opaqueBounds.x, y: opaqueBounds.y, width: opaqueBounds.width, height: opaqueBounds.height } : null,
        placed.width,
        placed.height,
      )
    } catch {
      // Undecodable asset: fall back to the artboard-sized clear canvas.
      if (revision === assetPreviewRevision && reloadSerial === bitmapCanvasReloadSerial) {
        placeEmpty()
        await tick()
        if (revision !== assetPreviewRevision || reloadSerial !== bitmapCanvasReloadSerial) return
        bitmapSelection = undefined
        clearBitmapCanvasPreview()
        commitOwner()
        maybeResolveBitmapLoadingStatus()
        publishBitmapFitState(null, bitmapArtboard.width, bitmapArtboard.height)
      }
    } finally {
      URL.revokeObjectURL(url)
    }
  }

  // Callers that draw right after resizing must `await tick()` first: the
  // canvas carries a reactive `width={bitmapCanvasWidth}` binding, and Chrome
  // resets the raster even on a same-value `width` assignment, so a pending
  // Svelte flush would wipe pixels drawn before it lands.
  function resizeBitmapCanvas(width: number, height: number) {
    if (!bitmapCanvas) return
    if (bitmapCanvas.width !== width) bitmapCanvas.width = width
    if (bitmapCanvas.height !== height) bitmapCanvas.height = height
    bitmapCanvasWidth = width
    bitmapCanvasHeight = height
    if (bitmapPaperScope?.view?.element) {
      const paperCanvas = bitmapPaperScope.view.element as HTMLCanvasElement
      paperCanvas.width = width
      paperCanvas.height = height
      bitmapPaperScope.view.viewSize = new bitmapPaperScope.Size(width, height)
    }
  }

  async function ensureBitmapPaperScope() {
    if (!bitmapCanvas) return undefined
    if (!bitmapPaperModule) {
      const imported = await import('paper/dist/paper-core')
      bitmapPaperModule = ('default' in imported ? imported.default : imported) as typeof paperCore
    }
    if (!bitmapPaperScope) {
      bitmapPaperScope = new bitmapPaperModule.PaperScope()
      const paperCanvas = document.createElement('canvas')
      paperCanvas.width = bitmapCanvas.width
      paperCanvas.height = bitmapCanvas.height
      bitmapPaperScope.setup(paperCanvas)
    }
    return bitmapPaperScope
  }

  async function refreshSoundWaveform(target: ScratchTarget) {
    const revision = assetPreviewRevision
    const loaded = target.sounds[selectedSoundIndex] ? await editableSoundBuffer(target, selectedSoundIndex) : undefined
    if (revision !== assetPreviewRevision) return
    soundWaveform = loaded ? wavPeaks(loaded.wav, 64) : []
    if (!previewAudio) soundPlayhead = 0
  }

  async function fillCurrentCostume() {
    if (!selectedTarget) return
    await captureCostumeHistory(selectedTarget, selectedTarget.currentCostume ?? 0)
    const index = selectedTarget.currentCostume ?? 0
    const width = selectedTarget.isStage ? 480 : 96
    const height = selectedTarget.isStage ? 360 : 96
    const paint = vectorPaintStyle(width, height, { x: 0, y: 0, width, height })
    const fill = `${paint.defs}<rect width="${width}" height="${height}" fill="${paint.fill}"/>`
    const svg = await svgWithInsertedShape(selectedTarget, index, fill, 'prepend')
    // Same-slot ordered write: route through the per-slot FIFO as `edit` so a
    // concurrent gated point/rotate/leaf preview/restore cannot interleave.
    // Bytes/patch are preserved verbatim (no runtime recompute) — only the
    // ordering is serialized.
    await enqueueVectorCostumeWrite(
      vectorWriteSlotKey(stableTargetId(selectedTarget), index),
      undefined,
      'edit',
      () =>
        vm.updateCostume(
          selectedTarget.name,
          index,
          {
            dataFormat: 'svg',
            rotationCenterX: selectedTarget.costumes[index]?.rotationCenterX ?? (selectedTarget.isStage ? 240 : 48),
            rotationCenterY: selectedTarget.costumes[index]?.rotationCenterY ?? (selectedTarget.isStage ? 180 : 48),
          },
          new TextEncoder().encode(svg),
        ),
    )
    status = 'Costume painted'
  }

  // Per-slot transaction sequencing for discrete saves (click stamp /
  // rect-oval-line drag commit): a move/resize pointerup owns a deferred
  // commit (`committing` + `applying`/`pending` quiescence + gated slot tails).
  // A stamp that only drains the slot FIFO can snapshot the tails before the
  // pointerup enqueues its final frame, then build on the pre-move base with
  // a stale CAS expected — the versioned write correctly rejects it and the
  // stamp is silently lost (queued move + stamp: 2 rects expected, 1 kept).
  // Waiting for drag quiescence first (same target/slot only, bounded) makes
  // the drain observe the full gesture; a second drain after quiescence
  // covers stragglers enqueued during the first wait. Late move frames can
  // therefore never land after the stamp, and the stamp's CAS expected (read
  // after this barrier, at svg/history time) matches its move-final base, so
  // external writes still fail closed via conflict instead of being clobbered.
  // Other targets/slots are never blocked; a switch/replacement/structural
  // shift aborts via the scope checks below.
  //
  // Fail-closed barrier (no silent commit): the probe below is per-slot
  // token/generation based, not a single replaceable global. Live drag
  // globals (`vectorDrag` etc.) are checked for this slot AND the versioned
  // gesture identities for this slot are checked, so replacing the global
  // with a new op on another slot never reports this slot idle while the
  // old gesture's final frame is still queued. The drain + cancel barrier
  // wait the captured exact final completion for this slot only. The total
  // budget is an explicit 2s: on expiry (or on barrier failure) this
  // returns `{ ok: false }` and callers abort WITHOUT writing
  // history/selection/bytes or a success status and WITHOUT a speculative
  // resume (no extra drain/write after the timeout). Never cancels gestures:
  // other-slot ops are untouched.
  // Fail-closed barrier probe (per-slot token/generation based, not a single
  // replaceable global). Hoisted as a named function so the test-only audit
  // hook (`__vectorGateDebug.slotBusy`) can observe the exact same reading
  // the barrier itself uses — no duplicated logic to drift.
  function isVectorSlotBarrierBusy(targetId: string, index: number): boolean {
    const move = vectorDrag
    const resize = vectorResizeDrag
    const rotate = vectorRotateDrag
    const point = vectorPathPointDrag
    const leaf = vectorLeafTranslateDrag
    if (
      move !== undefined &&
      move.targetId === targetId &&
      move.costumeIndex === index &&
      (move.applying || move.pendingClientX !== undefined || move.committing === true)
    ) return true
    if (
      resize !== undefined &&
      resize.targetId === targetId &&
      resize.costumeIndex === index &&
      (resize.applying || resize.pendingClientX !== undefined || resize.committing === true)
    ) return true
    if (
      rotate !== undefined &&
      rotate.targetId === targetId &&
      rotate.costumeIndex === index &&
      (rotate.applying || rotate.pendingClientX !== undefined || rotate.committing === true)
    ) return true
    if (
      point !== undefined &&
      point.targetId === targetId &&
      point.costumeIndex === index &&
      (point.applying || point.pendingClientX !== undefined || point.committing === true)
    ) return true
    if (
      leaf !== undefined &&
      leaf.targetId === targetId &&
      leaf.costumeIndex === index &&
      (leaf.applying || leaf.pendingClientX !== undefined || leaf.committing === true)
    ) return true
    // Versioned per-slot tokens: an in-flight gesture for this slot keeps
    // its identity until its commit/cancel settles, even after the globals
    // above were replaced by a new op on another slot. Checking the map
    // keeps the barrier closed across that replacement.
    for (const rec of vectorGestureIdentities.values()) {
      if (rec.targetId === targetId && rec.index === index) return true
    }
    // Exact slot execution: a write already running on this slot keeps the
    // barrier closed even when the globals were replaced and the gesture
    // identity was retired (e.g. a pointerup end whose bounded flag loop
    // expired while a >2s gated write was still running). Per-slot only:
    // other slots/targets stay responsive.
    if (isVectorSlotWritePending(vectorWriteSlotKey(targetId, index))) return true
    // Cancel restores (point/rotate/leaf Escape) run behind a shared
    // barrier promise: a stamp must observe the restored bytes, never the
    // pre-restore base.
    if (isVectorRotateCancelActive()) return true
    return false
  }
  // Bounded test-only log of discrete-save barrier verdicts (fail-closed
  // audit): each entry records which slot asked, whether it waited, and how
  // it resolved. Cap keeps memory bounded; tests read the tail.
  const vectorQuiescenceLog: Array<{ targetId: string; index: number; ok: boolean; reason?: 'timeout' | 'barrier'; at: number }> = []
  async function waitForVectorSlotQuiescence(
    targetId: string,
    index: number,
  ): Promise<{ ok: boolean; reason?: 'timeout' | 'barrier' }> {
    // Capture the exact final completion for this slot at settle time: the
    // per-slot FIFO tails snapshot plus the cancel barrier promise. Both
    // are awaited inside the helper; a straggler enqueued during the drain
    // is caught by the helper's post-drain recheck.
    const result = await waitForVectorSlotQuiescenceGate(
      {
        isBusy: () => isVectorSlotBarrierBusy(targetId, index),
        drain: () => drainTargetVectorWrites(targetId),
        waitCancel: () => waitForVectorRotateCancel(),
      },
      2000,
      10,
    )
    vectorQuiescenceLog.push({ targetId, index, ok: result.ok, reason: result.reason, at: Date.now() })
    if (vectorQuiescenceLog.length > 20) vectorQuiescenceLog.splice(0, vectorQuiescenceLog.length - 20)
    return result
  }

  async function saveVectorCostume(center?: { x: number; y: number }) {
    if (!selectedTarget) return
    // A text stamp never fires while the inline editor owns the draft: the
    // canvas click path opens the overlay instead of stamping, so a Save
    // click with an open draft must not stamp a second node (the draft still
    // commits exactly once on Escape/outside-click). Other shapes are
    // unaffected by the overlay.
    if (vectorShape === 'text' && isReshapeTextEditing()) {
      status = 'Vector text: editing in progress'
      return
    }
    // Transparent fill + transparent/width-0 stroke paints nothing: no
    // history, no node, no selection change (one stroke == at most one Undo
    // entry, here zero).
    if (isNewVectorShapeNoop(vectorShape)) {
      status = 'Vector shape: no change'
      return
    }
    // Owner + scope are captured synchronously, before the first await: a
    // target/costume switch, project replacement, or structural shift during
    // the delayed drain (or any later await) aborts silently below instead of
    // writing the shape into the newly selected asset with a success message.
    const owner = selectedTarget
    const targetId = stableTargetId(owner)
    const index = owner.currentCostume ?? 0
    const scope = captureDiscreteSaveScope(targetId, index)
    const scopeAlive = () => isDiscreteSaveScopeCurrent(scope, discreteSaveLiveOf(scope))
    // Order discrete stamps after in-flight previews on the same slot: a move
    // preview still gated in the per-slot FIFO would otherwise leave stale
    // live bytes here, so the stamp would build on the pre-move base and the
    // versioned CAS would correctly reject it (stamp silently lost). Drain
    // first keeps the stamp on the move-final base; CAS/history semantics and
    // per-target isolation are unchanged. Quiescence first: the pointerup
    // commit enqueues its final frame after mouse.up, so a drain snapshotted
    // too early misses it — the barrier waits for the exact in-flight
    // gesture/completion (per-slot tokens, not the replaceable globals),
    // drains the captured tails + cancel barrier, and rechecks stragglers.
    // Fail-closed: an explicit 2s timeout or a barrier failure aborts here
    // with an actionable status and no bytes/history/selection/success
    // status. No speculative resume after the timeout: this returns without
    // any further drain or write.
    const quiescence = await waitForVectorSlotQuiescence(targetId, index)
    if (!scopeAlive()) return
    if (!quiescence.ok) {
      if (scopeAlive()) status = 'Vector save: costume busy — try again'
      return
    }
    if (!scopeAlive()) return
    // Re-resolve the owner slot after the drain: `owner` is the pre-await
    // snapshot object, so its costume key may predate a move/drag commit
    // that landed during the drain. Reading peek/svg bytes through the stale
    // key would build the stamp on the pre-move base and overwrite the move
    // through a (correctly passing) CAS. The live target carries the same
    // stable id/slot (verified below), so only the key is refreshed — scope,
    // slot, and ordering are unchanged.
    const liveOwner = vectorWriteTargetById(targetId, owner.name) ?? owner
    if (stableTargetId(liveOwner) !== targetId) return
    // Peek/commit discipline: the pending entry is detached (no stack effects)
    // and is committed only after a successful CAS while the scope is still
    // current. The guarded commit drops stale completions with redo preserved,
    // so a concurrent edit's history entry is never deleted or restored.
    const pendingHistory = await peekCostumeHistory(liveOwner, index)
    if (!scopeAlive()) return
    const width = 480
    const height = 360
    const stampCenter = {
      x: typeof center?.x === 'number' && Number.isFinite(center.x) ? center.x : width / 2,
      y: typeof center?.y === 'number' && Number.isFinite(center.y) ? center.y : height / 2,
    }
    const stampBounds = vectorNewStampGradientBounds(vectorShape, width, height, center, vectorText)
    // Text stamps carry the toolbar font (normalized/clamped, multiline and
    // RTL aware) exactly like the inline insert path, instead of the legacy
    // hardcoded Sans Serif/40 single-line markup in `vectorShapeMarkup`.
    // Every other shape keeps its historical `vectorShapeMarkup` bytes.
    const shape = vectorShape === 'text'
      ? buildVectorTextMarkup({
        x: stampCenter.x,
        y: stampCenter.y,
        text: vectorText,
        paint: vectorPaintStyle(width, height, stampBounds),
        strokeColor: effectiveStrokeColor(),
        strokePaint: vectorStrokePaintStyle(width, height, stampBounds),
        strokeWidth,
        opacity: vectorOpacity,
        fontSize: clampVectorTextFontSize(vectorTextFontSize),
        fontFamily: normalizeVectorTextFontFamily(vectorTextFontFamily),
      })
      : vectorShapeMarkup({
        shape: vectorShape,
        width,
        height,
        center,
        paint: vectorPaintStyle(width, height, stampBounds),
        strokeColor: effectiveStrokeColor(),
        strokePaint: vectorStrokePaintStyle(width, height, stampBounds),
        strokeWidth,
        opacity: vectorOpacity,
        text: vectorText,
      })
    const svg = await svgWithInsertedShape(liveOwner, index, shape, 'append')
    if (!scopeAlive()) return
    const commit = await updateVectorCostumeFromEditor(liveOwner, index, svg, { quiet: true, isAlive: scopeAlive })
    if (commit.kind !== 'applied') {
      // Versioned CAS refusal (same-slot external meta/bytes update) keeps the
      // external: refresh + conflict status only while this scope is still
      // the live selection, never touching the new selection's status. A
      // superseded save (switch/epoch moved mid-write) stays fully silent.
      // No selection or history writes on either path. The own-bump tolerance
      // covers the self-inflicted generation bump on external conflicts (the
      // bump invalidates the just-peeked history before this check runs).
      if (scopeAlive() || (commit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(scope, discreteSaveLiveOf(scope)))) {
        await refreshVectorPreviewFromLive(targetId, liveOwner)
        reportVectorExternalConflict('Edit')
      }
      return
    }
    // The bytes landed on the correct (owner) slot; when the selection moved
    // mid-write the new selection owns the UI, so leave selection, status,
    // history, and preview untouched.
    if (!scopeAlive()) return
    if (pendingHistory) commitPaintHistory(pendingHistory)
    if (!scopeAlive()) return
    const committedSvg = commit.svgText
    vectorObjects = await paperVectorObjectList(committedSvg)
    if (!scopeAlive()) return
    await refreshCostumePreview(vectorWriteTargetById(targetId, owner.name) ?? owner)
    if (!scopeAlive()) return
    selectedVectorObjectIndex = vectorObjects.at(-1)?.index ?? selectedVectorObjectIndex
    selectedVectorObjectIndices = selectedVectorObjectIndex >= 0 ? [selectedVectorObjectIndex] : []
    status = 'Vector costume saved'
  }

  async function saveVectorBrushStroke(points: Array<{ x: number; y: number }>) {
    if (!selectedTarget || points.length === 0) return
    // Snapshot paint synchronously so the committed shape matches the pending
    // preview even if the user retunes colors mid-save. Closed-fill brush
    // uses the solid fill color (never the stroke color or gradient) and the
    // independent vector brush diameter (never the stroke width).
    const brushFill = fillTransparent ? 'none' : paintColor
    const brushWidth = normalizeVectorBrushSize(vectorBrushSize)
    const brushOpacity = vectorOpacity
    // Transparent fill paints nothing: no history, no node, no selection
    // change. This keeps one stroke == at most one Undo entry (here zero).
    if (brushFill.trim().toLowerCase() === 'none' || brushFill.trim().toLowerCase() === 'transparent') return
    const clampedOpacity = Math.max(0, Math.min(1, brushOpacity / 100))
    let shape: string
    if (points.length === 1) {
      const first = points[0]!
      shape = `<circle cx="${first.x}" cy="${first.y}" r="${Math.max(1, brushWidth) / 2}" fill="${brushFill}" stroke="none" opacity="${clampedOpacity}"/>`
    } else {
      const pathData = buildVectorBrushFillPathData(points, brushWidth)
      // Degenerate input (all points filtered) builds nothing: no-op without history.
      if (!pathData) return
      shape = vectorBrushFillMarkup({ pathData, fill: brushFill, opacity: brushOpacity })
    }
    const owner = selectedTarget
    const targetId = stableTargetId(owner)
    const index = owner.currentCostume ?? 0
    const scope = captureDiscreteSaveScope(targetId, index)
    const scopeAlive = () => isDiscreteSaveScopeCurrent(scope, discreteSaveLiveOf(scope))
    // DOM insert + non-destructive same-color union as a single history entry.
    // The doc comes from currentSvgDocument (already sanitize-first via
    // svgTextForVectorEditor), the brush markup is generated numbers + a hex
    // fill, and mergeBrushElementWithSiblings sanitizes every Paper.js
    // import/export. Any merge refusal or failure leaves the freshly inserted
    // brush node in place; unrelated siblings keep identity and order.
    const loaded = await currentSvgDocument(owner, index)
    if (!scopeAlive()) return
    // Exactly one history entry per committed stroke: peek once here, then
    // insert + merge as a single DOM change, committed only after a successful
    // CAS while the scope is still current (both branches share this peek, so
    // Undo restores pre-stroke bytes; a concurrent edit's entry is never
    // deleted or restored).
    const pendingHistory = await peekCostumeHistory(owner, index)
    if (!scopeAlive()) return
    if (!loaded) {
      const svg = await svgWithInsertedShape(owner, index, shape, 'append')
      if (!scopeAlive()) return
      const liveOwner = vectorWriteTargetById(targetId, owner.name) ?? owner
      if (stableTargetId(liveOwner) !== targetId) return
      const commit = await updateVectorCostumeFromEditor(liveOwner, index, svg, { quiet: true, isAlive: scopeAlive })
      if (commit.kind !== 'applied') {
        if (scopeAlive() || (commit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(scope, discreteSaveLiveOf(scope)))) {
          await refreshVectorPreviewFromLive(targetId, liveOwner)
          reportVectorExternalConflict('Edit')
        }
        return
      }
      if (!scopeAlive()) return
      if (pendingHistory) commitPaintHistory(pendingHistory)
      if (!scopeAlive()) return
      const committedSvg = commit.svgText
      vectorObjects = await paperVectorObjectList(committedSvg)
      if (!scopeAlive()) return
      await refreshCostumePreview(vectorWriteTargetById(targetId, owner.name) ?? owner)
      if (!scopeAlive()) return
      const previous = selectedVectorObjectIndex
      selectedVectorObjectIndex = vectorObjects.at(-1)?.index ?? selectedVectorObjectIndex
      selectedVectorObjectIndices = selectedVectorObjectIndex >= 0 ? [selectedVectorObjectIndex] : []
      if (previous !== selectedVectorObjectIndex) clearReshapeSelection()
      try {
        rememberCommittedReshapeSelection(targetId, index, new TextEncoder().encode(committedSvg))
      } catch {
        // Best-effort only.
      }
      status = 'Vector brush stroke saved'
      return
    }
    const { doc, svg } = loaded
    const holder = new DOMParser().parseFromString(
      `<svg xmlns="http://www.w3.org/2000/svg">${shape}</svg>`,
      'image/svg+xml',
    ).documentElement
    const brushNode = holder.firstElementChild ? doc.importNode(holder.firstElementChild, true) as Element : undefined
    if (!brushNode) return
    svg.appendChild(brushNode)
    try {
      const scope = await ensureVectorPaperScope()
      // Fail-closed union: touching same-color siblings unite at the brush
      // position; gradients, transparency, strokes, groups, cross-parent art,
      // far shapes and Z-order blockers are left untouched with zero node loss.
      mergeBrushElementWithSiblings(scope as unknown as paper.PaperScope, brushNode)
    } catch {
      // Keep the inserted brush; a merge helper failure must never lose art.
    }
    if (!scopeAlive()) return
    const liveOwner = vectorWriteTargetById(targetId, owner.name) ?? owner
    if (stableTargetId(liveOwner) !== targetId) return
    const commit = await updateVectorCostumeFromEditor(liveOwner, index, new XMLSerializer().serializeToString(doc.documentElement), { quiet: true, isAlive: scopeAlive })
    if (commit.kind !== 'applied') {
      if (scopeAlive() || (commit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(scope, discreteSaveLiveOf(scope)))) {
        await refreshVectorPreviewFromLive(targetId, liveOwner)
        reportVectorExternalConflict('Edit')
      }
      return
    }
    if (!scopeAlive()) return
    if (pendingHistory) commitPaintHistory(pendingHistory)
    if (!scopeAlive()) return
    const nextSvg = commit.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (!scopeAlive()) return
    await refreshCostumePreview(vectorWriteTargetById(targetId, owner.name) ?? owner)
    if (!scopeAlive()) return
    const previous = selectedVectorObjectIndex
    selectedVectorObjectIndex = vectorObjects.at(-1)?.index ?? selectedVectorObjectIndex
    selectedVectorObjectIndices = selectedVectorObjectIndex >= 0 ? [selectedVectorObjectIndex] : []
    // The merged node replaces the brush outline, so a stale reshape point
    // index into the old outline must not survive (it would delete/move the
    // wrong point). A fresh selection starts with no point selected.
    clearReshapeSelection()
    try {
      rememberCommittedReshapeSelection(targetId, index, new TextEncoder().encode(nextSvg))
    } catch {
      // Best-effort only.
    }
    status = 'Vector brush stroke saved'
  }

  async function saveVectorShapeInRect(shape: 'rect' | 'oval' | 'line', rect: { x: number; y: number; width: number; height: number }) {
    if (!selectedTarget) return
    // Same no-op rule as click stamps: an invisible outline/fill combination
    // writes no history entry.
    if (isNewVectorShapeNoop(shape)) {
      status = 'Vector shape: no change'
      return
    }
    // Owner + scope captured synchronously (see saveVectorCostume): any
    // target/costume switch, project replacement, or structural shift during
    // an await aborts silently instead of stamping the new selection.
    const owner = selectedTarget
    const targetId = stableTargetId(owner)
    const index = owner.currentCostume ?? 0
    const scope = captureDiscreteSaveScope(targetId, index)
    const scopeAlive = () => isDiscreteSaveScopeCurrent(scope, discreteSaveLiveOf(scope))
    // Same ordering as click stamps: drain in-flight previews on this slot
    // before peeking history / reading live bytes, so a rect dragged during
    // the deferred move window builds on the move-final base instead of the
    // pre-move base (CAS would otherwise keep the move and drop the stamp).
    // Quiescence first for the same pointerup-late-frame reason as stamps.
    // Fail-closed like click stamps: explicit 2s timeout or barrier failure
    // aborts with an actionable status and no bytes/history/selection or
    // success status, and never resumes speculatively after the timeout.
    const quiescence = await waitForVectorSlotQuiescence(targetId, index)
    if (!scopeAlive()) return
    if (!quiescence.ok) {
      if (scopeAlive()) status = 'Vector save: costume busy — try again'
      return
    }
    if (!scopeAlive()) return
    // Same stale-snapshot guard as click stamps: re-resolve the slot after
    // the drain so peek/svg read the move-final key, never the pre-move one.
    const liveOwner = vectorWriteTargetById(targetId, owner.name) ?? owner
    if (stableTargetId(liveOwner) !== targetId) return
    const pendingHistory = await peekCostumeHistory(liveOwner, index)
    if (!scopeAlive()) return
    const width = 480
    const height = 360
    const dragBounds = vectorDragGradientBounds(rect)
    const paint = vectorPaintStyle(width, height, dragBounds)
    const markup = vectorShapeInRectMarkup({ shape, rect, paint, strokeColor: effectiveStrokeColor(), strokePaint: vectorStrokePaintStyle(width, height, dragBounds), strokeWidth, opacity: vectorOpacity })
    const svg = await svgWithInsertedShape(liveOwner, index, markup, 'append')
    if (!scopeAlive()) return
    const commit = await updateVectorCostumeFromEditor(liveOwner, index, svg, { quiet: true, isAlive: scopeAlive })
    if (commit.kind !== 'applied') {
      if (scopeAlive() || (commit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(scope, discreteSaveLiveOf(scope)))) {
        await refreshVectorPreviewFromLive(targetId, liveOwner)
        reportVectorExternalConflict('Edit')
      }
      return
    }
    if (!scopeAlive()) return
    if (pendingHistory) commitPaintHistory(pendingHistory)
    if (!scopeAlive()) return
    const committedSvg = commit.svgText
    vectorObjects = await paperVectorObjectList(committedSvg)
    if (!scopeAlive()) return
    await refreshCostumePreview(vectorWriteTargetById(targetId, owner.name) ?? owner)
    if (!scopeAlive()) return
    selectedVectorObjectIndex = vectorObjects.at(-1)?.index ?? selectedVectorObjectIndex
    selectedVectorObjectIndices = selectedVectorObjectIndex >= 0 ? [selectedVectorObjectIndex] : []
    // New shape owns the selection with no point selected (stale reshape on
    // the old unit must not survive). Post-shape full object selection becomes
    // the prior for the next delete/redo (gap oracle: rect selected, not wave).
    clearReshapeSelection()
    try {
      rememberCommittedReshapeSelection(targetId, index, new TextEncoder().encode(committedSvg))
    } catch {
      // Best-effort only.
    }
    status = 'Vector shape saved'
  }

  // Vector fill tool (scratch-paint `fill-tool.js` behavior, reimplemented
  // from behavior notes without copying upstream source).
  //
  // - Hit test is fill + stroke only (no segments/curves) with the shared
  //   zoom-aware select tolerance (2 screen px). Only a Paper hit becomes a
  //   body target: a miss is a no-op with no selection change, no history
  //   entry, and no redo-stack disturbance. There is deliberately no
  //   bounding-box fallback here: the hole interior of a compound path (donut
  //   hole) misses in stock Paper.js yet sits inside the unit bbox, so a bbox
  //   fallback would recolor the whole parent.
  // - Stock Paper.js never reports hole children, so holes are identified
  //   geometrically (`paperVectorHoleTargetAtPoint` in `paper-vector.ts`):
  //   real compound children / winding / `fill-rule` (`evenodd`/`nonzero`)
  //   via Paper's own `contains`, top-down document order, ancestor
  //   transforms baked in, clip/mask declined. Colored hole clicks add a new
  //   fill-only shape covering only the hole (Scratch parity); transparent
  //   holes stay a no-op. Overlap / nesting / degenerate / boundary cases
  //   stay fail-closed with an honest status and no history.
  // - The `match` gate (`vector-fill-hover.ts`, reference parity): a fill hit
  //   on a plain path needs an existing fill, a closed contour, or an
  //   almost-closed contour; stroke hits and point-text always qualify.
  // - Commits are side-scoped: a fill hit recolors only the fill side, a
  //   stroke hit only the outline side (never adds an outline to a
  //   non-outlined shape or vice versa). Same-value clicks stay history-free
  //   via the existing style pipeline. Hole overlays commit exactly one
  //   history entry and leave selection cleared (reference `fill-tool.js`
  //   `handleMouseUp` never selects + `fill-mode.jsx` clears on activate);
  //   every no-op leaves history, selection, and the redo stack untouched.
  // - Sanitizer / clip-mask / ancestor-transform handling rides the shared
  //   Paper import (`bakedUnitClone` + fragment sanitizer in
  //   `paper-vector.ts`); `editableVectorUnits` already excludes
  //   clipPath/mask/defs companions. Hole `d` is Paper-exported geometry
  //   (validated safe subset) and paint comes only from the toolbar via
  //   `vectorPaintStyle` (never untrusted `url(#...)`).
  // - Hover preview (no commit): `BitmapEditor.svelte` resolves the same
  //   target through `resolveFillHoverPreview` + `createFillHoverPreviewTracker`
  //   (`vector-fill-hover-preview.ts`, stale drops) and renders a draw-only
  //   snapshot via `VectorFillHoverPreview.svelte` /
  //   `buildFillHoverPreviewSnapshot` (`vector-fill-hover-overlay.ts`). The
  //   live SVG / VM / history are never touched by hover; commits stay here
  //   in `fillVectorObjectAtPoint` / `editVectorObject('style', ...)`.
  function isSafeHoleSiblingTransform(transform: string): boolean {
    if (!transform) return true
    if (transform.length > 2000) return false
    if (/[<>&"']/.test(transform)) return false
    if (/url\s*\(/i.test(transform)) return false
    if (/script|javascript:|expression|behaviour/i.test(transform)) return false
    if (!/^[a-z0-9\s.,+\-()]*$/i.test(transform)) return false
    return true
  }
  async function fillVectorObjectAtPoint(point: { x: number; y: number }) {
    if (!selectedTarget) return
    const costumeIndex = selectedTarget.currentCostume ?? 0
    const loaded = await currentSvgDocument(selectedTarget, costumeIndex)
    if (!loaded) return
    const units = editableVectorUnits(loaded.svg)
    if (units.length === 0) return
    const tolerance = resolveVectorHitTolerance()
    let target: Awaited<ReturnType<typeof paperVectorFillTargetAtPoint>>
    try {
      target = await paperVectorFillTargetAtPoint(units, point, tolerance)
    } catch {
      return
    }
    let holeProbe: Awaited<ReturnType<typeof paperVectorHoleTargetAtPoint>>
    try {
      holeProbe = await paperVectorHoleTargetAtPoint(units, point, tolerance)
    } catch {
      return
    }
    if (holeProbe.kind === 'ambiguous' || holeProbe.kind === 'unsupported') {
      status = `Vector fill: no change (${holeProbe.reason})`
      return
    }
    if (!target) {
      if (holeProbe.kind === 'hole') {
        if (isFillInvisible(fillTransparent, secondaryTransparent, paintGradient)) {
          status = 'Vector fill: no change (transparent holes stay empty)'
          return
        }
        await fillVectorHoleOverlayAtPoint(loaded.doc, loaded.svg, units, point, holeProbe.target, costumeIndex)
        return
      }
      status = 'Vector fill: no change (no shape under the pointer)'
      return
    }
    if (holeProbe.kind === 'hole' && holeProbe.target.parentIndex > target.index) {
      status = 'Vector fill: no change (hole overlaps another shape, left unchanged)'
      return
    }
    const accepted = shouldAcceptFillHoverHit({
      kind: target.isText ? 'text' : 'path',
      hasFill: target.hasFill,
      closed: target.closed,
      almostClosed: target.almostClosed,
      hitType: target.hitType,
    })
    if (!accepted) {
      status = 'Vector fill: no change (open paths take only outline color)'
      return
    }
    const hole = isHoleFillHit({
      parentIsCompoundPath: target.parentIsCompoundPath,
      childArea: target.childArea ?? Number.NaN,
      hitType: target.hitType,
    })
    const decision = decideFillHoverTarget({
      accepted: true,
      isHole: hole,
      parentIsCompoundPath: target.parentIsCompoundPath,
      hitType: target.hitType,
      fillTransparent,
    })
    if (decision.action === 'noop-transparent-hole' || decision.action === 'ignore') {
      status = 'Vector fill: no change (transparent holes stay empty)'
      return
    }
    if (decision.action === 'preview-hole-overlay') {
      if (isFillInvisible(fillTransparent, secondaryTransparent, paintGradient)) {
        status = 'Vector fill: no change (transparent holes stay empty)'
        return
      }
      if (holeProbe.kind === 'hole') {
        await fillVectorHoleOverlayAtPoint(loaded.doc, loaded.svg, units, point, holeProbe.target, costumeIndex)
        return
      }
      status = 'Vector fill: no change (hole geometry is unavailable, left unchanged)'
      return
    }
    const fillPrevIndex = selectedVectorObjectIndex
    const fillPrevIndices = [...selectedVectorObjectIndices]
    selectedVectorObjectIndex = target.index
    selectedVectorObjectIndices = [target.index]
    await editVectorObject('style', point, decision.property)
    // Stale-scope guard: `editVectorObject` clears on success and restores
    // `fillPrev*` on known no-ops; a scope death between would otherwise leak
    // the provisional `target.index`. Fail closed to the entry selection.
    if (selectedVectorObjectIndex === target.index && selectedVectorObjectIndices.length === 1 && selectedVectorObjectIndices[0] === target.index) {
      // Distinguish success (already cleared to -1 above, so this branch is
      // scope-death/no-commit only): restore entry selection to avoid
      // accidentally selecting on a failed fill.
      selectedVectorObjectIndex = fillPrevIndex
      selectedVectorObjectIndices = [...fillPrevIndices]
      clearReshapeSelection()
    }
  }
  async function fillVectorHoleOverlayAtPoint(
    doc: Document,
    svg: Element,
    units: Element[],
    point: { x: number; y: number },
    hole: { parentIndex: number; holePathData: string; holeDocumentBounds: { x: number; y: number; width: number; height: number }; parentTransform: string },
    costumeIndex: number,
  ) {
    if (!selectedTarget) return
    const source = units[hole.parentIndex]
    if (!source) {
      status = 'Vector fill: no change (hole source is gone, left unchanged)'
      return
    }
    if (!isHolePathDataSafe(hole.holePathData)) {
      status = 'Vector fill: no change (hole geometry failed validation, left unchanged)'
      return
    }
    if (!isSafeHoleSiblingTransform(hole.parentTransform)) {
      status = 'Vector fill: no change (hole transform is unsupported, left unchanged)'
      return
    }
    if (!(hole.holeDocumentBounds.width > 0 && hole.holeDocumentBounds.height > 0)) {
      status = 'Vector fill: no change (degenerate hole, left unchanged)'
      return
    }
    if (isFillInvisible(fillTransparent, secondaryTransparent, paintGradient)) {
      status = 'Vector fill: no change (transparent holes stay empty)'
      return
    }
    let holeBoundsParent = { x: hole.holeDocumentBounds.x, y: hole.holeDocumentBounds.y, width: hole.holeDocumentBounds.width, height: hole.holeDocumentBounds.height }
    try {
      const ancestors = ancestorWorldMatrix(source)
      if (ancestors) {
        const inverse = invertVectorMatrix(ancestors)
        const corners = [
          transformVectorPoint(inverse, hole.holeDocumentBounds.x, hole.holeDocumentBounds.y),
          transformVectorPoint(inverse, hole.holeDocumentBounds.x + hole.holeDocumentBounds.width, hole.holeDocumentBounds.y),
          transformVectorPoint(inverse, hole.holeDocumentBounds.x + hole.holeDocumentBounds.width, hole.holeDocumentBounds.y + hole.holeDocumentBounds.height),
          transformVectorPoint(inverse, hole.holeDocumentBounds.x, hole.holeDocumentBounds.y + hole.holeDocumentBounds.height),
        ]
        if (corners.some((corner) => !Number.isFinite(corner.x) || !Number.isFinite(corner.y))) {
          status = 'Vector fill: no change (hole transform is unsupported, left unchanged)'
          return
        }
        const left = Math.min(...corners.map((corner) => corner.x))
        const top = Math.min(...corners.map((corner) => corner.y))
        const right = Math.max(...corners.map((corner) => corner.x))
        const bottom = Math.max(...corners.map((corner) => corner.y))
        holeBoundsParent = { x: left, y: top, width: Math.max(0, right - left), height: Math.max(0, bottom - top) }
      }
    } catch {
      status = 'Vector fill: no change (hole transform is unsupported, left unchanged)'
      return
    }
    if (!(holeBoundsParent.width > 0 && holeBoundsParent.height > 0)) {
      status = 'Vector fill: no change (degenerate hole, left unchanged)'
      return
    }
    const gradientCenter = documentPointToLocalGradientPoint(source, point)
    const paint = vectorPaintStyle(480, 360, holeBoundsParent, gradientCenter)
    if (!paint.fill || paint.fill === 'none') {
      status = 'Vector fill: no change (transparent holes stay empty)'
      return
    }
    const holeOwner = selectedTarget
    const holeTargetId = stableTargetId(holeOwner)
    const holeScope = captureDiscreteSaveScope(holeTargetId, costumeIndex)
    const holeScopeAlive = () => isDiscreteSaveScopeCurrent(holeScope, discreteSaveLiveOf(holeScope))
    const pendingHistory = await peekCostumeHistory(holeOwner, costumeIndex)
    if (!holeScopeAlive()) return
    if (!pendingHistory) return
    // Reference `fill-tool.js` never selects: overwrite the peek snapshot with
    // the actual empty set so undo restores cleared selection (redo path in
    // `currentHistoryEntry` then also resolves empty via the empty prior).
    attachEmptyFillSelectionToHistoryEntry(pendingHistory)
    const overlay = doc.createElementNS('http://www.w3.org/2000/svg', 'path')
    overlay.setAttribute('d', hole.holePathData)
    if (hole.parentTransform) overlay.setAttribute('transform', hole.parentTransform)
    overlay.setAttribute('fill', paint.fill)
    overlay.setAttribute('stroke', 'none')
    overlay.setAttribute('opacity', String(Math.max(0, Math.min(1, vectorOpacity / 100))))
    try {
      appendVectorPaintDefs(svg, doc, paint.defs)
      const parent = source.parentElement ?? svg
      parent.insertBefore(overlay, source.nextSibling)
    } catch {
      status = 'Vector fill: no change (hole could not be placed, left unchanged)'
      return
    }
    if (!holeScopeAlive()) return
    const holeLiveOwner = vectorWriteTargetById(holeTargetId, holeOwner.name) ?? holeOwner
    if (stableTargetId(holeLiveOwner) !== holeTargetId) return
    const holeCommit = await updateVectorCostumeFromEditor(holeLiveOwner, costumeIndex, new XMLSerializer().serializeToString(doc.documentElement), { quiet: true, isAlive: holeScopeAlive })
    if (holeCommit.kind !== 'applied') {
      if (holeScopeAlive() || (holeCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(holeScope, discreteSaveLiveOf(holeScope)))) {
        await refreshVectorPreviewFromLive(holeTargetId, holeLiveOwner)
        reportVectorExternalConflict('Edit')
      }
      return
    }
    if (!holeScopeAlive()) return
    commitPaintHistory(pendingHistory)
    if (!holeScopeAlive()) return
    const nextSvg = holeCommit.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (!holeScopeAlive()) return
    // Reference parity: successful fills never select (both hole overlays and
    // body recolors). Clear to the empty set so the hidden SVG view shows no
    // blue box and Delete stays disabled. No-op/failure paths above return
    // early without touching selection, so unrelated UI selection survives.
    selectedVectorObjectIndex = -1
    selectedVectorObjectIndices = []
    clearReshapeSelection()
    await refreshCostumePreview(vectorWriteTargetById(holeTargetId, holeOwner.name) ?? holeOwner)
    if (!holeScopeAlive()) return
    try {
      // Reference parity: both the immediate selection and the committed
      // prior are the empty set (no blue box; Delete disabled). Undo/redo
      // therefore restore cleared selection (V7 rect/brush priors untouched).
      rememberEmptyFillCommittedSelection(holeTargetId, costumeIndex, new TextEncoder().encode(nextSvg))
    } catch {
      // Best-effort only.
    }
    status = 'Vector fill: hole filled'
  }

  async function eraseVectorStroke(points: Array<{ x: number; y: number }>) {
    if (!selectedTarget || points.length === 0) return
    const eraseOwner = selectedTarget
    const eraseTargetId = stableTargetId(eraseOwner)
    const index = eraseOwner.currentCostume ?? 0
    const eraseScope = captureDiscreteSaveScope(eraseTargetId, index)
    const eraseScopeAlive = () => isDiscreteSaveScopeCurrent(eraseScope, discreteSaveLiveOf(eraseScope))
    const loaded = await currentSvgDocument(eraseOwner, index)
    if (!eraseScopeAlive()) return
    if (!loaded) return
    const { doc, svg } = loaded
    const children = editableVectorUnits(svg)
    if (children.length === 0) return
    const pendingHistory = await peekCostumeHistory(eraseOwner, index)
    if (!eraseScopeAlive()) return
    const scope = await ensureVectorPaperScope()
    if (!eraseScopeAlive()) return
    const selectedIndices = normalizedVectorSelection(children.length)
    const result = eraseVectorStrokeFromSvg(scope, svg, children, points, vectorEraserSize, selectedIndices)
    if (!result.erased) return
    if (!eraseScopeAlive()) return
    const eraseLiveOwner = vectorWriteTargetById(eraseTargetId, eraseOwner.name) ?? eraseOwner
    if (stableTargetId(eraseLiveOwner) !== eraseTargetId) return
    const eraseCommit = await updateVectorCostumeFromEditor(eraseLiveOwner, index, new XMLSerializer().serializeToString(doc.documentElement), { quiet: true, isAlive: eraseScopeAlive })
    if (eraseCommit.kind !== 'applied') {
      if (eraseScopeAlive() || (eraseCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(eraseScope, discreteSaveLiveOf(eraseScope)))) {
        await refreshVectorPreviewFromLive(eraseTargetId, eraseLiveOwner)
        reportVectorExternalConflict('Edit')
      }
      return
    }
    if (!eraseScopeAlive()) return
    if (pendingHistory) commitPaintHistory(pendingHistory)
    if (!eraseScopeAlive()) return
    if (!result.erasedFromSelection) {
      selectedVectorObjectIndex = -1
      selectedVectorObjectIndices = []
    }
    const nextSvg = eraseCommit.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (!eraseScopeAlive()) return
    selectedVectorObjectIndices = selectedVectorObjectIndices.filter((item) => vectorObjects.some((object) => object.index === item))
    selectedVectorObjectIndex = selectedVectorObjectIndices.at(-1) ?? -1
    if (selectedVectorObjectIndex < 0) clearReshapeSelection()
    await refreshCostumePreview(vectorWriteTargetById(eraseTargetId, eraseOwner.name) ?? eraseOwner)
    if (!eraseScopeAlive()) return
    try {
      rememberCommittedReshapeSelection(eraseTargetId, index, new TextEncoder().encode(nextSvg))
    } catch {
      // Best-effort only.
    }
    status = 'Vector eraser applied'
  }

  async function svgWithInsertedShape(target: ScratchTarget, index: number, shape: string, mode: 'append' | 'prepend') {
    const costume = target.costumes[index]
    const width = 480
    const height = 360
    const key = costume?.md5ext ?? costume?.assetId
    const bytes = key && costume?.dataFormat === 'svg' ? await vm.loadAsset(key, 'svg') : undefined
    const existing = bytes && costume ? svgTextForVectorEditor(new TextDecoder().decode(bytes), target, costume) : ''
    if (/<\/svg\s*>/i.test(existing)) {
      return mode === 'prepend'
        ? existing.replace(/(<svg\b[^>]*>)/i, `$1${shape}`)
        : existing.replace(/<\/svg\s*>/i, `${shape}</svg>`)
    }
    return `<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}" viewBox="0 0 ${width} ${height}">${shape}</svg>`
  }

  function vectorRuntimeCostume(svgText: string, target: ScratchTarget, index: number) {
    const costume = target.costumes[index]
    if (target.isStage) {
      return {
        svgText,
        patch: {
          dataFormat: 'svg',
          rotationCenterX: 240,
          rotationCenterY: 180,
        },
      }
    }

    const doc = new DOMParser().parseFromString(svgText, 'image/svg+xml')
    const svg = doc.documentElement
    if (svg.nodeName.toLowerCase() !== 'svg') {
      return {
        svgText,
        patch: {
          dataFormat: 'svg',
          bitmapResolution: 1,
          rotationCenterX: costume?.rotationCenterX ?? 48,
          rotationCenterY: costume?.rotationCenterY ?? 50,
        },
      }
    }

    const bounds = editableSvgChildren(svg)
      .map((child) => vectorObjectBounds(child))
      .filter((bound) => bound.width > 0 || bound.height > 0)
    const stageCenterX = 240
    const stageCenterY = 180
    const left = bounds.length > 0 ? Math.floor(Math.min(...bounds.map((bound) => bound.x)) - 2) : stageCenterX - 48
    const top = bounds.length > 0 ? Math.floor(Math.min(...bounds.map((bound) => bound.y)) - 2) : stageCenterY - 50
    const right = bounds.length > 0 ? Math.ceil(Math.max(...bounds.map((bound) => bound.x + bound.width)) + 2) : left + 96
    const bottom = bounds.length > 0 ? Math.ceil(Math.max(...bounds.map((bound) => bound.y + bound.height)) + 2) : top + 100
    const width = Math.max(1, right - left)
    const height = Math.max(1, bottom - top)
    svg.setAttribute('width', String(width))
    svg.setAttribute('height', String(height))
    svg.setAttribute('viewBox', `${left} ${top} ${width} ${height}`)
    const rotationCenterX = stageCenterX - left
    const rotationCenterY = stageCenterY - top
    return {
      svgText: new XMLSerializer().serializeToString(svg),
      patch: {
        dataFormat: 'svg',
        bitmapResolution: 1,
        rotationCenterX,
        rotationCenterY,
        width,
        height,
      } as Partial<ScratchCostume> & { width: number; height: number },
    }
  }

  // Versioned commit: gesture commits compare against the gesture snapshot's
  // `last` seq (press-time base, then each successful preview's returned seq).
  // After a conflict the gesture stays marked and later commits never retake
  // the seq to force the write. Discrete edits (no gesture) capture a fresh
  // versioned identity and use the same CAS; on conflict the external is kept,
  // preview residue is refreshed from live, and the just-peeked history is
  // invalidated via a generation bump (no usable history). Stable-id only,
  // structure-epoch guarded, format priority (`patch.dataFormat ?? live`)
  // preserved by the VM. Bitmap/sound paths are untouched. Direct
  // `vm.updateCostume` bypassing the slot queue is unsupported (boundary).
  async function updateVectorCostumeFromEditor(
    target: ScratchTarget,
    index: number,
    svgText: string,
    writeOpts?: { gestureId?: VectorWriteGesture; kind?: VectorWriteKind; expectedStructureEpoch?: number; quiet?: boolean; isAlive?: () => boolean },
  ): Promise<VectorEditorCommitResult> {
    const runtime = vectorRuntimeCostume(svgText, target, index)
    const kind = writeOpts?.kind ?? 'edit'
    const targetId = stableTargetId(target)
    const slotKey = vectorWriteSlotKey(targetId, index)
    const bytes = new TextEncoder().encode(runtime.svgText)
    const patch = runtime.patch
    const gesture = writeOpts?.gestureId
    const quiet = writeOpts?.quiet === true
    // Discrete expected is captured synchronously before the first await so an
    // external write slipping in before enqueue is still detected by the VM.
    const discreteExpected: VectorSlotIdentity | undefined = gesture ? undefined : vectorSlotIdentityOf(readLiveSlotIdentity(targetId, index))
    // Explicit discrete-save VM selection precondition (no gesture only):
    // stable target id exact + selected index + VM project generation +
    // monotonic selection epoch, all captured synchronously before the first
    // await. Previews, cancel restores, history, and external plugin calls
    // never pass it (legacy behavior unchanged). The VM re-validates it at
    // enqueue, at queue start, and after `storeAsset` immediately before the
    // atomic mutation; a target/costume switch (including away-and-back via
    // the epoch), a reload reusing the same id (via the generation), or a
    // reorder moving the selected index aborts the bytes themselves with
    // `reason: 'superseded'`, which the caller consumes silently.
    type DiscreteSelectionPrecondition = { targetId: string; index: number; projectGeneration?: number; selectionEpoch?: number }
    const discreteSelection: DiscreteSelectionPrecondition | undefined = (() => {
      if (gesture) return undefined
      let projectGeneration: number | undefined
      try {
        projectGeneration = (vm as unknown as { getProjectGeneration?: () => number }).getProjectGeneration?.()
      } catch {
        projectGeneration = undefined
      }
      let selectionEpoch: number | undefined
      try {
        selectionEpoch = (vm as unknown as { getSelectionEpoch?: () => number }).getSelectionEpoch?.()
      } catch {
        selectionEpoch = undefined
      }
      const out: DiscreteSelectionPrecondition = { targetId, index }
      if (typeof projectGeneration === 'number' && Number.isInteger(projectGeneration)) out.projectGeneration = projectGeneration
      if (typeof selectionEpoch === 'number' && Number.isInteger(selectionEpoch)) out.selectionEpoch = selectionEpoch
      return out
    })()
    let outcome: { applied: boolean; conflict: boolean; superseded: boolean; current?: VectorSlotIdentity } = { applied: false, conflict: false, superseded: false }
    // Superseded before execution: the owner scope died while queued (a
    // target/costume switch, replacement, or structural shift landed inside
    // the save window). Skipped without touching the VM so a delayed save can
    // never steer bytes into the newly selected asset; the caller stays
    // silent (no selection/status/history writes) via the skipped path below.
    let supersededBeforeWrite = false
    await enqueueVectorCostumeWrite(
      slotKey,
      gesture,
      kind,
      async () => {
        if (writeOpts?.isAlive && !writeOpts.isAlive()) {
          supersededBeforeWrite = true
          return undefined
        }
        const writer = vm as unknown as {
          updateCostumeIfMatch?: (
            t: string, i: number, e: VectorSlotIdentity | undefined,
            p: Partial<ScratchCostume>, d?: Uint8Array,
            s?: DiscreteSelectionPrecondition,
          ) => Promise<{ applied: boolean; reason?: 'superseded' | 'conflict'; current?: VectorSlotIdentity }>
        }
        const live = vectorWriteTargetById(targetId, target.name) ?? target
        if (stableTargetId(live) !== targetId) throw new Error('commit target gone')
        const expected: VectorSlotIdentity | undefined = gesture ? vectorCasExpectedOf(vectorGestureRecord(gesture)) : discreteExpected ? { ...discreteExpected } : undefined
        if (typeof writer.updateCostumeIfMatch === 'function') {
          const result = await writer.updateCostumeIfMatch(live.id ?? targetId, index, expected, patch, bytes, discreteSelection)
          if (result.applied) {
            outcome = { applied: true, conflict: false, superseded: false, current: result.current }
            if (gesture) noteVectorPreviewApplied(gesture, result.current)
            // Own-write adoption uses the CAS `result.current` seq only (never
            // a fresh external read): a same-bytes/metadata-only or rename
            // external that lands between the mutation and a fresh read would
            // otherwise be adopted into `known` and hidden, breaking
            // fail-closed Undo (must stay `External costume change kept`).
            // When the backend returns no identity, leave `known` untouched so
            // the next Undo fails closed instead of silently deleting it.
            else if (result.current) rememberPaintKnown(targetId, index, result.current)
          } else if ((result as { reason?: string }).reason === 'superseded') {
            // VM selection/generation guard (explicit discrete only): silent,
            // no generation bump, no history — the new selection owns the UI.
            outcome = { applied: false, conflict: false, superseded: true, current: result.current }
          } else {
            outcome = { applied: false, conflict: true, superseded: false, current: result.current }
            if (gesture) markVectorGestureConflicted(gesture)
            else bumpPaintGenerationForExternal()
          }
          return result
        }
        await vm.updateCostume(live.name, index, patch, bytes)
        outcome = { applied: true, conflict: false, superseded: false }
        if (!gesture) rememberPaintKnown(targetId, index, readLiveSlotIdentity(targetId, index))
      },
      writeOpts?.expectedStructureEpoch,
    )
    const readLiveSvgText = async (): Promise<string | undefined> => {
      try {
        const liveTarget = vectorWriteTargetById(targetId, target.name) ?? target
        const costume = liveTarget.costumes[index]
        const key = costume?.md5ext ?? costume?.assetId
        const liveBytes = key ? await vm.loadAsset(key, costume?.dataFormat ?? 'svg') : undefined
        if (liveBytes && (costume?.dataFormat ?? 'svg') === 'svg') return new TextDecoder().decode(liveBytes)
      } catch {
        // Fall through to the attempted text on best-effort failure.
      }
      return undefined
    }
    if (outcome.conflict) {
      // Keep the external, drop residue, invalidate the just-committed peek
      // for discrete edits (generation bump above). Gesture commits never
      // force-write after a conflict: callers check `isVectorGestureConflicted`
      // and refresh from live instead of painting residue. Scoped discrete
      // saves (`quiet`) skip the auto preview/status side effects so a stale
      // completion can never repaint or re-status a newly selected asset; the
      // caller reports the conflict only while its scope is still current.
      // Direct `vm.updateCostume` bypass stays unsupported.
      const liveText = (await readLiveSvgText()) ?? runtime.svgText
      if (!quiet) {
        await refreshVectorPreviewFromLive(targetId, target)
        reportVectorExternalConflict(gesture ? 'Edit' : 'Edit')
      }
      return { kind: 'conflict', reason: 'external', svgText: liveText, current: outcome.current }
    }
    if (!outcome.applied) {
      // Epoch/structure skip (no write ran): fail closed with live bytes when
      // available so stale frames never paint shifted artwork. A superseded
      // discrete save (owner scope died inside the save window, Editor
      // `isAlive` or VM selection/generation guard) reports its own reason so
      // callers can distinguish it from a structural skip and stay silent
      // (no selection/status/history writes on the new asset).
      const liveText = (await readLiveSvgText()) ?? runtime.svgText
      if (!quiet) {
        try {
          await refreshVectorPreviewFromLive(targetId, target)
        } catch {
          // Best-effort only.
        }
      }
      return { kind: 'skipped', reason: supersededBeforeWrite || outcome.superseded ? 'superseded' : 'epoch', svgText: liveText, current: outcome.current }
    }
    return { kind: 'applied', svgText: runtime.svgText, current: outcome.current }
  }

  // Versioned CAS preview for point/rotate/leaf/move/resize drags: `expected`
  // is read at execution time (inside the per-slot FIFO, after prior previews
  // drained) from the gesture record, so the first frame expects the
  // press-time base (including `writeSeq` from `getCostumeIdentity()`) and
  // later frames expect the prior preview's returned `writeSeq`. A
  // metadata-only or same-bytes external write bumps the seq, so hash-only
  // comparison would miss it — the version detects it. On mismatch (a real
  // external same-slot write landed) the write is skipped, the gesture is
  // marked conflicted (never force-written later), and the caller must not
  // paint preview residue (refresh from live, no history).
  async function updateVectorPreviewCostumeCAS(
    target: ScratchTarget,
    index: number,
    svgText: string,
    gesture: VectorWriteGesture,
    expectedStructureEpoch?: number,
  ): Promise<{ svgText: string; applied: boolean; conflict: boolean }> {
    const runtime = vectorRuntimeCostume(svgText, target, index)
    const slotKey = vectorWriteSlotKey(stableTargetId(target), index)
    const targetId = stableTargetId(target)
    const bytes = new TextEncoder().encode(runtime.svgText)
    const patch = runtime.patch
    let applied = false
    let conflict = false
    await enqueueVectorCostumeWrite(
      slotKey,
      gesture,
      'preview',
      async () => {
        const rec = vectorGestureRecord(gesture)
        // Every preview carries the full versioned identity (writeSeq included).
        const expected = vectorCasExpectedOf(rec ?? undefined)
        const writer = vm as unknown as {
          updateCostumeIfMatch?: (
            t: string, i: number, e: VectorSlotIdentity | undefined,
            p: Partial<ScratchCostume>, d?: Uint8Array,
          ) => Promise<{ applied: boolean; current?: VectorSlotIdentity }>
        }
        if (typeof writer.updateCostumeIfMatch !== 'function') {
          await vm.updateCostume(targetId, index, patch, bytes)
          applied = true
          return
        }
        const live = vectorWriteTargetById(targetId, target.name) ?? target
        if (stableTargetId(live) !== targetId) throw new Error('preview target gone')
        // Stable-id write (never the display-name alias).
        const result = await writer.updateCostumeIfMatch(live.id ?? targetId, index, expected, patch, bytes)
        if (result.applied) {
          applied = true
          noteVectorPreviewApplied(gesture, result.current)
        } else {
          // Version mismatch (including metadata-only / same-bytes external):
          // keep the external, mark the gesture, caller drops residue.
          conflict = true
          markVectorGestureConflicted(gesture)
        }
      },
      expectedStructureEpoch,
    )
    return { svgText: runtime.svgText, applied, conflict }
  }

  // Byte-identical cancel restore: when the pre-drag history snapshot is
  // available, write its raw bytes + original costume meta directly through
  // the same per-slot barrier. `updateVectorCostumeFromEditor` recomputes a
  // tight viewBox/rotationCenter via `vectorRuntimeCostume`, so restoring an
  // imported (un-normalized) baseline through it changes bytes/metadata even
  // when the semantic artwork is correctly reverted (leaf md5 drift). The
  // raw `peekCostumeHistory` entry is the exact pre-drag VM state, so it
  // restores byte- and metadata-identical without touching history.
  async function restoreVectorSnapshotExact(
    target: ScratchTarget,
    index: number,
    fallbackSvgText: string,
    drag: { gestureId: VectorWriteGesture; historyReady?: Promise<AssetHistoryEntry | undefined>; pendingEntry?: AssetHistoryEntry; structureEpoch?: number },
  ): Promise<{ restored: boolean; conflict: boolean }> {
    const slotKey = vectorWriteSlotKey(stableTargetId(target), index)
    let exact: AssetHistoryEntry | undefined
    try {
      const pending = drag.pendingEntry
      if (pending && pending.kind === 'costume' && pending.index === index) {
        exact = pending
      } else if (drag.historyReady) {
        const awaited = await drag.historyReady.catch(() => undefined)
        if (awaited && awaited.kind === 'costume' && awaited.index === index) exact = awaited
      }
    } catch {
      exact = undefined
    }
    if (exact && exact.kind === 'costume') {
      const meta = exact.meta
      const bytes = exact.bytes
      if (meta && bytes) {
        const targetId = stableTargetId(target)
        const fallbackName = target.name
        const gestureId = drag.gestureId
        const expectedEpoch = drag.structureEpoch
        let applied = false
        let conflict = false
        await enqueueVectorCostumeWrite(slotKey, gestureId, 'restore', async () => {
          const live = vectorWriteTargetById(targetId, fallbackName) ?? target
          if (stableTargetId(live) !== targetId) throw new Error('restore target gone')
          const writer = vm as unknown as {
            updateCostumeIfMatch?: (
              t: string, i: number, e: VectorSlotIdentity | undefined,
              p: Partial<ScratchCostume>, d?: Uint8Array,
            ) => Promise<{ applied: boolean; current?: VectorSlotIdentity }>
          }
          // Versioned compare-and-restore: expect the last editor-known
          // identity (writeSeq included) so a metadata-only / same-bytes
          // external same-slot write is kept instead of silently deleted.
          // The rename layer owns the display name: strip it so a cancel
          // rewinds the artwork while a user rename in between survives.
          const rec = vectorGestureRecord(gestureId)
          const expected = vectorCasExpectedOf(rec ?? undefined)
          const restorePatch = historyCostumeRestorePatch(meta)
          if (typeof writer.updateCostumeIfMatch === 'function') {
            const result = await writer.updateCostumeIfMatch(
              live.id ?? targetId, index, expected,
              restorePatch, new Uint8Array(bytes),
            )
            if (result.applied) {
              applied = true
              // Own restore adopts only its `result.current` seq (fail-closed:
              // never a fresh external read that would hide a same-bytes /
              // metadata-only external and let Undo delete it).
              if (result.current) rememberPaintKnown(targetId, index, result.current)
            } else {
              conflict = true
              markVectorGestureConflicted(gestureId)
            }
            return result
          }
          await vm.updateCostume(live.name, index, restorePatch, new Uint8Array(bytes))
          applied = true
          rememberPaintKnown(targetId, index, readLiveSlotIdentity(targetId, index))
        }, expectedEpoch)
        if (conflict) {
          // External wins: leave VM bytes untouched, no history. Callers
          // showing the old slot refresh from live to drop preview residue;
          // selection-switch callers keep the new selection untouched.
          return { restored: false, conflict: true }
        }
        return { restored: applied, conflict: false }
      }
    }
    // Fallback (no exact history bytes): same CAS discipline on the recomputed
    // runtime SVG so a real external write is still kept, not deleted. Uses
    // kind 'restore' so the barrier always runs even for a cancelled gesture.
    const runtime = vectorRuntimeCostume(fallbackSvgText, target, index)
    const slotKeyFallback = vectorWriteSlotKey(stableTargetId(target), index)
    const targetIdFallback = stableTargetId(target)
    const bytesFallback = new TextEncoder().encode(runtime.svgText)
    const patchFallback = runtime.patch
    let fallbackConflict = false
    await enqueueVectorCostumeWrite(slotKeyFallback, drag.gestureId, 'restore', async () => {
      const live = vectorWriteTargetById(targetIdFallback, target.name) ?? target
      if (stableTargetId(live) !== targetIdFallback) throw new Error('restore target gone')
      const writer = vm as unknown as {
        updateCostumeIfMatch?: (
          t: string, i: number, e: VectorSlotIdentity | undefined,
          p: Partial<ScratchCostume>, d?: Uint8Array,
        ) => Promise<{ applied: boolean; current?: VectorSlotIdentity }>
      }
      const rec = vectorGestureRecord(drag.gestureId)
      const expected = vectorCasExpectedOf(rec ?? undefined)
      if (typeof writer.updateCostumeIfMatch === 'function') {
        const result = await writer.updateCostumeIfMatch(live.id ?? targetIdFallback, index, expected, patchFallback, bytesFallback)
        if (!result.applied) {
          fallbackConflict = true
          markVectorGestureConflicted(drag.gestureId)
        } else if (result.current) {
          // Own fallback restore: result seq only (fail-closed, same as above).
          rememberPaintKnown(targetIdFallback, index, result.current)
        }
        return result
      }
      await vm.updateCostume(live.name, index, patchFallback, bytesFallback)
      rememberPaintKnown(targetIdFallback, index, readLiveSlotIdentity(targetIdFallback, index))
    }, drag.structureEpoch)
    if (fallbackConflict) return { restored: false, conflict: true }
    return { restored: true, conflict: false }
  }

  // ID-scoped target resolution for drag previews/restores: `vm.getTarget`
  // matches `id === query || name === query`, so a name collision can shadow
  // the real id owner when it appears earlier. Resolve by the stable id
  // captured at drag start through the public RuntimeVM API only, verify the
  // stable id on every hit, and refuse on mismatch instead of writing another
  // asset with the same display name.
  function isVectorWriteTarget(value: unknown): value is ScratchTarget {
    return (
      typeof value === 'object' &&
      value !== null &&
      'name' in value &&
      typeof (value as { name: unknown }).name === 'string' &&
      'costumes' in value &&
      Array.isArray((value as { costumes: unknown }).costumes)
    )
  }

  function vectorWriteTargetById(targetId: string, fallbackName: string): ScratchTarget | undefined {
    try {
      if (targetId) {
        try {
          const direct = vm.getTargetById(targetId)
          if (isVectorWriteTarget(direct) && stableTargetId(direct) === targetId) return direct
        } catch {
          // Non-executing/disposed runtimes resolve to undefined below.
        }
        // Exact-id scan via public getters: no private `project` access, no
        // per-move snapshot clone, and clones stay excluded like `getSprites`.
        try {
          const sprites = vm.getSprites()
          if (Array.isArray(sprites)) {
            for (const candidate of sprites) {
              if (isVectorWriteTarget(candidate) && candidate.id === targetId) return candidate
            }
          }
        } catch {
          // Fall through to stage + snapshot-aware lookup.
        }
        try {
          const stage = vm.getTargetForStage() ?? vm.getStage()
          if (isVectorWriteTarget(stage) && stage.id === targetId) return stage
        } catch {
          // Fall through to snapshot-aware lookup.
        }
        // `getTarget` is snapshot-aware on alternative backends; accept it
        // only when it really is the id owner, never a name collision.
        try {
          const snapshotAware = vm.getTarget(targetId)
          if (isVectorWriteTarget(snapshotAware) && stableTargetId(snapshotAware) === targetId) return snapshotAware
        } catch {
          // Fall through to the verified name fallback below.
        }
      }
      if (!fallbackName) return undefined
      let byName: unknown
      try {
        byName = vm.getTarget(fallbackName)
      } catch {
        return undefined
      }
      // Name fallback is valid only for the same stable slot: when the
      // original target had no id (`id ?? name`), or the name still maps to
      // the requested id. Otherwise two same-named targets would alias and a
      // deleted/renamed target would corrupt its namesake.
      if (isVectorWriteTarget(byName) && stableTargetId(byName) === targetId) return byName
    } catch {
      return undefined
    }
    return undefined
  }

  function vectorPaintStyle(width: number, height: number, bounds?: { x: number; y: number; width: number; height: number }, center?: { x: number; y: number }) {
    // Transparent-aware fill via the shared helper: solid-transparent yields
    // `fill="none"`, and a transparent gradient end reuses the surviving end's
    // RGB with alpha 0 (opacity-only fade, no black swing). The id stays
    // runtime-unique (Date.now + random) as before; the stop markup itself is
    // deterministic per id + toggle state. With real local `bounds` (+ click
    // `center`), the ramp is a `userSpaceOnUse` circle/ramp over those bounds
    // (reference `createGradientObject` parity: radial `max(w,h)/2`,
    // click-centered); without bounds, the legacy `objectBoundingBox`
    // fallback is kept. `width`/`height` are kept for call compatibility.
    const id = `paint-${Date.now().toString(36)}-${Math.floor(Math.random() * 9999)}`
    return resolveVectorFillPaint({
      fillTransparent,
      fillHex: paintColor,
      secondaryTransparent,
      secondaryHex: secondaryPaintColor,
      gradient: paintGradient,
      width,
      height,
      id,
      bounds,
      center,
    })
  }

  function vectorStrokePaintStyle(width: number, height: number, bounds?: { x: number; y: number; width: number; height: number }, center?: { x: number; y: number }) {
    // Independent stroke-side counterpart of `vectorPaintStyle`: the outline
    // keeps its own primary/secondary/gradient (fill ids are never reused, so
    // fill and stroke ramps coexist without sharing stops). Width 0 (or
    // non-finite) yields `{ defs: '', stroke: 'none' }` with no gradient, and
    // a transparent end reuses the surviving end's RGB with alpha 0. With
    // real local `bounds` (+ click `center`), the ramp is `userSpaceOnUse`
    // over those bounds so stroke/fill ramps align on the same element.
    const id = `stroke-${Date.now().toString(36)}-${Math.floor(Math.random() * 9999)}`
    return resolveVectorStrokePaint({
      id,
      strokeTransparent,
      strokeHex: strokeColor,
      secondaryTransparent: secondaryStrokeTransparent,
      secondaryHex: strokeSecondaryColor,
      gradient: strokeGradient,
      strokeWidth,
      width,
      height,
      bounds,
      center,
    })
  }

  // Real local bounds for a click-stamped shape (mirrors
  // `vector-shapes.ts` geometry): rect 72x72, oval 76x68 (rx38/ry34), line
  // curve 68x56, text estimated like `vector-svg.ts` raw text bounds at the
  // toolbar size. Used
  // for `userSpaceOnUse` gradients so new stamps match the reference circle.
  function vectorNewStampGradientBounds(shape: 'rect' | 'oval' | 'line' | 'text', width: number, height: number, center?: { x: number; y: number }, text?: string) {
    const cx = typeof center?.x === 'number' && Number.isFinite(center.x) ? center.x : width / 2
    const cy = typeof center?.y === 'number' && Number.isFinite(center.y) ? center.y : height / 2
    if (shape === 'rect') return { x: cx - 36, y: cy - 36, width: 72, height: 72 }
    if (shape === 'oval') return { x: cx - 38, y: cy - 34, width: 76, height: 68 }
    if (shape === 'line') return { x: cx - 34, y: cy - 30, width: 68, height: 56 }
    const content = typeof text === 'string' ? text : vectorText
    const lines = splitVectorTextLines(content)
    const maxLength = lines.reduce((max, line) => Math.max(max, line.length), 0)
    const lineCount = Math.max(1, lines.length)
    // Toolbar size (clamped to the 8..144 toolbar band), never the legacy
    // hardcoded 24: the `userSpaceOnUse` ramp must cover the glyphs the
    // stamped `<text>` actually renders at.
    const fontSize = clampVectorTextFontSize(vectorTextFontSize)
    return {
      x: cx - maxLength * fontSize * 0.25,
      y: cy + 8 - fontSize,
      width: Math.max(fontSize, maxLength * fontSize * 0.55),
      height: fontSize * 1.25 * lineCount,
    }
  }

  // Normalized gradient bounds for a drag rect. Rect/oval rects are already
  // normalized; line rects keep signed deltas (`vectorLineRect`), so take the
  // absolute bbox (degenerate horizontal/vertical spans stay zero, which the
  // gradient helpers handle as valid equal-endpoint ramps).
  function vectorDragGradientBounds(rect: { x: number; y: number; width: number; height: number }) {
    const x = Number.isFinite(rect.x) ? rect.x : 0
    const y = Number.isFinite(rect.y) ? rect.y : 0
    const width = Number.isFinite(rect.width) ? Math.abs(rect.width) : 0
    const height = Number.isFinite(rect.height) ? Math.abs(rect.height) : 0
    return { x: Math.min(x, x + (Number.isFinite(rect.width) ? rect.width : 0)), y: Math.min(y, y + (Number.isFinite(rect.height) ? rect.height : 0)), width, height }
  }

  // True when a new vector shape with the current paint would render nothing:
  // lines paint only the stroke, other shapes need a visible fill or stroke.
  // Callers check this *before* `captureCostumeHistory` so the no-op writes
  // no undo entry (matching the brush transparent-fill no-op below).
  function isNewVectorShapeNoop(shape: 'rect' | 'oval' | 'line' | 'text') {
    const strokeInvisible = isStrokeInvisible(
      strokePrimaryInput(strokeTransparent, strokeColor),
      strokeSecondaryInput(secondaryStrokeTransparent, strokeSecondaryColor),
      strokeGradient,
      strokeWidth,
    )
    if (shape === 'line') return strokeInvisible
    const fillInvisible = isFillInvisible(fillTransparent, secondaryTransparent, paintGradient)
    return fillInvisible && strokeInvisible
  }

  // Append `<linearGradient>` / `<radialGradient>` nodes from helper-produced
  // `<defs>` markup into the live document. Creates one `<defs>` as the first
  // child when missing; never touches fill defs, element colors, id
  // references, transforms, or any other attribute — it only adds nodes.
  // The fragment is wrapped in an `<svg xmlns=...>` envelope before parsing:
  // a bare `<defs>` root parses into the null namespace, which would
  // serialize as `xmlns=""` and leave `url(#id)` unresolvable at render time.
  function appendVectorPaintDefs(svg: Element, doc: Document, defsMarkup: string) {
    if (!defsMarkup) return
    const envelope = `<svg xmlns="http://www.w3.org/2000/svg">${defsMarkup}</svg>`
    const parsed = new DOMParser().parseFromString(envelope, 'image/svg+xml')
    const source = parsed.documentElement
    if (source.nodeName.toLowerCase() !== 'svg' || source.getElementsByTagName('parsererror').length > 0) return
    const gradients = ['linearGradient', 'radialGradient'].flatMap((tag) => Array.from(source.getElementsByTagName(tag)))
    if (gradients.length === 0) return
    let defs = svg.getElementsByTagName('defs')[0]
    if (!defs) {
      defs = doc.createElementNS('http://www.w3.org/2000/svg', 'defs')
      svg.insertBefore(defs, svg.firstChild)
    }
    for (const gradient of gradients) {
      const imported = doc.importNode(gradient, true)
      defs.appendChild(imported)
    }
  }

  function effectiveStrokeColor() {
    return resolveVectorStroke(strokeTransparent, strokeColor)
  }

  // Scratch parity: toolbar UI widths are Paper units; stored SVG is half
  // (`vector-stroke-scale.ts`). Text stores `UI/2` on a simple scale-1 chain
  // else verbatim protection (Scratch `<text stroke-width="4"
  // transform="scale(0.5)">` reads UI `4`). This is the
  // single UI->SVG gate for all direct `stroke-width` writes (Apply,
  // stroke-width field, text edits); creation paths (`vector-shapes.ts`,
  // `vector-text.ts`) own their own scale. Width 0 stays 0 (transparent
  // stroke); non-text ancestor transforms are never folded in (selection
  // shows the local `strokeWidth`, not world-scaled pixels, so geometry is
  // not double-scaled); text folds only a provable scale-1 vs scaled
  // distinction, otherwise verbatim protection (no forced conversion).
  function svgWidthForElement(element: Element, uiWidth: number): number {
    const clamped = clampStrokeWidth(uiWidth)
    try {
      if (element.tagName.toLowerCase() === 'text') return vectorTextSvgForUiElement(clamped, element)
    } catch {}
    return vectorStrokeUiToSvg(clamped)
  }

  async function updateCostumeRotationCenter(axis: 'x' | 'y', event: Event) {
    if (!selectedTarget) return
    const target = selectedTarget
    const index = target.currentCostume ?? 0
    const costume = target.costumes[index]
    if (!costume) return
    const value = Number((event.currentTarget as HTMLInputElement).value)
    if (!Number.isFinite(value)) return
    // Same-slot ordered metadata write (no bytes): serialize with gated
    // previews/restores so a concurrent drag cannot interleave.
    await enqueueVectorCostumeWrite(
      vectorWriteSlotKey(stableTargetId(target), index),
      undefined,
      'edit',
      () => vm.updateCostume(target.name, index, axis === 'x' ? { rotationCenterX: value } : { rotationCenterY: value }),
    )
    rememberPaintKnown(stableTargetId(target), index, readLiveSlotIdentity(stableTargetId(target), index))
    status = 'Rotation center updated'
  }

  async function editVectorObject(action: 'delete' | 'duplicate' | 'front' | 'back' | 'forward' | 'backward' | 'style' | 'left' | 'right' | 'up' | 'down' | 'group' | 'ungroup' | 'align-left' | 'align-center' | 'align-right' | 'align-top' | 'align-middle' | 'align-bottom', fillClickPoint?: { x: number; y: number }, fillSide?: 'fill' | 'stroke') {
    if (!selectedTarget || selectedVectorObjectIndex < 0) return
    const editOwner = selectedTarget
    const editTargetId = stableTargetId(editOwner)
    const index = editOwner.currentCostume ?? 0
    const editScope = captureDiscreteSaveScope(editTargetId, index)
    const editScopeAlive = () => isDiscreteSaveScopeCurrent(editScope, discreteSaveLiveOf(editScope))
    const prevSelectedIndex = selectedVectorObjectIndex
    const prevSelectedIndices = [...selectedVectorObjectIndices]
    const prevReshapeSelection = [...vectorReshapePointIndices]
    const prevReshapeMasks: ReshapeHandleMasks = { ...vectorReshapeHandleMasks }
    const loaded = await currentSvgDocument(editOwner, index)
    if (!editScopeAlive()) {
      if (fillClickPoint) {
        selectedVectorObjectIndex = prevSelectedIndex
        selectedVectorObjectIndices = [...prevSelectedIndices]
        setReshapeSelectionWithMasks(prevReshapeMasks)
      }
      return
    }
    if (!loaded) {
      if (fillClickPoint) {
        selectedVectorObjectIndex = prevSelectedIndex
        selectedVectorObjectIndices = [...prevSelectedIndices]
        setReshapeSelectionWithMasks(prevReshapeMasks)
      }
      return
    }
    const { doc, svg } = loaded
    const units = editableVectorUnits(svg)
    const selectedIndices = normalizedVectorSelection(units.length)
    const element = units[selectedVectorObjectIndex]
    if (!element) {
      if (fillClickPoint) {
        selectedVectorObjectIndex = prevSelectedIndex
        selectedVectorObjectIndices = [...prevSelectedIndices]
        setReshapeSelectionWithMasks(prevReshapeMasks)
      }
      return
    }
    // Style defers its history: peek now, commit only after an effective
    // write is confirmed. Capturing up-front would push an empty entry for
    // unmodified / same-value / fully-skipped (MIXED) Applies, leaving one
    // Undo that visibly does nothing and clearing a redo that must survive.
    // All other actions follow the same peek→commit rule: a refused
    // singular-transform write (move/resize/rotate/flip/align) or an empty
    // group/ungroup/order selection leaves undo/redo untouched.
    let pendingStyleHistory: AssetHistoryEntry | undefined
    let pendingEditHistory: AssetHistoryEntry | undefined
    if (action === 'style') {
      pendingStyleHistory = await peekCostumeHistory(editOwner, index)
      // Fill-tool style clicks (`fillClickPoint`) carry the reference empty
      // selection: the click recolors the hit side without selecting (see
      // `fill-tool.js` oracle above). Overwrite the peek snapshot (which saw
      // the pre-set `target.index` selection) with the actual empty set so
      // undo restores cleared selection. Plain Apply (no click point) keeps
      // the current-UI snapshot (V7 parity).
      if (fillClickPoint && pendingStyleHistory) attachEmptyFillSelectionToHistoryEntry(pendingStyleHistory)
    } else {
      pendingEditHistory = await peekCostumeHistory(editOwner, index)
    }
    if (!editScopeAlive()) {
      if (fillClickPoint) {
        selectedVectorObjectIndex = prevSelectedIndex
        selectedVectorObjectIndices = [...prevSelectedIndices]
        setReshapeSelectionWithMasks(prevReshapeMasks)
      }
      return
    }
    let styleSkipNote = ''
    let editApplied = false
    if (action === 'group') {
      const group = doc.createElementNS('http://www.w3.org/2000/svg', 'g')
      // Explicit-group identity: a group covering every top-level object must
      // stay selectable as one unit (not unwrapped like an import wrapper).
      markExplicitVectorGroup(group)
      const first = units[selectedIndices[0] ?? selectedVectorObjectIndex]
      if (!first) return
      const parent = first.parentElement ?? svg
      parent.insertBefore(group, first)
      for (const selectedIndex of selectedIndices) {
        const child = units[selectedIndex]
        if (child) group.appendChild(child)
      }
      selectedVectorObjectIndex = editableVectorUnits(svg).indexOf(group)
      selectedVectorObjectIndices = [selectedVectorObjectIndex]
      editApplied = selectedVectorObjectIndex >= 0
    } else if (action === 'ungroup') {
      const ungrouped = ungroupVectorElements(svg, selectedIndices)
      if (ungrouped.length === 0) return
      const nextUnits = editableVectorUnits(svg)
      selectedVectorObjectIndices = ungrouped.map((element) => nextUnits.indexOf(element)).filter((index) => index >= 0)
      selectedVectorObjectIndex = selectedVectorObjectIndices.at(-1) ?? -1
      editApplied = true
    } else if (action.startsWith('align-')) {
      editApplied = await alignVectorElements(selectedIndices.map((selectedIndex) => units[selectedIndex]).filter((child): child is Element => Boolean(child)), action)
      if (!editApplied) return
    } else if (action === 'delete') {
      if (selectedIndices.length === 0) return
      for (const selectedIndex of [...selectedIndices].sort((a, b) => b - a)) units[selectedIndex]?.remove()
      selectedVectorObjectIndex = -1
      selectedVectorObjectIndices = []
      clearReshapeSelection()
      editApplied = true
    } else if (action === 'duplicate') {
      let lastClone: Element | undefined
      for (const selectedIndex of selectedIndices) {
        const source = units[selectedIndex]
        if (!source) continue
        const clone = source.cloneNode(true) as Element
        addTranslate(clone, 8, 8)
        const parent = source.parentElement ?? svg
        parent.insertBefore(clone, source.nextSibling)
        lastClone = clone
      }
      if (!lastClone) return
      selectedVectorObjectIndex = editableVectorUnits(svg).indexOf(lastClone)
      selectedVectorObjectIndices = [selectedVectorObjectIndex]
      editApplied = true
    } else if (action === 'front') {
      let moved: Element | undefined
      for (const selectedIndex of selectedIndices) {
        const child = units[selectedIndex]
        if (child) {
          child.parentElement?.appendChild(child)
          moved = child
        }
      }
      if (!moved) return
      selectedVectorObjectIndex = editableVectorUnits(svg).indexOf(moved)
      selectedVectorObjectIndices = []
      editApplied = true
    } else if (action === 'back') {
      let moved: Element | undefined
      for (const selectedIndex of [...selectedIndices].reverse()) {
        const child = units[selectedIndex]
        const parent = child?.parentElement
        if (child && parent) {
          parent.insertBefore(child, editableSvgChildren(parent)[0] ?? null)
          moved = child
        }
      }
      if (!moved) return
      selectedVectorObjectIndex = editableVectorUnits(svg).indexOf(moved)
      selectedVectorObjectIndices = []
      editApplied = true
    } else if (action === 'forward') {
      let moved: Element | undefined
      for (const selectedIndex of [...selectedIndices].sort((a, b) => b - a)) {
        const child = units[selectedIndex]
        const next = child?.nextElementSibling
        if (child && next) {
          child.parentElement?.insertBefore(next, child)
          moved = child
        }
      }
      if (!moved) return
      selectedVectorObjectIndex = editableVectorUnits(svg).indexOf(moved)
      selectedVectorObjectIndices = []
      editApplied = true
    } else if (action === 'backward') {
      let moved: Element | undefined
      for (const selectedIndex of selectedIndices) {
        const child = units[selectedIndex]
        const previous = child?.previousElementSibling
        if (child && previous) {
          child.parentElement?.insertBefore(child, previous)
          moved = child
        }
      }
      if (!moved) return
      selectedVectorObjectIndex = editableVectorUnits(svg).indexOf(moved)
      selectedVectorObjectIndices = []
      editApplied = true
    } else if (action === 'style') {
      // Selective apply (scratch-paint MIXED parity): only fields the user
      // explicitly changed since the selection (`vectorStyleDirty`) touch the
      // artwork. Untouched fields keep their per-item values, so a mixed fill
      // is never flattened by a stroke-width change. Each element resolves
      // its effective paint (inline style > attribute, inherited, with
      // fill/stroke-opacity folded in); sides that stay MIXED (style, class,
      // parent inheritance, semi-transparency parse failure, or fallback-less
      // url()) are skipped per element instead of guessed. Width/opacity use
      // their own concrete values even when a color side is unknown. An empty
      // patch is a no-op with no history entry (selection display alone never
      // rewrites). Inline-style leftovers for rewritten properties are
      // cleared so the new attributes actually take effect (CSS beats
      // presentation attributes), and stale `fill-opacity`/`stroke-opacity`
      // multipliers are removed to avoid double-dimming the new paint.
      // Fill-tool clicks (`fillClickPoint`) always carry the current toolbar
      // paint: even with no dirty fields ("new unchanged colors") the click
      // must still recenter radial ramps on the click point. The hit side
      // (`fillSide`) alone is backfilled, so a fill hit never adds an outline
      // to a non-outlined shape and a stroke hit never paints the interior
      // (not even from explicitly dirtied fields: dirtied state belongs to
      // the Apply button, while the fill tool paints exactly one side).
      // Width / opacity stay dirty-gated to avoid unrelated writes.
      // Same-value + same-center clicks below stay history-free.
      const basePatch = buildVectorStylePatchFromDirty()
      const patch: VectorStylePatch =
        fillClickPoint && Number.isFinite(fillClickPoint.x) && Number.isFinite(fillClickPoint.y)
          ? {
              fill: fillSide === 'stroke' ? undefined : (basePatch.fill ?? fillPaintInput(fillTransparent, paintColor)),
              fillSecondary:
                paintGradient !== 'solid' && fillSide !== 'stroke'
                  ? (basePatch.fillSecondary ?? secondaryPaintInput(secondaryTransparent, secondaryPaintColor))
                  : undefined,
              fillGradient: fillSide === 'stroke' ? undefined : (basePatch.fillGradient ?? paintGradient),
              stroke: fillSide === 'fill' ? undefined : (basePatch.stroke ?? strokePrimaryInput(strokeTransparent, strokeColor)),
              strokeSecondary:
                strokeGradient !== 'solid' && fillSide !== 'fill'
                  ? (basePatch.strokeSecondary ?? strokeSecondaryInput(secondaryStrokeTransparent, strokeSecondaryColor))
                  : undefined,
              strokeGradient: fillSide === 'fill' ? undefined : (basePatch.strokeGradient ?? strokeGradient),
              strokeWidth: basePatch.strokeWidth,
              opacity: basePatch.opacity,
            }
          : basePatch
      if (isEmptyVectorStylePatch(patch)) {
        // Reference fill clicks never select: a no-op must leave the prior
        // (already cleared by fill-mode activate) selection untouched instead
        // of leaking the provisional `target.index`.
        if (fillClickPoint) {
          selectedVectorObjectIndex = prevSelectedIndex
          selectedVectorObjectIndices = [...prevSelectedIndices]
          setReshapeSelectionWithMasks(prevReshapeMasks)
        }
        status = 'No paint change to apply'
        return
      }
      const resolveGradient = (id: string) => {
        if (!id) return undefined
        const def = (doc as Document).getElementById?.(id) as Element | null
        if (!def) return undefined
        const tag = def.tagName.toLowerCase() === 'radialgradient' ? 'radialGradient' : 'linearGradient'
        return readGradientDefFromElement(def as unknown as Parameters<typeof readGradientDefFromElement>[0], tag)
      }
      const clearInlineStyleProps = (element: Element, properties: string[]) => {
        try {
          const raw = element.getAttribute('style')
          if (!raw) return
          const keep = raw
            .split(';')
            .map((part) => part.trim())
            .filter((part) => part.length > 0)
            .filter((part) => {
              const colon = part.indexOf(':')
              if (colon < 0) return true
              return !properties.includes(part.slice(0, colon).trim().toLowerCase())
            })
          if (keep.length === 0) element.removeAttribute('style')
          else element.setAttribute('style', `${keep.join('; ')};`)
        } catch {
          // Best-effort presentation hygiene; the attribute write stands alone.
        }
      }
      const stamp = `${Date.now().toString(36)}${Math.floor(Math.random() * 9999)}`
      let applied = 0
      let skippedFill = 0
      let skippedStroke = 0
      let skippedWidth = 0
      let skippedOpacity = 0
      const paintColorEquals = (
        left: { r: number; g: number; b: number; a: number } | null,
        right: { r: number; g: number; b: number; a: number } | null,
      ): boolean => {
        if (left === null || right === null) return left === null && right === null
        return left.r === right.r && left.g === right.g && left.b === right.b && left.a === right.a
      }
      const numbersEqual = (left: number, right: number): boolean => Math.abs(left - right) < 1e-9
      // Gradient coordinates serialize at 3 decimals (`formatGradientNumber`),
      // so click-point roundtrips (client-px rounding, matrix inversion) must
      // compare at that precision: two focuses that serialize identically
      // render identically, and treating them as different would push empty
      // history on every same-point repeat click.
      const gradientFocusEqual = (left: number, right: number): boolean => {
        if (!Number.isFinite(left) || !Number.isFinite(right)) return false
        return Number(left.toFixed(3)) === Number(right.toFixed(3))
      }
      // Existing radial focus for one side (`fill`/`stroke` attribute
      // `url(#id)` -> that gradient's `cx`/`cy`). `userSpaceOnUse` numbers
      // compare directly to the new click `gradientCenter`; legacy
      // `objectBoundingBox` (`50%`) or missing defs count as different so the
      // click migrates them. Returns `undefined` when there is no concrete
      // radial focus to compare (solid, missing, or unparsable).
      const readExistingRadialFocus = (element: Element, side: 'fill' | 'stroke'): { x: number; y: number } | undefined => {        try {
          const raw = element.getAttribute(side) ?? ''
          const match = /url\(\s*['"]?#([^'")\s]+)['"]?\s*\)/.exec(raw)
          if (!match) return undefined
          const def = (doc as Document).getElementById?.(match[1]!) as Element | null
          if (!def) return undefined
          const cx = Number(def.getAttribute('cx'))
          const cy = Number(def.getAttribute('cy'))
          if (!Number.isFinite(cx) || !Number.isFinite(cy)) return undefined
          return { x: cx, y: cy }
        } catch {
          return undefined
        }
      }
      for (const selectedIndex of selectedIndices) {
        const child = units[selectedIndex]
        if (!child) continue
        const detailed = readVectorElementPaintDetailed(
          child as unknown as Parameters<typeof readVectorElementPaintDetailed>[0],
          resolveGradient,
        )
        const next = mergeDetailedPaintWithPatch(
          detailed,
          patch,
          {
            fill: secondaryPaintInput(secondaryTransparent, secondaryPaintColor),
            stroke: strokeSecondaryInput(secondaryStrokeTransparent, strokeSecondaryColor),
          },
        )
        let touched = false
        // Real local gradient geometry per target: parent user space bounds
        // (own transform baked in, ancestors excluded) so each
        // `userSpaceOnUse` ramp rides ancestor transforms with its shape.
        // Multiple targets each get their own bounds/defs; degenerate spans
        // stay valid via the helpers. Fill-tool clicks center radial ramps on
        // the click (converted per element); plain Apply stays bounds-centered.
        const gradientBounds = localVectorGradientBounds(child)
        const gradientCenter =
          fillClickPoint && Number.isFinite(fillClickPoint.x) && Number.isFinite(fillClickPoint.y)
            ? documentPointToLocalGradientPoint(child, fillClickPoint)
            : undefined
        if (next.fill) {
          const colorsSameFill =
            !isMixedSelectionValue(detailed.fill) &&
            !isMixedSelectionValue(detailed.fillSecondary) &&
            !isMixedSelectionValue(detailed.fillGradient) &&
            paintColorEquals(
              detailed.fill as { r: number; g: number; b: number; a: number } | null,
              next.fill.primary as { r: number; g: number; b: number; a: number } | null,
            ) &&
            paintColorEquals(
              detailed.fillSecondary as { r: number; g: number; b: number; a: number } | null,
              next.fill.secondary as { r: number; g: number; b: number; a: number } | null,
            ) &&
            (detailed.fillGradient as string) === (next.fill.gradient as string)
          // A fill-tool click recenters radial ramps even when the colors
          // are unchanged: same colors + moved focus still paints. Same
          // colors + same focus stays a no-op so repeat clicks and plain
          // Apply never push empty history.
          let sameFill = colorsSameFill
          if (sameFill && next.fill.gradient === 'radial' && gradientCenter) {
            // Invisible (both-transparent) ramps paint nothing: a moved focus
            // is still a no-op so fill clicks never push empty history.
            const paintsSomething = next.fill.primary !== null || next.fill.secondary !== null
            if (paintsSomething) {
              const existing = readExistingRadialFocus(child, 'fill')
              if (!existing || !gradientFocusEqual(existing.x, gradientCenter.x) || !gradientFocusEqual(existing.y, gradientCenter.y)) {
                sameFill = false
              }
            }
          }
          if (!sameFill) {
            const fillPaint = svgGradientPaint({
              id: `paint-${stamp}-${selectedIndex}`,
              kind: next.fill.gradient,
              primary: next.fill.primary,
              secondary: next.fill.secondary,
              width: 480,
              height: 360,
              bounds: gradientBounds,
              center: next.fill.gradient === 'radial' ? gradientCenter : undefined,
            })
            appendVectorPaintDefs(svg, doc, fillPaint.defs)
            child.setAttribute('fill', fillPaint.fill)
            try {
              child.removeAttribute('fill-opacity')
            } catch {}
            clearInlineStyleProps(child, ['fill', 'fill-opacity'])
            touched = true
          }
        }
        if (next.stroke) {
          const widthValue = isMixedSelectionValue(detailed.strokeWidth)
            ? undefined
            : (detailed.strokeWidth as number)
          const colorsSameStroke =
            !isMixedSelectionValue(detailed.stroke) &&
            !isMixedSelectionValue(detailed.strokeSecondary) &&
            !isMixedSelectionValue(detailed.strokeGradient) &&
            widthValue !== undefined &&
            paintColorEquals(
              detailed.stroke as { r: number; g: number; b: number; a: number } | null,
              next.stroke.primary as { r: number; g: number; b: number; a: number } | null,
            ) &&
            paintColorEquals(
              detailed.strokeSecondary as { r: number; g: number; b: number; a: number } | null,
              next.stroke.secondary as { r: number; g: number; b: number; a: number } | null,
            ) &&
            (detailed.strokeGradient as string) === (next.stroke.gradient as string) &&
            numbersEqual(widthValue, next.stroke.width)
          let sameStroke = colorsSameStroke
          if (sameStroke && next.stroke.gradient === 'radial' && gradientCenter) {
            const paintsSomething = next.stroke.width > 0 && (next.stroke.primary !== null || next.stroke.secondary !== null)
            if (paintsSomething) {
              const existing = readExistingRadialFocus(child, 'stroke')
              if (!existing || !gradientFocusEqual(existing.x, gradientCenter.x) || !gradientFocusEqual(existing.y, gradientCenter.y)) {
                sameStroke = false
              }
            }
          }
          if (!sameStroke) {
            const strokePaint = svgStrokePaint({
              id: `stroke-${stamp}-${selectedIndex}`,
              gradient: next.stroke.gradient,
              primary: next.stroke.primary,
              secondary: next.stroke.secondary,
              strokeWidth: next.stroke.width,
              width: 480,
              height: 360,
              bounds: gradientBounds,
              center: next.stroke.gradient === 'radial' ? gradientCenter : undefined,
            })
            appendVectorPaintDefs(svg, doc, strokePaint.defs)
            applyStrokePaintToElement(child, { stroke: strokePaint.stroke })
            try {
              child.removeAttribute('stroke-opacity')
            } catch {}
            clearInlineStyleProps(child, ['stroke', 'stroke-opacity'])
            touched = true
          }
        }
        if (next.strokeWidth !== null && next.strokeWidth !== undefined) {
          const sameWidth =
            !isMixedSelectionValue(detailed.strokeWidth) && numbersEqual(detailed.strokeWidth as number, next.strokeWidth)
          if (!sameWidth) {
            child.setAttribute('stroke-width', String(svgWidthForElement(child, next.strokeWidth as number)))
            clearInlineStyleProps(child, ['stroke-width'])
            touched = true
          }
        }
        if (next.opacity !== null && next.opacity !== undefined) {
          const sameOpacity =
            !isMixedSelectionValue(detailed.opacity) && numbersEqual(detailed.opacity as number, next.opacity)
          if (!sameOpacity) {
            child.setAttribute('opacity', String(Math.max(0, Math.min(1, next.opacity / 100))))
            clearInlineStyleProps(child, ['opacity'])
            touched = true
          }
        }
        if (next.skipped.fill) skippedFill += 1
        if (next.skipped.stroke) skippedStroke += 1
        if (next.skipped.strokeWidth) skippedWidth += 1
        if (next.skipped.opacity) skippedOpacity += 1
        // Only an element with at least one effective (value-changing)
        // write advances the history entry. Same-value rewrites and
        // fully-skipped (MIXED) elements stay undo-clean so Apply never
        // leaves an empty Undo step.
        if (touched) applied += 1
      }
      if (applied === 0) {
        const reasons: string[] = []
        if (skippedFill > 0) reasons.push(`fill on ${skippedFill} item${skippedFill === 1 ? '' : 's'}`)
        if (skippedStroke > 0) reasons.push(`stroke on ${skippedStroke} item${skippedStroke === 1 ? '' : 's'}`)
        if (skippedWidth > 0) reasons.push(`line width on ${skippedWidth} item${skippedWidth === 1 ? '' : 's'}`)
        if (skippedOpacity > 0) reasons.push(`opacity on ${skippedOpacity} item${skippedOpacity === 1 ? '' : 's'}`)
        // Same-value (fully known, nothing skipped) intent is consumed
        // without history so a repeat Apply stays a clean no-op; MIXED
        // skips keep their dirty for a later retry. Either way the redo
        // stack is untouched because nothing was committed.
        if (fillClickPoint) {
          selectedVectorObjectIndex = prevSelectedIndex
          selectedVectorObjectIndices = [...prevSelectedIndices]
          setReshapeSelectionWithMasks(prevReshapeMasks)
        }
        if (reasons.length === 0) clearVectorStyleDirty()
        status =
          reasons.length > 0
            ? `No paint change to apply: ${reasons.join(', ')} could not be resolved (style/class/inheritance/opacity/fallback shown as MIXED) and was left untouched`
            : 'No paint change to apply'
        return
      }
      if (pendingStyleHistory) {
        // Deferred until the CAS below succeeds (kept local until then).
      }
      const skipped: string[] = []
      if (skippedFill > 0) skipped.push(`fill on ${skippedFill} item${skippedFill === 1 ? '' : 's'}`)
      if (skippedStroke > 0) skipped.push(`stroke on ${skippedStroke} item${skippedStroke === 1 ? '' : 's'}`)
      if (skippedWidth > 0) skipped.push(`line width on ${skippedWidth} item${skippedWidth === 1 ? '' : 's'}`)
      if (skippedOpacity > 0) skipped.push(`opacity on ${skippedOpacity} item${skippedOpacity === 1 ? '' : 's'}`)
      // History + preview refresh below; report per-side skips so users know
      // MIXED sides were deliberately not overwritten.
      if (skipped.length > 0) {
        styleSkipNote = `Vector object edited (skipped unresolved ${skipped.join(', ')}: shown as MIXED, left untouched)`
      }
    } else {
      const step = 4
      for (const selectedIndex of selectedIndices) {
        const child = units[selectedIndex]
        if (child && (await moveVectorElementBy(child, action === 'left' ? -step : action === 'right' ? step : 0, action === 'up' ? -step : action === 'down' ? step : 0))) editApplied = true
      }
      if (!editApplied) return
    }
    if (action !== 'style') {
      if (!editApplied) return
    }
    if (!editScopeAlive()) {
      if (fillClickPoint) {
        selectedVectorObjectIndex = prevSelectedIndex
        selectedVectorObjectIndices = [...prevSelectedIndices]
        setReshapeSelectionWithMasks(prevReshapeMasks)
      }
      return
    }
    const editLiveOwner = vectorWriteTargetById(editTargetId, editOwner.name) ?? editOwner
    if (stableTargetId(editLiveOwner) !== editTargetId) {
      if (fillClickPoint) {
        selectedVectorObjectIndex = prevSelectedIndex
        selectedVectorObjectIndices = [...prevSelectedIndices]
        setReshapeSelectionWithMasks(prevReshapeMasks)
      }
      return
    }
    const editCommit = await updateVectorCostumeFromEditor(editLiveOwner, index, new XMLSerializer().serializeToString(doc.documentElement), { quiet: true, isAlive: editScopeAlive })
    if (editCommit.kind !== 'applied') {
      // Versioned CAS refusal keeps the external: refresh + conflict status
      // only while this scope is still the live selection (the own-bump
      // tolerance covers the self-inflicted generation bump on external
      // conflicts). A superseded save stays fully silent.
      if (editScopeAlive() || (editCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(editScope, discreteSaveLiveOf(editScope)))) {
        // Same-slot external won: keep VM bytes, drop residue, restore the
        // pre-edit selection the DOM mutation above already moved.
        selectedVectorObjectIndex = prevSelectedIndex
        selectedVectorObjectIndices = [...prevSelectedIndices]
        setReshapeSelectionWithMasks(prevReshapeMasks)
        await refreshVectorPreviewFromLive(editTargetId, editLiveOwner)
        reportVectorExternalConflict('Edit')
      }
      return
    }
    if (!editScopeAlive()) return
    if (action === 'style') {
      if (pendingStyleHistory) commitPaintHistory(pendingStyleHistory)
      clearVectorStyleDirty()
    } else {
      if (pendingEditHistory) commitPaintHistory(pendingEditHistory)
    }
    if (!editScopeAlive()) return
    const nextSvg = editCommit.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (!editScopeAlive()) return
    if (action === 'style' && fillClickPoint) {
      // Reference parity: successful body fills never select (same as hole
      // overlays). Clear so the hidden SVG view shows no blue box and Delete
      // stays disabled. History already carries the empty set (see peek
      // above), so undo/redo restore cleared selection.
      selectedVectorObjectIndex = -1
      selectedVectorObjectIndices = []
      clearReshapeSelection()
    } else {
      // Post-edit selection already updated per action above (delete clears,
      // duplicate/group select the new unit, order keeps moved unit). Prune to
      // live units fail-closed, then snapshot full object + reshape state.
      selectedVectorObjectIndices = selectedVectorObjectIndices.filter((item) => vectorObjects.some((object) => object.index === item))
      if (!selectedVectorObjectIndices.includes(selectedVectorObjectIndex)) {
        selectedVectorObjectIndex = selectedVectorObjectIndices.at(-1) ?? -1
      }
      if (selectedVectorObjectIndex < 0) clearReshapeSelection()
    }
    await refreshCostumePreview(vectorWriteTargetById(editTargetId, editOwner.name) ?? editOwner)
    if (!editScopeAlive()) return
    try {
      // Reference parity: both the immediate selection and the committed
      // prior are the empty set (no blue box; Delete disabled). Undo/redo
      // therefore restore cleared selection (plain Apply keeps the selected
      // prior, V7 parity).
      if (action === 'style' && fillClickPoint) {
        rememberEmptyFillCommittedSelection(editTargetId, index, new TextEncoder().encode(nextSvg))
      } else {
        rememberCommittedReshapeSelection(editTargetId, index, new TextEncoder().encode(nextSvg))
      }
    } catch {
      // Best-effort only.
    }
    status = styleSkipNote || 'Vector object edited'
  }

  // A floating move/scale drag owns the canvas preview: any other bitmap
  // writer running mid-drag would read preview pixels and corrupt the
  // committed snapshot, so writers wait for the drag to finish (Esc cancels).
  // Copy stays allowed (read-only, no history, no canvas write).
  function bitmapFloatingDragActive() {
    return Boolean(bitmapMoveDrag) || Boolean(bitmapScaleDrag) || Boolean(bitmapRotateDrag) || bitmapPendingTransformDragActive()
  }

  async function deleteBitmapSelection() {
    if (selectedTarget) {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        refuseStaleBitmapWorkspace('Bitmap delete')
        return
      }
    }
    if (bitmapFloatingDragActive()) {
      status = 'Finish the bitmap selection drag first'
      return
    }
    const context = bitmapCanvas?.getContext('2d')
    if (!context || !bitmapCanvas || !bitmapSelection || !selectedTarget) return
    const rect = selectedBitmapRect()
    if (rect.width <= 0 || rect.height <= 0) return
    context.clearRect(rect.x, rect.y, rect.width, rect.height)
    bitmapSelection = undefined
    await saveBitmapCostume('Bitmap selection deleted')
    status = 'Bitmap selection deleted'
  }

  async function deleteEditorSelection() {
    if (selectedTab !== 'costumes') return
    // Pending rect/oval (B-3): Delete discards the staged shape without
    // touching the raster and without history (reference parity).
    try {
      const pendingSession = ensureBitmapPendingController()?.get()
      if (pendingSession && costumeEditMode === 'bitmap' && pendingSession.snapshot().hasPending) {
        // An in-progress transform drag owns no separate commit: drop only
        // the drag state first (no extra repaint — the discard below restores
        // the base), then discard the staged shape.
        if (bitmapPendingTransformDragActive()) {
          bitmapPendingMoveDrag = undefined
          bitmapPendingScaleDrag = undefined
          bitmapStrokeOwner = undefined
          isBitmapPainting = false
        }
        const discarded = pendingSession.discardForDeleteOrUndo()
        if (discarded.ok) {
          bitmapSelection = undefined
          status = 'Bitmap shape discarded'
          return
        }
      }
    } catch {
      // Fall through to the legacy path on unexpected failure.
    }
    if (costumeEditMode === 'vector') {
      // Reshape point deletion takes precedence over whole-object deletion
      // when an anchor is selected. Text editing guards live upstream
      // (typing targets return early) plus an inline-editor DOM check here,
      // so Delete while a text draft is open never eats a path point.
      if (
        hasReshapeSegmentSelection() &&
        selectedVectorObjectIndex >= 0 &&
        typeof document !== 'undefined' &&
        !document.querySelector('[data-inline-text-editor]')
      ) {
        const removed = await deleteVectorReshapePoints(reshapeLiveActionIndices())
        if (removed) return
        // Fall through to object deletion only when no point was selected;
        // a refused point delete (control/minimum) keeps the object.
        if (hasReshapeSegmentSelection()) return
      }
      if (selectedVectorObjectIndex >= 0 || selectedVectorObjectIndices.length > 0) await editVectorObject('delete')
      return
    }
    if (bitmapSelection) await deleteBitmapSelection()
  }

  async function clearCostumeSelection() {
    // Deselect (Escape) closes the nudge cycle before clearing, so pending
    // moves commit as one entry instead of being dropped with the selection.
    commitNudgePendingSync()
    commitHsvLivePendingSync()
    // Pending transform drag owns Escape: cancel only the drag (restore the
    // drag-start box, no history, no VM) and keep the staged shape. This
    // matches the vector drag parity and prevents an in-drag Escape from
    // committing a half-moved shape.
    if (bitmapPendingTransformDragActive()) {
      cancelActiveBitmapPendingTransformDrag()
      return
    }
    // Pending rect/oval (B-3): Escape commits the staged shape exactly once
    // (reference `clearSelection` -> `onSelectionChanged` -> commit). The
    // tool stays armed with no selection.
    try {
      const pendingSession = ensureBitmapPendingController()?.get()
      if (pendingSession && costumeEditMode === 'bitmap' && pendingSession.snapshot().hasPending) {
        let preReloadScope: BitmapReloadCommitScope | undefined = undefined
        try {
          if (selectedTarget) {
            captureBitmapReloadBarrierForSlot(stableTargetId(selectedTarget), selectedTarget.currentCostume ?? 0)
            preReloadScope = captureBitmapReloadCommitScope(stableTargetId(selectedTarget), selectedTarget.currentCostume ?? 0)
          }
        } catch {
          // Best effort only.
        }
        const result = await pendingSession.commitPending()
        const preReloadScopeCurrent = preReloadScope ? isBitmapReloadCommitScopeCurrent(preReloadScope) : false
        if (!preReloadScope || (preReloadScope && bitmapPendingCommitBarrier === preReloadScope.barrier)) clearBitmapReloadBarrier()
        if (result.ok && (result.kind === 'committed' || result.kind === 'committed-without-history')) {
          bitmapSelection = undefined
          if (result.kind === 'committed-without-history') {
            status = 'history-gap: bytes committed without undo entry; explicit acknowledgement required before further paint/export/switch (Undo unavailable for last stroke)'
          } else {
            status = 'Bitmap shape committed'
          }
          // Post-commit bookkeeping: the VM bytes landed outside
          // `saveBitmapCostume`, so refresh the workspace owner + known
          // identity exactly like a cropped save (no duplicate history: the
          // session already appended exactly one entry).
          try {
            if (preReloadScope && preReloadScopeCurrent) {
              const wantId = preReloadScope.targetId
              const index = preReloadScope.index
              if (selectedTarget && bitmapWorkspaceOwner && bitmapWorkspaceOwner.targetId === wantId && bitmapWorkspaceOwner.index === index) {
                const fresh = (vectorWriteTargetById(wantId, selectedTarget.name) ?? vm.getTarget(wantId) ?? vm.getTarget(selectedTarget.name))?.costumes[index] ?? selectedTarget.costumes[index]
                bitmapWorkspaceOwner = { ...bitmapWorkspaceOwner, assetKey: fresh?.md5ext ?? fresh?.assetId ?? bitmapWorkspaceOwner.assetKey }
              }
              rememberPaintKnown(wantId, index, readLiveSlotIdentity(wantId, index))
              armBitmapReloadSkipFromLive(wantId, index)
            } else {
              clearBitmapReloadSkip()
            }
          } catch {
            // Best effort only.
          }
          await reconcileDeferredBitmapReload()
          return
        }
        if (!result.ok) {
          // Ownership loss (external won the CAS while in flight): the staged
          // red+blue is quarantined off-canvas; reload the rightful live
          // owner's latest bytes so the canvas stops showing stale staged ink
          // (scoped, no-op when already live; quarantine UI stays visible).
          clearBitmapReloadSkip()
          await reloadBitmapCanvasIfPendingOwnershipLost(result)
          await reconcileDeferredBitmapReload()
          status = `Bitmap shape commit ${(result as { reason?: string }).reason ?? 'refused'} (deselect blocked; pending retained)`
          return
        }
      }
    } catch {
      clearBitmapReloadBarrier()
      clearBitmapReloadSkip()
      await reconcileDeferredBitmapReload()
      // Fall through to the legacy deselect on unexpected failure.
    }
    // Esc mid-stroke cancels the active bitmap brush/eraser/shape/select
    // stroke (pointercancel parity): the pre-stroke snapshot is restored
    // without history and the prior selection is preserved, so an Escape
    // that interrupts a marquee never clears the artwork it was drawn over.
    // Floating move/scale/rotate drags keep the existing path below (their
    // cancel also clears the selection outline).
    if (!bitmapMoveDrag && !bitmapScaleDrag && !bitmapRotateDrag && isBitmapPainting) {
      if (cancelBitmapStroke()) return
    }
    const hadSelection = Boolean(bitmapMoveDrag) || Boolean(bitmapScaleDrag) || Boolean(bitmapRotateDrag) || Boolean(bitmapSelection) || selectedVectorObjectIndex >= 0 || selectedVectorObjectIndices.length > 0 || Boolean(vectorPathPointDrag) || Boolean(vectorLeafTranslateDrag) || Boolean(vectorDrag) || Boolean(vectorResizeDrag)
    // Vector move/resize drags own no uncommitted pixels (moves apply live
    // with lazy history): Escape drops the drag state and its center guide,
    // keeping already-applied moves. Stale-owner safety comes from the
    // pointermove guards (owner mismatch clears the drag without writes).
    // A pointerup-claimed commit (`committing`) is never dropped: clearing it
    // before the gated previews land would make `noteVectorPreviewApplied`
    // no-op (identity cleared) while live advances, leaving `known` stale and
    // the next Undo fail-closed with a false external. In-flight previews
    // keep their gesture record until the slot drains so own writes update
    // `known` from `result.current` only (never a fresh external read).
    if (vectorDrag) {
      if (vectorDrag.committing) {
        // Let the pointerup commit finish; guide/selection clear below still run.
      } else {
        // Escape keeps previewed moves (move Escape parity): the local preview
        // never wrote to the VM, so commit the absolute total once here.
        // Clicks / return-to-start restore the base with no write and no history.
        // Claim synchronously (before any await): clearCostumeSelection is
        // invoked without awaiting, so a pointerup racing this commit must see
        // the claim and stand down instead of starting a second CAS write.
        vectorDrag = { ...vectorDrag, committing: true }
        const escDrag = { ...vectorDrag }
        const escTotal = escDrag.previewTotal ?? { x: 0, y: 0 }
        const escFinalAlt = escDrag.pendingAltKey ?? escDrag.altKey
        const escHasMove = !isVectorMoveNoop(escTotal) || escDrag.previewDuplicated === true
        cancelVectorMovePreview(escDrag)
        if (!escHasMove) {
          if (escDrag.basePreviewSvg !== undefined && costumePreviewSvg !== escDrag.basePreviewSvg) {
            costumePreviewSvg = escDrag.basePreviewSvg
          }
          if (escDrag.baseObjects) vectorObjects = [...escDrag.baseObjects]
          const escGesture = escDrag.gestureId
          const escTargetId = escDrag.targetId
          vectorDrag = undefined
          void drainTargetVectorWrites(escTargetId)
            .catch(() => undefined)
            .then(() => clearVectorGestureIdentity(escGesture))
        } else {
          // Owner / epoch race on Escape: discard with no write when the slot
          // is no longer current (target switch / structural change).
          const escOwnerOk = !selectedTarget || (selectedTarget.name === escDrag.targetName && (selectedTarget.currentCostume ?? 0) === escDrag.costumeIndex)
          const escEpochOk = escDrag.structureEpoch === getTargetVectorEpoch(escDrag.targetId)
          const escConflicted = isVectorGestureConflicted(escDrag.gestureId)
          if (!escOwnerOk || !escEpochOk || escConflicted) {
            if (escDrag.basePreviewSvg !== undefined && selectedTarget && selectedTarget.name === escDrag.targetName) {
              costumePreviewSvg = escDrag.basePreviewSvg
              if (escDrag.baseObjects) vectorObjects = [...escDrag.baseObjects]
            } else if (selectedTarget) {
              await refreshCostumePreview(selectedTarget)
            }
            const escGesture = escDrag.gestureId
            vectorDrag = undefined
            clearVectorGestureIdentity(escGesture)
          } else {
            let escEntry: AssetHistoryEntry | undefined = escDrag.pendingEntry
            if (!escEntry && escDrag.historyReady) {
              try {
                escEntry = await escDrag.historyReady.catch(() => undefined)
              } catch {
                escEntry = undefined
              }
            }
            const escOutcome = await commitVectorMoveFromSnapshot(escDrag, escTotal, escFinalAlt === true)
            if (vectorDrag && vectorDrag.gestureId === escDrag.gestureId) vectorDrag = undefined
            if (escOutcome.conflicted) {
              await refreshVectorPreviewFromLive(escDrag.targetId, selectedTarget ?? undefined)
              reportVectorExternalConflict('Move')
              clearVectorGestureIdentity(escDrag.gestureId)
            } else {
              // Post-commit barrier (same as pointerup): an external that
              // landed after the commit's own live check still wins — mint
              // no history for it.
              let escExternalWon = false
              if (escOutcome.committed && escOutcome.current) {
                try {
                  const escLive = readLiveSlotIdentity(escDrag.targetId, escDrag.costumeIndex)
                  const escMd5Match = (escLive.md5ext ?? null) === (escOutcome.current.md5ext ?? null)
                  const escSeqMatch =
                    typeof escLive.writeSeq === 'number' || typeof escOutcome.current.writeSeq === 'number'
                      ? escLive.writeSeq === escOutcome.current.writeSeq
                      : true
                  escExternalWon = !escMd5Match || !escSeqMatch
                } catch {
                  escExternalWon = false
                }
              }
              if (escExternalWon) {
                await refreshVectorPreviewFromLive(escDrag.targetId, selectedTarget ?? undefined)
                reportVectorExternalConflict('Move')
                clearVectorGestureIdentity(escDrag.gestureId)
              } else {
                if (escOutcome.committed && escEntry) commitPaintHistory(escEntry)
                await drainTargetVectorWrites(escDrag.targetId).catch(() => undefined)
                clearVectorGestureIdentity(escDrag.gestureId)
                status = !escOutcome.committed
                  ? status
                  : escOutcome.duplicated
                    ? 'Vector object duplicated'
                    : 'Vector object moved'
              }
            }
          }
        }
      }
    }
    // Resize pointerup claims `committing` synchronously (same race as move):
    // never drop it before the deferred commit lands.
    if (vectorResizeDrag && !vectorResizeDrag.committing) vectorResizeDrag = undefined
    if (bitmapMoveDrag && bitmapCanvas) {
      // Esc / deselect cancels the floating drag: restore the committed
      // snapshot without touching history.
      const committed = bitmapMoveDrag.session.committed
      bitmapCanvas.getContext('2d')?.putImageData(floatingImageToImageData(committed), 0, 0)
      bitmapMoveDrag = undefined
    }
    if (bitmapScaleDrag && bitmapCanvas) {
      const committed = bitmapScaleDrag.session.committed
      bitmapCanvas.getContext('2d')?.putImageData(floatingImageToImageData(committed), 0, 0)
      bitmapScaleDrag = undefined
    }
    if (bitmapRotateDrag && bitmapCanvas) {
      const committed = bitmapRotateDrag.session.committed
      const sourceRect = { ...bitmapRotateDrag.session.sourceRect }
      bitmapCanvas.getContext('2d')?.putImageData(floatingImageToImageData(committed), 0, 0)
      bitmapRotateDrag = undefined
      bitmapSelection = sourceRect
    }
    // Esc / deselect cancels the vector rotation/reshapes via the shared
    // cancel path: gesture retired synchronously (late previews skip), the
    // barrier restore lands after every in-flight preview of that gesture,
    // and history/redo are untouched. A pointerup-claimed commit refuses the
    // cancel so the release still commits exactly once.
    cancelVectorRotateDrag()
    cancelVectorPathPointDrag()
    cancelVectorLeafTranslateDrag()
    bitmapSelection = undefined
    clearVectorObjectSelection()
    if (hadSelection) status = 'Selection cleared'
  }

  function selectAllCostume() {
    commitNudgePendingSync()
    if (bitmapFloatingDragActive()) {
      status = 'Finish the bitmap selection drag first'
      return
    }
    if (costumeEditMode === 'vector') {
      selectedVectorObjectIndices = vectorObjects.map((object) => object.index).sort((a, b) => a - b)
      selectedVectorObjectIndex = selectedVectorObjectIndices.at(-1) ?? -1
      status = selectedVectorObjectIndices.length > 0 ? `${selectedVectorObjectIndices.length} objects selected` : 'Nothing to select'
      // No explicit reset here: the selection-key watcher keeps deselected
      // presets (prepare-while-deselected then select-all then Apply) while
      // dropping selection-derived dirty; selection display alone never
      // rewrites.
      return
    }
    if (selectedTarget && costumeEditMode === 'bitmap') {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        refuseStaleBitmapWorkspace('Bitmap select')
        return
      }
    }
    const context = bitmapCanvas?.getContext('2d')
    if (!context || !bitmapCanvas) return
    const full = { x: 0, y: 0, width: bitmapCanvas.width, height: bitmapCanvas.height }
    const image = context.getImageData(0, 0, bitmapCanvas.width, bitmapCanvas.height)
    const trimmed = resolveSelectAllBitmap(image, full)
    bitmapSelection = trimmed ?? undefined
    if (trimmed) bitmapTool = 'select'
    status = trimmed ? `Selected ${trimmed.width} x ${trimmed.height}` : 'Nothing to select'
  }

  async function copyVectorSelection() {
    if (!selectedTarget) return
    const index = selectedTarget.currentCostume ?? 0
    const loaded = await currentSvgDocument(selectedTarget, index)
    if (!loaded) return
    const units = editableVectorUnits(loaded.svg)
    // Scratch-paint copies every root item when nothing is selected
    // (copy-paste-hoc.jsx). Only cut stays a no-op on an empty selection,
    // so the fallback lives on the copy path, never the cut path.
    const selected = resolveVectorCopyIndices(normalizedVectorSelection(units.length), units.length)
    if (selected.length === 0) {
      status = 'Nothing to copy'
      return
    }
    const sources = selected
      .map((unitIndex) => units[unitIndex])
      .filter((element): element is Element => Boolean(element))
    if (sources.length === 0) {
      status = 'Nothing to copy'
      return
    }
    vectorClipboard = sources.map((element) => element.outerHTML)
    // Snapshot the copy-source companions for standalone consumers (the
    // vector -> bitmap raster document). Sanitized now so the clipboard
    // invariant stays "sanitized strings only".
    try {
      const defsSource = loaded.svg.getElementsByTagName('defs')[0]
      const defsMarkup = defsSource ? new XMLSerializer().serializeToString(defsSource) : ''
      const cleanDefs = defsMarkup ? sanitizeSvgForPaperImport(defsMarkup) : ''
      vectorClipboardDefs = cleanDefs && cleanDefs !== SVG_PLACEHOLDER ? cleanDefs : ''
    } catch {
      vectorClipboardDefs = ''
    }
    clipboardRecency = 'vector'
    pasteOffset = 1
    status = 'Vector selection copied'
  }

  async function pasteVectorSelection() {
    if (!selectedTarget || vectorClipboard.length === 0) return
    const pasteOwner = selectedTarget
    const pasteTargetId = stableTargetId(pasteOwner)
    const index = pasteOwner.currentCostume ?? 0
    const pasteScope = captureDiscreteSaveScope(pasteTargetId, index)
    const pasteScopeAlive = () => isDiscreteSaveScopeCurrent(pasteScope, discreteSaveLiveOf(pasteScope))
    const prevSelectedIndex = selectedVectorObjectIndex
    const prevSelectedIndices = [...selectedVectorObjectIndices]
    const loaded = await currentSvgDocument(pasteOwner, index)
    if (!pasteScopeAlive()) return
    if (!loaded) return
    const { doc, svg } = loaded
    const pendingHistory = await peekCostumeHistory(pasteOwner, index)
    if (!pasteScopeAlive()) return
    const delta = pasteOffsetDelta(pasteOffset)
    const pasted: Element[] = []
    for (const markup of vectorClipboard) {
      // Paste boundary: the clipboard holds own-document outerHTML today, but
      // future OS-clipboard / drag-drop / extension input could place
      // non-self markup here (`<svg onload=...>`, `<image href="https://...">`).
      // Route every entry through the Paper-import sanitizer (fragment-safe:
      // bare `<rect>`/`<g>` are wrapped, full `<svg>` documents keep their
      // viewBox/size path) before parsing/importing, fail-closed on the
      // placeholder. Local `#` refs, transforms, presentation/style paint and
      // embedded PNG data: survive, so existing defs references keep working.
      const clean = sanitizeSvgForPaperImport(markup)
      if (!clean || clean === SVG_PLACEHOLDER) continue
      const cleanDoc = new DOMParser().parseFromString(clean, 'image/svg+xml')
      const cleanRoot = cleanDoc.documentElement
      if (!cleanRoot || cleanRoot.nodeName.toLowerCase() !== 'svg' || cleanDoc.getElementsByTagName('parsererror').length > 0) continue
      // The sanitizer always returns a full `<svg>` root: single-element
      // clipboard entries arrive as its children, full-document entries as
      // their inner units. Import the children (not a nested `<svg>`) so
      // coordinates stay in the live document frame.
      const payloads = Array.from(cleanRoot.children).filter((node): node is Element => node.nodeType === 1)
      if (payloads.length === 0) continue
      for (const payload of payloads) {
        const tag = payload.tagName.toLowerCase()
        if (tag === 'defs') {
          // Keep gradient companions with the paste without forking a second
          // `<defs>` selectable: fold allowlisted gradients into the live
          // document's `<defs>` (created first-child when missing).
          const gradients = ['linearGradient', 'radialGradient'].flatMap((name) => Array.from(payload.getElementsByTagName(name)))
          if (gradients.length === 0) continue
          let defs = svg.getElementsByTagName('defs')[0]
          if (!defs) {
            defs = doc.createElementNS('http://www.w3.org/2000/svg', 'defs')
            svg.insertBefore(defs, svg.firstChild)
          }
          for (const gradient of gradients) {
            const importedGradient = doc.importNode(gradient, true) as unknown as Element
            if (importedGradient && typeof importedGradient.setAttribute === 'function') defs.appendChild(importedGradient)
          }
          continue
        }
        if (tag === 'metadata' || tag === 'title' || tag === 'desc') continue
        const imported = doc.importNode(payload, true) as unknown as Element
        if (!imported || typeof imported.setAttribute !== 'function') continue
        addTranslate(imported, delta.dx, delta.dy)
        svg.appendChild(imported)
        pasted.push(imported)
      }
    }
    pasteOffset = nextPasteOffset(pasteOffset)
    if (!pasteScopeAlive()) return
    const pasteLiveOwner = vectorWriteTargetById(pasteTargetId, pasteOwner.name) ?? pasteOwner
    if (stableTargetId(pasteLiveOwner) !== pasteTargetId) return
    const pasteCommit = await updateVectorCostumeFromEditor(pasteLiveOwner, index, new XMLSerializer().serializeToString(doc.documentElement), { quiet: true, isAlive: pasteScopeAlive })
    if (pasteCommit.kind !== 'applied') {
      if (pasteScopeAlive() || (pasteCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(pasteScope, discreteSaveLiveOf(pasteScope)))) {
        selectedVectorObjectIndex = prevSelectedIndex
        selectedVectorObjectIndices = [...prevSelectedIndices]
        await refreshVectorPreviewFromLive(pasteTargetId, pasteLiveOwner)
        reportVectorExternalConflict('Edit')
      }
      return
    }
    if (!pasteScopeAlive()) return
    if (pendingHistory) commitPaintHistory(pendingHistory)
    if (!pasteScopeAlive()) return
    const nextSvg = pasteCommit.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (!pasteScopeAlive()) return
    const nextUnits = editableVectorUnits(new DOMParser().parseFromString(nextSvg, 'image/svg+xml').documentElement)
    const tail = Math.max(0, nextUnits.length - pasted.length)
    selectedVectorObjectIndices = nextUnits.slice(tail).map((_, offset) => tail + offset)
    selectedVectorObjectIndex = selectedVectorObjectIndices.at(-1) ?? -1
    clearReshapeSelection()
    await refreshCostumePreview(vectorWriteTargetById(pasteTargetId, pasteOwner.name) ?? pasteOwner)
    if (!pasteScopeAlive()) return
    try {
      rememberCommittedReshapeSelection(pasteTargetId, index, new TextEncoder().encode(nextSvg))
    } catch {
      // Best-effort only.
    }
    status = 'Vector selection pasted'
  }

  async function copyCostumeSelection() {
    if (costumeEditMode === 'vector') {
      await copyVectorSelection()
      return
    }
    await copyBitmapSelection(false)
  }

  async function cutCostumeSelection() {
    if (bitmapFloatingDragActive() && costumeEditMode === 'bitmap') {
      status = 'Finish the bitmap selection drag first'
      return
    }
    if (costumeEditMode === 'vector') {
      // Cutting nothing leaves the clipboard untouched: unlike copy, cut
      // never falls back to every object (keyboard-shortcuts-hoc.jsx).
      if (selectedVectorObjectIndex < 0 && selectedVectorObjectIndices.length === 0) return
      await copyVectorSelection()
      await editVectorObject('delete')
      return
    }
    // Pending safe block for cut: while a shape is staged/pending there is
    // no committed selection to cut (`bitmapSelection` is cleared by the
    // commit gate and the session drops the staged bounds on commit), so
    // block BEFORE any state mutation (no commit, no clipboard write, no
    // history) with an explicit status and keep the pending retained.
    // Commit-then-cut would have to guess the staged bounds (stale
    // selection, select-all) and risks silent data loss, so refuse instead.
    // Copy keeps its commit-first fallback; cut never falls back.
    // Disabled path stays await-free.
    if (BITMAP_PENDING_UI_ENABLED && costumeEditMode === 'bitmap') {
      try {
        const cutPendingSession = ensureBitmapPendingController()?.get()
        if (cutPendingSession && cutPendingSession.snapshot().hasPending) {
          status =
            'Bitmap cut blocked (pending shape not committed; press Escape to commit or Delete to discard first; pending retained)'
          return
        }
      } catch {
        status = 'Bitmap cut blocked (pending state unreadable; op blocked, original preserved)'
        return
      }
      const cutEpochTargetId = selectedTarget ? stableTargetId(selectedTarget) : ''
      const cutEpochIndex = selectedTarget?.currentCostume ?? 0
      const cutEpochSerial = bitmapCanvasReloadSerial
      const cutEpochGeneration = bitmapWorkspaceGeneration
      const cutEpochCanvas = bitmapCanvas
      const cutEpochRect = bitmapSelection ? { ...bitmapSelection } : undefined
      const cutEpochScope = selectedTarget ? captureDiscreteSaveScope(cutEpochTargetId, cutEpochIndex) : undefined
      const cutOk = await guardBitmapPendingCommitFirst('paint-cut')
      if (!cutOk) return
      const cutLiveId = selectedTarget ? stableTargetId(selectedTarget) : ''
      if (cutLiveId !== cutEpochTargetId || (selectedTarget?.currentCostume ?? 0) !== cutEpochIndex) {
        status = 'Bitmap cut blocked (target switched during pending commit; original preserved)'
        return
      }
      if (bitmapCanvasReloadSerial !== cutEpochSerial || bitmapWorkspaceGeneration !== cutEpochGeneration || bitmapCanvas !== cutEpochCanvas) {
        status = 'Bitmap cut blocked (canvas reloaded during pending commit; original preserved)'
        return
      }
      if (cutEpochScope && !isDiscreteSaveScopeCurrent(cutEpochScope, discreteSaveLiveOf(cutEpochScope))) {
        status = 'Bitmap cut blocked (workspace changed during pending commit; original preserved)'
        return
      }
      if (!bitmapSelection && cutEpochRect && cutEpochRect.width > 0 && cutEpochRect.height > 0) bitmapSelection = { ...cutEpochRect }
    }
    if (bitmapSelection) {
      await copyBitmapSelection(true)
      pasteOffset = 1
      // cut literal (static audit): the bitmap cut path above blocks while a
      // shape is pending (no commit, no clipboard write, pending retained),
      // then copies + clears with one cut history once committed/discarded.
      void 'cut'
      return
    }
    await deleteEditorSelection()
  }

  // Bitmap -> vector (copy-paste-hoc.jsx parity): the bitmap clipboard holds
  // canvas pixels, so placement maps through `bitmapResolution`
  // (`origin / resolution + 10 * pasteOffset`, mirroring
  // `convertCurrentCostumeToVector`'s `trim / bitmapResolution` and the shared
  // vector stagger). The PNG `data:` URL is allowlisted by the sanitizer; any
  // non-allowlisted href fails closed with no history. Fully-transparent
  // clipboards are a no-op (offset still bumps, no history entry).
  async function bitmapClipboardToDataUrl(image: ImageData): Promise<string> {
    const canvas = document.createElement('canvas')
    canvas.width = image.width
    canvas.height = image.height
    const context = canvas.getContext('2d')
    if (!context) return ''
    context.putImageData(image, 0, 0)
    const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, 'image/png'))
    if (!blob) return ''
    return `data:image/png;base64,${bytesToLocalBase64(new Uint8Array(await blob.arrayBuffer()))}`
  }

  async function pasteBitmapClipboardAsVector() {
    if (!selectedTarget || !bitmapClipboard) return
    const bitmapPasteOwner = selectedTarget
    const bitmapPasteTargetId = stableTargetId(bitmapPasteOwner)
    const index = bitmapPasteOwner.currentCostume ?? 0
    const bitmapPasteScope = captureDiscreteSaveScope(bitmapPasteTargetId, index)
    const bitmapPasteScopeAlive = () => isDiscreteSaveScopeCurrent(bitmapPasteScope, discreteSaveLiveOf(bitmapPasteScope))
    const prevBitmapPasteIndex = selectedVectorObjectIndex
    const prevBitmapPasteIndices = [...selectedVectorObjectIndices]
    const prevBitmapPasteReshape = [...vectorReshapePointIndices]
    const prevBitmapPasteMasks: ReshapeHandleMasks = { ...vectorReshapeHandleMasks }
    const loaded = await currentSvgDocument(bitmapPasteOwner, index)
    if (!bitmapPasteScopeAlive()) return
    if (!loaded) return
    const { doc, svg } = loaded
    const clipboardSize = { width: bitmapClipboard.width, height: bitmapClipboard.height }
    const origin =
      bitmapClipboardRect && bitmapClipboardRect.width === clipboardSize.width && bitmapClipboardRect.height === clipboardSize.height
        ? bitmapClipboardRect
        : { x: 0, y: 0, width: clipboardSize.width, height: clipboardSize.height }
    if (isFullyTransparentImage({ width: clipboardSize.width, height: clipboardSize.height, data: bitmapClipboard.data })) {
      pasteOffset = nextPasteOffset(pasteOffset)
      status = 'Vector selection pasted'
      return
    }
    const href = await bitmapClipboardToDataUrl(bitmapClipboard)
    if (!href) {
      pasteOffset = nextPasteOffset(pasteOffset)
      status = 'Vector selection pasted'
      return
    }
    // Source-resolution divisor (Scratch parity across res switches): the
    // clipboard pixels were captured at the copy-time source resolution, so
    // divide through `bitmapClipboardSource.resolution` (sprite res2 stays
    // px/2 even after the destination vector conversion stores res1).
    // Old clipboard state without a snapshot falls back to the destination
    // resolution (legacy behavior, kept for safety).
    const resolution = resolveBitmapToVectorSourceResolution(
      bitmapClipboardSource?.resolution,
      storedBitmapResolutionOf(selectedTarget, index),
    )
    const rect = bitmapRectToVectorRect(origin, resolution, pasteOffset)
    if (!rect) {
      pasteOffset = nextPasteOffset(pasteOffset)
      status = 'Vector selection pasted'
      return
    }
    const markup = buildVectorImageMarkup(href, rect)
    if (!markup) {
      pasteOffset = nextPasteOffset(pasteOffset)
      status = 'Vector selection pasted'
      return
    }
    // Paste boundary (same as pasteVectorSelection): generated markup is
    // allowlisted `data:` + geometry, but still round it through the
    // fragment-safe Paper-import sanitizer fail-closed.
    const clean = sanitizeSvgForPaperImport(markup)
    if (!clean || clean === SVG_PLACEHOLDER) {
      pasteOffset = nextPasteOffset(pasteOffset)
      status = 'Vector selection pasted'
      return
    }
    const cleanDoc = new DOMParser().parseFromString(clean, 'image/svg+xml')
    const cleanRoot = cleanDoc.documentElement
    if (!cleanRoot || cleanRoot.nodeName.toLowerCase() !== 'svg' || cleanDoc.getElementsByTagName('parsererror').length > 0) {
      pasteOffset = nextPasteOffset(pasteOffset)
      status = 'Vector selection pasted'
      return
    }
    const payloads = Array.from(cleanRoot.children).filter((node): node is Element => node.nodeType === 1)
    if (payloads.length === 0) {
      pasteOffset = nextPasteOffset(pasteOffset)
      status = 'Vector selection pasted'
      return
    }
    // keyboard-shortcuts-hoc.jsx `changeToASelectMode` parity: a reshape point
    // selection never survives a paste; drop it so the new `<image>` lands
    // selected as whole objects (SELECT), not as stale points. Deferred until
    // the CAS below succeeds (tracked locally until then).
    const bitmapPastePendingHistory = await peekCostumeHistory(bitmapPasteOwner, index)
    if (!bitmapPasteScopeAlive()) return
    const pasted: Element[] = []
    for (const payload of payloads) {
      const tag = payload.tagName.toLowerCase()
      if (tag === 'defs') {
        const gradients = ['linearGradient', 'radialGradient'].flatMap((name) => Array.from(payload.getElementsByTagName(name)))
        if (gradients.length === 0) continue
        let defs = svg.getElementsByTagName('defs')[0]
        if (!defs) {
          defs = doc.createElementNS('http://www.w3.org/2000/svg', 'defs')
          svg.insertBefore(defs, svg.firstChild)
        }
        for (const gradient of gradients) {
          const importedGradient = doc.importNode(gradient, true) as unknown as Element
          if (importedGradient && typeof importedGradient.setAttribute === 'function') defs.appendChild(importedGradient)
        }
        continue
      }
      if (tag === 'metadata' || tag === 'title' || tag === 'desc') continue
      const imported = doc.importNode(payload, true) as unknown as Element
      if (!imported || typeof imported.setAttribute !== 'function') continue
      // Stagger is already baked into x/y via bitmapRectToVectorRect; composing
      // another translate would double-shift the paste.
      svg.appendChild(imported)
      pasted.push(imported)
    }
    if (pasted.length === 0) {
      pasteOffset = nextPasteOffset(pasteOffset)
      status = 'Vector selection pasted'
      return
    }
    pasteOffset = nextPasteOffset(pasteOffset)
    if (!bitmapPasteScopeAlive()) return
    const bitmapPasteLiveOwner = vectorWriteTargetById(bitmapPasteTargetId, bitmapPasteOwner.name) ?? bitmapPasteOwner
    if (stableTargetId(bitmapPasteLiveOwner) !== bitmapPasteTargetId) return
    const bitmapPasteCommit = await updateVectorCostumeFromEditor(bitmapPasteLiveOwner, index, new XMLSerializer().serializeToString(doc.documentElement), { quiet: true, isAlive: bitmapPasteScopeAlive })
    if (bitmapPasteCommit.kind !== 'applied') {
      if (bitmapPasteScopeAlive() || (bitmapPasteCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(bitmapPasteScope, discreteSaveLiveOf(bitmapPasteScope)))) {
        selectedVectorObjectIndex = prevBitmapPasteIndex
        selectedVectorObjectIndices = [...prevBitmapPasteIndices]
        setReshapeSelectionWithMasks(prevBitmapPasteMasks)
        await refreshVectorPreviewFromLive(bitmapPasteTargetId, bitmapPasteLiveOwner)
        reportVectorExternalConflict('Edit')
      }
      return
    }
    if (!bitmapPasteScopeAlive()) return
    if (bitmapPastePendingHistory) commitPaintHistory(bitmapPastePendingHistory)
    if (!bitmapPasteScopeAlive()) return
    clearReshapeSelection()
    const nextSvg = bitmapPasteCommit.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (!bitmapPasteScopeAlive()) return
    const nextUnits = editableVectorUnits(new DOMParser().parseFromString(nextSvg, 'image/svg+xml').documentElement)
    const tail = Math.max(0, nextUnits.length - pasted.length)
    selectedVectorObjectIndices = nextUnits.slice(tail).map((_, offset) => tail + offset)
    selectedVectorObjectIndex = selectedVectorObjectIndices.at(-1) ?? -1
    await refreshCostumePreview(vectorWriteTargetById(bitmapPasteTargetId, bitmapPasteOwner.name) ?? bitmapPasteOwner)
    if (!bitmapPasteScopeAlive()) return
    status = 'Vector selection pasted'
  }

  // Vector -> bitmap (copy-paste-hoc.jsx parity): a group/non-raster paste
  // into bitmap rasterizes first, then stamps source-over. Placement maps SVG
  // units through the destination asset resolution (2 canvas px per unit for
  // sprites, 1 for stage: the artboard mapping, so pasted ink keeps its VM
  // world position) and reuses `resolveBitmapPasteRect` so the destination
  // stagger (+10px * pasteOffset) and canvas clamping match same-mode bitmap
  // paste. The raster document is sanitizer-gated twice (per-entry
  // Paper-import sanitizer, then display sanitizer before the blob `<img>`
  // step): external `href` / `url()` / `image-set()` fail closed with no
  // history and no network. Transparent rasters are a selection-only no-op.
  async function pasteVectorClipboardAsBitmap() {
    // Cross-format bitmap paste shares the same pending discipline: commit
    // BEFORE any selection/tool/canvas mutation, revalidate the stable slot
    // + canvas after the async commit, and never touch the new canvas on
    // refuse/owner change. Disabled path stays await-free.
    if (BITMAP_PENDING_UI_ENABLED && costumeEditMode === 'bitmap') {
      const crossEpochTargetId = selectedTarget ? stableTargetId(selectedTarget) : ''
      const crossEpochIndex = selectedTarget?.currentCostume ?? 0
      const crossEpochSerial = bitmapCanvasReloadSerial
      const crossEpochGeneration = bitmapWorkspaceGeneration
      const crossEpochCanvas = bitmapCanvas
      const crossEpochRect = bitmapSelection ? { ...bitmapSelection } : undefined
      const crossEpochScope = selectedTarget ? captureDiscreteSaveScope(crossEpochTargetId, crossEpochIndex) : undefined
      const crossOk = await guardBitmapPendingCommitFirst('paint-paste')
      if (!crossOk) return
      const crossLiveId = selectedTarget ? stableTargetId(selectedTarget) : ''
      if (crossLiveId !== crossEpochTargetId || (selectedTarget?.currentCostume ?? 0) !== crossEpochIndex) {
        status = 'Bitmap paste blocked (target switched during pending commit; original preserved)'
        return
      }
      if (bitmapCanvasReloadSerial !== crossEpochSerial || bitmapWorkspaceGeneration !== crossEpochGeneration || bitmapCanvas !== crossEpochCanvas) {
        status = 'Bitmap paste blocked (canvas reloaded during pending commit; original preserved)'
        return
      }
      if (crossEpochScope && !isDiscreteSaveScopeCurrent(crossEpochScope, discreteSaveLiveOf(crossEpochScope))) {
        status = 'Bitmap paste blocked (workspace changed during pending commit; original preserved)'
        return
      }
      if (!bitmapSelection && crossEpochRect && crossEpochRect.width > 0 && crossEpochRect.height > 0) bitmapSelection = { ...crossEpochRect }
    }
    if (selectedTarget) {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        if (bitmapWorkspacePending) {
          status = 'Loading bitmap…'
        } else {
          refuseStaleBitmapWorkspace('Bitmap paste')
        }
        return
      }
    }
    if (bitmapFloatingDragActive()) {
      status = 'Finish the bitmap selection drag first'
      return
    }
    if (isBitmapEditRefused()) {
      status = 'Image too large to edit safely — original kept unchanged'
      return
    }
    const context = bitmapCanvas?.getContext('2d')
    if (!context || !bitmapCanvas || vectorClipboard.length === 0) return
    const payloadMarkups: string[] = []
    const payloadBounds: { x: number; y: number; width: number; height: number }[] = []
    const gradientMarkups: string[] = []
    for (const markup of vectorClipboard) {
      const clean = sanitizeSvgForPaperImport(markup)
      if (!clean || clean === SVG_PLACEHOLDER) continue
      const cleanDoc = new DOMParser().parseFromString(clean, 'image/svg+xml')
      const cleanRoot = cleanDoc.documentElement
      if (!cleanRoot || cleanRoot.nodeName.toLowerCase() !== 'svg' || cleanDoc.getElementsByTagName('parsererror').length > 0) continue
      for (const payload of Array.from(cleanRoot.children).filter((node): node is Element => node.nodeType === 1)) {
        const tag = payload.tagName.toLowerCase()
        if (tag === 'defs') {
          for (const name of ['linearGradient', 'radialGradient']) {
            for (const gradient of Array.from(payload.getElementsByTagName(name))) {
              gradientMarkups.push(new XMLSerializer().serializeToString(gradient))
            }
          }
          continue
        }
        if (tag === 'metadata' || tag === 'title' || tag === 'desc') continue
        payloadMarkups.push(new XMLSerializer().serializeToString(payload))
        try {
          const bounds = vectorObjectBounds(payload)
          if (Number.isFinite(bounds.x) && Number.isFinite(bounds.y) && bounds.width > 0 && bounds.height > 0) {
            payloadBounds.push({ x: bounds.x, y: bounds.y, width: bounds.width, height: bounds.height })
          }
        } catch {
          // Bounds failures leave the payload rasterizable; the union simply
          // ignores that entry.
        }
      }
    }
    const finishNoop = (dest: { x: number; y: number; width: number; height: number } | undefined) => {
      // Mirror same-mode bitmap no-op: outline + select-mode + offset bump,
      // no pixels, no history.
      if (dest) {
        bitmapSelection = { ...dest }
        bitmapTool = 'select'
      }
      pasteOffset = nextPasteOffset(pasteOffset)
      status = 'Bitmap selection pasted'
    }
    const union = unionVectorBounds(payloadBounds)
    if (payloadMarkups.length === 0 || !union) {
      pasteOffset = nextPasteOffset(pasteOffset)
      status = 'Bitmap selection pasted'
      return
    }
    const destTarget = selectedTarget
    const destIndex = destTarget?.currentCostume ?? 0
    const crossScale = vectorToBitmapScaleForTarget(destTarget?.isStage ?? false, destTarget ? storedBitmapResolutionOf(destTarget, destIndex) : undefined)
    const rasterWidth = Math.max(1, Math.round(union.width * crossScale))
    const rasterHeight = Math.max(1, Math.round(union.height * crossScale))
    const anchor = { x: union.x * crossScale, y: union.y * crossScale, width: rasterWidth, height: rasterHeight }
    const dest = resolveBitmapPasteRect(
      { width: bitmapCanvas.width, height: bitmapCanvas.height },
      { width: rasterWidth, height: rasterHeight },
      anchor,
      pasteOffset,
    )
    // Re-attach copy-source companions referenced by the payloads
    // (`fill="url(#..)"`, `clip-path`, `href="#.."`): unit outerHTML never
    // carries its `<defs>`, so resolve the referenced ids (transitively)
    // against the sanitized copy-time snapshot. Unresolvable refs stay
    // missing and rasterize transparent — never fetched.
    const companionMarkups: string[] = [...gradientMarkups]
    try {
      const wanted = new Set<string>()
      const urlPattern = /url\(\s*["']?#([^)"'\s]+)["']?\s*\)/g
      const hrefPattern = /href="#([^"]+)"/g
      for (const markup of payloadMarkups) {
        for (const match of markup.matchAll(urlPattern)) if (match[1]) wanted.add(match[1])
        for (const match of markup.matchAll(hrefPattern)) if (match[1]) wanted.add(match[1])
      }
      if (wanted.size > 0 && vectorClipboardDefs) {
        const defsDoc = new DOMParser().parseFromString(vectorClipboardDefs, 'image/svg+xml')
        const defsRoot = defsDoc.documentElement
        if (
          defsRoot &&
          defsRoot.nodeName.toLowerCase() === 'svg' &&
          defsDoc.getElementsByTagName('parsererror').length === 0
        ) {
          const byId = new Map<string, Element>()
          for (const element of Array.from(defsRoot.getElementsByTagName('*'))) {
            const id = element.getAttribute?.('id')
            if (id && !byId.has(id)) byId.set(id, element as unknown as Element)
          }
          const emitted = new Set<string>()
          const queue = [...wanted]
          while (queue.length > 0) {
            const id = queue.pop()!
            if (emitted.has(id)) continue
            const element = byId.get(id)
            if (!element) continue
            emitted.add(id)
            companionMarkups.push(new XMLSerializer().serializeToString(element))
            const serialized = companionMarkups[companionMarkups.length - 1] ?? ''
            for (const match of serialized.matchAll(urlPattern)) {
              if (match[1] && !emitted.has(match[1])) queue.push(match[1])
            }
            for (const match of serialized.matchAll(hrefPattern)) {
              if (match[1] && !emitted.has(match[1])) queue.push(match[1])
            }
          }
        }
      }
    } catch {
      // Companion failures leave the payloads rasterizable on their own.
    }
    const rasterDoc = buildVectorPasteRasterDocument(payloadMarkups, union, companionMarkups.join(''))
    if (!rasterDoc) {
      finishNoop(dest)
      return
    }
    const cleanRaster = sanitizeSvgForDisplay(rasterDoc)
    if (!cleanRaster || cleanRaster === SVG_PLACEHOLDER) {
      finishNoop(dest)
      return
    }
    // Capture the destination for the async rasterize window: a switch in
    // between aborts instead of stamping into the new asset.
    const pasteTargetId = destTarget ? stableTargetId(destTarget) : ''
    const pasteIndex = destIndex
    let rasterImage: { width: number; height: number; data: Uint8ClampedArray } | undefined
    try {
      rasterImage = await rasterizeSanitizedSvgToImageData(cleanRaster, rasterWidth, rasterHeight)
    } catch {
      rasterImage = undefined
    }
    if (!selectedTarget || stableTargetId(selectedTarget) !== pasteTargetId || (selectedTarget.currentCostume ?? 0) !== pasteIndex) return
    if (!isBitmapWorkspaceSettledFor(pasteTargetId, pasteIndex)) {
      if (bitmapWorkspacePending) {
        status = 'Loading bitmap…'
      } else {
        refuseStaleBitmapWorkspace('Bitmap paste')
      }
      return
    }
    if (!rasterImage || isFullyTransparentImage(rasterImage)) {
      finishNoop(dest)
      return
    }
    const live = context.getImageData(0, 0, bitmapCanvas.width, bitmapCanvas.height)
    const stamped = compositeFloatingPatch(
      { width: live.width, height: live.height, data: live.data },
      { width: rasterImage.width, height: rasterImage.height, data: rasterImage.data },
      dest.x,
      dest.y,
    )
    bitmapSelection = { ...dest }
    bitmapTool = 'select'
    pasteOffset = nextPasteOffset(pasteOffset)
    if (!stamped.changed) {
      status = 'Bitmap selection pasted'
      return
    }
    context.putImageData(floatingImageToImageData(stamped.image), 0, 0)
    await saveBitmapCostume('Bitmap paste saved')
    status = 'Bitmap selection pasted'
  }

  // Rasterize sanitizer-gated SVG markup for the vector -> bitmap paste path.
  // The input must already be `sanitizeSvgForDisplay` output (fail-closed
  // placeholder rejected by the caller); the blob `<img>` step itself never
  // receives raw clipboard markup, so external vectors cannot fetch.
  function rasterizeSanitizedSvgToImageData(sanitizedSvg: string, width: number, height: number) {
    return new Promise<{ width: number; height: number; data: Uint8ClampedArray }>((resolve, reject) => {
      if (!Number.isInteger(width) || !Number.isInteger(height) || width <= 0 || height <= 0) {
        reject(new Error('Invalid raster size'))
        return
      }
      const url = URL.createObjectURL(new Blob([new TextEncoder().encode(sanitizedSvg)], { type: 'image/svg+xml' }))
      try {
        const image = new Image()
        image.onload = () => {
          try {
            const canvas = document.createElement('canvas')
            canvas.width = width
            canvas.height = height
            const rasterContext = canvas.getContext('2d')
            if (!rasterContext) {
              reject(new Error('Raster context unavailable'))
              return
            }
            rasterContext.imageSmoothingEnabled = true
            rasterContext.clearRect(0, 0, width, height)
            rasterContext.drawImage(image, 0, 0, width, height)
            const pixels = rasterContext.getImageData(0, 0, width, height)
            resolve({ width, height, data: pixels.data })
          } catch (error) {
            reject(error)
          } finally {
            URL.revokeObjectURL(url)
          }
        }
        image.onerror = () => {
          URL.revokeObjectURL(url)
          reject(new Error('Vector raster failed'))
        }
        image.src = url
      } catch (error) {
        URL.revokeObjectURL(url)
        reject(error)
      }
    })
  }

  async function pasteCostumeSelection() {
    // Dispatch-level commit-first for bitmap paste (button + keyboard entry):
    // commit BEFORE any dispatch/tool/canvas mutation. Leaves re-guard for
    // direct helper calls; this gate covers the dispatch window (including
    // the cross-format rasterize await) with stable-slot revalidation.
    // Disabled path stays await-free.
    if (BITMAP_PENDING_UI_ENABLED && costumeEditMode === 'bitmap') {
      const dispatchEpochTargetId = selectedTarget ? stableTargetId(selectedTarget) : ''
      const dispatchEpochIndex = selectedTarget?.currentCostume ?? 0
      const dispatchEpochSerial = bitmapCanvasReloadSerial
      const dispatchEpochGeneration = bitmapWorkspaceGeneration
      const dispatchEpochCanvas = bitmapCanvas
      const dispatchEpochRect = bitmapSelection ? { ...bitmapSelection } : undefined
      const dispatchEpochScope = selectedTarget ? captureDiscreteSaveScope(dispatchEpochTargetId, dispatchEpochIndex) : undefined
      const dispatchOk = await guardBitmapPendingCommitFirst('paint-paste')
      if (!dispatchOk) return
      const dispatchLiveId = selectedTarget ? stableTargetId(selectedTarget) : ''
      if (dispatchLiveId !== dispatchEpochTargetId || (selectedTarget?.currentCostume ?? 0) !== dispatchEpochIndex) {
        status = 'Bitmap paste blocked (target switched during pending commit; original preserved)'
        return
      }
      if (bitmapCanvasReloadSerial !== dispatchEpochSerial || bitmapWorkspaceGeneration !== dispatchEpochGeneration || bitmapCanvas !== dispatchEpochCanvas) {
        status = 'Bitmap paste blocked (canvas reloaded during pending commit; original preserved)'
        return
      }
      if (dispatchEpochScope && !isDiscreteSaveScopeCurrent(dispatchEpochScope, discreteSaveLiveOf(dispatchEpochScope))) {
        status = 'Bitmap paste blocked (workspace changed during pending commit; original preserved)'
        return
      }
      if (!bitmapSelection && dispatchEpochRect && dispatchEpochRect.width > 0 && dispatchEpochRect.height > 0) bitmapSelection = { ...dispatchEpochRect }
    }
    if (bitmapFloatingDragActive() && costumeEditMode === 'bitmap') {
      status = 'Finish the bitmap selection drag first'
      return
    }
    // Single-clipboard dispatch (copy-paste-hoc.jsx parity): the most recent
    // copy wins across modes; when it is unavailable the other clipboard
    // converts across (bitmap <-> vector) instead of no-op.
    if (costumeEditMode === 'vector') {
      if (clipboardRecency === 'bitmap' && bitmapClipboard) {
        await pasteBitmapClipboardAsVector()
        return
      }
      if (vectorClipboard.length > 0) {
        await pasteVectorSelection()
        return
      }
      await pasteBitmapClipboardAsVector()
      return
    }
    if (clipboardRecency === 'vector' && vectorClipboard.length > 0) {
      await pasteVectorClipboardAsBitmap()
      return
    }
    if (bitmapClipboard) {
      await pasteBitmapSelection()
      return
    }
    await pasteVectorClipboardAsBitmap()
  }

  // First/second fill-color swap (Scratch Paint parity): the hex pickers and
  // their transparent flags exchange together, so a transparent primary with
  // an opaque secondary round-trips exactly. Pure paint state only — never
  // touches artwork, history, clipboard, text drafts, or the eyedropper
  // overlay — so the button stays enabled unconditionally.
  function swapFillPaint() {
    const next = swapFillPaintState({
      primary: paintColor,
      primaryTransparent: fillTransparent,
      secondary: secondaryPaintColor,
      secondaryTransparent,
    })
    paintColor = next.primary
    fillTransparent = next.primaryTransparent
    secondaryPaintColor = next.secondary
    secondaryTransparent = next.secondaryTransparent
    status = 'Fill colors swapped'
  }

  // First/second stroke-color swap (Scratch Paint parity for the outline):
  // the stroke hex pickers and their transparent flags exchange together, so
  // a transparent primary with an opaque secondary round-trips exactly. Pure
  // paint state only — never touches artwork, history, clipboard, text
  // drafts, or the eyedropper overlay.
  function swapStrokePaint() {
    const next = swapStrokePaintState({
      primary: strokeColor,
      primaryTransparent: strokeTransparent,
      secondary: strokeSecondaryColor,
      secondaryTransparent: secondaryStrokeTransparent,
    })
    strokeColor = next.primary
    strokeTransparent = next.primaryTransparent
    strokeSecondaryColor = next.secondary
    secondaryStrokeTransparent = next.secondaryTransparent
    status = 'Stroke colors swapped'
  }

  // Zoom-aware keyboard nudge (scratch-paint `nudge-tool.js` parity).
  //
  // Reference behavior (clean-room, no AGPL copy):
  // - one arrow keydown translates by `1 / paper.view.zoom` document units
  //   (Shift x15), clamped into the action bounds with a 1px margin;
  // - `onUpdateImage` (the history commit) runs on keyup, so holding a key
  //   produces N keydown translations but a single history entry per
  //   press-release cycle.
  //
  // Current-editor mapping (screen-constant 1px plain / 15px Shift):
  // - vector SVG units reach the screen as `svg * 5 * viewportScale`, so one
  //   screen px is `1 / (5 * scale)` SVG units;
  // - bitmap canvas px reach the screen as `px * viewportScale`, so one
  //   screen px is `1 / scale` canvas px (fractional; the integer raster
  //   preview truncates toward zero, sub-pixel totals accumulate across
  //   repeats, and a fully sub-pixel single press stays a history-free
  //   no-op at high zoom).
  type NudgePending = {
    mode: 'bitmap' | 'vector'
    targetId: string
    targetName: string
    costumeIndex: number
    selectionKey: string
    totalDx: number
    totalDy: number
    appliedDx: number
    appliedDy: number
    entry: AssetHistoryEntry | undefined
    bitmapOrigin: { x: number; y: number; width: number; height: number } | undefined
    // Reshape-point nudge session (vector only): the owning editable unit,
    // the point selection at session start, and the selection epoch last
    // settled by our own previews. A user-driven point/object switch changes
    // the key/epoch without updating these, so the next keydown commits the
    // old session before starting a new one; our own previews update
    // `reshapeEpoch` after the refresh bump, keeping one entry per cycle.
    reshapeObjectIndex: number | undefined
    reshapePointIndices: number[] | undefined
    reshapeEpoch: number | undefined
  }
  let nudgePending: NudgePending | undefined = undefined
  let nudgeChain: Promise<void> = Promise.resolve()

  function nudgeViewportScale(): number {
    // Per-mode Paper band projection: clamp to the global minimum 0.1332
    // (vector floor 0.333/2.5) so the vector reset 0.2 / floor 0.1332 map
    // exactly. Legacy 0.25 clipped 1 screen px to 0.8 SVG units at 100%.
    // Bitmap res2 (0.333) / unknown (0.25) scales sit above this floor, so
    // their raster math (integer truncation, sub-pixel accumulation) is
    // unchanged. UI-band enforcement stays in the zoom paths, not here.
    return clampNudgeViewportScale(costumeViewportScale)
  }

  function currentNudgeSelectionKey(mode: 'bitmap' | 'vector'): string | undefined {
    if (mode === 'vector') {
      // Reshape owns the cycle while anchor points are selected: the key
      // names the owning unit plus the normalized point set, so a point or
      // object switch finalizes the old session before a new one starts.
      // The key is returned even when the points turn out non-editable; the
      // preview then fail-closes (no whole-object fallback) via `moved`.
      if (selectedVectorObjectIndex >= 0 && hasReshapeSegmentSelection()) {
        return reshapeNudgeSelectionKey(selectedVectorObjectIndex, reshapeLiveActionIndices())
      }
      const selection = normalizedVectorSelection(vectorObjects.length)
      if (selection.length === 0) return undefined
      return `v:${selection.join(',')}`
    }
    if (!bitmapSelection) return undefined
    return `b:${Math.round(bitmapSelection.x)},${Math.round(bitmapSelection.y)},${bitmapSelection.width}x${bitmapSelection.height}`
  }

  function isNudgeArrowKey(key: string): boolean {
    return key === 'ArrowLeft' || key === 'ArrowRight' || key === 'ArrowUp' || key === 'ArrowDown'
  }

  function commitNudgePendingSync(): void {
    const pending = nudgePending
    nudgePending = undefined
    if (!pending) {
      return
    }
    // No visible movement: leave undo/redo untouched (no-op protection for
    // sub-pixel bitmap presses, edge clamps, and empty deltas).
    if (!pending.appliedDx && !pending.appliedDy) {
      return
    }
    // Both modes already persisted every preview (vector via
    // updateVectorCostumeFromEditor, bitmap via updateBitmapCostumeFromCanvas
    // in the preview step), so closing the cycle only commits the peeked
    // entry. Canvas, VM, and the entry stay consistent even if a refresh
    // lands between preview and keyup. The commit is guard-checked: after a
    // scope switch/clear it is dropped with redo preserved.
    if (pending.entry) commitPaintHistory(pending.entry)
    // Vector nudge keeps the point selection untouched: the post-nudge
    // selection (same live anchors) becomes the prior for the next entry, so
    // a later delete->undo restores the nudged selection (oracle Scenario B).
    // Bitmap never writes reshape snapshots.
    try {
      if (pending.mode === 'vector' && pending.reshapePointIndices) {
        void currentSvgDocument(selectedTarget as ScratchTarget, pending.costumeIndex)
          .then(async (loaded) => {
            if (!loaded || !selectedTarget) return
            const key = selectedTarget.costumes[pending.costumeIndex]?.md5ext ?? selectedTarget.costumes[pending.costumeIndex]?.assetId
            const bytes = key ? await vm.loadAsset(key, selectedTarget.costumes[pending.costumeIndex]?.dataFormat ?? '') : undefined
            if (bytes) rememberCommittedReshapeSelection(pending.targetId, pending.costumeIndex, new Uint8Array(bytes))
          })
          .catch(() => undefined)
      }
    } catch {
      // Best-effort only.
    }
    status = pending.mode === 'vector' ? (pending.reshapePointIndices ? 'Vector path points nudged' : 'Vector objects nudged') : 'Bitmap selection moved'
  }

  async function flushNudgePending(): Promise<void> {
    // Chain the finalize behind in-flight previews so the commit always lands
    // after every queued translation (and its persist), and later peeks
    // observe the saved bytes.
    const finalize = async () => {
      const pending = nudgePending
      nudgePending = undefined
      if (!pending) return
      if (!pending.appliedDx && !pending.appliedDy) return
      if (pending.entry) commitPaintHistory(pending.entry)
      try {
        if (pending.mode === 'vector' && pending.reshapePointIndices && selectedTarget) {
          const liveTarget = selectedTarget
          const liveIndex = pending.costumeIndex
          const loaded = await currentSvgDocument(liveTarget, liveIndex)
          void loaded
          const key = liveTarget.costumes[liveIndex]?.md5ext ?? liveTarget.costumes[liveIndex]?.assetId
          const bytes = key ? await vm.loadAsset(key, liveTarget.costumes[liveIndex]?.dataFormat ?? '') : undefined
          if (bytes) rememberCommittedReshapeSelection(pending.targetId, liveIndex, new Uint8Array(bytes))
        }
      } catch {
        // Best-effort only.
      }
      status = pending.mode === 'vector' ? (pending.reshapePointIndices ? 'Vector path points nudged' : 'Vector objects nudged') : 'Bitmap selection moved'
    }
    nudgeChain = nudgeChain.then(finalize).catch(() => undefined)
    try {
      await nudgeChain
    } catch {
      // A failed preview/save still leaves the committed entry for what moved.
    }
  }

  function queueNudgeTask(task: () => Promise<void>): void {
    nudgeChain = nudgeChain.then(task).catch(() => undefined)
  }

  // Reshape-point nudge preview (one Arrow keydown): translate each live
  // selected anchor of the owning unit by the document delta in a single
  // Paper import/serialize pass, persist without capturing history (keyup
  // commits the peeked entry once), and keep the point selection untouched.
  // Fail-closed: text units, control-only/stale selections, singular
  // ancestors and CAS/external conflicts move nothing and never fall back
  // to translating the whole object.
  async function previewReshapePointNudge(pending: NudgePending, dx: number, dy: number): Promise<boolean> {
    if ((!dx && !dy) || !selectedTarget || isReshapeTextEditing()) return false
    const objectIndex = pending.reshapeObjectIndex
    if (objectIndex === undefined || objectIndex < 0) return false
    if (vectorPathPointDrag || vectorLeafTranslateDrag) {
      status = 'Finish the reshape drag first'
      return false
    }
    const owner = selectedTarget
    const targetId = stableTargetId(owner)
    if (targetId !== pending.targetId) return false
    const costumeIndex = owner.currentCostume ?? 0
    if (costumeIndex !== pending.costumeIndex) return false
    // Epoch/identity gate: a user-driven point/object switch after the task
    // was queued must not preview onto the new selection with old targets.
    if (pending.reshapeEpoch !== undefined && pending.reshapeEpoch !== reshapeSelectionSeq) return false
    if (selectedVectorObjectIndex !== objectIndex) return false
    const scope = captureDiscreteSaveScope(targetId, costumeIndex)
    const scopeAlive = () => isDiscreteSaveScopeCurrent(scope, discreteSaveLiveOf(scope))
    const loaded = await currentSvgDocument(owner, costumeIndex)
    if (!scopeAlive()) return false
    if (!loaded) return false
    if (!selectedTarget || stableTargetId(selectedTarget) !== targetId || (selectedTarget.currentCostume ?? 0) !== costumeIndex) return false
    if (selectedVectorObjectIndex !== objectIndex) return false
    if (pending.reshapeEpoch !== undefined && pending.reshapeEpoch !== reshapeSelectionSeq) return false
    const { doc, svg } = loaded
    const element = editableVectorUnits(svg)[objectIndex]
    if (!element || element.tagName.toLowerCase() === 'text') return false
    // Document-space targets from the live preview points (slot-stable
    // artwork: moves never add/remove slots, so indices stay valid across
    // repeats and only still-live anchors travel).
    const liveOwner = vectorObjects.find((object) => object.index === objectIndex)
    const livePoints = liveOwner?.points ?? []
    const indices = liveReshapeNudgeIndices(livePoints, pending.reshapePointIndices ?? [])
    if (indices.length === 0) return false
    const targets = reshapeNudgeTargets(livePoints, indices, dx, dy)
    if (targets.length === 0) return false
    if (!scopeAlive()) return false
    const result = await moveVectorReshapePoints(element, targets)
    if (!result.moved) return false
    if (!scopeAlive()) return false
    if (pending.reshapeEpoch !== undefined && pending.reshapeEpoch !== reshapeSelectionSeq) return false
    const live = vectorWriteTargetById(targetId, owner.name) ?? owner
    if (stableTargetId(live) !== targetId) return false
    const commit = await updateVectorCostumeFromEditor(live, costumeIndex, new XMLSerializer().serializeToString(doc.documentElement), { quiet: true, isAlive: scopeAlive })
    if (commit.kind !== 'applied') {
      if (scopeAlive() || (commit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(scope, discreteSaveLiveOf(scope)))) {
        selectedVectorObjectIndex = objectIndex
        selectedVectorObjectIndices = [objectIndex]
        await refreshVectorPreviewFromLive(targetId, live)
        reportVectorExternalConflict('Edit')
      }
      return false
    }
    if (!scopeAlive()) return false
    const nextSvg = commit.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (!scopeAlive()) return false
    // Slot-stable move: the same anchors are still selected. Do not rewrite
    // the selection (that would bump the epoch mid-cycle and split the
    // coalesced entry); only drop indices that stopped being live.
    const settled = vectorObjects.find((object) => object.index === objectIndex)
    const settledPoints = settled?.points ?? []
    const stillLive = (pending.reshapePointIndices ?? []).filter((index) => isReshapeAnchorLive(settledPoints, index))
    if (stillLive.length !== (pending.reshapePointIndices ?? []).length) {
      pending.reshapePointIndices = stillLive
    }
    selectedVectorObjectIndex = objectIndex
    selectedVectorObjectIndices = [objectIndex]
    await refreshCostumePreview(vectorWriteTargetById(targetId, owner.name) ?? owner)
    if (!scopeAlive()) return false
    // Our own refresh bumped the selection epoch: adopt it so the next
    // repeat in the same press-release cycle still matches.
    pending.reshapeEpoch = reshapeSelectionSeq
    status = 'Vector path points nudged'
    return true
  }

  async function previewVectorNudge(dx: number, dy: number): Promise<boolean> {
    if ((!dx && !dy) || !selectedTarget) return false
    // Reshape owns the arrow while anchor points are selected: translate the
    // points, never the whole object (fail-closed on non-editable targets).
    if (selectedVectorObjectIndex >= 0 && hasReshapeSegmentSelection()) {
      const reshapePending = nudgePending
      if (!reshapePending || reshapePending.mode !== 'vector' || !reshapePending.reshapePointIndices) return false
      return previewReshapePointNudge(reshapePending, dx, dy)
    }
    const loaded = await currentSvgDocument(selectedTarget, selectedTarget.currentCostume ?? 0)
    if (!loaded) return false
    if (normalizedVectorSelection(editableVectorUnits(loaded.svg).length).length === 0) return false
    const applied = await updateVectorObjects((element) => moveVectorElementBy(element, dx, dy), false)
    if (!applied) return false
    status = 'Vector objects nudged'
    return true
  }

  async function previewBitmapNudge(pending: NudgePending, dx: number, dy: number): Promise<boolean> {
    // Stale-canvas gate: the live canvas must still show the pending asset.
    // A switch/load in between aborts the preview so old pixels never move
    // on (or persist into) the new asset.
    if (!isBitmapWorkspaceSettledFor(pending.targetId, pending.costumeIndex)) return false
    if (selectedTarget && (stableTargetId(selectedTarget) !== pending.targetId || (selectedTarget.currentCostume ?? 0) !== pending.costumeIndex)) return false
    const context = bitmapCanvas?.getContext('2d')
    const origin = pending.bitmapOrigin
    if (!context || !bitmapCanvas || !origin || !bitmapSelection) return false
    if (bitmapFloatingDragActive()) return false
    const totalDx = pending.totalDx + dx
    const totalDy = pending.totalDy + dy
    const destX = Math.max(0, Math.min(bitmapCanvas.width - origin.width, Math.trunc(origin.x + totalDx)))
    const destY = Math.max(0, Math.min(bitmapCanvas.height - origin.height, Math.trunc(origin.y + totalDy)))
    if (destX === Math.trunc(bitmapSelection.x) && destY === Math.trunc(bitmapSelection.y)) {
      // Sub-pixel accumulation (or an edge clamp): totals still grow so a
      // later repeat can cross the next integer, but nothing visible changed.
      pending.totalDx = totalDx
      pending.totalDy = totalDy
      return false
    }
    // Source-over move (not verbatim putImageData): transparent patch pixels
    // must not erase the destination, and the source hole is punched first.
    const live = context.getImageData(0, 0, bitmapCanvas.width, bitmapCanvas.height)
    const session = beginBitmapFloatingSession(live, bitmapSelection)
    if (!session) return false
    const preview = previewBitmapFloatingMove(session, destX - bitmapSelection.x, destY - bitmapSelection.y)
    if (!preview.changed) {
      pending.totalDx = totalDx
      pending.totalDy = totalDy
      return false
    }
    context.putImageData(floatingImageToImageData(preview.image), 0, 0)
    bitmapSelection = { x: preview.destX, y: preview.destY, width: session.patch.width, height: session.patch.height }
    // Persist the previewed canvas under the pending entry immediately (no
    // history capture here). Canvas and VM must stay in sync after every
    // preview: a VM-backed refresh landing between preview and keyup would
    // otherwise reload stale bytes and wipe the uncommitted preview, and the
    // next peek would read a stale base. This matches the old per-keydown
    // save cost minus the history churn; keyup only commits the entry.
    const syncTarget = (pending.targetId ? vm.getTarget(pending.targetId) : undefined) ?? (pending.targetName ? vm.getTarget(pending.targetName) : undefined) ?? selectedTarget
    if (syncTarget && bitmapCanvas) {
      await updateBitmapCostumeFromCanvas(syncTarget, pending.costumeIndex, bitmapCanvas)
    }
    pending.totalDx = totalDx
    pending.totalDy = totalDy
    pending.appliedDx = preview.destX - origin.x
    pending.appliedDy = preview.destY - origin.y
    status = 'Bitmap selection moved'
    return true
  }

  async function handleArrowNudge(key: string, shift: boolean): Promise<void> {
    if (!selectedTarget || isReshapeTextEditing()) return
    if (bitmapFloatingDragActive() && costumeEditMode === 'bitmap') {
      status = 'Finish the bitmap selection drag first'
      return
    }
    // Pending staged rect/oval owns arrow nudge: parametric `moveBy` in
    // place (frozen base + single-pass repaint, no history, no VM, no
    // nudge-entry cycle). The history-free overlay must never create a
    // `nudgePending` entry for the pending shape.
    if (BITMAP_PENDING_UI_ENABLED && costumeEditMode === 'bitmap' && (bitmapTool === 'rect' || bitmapTool === 'oval')) {
      try {
        const pendingForNudge = ensureBitmapPendingController()?.get()
        if (pendingForNudge && pendingForNudge.snapshot().hasPending) {
          const modeForPending = costumeEditMode
          const scaleForPending = nudgeViewportScale()
          const stepForPending = referenceBitmapNudgeStep(scaleForPending, shift)
          if (!Number.isFinite(stepForPending) || stepForPending === 0) return
          const pdx = key === 'ArrowLeft' ? -stepForPending : key === 'ArrowRight' ? stepForPending : 0
          const pdy = key === 'ArrowUp' ? -stepForPending : key === 'ArrowDown' ? stepForPending : 0
          if (!pdx && !pdy) return
          const targetForPending = selectedTarget
          const targetIdForPending = stableTargetId(targetForPending)
          const costumeIndexForPending = targetForPending.currentCostume ?? 0
          if (!isBitmapWorkspaceSettledFor(targetIdForPending, costumeIndexForPending)) {
            refuseStaleBitmapWorkspace('Bitmap nudge')
            return
          }
          const nudgeResult = pendingForNudge.moveBy(pdx, pdy)
          if (!nudgeResult.ok) {
            const reason = (nudgeResult as { reason?: string }).reason ?? 'refused'
            if (reason === 'owner-mismatch' || reason === 'superseded' || reason === 'invalid-scope') {
              status = 'live canvas left untouched (draft owner changed or uncertain; reloader owns pixels)'
            }
            return
          }
          if (nudgeResult.kind !== 'unchanged') status = 'Bitmap selection moved'
          void modeForPending
          return
        }
      } catch {
        // Fall through to the legacy nudge path on unexpected failure.
      }
    }
    const mode = costumeEditMode
    const scale = nudgeViewportScale()
    // Reshape ignores Shift (no multiplier) and Alt (no clone): every arrow
    // travels one screen px. Select-mode keeps the Shift multiplier.
    const isReshapeNudge = mode === 'vector' && selectedVectorObjectIndex >= 0 && hasReshapeSegmentSelection()
    const step = mode === 'vector' ? (isReshapeNudge ? reshapeNudgeStep(scale) : referenceVectorNudgeStep(scale, shift)) : referenceBitmapNudgeStep(scale, shift)
    if (!Number.isFinite(step) || step === 0) return
    const dx = key === 'ArrowLeft' ? -step : key === 'ArrowRight' ? step : 0
    const dy = key === 'ArrowUp' ? -step : key === 'ArrowDown' ? step : 0
    if (!dx && !dy) return
    const target = selectedTarget
    const targetId = stableTargetId(target)
    const costumeIndex = target.currentCostume ?? 0
    const selectionKey = currentNudgeSelectionKey(mode)
    // No selection: no-op without history (input/focus guards live upstream;
    // typing targets return before arrows reach here).
    if (!selectionKey) return
    const task = async () => {
      if (isVectorRotateCancelActive()) await waitForVectorRotateCancel()
      // Bitmap nudge on an unsettled canvas would move stale pixels: refuse
      // the whole press-release cycle (no peek, no preview, no entry).
      if (mode === 'bitmap' && !isBitmapWorkspaceSettledFor(targetId, costumeIndex)) return
      // Target/mode/selection switched mid-press: finalize the previous
      // session first so its entry commits before the new session peeks.
      // Compared by stable target id so a sprite rename keeps the session.
      if (
        nudgePending &&
        (nudgePending.mode !== mode ||
          nudgePending.targetId !== targetId ||
          nudgePending.costumeIndex !== costumeIndex ||
          nudgePending.selectionKey !== selectionKey)
      ) {
        commitNudgePendingSync()
      }
      if (!nudgePending) {
        const entry = await peekCostumeHistory(target, costumeIndex)
        // Re-validate after the async peek: a switch/undo mid-peek must not
        // attach a stale entry to the new session.
        if (!selectedTarget || stableTargetId(selectedTarget) !== targetId || (selectedTarget.currentCostume ?? 0) !== costumeIndex) return
        if (currentNudgeSelectionKey(mode) !== selectionKey) return
        if (nudgePending) return
        // Reshape sessions pin the owning unit, the normalized point set and
        // the selection epoch; the Alt key never clones on this path.
        const reshapeActive = mode === 'vector' && selectedVectorObjectIndex >= 0 && hasReshapeSegmentSelection()
        nudgePending = {
          mode,
          targetId,
          targetName: target.name,
          costumeIndex,
          selectionKey,
          totalDx: 0,
          totalDy: 0,
          appliedDx: 0,
          appliedDy: 0,
          entry,
          bitmapOrigin: mode === 'bitmap' && bitmapSelection ? { ...bitmapSelection } : undefined,
          reshapeObjectIndex: reshapeActive ? selectedVectorObjectIndex : undefined,
          reshapePointIndices: reshapeActive ? reshapeLiveActionIndices() : undefined,
          reshapeEpoch: reshapeActive ? reshapeSelectionSeq : undefined,
        }
      }
      const pending = nudgePending
      if (!pending) return
      if (pending.mode !== mode) return
      if (mode === 'vector') {
        const moved = await previewVectorNudge(dx, dy)
        if (nudgePending !== pending) return
        if (moved) {
          pending.totalDx += dx
          pending.totalDy += dy
          pending.appliedDx += dx
          pending.appliedDy += dy
        } else if (!pending.appliedDx && !pending.appliedDy) {
          // Selection vanished mid-press: drop the empty session so redo
          // survives an undo-clean no-op.
          nudgePending = undefined
        }
      } else {
        const moved = await previewBitmapNudge(pending, dx, dy)
        if (nudgePending !== pending) return
        if (!moved && !pending.appliedDx && !pending.appliedDy) {
          // Keep sub-pixel totals accumulating (do NOT drop): later repeats
          // in the same press-release cycle can still cross the next integer.
        }
      }
    }
    queueNudgeTask(task)
    await nudgeChain
  }

  // Legacy direct-move entry point kept for non-keyboard callers. Keyboard
  // arrows go through handleArrowNudge (zoom-aware + keyup coalescing); this
  // preserves the old immediate-commit semantics for any other caller.
  async function nudgeCostumeSelection(dx: number, dy: number) {
    if (costumeEditMode === 'bitmap' && selectedTarget) {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        refuseStaleBitmapWorkspace('Bitmap nudge')
        return
      }
    }
    if (bitmapFloatingDragActive() && costumeEditMode === 'bitmap') {
      status = 'Finish the bitmap selection drag first'
      return
    }
    // Pending staged rect/oval: parametric nudge, no history, no VM write.
    if (BITMAP_PENDING_UI_ENABLED && costumeEditMode === 'bitmap' && (bitmapTool === 'rect' || bitmapTool === 'oval')) {
      try {
        const pendingForDirectNudge = ensureBitmapPendingController()?.get()
        if (pendingForDirectNudge && pendingForDirectNudge.snapshot().hasPending) {
          const directResult = pendingForDirectNudge.moveBy(dx, dy)
          if (directResult.ok && directResult.kind !== 'unchanged') status = 'Bitmap selection moved'
          return
        }
      } catch {
        // Fall through to the legacy path on unexpected failure.
      }
    }
    if (costumeEditMode === 'vector') {
      await moveSelectedVectorObjectBy(dx, dy)
      return
    }
    const context = bitmapCanvas?.getContext('2d')
    if (!context || !bitmapCanvas || !bitmapSelection) return
    const next = {
      x: Math.max(0, Math.min(bitmapCanvas.width - bitmapSelection.width, Math.round(bitmapSelection.x + dx))),
      y: Math.max(0, Math.min(bitmapCanvas.height - bitmapSelection.height, Math.round(bitmapSelection.y + dy))),
    }
    if (next.x === bitmapSelection.x && next.y === bitmapSelection.y) return
    // Source-over move (not verbatim putImageData): transparent patch pixels
    // must not erase the destination, and the source hole is punched first.
    const live = context.getImageData(0, 0, bitmapCanvas.width, bitmapCanvas.height)
    const session = beginBitmapFloatingSession(live, bitmapSelection)
    if (!session) return
    const preview = previewBitmapFloatingMove(session, next.x - bitmapSelection.x, next.y - bitmapSelection.y)
    if (!preview.changed) return
    context.putImageData(floatingImageToImageData(preview.image), 0, 0)
    bitmapSelection = { x: preview.destX, y: preview.destY, width: session.patch.width, height: session.patch.height }
    await saveBitmapCostume('Bitmap selection moved')
  }

  function selectVectorObject(index: number, append = false) {
    // A selection switch closes any pending nudge cycle first (sync commit
    // of what already moved; in-flight previews abort on identity mismatch).
    commitNudgePendingSync()
    commitHsvLivePendingSync()
    const previous = selectedVectorObjectIndex
    selectedVectorObjectIndex = index
    // Switching to another object drops the point selection: flattened
    // indices belong to one editable unit and must never leak across units.
    if (previous !== index) clearReshapeSelection()
    if (append) {
      selectedVectorObjectIndices = selectedVectorObjectIndices.includes(index)
        ? selectedVectorObjectIndices.filter((item) => item !== index)
        : [...selectedVectorObjectIndices, index].sort((a, b) => a - b)
    } else {
      selectedVectorObjectIndices = [index]
    }
    // Selection display only: changing the selection never rewrites the
    // artwork. Deselected presets (owner `none`) survive so
    // prepare-while-deselected then select then Apply keeps working; any
    // selection-derived dirty is dropped by the selection-key watcher.
    // Only an empty selection (Escape / artwork switch via
    // clearVectorObjectSelection) resets presets as well.
  }

  function clearVectorObjectSelection() {
    commitHsvLivePendingSync()
    selectedVectorObjectIndex = -1
    selectedVectorObjectIndices = []
    clearReshapeSelection()
    clearVectorStyleDirty()
  }

  function selectVectorReshapePoint(index: number | undefined) {
    setReshapeSelection(index === undefined ? [] : [index])
    if (index === undefined) clearReshapeLeafSelection()
    else void syncReshapeLeavesToPoints()
  }

  function selectVectorReshapePoints(indices: readonly number[]) {
    setReshapeSelection(indices)
    if (indices.length === 0) clearReshapeLeafSelection()
    else void syncReshapeLeavesToPoints()
  }

  function selectVectorReshapeLeaves(indices: readonly number[]) {
    setReshapeLeafSelection(indices)
  }

  // Compound-root normalization (reshape leaf -> select root): the select
  // tool addresses one selectable unit (the `<g>` root); reshape keeps
  // per-leaf addresses. Returning to select collapses any leaf set back to
  // its root without touching the DOM — the group object stays selected, the
  // leaf/point sets clear. Pure index arithmetic via
  // `normalizeLeafSelectionToRoot`; no history.
  function normalizeReshapeLeafToSelectRoot() {
    const normalized = normalizeLeafSelectionToRoot(selectedVectorObjectIndex, vectorReshapeLeafIndices)
    clearReshapeSelection()
    if (normalized.normalized) status = 'Group selected'
  }

  // Single-point click/Shift+click update for one anchor.
  // Plain click replaces; Shift toggles the anchor in/out (object-level
  // Shift toggle parity, but per anchor). Explicit clicks are flags7
  // (both handles). No history: selection only.
  function toggleVectorReshapePoint(index: number, append: boolean) {
    setReshapeSelectionWithMasks(toggleReshapeHandleSelection(vectorReshapeHandleMasks, index, append))
    void syncReshapeLeavesToPoints()
  }

  // Point marquee over the selected object's anchors plus curve crossings
  // (document coordinates — the same space as `VectorPathPointInfo.x/y`).
  // Plain drag replaces; Shift drag toggles. Anchors inside the rect select
  // individually; a curve crossing the rect with no anchor inside selects its
  // two endpoint anchors as a unit (`curve.selected` parity: the reference
  // auto-selects both ends, never handles alone). No history: selection only.
  // Paper curve matches are best-effort with stale guards; unreadable units
  // fall back to the DOM anchor-only marquee. Returns the new selection.
  async function selectVectorReshapePointsInRect(
    rect: { x: number; y: number; width: number; height: number },
    append = false,
  ): Promise<number[]> {
    const targetAtEntry = selectedTarget
    const targetIdAtEntry = targetAtEntry ? stableTargetId(targetAtEntry) : undefined
    const costumeAtEntry = targetAtEntry?.currentCostume ?? 0
    const objectAtEntry = selectedVectorObjectIndex
    const epochAtEntry = reshapeSelectionSeq
    const owner = vectorObjects.find((object) => object.index === objectAtEntry)
    const points = owner?.points ?? []
    const anchorFallback = reshapePointsInRect(points, rect)
    let paperMatch: { anchorFlats: number[]; curvePairs: Array<[number, number]> } | undefined | null = null
    try {
      if (targetAtEntry && objectAtEntry >= 0) {
        const loaded = await currentSvgDocument(targetAtEntry, costumeAtEntry)
        const stale =
          epochAtEntry !== reshapeSelectionSeq ||
          !selectedTarget ||
          stableTargetId(selectedTarget) !== targetIdAtEntry ||
          selectedVectorObjectIndex !== objectAtEntry ||
          (selectedTarget.currentCostume ?? 0) !== costumeAtEntry
        if (!stale && loaded) {
          const element = editableVectorUnits(loaded.svg)[objectAtEntry]
          if (element) paperMatch = await paperReshapeMarqueeFlatsInRect(element, rect)
        }
      }
    } catch {
      paperMatch = null
    }
    const staleAfter =
      epochAtEntry !== reshapeSelectionSeq ||
      !selectedTarget ||
      stableTargetId(selectedTarget) !== targetIdAtEntry ||
      selectedVectorObjectIndex !== objectAtEntry ||
      (selectedTarget.currentCostume ?? 0) !== costumeAtEntry
    if (staleAfter) return vectorReshapePointIndices
    if (paperMatch) {
      // Paper-truth masks: explicit anchors 7, curve pairs start 5 / end 3.
      // Indices stay derived so SVG bytes/history are untouched.
      setReshapeSelectionWithMasks(
        mergeReshapeMarqueeSelectionWithMasks(vectorReshapeHandleMasks, paperMatch.anchorFlats, paperMatch.curvePairs, append),
      )
    } else {
      setReshapeSelection(mergeReshapeMarqueeSelection(vectorReshapePointIndices, anchorFallback, append))
    }
    // Marquee never selects control handles (anchor-only, edges inclusive;
    // curve crossings contribute endpoint anchors only).
    void syncReshapeLeavesToPoints()
    return vectorReshapePointIndices
  }

  // Best-effort leaf/point sync: derive the leaf set owning the current
  // flattened anchor selection (one Paper import per anchor, user-paced
  // paths only). Ambiguous units and control/out-of-range slots clear the
  // leaf set fail-closed instead of naming the wrong child. Never touches
  // the artwork or history; guarded against target/costume/object switches
  // so a stale async resolve never rewrites a new selection.
  // Whole-leaf translate selections (`text`/`image` in mixed groups) carry
  // no anchor flats by design, so this anchor sync preserves them instead of
  // clearing: translate eligibility is checked first and returns early.
  async function syncReshapeLeavesToPoints() {
    if (!selectedTarget) return
    // Follower, not a ticket holder: capture the epoch and the point base.
    // Any newer selection write (rapid next click, switch, undo rebase)
    // invalidates this derivation; it must abort instead of overwriting.
    const epoch = reshapeSelectionSeq
    const targetId = stableTargetId(selectedTarget)
    const costumeIndex = selectedTarget.currentCostume ?? 0
    const objectIndex = selectedVectorObjectIndex
    const flats = [...vectorReshapePointIndices]
    const stale = () =>
      epoch !== reshapeSelectionSeq ||
      JSON.stringify(vectorReshapePointIndices) !== JSON.stringify(flats) ||
      !selectedTarget ||
      stableTargetId(selectedTarget) !== targetId ||
      selectedVectorObjectIndex !== objectIndex ||
      (selectedTarget.currentCostume ?? 0) !== costumeIndex
    if (objectIndex < 0 || flats.length === 0) {
      // Preserve whole-leaf translate selections: they intentionally hold
      // leaf indices with empty anchor flats.
      if (vectorReshapeLeafIndices.length === 0) return
      try {
        const loadedForTranslate = await currentSvgDocument(selectedTarget, costumeIndex)
        if (stale()) return
        if (loadedForTranslate) {
          const elementForTranslate = editableVectorUnits(loadedForTranslate.svg)[objectIndex]
          if (elementForTranslate && classifyGroupUnitForLeafTranslate(elementForTranslate).ok) return
        }
      } catch {
        // Fall through to clear on probe failure.
      }
      if (stale()) return
      clearReshapeLeafSelection()
      return
    }
    const loaded = await currentSvgDocument(selectedTarget, costumeIndex)
    if (stale()) return
    if (!loaded) return
    const element = editableVectorUnits(loaded.svg)[objectIndex]
    if (!element || element.tagName.toLowerCase() !== 'g') {
      if (vectorReshapeLeafIndices.length > 0) clearReshapeLeafSelection()
      return
    }
    if (!classifyGroupUnitForLeafReshape(element).ok) {
      try {
        if (classifyGroupUnitForLeafTranslate(element).ok) return
      } catch {
        // Fall through to clear.
      }
      if (vectorReshapeLeafIndices.length > 0) clearReshapeLeafSelection()
      return
    }
    const leaves = new Set<number>()
    for (const flat of flats) {
      let leaf: number | undefined
      try {
        leaf = await paperLeafIndexForFlatAnchor(element, flat)
      } catch {
        leaf = undefined
      }
      if (stale()) return
      if (leaf === undefined) {
        clearReshapeLeafSelection()
        return
      }
      leaves.add(leaf)
    }
    if (stale()) return
    setReshapeLeafSelection([...leaves])
  }

  // Group-leaf subselect for reshape: resolve a document-space click to one
  // child shape inside the selected `<g>` unit with a real Paper.js hitTest
  // (topmost wins, so overlaps name the painted-top child — never a bbox
  // guess), then narrow the point selection to exactly that leaf's anchors.
  // Plain click replaces (one leaf); Shift toggles the leaf in/out (multi).
  // Clicking the already-selected single leaf again keeps it (so a press can
  // start an anchor drag); Shift+click on the only selected leaf deselects.
  // Misses return false (caller falls through to curve-add/marquee); clip,
  // compound and ambiguous units report explicitly and return false with no
  // history and no selection change (fail-closed). Geometry-only units use
  // the anchor path; mixed groups with safe `text`/`image` leaves fall
  // through to the whole-leaf translate path below (single history, no
  // anchors). `use` stays fail-closed by design (shadow/filter complexity,
  // no live evidence). Drag-safety: refuses while a point/translate drag is
  // active, and re-checks target/costume/object identity after every await
  // so a switch mid-resolve never rewrites the new selection.
  async function selectVectorReshapeLeafAtPoint(
    point: { x: number; y: number },
    append = false,
    toleranceSvgUnits?: number,
  ): Promise<boolean> {
    if (!selectedTarget || selectedVectorObjectIndex < 0 || isReshapeTextEditing()) return false
    if (vectorPathPointDrag || vectorLeafTranslateDrag) return false
    // Ticket the intent up front: rapid consecutive leaf clicks each hold a
    // ticket, and only the newest may write. An older click resolving later
    // sees its ticket superseded and aborts instead of overwriting the newer
    // selection (last-starter-wins). Any selection write in between — toggle,
    // marquee, collapse, undo rebase, switch clear — supersedes as well.
    // A click that changes nothing (miss/unsupported) re-syncs leaves on its
    // way out so an in-flight derivation it superseded is recomputed.
    const ticket = (reshapeSelectionSeq += 1)
    const superseded = () => ticket !== reshapeSelectionSeq
    const targetName = selectedTarget.name
    const costumeIndex = selectedTarget.currentCostume ?? 0
    const objectIndex = selectedVectorObjectIndex
    const switched = () =>
      !selectedTarget || selectedTarget.name !== targetName || selectedVectorObjectIndex !== objectIndex || (selectedTarget.currentCostume ?? 0) !== costumeIndex
    const loaded = await currentSvgDocument(selectedTarget, costumeIndex)
    // A superseded or switched click must not fall through to point-add:
    // report handled so the overlay never splits a curve from a stale hit.
    // The newest selection intent (or the new artwork) already owns the state.
    if (superseded() || switched()) return true
    if (!loaded) {
      void syncReshapeLeavesToPoints()
      return false
    }
    const element = editableVectorUnits(loaded.svg)[objectIndex]
    if (!element || element.tagName.toLowerCase() !== 'g') {
      void syncReshapeLeavesToPoints()
      return false
    }
    const eligibility = classifyGroupUnitForLeafReshape(element)
    if (!eligibility.ok) {
      return await selectVectorTranslateLeafAtPoint(
        element,
        point,
        append,
        toleranceSvgUnits,
        ticket,
        superseded,
        switched,
      )
    }
    const tolerance =
      Number.isFinite(toleranceSvgUnits) && (toleranceSvgUnits as number) >= 0
        ? (toleranceSvgUnits as number)
        : resolveVectorHitTolerance()
    let hit: Awaited<ReturnType<typeof paperGroupLeafHitAtPoint>>
    try {
      hit = await paperGroupLeafHitAtPoint(element, point, tolerance)
    } catch {
      void syncReshapeLeavesToPoints()
      return false
    }
    if (superseded() || switched()) return true
    if (hit.kind === 'miss' || hit.kind === 'import-failed') {
      void syncReshapeLeavesToPoints()
      return false
    }
    if (hit.kind === 'unsupported') {
      status = `Reshape leaf: ${hit.reason}`
      void syncReshapeLeavesToPoints()
      return false
    }
    // Re-read the leaf base only after proving this ticket is still newest,
    // so a rapid earlier click never toggles from a stale set.
    const current = [...vectorReshapeLeafIndices]
    // Curve click on the already solely-selected leaf splits the curve
    // (Scratch parity: selected-stroke/curve clicks add a point) instead of
    // re-selecting: return false so the caller falls through to point-add,
    // which selects the new anchor and re-syncs leaves. Fill clicks and
    // unselected/Shift clicks always (de)select the leaf.
    if (
      !append &&
      current.length === 1 &&
      current[0] === hit.leafIndex &&
      (hit.hitType === 'curve' || hit.hitType === 'stroke')
    ) {
      void syncReshapeLeavesToPoints()
      return false
    }
    const nextLeaves =
      append
        ? current.includes(hit.leafIndex)
          ? current.filter((leaf) => leaf !== hit.leafIndex)
          : [...current, hit.leafIndex]
        : [hit.leafIndex]
    const clean = normalizeReshapeSelection(nextLeaves)
    if (clean.length === 0) {
      clearReshapeSelection()
      status = 'Reshape leaf deselected'
      return true
    }
    let flats: number[] | undefined
    try {
      flats = await paperFlatAnchorIndicesForGroupLeaves(element, clean) ?? undefined
    } catch {
      flats = undefined
    }
    if (superseded() || switched()) return true
    if (!flats) {
      status = 'Reshape leaf: ambiguous identity (fail-closed)'
      void syncReshapeLeavesToPoints()
      return false
    }
    setReshapeLeafSelection(clean)
    setReshapeSelection(flats)
    status = clean.length > 1 ? `Reshape leaves selected (${clean.length})` : 'Reshape leaf selected'
    return true
  }

  // Whole-leaf translate subselect for mixed groups (geometry + safe
  // `text`/`image`). Uses the real Paper translate hit (topmost wins) and
  // selects leaf indices with empty anchor flats: the drag moves each leaf
  // atomically via `planLeafDocumentTranslate` (prepend `translate()`), so
  // siblings, Z-order, fonts, gradients, opacity, tspan/defs/clip and
  // sanitize survive. `use` never selects here (fail-closed upstream, and
  // re-checked per leaf below). No history, no DOM write; ticket/switch
  // guards mirror the anchor path so stale clicks never rewrite new state.
  async function selectVectorTranslateLeafAtPoint(
    element: Element,
    point: { x: number; y: number },
    append: boolean,
    toleranceSvgUnits: number | undefined,
    ticket: number,
    superseded: () => boolean,
    switched: () => boolean,
  ): Promise<boolean> {
    const translateEligibility = classifyGroupUnitForLeafTranslate(element)
    if (!translateEligibility.ok) {
      status = `Reshape leaf: ${translateEligibility.reason}`
      void syncReshapeLeavesToPoints()
      return false
    }
    const tolerance =
      Number.isFinite(toleranceSvgUnits) && (toleranceSvgUnits as number) >= 0
        ? (toleranceSvgUnits as number)
        : resolveVectorHitTolerance()
    let hit: Awaited<ReturnType<typeof paperGroupTranslateLeafHitAtPoint>>
    try {
      hit = await paperGroupTranslateLeafHitAtPoint(element, point, tolerance)
    } catch {
      void syncReshapeLeavesToPoints()
      return false
    }
    if (superseded() || switched()) return true
    if (hit.kind === 'miss' || hit.kind === 'import-failed') {
      void syncReshapeLeavesToPoints()
      return false
    }
    if (hit.kind === 'unsupported') {
      status = `Reshape leaf: ${hit.reason}`
      void syncReshapeLeavesToPoints()
      return false
    }
    // Per-leaf safety: `use` stays fail-closed even if the planner would
    // admit it (shadow/filter complexity, no live evidence). Only
    // geometry/text/image move as a whole.
    try {
      const domLeaves = groupTranslateLeafTargetsInOrder(element)
      const leaf = domLeaves?.[hit.leafIndex]
      if (!leaf) {
        status = 'Reshape leaf: ambiguous identity (fail-closed)'
        void syncReshapeLeavesToPoints()
        return false
      }
      const leafEligibility = classifyLeafElementForTranslate(leaf)
      if (!leafEligibility.ok) {
        status = `Reshape leaf: ${leafEligibility.reason}`
        void syncReshapeLeavesToPoints()
        return false
      }
      if (leafEligibility.ok && (leafEligibility as { kind?: string }).kind === 'use') {
        status = 'Reshape leaf: use in group is not translatable (fail-closed)'
        void syncReshapeLeavesToPoints()
        return false
      }
    } catch {
      status = 'Reshape leaf: leaf probe failed (fail-closed)'
      void syncReshapeLeavesToPoints()
      return false
    }
    const current = [...vectorReshapeLeafIndices]
    const nextLeaves = append
      ? current.includes(hit.leafIndex)
        ? current.filter((leafIndex) => leafIndex !== hit.leafIndex)
        : [...current, hit.leafIndex]
      : [hit.leafIndex]
    const clean = normalizeReshapeSelection(nextLeaves)
    if (clean.length === 0) {
      clearReshapeSelection()
      status = 'Reshape leaf deselected'
      return true
    }
    // Whole-leaf moves carry no anchor flats by design (text/image have no
    // anchors; geometry in mixed groups moves via prepend, not anchor edits).
    setReshapeLeafSelection(clean)
    setReshapeSelection([])
    status = clean.length > 1 ? `Reshape leaves selected (${clean.length})` : 'Reshape leaf selected'
    return true
  }

  async function selectVectorObjectsInRect(rect: { x: number; y: number; width: number; height: number }, append = false) {
    const previousObject = selectedVectorObjectIndex
    let matches = await paperVectorMatchesInRect(rect)
    matches ??= vectorObjects
      .filter((object) => vectorObjectIntersectsRect(object, rect))
      .map((object) => object.index)
      .sort((a, b) => a - b)
    if (append) {
      // Mirror scratch-paint's shift+marquee: matched items toggle instead of only being added.
      const matched = new Set(matches)
      const kept = selectedVectorObjectIndices.filter((index) => !matched.has(index))
      const added = matches.filter((index) => !selectedVectorObjectIndices.includes(index))
      selectedVectorObjectIndices = [...kept, ...added].sort((a, b) => a - b)
    } else {
      selectedVectorObjectIndices = matches
    }
    selectedVectorObjectIndex = selectedVectorObjectIndices.at(-1) ?? -1
    // Same as select-all above: marquee selection never rewrites the artwork.
    // Deselected presets survive via the selection-key watcher while
    // selection-derived dirty is dropped.
    // A point selection belongs to one object; an object switch drops it.
    if (previousObject !== selectedVectorObjectIndex) clearReshapeSelection()
  }

  async function paperVectorMatchesInRect(rect: { x: number; y: number; width: number; height: number }): Promise<number[] | undefined> {
    if (!selectedTarget) return undefined
    const loaded = await currentSvgDocument(selectedTarget, selectedTarget.currentCostume ?? 0)
    if (!loaded) return undefined
    try {
      return await paperVectorIndicesInRect(editableVectorUnits(loaded.svg), rect)
    } catch {
      return undefined
    }
  }

  function vectorObjectIntersectsRect(object: VectorObjectInfo, rect: { x: number; y: number; width: number; height: number }) {
    const left = object.boundsX ?? object.x ?? 0
    const top = object.boundsY ?? object.y ?? 0
    const width = object.boundsWidth ?? object.width ?? 0
    const height = object.boundsHeight ?? object.height ?? 0
    const right = left + width
    const bottom = top + height
    return right >= rect.x && left <= rect.x + rect.width && bottom >= rect.y && top <= rect.y + rect.height
  }

  function resolveVectorHitTolerance(explicitTolerance?: number): number {
    // Zoom-aware select budget: 2 screen px divided by the live surface
    // scale. Callers pass the layout-measured value when they have it
    // (pointer handlers); keyboard/text paths without a rect fall back to the
    // bound viewport scale, then to the legacy fixed tolerance.
    if (Number.isFinite(explicitTolerance) && (explicitTolerance as number) >= 0) return explicitTolerance as number
    try {
      return vectorSelectToleranceSvgUnits(nudgeViewportScale())
    } catch {
      return 0.5
    }
  }

  async function vectorObjectIndexAtPoint(point: { x: number; y: number }, toleranceSvgUnits?: number) {
    if (selectedTarget) {
      const loaded = await currentSvgDocument(selectedTarget, selectedTarget.currentCostume ?? 0)
      if (loaded) {
        try {
          // A clean miss returns -1; only fall back when paper itself fails.
          return await paperVectorHitIndex(editableVectorUnits(loaded.svg), point, resolveVectorHitTolerance(toleranceSvgUnits))
        } catch {
          // Fall through to the bounding-box check below.
        }
      }
    }
    const found = [...vectorObjects].reverse().find((object) => {
      const left = object.boundsX ?? object.x ?? 0
      const top = object.boundsY ?? object.y ?? 0
      const width = object.boundsWidth ?? object.width ?? 0
      const height = object.boundsHeight ?? object.height ?? 0
      return point.x >= left && point.x <= left + width && point.y >= top && point.y <= top + height
    })
    return found?.index ?? -1
  }

  function normalizedVectorSelection(length: number) {
    const fromMulti = selectedVectorObjectIndices.filter((index) => index >= 0 && index < length)
    if (fromMulti.length > 0) return [...new Set(fromMulti)].sort((a, b) => a - b)
    return selectedVectorObjectIndex >= 0 && selectedVectorObjectIndex < length ? [selectedVectorObjectIndex] : []
  }

  // Read-only selection summary for the MIXED UI. Parses the sanitized
  // display SVG (already in memory as `costumePreviewSvg`) with no history,
  // no canvas, and no document writes. Effective resolution honors inline
  // `style` over presentation attributes, ancestor inheritance, and
  // `fill-opacity` / `stroke-opacity` / chained `opacity`; `class`,
  // unparsable, or fallback-less `url()` paints fail closed to per-field
  // MIXED so selective apply can skip exactly the unknown side.
  function computeVectorSelectionDetailedPaints(svgText: string, indices: number[]): DetailedVectorElementPaint[] {
    if (indices.length === 0 || !svgText) return []
    try {
      const doc = new DOMParser().parseFromString(svgText, 'image/svg+xml')
      const svg = doc.documentElement
      if (svg.nodeName.toLowerCase() !== 'svg' || doc.getElementsByTagName('parsererror').length > 0) return []
      const units = editableVectorUnits(svg)
      const resolveGradient = (id: string) => {
        if (!id) return undefined
        let def: Element | null = null
        try {
          def = typeof (doc as Document).getElementById === 'function' ? (doc as Document).getElementById(id) : null
        } catch {
          def = null
        }
        if (!def) {
          try {
            def = svg.querySelector(`linearGradient[id="${id}"]`) ?? svg.querySelector(`radialGradient[id="${id}"]`)
          } catch {
            def = null
          }
        }
        if (!def) return undefined
        const tag = def.tagName.toLowerCase() === 'radialgradient' ? 'radialGradient' : 'linearGradient'
        return readGradientDefFromElement(def as unknown as Parameters<typeof readGradientDefFromElement>[0], tag)
      }
      return indices
        .map((index) => units[index])
        .filter((element): element is Element => Boolean(element))
        .map((element) =>
          readVectorElementPaintDetailed(element as unknown as Parameters<typeof readVectorElementPaintDetailed>[0], resolveGradient),
        )
    } catch {
      return []
    }
  }

  function computeVectorSelectionSummary(svgText: string, indices: number[]): VectorSelectionSummary | undefined {
    if (indices.length === 0 || !svgText) return undefined
    const paints = computeVectorSelectionDetailedPaints(svgText, indices)
    if (paints.length === 0) return undefined
    return summarizeDetailedVectorElementPaints(paints)
  }

  let vectorSelectionSummary: VectorSelectionSummary | undefined = undefined
  let vectorSelectionHasUnresolvable = false
  $: {
    // Explicit subscriptions: `normalizedVectorSelection` reads the
    // selection arrays inside its body, which legacy `$:` would not
    // otherwise track, so selection changes alone would never refresh.
    const summaryAnchor = selectedVectorObjectIndex
    const summaryIndicesList = selectedVectorObjectIndices
    const summaryUnitsLength = vectorObjects.length
    const summarySvg = costumePreviewSvg
    void summaryAnchor
    void summaryIndicesList
    const summaryIndices = normalizedVectorSelection(summaryUnitsLength)
    if (summaryIndices.length === 0) {
      vectorSelectionSummary = undefined
      vectorSelectionHasUnresolvable = false
    } else {
      const detailed = computeVectorSelectionDetailedPaints(summarySvg, summaryIndices)
      vectorSelectionSummary = detailed.length === 0 ? undefined : summarizeDetailedVectorElementPaints(detailed)
      vectorSelectionHasUnresolvable = detailed.some((paint) => isDetailedPaintUnknown(paint))
    }
  }

  function buildVectorStylePatchFromDirty(): VectorStylePatch {
    const patch: VectorStylePatch = {}
    if (vectorStyleDirty.includes('fill')) patch.fill = fillPaintInput(fillTransparent, paintColor)
    if (vectorStyleDirty.includes('fillSecondary') && paintGradient !== 'solid') {
      patch.fillSecondary = secondaryPaintInput(secondaryTransparent, secondaryPaintColor)
    }
    if (vectorStyleDirty.includes('fillGradient')) patch.fillGradient = paintGradient
    if (vectorStyleDirty.includes('stroke')) patch.stroke = strokePrimaryInput(strokeTransparent, strokeColor)
    if (vectorStyleDirty.includes('strokeSecondary') && strokeGradient !== 'solid') {
      patch.strokeSecondary = strokeSecondaryInput(secondaryStrokeTransparent, strokeSecondaryColor)
    }
    if (vectorStyleDirty.includes('strokeGradient')) patch.strokeGradient = strokeGradient
    if (vectorStyleDirty.includes('strokeWidth')) patch.strokeWidth = clampStrokeWidth(strokeWidth)
    if (vectorStyleDirty.includes('opacity')) patch.opacity = Math.max(0, Math.min(100, vectorOpacity))
    return patch
  }

  async function updateVectorObjectNumber(field: 'x' | 'y' | 'width' | 'height', event: Event) {
    const value = Number((event.currentTarget as HTMLInputElement).value)
    if (!Number.isFinite(value)) return
    await updateVectorObject((element) => setVectorNumericAttribute(element, field, value))
  }

  async function updateVectorObjectStrokeWidth(event: Event) {
    const value = Number((event.currentTarget as HTMLInputElement).value)
    if (!Number.isFinite(value)) return
    strokeWidth = clampStrokeWidth(value)
    const writeOwner = currentVectorStyleSelectionKey()
    markVectorStyleDirty('strokeWidth')
    if (costumeEditMode === 'vector' && selectedVectorObjectIndex >= 0 && selectedTarget) {
      // Same-value guard: writing the width every unit already has would
      // otherwise capture history for a no-op and leave an empty Undo step.
      try {
        const checkLoaded = await currentSvgDocument(selectedTarget, selectedTarget.currentCostume ?? 0)
        if (checkLoaded) {
          const checkUnits = editableVectorUnits(checkLoaded.svg)
          const checkIndices = normalizedVectorSelection(checkUnits.length)
          const checkResolveGradient = (id: string) => {
            if (!id) return undefined
            const def = (checkLoaded.doc as Document).getElementById?.(id) as Element | null
            if (!def) return undefined
            const tag = def.tagName.toLowerCase() === 'radialgradient' ? 'radialGradient' : 'linearGradient'
            return readGradientDefFromElement(def as unknown as Parameters<typeof readGradientDefFromElement>[0], tag)
          }
          let allSameWidth = checkIndices.length > 0
          for (const checkIndex of checkIndices) {
            const checkChild = checkUnits[checkIndex]
            if (!checkChild) {
              allSameWidth = false
              break
            }
            const checkDetailed = readVectorElementPaintDetailed(
              checkChild as unknown as Parameters<typeof readVectorElementPaintDetailed>[0],
              checkResolveGradient,
            )
            if (isMixedSelectionValue(checkDetailed.strokeWidth) || Math.abs((checkDetailed.strokeWidth as number) - strokeWidth) >= 1e-9) {
              allSameWidth = false
              break
            }
          }
          if (allSameWidth) {
            if ((vectorStyleDirtyOwner['strokeWidth'] ?? VECTOR_STYLE_DESELECTED_KEY) === writeOwner)
              consumeVectorStyleDirty('strokeWidth')
            status = 'No paint change to apply'
            return
          }
        }
      } catch {
        // Fall through to the write path on read failure.
      }
      await updateVectorObjects((element) => {
        element.setAttribute('stroke-width', String(svgWidthForElement(element, strokeWidth)))
        // Inline `style="stroke-width:…"` beats the attribute; clear it so
        // the width edit takes effect without touching paint sides.
        try {
          const raw = element.getAttribute('style')
          if (raw && /(^|;)\s*stroke-width\s*:/i.test(raw)) {
            const keep = raw
              .split(';')
              .map((part) => part.trim())
              .filter((part) => part.length > 0 && !/^\s*stroke-width\s*:/i.test(part))
            if (keep.length === 0) element.removeAttribute('style')
            else element.setAttribute('style', `${keep.join('; ')};`)
          }
        } catch {}
      })
      // Immediate write-through: only consume when the selection did not
      // change mid-write, so a newer dirty for the new selection survives.
      if ((vectorStyleDirtyOwner['strokeWidth'] ?? VECTOR_STYLE_DESELECTED_KEY) === writeOwner) consumeVectorStyleDirty('strokeWidth')
    }
  }

  async function updateVectorObjectOpacity(event: Event) {
    const value = Number((event.currentTarget as HTMLInputElement).value)
    if (!Number.isFinite(value)) return
    vectorOpacity = Math.max(0, Math.min(100, value))
    const writeOwner = currentVectorStyleSelectionKey()
    markVectorStyleDirty('opacity')
    if (costumeEditMode === 'vector' && selectedVectorObjectIndex >= 0 && selectedTarget) {
      // Same-value guard (mirrors the stroke-width path): an opacity every
      // selected unit already has must stay undo-clean.
      try {
        const checkLoaded = await currentSvgDocument(selectedTarget, selectedTarget.currentCostume ?? 0)
        if (checkLoaded) {
          const checkUnits = editableVectorUnits(checkLoaded.svg)
          const checkChild = checkUnits[selectedVectorObjectIndex]
          if (checkChild) {
            const checkResolveGradient = (id: string) => {
              if (!id) return undefined
              const def = (checkLoaded.doc as Document).getElementById?.(id) as Element | null
              if (!def) return undefined
              const tag = def.tagName.toLowerCase() === 'radialgradient' ? 'radialGradient' : 'linearGradient'
              return readGradientDefFromElement(def as unknown as Parameters<typeof readGradientDefFromElement>[0], tag)
            }
            const checkDetailed = readVectorElementPaintDetailed(
              checkChild as unknown as Parameters<typeof readVectorElementPaintDetailed>[0],
              checkResolveGradient,
            )
            if (
              !isMixedSelectionValue(checkDetailed.opacity) &&
              Math.abs((checkDetailed.opacity as number) - vectorOpacity) < 1e-9
            ) {
              if ((vectorStyleDirtyOwner['opacity'] ?? VECTOR_STYLE_DESELECTED_KEY) === writeOwner)
                consumeVectorStyleDirty('opacity')
              status = 'No paint change to apply'
              return
            }
          }
        }
      } catch {
        // Fall through to the write path on read failure.
      }
      await updateVectorObject((element) => {
        element.setAttribute('opacity', String(vectorOpacity / 100))
        try {
          const raw = element.getAttribute('style')
          if (raw && /(^|;)\s*opacity\s*:/i.test(raw)) {
            const keep = raw
              .split(';')
              .map((part) => part.trim())
              .filter((part) => part.length > 0 && !/^\s*opacity\s*:/i.test(part))
            if (keep.length === 0) element.removeAttribute('style')
            else element.setAttribute('style', `${keep.join('; ')};`)
          }
        } catch {}
      })
      if ((vectorStyleDirtyOwner['opacity'] ?? VECTOR_STYLE_DESELECTED_KEY) === writeOwner) consumeVectorStyleDirty('opacity')
    }
  }

  async function updateVectorObjectRotation(event: Event) {
    const value = Number((event.currentTarget as HTMLInputElement).value)
    if (!Number.isFinite(value)) return
    await updateVectorObject((element) => setVectorRotation(element, value))
  }

  async function rotateSelectedVectorObject(delta: number) {
    if (!selectedTarget || !Number.isFinite(delta) || delta === 0) return
    const rotateOwner = selectedTarget
    const rotateTargetId = stableTargetId(rotateOwner)
    const costumeIndex = rotateOwner.currentCostume ?? 0
    const rotateScope = captureDiscreteSaveScope(rotateTargetId, costumeIndex)
    const rotateScopeAlive = () => isDiscreteSaveScopeCurrent(rotateScope, discreteSaveLiveOf(rotateScope))
    const loaded = await currentSvgDocument(rotateOwner, costumeIndex)
    if (!rotateScopeAlive()) return
    if (!loaded) return
    const selectedIndices = normalizedVectorSelection(editableVectorUnits(loaded.svg).length)
    if (selectedIndices.length <= 1) {
      await updateVectorObject((element) => applyPaperRotation(element, delta))
      return
    }
    const units = editableVectorUnits(loaded.svg)
    const elements = selectedIndices.map((index) => units[index]).filter((element): element is Element => Boolean(element))
    if (elements.length < 2) return
    const bounds = await vectorSelectionBounds(elements)
    if (!rotateScopeAlive()) return
    if (!bounds) return
    const center = { x: bounds.centerX, y: bounds.centerY }
    const keptIndices = [...selectedIndices]
    const keptIndex = selectedVectorObjectIndex
    const pendingRotateHistory = await peekCostumeHistory(rotateOwner, costumeIndex)
    if (!rotateScopeAlive()) return
    if (!rotateVectorElementsAroundCenter(elements, delta, center)) return
    if (!rotateScopeAlive()) return
    const rotateLiveOwner = vectorWriteTargetById(rotateTargetId, rotateOwner.name) ?? rotateOwner
    if (stableTargetId(rotateLiveOwner) !== rotateTargetId) return
    const rotateCommit = await updateVectorCostumeFromEditor(rotateLiveOwner, costumeIndex, new XMLSerializer().serializeToString(loaded.doc.documentElement), { quiet: true, isAlive: rotateScopeAlive })
    if (rotateCommit.kind !== 'applied') {
      if (rotateScopeAlive() || (rotateCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(rotateScope, discreteSaveLiveOf(rotateScope)))) {
        await refreshVectorPreviewFromLive(rotateTargetId, rotateLiveOwner)
        reportVectorExternalConflict('Edit')
      }
      return
    }
    if (!rotateScopeAlive()) return
    if (pendingRotateHistory) commitPaintHistory(pendingRotateHistory)
    if (!rotateScopeAlive()) return
    const nextSvg = rotateCommit.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (!rotateScopeAlive()) return
    selectedVectorObjectIndices = keptIndices.filter((item) => vectorObjects.some((object) => object.index === item))
    selectedVectorObjectIndex = selectedVectorObjectIndices.includes(keptIndex) ? keptIndex : (selectedVectorObjectIndices.at(-1) ?? -1)
    await refreshCostumePreview(vectorWriteTargetById(rotateTargetId, rotateOwner.name) ?? rotateOwner)
    if (!rotateScopeAlive()) return
    try {
      rememberCommittedReshapeSelection(rotateTargetId, costumeIndex, new TextEncoder().encode(nextSvg))
    } catch {
      // Best-effort only.
    }
    status = 'Vector objects updated'
  }

  async function flipSelectedVectorObject(horizontal: boolean) {
    if (!selectedTarget) return
    const flipOwner = selectedTarget
    const flipTargetId = stableTargetId(flipOwner)
    const costumeIndex = flipOwner.currentCostume ?? 0
    const flipScope = captureDiscreteSaveScope(flipTargetId, costumeIndex)
    const flipScopeAlive = () => isDiscreteSaveScopeCurrent(flipScope, discreteSaveLiveOf(flipScope))
    const loaded = await currentSvgDocument(flipOwner, costumeIndex)
    if (!flipScopeAlive()) return
    if (!loaded) return
    const selectedIndices = normalizedVectorSelection(editableVectorUnits(loaded.svg).length)
    if (selectedIndices.length <= 1) {
      await updateVectorObject((element) => applyPaperFlip(element, horizontal))
      return
    }
    const units = editableVectorUnits(loaded.svg)
    const elements = selectedIndices.map((index) => units[index]).filter((element): element is Element => Boolean(element))
    if (elements.length < 2) return
    const bounds = await vectorSelectionBounds(elements)
    if (!flipScopeAlive()) return
    if (!bounds) return
    const center = { x: bounds.centerX, y: bounds.centerY }
    const keptIndices = [...selectedIndices]
    const keptIndex = selectedVectorObjectIndex
    const pendingFlipHistory = await peekCostumeHistory(flipOwner, costumeIndex)
    if (!flipScopeAlive()) return
    if (!flipVectorElementsAroundCenter(elements, horizontal, center)) return
    if (!flipScopeAlive()) return
    const flipLiveOwner = vectorWriteTargetById(flipTargetId, flipOwner.name) ?? flipOwner
    if (stableTargetId(flipLiveOwner) !== flipTargetId) return
    const flipCommit = await updateVectorCostumeFromEditor(flipLiveOwner, costumeIndex, new XMLSerializer().serializeToString(loaded.doc.documentElement), { quiet: true, isAlive: flipScopeAlive })
    if (flipCommit.kind !== 'applied') {
      if (flipScopeAlive() || (flipCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(flipScope, discreteSaveLiveOf(flipScope)))) {
        await refreshVectorPreviewFromLive(flipTargetId, flipLiveOwner)
        reportVectorExternalConflict('Edit')
      }
      return
    }
    if (!flipScopeAlive()) return
    if (pendingFlipHistory) commitPaintHistory(pendingFlipHistory)
    if (!flipScopeAlive()) return
    const nextSvg = flipCommit.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (!flipScopeAlive()) return
    selectedVectorObjectIndices = keptIndices.filter((item) => vectorObjects.some((object) => object.index === item))
    selectedVectorObjectIndex = selectedVectorObjectIndices.includes(keptIndex) ? keptIndex : (selectedVectorObjectIndices.at(-1) ?? -1)
    await refreshCostumePreview(vectorWriteTargetById(flipTargetId, flipOwner.name) ?? flipOwner)
    if (!flipScopeAlive()) return
    try {
      rememberCommittedReshapeSelection(flipTargetId, costumeIndex, new TextEncoder().encode(nextSvg))
    } catch {
      // Best-effort only.
    }
    status = 'Vector objects updated'
  }

  async function updateVectorObjectText(event: Event) {
    const value = (event.currentTarget as HTMLInputElement).value
    await updateVectorObject((element) => {
      if (element.tagName.toLowerCase() === 'text') element.textContent = value
    })
  }

  // Inline text editing (canvas overlay in BitmapEditor.svelte):
  // - Hit-test the click point for an existing `<text>` unit so it can be
  //   re-opened with its current content (returns -1 for a new-text click).
  // - Commit writes history exactly once per confirmed edit; typing, focus,
  //   and cancel never touch the undo stack. Empty drafts are no-ops for new
  //   text, and delete the element when an existing item is cleared.
  async function findVectorTextIndexAtPoint(point: { x: number; y: number }, toleranceSvgUnits?: number) {
    if (!selectedTarget) return -1
    const loaded = await currentSvgDocument(selectedTarget, selectedTarget.currentCostume ?? 0)
    if (!loaded) return -1
    const units = editableVectorUnits(loaded.svg)
    let hit = -1
    try {
      hit = await paperVectorHitIndex(units, point, resolveVectorHitTolerance(toleranceSvgUnits))
    } catch {
      hit = -1
    }
    if (hit >= 0) return units[hit]?.tagName.toLowerCase() === 'text' ? hit : -1
    const found = [...vectorObjects]
      .reverse()
      .find((object) => {
        if (object.tag !== 'text') return false
        const left = object.boundsX ?? object.x ?? 0
        const top = object.boundsY ?? object.y ?? 0
        const width = object.boundsWidth ?? object.width ?? 0
        const height = object.boundsHeight ?? object.height ?? 0
        return point.x >= left && point.x <= left + width && point.y >= top && point.y <= top + height
      })
    return found?.index ?? -1
  }

  // Display-only sync when an existing `<text>` unit is opened for inline
  // editing: the toolbar shows the unit's effective font-family/size
  // (ancestor inheritance + inline style resolved, unknown stacks shown
  // verbatim) without marking anything dirty, and the values are recorded as
  // the session baseline (see `vectorTextFontSessionBaseline`). Never touches
  // the artwork or history; stale async completions after a target/costume
  // switch are dropped instead of syncing the new target.
  async function prepareVectorInlineTextFont(targetIndex: number) {
    if (!selectedTarget) return
    const target = selectedTarget
    const targetId = stableTargetId(target)
    const costumeIndex = target.currentCostume ?? 0
    // Paint baseline synchronously at open time (before any await): the
    // toolbar snapshot must predate user edits made while the async font
    // resolve is in flight, otherwise an explicit change would be folded into
    // the baseline and missed. Display is untouched; only the owner triple +
    // values are recorded for the later explicit-change check.
    vectorTextPaintSessionBaseline = {
      targetId,
      costumeIndex,
      targetIndex,
      paint: {
        fillTransparent,
        fillHex: paintColor,
        secondaryTransparent,
        secondaryHex: secondaryPaintColor,
        paintGradient,
        strokeTransparent,
        strokeHex: strokeColor,
        secondaryStrokeTransparent,
        secondaryStrokeHex: strokeSecondaryColor,
        strokeGradient,
        strokeWidth,
        vectorOpacity,
      },
    }
    const loaded = await currentSvgDocument(target, costumeIndex).catch(() => undefined)
    if (!selectedTarget || stableTargetId(selectedTarget) !== targetId || (selectedTarget.currentCostume ?? 0) !== costumeIndex) return
    const unit = loaded ? editableVectorUnits(loaded.svg)[targetIndex] : undefined
    let family = VECTOR_TEXT_DEFAULT_FONT_FAMILY
    let size = VECTOR_TEXT_DEFAULT_FONT_SIZE
    if (unit && unit.tagName.toLowerCase() === 'text') {
      try {
        family = resolveEffectiveVectorTextFontFamily(unit)
      } catch {
        family = VECTOR_TEXT_DEFAULT_FONT_FAMILY
      }
      try {
        const effective = resolveEffectiveVectorTextFontSize(unit)
        if (effective !== undefined) size = clampVectorTextFontSize(effective)
      } catch {
        size = VECTOR_TEXT_DEFAULT_FONT_SIZE
      }
    }
    vectorTextFontFamily = family
    vectorTextFontSize = size
    vectorTextFontSessionBaseline = { targetId, costumeIndex, targetIndex, fontSize: size, fontFamily: family }
    // (Paint baseline was snapshotted synchronously at open time above, so an
    // explicit toolbar change made while the font resolve was in flight still
    // counts as explicit.)
  }

  async function commitVectorInlineText(session: { x: number; y: number; text: string; targetIndex?: number }) {
    if (!selectedTarget) return 'noop' as const
    const index = selectedTarget.currentCostume ?? 0
    const commitTargetId = stableTargetId(selectedTarget)
    const textOwner = selectedTarget
    const textScope = captureDiscreteSaveScope(commitTargetId, index)
    const textScopeAlive = () => isDiscreteSaveScopeCurrent(textScope, discreteSaveLiveOf(textScope))
    const textPrevIndex = selectedVectorObjectIndex
    const textPrevIndices = [...selectedVectorObjectIndices]
    const loaded = await currentSvgDocument(textOwner, index)
    if (!textScopeAlive()) return 'noop' as const
    if (!loaded) return 'noop' as const
    if (!selectedTarget || stableTargetId(selectedTarget) !== commitTargetId || (selectedTarget.currentCostume ?? 0) !== index) return 'noop' as const
    const { doc, svg } = loaded
    const units = editableVectorUnits(svg)
    const target = session.targetIndex !== undefined ? units[session.targetIndex] : undefined
    const existingText = target && target.tagName.toLowerCase() === 'text'
      ? (readVectorTextElementContent(target) ?? '')
      : undefined
    // Session-owned font dirty: only an explicit toolbar change made while
    // THIS unit's session is open (toolbar differs from the open-time
    // baseline for the same owner + scope, and differs from the live
    // effective values) may rewrite font attributes. Unoperated sessions,
    // stale presets from other selections, and cross-target completions keep
    // the existing stack (including ancestor inheritance) untouched.
    let fontSizeToApply: number | undefined = undefined
    let fontFamilyToApply: string | undefined = undefined
    let fontChanged = false
    if (target && target.tagName.toLowerCase() === 'text' && session.targetIndex !== undefined) {
      const baseline = vectorTextFontSessionBaseline
      const scopeMatches = baseline !== undefined
        && baseline.targetId === commitTargetId
        && baseline.costumeIndex === index
        && baseline.targetIndex === session.targetIndex
      if (!scopeMatches) {
        // No valid baseline for this owner: a stale cross-scope session must
        // not write to the wrong item. When the baseline simply predates this
        // change (or the session outlived a switch), treat characters-only.
        if (baseline !== undefined) return 'noop' as const
      } else {
        const currentFamily = normalizeVectorTextFontFamily(vectorTextFontFamily)
        const currentSize = clampVectorTextFontSize(vectorTextFontSize)
        const baselineFamily = normalizeVectorTextFontFamily(baseline.fontFamily)
        const baselineSize = clampVectorTextFontSize(baseline.fontSize)
        if (currentFamily !== baselineFamily || currentSize !== baselineSize) {
          const needs = vectorTextFontNeedsUpdate(target, { fontSize: currentSize, fontFamily: currentFamily })
          if (currentFamily !== baselineFamily && needs.family) {
            fontFamilyToApply = currentFamily
            fontChanged = true
          }
          if (currentSize !== baselineSize && needs.size) {
            fontSizeToApply = currentSize
            fontChanged = true
          }
        }
      }
    }
    // Session-owned paint dirty (the paint-preserve counterpart of the font
    // fix above): only toolbar paint fields that changed during THIS unit's
    // session for the SAME owner may rewrite paint, and only via the safe
    // selective patch (same-value no-op, unknown/MIXED sides skipped, inline
    // style cleared only for rewritten sides). Characters-only edits keep
    // fill/stroke/width/opacity, `none`, inline style, parent inheritance,
    // tspan rows, defs, transform and direction byte-identical. Stale
    // cross-scope completions are dropped with no DOM/history write (redo
    // preserved), exactly like the font guard; HSV live ticks are flushed by
    // the caller before this commit, so an already-applied HSV color reads as
    // same-value here and never double-writes history.
    let vectorTextPaintPatch: VectorStylePatch = {}
    let paintChanged = false
    if (target && target.tagName.toLowerCase() === 'text' && session.targetIndex !== undefined) {
      const paintBaseline = vectorTextPaintSessionBaseline
      const paintScopeMatches = paintBaseline !== undefined
        && paintBaseline.targetId === commitTargetId
        && paintBaseline.costumeIndex === index
        && paintBaseline.targetIndex === session.targetIndex
      if (!paintScopeMatches) {
        if (paintBaseline !== undefined) return 'noop' as const
      } else {
        const changedFields = vectorTextPaintChangedFields(paintBaseline.paint, {
          fillTransparent,
          fillHex: paintColor,
          secondaryTransparent,
          secondaryHex: secondaryPaintColor,
          paintGradient,
          strokeTransparent,
          strokeHex: strokeColor,
          secondaryStrokeTransparent: secondaryStrokeTransparent,
          secondaryStrokeHex: strokeSecondaryColor,
          strokeGradient,
          strokeWidth,
          vectorOpacity,
        })
        if (changedFields.length > 0) {
          const candidate: VectorStylePatch = {}
          if (changedFields.includes('fill')) candidate.fill = fillPaintInput(fillTransparent, paintColor)
          if (changedFields.includes('fillSecondary') && paintGradient !== 'solid') {
            candidate.fillSecondary = secondaryPaintInput(secondaryTransparent, secondaryPaintColor)
          }
          if (changedFields.includes('fillGradient')) candidate.fillGradient = paintGradient
          if (changedFields.includes('stroke')) candidate.stroke = strokePrimaryInput(strokeTransparent, strokeColor)
          if (changedFields.includes('strokeSecondary') && strokeGradient !== 'solid') {
            candidate.strokeSecondary = strokeSecondaryInput(secondaryStrokeTransparent, strokeSecondaryColor)
          }
          if (changedFields.includes('strokeGradient')) candidate.strokeGradient = strokeGradient
          // Text patch stays in toolbar UI units (like every other path):
          // `detailed` is UI (`SVG*2` simple else verbatim) and the write gate below
          // converts UI->SVG (`/2` simple else verbatim) via `svgWidthForElement`.
          if (changedFields.includes('strokeWidth')) candidate.strokeWidth = clampStrokeWidth(strokeWidth)
          if (changedFields.includes('opacity')) candidate.opacity = Math.max(0, Math.min(100, vectorOpacity))
          if (!isEmptyVectorStylePatch(candidate)) {
            try {
              const resolveGradient = (id: string) => {
                if (!id) return undefined
                const def = (doc as Document).getElementById?.(id) as Element | null
                if (!def) return undefined
                const tag = def.tagName.toLowerCase() === 'radialgradient' ? 'radialGradient' : 'linearGradient'
                return readGradientDefFromElement(def as unknown as Parameters<typeof readGradientDefFromElement>[0], tag)
              }
              const detailed = readVectorElementPaintDetailed(
                target as unknown as Parameters<typeof readVectorElementPaintDetailed>[0],
                resolveGradient,
              )
              const next = mergeDetailedPaintWithPatch(
                detailed,
                candidate,
                {
                  fill: secondaryPaintInput(secondaryTransparent, secondaryPaintColor),
                  stroke: strokeSecondaryInput(secondaryStrokeTransparent, strokeSecondaryColor),
                },
              )
              const paintEquals = (
                left: { r: number; g: number; b: number; a: number } | null,
                right: { r: number; g: number; b: number; a: number } | null,
              ): boolean => {
                if (left === null || right === null) return left === null && right === null
                return left.r === right.r && left.g === right.g && left.b === right.b && left.a === right.a
              }
              const numbersEqual = (left: number, right: number): boolean => Math.abs(left - right) < 1e-9
              let wouldWrite = false
              if (next.fill) {
                const same = !isMixedSelectionValue(detailed.fill)
                  && !isMixedSelectionValue(detailed.fillSecondary)
                  && !isMixedSelectionValue(detailed.fillGradient)
                  && paintEquals(detailed.fill as { r: number; g: number; b: number; a: number } | null, next.fill.primary as { r: number; g: number; b: number; a: number } | null)
                  && paintEquals(detailed.fillSecondary as { r: number; g: number; b: number; a: number } | null, next.fill.secondary as { r: number; g: number; b: number; a: number } | null)
                  && (detailed.fillGradient as string) === (next.fill.gradient as string)
                if (!same) wouldWrite = true
              }
              if (!wouldWrite && next.stroke) {
                const widthValue = isMixedSelectionValue(detailed.strokeWidth) ? undefined : (detailed.strokeWidth as number)
                const same = widthValue !== undefined
                  && !isMixedSelectionValue(detailed.stroke)
                  && !isMixedSelectionValue(detailed.strokeSecondary)
                  && !isMixedSelectionValue(detailed.strokeGradient)
                  && paintEquals(detailed.stroke as { r: number; g: number; b: number; a: number } | null, next.stroke.primary as { r: number; g: number; b: number; a: number } | null)
                  && paintEquals(detailed.strokeSecondary as { r: number; g: number; b: number; a: number } | null, next.stroke.secondary as { r: number; g: number; b: number; a: number } | null)
                  && (detailed.strokeGradient as string) === (next.stroke.gradient as string)
                  && numbersEqual(widthValue, next.stroke.width)
                if (!same && widthValue !== undefined) wouldWrite = true
              }
              if (!wouldWrite && next.strokeWidth !== null && next.strokeWidth !== undefined) {
                const same = !isMixedSelectionValue(detailed.strokeWidth) && numbersEqual(detailed.strokeWidth as number, next.strokeWidth)
                if (!same) wouldWrite = true
              }
              if (!wouldWrite && next.opacity !== null && next.opacity !== undefined) {
                const same = !isMixedSelectionValue(detailed.opacity) && numbersEqual(detailed.opacity as number, next.opacity)
                if (!same) wouldWrite = true
              }
              // Fully skipped (unknown/MIXED) or same-value intent stays
              // history-clean: keep the characters-only path below.
              if (wouldWrite) {
                vectorTextPaintPatch = candidate
                paintChanged = true
              }
            } catch {
              // Fail-closed: an unreadable paint state never invents a color;
              // the characters-only path preserves everything below.
            }
          }
        }
      }
    }
    const kind = resolveVectorTextCommit(existingText, session.text, fontChanged, paintChanged)
    if (kind === 'noop') return 'noop' as const
    // An invisible fill + invisible stroke paints no glyphs: no history, no
    // node change (text honors the same no-op rule as rect/oval/line). Only
    // gate updates that actually change paint: a characters-only edit keeps
    // the existing visible paint, so the toolbar's stale transparent preset
    // must not drop the text change.
    if ((kind === 'insert' || (kind === 'update' && paintChanged)) && isNewVectorShapeNoop('text')) {
      status = 'Vector text: no change'
      return 'noop' as const
    }
    // One history entry per confirmed edit, never on keystrokes and never
    // for cancelled/empty sessions (handled above). Peek-then-commit (not
    // capture-then-write): the peeked pre-edit entry is committed only after
    // the scope re-guard passes, so a target/costume switch or undo/redo
    // rebase during the await drops the stale completion with no DOM write,
    // no history entry, and redo preserved.
    const pendingTextHistory = await peekCostumeHistory(selectedTarget, index)
    if (!textScopeAlive()) return 'noop' as const
    if (!selectedTarget || stableTargetId(selectedTarget) !== commitTargetId || (selectedTarget.currentCostume ?? 0) !== index) {
      return 'noop' as const
    }
    const fontSize = clampVectorTextFontSize(vectorTextFontSize)
    const fontFamily = normalizeVectorTextFontFamily(vectorTextFontFamily)
    if (kind === 'delete') {
      target?.remove()
      vectorTextFontSessionBaseline = undefined
      vectorTextPaintSessionBaseline = undefined
    } else if (kind === 'update' && target) {
      // Characters-only edits pass no font options, so the element keeps its
      // own attributes, ancestor inheritance, inline style, weight, and
      // transform. Only an explicit session-owned font/size change rewrites
      // the corresponding attribute (same-value writes are skipped inside).
      setVectorTextElementContent(
        target,
        session.text,
        {
          ...(fontSizeToApply !== undefined ? { fontSize: fontSizeToApply } : {}),
          ...(fontFamilyToApply !== undefined ? { fontFamily: fontFamilyToApply } : {}),
        },
      )
      // Characters-only edits stop here: fill/stroke/width/opacity, `none`,
      // inline style, parent inheritance, tspan rows, defs, transform and
      // direction all survive byte-identical. Only explicit session-owned
      // paint changes reach the safe selective patch below (same-value and
      // unknown/MIXED sides skipped, inline style cleared only for rewritten
      // sides, defs only appended when a gradient actually paints).
      if (paintChanged && !isEmptyVectorStylePatch(vectorTextPaintPatch)) {
        const resolveGradient = (id: string) => {
          if (!id) return undefined
          const def = (doc as Document).getElementById?.(id) as Element | null
          if (!def) return undefined
          const tag = def.tagName.toLowerCase() === 'radialgradient' ? 'radialGradient' : 'linearGradient'
          return readGradientDefFromElement(def as unknown as Parameters<typeof readGradientDefFromElement>[0], tag)
        }
        const detailed = readVectorElementPaintDetailed(
          target as unknown as Parameters<typeof readVectorElementPaintDetailed>[0],
          resolveGradient,
        )
        const next = mergeDetailedPaintWithPatch(
          detailed,
          vectorTextPaintPatch,
          {
            fill: secondaryPaintInput(secondaryTransparent, secondaryPaintColor),
            stroke: strokeSecondaryInput(secondaryStrokeTransparent, strokeSecondaryColor),
          },
        )
        const clearInlineStyleProps = (element: Element, properties: string[]) => {
          try {
            const raw = element.getAttribute('style')
            if (!raw) return
            const keep = raw
              .split(';')
              .map((part) => part.trim())
              .filter((part) => part.length > 0)
              .filter((part) => {
                const colon = part.indexOf(':')
                if (colon < 0) return true
                return !properties.includes(part.slice(0, colon).trim().toLowerCase())
              })
            if (keep.length === 0) element.removeAttribute('style')
            else element.setAttribute('style', `${keep.join('; ')};`)
          } catch {
            // Best-effort presentation hygiene; the attribute write stands alone.
          }
        }
        const paintEquals = (
          left: { r: number; g: number; b: number; a: number } | null,
          right: { r: number; g: number; b: number; a: number } | null,
        ): boolean => {
          if (left === null || right === null) return left === null && right === null
          return left.r === right.r && left.g === right.g && left.b === right.b && left.a === right.a
        }
        const numbersEqual = (left: number, right: number): boolean => Math.abs(left - right) < 1e-9
        const gradientBounds = localVectorGradientBounds(target)
        const stamp = `${Date.now().toString(36)}${Math.floor(Math.random() * 9999)}`
        if (next.fill) {
          const same = !isMixedSelectionValue(detailed.fill)
            && !isMixedSelectionValue(detailed.fillSecondary)
            && !isMixedSelectionValue(detailed.fillGradient)
            && paintEquals(detailed.fill as { r: number; g: number; b: number; a: number } | null, next.fill.primary as { r: number; g: number; b: number; a: number } | null)
            && paintEquals(detailed.fillSecondary as { r: number; g: number; b: number; a: number } | null, next.fill.secondary as { r: number; g: number; b: number; a: number } | null)
            && (detailed.fillGradient as string) === (next.fill.gradient as string)
          if (!same && !next.skipped.fill) {
            const fillPaint = svgGradientPaint({
              id: `paint-${stamp}-text`,
              kind: next.fill.gradient,
              primary: next.fill.primary,
              secondary: next.fill.secondary,
              width: 480,
              height: 360,
              bounds: gradientBounds,
              center: undefined,
            })
            appendVectorPaintDefs(svg, doc, fillPaint.defs)
            target.setAttribute('fill', fillPaint.fill)
            try {
              target.removeAttribute('fill-opacity')
            } catch {}
            clearInlineStyleProps(target, ['fill', 'fill-opacity'])
          }
        }
        if (next.stroke) {
          const widthValue = isMixedSelectionValue(detailed.strokeWidth) ? undefined : (detailed.strokeWidth as number)
          const same = widthValue !== undefined
            && !isMixedSelectionValue(detailed.stroke)
            && !isMixedSelectionValue(detailed.strokeSecondary)
            && !isMixedSelectionValue(detailed.strokeGradient)
            && paintEquals(detailed.stroke as { r: number; g: number; b: number; a: number } | null, next.stroke.primary as { r: number; g: number; b: number; a: number } | null)
            && paintEquals(detailed.strokeSecondary as { r: number; g: number; b: number; a: number } | null, next.stroke.secondary as { r: number; g: number; b: number; a: number } | null)
            && (detailed.strokeGradient as string) === (next.stroke.gradient as string)
            && numbersEqual(widthValue, next.stroke.width)
          if (!same && widthValue !== undefined && !next.skipped.stroke) {
            const strokePaint = svgStrokePaint({
              id: `stroke-${stamp}-text`,
              gradient: next.stroke.gradient,
              primary: next.stroke.primary,
              secondary: next.stroke.secondary,
              strokeWidth: next.stroke.width,
              width: 480,
              height: 360,
              bounds: gradientBounds,
              center: undefined,
            })
            appendVectorPaintDefs(svg, doc, strokePaint.defs)
            applyStrokePaintToElement(target, { stroke: strokePaint.stroke, strokeWidth: svgWidthForElement(target, next.stroke.width) })
            try {
              target.removeAttribute('stroke-opacity')
            } catch {}
            clearInlineStyleProps(target, ['stroke', 'stroke-opacity'])
          }
        }
        if (next.strokeWidth !== null && next.strokeWidth !== undefined && !next.skipped.strokeWidth) {
          const same = !isMixedSelectionValue(detailed.strokeWidth) && numbersEqual(detailed.strokeWidth as number, next.strokeWidth)
          if (!same) {
            target.setAttribute('stroke-width', String(svgWidthForElement(target, next.strokeWidth)))
            clearInlineStyleProps(target, ['stroke-width'])
          }
        }
        if (next.opacity !== null && next.opacity !== undefined && !next.skipped.opacity) {
          const same = !isMixedSelectionValue(detailed.opacity) && numbersEqual(detailed.opacity as number, next.opacity)
          if (!same) {
            target.setAttribute('opacity', String(Math.max(0, Math.min(1, next.opacity / 100))))
            clearInlineStyleProps(target, ['opacity'])
          }
        }
        // Consume only the fields this session actually owned, so a later
        // Apply cannot leak the same intent into a different selection. A
        // selection switch mid-session already changed the key, so the owner
        // check below keeps newer dirty for the new selection intact.
        const writeOwner = currentVectorStyleSelectionKey()
        for (const field of ['fill', 'fillSecondary', 'fillGradient', 'stroke', 'strokeSecondary', 'strokeGradient', 'strokeWidth', 'opacity'] as const) {
          const dirtyOwner = vectorStyleDirtyOwner[field] ?? VECTOR_STYLE_DESELECTED_KEY
          if (dirtyOwner === writeOwner || dirtyOwner === VECTOR_STYLE_DESELECTED_KEY) {
            // Only consume fields this patch carried; untouched dirty (e.g. an
            // unused secondary while solid) stays for a later Apply.
            const carried = field === 'fill' ? vectorTextPaintPatch.fill !== undefined
              : field === 'fillSecondary' ? vectorTextPaintPatch.fillSecondary !== undefined
              : field === 'fillGradient' ? vectorTextPaintPatch.fillGradient !== undefined
              : field === 'stroke' ? vectorTextPaintPatch.stroke !== undefined
              : field === 'strokeSecondary' ? vectorTextPaintPatch.strokeSecondary !== undefined
              : field === 'strokeGradient' ? vectorTextPaintPatch.strokeGradient !== undefined
              : field === 'strokeWidth' ? vectorTextPaintPatch.strokeWidth !== undefined
              : vectorTextPaintPatch.opacity !== undefined
            if (carried) consumeVectorStyleDirty(field)
          }
        }
      }
      if (pendingTextHistory) {
        // Deferred until the CAS below succeeds (shared peek for update/delete).
      }
      vectorTextFontSessionBaseline = undefined
      vectorTextPaintSessionBaseline = undefined
    } else {
      const point = clampVectorTextPoint(session)
      const shape = buildVectorTextMarkup({
        x: point.x,
        y: point.y,
        text: session.text,
        paint: vectorPaintStyle(480, 360),
        strokeColor: effectiveStrokeColor(),
        strokePaint: vectorStrokePaintStyle(480, 360),
        strokeWidth,
        opacity: vectorOpacity,
        fontSize,
        fontFamily,
      })
      if (!textScopeAlive()) return 'noop' as const
      const next = await svgWithInsertedShape(textOwner, index, shape, 'append')
      if (!textScopeAlive()) return 'noop' as const
      const textInsertLive = vectorWriteTargetById(commitTargetId, textOwner.name) ?? textOwner
      if (stableTargetId(textInsertLive) !== commitTargetId) return 'noop' as const
      const textInsertCommit = await updateVectorCostumeFromEditor(textInsertLive, index, next, { quiet: true, isAlive: textScopeAlive })
      if (textInsertCommit.kind !== 'applied') {
        if (textScopeAlive() || (textInsertCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(textScope, discreteSaveLiveOf(textScope)))) {
          selectedVectorObjectIndex = textPrevIndex
          selectedVectorObjectIndices = [...textPrevIndices]
          await refreshVectorPreviewFromLive(commitTargetId, textInsertLive)
          reportVectorExternalConflict('Edit')
        }
        return 'noop' as const
      }
      if (!textScopeAlive()) return 'noop' as const
      if (pendingTextHistory) commitPaintHistory(pendingTextHistory)
      if (!textScopeAlive()) return 'noop' as const
      const nextSvg = textInsertCommit.svgText
      vectorObjects = await paperVectorObjectList(nextSvg)
      if (!textScopeAlive()) return 'noop' as const
      await refreshCostumePreview(vectorWriteTargetById(commitTargetId, textOwner.name) ?? textOwner)
      if (!textScopeAlive()) return 'noop' as const
      selectedVectorObjectIndex = vectorObjects.at(-1)?.index ?? selectedVectorObjectIndex
      selectedVectorObjectIndices = selectedVectorObjectIndex >= 0 ? [selectedVectorObjectIndex] : []
      clearReshapeSelection()
      if (!isVectorTextEmpty(session.text)) vectorText = session.text.split('\n')[0] ?? vectorText
      try {
        rememberCommittedReshapeSelection(commitTargetId, index, new TextEncoder().encode(nextSvg))
      } catch {
        // Best-effort only.
      }
      status = 'Vector text saved'
      return 'inserted' as const
    }
    if (!textScopeAlive()) return 'noop' as const
    const textLive = vectorWriteTargetById(commitTargetId, textOwner.name) ?? textOwner
    if (stableTargetId(textLive) !== commitTargetId) return 'noop' as const
    const textCommit = await updateVectorCostumeFromEditor(textLive, index, new XMLSerializer().serializeToString(doc.documentElement), { quiet: true, isAlive: textScopeAlive })
    if (textCommit.kind !== 'applied') {
      if (textScopeAlive() || (textCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(textScope, discreteSaveLiveOf(textScope)))) {
        selectedVectorObjectIndex = textPrevIndex
        selectedVectorObjectIndices = [...textPrevIndices]
        await refreshVectorPreviewFromLive(commitTargetId, textLive)
        reportVectorExternalConflict('Edit')
      }
      return 'noop' as const
    }
    if (!textScopeAlive()) return 'noop' as const
    if (pendingTextHistory) commitPaintHistory(pendingTextHistory)
    if (!textScopeAlive()) return 'noop' as const
    const nextSvg = textCommit.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (!textScopeAlive()) return 'noop' as const
    if (kind === 'delete') {
      selectedVectorObjectIndex = -1
      selectedVectorObjectIndices = []
      clearReshapeSelection()
      try {
        rememberCommittedReshapeSelection(commitTargetId, index, new TextEncoder().encode(nextSvg))
      } catch {
        // Best-effort only.
      }
      status = 'Vector text deleted'
      return 'deleted' as const
    }
    await refreshCostumePreview(vectorWriteTargetById(commitTargetId, textOwner.name) ?? textOwner)
    if (!textScopeAlive()) return 'noop' as const
    selectedVectorObjectIndex = session.targetIndex ?? selectedVectorObjectIndex
    selectedVectorObjectIndices = selectedVectorObjectIndex >= 0 ? [selectedVectorObjectIndex] : []
    if (!isVectorTextEmpty(session.text)) vectorText = session.text.split('\n')[0] ?? vectorText
    try {
      rememberCommittedReshapeSelection(commitTargetId, index, new TextEncoder().encode(nextSvg))
    } catch {
      // Best-effort only.
    }
    status = 'Vector text saved'
    return 'updated' as const
  }

  // Bitmap inline text: the overlay textarea collects the draft and a single
  // rasterize + save commits it, so history also holds exactly one entry per
  // confirmed edit (saveBitmapCostume captures before writing). A transparent
  // fill paints no fill glyphs (hollow when the stroke stays opaque); when
  // both fill and stroke are transparent there is nothing to rasterize, so
  // the commit is a no-op without history, like an empty draft.
  async function commitBitmapInlineText(point: { x: number; y: number }, text: string) {
    if (!selectedTarget || !bitmapCanvas || isBitmapTextEmpty(text)) return false
    if (isBitmapPaintNoop('text', { fillTransparent, secondaryTransparent, strokeTransparent }, paintGradient)) {
      status = 'Bitmap text: no change'
      return false
    }
    const context = bitmapCanvas.getContext('2d')
    if (!context) return false
    const fontSize = clampBitmapTextFontSize(vectorTextFontSize)
    const lines = splitBitmapTextLines(text)
    const bounds = bitmapTextBlockBounds(point.x, point.y, text, fontSize)
    context.save()
    try {
      context.font = resolveBitmapTextFont(fontSize, vectorTextFontFamily)
      // RTL rows draw right-aligned at the shared click edge (the caller
      // pre-shifts the commit point left by half the widest line); LTR/CJK
      // keep the historical centered draw.
      const align = resolveBitmapTextAlign(text)
      // Reference parity: scratch-paint creates PointText with leading 46.15
      // at 40px and rasterizes it for bitmap, so multiline rows advance by
      // 46.15/40 em (see bitmap-text.ts). Single-line commits keep firstY on
      // the click; align/baseline stay center/middle; res1/res2 only change
      // the canvas size, not this em factor; no transform is touched here.
      const lineHeight = bitmapTextLineHeight(fontSize)
      const firstY = point.y - ((lines.length - 1) * lineHeight) / 2
      if (align === 'right') {
        const drawX = resolveBitmapTextRtlDrawX(point.x, text, fontSize, vectorTextFontFamily, (line, font) => {
          try {
            context.font = font
            const width = context.measureText(line).width
            return Number.isFinite(width) && width > 0 ? width : undefined
          } catch {
            return undefined
          }
        })
        context.textAlign = 'right'
        context.textBaseline = 'middle'
        context.lineWidth = 1
        context.strokeStyle = strokeTransparent ? 'rgba(0, 0, 0, 0)' : strokeColor
        context.fillStyle = bitmapPaintStyle(context, bounds.x, bounds.y, Math.max(1, bounds.width), Math.max(1, bounds.height))
        lines.forEach((line, lineIndex) => {
          const lineY = firstY + lineIndex * lineHeight
          const source = line.length === 0 ? ' ' : line
          if (!strokeTransparent) context.strokeText(source, drawX, lineY)
          context.fillText(source, drawX, lineY)
        })
      } else {
        context.textAlign = 'center'
        context.textBaseline = 'middle'
        context.lineWidth = 1
        context.strokeStyle = strokeTransparent ? 'rgba(0, 0, 0, 0)' : strokeColor
        context.fillStyle = bitmapPaintStyle(context, bounds.x, bounds.y, Math.max(1, bounds.width), Math.max(1, bounds.height))
        lines.forEach((line, lineIndex) => {
          const lineY = firstY + lineIndex * lineHeight
          if (!strokeTransparent) context.strokeText(line.length === 0 ? ' ' : line, point.x, lineY)
          context.fillText(line.length === 0 ? ' ' : line, point.x, lineY)
        })
      }
    } finally {
      context.restore()
    }
    vectorText = text.split('\n')[0] ?? vectorText
    await saveBitmapCostume('Bitmap text saved')
    return true
  }

  async function scaleSelectedVectorObject(factor: number) {
    await updateVectorObject((element) => applyPaperScale(element, factor))
  }

  async function moveSelectedVectorObjectBy(dx: number, dy: number, captureHistory = true): Promise<boolean> {
    if (!dx && !dy) return false
    return updateVectorObjects((element) => moveVectorElementBy(element, dx, dy), captureHistory)
  }

  async function resizeSelectedVectorObjectBy(handle: VectorResizeHandle, dx: number, dy: number, captureHistory = true): Promise<boolean> {
    if (!dx && !dy) return false
    return updateVectorObject((element) => resizeVectorElementBy(element, handle, dx, dy), captureHistory)
  }

  async function resizeSelectedVectorObjectFromSource(
    sourceReady: Promise<{ targetName: string; costumeIndex: number; svgText: string } | undefined>,
    objectIndex: number,
    handle: VectorResizeHandle,
    dx: number,
    dy: number,
    modifiers: { shiftKey?: boolean; altKey?: boolean } = {},
    expectedStructureEpoch?: number,
    expectedTargetId?: string,
    writeGesture?: { gestureId: VectorWriteGesture; targetId: string },
  ) {
    if (!selectedTarget || (!dx && !dy)) return false
    const epochTarget = selectedTarget
    const resizeSingleTargetId = stableTargetId(epochTarget)
    const resizeSingleCostume = epochTarget.currentCostume ?? 0
    const resizeSingleScope = captureDiscreteSaveScope(resizeSingleTargetId, resizeSingleCostume)
    const resizeSingleAlive = () => isDiscreteSaveScopeCurrent(resizeSingleScope, discreteSaveLiveOf(resizeSingleScope))
    if (expectedStructureEpoch !== undefined && expectedStructureEpoch !== getTargetVectorEpoch(stableTargetId(epochTarget))) return false
    if (expectedTargetId !== undefined && stableTargetId(epochTarget) !== expectedTargetId) return false
    const source = await sourceReady
    if (!resizeSingleAlive() && !writeGesture) return false
    if (!source || source.targetName !== selectedTarget.name) return false
    if (expectedTargetId !== undefined && stableTargetId(selectedTarget) !== expectedTargetId) return false
    if (expectedStructureEpoch !== undefined && expectedStructureEpoch !== getTargetVectorEpoch(stableTargetId(selectedTarget))) return false
    const doc = new DOMParser().parseFromString(source.svgText, 'image/svg+xml')
    const svg = doc.documentElement
    if (svg.nodeName.toLowerCase() !== 'svg') return false
    const element = editableVectorUnits(svg)[objectIndex]
    if (!element) return false
    const applied = await resizeVectorElementBy(element, handle, dx, dy, modifiers)
    if (!applied) return false
    const writeOpts =
      expectedStructureEpoch !== undefined || writeGesture
        ? {
            ...(writeGesture ? { gestureId: writeGesture.gestureId, kind: 'preview' as const } : {}),
            ...(expectedStructureEpoch !== undefined ? { expectedStructureEpoch } : {}),
          }
        : { quiet: true, isAlive: resizeSingleAlive }
    const resizeCommit = await updateVectorCostumeFromEditor(selectedTarget, source.costumeIndex, new XMLSerializer().serializeToString(doc.documentElement), writeOpts)
    if (!writeGesture) {
      if (resizeCommit.kind !== 'applied') {
        if (resizeSingleAlive() || (resizeCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(resizeSingleScope, discreteSaveLiveOf(resizeSingleScope)))) {
          await refreshVectorPreviewFromLive(resizeSingleTargetId, selectedTarget)
          reportVectorExternalConflict('Resize')
        }
        return false
      }
      if (!resizeSingleAlive()) return false
    }
    const nextSvg = resizeCommit.svgText
    if (writeGesture && isVectorGestureConflicted(writeGesture.gestureId)) {
      await refreshVectorPreviewFromLive(writeGesture.targetId, selectedTarget)
      reportVectorExternalConflict('Resize')
      return false
    }
    if (!writeGesture && !resizeSingleAlive()) return false
    selectedVectorObjectIndex = objectIndex
    selectedVectorObjectIndices = [objectIndex]
    await refreshCostumePreview(vectorWriteTargetById(resizeSingleTargetId, epochTarget.name) ?? selectedTarget)
    if (!writeGesture && !resizeSingleAlive()) return false
    if (!writeGesture) {
      try {
        rememberCommittedReshapeSelection(resizeSingleTargetId, source.costumeIndex, new TextEncoder().encode(nextSvg))
      } catch {
        // Best-effort only.
      }
    }
    status = 'Vector object resized'
    return true
  }

  // 複数選択の共有境界リサイズ: 開始時スナップショットへ総移動量を一発適用する
  // (単一と同様の絶対適用で、ドラッグ中の再適用が累積しない)。共通境界の
  // 幾何 (`resolveCommonVectorScale` + 共役配布) で全要素を同じワールド行列
  // 通りに拡縮するため、祖先 transform・文書順序 (前面順) に触れない。
  // stroke は SVG CTM 経由で形状と一緒に拡縮される。no-op は DOM に触らず
  // false を返し、呼び出し側は履歴を積まない。選択は維持する。
  async function resizeMultiVectorSelectionFromSource(
    sourceReady: Promise<{ targetName: string; costumeIndex: number; svgText: string } | undefined>,
    selection: number[],
    handle: VectorResizeHandle,
    dx: number,
    dy: number,
    modifiers: { shiftKey?: boolean; altKey?: boolean } = {},
    expectedStructureEpoch?: number,
    expectedTargetId?: string,
    writeGesture?: { gestureId: VectorWriteGesture; targetId: string },
  ) {
    if (!selectedTarget || (!dx && !dy)) return false
    const resizeMultiOwner = selectedTarget
    const resizeMultiTargetId = stableTargetId(resizeMultiOwner)
    const resizeMultiCostume = resizeMultiOwner.currentCostume ?? 0
    const resizeMultiScope = captureDiscreteSaveScope(resizeMultiTargetId, resizeMultiCostume)
    const resizeMultiAlive = () => isDiscreteSaveScopeCurrent(resizeMultiScope, discreteSaveLiveOf(resizeMultiScope))
    if (expectedStructureEpoch !== undefined && expectedStructureEpoch !== getTargetVectorEpoch(stableTargetId(selectedTarget))) return false
    if (expectedTargetId !== undefined && stableTargetId(selectedTarget) !== expectedTargetId) return false
    const source = await sourceReady
    if (!resizeMultiAlive() && !writeGesture) return false
    if (!source || source.targetName !== selectedTarget.name) return false
    if (expectedTargetId !== undefined && stableTargetId(selectedTarget) !== expectedTargetId) return false
    if (expectedStructureEpoch !== undefined && expectedStructureEpoch !== getTargetVectorEpoch(stableTargetId(selectedTarget))) return false
    const doc = new DOMParser().parseFromString(source.svgText, 'image/svg+xml')
    const svg = doc.documentElement
    if (svg.nodeName.toLowerCase() !== 'svg') return false
    const units = editableVectorUnits(svg)
    const elements = [...new Set(selection)].map((index) => units[index]).filter((element): element is Element => Boolean(element))
    if (elements.length < 2) return false
    const applied = scaleVectorElementsByCommonBounds(elements, handle, dx, dy, modifiers)
    if (!applied) return false
    const writeOpts =
      expectedStructureEpoch !== undefined || writeGesture
        ? {
            ...(writeGesture ? { gestureId: writeGesture.gestureId, kind: 'preview' as const } : {}),
            ...(expectedStructureEpoch !== undefined ? { expectedStructureEpoch } : {}),
          }
        : { quiet: true, isAlive: resizeMultiAlive }
    const resizeMultiCommit = await updateVectorCostumeFromEditor(selectedTarget, source.costumeIndex, new XMLSerializer().serializeToString(doc.documentElement), writeOpts)
    if (!writeGesture) {
      if (resizeMultiCommit.kind !== 'applied') {
        if (resizeMultiAlive() || (resizeMultiCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(resizeMultiScope, discreteSaveLiveOf(resizeMultiScope)))) {
          await refreshVectorPreviewFromLive(resizeMultiTargetId, selectedTarget)
          reportVectorExternalConflict('Resize')
        }
        return false
      }
      if (!resizeMultiAlive()) return false
    }
    const nextSvg = resizeMultiCommit.svgText
    if (writeGesture && isVectorGestureConflicted(writeGesture.gestureId)) {
      await refreshVectorPreviewFromLive(writeGesture.targetId, selectedTarget)
      reportVectorExternalConflict('Resize')
      return false
    }
    if (!writeGesture && !resizeMultiAlive()) return false
    const keptSelection = [...new Set(selection)].filter((index) => editableVectorUnits(doc.documentElement)[index])
    selectedVectorObjectIndices = keptSelection
    selectedVectorObjectIndex = keptSelection.includes(selectedVectorObjectIndex) ? selectedVectorObjectIndex : (keptSelection.at(-1) ?? -1)
    await refreshCostumePreview(vectorWriteTargetById(resizeMultiTargetId, resizeMultiOwner.name) ?? selectedTarget)
    if (!writeGesture && !resizeMultiAlive()) return false
    status = 'Vector objects resized'
    return true
  }

  function vectorPreviewDimensions() {
    return { width: 480, height: 360 }
  }

  // United selection center in SVG units for center-snap parity. Single and
  // multi selections share one anchor: the union of the selected bounds.
  // Returns `undefined` on unusable bounds so callers safely skip snapping
  // (fail-closed, never snap). Original coordinates and rotationCenter are
  // untouched here; only the drag delta is affected downstream.
  function vectorSelectionSnapCenter(selection: number[], objects: VectorObjectInfo[]): { x: number; y: number } | undefined {
    const boxes = [...new Set(selection)]
      .map((index) => objects.find((item) => item.index === index))
      .filter((item): item is VectorObjectInfo => Boolean(item))
      .map((item) => {
        const left = item.boundsX ?? item.x ?? 0
        const top = item.boundsY ?? item.y ?? 0
        const width = item.boundsWidth ?? item.width ?? 0
        const height = item.boundsHeight ?? item.height ?? 0
        return { left, top, right: left + width, bottom: top + height }
      })
      .filter((box) => Number.isFinite(box.left) && Number.isFinite(box.top) && Number.isFinite(box.right) && Number.isFinite(box.bottom))
    if (boxes.length === 0) return undefined
    const united = uniteSelectionBounds(boxes as MoveRect[])
    if (!united) return undefined
    const center = rectCenter(united)
    if (!Number.isFinite(center.x) || !Number.isFinite(center.y)) return undefined
    return center
  }

  // Union bounds matching the snap center (for the drag guide fade). Same
  // fail-closed rule: `undefined` hides the guide instead of guessing.
  function vectorSelectionSnapBounds(selection: number[], objects: VectorObjectInfo[]): MoveRect | undefined {
    const boxes = [...new Set(selection)]
      .map((index) => objects.find((item) => item.index === index))
      .filter((item): item is VectorObjectInfo => Boolean(item))
      .map((item) => {
        const left = item.boundsX ?? item.x ?? 0
        const top = item.boundsY ?? item.y ?? 0
        const width = item.boundsWidth ?? item.width ?? 0
        const height = item.boundsHeight ?? item.height ?? 0
        return { left, top, right: left + width, bottom: top + height }
      })
      .filter((box) => Number.isFinite(box.left) && Number.isFinite(box.top) && Number.isFinite(box.right) && Number.isFinite(box.bottom))
    if (boxes.length === 0) return undefined
    return uniteSelectionBounds(boxes as MoveRect[])
  }

  // Vector action-bounds clamp in SVG units. Reference: (view bounds united
  // with the art board) intersected with the max workspace. The live Paper
  // view bounds are not tracked here, so this clamps to the SVG-mapped max
  // workspace ((-120,-90)-(600,450) = Paper (-240,-180)-(1200,900) at 2x)
  // instead of guessing a view rect: wide enough to never disturb in-bounds
  // drags, tight enough to keep NaN/huge pointers from teleporting artwork.
  // Safe fail: non-finite input maps to the selection center (zero delta).
  function clampVectorSnapPointer(point: { x: number; y: number }, fallback: { x: number; y: number }): { x: number; y: number } {
    if (!Number.isFinite(point?.x) || !Number.isFinite(point?.y)) return { ...fallback }
    return clampPointerIntoBounds(point, { left: -120, top: -90, right: 600, bottom: 450 })
  }

  function vectorObjectOverlayStyle(object: VectorObjectInfo) {
    const dims = vectorPreviewDimensions()
    const scale = Math.min(100 / dims.width, 100 / dims.height)
    const offsetX = (100 - dims.width * scale) / 2
    const offsetY = (100 - dims.height * scale) / 2
    const left = offsetX + (object.boundsX ?? object.x ?? 0) * scale
    const top = offsetY + (object.boundsY ?? object.y ?? 0) * scale
    const width = Math.max(3, (object.boundsWidth ?? object.width ?? 2) * scale)
    const height = Math.max(3, (object.boundsHeight ?? object.height ?? 2) * scale)
    const drag = vectorDrag?.index === object.index ? ` translate(${vectorDrag.dx}px, ${vectorDrag.dy}px)` : ''
    const resize = vectorResizeDrag?.index === object.index && !vectorResizeDrag.multi ? `width:calc(${width}% + ${vectorResizeDrag.dx}px);height:calc(${height}% + ${vectorResizeDrag.dy}px);` : `width:${width}%;height:${height}%;`
    return `left:${left}%;top:${top}%;${resize}transform:${drag};`
  }

  function vectorResizeHandleStyle(object: VectorObjectInfo, handle: VectorResizeHandle) {
    const dims = vectorPreviewDimensions()
    const scale = Math.min(100 / dims.width, 100 / dims.height)
    const offsetX = (100 - dims.width * scale) / 2
    const offsetY = (100 - dims.height * scale) / 2
    const objectLeft = object.boundsX ?? object.x ?? 0
    const objectTop = object.boundsY ?? object.y ?? 0
    const objectWidth = object.boundsWidth ?? object.width ?? 2
    const objectHeight = object.boundsHeight ?? object.height ?? 2
    const handleX = handle.includes('w') ? objectLeft : handle.includes('e') ? objectLeft + objectWidth : objectLeft + objectWidth / 2
    const handleY = handle.includes('n') ? objectTop : handle.includes('s') ? objectTop + objectHeight : objectTop + objectHeight / 2
    const left = offsetX + handleX * scale
    const top = offsetY + handleY * scale
    const drag = vectorResizeDrag?.index === object.index && !vectorResizeDrag.multi ? ` translate(${vectorResizeDrag.dx}px, ${vectorResizeDrag.dy}px)` : ''
    return `left:${left}%;top:${top}%;transform:translate(-50%, -50%)${drag};`
  }

  type VectorUnionBounds = { x: number; y: number; width: number; height: number }

  // 複数選択の共有選択境界 (union)。`vectorObjects` の文書座標バウンズから
  // 求め、2 件未満ではハンドルを表示しないため undefined を返す。
  // `$:` から選択・一覧を引数で渡して呼び出すこと (直接参照でなければ
  // 変更検知されないため。テンプレート内の関数呼び出しだけでは再評価
  // されない)。
  function computeVectorMultiSelectionBounds(selection: number[], objects: VectorObjectInfo[]): VectorUnionBounds | undefined {
    const active = [...new Set(selection)].filter((index) => index >= 0 && index < objects.length)
    if (active.length < 2) return undefined
    const boxes = active
      .map((index) => objects.find((item) => item.index === index))
      .filter((item): item is VectorObjectInfo => Boolean(item))
      .map((item) => ({
        x: item.boundsX ?? item.x ?? 0,
        y: item.boundsY ?? item.y ?? 0,
        width: item.boundsWidth ?? item.width ?? 0,
        height: item.boundsHeight ?? item.height ?? 0,
      }))
      .filter((box) => Number.isFinite(box.x) && Number.isFinite(box.y) && Number.isFinite(box.width) && Number.isFinite(box.height) && (box.width > 0 || box.height > 0))
    if (boxes.length < 2) return undefined
    const left = Math.min(...boxes.map((box) => box.x))
    const top = Math.min(...boxes.map((box) => box.y))
    const right = Math.max(...boxes.map((box) => box.x + box.width))
    const bottom = Math.max(...boxes.map((box) => box.y + box.height))
    return { x: left, y: top, width: Math.max(0, right - left), height: Math.max(0, bottom - top) }
  }

  function vectorMultiResizeHandleStyle(bounds: VectorUnionBounds, handle: VectorResizeHandle) {
    const dims = vectorPreviewDimensions()
    const scale = Math.min(100 / dims.width, 100 / dims.height)
    const offsetX = (100 - dims.width * scale) / 2
    const offsetY = (100 - dims.height * scale) / 2
    const handleX = handle.includes('w') ? bounds.x : handle.includes('e') ? bounds.x + bounds.width : bounds.x + bounds.width / 2
    const handleY = handle.includes('n') ? bounds.y : handle.includes('s') ? bounds.y + bounds.height : bounds.y + bounds.height / 2
    const left = offsetX + handleX * scale
    const top = offsetY + handleY * scale
    return `left:${left}%;top:${top}%;transform:translate(-50%, -50%);`
  }

  function vectorMultiSelectionOutlineStyle(bounds: VectorUnionBounds) {
    const dims = vectorPreviewDimensions()
    const scale = Math.min(100 / dims.width, 100 / dims.height)
    const offsetX = (100 - dims.width * scale) / 2
    const offsetY = (100 - dims.height * scale) / 2
    const left = offsetX + bounds.x * scale
    const top = offsetY + bounds.y * scale
    const width = Math.max(1, bounds.width * scale)
    const height = Math.max(1, bounds.height * scale)
    return `left:${left}%;top:${top}%;width:${width}%;height:${height}%;`
  }

  // 共有選択境界のリアクティブ値。引数で選択・一覧を直接参照させることで
  // `$:` の変更検知に載せる (関数内参照だけでは再計算されない)。
  $: vectorMultiSelectionBoundsState = computeVectorMultiSelectionBounds(selectedVectorObjectIndices, vectorObjects)

  function rotationCenterOverlayStyle() {
    const costume = selectedTarget?.costumes[selectedTarget.currentCostume ?? 0]
    const dims = vectorPreviewDimensions()
    const scale = Math.min(100 / dims.width, 100 / dims.height)
    const offsetX = (100 - dims.width * scale) / 2
    const offsetY = (100 - dims.height * scale) / 2
    const centerX = costume?.rotationCenterX ?? (selectedTarget?.isStage ? 240 : 48)
    const centerY = costume?.rotationCenterY ?? (selectedTarget?.isStage ? 180 : 48)
    const drag = rotationCenterDrag ? ` translate(${rotationCenterDrag.dx}px, ${rotationCenterDrag.dy}px)` : ''
    return `left:${offsetX + centerX * scale}%;top:${offsetY + centerY * scale}%;transform:translate(-50%, -50%)${drag};`
  }

  async function beginVectorObjectDrag(object: VectorObjectInfo, event: PointerEvent, scaleOverride?: number, shapeMove = false) {
    if (!selectedTarget) return
    event.preventDefault()
    event.stopPropagation()
    // Retained shape-tool presses already hit the live selection: keep it
    // untouched (reference clone=false/multiselect=false), so Shift never
    // toggles and Alt never clones. The select path keeps its append/clone.
    const append = !shapeMove && (event.shiftKey || event.metaKey || event.ctrlKey)
    if (!shapeMove && (append || !selectedVectorObjectIndices.includes(object.index))) selectVectorObject(object.index, append)
    // Inline text editing owns Alt and pointer focus; select only so typing
    // (and its shortcuts) keep working while the overlay is open.
    if (isVectorMoveTypingTarget(event.target) || isReshapeTextEditing()) return
    const element = event.currentTarget as HTMLElement | null
    const host = element?.parentElement
    const rect = host?.getBoundingClientRect()
    const dims = host?.dataset.vectorStageSurface === 'true' ? { width: 480, height: 360 } : vectorPreviewDimensions()
    const scale = scaleOverride ?? (rect ? Math.min(rect.width / dims.width, rect.height / dims.height) : 1)
    element?.setPointerCapture?.(event.pointerId)
    const target = selectedTarget
    const pressSelection = normalizedVectorSelection(vectorObjects.length)
    const moveCostumeIndex = target.currentCostume ?? 0
    const moveGesture = beginVectorWriteGesture()
    vectorDrag = {
      index: object.index,
      pointerId: event.pointerId,
      startClientX: event.clientX,
      startClientY: event.clientY,
      dx: 0,
      dy: 0,
      scale,
      applying: false,
      historyReady: peekCostumeHistory(target, moveCostumeIndex).catch(() => undefined),
      pendingEntry: undefined,
      historyCaptured: false,
      targetName: target.name,
      targetId: stableTargetId(target),
      costumeIndex: target.currentCostume ?? 0,
      structureEpoch: getTargetVectorEpoch(stableTargetId(target)),
      gestureId: moveGesture,
      selection: pressSelection,
      altAtStart: shapeMove ? false : event.altKey,
      shiftKey: event.shiftKey,
      altKey: shapeMove ? false : event.altKey,
      shapeMove,
      duplicated: false,
      appliedX: 0,
      appliedY: 0,
      selectionCenter: vectorSelectionSnapCenter(pressSelection, vectorObjects),
      selectionBounds: vectorSelectionSnapBounds(pressSelection, vectorObjects),
      guideOpacity: 0,
      // Immutable source snapshot for the local-preview session: every frame
      // re-applies the absolute total from this text (never incrementally),
      // so Shift toggling recomputes cleanly and repeated moves cannot drift.
      sourceReady: currentSvgDocument(target, moveCostumeIndex).then((loaded) =>
        loaded
          ? { targetName: target.name, costumeIndex: moveCostumeIndex, svgText: new XMLSerializer().serializeToString(loaded.doc.documentElement) }
          : undefined,
      ),
      sourceSvgText: undefined,
      baseObjects: [...vectorObjects],
      basePreviewSvg: costumePreviewSvg,
      previewRaf: undefined,
      previewTotal: { x: 0, y: 0 },
      previewSelection: [...pressSelection],
      previewDuplicated: false,
      pressSelection: [...pressSelection],
      previewMoved: false,
    }
    captureVectorGestureIdentity(stableTargetId(target), moveCostumeIndex, moveGesture)
  }

  // Hit-test a canvas click against the drawn shapes (like scratch-paint's
  // select tool) and start dragging the topmost hit. Returns false for a miss
  // so the caller can fall back to marquee selection.
  async function beginVectorObjectDragAtPoint(point: { x: number; y: number }, event: PointerEvent, scale: number): Promise<boolean> {
    // `scale` is layout-measured surface px per SVG unit (== 5 * zoom), so
    // the 2 screen-px select budget converts directly without re-reading the
    // viewport state. Unusable scales fall back to the bound zoom state.
    const tolerance = Number.isFinite(scale) && scale > 0
      ? vectorSelectToleranceFromSurfaceScale(scale)
      : resolveVectorHitTolerance()
    const hitIndex = await vectorObjectIndexAtPoint(point, tolerance)
    if (hitIndex < 0) return false
    const object = vectorObjects.find((item) => item.index === hitIndex)
    if (!object) return false
    await beginVectorObjectDrag(object, event, scale)
    return true
  }

  // Shape-tool press parity (scratch-paint rect/oval `BoundingBoxTool` first):
  // start a move drag only when the hit belongs to the live selection.
  // Anything else (blank canvas, unselected shape, bbox corner outside an
  // ellipse) is a miss so the caller draws a fresh shape instead of dragging
  // or reselecting. The allowed set is read by the caller at press time.
  async function beginVectorSelectedDragAtPoint(point: { x: number; y: number }, event: PointerEvent, scale: number, allowedIndices: readonly number[]): Promise<boolean> {
    const tolerance = Number.isFinite(scale) && scale > 0
      ? vectorSelectToleranceFromSurfaceScale(scale)
      : resolveVectorHitTolerance()
    const hitIndex = await vectorObjectIndexAtPoint(point, tolerance)
    if (hitIndex < 0 || !allowedIndices.includes(hitIndex)) return false
    const object = vectorObjects.find((item) => item.index === hitIndex)
    if (!object) return false
    await beginVectorObjectDrag(object, event, scale, true /* shapeMove: no toggle, no clone */)
    return true
  }

  function dragVectorObject(event: PointerEvent) {
    if (!vectorDrag || vectorDrag.pointerId !== event.pointerId) return
    // A claimed finish (pointerup/Escape commit in flight) owns the drag:
    // late moves must not repaint over the committing state.
    if (vectorDrag.committing) return
    // Stale-owner guard: a target/costume switch mid-drag clears the drag in
    // `resetCostumeEditorSelection`, but an already-queued pointermove must
    // never write to the old asset. Drop it without history or guide, and
    // restore the live preview (a local preview may have painted the old art).
    if (selectedTarget && (selectedTarget.name !== vectorDrag.targetName || (selectedTarget.currentCostume ?? 0) !== vectorDrag.costumeIndex)) {
      cancelVectorMovePreview(vectorDrag)
      vectorDrag = undefined
      if (selectedTarget) void refreshCostumePreview(selectedTarget)
      return
    }
    // Structural epoch guard: a delete/reorder/duplicate that landed while a
    // frame was queued invalidates this drag. Never preview or enqueue.
    if (vectorDrag.structureEpoch !== getTargetVectorEpoch(vectorDrag.targetId)) {
      cancelVectorMovePreview(vectorDrag)
      vectorDrag = undefined
      if (selectedTarget) void refreshCostumePreview(selectedTarget)
      return
    }
    const scale = vectorDrag.scale || 1
    const total = resolveVectorSnapTotal(
      { x: (event.clientX - vectorDrag.startClientX) / scale, y: (event.clientY - vectorDrag.startClientY) / scale },
      vectorDrag.selectionCenter,
      vectorDrag.selectionBounds,
      scale,
      event.shiftKey === true,
    )
    vectorDrag = {
      ...vectorDrag,
      dx: total.x * scale,
      dy: total.y * scale,
      shiftKey: event.shiftKey,
      // Retained shape-tool drags never clone (reference clone=false):
      // force Alt off so press-time and mid-drag Alt stay a plain move.
      altKey: vectorDrag.shapeMove === true ? false : event.altKey,
      guideOpacity: resolveVectorSnapGuide(
        vectorDrag.selectionCenter,
        vectorDrag.selectionBounds,
        { x: (event.clientX - vectorDrag.startClientX) / scale, y: (event.clientY - vectorDrag.startClientY) / scale },
        total,
        scale,
        event.shiftKey === true,
      ),
      // Latest absolute total wins (no stale or lost pointer): every move
      // overwrites, the rAF pass renders the newest exactly once.
      previewTotal: { ...total },
      pendingClientX: event.clientX,
      pendingClientY: event.clientY,
      pendingShiftKey: event.shiftKey,
      pendingAltKey: vectorDrag.shapeMove === true ? false : event.altKey,
    }
    scheduleVectorMovePreview()
  }

  function cancelVectorMovePreview(drag: { previewRaf?: number } | undefined) {
    try {
      if (drag?.previewRaf !== undefined) cancelAnimationFrame(drag.previewRaf)
    } catch {
      // Best-effort only.
    }
    if (drag) drag.previewRaf = undefined
  }

  function scheduleVectorMovePreview() {
    if (!vectorDrag || vectorDrag.previewRaf !== undefined) return
    try {
      vectorDrag = {
        ...vectorDrag,
        previewRaf: requestAnimationFrame(() => {
          void runVectorMovePreview()
        }),
      }
    } catch {
      // No rAF (test env): render synchronously so previews never stall.
      void runVectorMovePreview()
    }
  }

  // rAF-coalesced local preview: zero VM writes, zero Paper imports, zero
  // hashing. Parses the press-time snapshot once, prepends the absolute
  // translate, and swaps the display SVG + outline bounds. History, selection
  // order, and the VM are untouched until the pointerup single commit.
  async function runVectorMovePreview() {
    const drag = vectorDrag
    if (!drag || drag.committing) return
    drag.previewRaf = undefined
    if (selectedTarget && (selectedTarget.name !== drag.targetName || (selectedTarget.currentCostume ?? 0) !== drag.costumeIndex)) return
    if (drag.structureEpoch !== getTargetVectorEpoch(drag.targetId)) return
    const typing = isReshapeTextEditing() || isVectorMoveTypingTarget(document.activeElement)
    try {
      if (!drag.sourceSvgText) {
        const source = await drag.sourceReady?.catch(() => undefined)
        if (!vectorDrag || vectorDrag.pointerId !== drag.pointerId) return
        // A pointerup-claimed commit owns visuals from here: a stale frame
        // awaiting the snapshot must stand down instead of repainting over
        // the synchronous final preview with an older total.
        if (vectorDrag.committing) return
        if (!source) return
        if (selectedTarget && (selectedTarget.name !== drag.targetName || (selectedTarget.currentCostume ?? 0) !== drag.costumeIndex)) return
        drag.sourceSvgText = source.svgText
        if (vectorDrag && vectorDrag.pointerId === drag.pointerId) vectorDrag.sourceSvgText = source.svgText
      }
      if (vectorDrag && vectorDrag.pointerId === drag.pointerId && vectorDrag.committing) return
      const sourceText = (vectorDrag && vectorDrag.pointerId === drag.pointerId ? vectorDrag.sourceSvgText : drag.sourceSvgText) ?? drag.sourceSvgText
      if (!sourceText) return
      // Freshest absolute total wins: moves that landed while the snapshot
      // was in flight updated `vectorDrag.previewTotal`; rendering the
      // frame-start copy would flash a stale position for one frame (and the
      // next scheduled frame would immediately repaint). Read the latest.
      const latest = vectorDrag && vectorDrag.pointerId === drag.pointerId ? vectorDrag : drag
      const total = latest.previewTotal ?? drag.previewTotal ?? { x: 0, y: 0 }
      const pressSelection = drag.pressSelection ?? drag.selection
      // Alt clones once on the first effective move only (press-time Alt or
      // Alt pressed before anything moved). Later Alt toggles never spawn
      // extra copies: `previewMoved` gates, mirroring the old appliedX/Y rule.
      // Read the freshest flags: an overlapping frame may have marked the
      // move already while this frame awaited the snapshot.
      const movedAlready = latest.previewMoved === true || latest.previewDuplicated === true
      const altNow = latest.pendingAltKey ?? latest.altKey
      const wantsCloneNow =
        !movedAlready &&
        !isVectorMoveNoop(total) &&
        drag.shapeMove !== true &&
        shouldDuplicateVectorMove(drag.altAtStart || altNow === true, typing) &&
        !typing
      const effectiveDuplicate = wantsCloneNow || drag.previewDuplicated === true
      const preview = effectiveDuplicate
        ? buildVectorMovePreviewSvg(sourceText, pressSelection, total, { duplicate: true })
        : buildVectorMovePreviewSvg(sourceText, pressSelection, total, {})
      if (!preview) {
        // Zero-total non-duplicate: restore base exactly (no residue).
        if (!effectiveDuplicate && drag.basePreviewSvg !== undefined && costumePreviewSvg !== drag.basePreviewSvg) {
          costumePreviewSvg = drag.basePreviewSvg
        }
        if (!effectiveDuplicate && drag.baseObjects && vectorObjects !== drag.baseObjects) {
          vectorObjects = [...drag.baseObjects]
        }
        if (vectorDrag && vectorDrag.pointerId === drag.pointerId) {
          vectorDrag = { ...vectorDrag, previewRaf: undefined, dx: 0, dy: 0 }
        }
        return
      }
      const nextSelection = [...preview.selection]
      if (!vectorDrag || vectorDrag.pointerId !== drag.pointerId) return
      if (selectedTarget && (selectedTarget.name !== drag.targetName || (selectedTarget.currentCostume ?? 0) !== drag.costumeIndex)) return
      if (drag.structureEpoch !== getTargetVectorEpoch(drag.targetId)) return
      costumePreviewSvg = preview.svgText
      const base = drag.baseObjects ?? vectorObjects
      vectorObjects = effectiveDuplicate
        ? shiftVectorMoveBounds(base, nextSelection, total, { duplicated: true, sources: pressSelection })
        : shiftVectorMoveBounds(base, nextSelection, total)
      vectorDrag = {
        ...vectorDrag,
        previewRaf: undefined,
        previewSelection: nextSelection,
        previewDuplicated: effectiveDuplicate,
        previewMoved: true,
        selection: nextSelection,
        duplicated: vectorDrag.duplicated || effectiveDuplicate,
        // Bounds now carry the move; clear the CSS translate so outlines do
        // not double-shift (single-select parity kept for the pre-rAF gap).
        dx: 0,
        dy: 0,
      }
    } catch {
      // Preview is best-effort: the pointerup commit re-derives everything
      // from the snapshot, so a failed frame never corrupts the drag.
      if (vectorDrag && vectorDrag.pointerId === drag.pointerId) vectorDrag.previewRaf = undefined
    }
  }

  // Clone indices for a freshly duplicated base: the duplicated base has
  // `press.length` more units than the source; clones sit directly after
  // their sources (duplicateVectorUnits order). Re-derive by duplicating the
  // source once (mapping frame only).
  function zeroCloneIndices(_dupBase: string, _pressLength: number): number[] | undefined {
    return undefined
  }

  // Pure snap resolution shared by the preview (`dragVectorObject`) and the
  // committer (`applyLiveVectorDrag`) so both agree on the winning vector.
  // Order: clamp moved center into the workspace, then center-snap (box
  // window, Shift/reshape excluded), else Shift 45-degree projection.
  // Safe fail: unusable scale/center/threshold skips snapping (raw delta).
  function resolveVectorSnapTotal(
    rawDelta: { x: number; y: number },
    selectionCenter: { x: number; y: number } | undefined,
    selectionBounds: MoveRect | undefined,
    scale: number,
    shiftKey: boolean,
  ): { x: number; y: number } {
    void selectionBounds
    const rx = Number.isFinite(rawDelta?.x) ? rawDelta.x : 0
    const ry = Number.isFinite(rawDelta?.y) ? rawDelta.y : 0
    // Clicks (zero raw delta) never move: center-snap must not engage without
    // an actual drag, or a plain select click on an object already near the
    // art center would move it and commit history (dirtying e.g. the bytes a
    // switch-cancel just restored).
    if (rx === 0 && ry === 0) return { x: 0, y: 0 }
    if (!(scale > 0) || !Number.isFinite(scale)) return resolveVectorMoveDelta({ x: rx, y: ry }, { shiftKey })
    if (!selectionCenter || !Number.isFinite(selectionCenter.x) || !Number.isFinite(selectionCenter.y)) {
      return resolveVectorMoveDelta({ x: rx, y: ry }, { shiftKey })
    }
    if (shiftKey === true || isReshapeTextEditing()) {
      return resolveVectorMoveDelta({ x: rx, y: ry }, { shiftKey })
    }
    // Clamp the moved center (not the raw delta) so huge/NaN pointers cannot
    // teleport artwork; the delta is rebuilt from the clamped center.
    const clampedMoved = clampVectorSnapPointer(
      { x: selectionCenter.x + rx, y: selectionCenter.y + ry },
      { ...selectionCenter },
    )
    const clampedDelta = { x: clampedMoved.x - selectionCenter.x, y: clampedMoved.y - selectionCenter.y }
    const threshold = 4 / scale
    if (!Number.isFinite(threshold) || threshold <= 0) {
      return resolveVectorMoveDelta(clampedDelta, { shiftKey })
    }
    try {
      // SVG-unit anchor is the vector art center (240,180 for 480x360), NOT
      // the Paper 480,360 reference: selection centers live in SVG units, so
      // the default MOVE_ART_CENTER would snap 2x off-canvas. The guide
      // (resolveVectorSnapGuide) already uses dims/2; pass the same value
      // here so snap and guide share one anchor.
      const dims = vectorPreviewDimensions()
      const artCenter = { x: dims.width / 2, y: dims.height / 2 }
      const snap = resolveCenterSnap({
        selectionCenter,
        dragVector: clampedDelta,
        artCenter,
        thresholdPaper: threshold,
      })
      if (snap.snapped && snap.snapVector) return { ...snap.snapVector }
    } catch {
      // Safe fail: fall through to the Shift/raw rule without snapping.
    }
    return resolveVectorMoveDelta(clampedDelta, { shiftKey })
  }

  // Drag-guide opacity for the moved selection bounds. Inside the bounds the
  // crosshair stays at full opacity; outside it fades over 10 screen px.
  // Reshape mode and unusable geometry hide the guide (0). Uses the raw
  // pointer-driven center for the fade distance (reference behavior).
  function resolveVectorSnapGuide(
    selectionCenter: { x: number; y: number } | undefined,
    selectionBounds: MoveRect | undefined,
    rawDelta: { x: number; y: number },
    total: { x: number; y: number },
    scale: number,
    shiftKey: boolean,
  ): number {
    try {
      // The crosshair appears on the first effective move only; clicks and
      // sub-pixel jitter stay hidden (and undo-clean).
      if (Math.abs(total?.x ?? 0) < 1e-9 && Math.abs(total?.y ?? 0) < 1e-9) return 0
      if (shiftKey === true || isReshapeTextEditing()) return 0
      if (!selectionCenter || !selectionBounds) return 0
      if (!(scale > 0) || !Number.isFinite(scale)) return 0
      const dims = vectorPreviewDimensions()
      const artCenter = { x: dims.width / 2, y: dims.height / 2 }
      const fade = 10 / scale
      if (!Number.isFinite(fade) || fade <= 0) return 0
      const rx = Number.isFinite(rawDelta?.x) ? rawDelta.x : 0
      const ry = Number.isFinite(rawDelta?.y) ? rawDelta.y : 0
      const rawMoved = { x: selectionCenter.x + rx, y: selectionCenter.y + ry }
      const movedBounds: MoveRect = {
        left: selectionBounds.left + total.x,
        top: selectionBounds.top + total.y,
        right: selectionBounds.right + total.x,
        bottom: selectionBounds.bottom + total.y,
      }
      return crosshairOpacityForBounds(movedBounds, rawMoved, artCenter, fade)
    } catch {
      return 0
    }
  }

  // Legacy entry kept for call-site compatibility: the local-preview path
  // never writes per move. If a stale caller reaches here, fold the sample
  // into the coalesced preview instead of touching the VM.
  async function applyLiveVectorDrag(clientX: number, clientY: number, shiftKey = false, altKey = false) {
    if (!vectorDrag) return
    vectorDrag = {
      ...vectorDrag,
      pendingClientX: clientX,
      pendingClientY: clientY,
      pendingShiftKey: shiftKey,
      pendingAltKey: vectorDrag.shapeMove === true ? false : altKey,
    }
    const scale = vectorDrag.scale || 1
    const total = resolveVectorSnapTotal(
      { x: (clientX - vectorDrag.startClientX) / scale, y: (clientY - vectorDrag.startClientY) / scale },
      vectorDrag.selectionCenter,
      vectorDrag.selectionBounds,
      scale,
      shiftKey,
    )
    vectorDrag = { ...vectorDrag, previewTotal: { ...total } }
    scheduleVectorMovePreview()
  }

  // Shallow-exact equality for the move fast path: the sync pointerup paint
  // already derived the same shifted array from the same base + total, so
  // assigning a recomputed-but-identical array would force Svelte to
  // re-render 120 outlines inside the pointerup task for no pixel change.
  function vectorObjectsEqualForMove(
    current: { index: number; boundsX?: number; boundsY?: number; x?: number; y?: number; points?: { x: number; y: number }[] }[],
    next: { index: number; boundsX?: number; boundsY?: number; x?: number; y?: number; points?: { x: number; y: number }[] }[],
  ): boolean {
    try {
      if (current.length !== next.length) return false
      for (let i = 0; i < next.length; i += 1) {
        const a = current[i]!
        const b = next[i]!
        if (a.index !== b.index) return false
        if ((a.boundsX ?? a.x ?? 0) !== (b.boundsX ?? b.x ?? 0)) return false
        if ((a.boundsY ?? a.y ?? 0) !== (b.boundsY ?? b.y ?? 0)) return false
        const ap = a.points
        const bp = b.points
        if ((ap?.length ?? 0) !== (bp?.length ?? 0)) return false
        if (ap && bp) {
          for (let j = 0; j < bp.length; j += 1) {
            if (ap[j]!.x !== bp[j]!.x || ap[j]!.y !== bp[j]!.y) return false
          }
        }
      }
      return true
    } catch {
      return false
    }
  }

  // Single validated CAS commit for a finished move drag, built from the
  // immutable press-time snapshot (never from live, never incrementally).
  // Unified geometry-translate + runtime viewBox + hashing + VM write +
  // object list happen exactly once here; every pointermove before this was
  // a pure local preview with zero VM traffic. Preview and commit share the
  // same surgical `translate` semantics so `userSpaceOnUse` gradients/clips
  // ride identically (no pointerup snap).
  async function commitVectorMoveFromSnapshot(
    drag: NonNullable<typeof vectorDrag>,
    total: { x: number; y: number },
    finalAltKey: boolean,
  ): Promise<{ committed: boolean; duplicated: boolean; conflicted: boolean; current?: VectorSlotIdentity }> {
    const target = vm.getTarget(drag.targetName) ?? selectedTarget
    if (!target) return { committed: false, duplicated: false, conflicted: false }
    if (selectedTarget && (selectedTarget.name !== drag.targetName || (selectedTarget.currentCostume ?? 0) !== drag.costumeIndex)) {
      return { committed: false, duplicated: false, conflicted: false }
    }
    if (drag.structureEpoch !== getTargetVectorEpoch(drag.targetId)) {
      return { committed: false, duplicated: false, conflicted: false }
    }
    if (isVectorGestureConflicted(drag.gestureId)) {
      return { committed: false, duplicated: false, conflicted: true }
    }
    const typing = isReshapeTextEditing() || isVectorMoveTypingTarget(document.activeElement)
    const movedAlready = drag.previewMoved === true || drag.previewDuplicated === true
    const wantsClone =
      !movedAlready &&
      !isVectorMoveNoop(total) &&
      drag.shapeMove !== true &&
      shouldDuplicateVectorMove(drag.altAtStart || finalAltKey === true, typing) &&
      !typing
    const effectiveDuplicate = wantsClone || drag.previewDuplicated === true
    if (isVectorMoveNoop(total) && !effectiveDuplicate) {
      return { committed: false, duplicated: false, conflicted: false }
    }
    let sourceText = drag.sourceSvgText
    if (!sourceText) {
      const source = await drag.sourceReady?.catch(() => undefined)
      sourceText = source?.svgText
    }
    if (!sourceText) {
      const loaded = await currentSvgDocument(target, drag.costumeIndex)
      if (loaded) sourceText = new XMLSerializer().serializeToString(loaded.doc.documentElement)
    }
    if (!sourceText) return { committed: false, duplicated: false, conflicted: false }
    if (selectedTarget && (selectedTarget.name !== drag.targetName || (selectedTarget.currentCostume ?? 0) !== drag.costumeIndex)) {
      return { committed: false, duplicated: false, conflicted: false }
    }
    if (drag.structureEpoch !== getTargetVectorEpoch(drag.targetId)) {
      return { committed: false, duplicated: false, conflicted: false }
    }
    const pressSelection = drag.pressSelection ?? drag.selection
    const doc = new DOMParser().parseFromString(sourceText, 'image/svg+xml')
    const svg = doc.documentElement
    if (!svg || svg.nodeName.toLowerCase() !== 'svg' || doc.getElementsByTagName('parsererror').length > 0) {
      return { committed: false, duplicated: false, conflicted: false }
    }
    let units = editableVectorUnits(svg)
    let active = [...new Set(pressSelection)].filter((index) => Number.isInteger(index) && index >= 0 && index < units.length)
    if (active.length === 0) {
      active = normalizedVectorSelection(units.length)
      if (active.length === 0) return { committed: false, duplicated: false, conflicted: false }
    }
    if (effectiveDuplicate) {
      const clones = duplicateVectorUnits(svg, active)
      if (clones.length === 0) return { committed: false, duplicated: false, conflicted: false }
      units = editableVectorUnits(svg)
      active = clones
      for (const index of active) {
        const element = units[index]
        if (element) await moveVectorElementBy(element, total.x, total.y)
      }
    } else {
      let appliedAny = false
      for (const index of active) {
        const element = units[index]
        if (element && (await moveVectorElementBy(element, total.x, total.y))) appliedAny = true
      }
      if (!appliedAny) return { committed: false, duplicated: false, conflicted: false }
    }
    const editedText = new XMLSerializer().serializeToString(doc.documentElement)
    // Arm the in-flight guard BEFORE the CAS: the CAS applies + emits (which
    // trips the reactive `assetSignature` effect) while awaited, so the flag
    // must already be set when that effect runs. Cleared right after the CAS
    // settles; the effect is scheduled during the emit and therefore always
    // observes the armed flag (FIFO), while any later change observes it
    // cleared and refreshes normally.
    vectorMoveCommitPending = { targetId: drag.targetId, index: drag.costumeIndex, projectGeneration: readProjectGenerationSafe(), selectionEpoch: readSelectionEpochSafe() }
    let moveCommit: VectorEditorCommitResult
    try {
      moveCommit = await updateVectorCostumeFromEditor(
        target,
        drag.costumeIndex,
        editedText,
        {
          gestureId: drag.gestureId,
          kind: 'preview' as const,
          expectedStructureEpoch: drag.structureEpoch,
        },
      )
    } finally {
      vectorMoveCommitPending = undefined
    }
    if (moveCommit.kind !== 'applied') {
      if (moveCommit.reason === 'external' || isVectorGestureConflicted(drag.gestureId)) {
        return { committed: false, duplicated: false, conflicted: true }
      }
      return { committed: false, duplicated: false, conflicted: false }
    }
    if (isVectorGestureConflicted(drag.gestureId)) {
      return { committed: false, duplicated: false, conflicted: true }
    }
    // Own-identity adoption + post-CAS live re-validation (barrier
    // isolation): adopt the CAS `result.current` identity (never a fresh
    // read) into the effect guard, then compare the LIVE slot against it. A
    // direct-VM same-slot external that landed after our CAS applied but
    // before this continuation resumed (different green, metadata-only
    // rename, or same-bytes rewrite — all bump `writeSeq`) must win:
    // fail-safe external, refresh from live, mark conflicted, no fastpath
    // paint and no history. Without this, the armed slot-only guard would
    // swallow the external in the reactive effect below.
    if (moveCommit.kind === 'applied' && moveCommit.current) {
      vectorMoveCommitPending = {
        targetId: drag.targetId,
        index: drag.costumeIndex,
        md5ext: moveCommit.current.md5ext ?? null,
        writeSeq: typeof moveCommit.current.writeSeq === 'number' ? moveCommit.current.writeSeq : null,
        hasIdentity: true,
        projectGeneration: readProjectGenerationSafe(),
        selectionEpoch: readSelectionEpochSafe(),
      }
      try {
        const liveAfterCommit = readLiveSlotIdentity(drag.targetId, drag.costumeIndex)
        const md5Match = (liveAfterCommit.md5ext ?? null) === (moveCommit.current.md5ext ?? null)
        const seqMatch =
          typeof liveAfterCommit.writeSeq === 'number' || typeof moveCommit.current.writeSeq === 'number'
            ? liveAfterCommit.writeSeq === moveCommit.current.writeSeq
            : true
        if (!md5Match || !seqMatch) {
          markVectorGestureConflicted(drag.gestureId)
          await refreshVectorPreviewFromLive(drag.targetId, target)
          return { committed: false, duplicated: false, conflicted: true, current: liveAfterCommit }
        }
      } catch {
        // Best effort: on unreadable identity keep the applied path; the
        // effect-side identity check still guards the refresh.
      }
    }
    // Validated shifted-cache fast path (no Paper re-measure, no reload):
    // a pure translate shifts document-space bounds/points by exactly `total`
    // (rotation/ancestor/paint invariant), and the commit prepends the same
    // parent-frame `translate` as the already-painted sync preview, so the
    // display SVG bytes are identical (runtime tight viewBox re-centers to
    // dx=dy=0). Reuse the pre-drag display objects shifted arithmetically and
    // keep the synchronously painted preview pixels; fall back to the full
    // Paper list + refresh only when validation fails (count/finite mismatch).
    const baseObjects = drag.baseObjects
    if (baseObjects && baseObjects.length > 0 && Number.isFinite(total.x) && Number.isFinite(total.y)) {
      try {
        const shifted = effectiveDuplicate
          ? shiftVectorMoveBounds(baseObjects, active, total, { duplicated: true, sources: pressSelection })
          : shiftVectorMoveBounds(baseObjects, active, total)
        const expectedLen = effectiveDuplicate ? baseObjects.length + active.length : baseObjects.length
        const finite = shifted.every(
          (object) => Number.isFinite(object.boundsX ?? object.x ?? 0) && Number.isFinite(object.boundsY ?? object.y ?? 0),
        )
        // Index integrity: the cache must be positional (duplicate indices or
        // stale positions mean the interleaved duplicate layout diverged).
        const positional = shifted.every((object, position) => object.index === position)
        if (shifted.length === expectedLen && finite && positional) {
          // Guarantee final pixels even if the sync preview missed (e.g. the
          // snapshot arrived late): rebuild the cheap display preview from the
          // same snapshot + total (one DOM parse/serialize, zero Paper/VM).
          // When the sync paint already ran this recomputes identical bytes,
          // and identical assignments are skipped so the browser never
          // re-parses the same 120-node SVG or re-renders identical outlines
          // inside the pointerup longtask.
          try {
            const cheap = effectiveDuplicate
              ? buildVectorMovePreviewSvg(sourceText, pressSelection, total, { duplicate: true })
              : buildVectorMovePreviewSvg(sourceText, pressSelection, total, {})
            if (cheap && costumePreviewSvg !== cheap.svgText) costumePreviewSvg = cheap.svgText
          } catch {
            // Keep the sync-painted pixels on best-effort failure.
          }
          if (!vectorObjectsEqualForMove(vectorObjects, shifted)) vectorObjects = shifted
          if (effectiveDuplicate) {
            selectedVectorObjectIndices = [...active].sort((a, b) => a - b)
            selectedVectorObjectIndex = selectedVectorObjectIndices.at(-1) ?? -1
          } else {
            selectedVectorObjectIndices = active.filter((index) => vectorObjects.some((object) => object.index === index))
            selectedVectorObjectIndex = selectedVectorObjectIndices.at(-1) ?? drag.index
          }
          // The sync preview already painted the final display SVG + shifted
          // outlines before this CAS landed; keep those pixels (no stale
          // ownership: UI never waits on the write). No refresh: the live
          // bytes equal the committed runtime text and the display frame is
          // translate-invariant, so a reload would only recompute identical
          // values via two 120-import Paper passes.
          return { committed: true, duplicated: effectiveDuplicate, conflicted: false, current: moveCommit.current }
        }
      } catch {
        // Fall through to the Paper fallback below.
      }
    }
    const nextSvg = moveCommit.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (effectiveDuplicate) {
      selectedVectorObjectIndices = [...active].sort((a, b) => a - b)
      selectedVectorObjectIndex = selectedVectorObjectIndices.at(-1) ?? -1
    } else {
      selectedVectorObjectIndices = active.filter((index) => vectorObjects.some((object) => object.index === index))
      selectedVectorObjectIndex = selectedVectorObjectIndices.at(-1) ?? drag.index
    }
    await refreshCostumePreview(vm.getTarget(target.name) ?? selectedTarget)
    return { committed: true, duplicated: effectiveDuplicate, conflicted: false, current: moveCommit.current }
  }


  type VectorMoveDragState = {
    targetName: string
    costumeIndex: number
    selection: number[]
    duplicated: boolean
    appliedX: number
    appliedY: number
    index: number
    structureEpoch?: number
    targetId?: string
    gestureId?: VectorWriteGesture
  }

  type VectorMoveResult = { selection: number[] } | undefined

  async function moveVectorSelectionFromCurrent(
    target: ScratchTarget | undefined,
    drag: VectorMoveDragState,
    total: { x: number; y: number },
    incremental: { x: number; y: number },
    wantsClone: boolean
  ): Promise<VectorMoveResult> {
    if (!target) return undefined
    if (isVectorMoveNoop(incremental)) return undefined
    const moveTargetId = stableTargetId(target)
    const moveScope = captureDiscreteSaveScope(moveTargetId, drag.costumeIndex)
    const moveScopeAlive = () => isDiscreteSaveScopeCurrent(moveScope, discreteSaveLiveOf(moveScope))
    // Structural epoch guard: a delete/reorder/duplicate that landed while
    // the async SVG load was in flight invalidates this frame. A
    // check-before-await alone is insufficient because the write itself is
    // delayed (gated VM); the epoch check at enqueue time (below) is the
    // atomic barrier.
    const dragEpoch = drag.structureEpoch
    if (dragEpoch !== undefined && dragEpoch !== getTargetVectorEpoch(stableTargetId(target))) return undefined
    const loaded = await currentSvgDocument(target, drag.costumeIndex)
    if (!loaded) return undefined
    const { doc, svg } = loaded
    let units = editableVectorUnits(svg)
    let selection = [...drag.selection].filter((index) => index >= 0 && index < units.length)
    if (selection.length === 0) {
      selection = normalizedVectorSelection(units.length)
      if (selection.length === 0) return undefined
    }
    if (wantsClone) {
      const clones = duplicateVectorUnits(svg, selection)
      if (clones.length === 0) return undefined
      units = editableVectorUnits(svg)
      selection = clones
      // First effective move carries the full total onto the fresh clones.
      // The clone insertion itself is a change, so a refused move still
      // counts as applied (duplicate without displacement).
      for (const index of selection) {
        const element = units[index]
        if (element) await moveVectorElementBy(element, total.x, total.y)
      }
    } else {
      let appliedAny = false
      for (const index of selection) {
        const element = units[index]
        if (element && (await moveVectorElementBy(element, incremental.x, incremental.y))) appliedAny = true
      }
      if (!appliedAny) return undefined
    }
    const moveCommit = await updateVectorCostumeFromEditor(
      target,
      drag.costumeIndex,
      new XMLSerializer().serializeToString(doc.documentElement),
      drag.gestureId || dragEpoch !== undefined
        ? {
            ...(drag.gestureId ? { gestureId: drag.gestureId, kind: 'preview' as const } : {}),
            ...(dragEpoch !== undefined ? { expectedStructureEpoch: dragEpoch } : {}),
          }
        : { quiet: true, isAlive: moveScopeAlive },
    )
    if (!drag.gestureId && moveCommit.kind !== 'applied') {
      if (moveScopeAlive() || (moveCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(moveScope, discreteSaveLiveOf(moveScope)))) {
        await refreshVectorPreviewFromLive(moveTargetId, target)
        reportVectorExternalConflict('Move')
      }
      return undefined
    }
    const nextSvg = moveCommit.svgText
    if (drag.gestureId && isVectorGestureConflicted(drag.gestureId)) {
      // External won: keep it, drop residue, no history usable (generation
      // bumped). The move caller treats this as not-applied.
      if (drag.targetId) await refreshVectorPreviewFromLive(drag.targetId, target)
      return undefined
    }
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (!drag.gestureId && !moveScopeAlive()) return undefined
    if (wantsClone) {
      selectedVectorObjectIndices = [...selection].sort((a, b) => a - b)
      selectedVectorObjectIndex = selectedVectorObjectIndices.at(-1) ?? -1
    } else {
      selectedVectorObjectIndices = selection.filter((index) => vectorObjects.some((object) => object.index === index))
      selectedVectorObjectIndex = selectedVectorObjectIndices.at(-1) ?? drag.index
    }
    await refreshCostumePreview(vm.getTarget(target.name) ?? selectedTarget)
    return { selection: selectedVectorObjectIndices }
  }

  async function endVectorObjectDrag(event: PointerEvent) {
    if (!vectorDrag || vectorDrag.pointerId !== event.pointerId) return
    // Single-commit owner: an Escape-claimed commit (committing set
    // synchronously in the keydown dispatch) owns the one CAS write. A
    // pointerup arriving during it must not start a second commit.
    if (vectorDrag.committing) return
    // Sync claim (resize/rotate parity): the trailing implicit
    // `lostpointercapture` auto-loss after pointerup must not clear the
    // just-released drag before the single commit lands.
    cancelVectorMovePreview(vectorDrag)
    vectorDrag = { ...vectorDrag, committing: true, previewRaf: undefined }
    const myGestureId = vectorDrag.gestureId
    const myTargetId = vectorDrag.targetId
    const dragAtRelease = { ...vectorDrag }
    // Apply the latest pointer exactly once (no stale or lost): recompute the
    // absolute total from this event (not from a coalesced frame), paint the
    // final preview synchronously for immediate visuals, then commit once.
    const scale = dragAtRelease.scale || 1
    const finalAlt = dragAtRelease.shapeMove === true ? false : event.altKey
    const rawDelta = {
      x: (event.clientX - dragAtRelease.startClientX) / scale,
      y: (event.clientY - dragAtRelease.startClientY) / scale,
    }
    const finalTotal = resolveVectorSnapTotal(
      rawDelta,
      dragAtRelease.selectionCenter,
      dragAtRelease.selectionBounds,
      scale,
      event.shiftKey === true,
    )
    const finalGuide = resolveVectorSnapGuide(
      dragAtRelease.selectionCenter,
      dragAtRelease.selectionBounds,
      rawDelta,
      finalTotal,
      scale,
      event.shiftKey === true,
    )
    if (vectorDrag && vectorDrag.gestureId === myGestureId) {
      vectorDrag = {
        ...vectorDrag,
        previewTotal: { ...finalTotal },
        guideOpacity: finalGuide,
        shiftKey: event.shiftKey,
        altKey: finalAlt,
        pendingClientX: event.clientX,
        pendingClientY: event.clientY,
        pendingShiftKey: event.shiftKey,
        pendingAltKey: finalAlt,
        dx: 0,
        dy: 0,
      }
    }
    // Immediate visual: render the final absolute preview synchronously from
    // the snapshot (no VM), so pointerup pixels move even before the CAS lands.
    try {
      const syncDrag = vectorDrag && vectorDrag.gestureId === myGestureId ? vectorDrag : dragAtRelease
      let syncSource = syncDrag.sourceSvgText
      if (!syncSource) {
        const loaded = await syncDrag.sourceReady?.catch(() => undefined)
        syncSource = loaded?.svgText
        if (syncSource && vectorDrag && vectorDrag.gestureId === myGestureId) vectorDrag.sourceSvgText = syncSource
      }
      if (syncSource) {
        const pressSelection = syncDrag.pressSelection ?? syncDrag.selection
        const typingNow = isReshapeTextEditing() || isVectorMoveTypingTarget(document.activeElement)
        const movedAlready = syncDrag.previewMoved === true || syncDrag.previewDuplicated === true
        const wantsCloneSync =
          !movedAlready &&
          !isVectorMoveNoop(finalTotal) &&
          syncDrag.shapeMove !== true &&
          shouldDuplicateVectorMove(syncDrag.altAtStart || finalAlt === true, typingNow) &&
          !typingNow
        const effectiveDupSync = wantsCloneSync || syncDrag.previewDuplicated === true
        const syncPreview = effectiveDupSync
          ? buildVectorMovePreviewSvg(syncSource, pressSelection, finalTotal, { duplicate: true })
          : buildVectorMovePreviewSvg(syncSource, pressSelection, finalTotal, {})
        if (syncPreview) {
          costumePreviewSvg = syncPreview.svgText
          const base = syncDrag.baseObjects ?? vectorObjects
          vectorObjects = effectiveDupSync
            ? shiftVectorMoveBounds(base, syncPreview.selection, finalTotal, { duplicated: true, sources: pressSelection })
            : shiftVectorMoveBounds(base, syncPreview.selection, finalTotal)
          if (vectorDrag && vectorDrag.gestureId === myGestureId) {
            vectorDrag = {
              ...vectorDrag,
              previewSelection: [...syncPreview.selection],
              previewDuplicated: effectiveDupSync,
              previewMoved: true,
              selection: [...syncPreview.selection],
              duplicated: vectorDrag.duplicated || effectiveDupSync,
            }
          }
        } else if (!effectiveDupSync && syncDrag.basePreviewSvg !== undefined) {
          costumePreviewSvg = syncDrag.basePreviewSvg
          if (syncDrag.baseObjects) vectorObjects = [...syncDrag.baseObjects]
        }
      }
    } catch {
      // Best-effort only; the commit below re-derives from the snapshot.
    }
    // Owner / epoch race: a target/costume switch or structural change that
    // landed before release discards the drag with no write and no history.
    // The live preview already shows the new asset (or will after refresh).
    const releaseDrag = vectorDrag && vectorDrag.gestureId === myGestureId ? vectorDrag : dragAtRelease
    if (selectedTarget && (selectedTarget.name !== releaseDrag.targetName || (selectedTarget.currentCostume ?? 0) !== releaseDrag.costumeIndex)) {
      if (vectorDrag && vectorDrag.gestureId === myGestureId) vectorDrag = undefined
      clearVectorGestureIdentity(myGestureId)
      if (selectedTarget) await refreshCostumePreview(selectedTarget)
      return
    }
    if (releaseDrag.structureEpoch !== getTargetVectorEpoch(releaseDrag.targetId)) {
      if (vectorDrag && vectorDrag.gestureId === myGestureId) vectorDrag = undefined
      clearVectorGestureIdentity(myGestureId)
      if (selectedTarget) await refreshCostumePreview(selectedTarget)
      return
    }
    if (isVectorGestureConflicted(myGestureId)) {
      await refreshVectorPreviewFromLive(releaseDrag.targetId, selectedTarget ?? undefined)
      reportVectorExternalConflict('Move')
      clearVectorGestureIdentity(myGestureId)
      if (vectorDrag && vectorDrag.gestureId === myGestureId) vectorDrag = undefined
      return
    }
    // Peek history lazily (clicks never reach here with a commit, so no
    // empty entries). `historyReady` was captured at press; await it now.
    let pendingEntry: AssetHistoryEntry | undefined = releaseDrag.pendingEntry
    if (!pendingEntry && releaseDrag.historyReady) {
      try {
        pendingEntry = await releaseDrag.historyReady.catch(() => undefined)
      } catch {
        pendingEntry = undefined
      }
    }
    if (!pendingEntry && selectedTarget) {
      try {
        const target = vm.getTarget(releaseDrag.targetName) ?? selectedTarget
        if (target) pendingEntry = await peekCostumeHistory(target, releaseDrag.costumeIndex)
      } catch {
        pendingEntry = undefined
      }
    }
    const commitDrag = vectorDrag && vectorDrag.gestureId === myGestureId ? vectorDrag : releaseDrag
    const outcome = await commitVectorMoveFromSnapshot(commitDrag, finalTotal, finalAlt)
    // A newcomer took the global mid-commit: retire only our identity and
    // leave the new drag + status untouched.
    if (!vectorDrag || vectorDrag.gestureId !== myGestureId) {
      if (outcome.conflicted) {
        await refreshVectorPreviewFromLive(commitDrag.targetId, selectedTarget ?? undefined)
      }
      clearVectorGestureIdentity(myGestureId)
      return
    }
    // Exact slot completion before retiring the identity (fail-closed settle,
    // bounded): retiring early would strand `known` behind `live`.
    await settleVectorGestureSlotCompletion(
      () => {
        const settled = vectorDrag
        if (!settled || settled.gestureId !== myGestureId) return 'gone'
        return 'settled'
      },
      () => drainTargetVectorWrites(myTargetId),
    )
    if (!vectorDrag || vectorDrag.gestureId !== myGestureId) {
      clearVectorGestureIdentity(myGestureId)
      return
    }
    if (outcome.conflicted) {
      await refreshVectorPreviewFromLive(commitDrag.targetId, selectedTarget ?? undefined)
      reportVectorExternalConflict('Move')
      clearVectorGestureIdentity(myGestureId)
      vectorDrag = undefined
      return
    }
    const changed = outcome.committed
    const duplicated = outcome.duplicated
    // Post-settle barrier (fail-safe external wins): a direct-VM same-slot
    // write that landed after the commit's own live check (during
    // quiescence, before history is minted) still diverges the live slot
    // from our committed identity. Re-validate before touching history: on
    // divergence refresh from live, report the conflict, and mint NO history
    // entry, so Undo can never delete the external bytes. (Even without
    // this, Undo's own live-vs-known compare would refuse, but the history
    // entry would wrongly linger and the status would claim a move.)
    if (changed && outcome.current) {
      try {
        const liveBeforeHistory = readLiveSlotIdentity(commitDrag.targetId, commitDrag.costumeIndex)
        const historyMd5Match = (liveBeforeHistory.md5ext ?? null) === (outcome.current.md5ext ?? null)
        const historySeqMatch =
          typeof liveBeforeHistory.writeSeq === 'number' || typeof outcome.current.writeSeq === 'number'
            ? liveBeforeHistory.writeSeq === outcome.current.writeSeq
            : true
        if (!historyMd5Match || !historySeqMatch) {
          await refreshVectorPreviewFromLive(commitDrag.targetId, selectedTarget ?? undefined)
          reportVectorExternalConflict('Move')
          clearVectorGestureIdentity(myGestureId)
          vectorDrag = undefined
          return
        }
      } catch {
        // Best effort: fall through to the history commit.
      }
    }
    if (changed && pendingEntry) commitPaintHistory(pendingEntry)
    if (!changed) {
      // No-op release (click / return-to-start): restore the base exactly so
      // no preview residue lingers, with no history entry. Fail-closed: when
      // the drag identity is already gone there is nothing to restore.
      const baseDrag = vectorDrag
      if (baseDrag !== undefined && baseDrag.gestureId === myGestureId) {
        if (baseDrag.basePreviewSvg !== undefined && costumePreviewSvg !== baseDrag.basePreviewSvg) {
          costumePreviewSvg = baseDrag.basePreviewSvg
        }
        if (baseDrag.baseObjects) vectorObjects = [...baseDrag.baseObjects]
      }
    }
    const finished = vectorDrag
    clearVectorGestureIdentity(myGestureId)
    vectorDrag = undefined
    if (changed && finished) {
      try {
        const live = selectedTarget ? vectorWriteTargetById(finished.targetId, selectedTarget.name) ?? selectedTarget : undefined
        const idx = finished.costumeIndex
        const cost = live?.costumes[idx]
        const key = cost?.md5ext ?? cost?.assetId
        void (async () => {
          try {
            if (!live || !key) return
            const bytes = await vm.loadAsset(key, cost?.dataFormat ?? '')
            if (bytes && selectedTarget && stableTargetId(selectedTarget) === finished.targetId && (selectedTarget.currentCostume ?? 0) === idx) {
              rememberCommittedReshapeSelection(finished.targetId, idx, new Uint8Array(bytes as Uint8Array))
            }
          } catch {}
        })()
      } catch {
        // Best-effort only.
      }
    }
    status = !changed ? 'Vector move: no change' : duplicated ? 'Vector object duplicated' : 'Vector object moved'
  }


  function beginVectorObjectResize(object: VectorObjectInfo, handle: VectorResizeHandle, event: PointerEvent) {
    if (!selectedTarget) return
    event.preventDefault()
    event.stopPropagation()
    // 複数選択中のいずれかの枠ハンドル操作は共有境界ドラッグとして開始し、
    // 選択全体を維持する。新規単一対象のときのみ単一へ正規化する。
    const multiSelection = normalizedVectorSelection(vectorObjects.length).filter((index) => vectorObjects.some((item) => item.index === index))
    const isMulti = multiSelection.length > 1 && multiSelection.includes(object.index)
    if (!isMulti) selectVectorObject(object.index, false)
    const selection = isMulti ? multiSelection : [object.index]
    const element = event.currentTarget as HTMLElement
    const host = element.parentElement
    const rect = host?.getBoundingClientRect()
    const dims = host?.dataset.vectorStageSurface === 'true' ? { width: 480, height: 360 } : vectorPreviewDimensions()
    const scale = rect ? Math.min(rect.width / dims.width, rect.height / dims.height) : 1
    const target = selectedTarget
    const costumeIndex = target.currentCostume ?? 0
    element.setPointerCapture(event.pointerId)
    vectorResizeDrag = {
      index: object.index,
      handle,
      pointerId: event.pointerId,
      startClientX: event.clientX,
      startClientY: event.clientY,
      dx: 0,
      dy: 0,
      scale,
      applying: false,
      historyReady: peekCostumeHistory(target, costumeIndex).catch(() => undefined),
      pendingEntry: undefined,
      gestureId: beginVectorWriteGesture(),
      committing: false,
      moved: false,
      historyCaptured: false,
      multi: isMulti,
      selection,
      targetName: target.name,
      targetId: stableTargetId(target),
      costumeIndex,
      structureEpoch: getTargetVectorEpoch(stableTargetId(target)),
      shiftKey: event.shiftKey,
      altKey: event.altKey,
      sourceReady: currentSvgDocument(target, costumeIndex).then((loaded) => loaded
        ? { targetName: target.name, costumeIndex, svgText: new XMLSerializer().serializeToString(loaded.doc.documentElement) }
        : undefined),
    }
    captureVectorGestureIdentity(stableTargetId(target), costumeIndex, vectorResizeDrag.gestureId)
  }

  // 共有選択境界 (union) ハンドルのドラッグ開始。対象は現在の複数選択全体で、
  // 選択・前面順は操作前後で維持される。
  function beginVectorMultiResize(handle: VectorResizeHandle, event: PointerEvent) {
    if (!selectedTarget) return
    event.preventDefault()
    event.stopPropagation()
    const multiSelection = normalizedVectorSelection(vectorObjects.length).filter((index) => vectorObjects.some((item) => item.index === index))
    if (multiSelection.length < 2) return
    const element = event.currentTarget as HTMLElement
    const host = element.parentElement
    const rect = host?.getBoundingClientRect()
    const dims = host?.dataset.vectorStageSurface === 'true' ? { width: 480, height: 360 } : vectorPreviewDimensions()
    const scale = rect ? Math.min(rect.width / dims.width, rect.height / dims.height) : 1
    const target = selectedTarget
    const costumeIndex = target.currentCostume ?? 0
    element.setPointerCapture(event.pointerId)
    vectorResizeDrag = {
      index: multiSelection.at(-1) ?? -1,
      handle,
      pointerId: event.pointerId,
      startClientX: event.clientX,
      startClientY: event.clientY,
      dx: 0,
      dy: 0,
      scale,
      applying: false,
      historyReady: peekCostumeHistory(target, costumeIndex).catch(() => undefined),
      pendingEntry: undefined,
      gestureId: beginVectorWriteGesture(),
      committing: false,
      moved: false,
      historyCaptured: false,
      multi: true,
      selection: multiSelection,
      targetName: target.name,
      targetId: stableTargetId(target),
      costumeIndex,
      structureEpoch: getTargetVectorEpoch(stableTargetId(target)),
      shiftKey: event.shiftKey,
      altKey: event.altKey,
      sourceReady: currentSvgDocument(target, costumeIndex).then((loaded) => loaded
        ? { targetName: target.name, costumeIndex, svgText: new XMLSerializer().serializeToString(loaded.doc.documentElement) }
        : undefined),
    }
    captureVectorGestureIdentity(stableTargetId(target), costumeIndex, vectorResizeDrag.gestureId)
  }

  function dragVectorObjectResize(event: PointerEvent) {
    if (!vectorResizeDrag || vectorResizeDrag.pointerId !== event.pointerId) return
    vectorResizeDrag = {
      ...vectorResizeDrag,
      dx: event.clientX - vectorResizeDrag.startClientX,
      dy: event.clientY - vectorResizeDrag.startClientY,
      shiftKey: event.shiftKey,
      altKey: event.altKey,
    }
    void applyLiveVectorResize(event.clientX, event.clientY, event.shiftKey, event.altKey)
  }

  async function applyLiveVectorResize(clientX: number, clientY: number, shiftKey = false, altKey = false) {
    if (!vectorResizeDrag) return
    if (vectorResizeDrag.applying) {
      vectorResizeDrag = { ...vectorResizeDrag, pendingClientX: clientX, pendingClientY: clientY, pendingShiftKey: shiftKey, pendingAltKey: altKey }
      return
    }
    if (vectorResizeDrag.structureEpoch !== getTargetVectorEpoch(vectorResizeDrag.targetId)) {
      vectorResizeDrag = undefined
      return
    }
    const drag = { ...vectorResizeDrag, applying: true, shiftKey, altKey }
    vectorResizeDrag = drag
    const dw = (clientX - drag.startClientX) / (drag.scale || 1)
    const dh = (clientY - drag.startClientY) / (drag.scale || 1)
    if (dw || dh) {
      // Deferred preview (rotate/point/leaf parity): every frame writes with
      // {gestureId, kind:'preview'} on the same per-slot FIFO, no history
      // commit here. Pointerup owns the single commit after quiescence.
      const applied = drag.multi
        ? await resizeMultiVectorSelectionFromSource(drag.sourceReady, drag.selection, drag.handle, dw, dh, { shiftKey, altKey }, drag.structureEpoch, drag.targetId, { gestureId: drag.gestureId, targetId: drag.targetId })
        : await resizeSelectedVectorObjectFromSource(drag.sourceReady, drag.index, drag.handle, dw, dh, { shiftKey, altKey }, drag.structureEpoch, drag.targetId, { gestureId: drag.gestureId, targetId: drag.targetId })
      if (applied) {
        if (!vectorResizeDrag || vectorResizeDrag.pointerId !== drag.pointerId) return
        vectorResizeDrag = { ...vectorResizeDrag, moved: true }
      }
      // no-op 時は何も積まず redo にも触れない。
    }
    if (!vectorResizeDrag || vectorResizeDrag.pointerId !== drag.pointerId) return
    const pendingClientX = vectorResizeDrag.pendingClientX
    const pendingClientY = vectorResizeDrag.pendingClientY
    const pendingShiftKey = vectorResizeDrag.pendingShiftKey ?? shiftKey
    const pendingAltKey = vectorResizeDrag.pendingAltKey ?? altKey
    vectorResizeDrag = {
      ...vectorResizeDrag,
      dx: 0,
      dy: 0,
      applying: false,
      pendingClientX: undefined,
      pendingClientY: undefined,
      pendingShiftKey: undefined,
      pendingAltKey: undefined,
    }
    if (pendingClientX !== undefined && pendingClientY !== undefined && (pendingClientX !== clientX || pendingClientY !== clientY)) {
      void applyLiveVectorResize(pendingClientX, pendingClientY, pendingShiftKey, pendingAltKey)
    }
  }

  async function endVectorObjectResize(event: PointerEvent) {
    if (!vectorResizeDrag || vectorResizeDrag.pointerId !== event.pointerId) return
    const wasMulti = vectorResizeDrag.multi
    const myResizeTargetId = vectorResizeDrag.targetId
    const myResizePointerId = vectorResizeDrag.pointerId
    // Sync claim (rotate/point/leaf parity): the trailing implicit
    // `lostpointercapture` auto-loss after pointerup must not clear the
    // just-released drag before the deferred commit lands.
    vectorResizeDrag = { ...vectorResizeDrag, committing: true }
    await applyLiveVectorResize(event.clientX, event.clientY, event.shiftKey, event.altKey)
    // Wait for quiescence: a coalesced move queued inside the in-flight frame
    // resolves only after `applying === false && pending === undefined`.
    // Re-apply the final absolute delta once (idempotent from the immutable
    // snapshot) so the final artwork actually changed decides history.
    for (let attempt = 0; attempt < 200; attempt += 1) {
      const settled = vectorResizeDrag
      if (!settled || (!settled.applying && settled.pendingClientX === undefined)) break
      await new Promise((resolve) => setTimeout(resolve, 10))
    }
    if (vectorResizeDrag && vectorResizeDrag.pointerId === event.pointerId) {
      await applyLiveVectorResize(event.clientX, event.clientY, event.shiftKey, event.altKey)
    }
    // Captured exact slot completion before retiring the identity (move-end
    // parity): a >2s gated write outlives the flag loop above, and retiring
    // early strands `known` behind `live`.
    await settleVectorGestureSlotCompletion(
      () => {
        const settled = vectorResizeDrag
        if (!settled || settled.pointerId !== myResizePointerId) return 'gone'
        return !settled.applying && settled.pendingClientX === undefined ? 'settled' : 'busy'
      },
      () => drainTargetVectorWrites(myResizeTargetId),
    )
    const drag = vectorResizeDrag
    // Pointerup uses the gesture snapshot's last seq: a conflicted gesture
    // never force-writes — keep the external, drop residue, no history.
    if (drag && isVectorGestureConflicted(drag.gestureId)) {
      await refreshVectorPreviewFromLive(drag.targetId, selectedTarget ?? undefined)
      reportVectorExternalConflict('Resize')
      clearVectorGestureIdentity(drag.gestureId)
      vectorResizeDrag = undefined
      return
    }
    // Only a preview that actually moved AND a resolved pre-drag entry
    // commits exactly one history entry. Returning to start (moved === false)
    // or a failed peek commits nothing, so no empty Undo entry is created.
    let shouldCommit = Boolean(drag?.moved)
    let entry: AssetHistoryEntry | undefined = drag?.pendingEntry
    if (shouldCommit && !entry && drag?.historyReady) {
      try {
        entry = await drag.historyReady.catch(() => undefined)
      } catch {
        entry = undefined
      }
    }
    if (shouldCommit && entry) {
      // Final-artwork check: if the gated previews were all no-ops the live
      // bytes still equal the pre-drag snapshot — drop the entry instead of
      // recording an empty Undo step.
      try {
        const target = vm.getTarget(drag!.targetName) ?? selectedTarget
        const costume = target?.costumes[drag!.costumeIndex]
        const key = costume?.md5ext ?? costume?.assetId
        const liveBytes = key ? await vm.loadAsset(key, costume!.dataFormat ?? '') : undefined
        const preBytes = entry.bytes as Uint8Array | undefined
        if (liveBytes && preBytes && liveBytes.length === preBytes.length) {
          let same = true
          for (let i = 0; i < liveBytes.length; i += 1) {
            if (liveBytes[i] !== preBytes[i]) {
              same = false
              break
            }
          }
          if (same) shouldCommit = false
        }
      } catch {
        // Compare best-effort only; commit on doubt (rare path).
      }
    } else if (!entry) {
      shouldCommit = false
    }
    if (shouldCommit && entry) commitPaintHistory(entry)
    if (shouldCommit && drag) {
      try {
        const _live = selectedTarget ? vectorWriteTargetById(drag.targetId, selectedTarget.name) ?? selectedTarget : undefined
        const _idx = drag.costumeIndex
        const _cost = _live?.costumes[_idx]
        const _key = _cost?.md5ext ?? _cost?.assetId
        void (async () => {
          try {
            if (!_live || !_key) return
            const _bytes = await vm.loadAsset(_key, _cost?.dataFormat ?? '')
            if (_bytes && selectedTarget && stableTargetId(selectedTarget) === drag.targetId && (selectedTarget.currentCostume ?? 0) === _idx) {
              rememberCommittedReshapeSelection(drag.targetId, _idx, new Uint8Array(_bytes as Uint8Array))
            }
          } catch {}
        })()
      } catch {
        // Best-effort only.
      }
    }
    if (drag) clearVectorGestureIdentity(drag.gestureId)
    vectorResizeDrag = undefined
    if (!shouldCommit) {
      status = 'Vector resize: no change'
    } else {
      status = wasMulti ? 'Vector objects resized' : 'Vector object resized'
    }
  }

  // Rotation-handle drag for the vector selection (single object or shared
  // multi-selection bounds). The center is the shared selection center in
  // document units; the gesture resolves in client pixels (zoom-invariant
  // under the uniform stage scale) and the matrix applies in document units
  // around `centerDoc` via `rotateVectorElementsAroundCenter`. Every preview
  // re-applies the absolute delta from the immutable `sourceReady` snapshot,
  // never incrementally, so Shift toggling recomputes cleanly. History is
  // peeked once into `pendingEntry` and committed only on pointerup when the
  // final state actually changed; no-op drags (including rotate-and-return)
  // leave the stack untouched and a committed drag writes exactly one entry.
  // Esc restores the snapshot via `restoreVectorRotateSource` without history.
  function beginVectorRotateForSelection(
    selection: number[],
    centerDoc: { x: number; y: number },
    event: PointerEvent,
    multi: boolean,
  ) {
    if (!selectedTarget) return
    if (vectorRotateDrag || vectorResizeDrag || vectorDrag) return
    event.preventDefault()
    event.stopPropagation()
    const element = event.currentTarget as HTMLElement
    const host = element.parentElement
    const rect = host?.getBoundingClientRect()
    if (!rect || !(rect.width > 0) || !(rect.height > 0)) return
    try {
      element.setPointerCapture(event.pointerId)
    } catch {
      // Pointer capture is best-effort; the drag still tracks by pointer id.
    }
    const target = selectedTarget
    const costumeIndex = target.currentCostume ?? 0
    // Client-space center from the document center through the host rect, so
    // later moves resolve angles purely in client pixels (zoom-invariant).
    const dims = host?.dataset.vectorStageSurface === 'true' ? { width: 480, height: 360 } : vectorPreviewDimensions()
    const historyReady = peekCostumeHistory(target, costumeIndex).catch(() => undefined)
    vectorRotateDrag = {
      pointerId: event.pointerId,
      startClientX: event.clientX,
      startClientY: event.clientY,
      centerClientX: rect.left + (centerDoc.x / dims.width) * rect.width,
      centerClientY: rect.top + (centerDoc.y / dims.height) * rect.height,
      centerDoc: { ...centerDoc },
      selection: [...selection],
      multi,
      targetName: target.name,
      targetId: stableTargetId(target),
      gestureId: beginVectorWriteGesture(),
      structureEpoch: getTargetVectorEpoch(stableTargetId(target)),
      committing: false,
      costumeIndex,
      sourceReady: currentSvgDocument(target, costumeIndex).then((loaded) => loaded
        ? { targetName: target.name, costumeIndex, svgText: new XMLSerializer().serializeToString(loaded.doc.documentElement) }
        : undefined),
      historyReady,
      pendingEntry: undefined,
      applying: false,
      appliedDegrees: 0,
      shiftKey: event.shiftKey === true,
    }
    captureVectorGestureIdentity(stableTargetId(target), costumeIndex, vectorRotateDrag.gestureId)
    void historyReady.then((entry) => {
      if (vectorRotateDrag && vectorRotateDrag.pointerId === event.pointerId) vectorRotateDrag.pendingEntry = entry
    })
    status = 'Rotating vector selection'
  }

  function vectorRotateCenterForSingle(objectIndex: number): { x: number; y: number } | undefined {
    const object = vectorObjects.find((item) => item.index === objectIndex)
    if (!object) return undefined
    const left = object.boundsX ?? object.x ?? 0
    const top = object.boundsY ?? object.y ?? 0
    const width = object.boundsWidth ?? object.width ?? 0
    const height = object.boundsHeight ?? object.height ?? 0
    if (!Number.isFinite(left) || !Number.isFinite(top) || !Number.isFinite(width) || !Number.isFinite(height)) return undefined
    if (!(width > 0) && !(height > 0)) return undefined
    return { x: left + width / 2, y: top + height / 2 }
  }

  function beginVectorObjectRotate(object: VectorObjectInfo, event: PointerEvent) {
    const multiSelection = normalizedVectorSelection(vectorObjects.length).filter((index) => vectorObjects.some((item) => item.index === index))
    const isMulti = multiSelection.length > 1 && multiSelection.includes(object.index)
    if (isMulti) {
      beginVectorMultiRotate(event)
      return
    }
    selectVectorObject(object.index, false)
    const center = vectorRotateCenterForSingle(object.index)
    if (!center) return
    beginVectorRotateForSelection([object.index], center, event, false)
  }

  function beginVectorMultiRotate(event: PointerEvent) {
    const multiSelection = normalizedVectorSelection(vectorObjects.length).filter((index) => vectorObjects.some((item) => item.index === index))
    if (multiSelection.length < 2) return
    const bounds = computeVectorMultiSelectionBounds(multiSelection, vectorObjects)
    if (!bounds || !(bounds.width > 0 || bounds.height > 0)) return
    beginVectorRotateForSelection(multiSelection, { x: bounds.x + bounds.width / 2, y: bounds.y + bounds.height / 2 }, event, true)
  }

  function dragVectorObjectRotate(event: PointerEvent) {
    if (!vectorRotateDrag || vectorRotateDrag.pointerId !== event.pointerId) return
    vectorRotateDrag = {
      ...vectorRotateDrag,
      shiftKey: event.shiftKey === true,
    }
    void applyLiveVectorRotate(event.clientX, event.clientY, event.shiftKey === true)
  }

  async function applyLiveVectorRotate(clientX: number, clientY: number, shiftKey = false) {
    if (!vectorRotateDrag) return
    if (vectorRotateDrag.applying) {
      vectorRotateDrag = { ...vectorRotateDrag, pendingClientX: clientX, pendingClientY: clientY, pendingShiftKey: shiftKey }
      return
    }
    const drag = { ...vectorRotateDrag, applying: true, shiftKey }
    vectorRotateDrag = drag
    const gesture = resolveRotationGesture(
      { x: drag.centerClientX, y: drag.centerClientY },
      { x: drag.startClientX, y: drag.startClientY },
      { x: clientX, y: clientY },
      { shiftKey },
    )
    if (!gesture.valid || gesture.noop || isRotationNoop(gesture.appliedDeltaDegrees)) {
      // Snapped-to-zero / center-press / rotate-back-to-start: restore the
      // immutable snapshot when a previous move had previewed, otherwise
      // leave artwork/history untouched. The deferred `pendingEntry` is
      // kept (not committed, not discarded) so a later re-rotate in the
      // same drag still resolves to the same pre-drag history entry and a
      // return-to-start never leaves an empty Undo entry.
      if (drag.appliedDegrees !== 0) {
        await restoreVectorRotateSource(drag, true)
        if (!vectorRotateDrag || vectorRotateDrag.pointerId !== drag.pointerId) return
        vectorRotateDrag = {
          ...vectorRotateDrag,
          applying: false,
          appliedDegrees: 0,
          pendingClientX: undefined,
          pendingClientY: undefined,
          pendingShiftKey: undefined,
        }
      } else {
        if (!vectorRotateDrag || vectorRotateDrag.pointerId !== drag.pointerId) return
        vectorRotateDrag = {
          ...vectorRotateDrag,
          applying: false,
          pendingClientX: undefined,
          pendingClientY: undefined,
          pendingShiftKey: undefined,
        }
      }
      return
    }
    const target = vectorWriteTargetById(drag.targetId, drag.targetName) ?? selectedTarget
    // Deferred history: peek once per drag, commit only on pointerup when the
    // final state actually changed (see `endVectorObjectRotate`). Peeking is
    // side-effect free, so a concurrent successful edit keeps its own entry
    // and redo is never cleared by a no-op path.
    let pendingEntry = drag.pendingEntry
    if (!pendingEntry && target) {
      await waitForVectorRotateCancel()
      if (!vectorRotateDrag || vectorRotateDrag.pointerId !== drag.pointerId) return
      pendingEntry = await peekCostumeHistory(target, drag.costumeIndex)
    }
    const applied = await rotateVectorSelectionFromSource(drag.sourceReady, drag.selection, drag.centerDoc, gesture.appliedDeltaDegrees, drag)
    if (!vectorRotateDrag || vectorRotateDrag.pointerId !== drag.pointerId) return
    if (applied) {
      status = drag.shiftKey || shiftKey
        ? `Rotating vector selection (${Math.round(gesture.appliedDeltaDegrees)}°)`
        : 'Rotating vector selection'
      vectorRotateDrag = {
        ...vectorRotateDrag,
        pendingEntry,
        applying: false,
        appliedDegrees: gesture.appliedDeltaDegrees,
        pendingClientX: undefined,
        pendingClientY: undefined,
        pendingShiftKey: undefined,
      }
    } else {
      vectorRotateDrag = {
        ...vectorRotateDrag,
        pendingEntry,
        applying: false,
        pendingClientX: undefined,
        pendingClientY: undefined,
        pendingShiftKey: undefined,
      }
    }
    const pendingClientX = vectorRotateDrag?.pendingClientX
    const pendingClientY = vectorRotateDrag?.pendingClientY
    const pendingShiftKey = vectorRotateDrag?.pendingShiftKey ?? shiftKey
    if (pendingClientX !== undefined && pendingClientY !== undefined && (pendingClientX !== clientX || pendingClientY !== clientY)) {
      void applyLiveVectorRotate(pendingClientX, pendingClientY, pendingShiftKey)
    }
  }

  async function rotateVectorSelectionFromSource(
    sourceReady: Promise<{ targetName: string; costumeIndex: number; svgText: string } | undefined>,
    selection: number[],
    centerDoc: { x: number; y: number },
    degrees: number,
    writeGesture?: { gestureId: VectorWriteGesture; targetId: string; targetName: string; costumeIndex: number; pointerId: number; structureEpoch?: number },
  ) {
    if (!selectedTarget || isRotationNoop(degrees)) return false
    if (!Number.isFinite(centerDoc.x) || !Number.isFinite(centerDoc.y)) return false
    const rotateSrcOwner = selectedTarget
    const rotateSrcTargetId = stableTargetId(rotateSrcOwner)
    const rotateSrcCostume = rotateSrcOwner.currentCostume ?? 0
    const rotateSrcScope = captureDiscreteSaveScope(rotateSrcTargetId, rotateSrcCostume)
    const rotateSrcAlive = () => isDiscreteSaveScopeCurrent(rotateSrcScope, discreteSaveLiveOf(rotateSrcScope))
    if (writeGesture) {
      if (!vectorRotateDrag || vectorRotateDrag.pointerId !== writeGesture.pointerId) return false
      if (writeGesture.structureEpoch !== undefined && writeGesture.structureEpoch !== getTargetVectorEpoch(writeGesture.targetId)) return false
    }
    const source = await sourceReady
    if (!source) return false
    if (!writeGesture && !rotateSrcAlive()) return false
    if (writeGesture) {
      if (!vectorRotateDrag || vectorRotateDrag.pointerId !== writeGesture.pointerId) return false
      if (writeGesture.structureEpoch !== undefined && writeGesture.structureEpoch !== getTargetVectorEpoch(writeGesture.targetId)) return false
      // ID-scoped (same-name safe, rename tolerant).
      const target = vectorWriteTargetById(writeGesture.targetId, source.targetName)
      if (!target || stableTargetId(target) !== writeGesture.targetId) return false
      if (!selectedTarget || stableTargetId(selectedTarget) !== writeGesture.targetId) return false
      if ((selectedTarget.currentCostume ?? 0) !== source.costumeIndex) return false
    } else if (source.targetName !== selectedTarget.name) return false
    const doc = new DOMParser().parseFromString(source.svgText, 'image/svg+xml')
    const svg = doc.documentElement
    if (svg.nodeName.toLowerCase() !== 'svg') return false
    const units = editableVectorUnits(svg)
    const elements = [...new Set(selection)].map((index) => units[index]).filter((element): element is Element => Boolean(element))
    if (elements.length === 0) return false
    if (!rotateVectorElementsAroundCenter(elements, degrees, centerDoc)) return false
    if (writeGesture) {
      if (!vectorRotateDrag || vectorRotateDrag.pointerId !== writeGesture.pointerId) return false
      const target = vectorWriteTargetById(writeGesture.targetId, source.targetName)
      if (!target) return false
      const preview = await updateVectorPreviewCostumeCAS(target, source.costumeIndex, new XMLSerializer().serializeToString(doc.documentElement), writeGesture.gestureId, writeGesture.structureEpoch)
      if (!preview.applied) {
        if (preview.conflict) await refreshVectorPreviewFromLive(writeGesture.targetId, target)
        return false
      }
      const nextSvg = preview.svgText
      vectorObjects = await paperVectorObjectList(nextSvg)
      selectedVectorObjectIndices = [...new Set(selection)].filter((index) => vectorObjects.some((object) => object.index === index))
      selectedVectorObjectIndex = selectedVectorObjectIndices.includes(selectedVectorObjectIndex)
        ? selectedVectorObjectIndex
        : (selectedVectorObjectIndices.at(-1) ?? -1)
      await refreshCostumePreview(vectorWriteTargetById(writeGesture.targetId, source.targetName) ?? selectedTarget)
      return true
    }
    const rotateDiscreteCommit = !writeGesture
      ? await updateVectorCostumeFromEditor(rotateSrcOwner, source.costumeIndex, new XMLSerializer().serializeToString(doc.documentElement), { quiet: true, isAlive: rotateSrcAlive })
      : undefined
    if (!writeGesture) {
      const dc = rotateDiscreteCommit!
      if (dc.kind !== 'applied') {
        if (rotateSrcAlive() || (dc.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(rotateSrcScope, discreteSaveLiveOf(rotateSrcScope)))) {
          await refreshVectorPreviewFromLive(rotateSrcTargetId, rotateSrcOwner)
          reportVectorExternalConflict('Rotate')
        }
        return false
      }
      if (!rotateSrcAlive()) return false
    }
    const nextSvg = (rotateDiscreteCommit as { svgText: string }).svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    selectedVectorObjectIndices = [...new Set(selection)].filter((index) => vectorObjects.some((object) => object.index === index))
    selectedVectorObjectIndex = selectedVectorObjectIndices.includes(selectedVectorObjectIndex)
      ? selectedVectorObjectIndex
      : (selectedVectorObjectIndices.at(-1) ?? -1)
    await refreshCostumePreview(vectorWriteTargetById(rotateSrcTargetId, rotateSrcOwner.name) ?? selectedTarget)
    if (!rotateSrcAlive()) return false
    return true
  }

  async function restoreVectorRotateSource(
    drag: { sourceReady: Promise<{ targetName: string; costumeIndex: number; svgText: string } | undefined>; selection: number[]; targetName: string; targetId: string; gestureId: VectorWriteGesture; historyReady?: Promise<AssetHistoryEntry | undefined>; pendingEntry?: AssetHistoryEntry },
    keepSelection = false,
  ) {
    const source = await drag.sourceReady
    if (!source) {
      clearVectorGestureIdentity(drag.gestureId)
      return false
    }
    // Barrier write on the same per-slot FIFO: final write of this gesture.
    const target = vectorWriteTargetById(drag.targetId, source.targetName)
    if (!target || stableTargetId(target) !== drag.targetId) {
      clearVectorGestureIdentity(drag.gestureId)
      return false
    }
    const outcome = await restoreVectorSnapshotExact(target, source.costumeIndex, source.svgText, drag)
    if (outcome.conflict) {
      // External same-slot write wins: drop preview residue by reloading
      // from live, history untouched, conflict surfaced (safe rejection).
      await refreshVectorPreviewFromLive(drag.targetId, target)
      reportVectorExternalConflict('Rotate')
      clearVectorGestureIdentity(drag.gestureId)
      return true
    }
    vectorObjects = await paperVectorObjectList(source.svgText)
    if (keepSelection) {
      selectedVectorObjectIndices = [...new Set(drag.selection)].filter((index) => vectorObjects.some((object) => object.index === index))
    }
    await refreshCostumePreview(vectorWriteTargetById(drag.targetId, source.targetName) ?? selectedTarget)
    status = isVectorGestureConflicted(drag.gestureId) ? (() => { reportVectorExternalConflict('Rotate'); return status })() : 'Vector rotate: no change'
    clearVectorGestureIdentity(drag.gestureId)
    return true
  }

  // Selection-switch variant of the rotate cancel: old slot only, no editor
  // globals (mirrors the reshape switch variants).
  async function restoreVectorRotateSourceForSelectionSwitch(
    drag: { sourceReady: Promise<{ targetName: string; costumeIndex: number; svgText: string } | undefined>; targetName: string; targetId: string; gestureId: VectorWriteGesture; historyReady?: Promise<AssetHistoryEntry | undefined>; pendingEntry?: AssetHistoryEntry },
  ) {
    const source = await drag.sourceReady
    if (!source) {
      clearVectorGestureIdentity(drag.gestureId)
      return false
    }
    const target = vectorWriteTargetById(drag.targetId, source.targetName)
    if (!target || stableTargetId(target) !== drag.targetId) {
      clearVectorGestureIdentity(drag.gestureId)
      return false
    }
    const costume = target.costumes[source.costumeIndex]
    if (!costume) {
      clearVectorGestureIdentity(drag.gestureId)
      return false
    }
    // Old slot only, never editor globals: on external conflict the live
    // external bytes are kept as-is (no UI touch; the editor shows the new
    // selection), history untouched.
    await restoreVectorSnapshotExact(target, source.costumeIndex, source.svgText, drag)
    clearVectorGestureIdentity(drag.gestureId)
    return true
  }

  // Rotate cancel (Escape / deselect / target-costume switch / pointercancel /
  // lostpointercapture): retires the gesture synchronously so late previews
  // skip, then enqueues the barrier restore as the final write of the gesture.
  // Refuses while a pointerup commit owns the gesture. Bitmap / point / leaf
  // parity: a genuine capture loss or touch interruption (pointercancel)
  // restores the exact pre-drag snapshot + metadata with history/redo
  // untouched; the trailing implicit `lostpointercapture` auto-loss after a
  // normal pointerup arrives with `committing === true` and is refused so the
  // release still commits exactly once.
  function cancelVectorRotateDrag(event?: PointerEvent): boolean {
    if (!vectorRotateDrag) return false
    if (event && event.pointerId !== undefined && vectorRotateDrag.pointerId !== event.pointerId) return false
    if (vectorRotateDrag.committing) return false
    const drag = vectorRotateDrag
    vectorRotateDrag = undefined
    cancelVectorWriteGesture(drag.gestureId)
    const restoring = restoreVectorRotateSource(drag).finally(() => {
      if (vectorRotateCancelPromise === restoring) vectorRotateCancelPromise = undefined
    })
    vectorRotateCancelPromise = restoring
    void restoring
    return true
  }

  async function endVectorObjectRotate(event: PointerEvent) {
    if (!vectorRotateDrag || vectorRotateDrag.pointerId !== event.pointerId) return
    // pointercancel / lostpointercapture is a cancel, not a commit: restore
    // the exact start snapshot + metadata without touching history/redo
    // (bitmap / point / leaf parity; touch interruption routes here). The
    // overlay routes the post-pointerup implicit auto-loss here as well; the
    // committing claim below makes that trailing loss a no-op so the release
    // commits exactly once.
    if (event.type === 'pointercancel' || event.type === 'lostpointercapture') {
      cancelVectorRotateDrag(event)
      return
    }
    // Claim synchronously: the trailing implicit `lostpointercapture`
    // auto-loss after this pointerup must not cancel the just-released drag.
    vectorRotateDrag.committing = true
    const myRotateTargetId = vectorRotateDrag.targetId
    const myRotatePointerId = vectorRotateDrag.pointerId
    await applyLiveVectorRotate(event.clientX, event.clientY, event.shiftKey === true)
    // Coalesced pointermoves are scheduled via `void applyLiveVectorRotate`
    // from inside the in-flight iteration. The `await` above can resolve
    // while a newer move (e.g. the out-and-back return) is still queued, so
    // wait for quiescence and re-apply the final pointer position once. The
    // re-apply is idempotent (absolute delta from the immutable snapshot), so
    // a rotate-and-return reliably settles to `appliedDegrees === 0` instead
    // of stranding the earlier non-zero preview behind.
    for (let attempt = 0; attempt < 200; attempt += 1) {
      const settled = vectorRotateDrag
      if (!settled || (!settled.applying && settled.pendingClientX === undefined)) break
      await new Promise((resolve) => setTimeout(resolve, 10))
    }
    if (vectorRotateDrag && vectorRotateDrag.pointerId === event.pointerId) {
      await applyLiveVectorRotate(event.clientX, event.clientY, event.shiftKey === true)
    }
    // Captured exact slot completion before retiring the identity (move-end
    // parity): a >2s gated write outlives the flag loop above, and retiring
    // early strands `known` behind `live`.
    await settleVectorGestureSlotCompletion(
      () => {
        const settled = vectorRotateDrag
        if (!settled || settled.pointerId !== myRotatePointerId) return 'gone'
        return !settled.applying && settled.pendingClientX === undefined ? 'settled' : 'busy'
      },
      () => drainTargetVectorWrites(myRotateTargetId),
    )
    const drag = vectorRotateDrag
    const wasMulti = drag?.multi ?? false
    // The final artwork decides history: only a non-noop final delta commits
    // the deferred peeked entry (exactly one). Rotating back to the start
    // angle, snapped-to-zero, or center-press discards the peek and leaves
    // undo/redo untouched instead of leaving an empty Undo entry.
    const finalDegrees = drag?.appliedDegrees ?? 0
    const changed = drag !== undefined && !isRotationNoop(finalDegrees) && finalDegrees !== 0
    const pendingEntry = drag?.pendingEntry
    vectorRotateDrag = undefined
    if (drag && isVectorGestureConflicted(drag.gestureId)) {
      await refreshVectorPreviewFromLive(drag.targetId, selectedTarget ?? undefined)
      reportVectorExternalConflict('Rotate')
      clearVectorGestureIdentity(drag.gestureId)
      return
    }
    if (!changed) {
      status = 'Vector rotate: no change'
      if (drag) clearVectorGestureIdentity(drag.gestureId)
      return
    }
    if (pendingEntry) commitPaintHistory(pendingEntry)
    if (changed && drag) {
      try {
        const _live = selectedTarget ? vectorWriteTargetById(drag.targetId, selectedTarget.name) ?? selectedTarget : undefined
        const _idx = drag.costumeIndex
        const _cost = _live?.costumes[_idx]
        const _key = _cost?.md5ext ?? _cost?.assetId
        void (async () => {
          try {
            if (!_live || !_key) return
            const _bytes = await vm.loadAsset(_key, _cost?.dataFormat ?? '')
            if (_bytes && selectedTarget && stableTargetId(selectedTarget) === drag.targetId && (selectedTarget.currentCostume ?? 0) === _idx) {
              rememberCommittedReshapeSelection(drag.targetId, _idx, new Uint8Array(_bytes as Uint8Array))
            }
          } catch {}
        })()
      } catch {
        // Best-effort only.
      }
    }
    status = wasMulti ? 'Vector objects rotated' : 'Vector object rotated'
    if (drag) clearVectorGestureIdentity(drag.gestureId)
  }

  function beginVectorPathPointDrag(object: VectorObjectInfo, pointIndex: number, event: PointerEvent) {
    if (!selectedTarget || isReshapeTextEditing()) return
    if (vectorRotateDrag || vectorResizeDrag || vectorDrag) return
    if (vectorPathPointDrag || vectorLeafTranslateDrag) return
    const point = object.points?.find((item) => item.index === pointIndex)
    if (!point) return
    event.preventDefault()
    event.stopPropagation()
    // Object switch first: it drops a foreign point selection, then the
    // anchor logic below rebuilds the selection for this unit.
    const sameObject = object.index === selectedVectorObjectIndex
    const priorActionSelection = sameObject ? reshapeLiveActionIndices() : []
    selectVectorObject(object.index, false)
    const append = event.shiftKey === true || event.metaKey === true || event.ctrlKey === true
    if (point.kind === 'control') {
      // Control handles stay single-point: bulk translation is anchor-only
      // (foreign handles are never touched), so a control press drags just
      // that handle and leaves the anchor selection alone.
    } else if (append) {
      toggleVectorReshapePoint(pointIndex, true)
    } else if (!vectorReshapePointIndices.includes(pointIndex) && !reshapeLiveActionIndices().includes(pointIndex)) {
      setReshapeSelection([pointIndex])
    }
    // Plain press on an already-selected anchor keeps the set so the drag
    // moves every selected anchor together; a press released without a move
    // collapses back to the single anchor (legacy click-to-isolate).
    // Action-only parity: latent handle-only anchors (mask 2/4/6) still count
    // as `segment.selected` in the reference point tool, so the bulk set is
    // the live any-bit selection, never the point-bit projection alone.
    const liveAction = reshapeLiveActionIndices()
    const bulkAnchors =
      point.kind === 'control'
        ? []
        : (liveAction.length > 0 ? [...liveAction] : [pointIndex])
    const startPositions = new Map<number, { x: number; y: number }>()
    if (point.kind !== 'control') {
      for (const index of bulkAnchors) {
        const anchor = object.points?.find((item) => item.index === index && item.kind !== 'control')
        if (anchor) startPositions.set(index, { x: anchor.x, y: anchor.y })
      }
      if (!startPositions.has(pointIndex)) {
        const anchor = object.points?.find((item) => item.index === pointIndex && item.kind !== 'control')
        if (anchor) startPositions.set(pointIndex, { x: anchor.x, y: anchor.y })
      }
    }
    const element = event.currentTarget as HTMLElement
    const host = element.parentElement
    const rect = host?.getBoundingClientRect()
    const dims = host?.dataset.vectorStageSurface === 'true' ? { width: 480, height: 360 } : vectorPreviewDimensions()
    const scale = rect ? Math.min(rect.width / dims.width, rect.height / dims.height) : 1
    try {
      element.setPointerCapture(event.pointerId)
    } catch {
      // Pointer capture is best-effort; the drag still tracks by pointer id.
    }
    const target = selectedTarget
    const costumeIndex = target.currentCostume ?? 0
    // Snapshot + deferred single entry: the immutable pre-drag SVG is the
    // source for every preview frame, and the peeked entry is committed
    // once at drag end only when the artwork actually moved. Click-selects
    // and no-op drags leave undo/redo untouched instead of recording an
    // empty entry.
    const sourceReady = currentSvgDocument(target, costumeIndex).then((loaded) => loaded
      ? { targetName: target.name, costumeIndex, svgText: new XMLSerializer().serializeToString(loaded.doc.documentElement) }
      : undefined)
    const historyReady = peekCostumeHistory(target, costumeIndex).catch(() => undefined)
    const liveActionForCollapse = reshapeLiveActionIndices()
    const collapseTo =
      point.kind === 'control' || append || !priorActionSelection.includes(pointIndex) || liveActionForCollapse.length < 2
        ? undefined
        : pointIndex
    vectorPathPointDrag = {
      objectIndex: object.index,
      pointIndex,
      pointIndices: point.kind === 'control' ? [pointIndex] : [...startPositions.keys()],
      startPositions,
      pointerId: event.pointerId,
      startClientX: event.clientX,
      startClientY: event.clientY,
      startX: point.x,
      startY: point.y,
      scale,
      applying: false,
      historyReady,
      pendingEntry: undefined,
      moved: false,
      collapseTo,
      targetName: target.name,
      targetId: stableTargetId(target),
      gestureId: beginVectorWriteGesture(),
      structureEpoch: getTargetVectorEpoch(stableTargetId(target)),
      committing: false,
      costumeIndex,
      sourceReady,
      isControl: point.kind === 'control',
      reshapeSelection: [...vectorReshapePointIndices],
      reshapeMasks: { ...vectorReshapeHandleMasks },
      reshapeLeaves: [...vectorReshapeLeafIndices],
    }
    captureVectorGestureIdentity(stableTargetId(target), costumeIndex, vectorPathPointDrag.gestureId)
    void historyReady.then((entry) => {
      if (vectorPathPointDrag && vectorPathPointDrag.pointerId === event.pointerId) vectorPathPointDrag.pendingEntry = entry
    })
  }

  function dragVectorPathPoint(event: PointerEvent) {
    if (!vectorPathPointDrag || vectorPathPointDrag.pointerId !== event.pointerId) return
    void applyLiveVectorPathPointDrag(event.clientX, event.clientY, event.shiftKey, event.altKey)
  }

  async function applyLiveVectorPathPointDrag(clientX: number, clientY: number, shiftKey = false, altKey = false) {
    if (!vectorPathPointDrag) return
    if (vectorPathPointDrag.applying) {
      vectorPathPointDrag = { ...vectorPathPointDrag, pendingClientX: clientX, pendingClientY: clientY, pendingShiftKey: shiftKey, pendingAltKey: altKey }
      return
    }
    const drag = { ...vectorPathPointDrag, applying: true }
    vectorPathPointDrag = drag
    const delta = pathPointDragDelta((clientX - drag.startClientX) / (drag.scale || 1), (clientY - drag.startClientY) / (drag.scale || 1), shiftKey)
    if (delta.x === 0 && delta.y === 0) {
      // Snapped-to-zero / return-to-start: restore the immutable snapshot
      // when a previous frame had previewed, otherwise leave artwork/history
      // untouched. The deferred `pendingEntry` is kept (not committed, not
      // discarded) so a later move in the same drag still resolves to the
      // same pre-drag history entry and a return-to-start never leaves an
      // empty Undo entry.
      if (drag.moved) {
        await restoreVectorPathPointSource(drag, true)
        if (!vectorPathPointDrag || vectorPathPointDrag.pointerId !== drag.pointerId) return
        vectorPathPointDrag = {
          ...vectorPathPointDrag,
          applying: false,
          moved: false,
          pendingClientX: undefined,
          pendingClientY: undefined,
          pendingShiftKey: undefined,
          pendingAltKey: undefined,
        }
      } else {
        if (!vectorPathPointDrag || vectorPathPointDrag.pointerId !== drag.pointerId) return
        vectorPathPointDrag = {
          ...vectorPathPointDrag,
          applying: false,
          pendingClientX: undefined,
          pendingClientY: undefined,
          pendingShiftKey: undefined,
          pendingAltKey: undefined,
        }
      }
      return
    }
    // Wait for the deferred peek so the later commit restores pre-drag
    // bytes exactly. Live frames never write history themselves.
    await waitForVectorRotateCancel()
    if (!vectorPathPointDrag || vectorPathPointDrag.pointerId !== drag.pointerId) return
    const entry = await drag.historyReady
    if (!vectorPathPointDrag || vectorPathPointDrag.pointerId !== drag.pointerId) return
    if (vectorPathPointDrag.pendingEntry === undefined) vectorPathPointDrag.pendingEntry = entry
    const applied = await previewVectorPathPointFromSource(drag, delta.x, delta.y, altKey)
    if (!vectorPathPointDrag || vectorPathPointDrag.pointerId !== drag.pointerId) return
    if (applied) {
      vectorPathPointDrag = {
        ...vectorPathPointDrag,
        applying: false,
        moved: true,
        pendingClientX: undefined,
        pendingClientY: undefined,
        pendingShiftKey: undefined,
        pendingAltKey: undefined,
      }
    } else {
      vectorPathPointDrag = {
        ...vectorPathPointDrag,
        applying: false,
        pendingClientX: undefined,
        pendingClientY: undefined,
        pendingShiftKey: undefined,
        pendingAltKey: undefined,
      }
    }
    const pendingClientX = vectorPathPointDrag?.pendingClientX
    const pendingClientY = vectorPathPointDrag?.pendingClientY
    const pendingShiftKey = vectorPathPointDrag?.pendingShiftKey
    const pendingAltKey = vectorPathPointDrag?.pendingAltKey
    if (pendingClientX !== undefined && pendingClientY !== undefined && (pendingClientX !== clientX || pendingClientY !== clientY)) {
      void applyLiveVectorPathPointDrag(pendingClientX, pendingClientY, pendingShiftKey, pendingAltKey)
    }
  }

  // Absolute preview from the immutable pre-drag snapshot: parse the source
  // SVG, move the dragged anchor(s)/control to start + delta, and write the
  // result without history. Only the dragged unit is touched, so sibling
  // objects and wrapper transforms survive every frame. Selection is
  // re-applied so the set never collapses mid-drag.
  async function previewVectorPathPointFromSource(
    drag: { sourceReady: Promise<{ targetName: string; costumeIndex: number; svgText: string } | undefined>; objectIndex: number; pointIndex: number; startPositions: Map<number, { x: number; y: number }>; startX: number; startY: number; isControl: boolean; reshapeSelection: number[]; reshapeMasks?: ReshapeHandleMasks; reshapeLeaves: number[]; pointerId: number; targetName: string; targetId: string; gestureId: VectorWriteGesture; structureEpoch?: number },
    dx: number,
    dy: number,
    splitHandles = false,
  ) {
    if (!selectedTarget) return false
    // The drag may have been cancelled by a costume/sprite switch while this
    // frame was in flight: stop before touching any asset so the old preview
    // never lands on the newly selected artwork.
    if (!vectorPathPointDrag || vectorPathPointDrag.pointerId !== drag.pointerId) return false
    if (drag.structureEpoch !== undefined && drag.structureEpoch !== getTargetVectorEpoch(drag.targetId)) return false
    const source = await drag.sourceReady
    if (!source) return false
    if (!vectorPathPointDrag || vectorPathPointDrag.pointerId !== drag.pointerId) return false
    if (drag.structureEpoch !== undefined && drag.structureEpoch !== getTargetVectorEpoch(drag.targetId)) return false
    // ID-scoped (same-name safe, rename tolerant): the slot is the stable id,
    // so a rename keeps the drag alive while a switch to another target —
    // even one with the same display name — refuses here.
    const target = vectorWriteTargetById(drag.targetId, source.targetName)
    if (!target || stableTargetId(target) !== drag.targetId) return false
    if (stableTargetId(selectedTarget) !== drag.targetId) return false
    // Same-target costume switch: the live drag was cancelled and its
    // snapshot belongs to the old costume index — never preview it onto the
    // newly selected costume.
    if ((selectedTarget.currentCostume ?? 0) !== source.costumeIndex) return false
    if (source.targetName !== drag.targetName && stableTargetId(target) !== drag.targetId) return false
    const doc = new DOMParser().parseFromString(source.svgText, 'image/svg+xml')
    const svg = doc.documentElement
    if (svg.nodeName.toLowerCase() !== 'svg') return false
    const units = editableVectorUnits(svg)
    const element = units[drag.objectIndex]
    if (!element || element.tagName.toLowerCase() === 'text') return false
    if (drag.isControl) {
      if (!(await moveVectorEditablePoint(element, drag.pointIndex, drag.startX + dx, drag.startY + dy, splitHandles))) return false
    } else {
      const targets = [...drag.startPositions.entries()].map(([index, start]) => ({ index, x: start.x + dx, y: start.y + dy }))
      if (targets.length === 0) return false
      const result = await moveVectorReshapePoints(element, targets)
      if (!result.moved) return false
    }
    // Re-check immediately before the write (no await between here and the
    // update call): a switch that cleared the drag after the awaits above
    // must not let this frame overwrite the new selection, and the queued
    // switch-cancel restore (tracked on the shared cancel promise) then stays
    // the last writer of the old asset. The per-slot FIFO additionally orders
    // the restore after every preview of this gesture; a preview enqueued
    // after its own cancel is skipped inside the queue.
    if (!vectorPathPointDrag || vectorPathPointDrag.pointerId !== drag.pointerId) return false
    if (drag.structureEpoch !== undefined && drag.structureEpoch !== getTargetVectorEpoch(drag.targetId)) return false
    const preview = await updateVectorPreviewCostumeCAS(target, source.costumeIndex, new XMLSerializer().serializeToString(doc.documentElement), drag.gestureId, drag.structureEpoch)
    if (!preview.applied) {
      // External same-slot write wins: never paint stale preview residue.
      if (preview.conflict) await refreshVectorPreviewFromLive(drag.targetId, target)
      return false
    }
    const nextSvg = preview.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    selectedVectorObjectIndex = drag.objectIndex
    selectedVectorObjectIndices = vectorObjects.some((object) => object.index === drag.objectIndex) ? [drag.objectIndex] : []
    if (drag.reshapeMasks !== undefined) setReshapeSelectionWithMasks(drag.reshapeMasks)
    else setReshapeSelection(drag.reshapeSelection)
    setReshapeLeafSelection(drag.reshapeLeaves ?? [])
    await refreshCostumePreview(vectorWriteTargetById(drag.targetId, source.targetName) ?? selectedTarget)
    return true
  }

  async function restoreVectorPathPointSource(
    drag: { sourceReady: Promise<{ targetName: string; costumeIndex: number; svgText: string } | undefined>; objectIndex: number; reshapeSelection: number[]; reshapeMasks?: ReshapeHandleMasks; reshapeLeaves?: number[]; targetName: string; targetId: string; gestureId: VectorWriteGesture; historyReady?: Promise<AssetHistoryEntry | undefined>; pendingEntry?: AssetHistoryEntry },
    keepSelection = true,
  ) {
    const source = await drag.sourceReady
    if (!source) {
      clearVectorGestureIdentity(drag.gestureId)
      return false
    }
    // Barrier write on the same per-slot FIFO: enqueued after every preview
    // of this gesture, so it lands after all of them and is the final write
    // of the cancelled gesture. Only this asset's own bytes are written —
    // never an unconditional whole snapshot — and newer legitimate edits
    // enqueue after this barrier, so they still win.
    const target = vectorWriteTargetById(drag.targetId, source.targetName)
    if (!target || stableTargetId(target) !== drag.targetId) {
      clearVectorGestureIdentity(drag.gestureId)
      return false
    }
    const outcome = await restoreVectorSnapshotExact(target, source.costumeIndex, source.svgText, drag)
    if (outcome.conflict) {
      await refreshVectorPreviewFromLive(drag.targetId, target)
      reportVectorExternalConflict('Reshape')
      clearVectorGestureIdentity(drag.gestureId)
      return true
    }
    vectorObjects = await paperVectorObjectList(source.svgText)
    if (keepSelection) {
      selectedVectorObjectIndex = drag.objectIndex
      selectedVectorObjectIndices = vectorObjects.some((object) => object.index === drag.objectIndex) ? [drag.objectIndex] : []
      if ((drag as { reshapeMasks?: unknown }).reshapeMasks !== undefined) setReshapeSelectionWithMasks((drag as { reshapeMasks?: ReshapeHandleMasks }).reshapeMasks as ReshapeHandleMasks)
      else setReshapeSelection(drag.reshapeSelection)
      setReshapeLeafSelection(drag.reshapeLeaves ?? [])
    }
    await refreshCostumePreview(vectorWriteTargetById(drag.targetId, source.targetName) ?? selectedTarget)
    if (isVectorGestureConflicted(drag.gestureId)) reportVectorExternalConflict('Reshape')
    else status = 'Vector reshape: no change'
    clearVectorGestureIdentity(drag.gestureId)
    return true
  }

  // Selection-switch variant of the reshape cancel: restores the OLD target's
  // pre-drag snapshot to the OLD costume index only. Unlike the Esc/deselect
  // restore above it never touches the editor globals (`vectorObjects`,
  // object/point selection, preview, `status`) — the editor already shows
  // the newly selected target/costume and must not be overwritten with the
  // old artwork. History/redo are untouched (the pending peeked entry is
  // discarded, never committed). A deleted old target/costume, or a missing
  // snapshot, is a safe no-op returning false. Callers track the returned
  // promise on `vectorRotateCancelPromise` so a concurrent next edit awaits
  // the restored bytes.
  async function restoreVectorPathPointSourceForSelectionSwitch(
    drag: { sourceReady: Promise<{ targetName: string; costumeIndex: number; svgText: string } | undefined>; targetName: string; targetId: string; gestureId: VectorWriteGesture; historyReady?: Promise<AssetHistoryEntry | undefined>; pendingEntry?: AssetHistoryEntry },
  ) {
    const source = await drag.sourceReady
    if (!source) {
      clearVectorGestureIdentity(drag.gestureId)
      return false
    }
    if (source.targetName !== drag.targetName && !drag.targetId) {
      clearVectorGestureIdentity(drag.gestureId)
      return false
    }
    const target = vectorWriteTargetById(drag.targetId, source.targetName)
    if (!target || stableTargetId(target) !== drag.targetId) {
      clearVectorGestureIdentity(drag.gestureId)
      return false
    }
    const costume = target.costumes[source.costumeIndex]
    if (!costume) {
      clearVectorGestureIdentity(drag.gestureId)
      return false
    }
    await restoreVectorSnapshotExact(target, source.costumeIndex, source.svgText, drag)
    clearVectorGestureIdentity(drag.gestureId)
    return true
  }

  function cancelVectorPathPointDrag(event?: PointerEvent) {
    if (!vectorPathPointDrag) return false
    if (event && event.pointerId !== undefined && vectorPathPointDrag.pointerId !== event.pointerId) return false
    // A pointerup-claimed commit owns this gesture: a trailing
    // `lostpointercapture` auto-loss (or an Escape/switch racing the async
    // commit) must not restore away the just-released drag.
    if (vectorPathPointDrag.committing) return false
    // Clear synchronously so live frames/pointer moves stop immediately;
    // the async restore is tracked so an immediate next edit (or Undo/Redo)
    // waits for (rather than races) the restored bytes. History/redo are
    // untouched by the cancel itself.
    const drag = vectorPathPointDrag
    vectorPathPointDrag = undefined
    cancelVectorWriteGesture(drag.gestureId)
    const restoring = restoreVectorPathPointSource(drag, true).finally(() => {
      if (vectorRotateCancelPromise === restoring) vectorRotateCancelPromise = undefined
    })
    vectorRotateCancelPromise = restoring
    void restoring
    return true
  }

  async function endVectorPathPointDrag(event: PointerEvent) {
    if (!vectorPathPointDrag || vectorPathPointDrag.pointerId !== event.pointerId) return
    // pointercancel / lostpointercapture is a cancel, not a commit: restore
    // the start snapshot without touching history/redo. (The overlay routes
    // the post-pointerup implicit auto-loss here as well; the committing
    // claim below makes that trailing loss a no-op so the release commits
    // exactly once.)
    if (event.type === 'pointercancel' || event.type === 'lostpointercapture') {
      cancelVectorPathPointDrag(event)
      return
    }
    // Claim synchronously before the first await: the browser queues the
    // implicit `lostpointercapture` auto-loss immediately after this pointerup
    // task while the commit below still awaits, and without the claim the
    // trailing loss would cancel the just-released drag.
    vectorPathPointDrag.committing = true
    const myPointTargetId = vectorPathPointDrag.targetId
    const myPointPointerId = vectorPathPointDrag.pointerId
    await applyLiveVectorPathPointDrag(event.clientX, event.clientY, event.shiftKey, event.altKey)
    // Coalesced pointermoves are scheduled via `void applyLive...` from
    // inside the in-flight iteration. The `await` above can resolve while a
    // newer move (e.g. the out-and-back return) is still queued, so wait for
    // quiescence and re-apply the final pointer position once. The re-apply
    // is idempotent (absolute delta from the immutable snapshot), so a
    // drag-and-return reliably settles to `moved === false` instead of
    // stranding the earlier non-zero preview behind.
    for (let attempt = 0; attempt < 200; attempt += 1) {
      const settled = vectorPathPointDrag
      if (!settled || (!settled.applying && settled.pendingClientX === undefined)) break
      await new Promise((resolve) => setTimeout(resolve, 10))
    }
    if (vectorPathPointDrag && vectorPathPointDrag.pointerId === event.pointerId) {
      await applyLiveVectorPathPointDrag(event.clientX, event.clientY, event.shiftKey, event.altKey)
    }
    // Captured exact slot completion before retiring the identity (move-end
    // parity): a >2s gated write outlives the flag loop above, and retiring
    // early strands `known` behind `live`.
    await settleVectorGestureSlotCompletion(
      () => {
        const settled = vectorPathPointDrag
        if (!settled || settled.pointerId !== myPointPointerId) return 'gone'
        return !settled.applying && settled.pendingClientX === undefined ? 'settled' : 'busy'
      },
      () => drainTargetVectorWrites(myPointTargetId),
    )
    const drag = vectorPathPointDrag
    vectorPathPointDrag = undefined
    // External conflict wins even on commit (safe rejection): never delete
    // the real external write, no history, surface the conflict.
    if (drag && isVectorGestureConflicted(drag.gestureId)) {
      await refreshVectorPreviewFromLive(drag.targetId, selectedTarget ?? undefined)
      reportVectorExternalConflict('Reshape')
      clearVectorGestureIdentity(drag.gestureId)
      return
    }
    // Exactly one history entry for a real move; clicks, cancels and no-op
    // drags commit nothing so Undo/Redo stay clean. A plain press released
    // without a move on an already-selected anchor collapses to that anchor.
    // The final artwork decides history: only a non-zero final delta commits
    // the deferred peeked entry.
    if (drag?.moved && drag.pendingEntry) commitPaintHistory(drag.pendingEntry)
    if (drag?.moved) {
      try {
        const _live = selectedTarget ? vectorWriteTargetById(drag.targetId, selectedTarget.name) ?? selectedTarget : undefined
        const _idx = drag.costumeIndex
        const _cost = _live?.costumes[_idx]
        const _key = _cost?.md5ext ?? _cost?.assetId
        void (async () => {
          try {
            if (!_live || !_key) return
            const _bytes = await vm.loadAsset(_key, _cost?.dataFormat ?? '')
            if (_bytes && selectedTarget && stableTargetId(selectedTarget) === drag.targetId && (selectedTarget.currentCostume ?? 0) === _idx) {
              rememberCommittedReshapeSelection(drag.targetId, _idx, new Uint8Array(_bytes as Uint8Array))
            }
          } catch {}
        })()
      } catch {
        // Best-effort only.
      }
    }
    if (drag && !drag.moved && drag.collapseTo !== undefined) {
      setReshapeSelection([drag.collapseTo])
      // The collapse narrows points without touching artwork: re-derive the
      // leaf set (fail-closed) so the next Shift+leaf toggles from the
      // collapsed leaf instead of the stale pre-collapse set.
      void syncReshapeLeavesToPoints()
      status = 'Reshape point selected'
      if (drag) clearVectorGestureIdentity(drag.gestureId)
      return
    }
    // A press that selected a new anchor (or a finished move) also leaves
    // the leaf set behind the point set: re-derive it so leaf toggles stay
    // consistent. Moves never shift slots, so this is idempotent for them.
    void syncReshapeLeavesToPoints()
    status = drag?.moved
      ? drag.pointIndices.length > 1
        ? `Vector path points moved (${drag.pointIndices.length})`
        : 'Vector path point moved'
      : 'Vector reshape: no change'
    if (drag) clearVectorGestureIdentity(drag.gestureId)
  }

  // Whole-leaf translate drag (text/image + geometry in mixed groups).
  // Single immutable snapshot, absolute document deltas, one deferred history
  // entry on non-zero final move, Escape/pointercancel restores the snapshot
  // with no history. Stale guards (target/costume/object switch, detached
  // leaves, reindex, singular ancestors, clip) fail closed with no DOM write.
  async function beginVectorLeafTranslateDragAtPoint(
    point: { x: number; y: number },
    event: PointerEvent,
    scale: number,
  ): Promise<boolean> {
    // Capture synchronously before the first await: after an await the
    // PointerEvent's currentTarget is cleared and setPointerCapture would
    // no-op, stranding subsequent moves (anchor drag captures sync for the
    // same reason). Capture is best-effort; tracking still works by id.
    const captureEl = (event.currentTarget as HTMLElement | null) ?? null
    try { captureEl?.setPointerCapture?.(event.pointerId) } catch {}
    const releaseCapture = () => {
      try { captureEl?.releasePointerCapture?.(event.pointerId) } catch {}
    }
    if (!selectedTarget || selectedVectorObjectIndex < 0 || isReshapeTextEditing()) {
      releaseCapture()
      return false
    }
    if (vectorPathPointDrag || vectorLeafTranslateDrag) {
      releaseCapture()
      return false
    }
    if (vectorRotateDrag || vectorResizeDrag || vectorDrag) {
      releaseCapture()
      return false
    }
    const append = event.shiftKey === true || event.metaKey === true || event.ctrlKey === true
    const targetName = selectedTarget.name
    const costumeIndex = selectedTarget.currentCostume ?? 0
    const objectIndex = selectedVectorObjectIndex
    const loaded = await currentSvgDocument(selectedTarget, costumeIndex)
    if (!selectedTarget || selectedTarget.name !== targetName || selectedVectorObjectIndex !== objectIndex || (selectedTarget.currentCostume ?? 0) !== costumeIndex) return true
    if (!loaded) {
      releaseCapture()
      return false
    }
    const element = editableVectorUnits(loaded.svg)[objectIndex]
    if (!element || element.tagName.toLowerCase() !== 'g') {
      releaseCapture()
      return false
    }
    // Geometry-only units stay on the anchor path; translate drag only starts
    // for mixed groups that fail the geometry gate but pass the translate gate.
    if (classifyGroupUnitForLeafReshape(element).ok) {
      releaseCapture()
      return false
    }
    if (!classifyGroupUnitForLeafTranslate(element).ok) {
      releaseCapture()
      return false
    }
    const tolerance = Number.isFinite(scale) && scale > 0 ? vectorSelectToleranceFromSurfaceScale(scale) : resolveVectorHitTolerance()
    let hit: Awaited<ReturnType<typeof paperGroupTranslateLeafHitAtPoint>>
    try {
      hit = await paperGroupTranslateLeafHitAtPoint(element, point, tolerance)
    } catch {
      releaseCapture()
      return false
    }
    if (!selectedTarget || selectedTarget.name !== targetName || selectedVectorObjectIndex !== objectIndex || (selectedTarget.currentCostume ?? 0) !== costumeIndex) return true
    if (hit.kind !== 'hit') {
      // Miss falls through to the anchor-leaf / point-add path in the
      // overlay: release the speculative capture so the fallback gesture
      // starts from a clean pointer state.
      releaseCapture()
      return false
    }
    try {
      const domLeaves = groupTranslateLeafTargetsInOrder(element)
      const leaf = domLeaves?.[hit.leafIndex]
      if (!leaf) {
        releaseCapture()
        return false
      }
      const eligibility = classifyLeafElementForTranslate(leaf)
      if (!eligibility.ok) {
        status = `Reshape leaf: ${eligibility.reason}`
        return true
      }
      if ((eligibility as { kind?: string }).kind === 'use') {
        status = 'Reshape leaf: use in group is not translatable (fail-closed)'
        return true
      }
    } catch {
      releaseCapture()
      return false
    }
    // Selection: plain replaces, Shift toggles (multi-leaf whole moves share
    // one history entry). Deselect (Shift on sole leaf) consumes without drag.
    const current = [...vectorReshapeLeafIndices]
    const nextLeaves = append
      ? current.includes(hit.leafIndex)
        ? current.filter((leafIndex) => leafIndex !== hit.leafIndex)
        : [...current, hit.leafIndex]
      : [hit.leafIndex]
    const clean = normalizeReshapeSelection(nextLeaves)
    if (clean.length === 0) {
      clearReshapeSelection()
      status = 'Reshape leaf deselected'
      return true
    }
    setReshapeLeafSelection(clean)
    setReshapeSelection([])
    status = clean.length > 1 ? `Reshape leaves selected (${clean.length})` : 'Reshape leaf selected'
    // Start the drag from this press so press-move-release moves in one gesture.
    const domLeavesForDrag = groupTranslateLeafTargetsInOrder(element) ?? []
    const leafTags = clean.map((leafIndex) => {
      try {
        return domLeavesForDrag[leafIndex]?.tagName.toLowerCase() ?? ''
      } catch {
        return ''
      }
    })
    event.preventDefault()
    // Pointer was already captured synchronously at entry (see above); the
    // late capture here is a no-op best-effort since currentTarget clears.
    try {
      ;(captureEl as HTMLElement | null)?.setPointerCapture?.(event.pointerId)
    } catch {
      // Best-effort; tracking still works by pointer id.
    }
    const target = selectedTarget
    const sourceReady = currentSvgDocument(target, costumeIndex).then((snapshot) =>
      snapshot ? { targetName: target.name, costumeIndex, svgText: new XMLSerializer().serializeToString(snapshot.doc.documentElement) } : undefined,
    )
    const historyReady = peekCostumeHistory(target, costumeIndex).catch(() => undefined)
    vectorLeafTranslateDrag = {
      objectIndex,
      leafIndices: clean,
      leafTags,
      pointerId: event.pointerId,
      startClientX: event.clientX,
      startClientY: event.clientY,
      scale: Number.isFinite(scale) && scale > 0 ? scale : 1,
      applying: false,
      historyReady,
      pendingEntry: undefined,
      moved: false,
      targetName: target.name,
      targetId: stableTargetId(target),
      gestureId: beginVectorWriteGesture(),
      structureEpoch: getTargetVectorEpoch(stableTargetId(target)),
      costumeIndex,
      sourceReady,
      reshapeSelection: [...vectorReshapePointIndices],
      reshapeLeaves: [...clean],
      committing: false,
    }
    captureVectorGestureIdentity(stableTargetId(target), costumeIndex, vectorLeafTranslateDrag.gestureId)
    void historyReady.then((entry) => {
      if (vectorLeafTranslateDrag && vectorLeafTranslateDrag.pointerId === event.pointerId) vectorLeafTranslateDrag.pendingEntry = entry
    })
    return true
  }

  function dragVectorLeafTranslate(event: PointerEvent) {
    if (!vectorLeafTranslateDrag || vectorLeafTranslateDrag.pointerId !== event.pointerId) return
    void applyLiveVectorLeafTranslateDrag(event.clientX, event.clientY)
  }

  async function applyLiveVectorLeafTranslateDrag(clientX: number, clientY: number) {
    if (!vectorLeafTranslateDrag) return
    if (vectorLeafTranslateDrag.applying) {
      vectorLeafTranslateDrag = { ...vectorLeafTranslateDrag, pendingClientX: clientX, pendingClientY: clientY }
      return
    }
    const drag = { ...vectorLeafTranslateDrag, applying: true }
    vectorLeafTranslateDrag = drag
    const dx = (clientX - drag.startClientX) / (drag.scale || 1)
    const dy = (clientY - drag.startClientY) / (drag.scale || 1)
    if (!Number.isFinite(dx) || !Number.isFinite(dy) || (dx === 0 && dy === 0)) {
      if (drag.moved) {
        await restoreVectorLeafTranslateSource(drag, true)
        if (!vectorLeafTranslateDrag || vectorLeafTranslateDrag.pointerId !== drag.pointerId) return
        // Read-before-clear (move/resize queue parity): a move that arrived
        // during the restore await is still in `pendingClientX/Y` here and
        // must run once against the restored snapshot instead of being
        // discarded with the clear below.
        const pendingRestoreX = vectorLeafTranslateDrag.pendingClientX
        const pendingRestoreY = vectorLeafTranslateDrag.pendingClientY
        vectorLeafTranslateDrag = { ...vectorLeafTranslateDrag, applying: false, moved: false, pendingClientX: undefined, pendingClientY: undefined }
        if (pendingRestoreX !== undefined && pendingRestoreY !== undefined && (pendingRestoreX !== clientX || pendingRestoreY !== clientY)) {
          void applyLiveVectorLeafTranslateDrag(pendingRestoreX, pendingRestoreY)
        }
      } else {
        if (!vectorLeafTranslateDrag || vectorLeafTranslateDrag.pointerId !== drag.pointerId) return
        const pendingNoopX = vectorLeafTranslateDrag.pendingClientX
        const pendingNoopY = vectorLeafTranslateDrag.pendingClientY
        vectorLeafTranslateDrag = { ...vectorLeafTranslateDrag, applying: false, pendingClientX: undefined, pendingClientY: undefined }
        if (pendingNoopX !== undefined && pendingNoopY !== undefined && (pendingNoopX !== clientX || pendingNoopY !== clientY)) {
          void applyLiveVectorLeafTranslateDrag(pendingNoopX, pendingNoopY)
        }
      }
      return
    }
    await waitForVectorRotateCancel()
    if (!vectorLeafTranslateDrag || vectorLeafTranslateDrag.pointerId !== drag.pointerId) return
    const entry = await drag.historyReady
    if (!vectorLeafTranslateDrag || vectorLeafTranslateDrag.pointerId !== drag.pointerId) return
    if (vectorLeafTranslateDrag.pendingEntry === undefined) vectorLeafTranslateDrag.pendingEntry = entry
    const applied = await previewVectorLeafTranslateFromSource(drag, dx, dy)
    if (!vectorLeafTranslateDrag || vectorLeafTranslateDrag.pointerId !== drag.pointerId) return
    // Read-before-clear (move/resize queue parity): clearing first and then
    // reading always observes `undefined` and drops the final move that
    // arrived while this frame was in flight. Capture the latest coordinates
    // first, clear the slot, then run the latest frame at most once.
    const pendingX = vectorLeafTranslateDrag.pendingClientX
    const pendingY = vectorLeafTranslateDrag.pendingClientY
    vectorLeafTranslateDrag = {
      ...vectorLeafTranslateDrag,
      applying: false,
      moved: applied ? true : vectorLeafTranslateDrag.moved,
      pendingClientX: undefined,
      pendingClientY: undefined,
    }
    if (pendingX !== undefined && pendingY !== undefined && (pendingX !== clientX || pendingY !== clientY)) {
      void applyLiveVectorLeafTranslateDrag(pendingX, pendingY)
    }
  }

  async function previewVectorLeafTranslateFromSource(
    drag: { sourceReady: Promise<{ targetName: string; costumeIndex: number; svgText: string } | undefined>; objectIndex: number; leafIndices: number[]; leafTags: string[]; pointerId: number; targetName: string; targetId: string; gestureId: VectorWriteGesture; structureEpoch?: number; reshapeSelection: number[]; reshapeLeaves: number[] },
    dx: number,
    dy: number,
  ) {
    if (!selectedTarget) return false
    if (!vectorLeafTranslateDrag || vectorLeafTranslateDrag.pointerId !== drag.pointerId) return false
    if (drag.structureEpoch !== undefined && drag.structureEpoch !== getTargetVectorEpoch(drag.targetId)) return false
    if (!Number.isFinite(dx) || !Number.isFinite(dy) || (dx === 0 && dy === 0)) return false
    const source = await drag.sourceReady
    if (!source) return false
    if (!vectorLeafTranslateDrag || vectorLeafTranslateDrag.pointerId !== drag.pointerId) return false
    if (drag.structureEpoch !== undefined && drag.structureEpoch !== getTargetVectorEpoch(drag.targetId)) return false
    // ID-scoped (same-name safe, rename tolerant).
    const target = vectorWriteTargetById(drag.targetId, source.targetName)
    if (!target || stableTargetId(target) !== drag.targetId) return false
    if (stableTargetId(selectedTarget) !== drag.targetId) return false
    if ((selectedTarget.currentCostume ?? 0) !== source.costumeIndex) return false
    if (source.targetName !== drag.targetName && stableTargetId(target) !== drag.targetId) return false
    const doc = new DOMParser().parseFromString(source.svgText, 'image/svg+xml')
    const svg = doc.documentElement
    if (svg.nodeName.toLowerCase() !== 'svg') return false
    const units = editableVectorUnits(svg)
    const unit = units[drag.objectIndex]
    if (!unit || unit.tagName.toLowerCase() !== 'g') return false
    // Re-resolve leaves by position + tag on the live revision; stale,
    // reindexed, cloned or switch-moved leaves refuse instead of moving the
    // wrong node. `use` never moves here (fail-closed).
    const liveLeaves = groupTranslateLeafTargetsInOrder(unit)
    if (!liveLeaves) return false
    if (!classifyGroupUnitForLeafTranslate(unit).ok) return false
    const selected = [...drag.leafIndices].sort((a, b) => a - b)
    if (selected.length === 0) return false
    for (let offset = 0; offset < selected.length; offset++) {
      const leafIndex = selected[offset]!
      const live = liveLeaves[leafIndex]
      if (!live) return false
      const expectedTag = drag.leafTags[offset] ?? ''
      try {
        if (live.tagName.toLowerCase() !== expectedTag) return false
      } catch {
        return false
      }
      const eligibility = classifyLeafElementForTranslate(live)
      if (!eligibility.ok) return false
      if ((eligibility as { kind?: string }).kind === 'use') return false
    }
    let unitWorld: VectorLeafTranslateMatrix | undefined
    try {
      const world = worldTransformMatrix(unit)
      unitWorld = world ? ([world[0], world[1], world[2], world[3], world[4], world[5]] as VectorLeafTranslateMatrix) : undefined
    } catch {
      return false
    }
    const plans: Array<{ leaf: Element; newTransform: string }> = []
    for (const leafIndex of selected) {
      const leaf = liveLeaves[leafIndex]!
      const plan = planLeafDocumentTranslate(unit, leaf, unitWorld, { dx, dy })
      if (!plan.ok) return false
      plans.push({ leaf, newTransform: plan.newTransform })
    }
    // All plans valid: apply atomically so siblings never see a partial write.
    for (const { leaf, newTransform } of plans) {
      try {
        leaf.setAttribute('transform', newTransform)
      } catch {
        return false
      }
    }
    if (!vectorLeafTranslateDrag || vectorLeafTranslateDrag.pointerId !== drag.pointerId) return false
    if (drag.structureEpoch !== undefined && drag.structureEpoch !== getTargetVectorEpoch(drag.targetId)) return false
    let nextSvg: string | undefined = ''
    try {
      const serialized = new XMLSerializer().serializeToString(doc.documentElement)
      // Per-slot FIFO preview + CAS: a preview enqueued after its own cancel
      // is skipped inside the queue, and a preview racing a real external
      // same-slot write is skipped via identity compare (no stale residue).
      const preview = await updateVectorPreviewCostumeCAS(target, source.costumeIndex, serialized, drag.gestureId, drag.structureEpoch)
      if (!preview.applied) {
        if (preview.conflict) await refreshVectorPreviewFromLive(drag.targetId, target)
        return false
      }
      nextSvg = preview.svgText
    } catch {
      return false
    }
    if (nextSvg === undefined) return false
    try {
      vectorObjects = await paperVectorObjectList(nextSvg)
    } catch {
      return false
    }
    selectedVectorObjectIndex = drag.objectIndex
    selectedVectorObjectIndices = vectorObjects.some((object) => object.index === drag.objectIndex) ? [drag.objectIndex] : []
    setReshapeSelection(drag.reshapeSelection)
    setReshapeLeafSelection(drag.reshapeLeaves)
    try {
      await refreshCostumePreview(vectorWriteTargetById(drag.targetId, source.targetName) ?? selectedTarget)
    } catch {
      return false
    }
    return true
  }

  async function restoreVectorLeafTranslateSource(
    drag: { sourceReady: Promise<{ targetName: string; costumeIndex: number; svgText: string } | undefined>; objectIndex: number; reshapeSelection: number[]; reshapeLeaves: number[]; targetName: string; targetId: string; gestureId: VectorWriteGesture; historyReady?: Promise<AssetHistoryEntry | undefined>; pendingEntry?: AssetHistoryEntry },
    keepSelection = true,
  ) {
    const source = await drag.sourceReady
    if (!source) {
      clearVectorGestureIdentity(drag.gestureId)
      return false
    }
    // Barrier write on the same per-slot FIFO: final write of this gesture.
    const target = vectorWriteTargetById(drag.targetId, source.targetName)
    if (!target || stableTargetId(target) !== drag.targetId) {
      clearVectorGestureIdentity(drag.gestureId)
      return false
    }
    const outcome = await restoreVectorSnapshotExact(target, source.costumeIndex, source.svgText, drag)
    if (outcome.conflict) {
      await refreshVectorPreviewFromLive(drag.targetId, target)
      reportVectorExternalConflict('Reshape')
      clearVectorGestureIdentity(drag.gestureId)
      return true
    }
    vectorObjects = await paperVectorObjectList(source.svgText)
    if (keepSelection) {
      selectedVectorObjectIndex = drag.objectIndex
      selectedVectorObjectIndices = vectorObjects.some((object) => object.index === drag.objectIndex) ? [drag.objectIndex] : []
      setReshapeSelection(drag.reshapeSelection)
      setReshapeLeafSelection(drag.reshapeLeaves ?? [])
    }
    await refreshCostumePreview(vectorWriteTargetById(drag.targetId, source.targetName) ?? selectedTarget)
    if (isVectorGestureConflicted(drag.gestureId)) reportVectorExternalConflict('Reshape')
    else status = 'Vector reshape: no change'
    clearVectorGestureIdentity(drag.gestureId)
    return true
  }

  async function restoreVectorLeafTranslateSourceForSelectionSwitch(
    drag: { sourceReady: Promise<{ targetName: string; costumeIndex: number; svgText: string } | undefined>; targetName: string; targetId: string; gestureId: VectorWriteGesture; historyReady?: Promise<AssetHistoryEntry | undefined>; pendingEntry?: AssetHistoryEntry },
  ) {
    const source = await drag.sourceReady
    if (!source) {
      clearVectorGestureIdentity(drag.gestureId)
      return false
    }
    if (source.targetName !== drag.targetName && !drag.targetId) {
      clearVectorGestureIdentity(drag.gestureId)
      return false
    }
    const target = vectorWriteTargetById(drag.targetId, source.targetName)
    if (!target || stableTargetId(target) !== drag.targetId) {
      clearVectorGestureIdentity(drag.gestureId)
      return false
    }
    const costume = target.costumes[source.costumeIndex]
    if (!costume) {
      clearVectorGestureIdentity(drag.gestureId)
      return false
    }
    await restoreVectorSnapshotExact(target, source.costumeIndex, source.svgText, drag)
    clearVectorGestureIdentity(drag.gestureId)
    return true
  }

  function cancelVectorLeafTranslateDrag(event?: PointerEvent) {
    if (!vectorLeafTranslateDrag) return false
    if (event && event.pointerId !== undefined && vectorLeafTranslateDrag.pointerId !== event.pointerId) return false
    // Any cancel while a pointerup commit owns the gesture is refused, not
    // just the trailing auto-loss: the commit below is the final writer.
    // A genuine mid-drag capture loss (no preceding pointerup) never sets
    // `committing` and still cancels.
    if (vectorLeafTranslateDrag.committing) return false
    const drag = vectorLeafTranslateDrag
    vectorLeafTranslateDrag = undefined
    cancelVectorWriteGesture(drag.gestureId)
    const restoring = restoreVectorLeafTranslateSource(drag, true).finally(() => {
      if (vectorRotateCancelPromise === restoring) vectorRotateCancelPromise = undefined
    })
    vectorRotateCancelPromise = restoring
    void restoring
    return true
  }

  async function endVectorLeafTranslateDrag(event: PointerEvent) {
    if (!vectorLeafTranslateDrag || vectorLeafTranslateDrag.pointerId !== event.pointerId) return
    if (event.type === 'pointercancel' || event.type === 'lostpointercapture') {
      cancelVectorLeafTranslateDrag(event)
      return
    }
    // Claim the pointer synchronously (before the first await): the browser
    // queues the implicit `lostpointercapture` auto-loss for this release
    // immediately after the pointerup task, while the commit below still
    // awaits async work — without the claim the trailing auto-loss would
    // route to cancel and restore away the just-released drag.
    vectorLeafTranslateDrag.committing = true
    const myLeafTargetId = vectorLeafTranslateDrag.targetId
    const myLeafPointerId = vectorLeafTranslateDrag.pointerId
    await applyLiveVectorLeafTranslateDrag(event.clientX, event.clientY)
    // The pointerup position above is queued into `pendingClientX/Y` when an
    // older frame is still in flight, so the release point is never lost: the
    // in-flight frame chains to it exactly once (read-before-clear), the loop
    // below waits for that chained frame to settle, and the final re-apply is
    // idempotent (absolute delta from the immutable snapshot).
    for (let attempt = 0; attempt < 200; attempt += 1) {
      const settled = vectorLeafTranslateDrag
      if (!settled || (!settled.applying && settled.pendingClientX === undefined)) break
      await new Promise((resolve) => setTimeout(resolve, 10))
    }
    if (vectorLeafTranslateDrag && vectorLeafTranslateDrag.pointerId === event.pointerId) {
      await applyLiveVectorLeafTranslateDrag(event.clientX, event.clientY)
    }
    // Captured exact slot completion before retiring the identity (move-end
    // parity): a >2s gated write outlives the flag loop above, and retiring
    // early strands `known` behind `live`.
    await settleVectorGestureSlotCompletion(
      () => {
        const settled = vectorLeafTranslateDrag
        if (!settled || settled.pointerId !== myLeafPointerId) return 'gone'
        return !settled.applying && settled.pendingClientX === undefined ? 'settled' : 'busy'
      },
      () => drainTargetVectorWrites(myLeafTargetId),
    )
    const drag = vectorLeafTranslateDrag
    vectorLeafTranslateDrag = undefined
    if (drag && isVectorGestureConflicted(drag.gestureId)) {
      await refreshVectorPreviewFromLive(drag.targetId, selectedTarget ?? undefined)
      reportVectorExternalConflict('Reshape')
      clearVectorGestureIdentity(drag.gestureId)
      return
    }
    if (drag?.moved && drag.pendingEntry) commitPaintHistory(drag.pendingEntry)
    if (drag?.moved) {
      try {
        const _live = selectedTarget ? vectorWriteTargetById(drag.targetId, selectedTarget.name) ?? selectedTarget : undefined
        const _idx = (drag as unknown as { costumeIndex?: number }).costumeIndex ?? selectedTarget?.currentCostume ?? 0
        const _cost = _live?.costumes[_idx]
        const _key = _cost?.md5ext ?? _cost?.assetId
        void (async () => {
          try {
            if (!_live || !_key) return
            const _bytes = await vm.loadAsset(_key, _cost?.dataFormat ?? '')
            if (_bytes && selectedTarget && stableTargetId(selectedTarget) === drag.targetId && (selectedTarget.currentCostume ?? 0) === _idx) {
              rememberCommittedReshapeSelection(drag.targetId, _idx, new Uint8Array(_bytes as Uint8Array))
            }
          } catch {}
        })()
      } catch {
        // Best-effort only.
      }
    }
    void syncReshapeLeavesToPoints()
    status = drag?.moved
      ? drag.leafIndices.length > 1
        ? `Vector leaves moved (${drag.leafIndices.length})`
        : 'Vector leaf moved'
      : 'Vector reshape: no change'
    if (drag) clearVectorGestureIdentity(drag.gestureId)
  }

  function pathPointDragDelta(dx: number, dy: number, snap: boolean) {
    if (!snap) return { x: dx, y: dy }
    const length = Math.hypot(dx, dy)
    if (!length) return { x: 0, y: 0 }
    const angle = Math.round(Math.atan2(dy, dx) / (Math.PI / 4)) * (Math.PI / 4)
    return { x: Math.cos(angle) * length, y: Math.sin(angle) * length }
  }

  type RotationCenterDragState = { pointerId: number; startClientX: number; startClientY: number; dx: number; dy: number; scale: number; targetId: string; index: number }
  function beginRotationCenterDrag(event: PointerEvent) {
    if (!selectedTarget) return
    // Gate bitmap centers on the settled workspace: dragging the center while
    // the canvas still shows the previous asset would fold a stale delta into
    // the next save.
    if (costumeEditMode === 'bitmap') {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        refuseStaleBitmapWorkspace('Rotation center')
        return
      }
    }
    event.preventDefault()
    event.stopPropagation()
    const element = event.currentTarget as HTMLElement
    const host = element.parentElement
    const rect = host?.getBoundingClientRect()
    const dims = vectorPreviewDimensions()
    const scale = rect ? Math.min(rect.width / dims.width, rect.height / dims.height) : 1
    element.setPointerCapture(event.pointerId)
    rotationCenterDrag = { pointerId: event.pointerId, startClientX: event.clientX, startClientY: event.clientY, dx: 0, dy: 0, scale, targetId: stableTargetId(selectedTarget), index: selectedTarget.currentCostume ?? 0 } as RotationCenterDragState
  }

  function dragRotationCenter(event: PointerEvent) {
    if (!rotationCenterDrag || rotationCenterDrag.pointerId !== event.pointerId) return
    rotationCenterDrag = {
      ...rotationCenterDrag,
      dx: event.clientX - rotationCenterDrag.startClientX,
      dy: event.clientY - rotationCenterDrag.startClientY,
    }
  }

  async function endRotationCenterDrag(event: PointerEvent) {
    if (!selectedTarget || !rotationCenterDrag || rotationCenterDrag.pointerId !== event.pointerId) return
    const drag = rotationCenterDrag as RotationCenterDragState
    rotationCenterDrag = undefined
    // Post-drag gate: a target/costume switch mid-drag aborts instead of
    // writing the old delta into the newly selected asset.
    if (stableTargetId(selectedTarget) !== drag.targetId || (selectedTarget.currentCostume ?? 0) !== drag.index) {
      refuseStaleBitmapWorkspace('Rotation center')
      return
    }
    if (costumeEditMode === 'bitmap' && !isBitmapWorkspaceSettledFor(drag.targetId, drag.index)) {
      refuseStaleBitmapWorkspace('Rotation center')
      return
    }
    const index = selectedTarget.currentCostume ?? 0
    const costume = selectedTarget.costumes[index]
    if (!costume) return
    const scale = drag.scale || 1
    const target = selectedTarget
    // Same-slot ordered metadata write (no bytes): serialize with gated
    // previews/restores so a concurrent drag cannot interleave.
    await enqueueVectorCostumeWrite(
      vectorWriteSlotKey(stableTargetId(target), index),
      undefined,
      'edit',
      () =>
        vm.updateCostume(target.name, index, {
          rotationCenterX: (costume.rotationCenterX ?? (target.isStage ? 240 : 48)) + drag.dx / scale,
          rotationCenterY: (costume.rotationCenterY ?? (target.isStage ? 180 : 48)) + drag.dy / scale,
        }),
    )
    rememberPaintKnown(stableTargetId(target), index, readLiveSlotIdentity(stableTargetId(target), index))
    status = 'Rotation center updated'
  }

  async function updateVectorObject(mutator: (element: Element) => boolean | void | Promise<boolean | void>, captureHistory = true): Promise<boolean> {
    if (!selectedTarget || selectedVectorObjectIndex < 0) return false
    const updateOwner = selectedTarget
    const updateTargetId = stableTargetId(updateOwner)
    const index = updateOwner.currentCostume ?? 0
    const updateScope = captureDiscreteSaveScope(updateTargetId, index)
    const updateScopeAlive = () => isDiscreteSaveScopeCurrent(updateScope, discreteSaveLiveOf(updateScope))
    const prevUpdateIndex = selectedVectorObjectIndex
    const prevUpdateIndices = [...selectedVectorObjectIndices]
    const loaded = await currentSvgDocument(updateOwner, index)
    if (!updateScopeAlive()) return false
    if (!loaded) return false
    const { doc, svg } = loaded
    const element = editableVectorUnits(svg)[selectedVectorObjectIndex]
    if (!element) return false
    const pendingEntry = captureHistory ? await peekCostumeHistory(updateOwner, index) : undefined
    if (!updateScopeAlive()) return false
    const applied = await mutator(element)
    if (applied === false) return false
    if (!updateScopeAlive()) return false
    const updateLive = vectorWriteTargetById(updateTargetId, updateOwner.name) ?? updateOwner
    if (stableTargetId(updateLive) !== updateTargetId) return false
    const updateCommit = await updateVectorCostumeFromEditor(updateLive, index, new XMLSerializer().serializeToString(doc.documentElement), { quiet: true, isAlive: updateScopeAlive })
    if (updateCommit.kind !== 'applied') {
      if (updateScopeAlive() || (updateCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(updateScope, discreteSaveLiveOf(updateScope)))) {
        selectedVectorObjectIndex = prevUpdateIndex
        selectedVectorObjectIndices = [...prevUpdateIndices]
        await refreshVectorPreviewFromLive(updateTargetId, updateLive)
        reportVectorExternalConflict('Edit')
      }
      return false
    }
    if (!updateScopeAlive()) return false
    if (pendingEntry) commitPaintHistory(pendingEntry)
    if (!updateScopeAlive()) return false
    const nextSvg = updateCommit.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (!updateScopeAlive()) return false
    await refreshCostumePreview(vectorWriteTargetById(updateTargetId, updateOwner.name) ?? updateOwner)
    if (!updateScopeAlive()) return false
    try {
      rememberCommittedReshapeSelection(updateTargetId, index, new TextEncoder().encode(nextSvg))
    } catch {
      // Best-effort only.
    }
    status = 'Vector object updated'
    return true
  }

  async function updateVectorPathPoint(objectIndex: number, pointIndex: number, x: number, y: number, splitHandles = false, captureHistory = true): Promise<boolean> {
    if (!selectedTarget || objectIndex < 0) return false
    const pathOwner = selectedTarget
    const pathTargetId = stableTargetId(pathOwner)
    const index = pathOwner.currentCostume ?? 0
    const pathScope = captureDiscreteSaveScope(pathTargetId, index)
    const pathScopeAlive = () => isDiscreteSaveScopeCurrent(pathScope, discreteSaveLiveOf(pathScope))
    const prevPathIndices = [...selectedVectorObjectIndices]
    const loaded = await currentSvgDocument(pathOwner, index)
    if (!pathScopeAlive()) return false
    if (!loaded) return false
    const { doc, svg } = loaded
    const element = editableVectorUnits(svg)[objectIndex]
    if (!element) return false
    const pendingEntry = captureHistory ? await peekCostumeHistory(pathOwner, index) : undefined
    if (!pathScopeAlive()) return false
    const applied = await moveVectorEditablePoint(element, pointIndex, x, y, splitHandles)
    if (!applied) return false
    if (!pathScopeAlive()) return false
    const pathLive = vectorWriteTargetById(pathTargetId, pathOwner.name) ?? pathOwner
    if (stableTargetId(pathLive) !== pathTargetId) return false
    const pathCommit = await updateVectorCostumeFromEditor(pathLive, index, new XMLSerializer().serializeToString(doc.documentElement), { quiet: true, isAlive: pathScopeAlive })
    if (pathCommit.kind !== 'applied') {
      if (pathScopeAlive() || (pathCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(pathScope, discreteSaveLiveOf(pathScope)))) {
        selectedVectorObjectIndex = objectIndex
        selectedVectorObjectIndices = [...prevPathIndices]
        await refreshVectorPreviewFromLive(pathTargetId, pathLive)
        reportVectorExternalConflict('Edit')
      }
      return false
    }
    if (!pathScopeAlive()) return false
    if (pendingEntry) commitPaintHistory(pendingEntry)
    if (!pathScopeAlive()) return false
    const nextSvg = pathCommit.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (!pathScopeAlive()) return false
    selectedVectorObjectIndex = objectIndex
    selectedVectorObjectIndices = [objectIndex]
    await refreshCostumePreview(vectorWriteTargetById(pathTargetId, pathOwner.name) ?? pathOwner)
    if (!pathScopeAlive()) return false
    try {
      rememberCommittedReshapeSelection(pathTargetId, index, new TextEncoder().encode(nextSvg))
    } catch {
      // Best-effort only.
    }
    status = 'Vector path point updated'
    return true
  }

  // Bulk anchor translation through one Paper import/serialize pass
  // (`moveVectorReshapePoints`). All anchors resolve against the same
  // pre-mutation flattened numbering (moves never add/remove slots), each
  // selected anchor travels with its own handles carried rigidly, and only
  // edited paths are written back — a second sequential move can never clobber
  // the first through a stale element reference. Ancestor transforms are
  // mapped inside the helper, so targets stay in document coordinates.
  // Control slots are never passed here — control drags use
  // `updateVectorPathPoint` directly.
  async function updateVectorReshapePoints(
    objectIndex: number,
    targets: Array<{ index: number; x: number; y: number }>,
    captureHistory = true,
  ): Promise<boolean> {
    if (!selectedTarget || objectIndex < 0 || targets.length === 0) return false
    const reshapeOwner = selectedTarget
    const reshapeTargetId = stableTargetId(reshapeOwner)
    const index = reshapeOwner.currentCostume ?? 0
    const reshapeScope = captureDiscreteSaveScope(reshapeTargetId, index)
    const reshapeScopeAlive = () => isDiscreteSaveScopeCurrent(reshapeScope, discreteSaveLiveOf(reshapeScope))
    const prevReshapeIndices = [...selectedVectorObjectIndices]
    const loaded = await currentSvgDocument(reshapeOwner, index)
    if (!reshapeScopeAlive()) return false
    if (!loaded) return false
    const { doc, svg } = loaded
    const element = editableVectorUnits(svg)[objectIndex]
    if (!element || element.tagName.toLowerCase() === 'text') return false
    const pendingEntry = captureHistory ? await peekCostumeHistory(reshapeOwner, index) : undefined
    if (!reshapeScopeAlive()) return false
    const result = await moveVectorReshapePoints(element, targets)
    if (!result.moved) return false
    if (!reshapeScopeAlive()) return false
    const reshapeLive = vectorWriteTargetById(reshapeTargetId, reshapeOwner.name) ?? reshapeOwner
    if (stableTargetId(reshapeLive) !== reshapeTargetId) return false
    const reshapeCommit = await updateVectorCostumeFromEditor(reshapeLive, index, new XMLSerializer().serializeToString(doc.documentElement), { quiet: true, isAlive: reshapeScopeAlive })
    if (reshapeCommit.kind !== 'applied') {
      if (reshapeScopeAlive() || (reshapeCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(reshapeScope, discreteSaveLiveOf(reshapeScope)))) {
        selectedVectorObjectIndex = objectIndex
        selectedVectorObjectIndices = [...prevReshapeIndices]
        await refreshVectorPreviewFromLive(reshapeTargetId, reshapeLive)
        reportVectorExternalConflict('Edit')
      }
      return false
    }
    if (!reshapeScopeAlive()) return false
    if (pendingEntry) commitPaintHistory(pendingEntry)
    if (!reshapeScopeAlive()) return false
    const nextSvg = reshapeCommit.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (!reshapeScopeAlive()) return false
    selectedVectorObjectIndex = objectIndex
    selectedVectorObjectIndices = [objectIndex]
    await refreshCostumePreview(vectorWriteTargetById(reshapeTargetId, reshapeOwner.name) ?? reshapeOwner)
    if (!reshapeScopeAlive()) return false
    try {
      rememberCommittedReshapeSelection(reshapeTargetId, index, new TextEncoder().encode(nextSvg))
    } catch {
      // Best-effort only.
    }
    status = result.movedIndices.length > 1 ? `Vector path points updated (${result.movedIndices.length})` : 'Vector path point updated'
    return true
  }

  function isReshapeTextEditing() {
    return typeof document !== 'undefined' && Boolean(document.querySelector('[data-inline-text-editor]'))
  }

  // Curve click: split the nearest curve of the selected editable unit.
  // Document coordinates (same space as moveVectorEditablePoint), so ancestor
  // transforms are handled inside the helper. History is captured once per
  // successful insert; misses (too-far / existing anchor / text) leave the
  // undo stack untouched.
  async function addVectorPathPointAt(point: { x: number; y: number }, toleranceSvgUnits?: number): Promise<boolean> {
    if (!selectedTarget || selectedVectorObjectIndex < 0 || isReshapeTextEditing()) return false
    if (vectorPathPointDrag || vectorLeafTranslateDrag) {
      status = 'Finish the reshape drag first'
      return false
    }
    const costumeIndex = selectedTarget.currentCostume ?? 0
    const addOwner = selectedTarget
    const addTargetId = stableTargetId(addOwner)
    const addScope = captureDiscreteSaveScope(addTargetId, costumeIndex)
    const addScopeAlive = () => isDiscreteSaveScopeCurrent(addScope, discreteSaveLiveOf(addScope))
    const prevAddReshape = [...vectorReshapePointIndices]
    const prevAddMasks: ReshapeHandleMasks = { ...vectorReshapeHandleMasks }
    const loaded = await currentSvgDocument(addOwner, costumeIndex)
    if (!addScopeAlive()) return false
    if (!loaded) return false
    const { doc, svg } = loaded
    const element = editableVectorUnits(svg)[selectedVectorObjectIndex]
    if (!element || element.tagName.toLowerCase() === 'text') return false
    const pendingEntry = await peekCostumeHistory(addOwner, costumeIndex)
    if (!addScopeAlive()) return false
    // Zoom-aware add budget (6.25 screen px). BitmapEditor passes the
    // layout-measured value; direct callers fall back to the bound zoom.
    const tolerance = Number.isFinite(toleranceSvgUnits) && (toleranceSvgUnits as number) >= 0
      ? (toleranceSvgUnits as number)
      : vectorReshapeToleranceSvgUnits(nudgeViewportScale())
    const result = await addVectorPathPoint(element, point.x, point.y, { tolerance })
    if (!result.added) {
      // no-op: スタック不変・redo 温存。既存アンカー選択のみ副作用とする。
      // Clicking an existing anchor selects it instead of stacking a duplicate.
      if (result.reason === 'already-anchor' && result.pointIndex !== undefined) {
        setReshapeSelection([result.pointIndex])
        void syncReshapeLeavesToPoints()
        status = 'Reshape point selected'
      } else if (result.reason === 'too-far') {
        status = 'Reshape add: no curve nearby'
      } else {
        status = 'Reshape add: not editable'
      }
      return false
    }
    if (pendingEntry) {
      // Committed only after the CAS below succeeds.
    }
    if (!addScopeAlive()) return false
    const addLive = vectorWriteTargetById(addTargetId, addOwner.name) ?? addOwner
    if (stableTargetId(addLive) !== addTargetId) return false
    const addCommit = await updateVectorCostumeFromEditor(addLive, costumeIndex, new XMLSerializer().serializeToString(doc.documentElement), { quiet: true, isAlive: addScopeAlive })
    if (addCommit.kind !== 'applied') {
      if (addScopeAlive() || (addCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(addScope, discreteSaveLiveOf(addScope)))) {
        setReshapeSelectionWithMasks(prevAddMasks)
        await refreshVectorPreviewFromLive(addTargetId, addLive)
        reportVectorExternalConflict('Edit')
      }
      return false
    }
    if (!addScopeAlive()) return false
    if (pendingEntry) commitPaintHistory(pendingEntry)
    if (!addScopeAlive()) return false
    const nextSvg = addCommit.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (!addScopeAlive()) return false
    selectedVectorObjectIndices = [selectedVectorObjectIndex]
    await refreshCostumePreview(vectorWriteTargetById(addTargetId, addOwner.name) ?? addOwner)
    if (!addScopeAlive()) return false
    // The new anchor has no pre-mutation identity, so select it only after
    // the preview settled (a preview-time rebase would drop it as unmatched).
    setReshapeSelection(result.pointIndex !== undefined ? [result.pointIndex] : [])
    void syncReshapeLeavesToPoints()
    // Post-edit prior (not pre-operation selection): the next delete/redo for
    // this slot must see the added anchor, never the stale pre-add triple.
    // Committed only on applied CAS + live scope (same guard as history).
    try {
      rememberCommittedReshapeSelection(addTargetId, costumeIndex, new TextEncoder().encode(nextSvg))
    } catch {
      // Best-effort only.
    }
    status = 'Vector path point added'
    return true
  }

  // Anchor deletion for the reshape selection (double-click, Delete-button or
  // Delete key). One import/serialize pass for the whole batch, exactly one
  // history entry on success. Control handles and degenerate deletions are
  // refused per anchor without history; a fully-refused batch is a no-op
  // (stack untouched, redo kept). Surviving selection indices are remapped
  // down by the removed flattened slots so they keep pointing at the same
  // anchors, then revalidated as live anchors.
  async function deleteVectorReshapePoints(pointIndices: readonly number[]): Promise<boolean> {
    if (!selectedTarget || selectedVectorObjectIndex < 0 || pointIndices.length === 0 || isReshapeTextEditing()) return false
    if (vectorPathPointDrag || vectorLeafTranslateDrag) {
      status = 'Finish the reshape drag first'
      return false
    }
    const costumeIndex = selectedTarget.currentCostume ?? 0
    const deleteOwner = selectedTarget
    const deleteTargetId = stableTargetId(deleteOwner)
    const deleteScope = captureDiscreteSaveScope(deleteTargetId, costumeIndex)
    const deleteScopeAlive = () => isDiscreteSaveScopeCurrent(deleteScope, discreteSaveLiveOf(deleteScope))
    const prevDeleteReshape = [...vectorReshapePointIndices]
    const prevDeleteMasks: ReshapeHandleMasks = { ...vectorReshapeHandleMasks }
    const loaded = await currentSvgDocument(deleteOwner, costumeIndex)
    if (!deleteScopeAlive()) return false
    if (!loaded) return false
    const { doc, svg } = loaded
    const element = editableVectorUnits(svg)[selectedVectorObjectIndex]
    if (!element || element.tagName.toLowerCase() === 'text') return false
    const pendingEntry = await peekCostumeHistory(deleteOwner, costumeIndex)
    if (!deleteScopeAlive()) return false
    // Oracle parity: the delete entry merges the selection at the prior
    // committed snapshot, not the unconditional deletion-time UI. A
    // selection-only change after the last snapshot is therefore lost on
    // delete->undo unless a post-selection edit snapshot recorded it.
    // Freshness gate: the prior must describe the entry's pre-delete bytes
    // (exact byte equality of two distinct buffers); a stale prior from a
    // missed edit/external write must never retarget (fail-closed to
    // selection-lost).
    try {
      if (pendingEntry && pendingEntry.kind === 'costume') {
        const candidate = priorCommittedReshapeSelectionForSlot(deleteTargetId, costumeIndex)
        const fresh =
          candidate !== undefined &&
          isSelectionSnapshotFreshForBytes(candidate, pendingEntry.bytes as unknown as Uint8Array | undefined | null)
        const prior = mergeSelectionAtPriorCommitted(fresh ? candidate : undefined)
        if (prior) historyReshapeSelection.set(pendingEntry, prior)
        else historyReshapeSelection.delete(pendingEntry)
      }
    } catch {
      // Best-effort only.
    }
    const result = await deleteVectorPathPoints(element, pointIndices)
    if (!result.deleted) {
      // no-op: スタック不変・redo 温存。
      const first = result.skipped[0]
      status = first?.reason === 'minimum-segments'
        ? 'Reshape delete: minimum segments'
        : first?.reason === 'control-point'
          ? 'Reshape delete: select an anchor'
          : 'Reshape delete: not editable'
      return false
    }
    if (pendingEntry) {
      // Committed only after the CAS below succeeds.
    }
    if (!deleteScopeAlive()) return false
    const deleteLive = vectorWriteTargetById(deleteTargetId, deleteOwner.name) ?? deleteOwner
    if (stableTargetId(deleteLive) !== deleteTargetId) return false
    const deleteCommit = await updateVectorCostumeFromEditor(deleteLive, costumeIndex, new XMLSerializer().serializeToString(doc.documentElement), { quiet: true, isAlive: deleteScopeAlive })
    if (deleteCommit.kind !== 'applied') {
      if (deleteScopeAlive() || (deleteCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(deleteScope, discreteSaveLiveOf(deleteScope)))) {
        setReshapeSelectionWithMasks(prevDeleteMasks)
        await refreshVectorPreviewFromLive(deleteTargetId, deleteLive)
        reportVectorExternalConflict('Edit')
      }
      return false
    }
    if (!deleteScopeAlive()) return false
    if (pendingEntry) commitPaintHistory(pendingEntry)
    if (!deleteScopeAlive()) return false
    const nextSvg = deleteCommit.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (!deleteScopeAlive()) return false
    selectedVectorObjectIndices = [selectedVectorObjectIndex]
    // Remap the surviving selection through every removal (descending order:
    // higher removals never disturb lower indices), then keep live anchors.
    // Prefer the precise disjoint ranges: the legacy contiguous `removed`
    // over-covers the survivor for a deleted first anchor (vanished
    // {anchor, out, nextIn} reported as {index, 3}), dropping the surviving
    // old anchor. Fall back to `removed` only for older results.
    let next = normalizeReshapeSelection(vectorReshapePointIndices)
    let nextMasks = normalizeReshapeHandleMasks(vectorReshapeHandleMasks)
    if (result.removedRanges && result.removedRanges.length > 0) {
      next = remapReshapeSelectionAfterBulkRanges(next, result.removedRanges)
      nextMasks = remapReshapeHandleMasksAfterBulkRanges(nextMasks, result.removedRanges)
    } else {
      for (const removal of result.removed) {
        next = remapReshapeSelectionAfterSlotDelete(next, removal.index, removal.slots)
        nextMasks = remapReshapeHandleMasksAfterSlotDelete(nextMasks, removal.index, removal.slots)
      }
    }
    const owner = vectorObjects.find((object) => object.index === selectedVectorObjectIndex)
    next = next.filter((index) => isReshapeAnchorLive(owner?.points ?? [], index))
    // Keep masks consistent with surviving anchors (drop vanished anchors).
    // Prune by live anchors, not by the point-bit projection, so latent
    // handle-only residuals (2/4/6) on live anchors survive the delete remap.
    {
      const liveAnchorSet = new Set(
        (owner?.points ?? []).filter((point) => point.kind !== 'control').map((point) => point.index),
      )
      const pruned: ReshapeHandleMasks = {}
      for (const [key, value] of Object.entries(nextMasks)) {
        const flat = Number(key)
        if (liveAnchorSet.has(flat)) pruned[flat] = value
      }
      nextMasks = pruned
    }
    setReshapeSelectionWithMasks(nextMasks)
    await refreshCostumePreview(vectorWriteTargetById(deleteTargetId, deleteOwner.name) ?? deleteOwner)
    if (!deleteScopeAlive()) return false
    // Post-delete committed selection (usually empty survivors) becomes the
    // prior for the next entry; the deleted masks live only in the delete
    // entry's prior snapshot for undo.
    try {
      rememberCommittedReshapeSelection(deleteTargetId, costumeIndex, new TextEncoder().encode(nextSvg))
    } catch {
      // Best-effort only.
    }
    // The preview above invalidates in-flight derivations; re-derive leaves
    // from the remapped survivors on the settled artwork.
    void syncReshapeLeavesToPoints()
    status = result.deletedIndices.length > 1
      ? `Vector path points deleted (${result.deletedIndices.length})`
      : 'Vector path point deleted'
    return true
  }

  // Anchor deletion for the reshape selection (double-click or Delete key).
  // Control handles and degenerate deletions are refused without history.
  async function deleteVectorReshapePoint(pointIndex?: number): Promise<boolean> {
    const targets = pointIndex !== undefined ? [pointIndex] : reshapeLiveActionIndices()
    return deleteVectorReshapePoints(targets)
  }

  // Reshape 選択アンカーの曲線化/直線化 (Scratch mode-tools の Curved/Pointed)。
  // vector-point-style.ts の DOM ラッパーに選択配列ごと委譲する。要素の transform は保持し、
  // 祖先 transform はヘルパー内で逆写像するため、ここでは文書座標の変換を行わない。
  // 成功時は履歴を exactly 1 件積み、選択を変異後の flattened anchor index に
  // 載せ替える (ハンドル増減で後方 index がずれるため)。no-op 時は DOM・履歴・
  // redo に触れない。既存の移動/追加/削除と同じ更新経路を通す。
  async function styleVectorReshapePoint(mode: 'curved' | 'pointed'): Promise<boolean> {
    const targetIndices = reshapeLiveActionIndices()
    if (!selectedTarget || selectedVectorObjectIndex < 0 || targetIndices.length === 0 || isReshapeTextEditing()) return false
    if (vectorPathPointDrag || vectorLeafTranslateDrag) {
      status = 'Finish the reshape drag first'
      return false
    }
    // Pre-mutation anchor coordinates for stable-identity rebasing below.
    // Curving/pointing inserts/removes flattened handle slots, so later
    // indices shift: an unchanged skipped index may now name a handle slot
    // or another anchor. The helper returns post-mutation indices only for
    // changed anchors; survivors are rebased by coordinates (anchors never
    // move here) and dropped when ambiguous instead of editing the wrong one.
    const styledObjectIndex = selectedVectorObjectIndex
    const previousStyleOwnerPoints = vectorObjects.find((object) => object.index === styledObjectIndex)?.points ?? []
    const costumeIndex = selectedTarget.currentCostume ?? 0
    const styleOwner = selectedTarget
    const styleTargetId = stableTargetId(styleOwner)
    const styleScope = captureDiscreteSaveScope(styleTargetId, costumeIndex)
    const styleScopeAlive = () => isDiscreteSaveScopeCurrent(styleScope, discreteSaveLiveOf(styleScope))
    const prevStyleSelection = selectedVectorObjectIndex
    const prevStyleIndices = [...selectedVectorObjectIndices]
    const prevStyleReshape = [...vectorReshapePointIndices]
    const prevStyleMasks: ReshapeHandleMasks = { ...vectorReshapeHandleMasks }
    const loaded = await currentSvgDocument(styleOwner, costumeIndex)
    if (!styleScopeAlive()) return false
    if (!loaded) return false
    const { doc, svg } = loaded
    const element = editableVectorUnits(svg)[selectedVectorObjectIndex]
    if (!element || element.tagName.toLowerCase() === 'text') return false
    const pendingEntry = await peekCostumeHistory(styleOwner, costumeIndex)
    if (!styleScopeAlive()) return false
    const result =
      mode === 'curved'
        ? await curveVectorPointStyle(element, targetIndices)
        : await pointVectorPointStyle(element, targetIndices)
    if (!result.changed) {
      // no-op: スタック不変・redo 温存。DOM はヘルパーが変更していない。
      const first = result.skipped[0]
      const domReason = result.reason
      status =
        domReason === 'not-editable' || domReason === 'import-failed' || domReason === 'no-path'
          ? 'Reshape style: not editable'
          : first?.reason === 'not-found' || domReason === 'not-found'
            ? 'Reshape style: point not found'
            : first?.reason === 'control-point' || domReason === 'control-point'
              ? 'Reshape style: select an anchor'
              : first?.reason === 'isolated' || domReason === 'isolated'
                ? 'Reshape style: isolated point'
                : 'Reshape style: no change'
      return false
    }
    if (pendingEntry) {
      // Committed only after the CAS below succeeds.
    }
    if (!styleScopeAlive()) return false
    const styleLive = vectorWriteTargetById(styleTargetId, styleOwner.name) ?? styleOwner
    if (stableTargetId(styleLive) !== styleTargetId) return false
    const styleCommit = await updateVectorCostumeFromEditor(styleLive, costumeIndex, new XMLSerializer().serializeToString(doc.documentElement), { quiet: true, isAlive: styleScopeAlive })
    if (styleCommit.kind !== 'applied') {
      if (styleScopeAlive() || (styleCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(styleScope, discreteSaveLiveOf(styleScope)))) {
        selectedVectorObjectIndex = prevStyleSelection
        selectedVectorObjectIndices = [...prevStyleIndices]
        setReshapeSelectionWithMasks(prevStyleMasks)
        await refreshVectorPreviewFromLive(styleTargetId, styleLive)
        reportVectorExternalConflict('Edit')
      }
      return false
    }
    if (!styleScopeAlive()) return false
    if (pendingEntry) commitPaintHistory(pendingEntry)
    if (!styleScopeAlive()) return false
    const nextSvg = styleCommit.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (!styleScopeAlive()) return false
    selectedVectorObjectIndices = [selectedVectorObjectIndex]
    // 変異後の anchor index に載せ替える (helper が変異後の値を返す)。
    // 変更されなかった指定はハンドル増減でずれているため、変異前の座標で
    // 同一アンカーを探して載せ替える。一意に定まらないものは捨てる
    // (偶然再利用された別アンカーの誤編集防止)。
    const owner = vectorObjects.find((object) => object.index === selectedVectorObjectIndex)
    const livePoints = owner?.points ?? []
    const rebasedSkipped = rebaseReshapeSelectionByAnchorCoordinates(
      previousStyleOwnerPoints.filter((point) => point.kind !== 'control'),
      livePoints.filter((point) => point.kind !== 'control'),
      result.skipped.map((item) => item.index),
    )
    // Carry masks by coordinates (anchors never move on style): changed keep
    // their pre-style exact Paper flags when the coordinate still resolves, else 7.
    const rebasedAllMasks = rebaseReshapeHandleMasksByAnchorCoordinates(
      previousStyleOwnerPoints.filter((point) => point.kind !== 'control'),
      livePoints.filter((point) => point.kind !== 'control'),
      prevStyleMasks,
    )
    const mergedMasks: ReshapeHandleMasks = { ...rebasedAllMasks }
    for (const flat of result.changedIndices) {
      if (mergedMasks[flat] === undefined) mergedMasks[flat] = 7
    }
    // Keep only live anchors (fail-closed).
    {
      const liveSet = new Set(livePoints.filter((p) => p.kind !== 'control').map((p) => p.index))
      for (const key of Object.keys(mergedMasks)) {
        if (!liveSet.has(Number(key))) delete mergedMasks[Number(key)]
      }
    }
    // Trust the index helper's list; masks are its provenance-preserving view.
    // If they disagree (renamed changed indices), fall back to explicit.
    const helperIndices = [...result.changedIndices, ...rebasedSkipped]
    const maskIndices = reshapeSelectedSegmentFlats(normalizeReshapeHandleMasks(mergedMasks)).sort((a, b) => a - b)
    if (JSON.stringify(maskIndices) !== JSON.stringify([...helperIndices].sort((a, b) => a - b))) {
      setReshapeSelection(helperIndices)
    } else {
      setReshapeSelectionWithMasks(mergedMasks)
    }
    await refreshCostumePreview(vectorWriteTargetById(styleTargetId, styleOwner.name) ?? styleOwner)
    if (!styleScopeAlive()) return false
    try {
      rememberCommittedReshapeSelection(styleTargetId, costumeIndex, new TextEncoder().encode(nextSvg))
    } catch {
      // Best-effort only.
    }
    // The preview above invalidates in-flight derivations; re-derive leaves
    // from the proven post-mutation selection on the settled artwork.
    void syncReshapeLeavesToPoints()
    status = mode === 'curved'
      ? result.changedIndices.length > 1
        ? `Reshape points curved (${result.changedIndices.length})`
        : 'Reshape point curved'
      : result.changedIndices.length > 1
        ? `Reshape points pointed (${result.changedIndices.length})`
        : 'Reshape point pointed'
    return true
  }

  async function curveVectorReshapePoint(): Promise<boolean> {
    return styleVectorReshapePoint('curved')
  }

  async function pointVectorReshapePoint(): Promise<boolean> {
    return styleVectorReshapePoint('pointed')
  }

  async function updateVectorObjects(mutator: (element: Element) => boolean | void | Promise<boolean | void>, captureHistory = true): Promise<boolean> {
    if (!selectedTarget) return false
    const objectsOwner = selectedTarget
    const objectsTargetId = stableTargetId(objectsOwner)
    const index = objectsOwner.currentCostume ?? 0
    const objectsScope = captureDiscreteSaveScope(objectsTargetId, index)
    const objectsScopeAlive = () => isDiscreteSaveScopeCurrent(objectsScope, discreteSaveLiveOf(objectsScope))
    const prevObjectsIndex = selectedVectorObjectIndex
    const prevObjectsIndices = [...selectedVectorObjectIndices]
    const loaded = await currentSvgDocument(objectsOwner, index)
    if (!objectsScopeAlive()) return false
    if (!loaded) return false
    const { doc, svg } = loaded
    const units = editableVectorUnits(svg)
    const selectedIndices = normalizedVectorSelection(units.length)
    if (selectedIndices.length === 0) return false
    const pendingEntry = captureHistory ? await peekCostumeHistory(objectsOwner, index) : undefined
    if (!objectsScopeAlive()) return false
    let appliedAny = false
    for (const selectedIndex of selectedIndices) {
      const element = units[selectedIndex]
      if (element) {
        const result = await mutator(element)
        if (result !== false) appliedAny = true
      }
    }
    if (!appliedAny) return false
    if (!objectsScopeAlive()) return false
    const objectsLive = vectorWriteTargetById(objectsTargetId, objectsOwner.name) ?? objectsOwner
    if (stableTargetId(objectsLive) !== objectsTargetId) return false
    const objectsCommit = await updateVectorCostumeFromEditor(objectsLive, index, new XMLSerializer().serializeToString(doc.documentElement), { quiet: true, isAlive: objectsScopeAlive })
    if (objectsCommit.kind !== 'applied') {
      if (objectsScopeAlive() || (objectsCommit.reason === 'external' && isDiscreteSaveScopeCurrentAfterOwnBump(objectsScope, discreteSaveLiveOf(objectsScope)))) {
        selectedVectorObjectIndex = prevObjectsIndex
        selectedVectorObjectIndices = [...prevObjectsIndices]
        await refreshVectorPreviewFromLive(objectsTargetId, objectsLive)
        reportVectorExternalConflict('Edit')
      }
      return false
    }
    if (!objectsScopeAlive()) return false
    if (pendingEntry) commitPaintHistory(pendingEntry)
    if (!objectsScopeAlive()) return false
    const nextSvg = objectsCommit.svgText
    vectorObjects = await paperVectorObjectList(nextSvg)
    if (!objectsScopeAlive()) return false
    selectedVectorObjectIndices = selectedVectorObjectIndices.filter((item) => vectorObjects.some((object) => object.index === item))
    selectedVectorObjectIndex = selectedVectorObjectIndices.at(-1) ?? -1
    await refreshCostumePreview(vectorWriteTargetById(objectsTargetId, objectsOwner.name) ?? objectsOwner)
    if (!objectsScopeAlive()) return false
    try {
      rememberCommittedReshapeSelection(objectsTargetId, index, new TextEncoder().encode(nextSvg))
    } catch {
      // Best-effort only.
    }
    status = 'Vector objects updated'
    return true
  }

  async function currentSvgDocument(target: ScratchTarget, index: number) {
    if (vectorRotateCancelPromise) await vectorRotateCancelPromise
    const costume = target.costumes[index]
    const key = costume?.md5ext ?? costume?.assetId
    const bytes = key && costume?.dataFormat === 'svg' ? await vm.loadAsset(key, 'svg') : undefined
    if (!bytes) return undefined
    const doc = new DOMParser().parseFromString(svgTextForVectorEditor(new TextDecoder().decode(bytes), target, costume), 'image/svg+xml')
    const svg = doc.documentElement
    if (svg.nodeName.toLowerCase() !== 'svg') return undefined
    return { doc, svg }
  }

  async function clearBitmapCanvas() {
    // Pending block (B-3 paste/crop/flip/clear gap): while a shape is
    // staged/pending there is no committed state to clear — clearing would
    // silently drop the staged bounds. Block BEFORE any canvas/mutation
    // (no commit, no history) with an explicit status, retained until
    // Escape (commit) or Delete (discard). Disabled path stays await-free.
    if (BITMAP_PENDING_UI_ENABLED && costumeEditMode === 'bitmap') {
      try {
        const clearPendingSession = ensureBitmapPendingController()?.get()
        if (clearPendingSession && clearPendingSession.snapshot().hasPending) {
          status =
            'Bitmap clear blocked (pending shape not committed; press Escape to commit or Delete to discard first; pending retained)'
          return
        }
      } catch {
        status = 'Bitmap clear blocked (pending state unreadable; op blocked, original preserved)'
        return
      }
      const clearEpochTargetId = selectedTarget ? stableTargetId(selectedTarget) : ''
      const clearEpochIndex = selectedTarget?.currentCostume ?? 0
      const clearEpochSerial = bitmapCanvasReloadSerial
      const clearEpochGeneration = bitmapWorkspaceGeneration
      const clearEpochCanvas = bitmapCanvas
      const clearEpochScope = selectedTarget ? captureDiscreteSaveScope(clearEpochTargetId, clearEpochIndex) : undefined
      const clearOk = await guardBitmapPendingCommitFirst('paint-clear')
      if (!clearOk) return
      const clearLiveId = selectedTarget ? stableTargetId(selectedTarget) : ''
      if (clearLiveId !== clearEpochTargetId || (selectedTarget?.currentCostume ?? 0) !== clearEpochIndex) {
        status = 'Bitmap clear blocked (target switched during pending commit; original preserved)'
        return
      }
      if (bitmapCanvasReloadSerial !== clearEpochSerial || bitmapWorkspaceGeneration !== clearEpochGeneration || bitmapCanvas !== clearEpochCanvas) {
        status = 'Bitmap clear blocked (canvas reloaded during pending commit; original preserved)'
        return
      }
      if (clearEpochScope && !isDiscreteSaveScopeCurrent(clearEpochScope, discreteSaveLiveOf(clearEpochScope))) {
        status = 'Bitmap clear blocked (workspace changed during pending commit; original preserved)'
        return
      }
    }
    if (selectedTarget) {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        refuseStaleBitmapWorkspace('Bitmap clear')
        return
      }
    }
    if (bitmapFloatingDragActive()) {
      status = 'Finish the bitmap selection drag first'
      return
    }
    const context = bitmapCanvas?.getContext('2d')
    if (!context) return
    clearBitmapCanvasPreview()
    await saveBitmapCostume('Bitmap cleared')
    status = 'Bitmap cleared'
  }

  function clearBitmapCanvasPreview() {
    const context = bitmapCanvas?.getContext('2d')
    if (!context || !bitmapCanvas) return
    context.clearRect(0, 0, bitmapCanvas.width, bitmapCanvas.height)
    bitmapSelection = undefined
  }

  // Shared floating-move starter for the select tool and the retained
  // bitmap shape tools (rect/oval stay armed after commit, so a press inside
  // the live selection must move it instead of drawing). The canvas is left
  // untouched here; the first effective pointermove punches the source hole
  // and stamps the patch with source-over compositing, so transparent patch
  // pixels never erase the destination. Alt is a PRESS-TIME duplicate flag
  // (Scratch parity): it is frozen here and never refreshed live mid-drag,
  // so toggling Alt mid-drag cannot spawn or cancel a copy. Shift is
  // evaluated live per move (45-degree projection + snap exclusion).
  // Returns true when a drag started; false declines (empty/offscreen
  // selection) so the caller falls through to its own gesture.
  function startBitmapFloatingMove(point: { x: number; y: number }, event: MouseEvent): boolean {
    const context = bitmapCanvas?.getContext('2d')
    if (!context || !bitmapCanvas || !bitmapSelection || !pointInBitmapRect(point, bitmapSelection)) return false
    const live = context.getImageData(0, 0, bitmapCanvas.width, bitmapCanvas.height)
    const session = beginBitmapFloatingSession(live, bitmapSelection, { copy: event.altKey === true })
    if (!session) return false
    const clampedStart = clampPointerIntoBounds(point, { left: 0, top: 0, right: bitmapCanvas.width, bottom: bitmapCanvas.height })
    bitmapMoveDrag = {
      session,
      startPoint: clampedStart,
      startSelection: { ...session.sourceRect },
      copy: event.altKey === true,
      shiftAtStart: event.shiftKey === true,
      pointerId: (event as PointerEvent).pointerId ?? 0,
      targetName: selectedTarget?.name ?? '',
      costumeIndex: selectedTarget?.currentCostume ?? 0,
      destX: session.sourceRect.x,
      destY: session.sourceRect.y,
      moved: false,
      guideOpacity: 0,
    }
    isBitmapPainting = true
    status = event.altKey === true ? 'Duplicating bitmap selection' : 'Moving bitmap selection'
    return true
  }

  async function beginBitmapPaint(event: MouseEvent) {
    // Owner gate: no new stroke/selection/drag may start on an unsettled
    // canvas (decode pending or owner mismatch). Starting one would paint
    // stale pixels and later save them into the new asset.
    if (selectedTarget) {
      const id = stableTargetId(selectedTarget)
      const idx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(id, idx)) {
        refuseStaleBitmapWorkspace('Bitmap paint')
        return
      }
      bitmapStrokeOwner = { targetId: id, index: idx, loadSerial: bitmapCanvasReloadSerial, generation: bitmapWorkspaceGeneration }
    } else {
      bitmapStrokeOwner = undefined
    }
    const context = bitmapCanvas?.getContext('2d')
    const point = bitmapPoint(event)
    if (!pointInBitmapWorkspace(point)) {
      bitmapStrokeOwner = undefined
      return
    }
    if (bitmapTool === 'select') {
      // Legacy select-floating while a shape is staged must not read the
      // pending overlay: refuse before any marquee/floating mutation with the
      // pending retained (Escape commits, Delete discards). Disabled path
      // stays untouched.
      if (BITMAP_PENDING_UI_ENABLED && costumeEditMode === 'bitmap') {
        try {
          const pendingForSelect = ensureBitmapPendingController()?.get()
          if (pendingForSelect) {
            let snap: { hasPending: boolean; commitInFlight: boolean } | undefined
            try {
              snap = pendingForSelect.snapshot()
            } catch {
              snap = undefined
            }
            if (snap && (snap.hasPending || snap.commitInFlight)) {
              let entryId = ''
              let entryGen = 0
              try {
                entryId = selectedTarget ? stableTargetId(selectedTarget) : ''
                entryGen = readProjectGenerationSafe()
              } catch {}
              void entryId
              void entryGen
              bitmapStrokeOwner = undefined
              status = snap.commitInFlight
                ? 'Bitmap save in flight (select-floating blocked; retry after it settles)'
                : 'Bitmap edit pending (select-floating blocked; press Escape to commit or Delete to discard, then retry; pending retained)'
              return
            }
          }
        } catch {
          bitmapStrokeOwner = undefined
          status = 'Bitmap select-floating blocked (pending state unreadable; op blocked, original preserved)'
          return
        }
      }
      // The helper declined (empty/offscreen selection): fall through to
      // marquee selection instead of starting a drag.
      if (startBitmapFloatingMove(point, event)) return
    }
    if (bitmapTool === 'rect' || bitmapTool === 'oval') {
      // Retained shape mode: a press inside the live selection moves it
      // (bounding-box parity); only a blank press draws. The helper declined
      // (empty/offscreen selection): fall through to the draft below.
      // Pending parametric path (B-3) owns the press when staged: an inside
      // press starts a history-free `session.moveBy` drag (never the legacy
      // floating raster path, never `saveBitmapCostume`); a blank press
      // commits-first through `session.pointerDown` below.
      if (BITMAP_PENDING_UI_ENABLED) {
        try {
          const pendingForPress = ensureBitmapPendingController()?.get()
          if (pendingForPress && pendingForPress.snapshot().hasPending) {
            if (startBitmapPendingMove(point, event)) return
            // Blank press: skip the floating raster starter entirely and fall
            // through to the pending `pointerDown` blank-press commit below.
          } else {
            // Enabled but nothing staged: the floating starter declines (no
            // committed selection) and the pending draft below stages.
            // Never start a floating drag on the pending outline path.
          }
        } catch {
          // Fall through to the pending draft below; never silently drop.
        }
      } else if (startBitmapFloatingMove(point, event)) return
      // Pending parametric path (B-3): blank-press commit-first is owned by
      // the session (`pointerDown` commits the previous shape before the new
      // draft, so two shapes never share one base). On refusal the op is
      // blocked with the pending retained and no canvas touch.
      try {
        const controller = ensureBitmapPendingController()
        const session = controller?.get()
        if (controller && session && selectedTarget && bitmapCanvas) {
          const kind = controller.kindFrom(bitmapTool)
          if (kind) {
            const at = clampBitmapPoint(point)
            const style = bitmapPendingStyleNow()
            const mode = normalizeBitmapShapeMode(bitmapShapeMode)
            // Synchronous history-gap / quarantine gates live inside the
            // session; `await` only for the blank-press commit. When a
            // pending is staged the commit lands VM bytes for the live slot:
            // the in-flight barrier below covers the `await` window (never a
            // skip): reloads arriving mid-flight buffer until the flight
            // settles and then reconcile from live. No reload is skipped
            // before the CAS proves the write.
            let preReloadScope: BitmapReloadCommitScope | undefined = undefined
            try {
              const pre = session.snapshot()
              if ((pre.hasPending || pre.commitInFlight) && selectedTarget) {
                captureBitmapReloadBarrierForSlot(stableTargetId(selectedTarget), selectedTarget.currentCostume ?? 0)
                preReloadScope = captureBitmapReloadCommitScope(stableTargetId(selectedTarget), selectedTarget.currentCostume ?? 0)
              }
            } catch {
              // Best effort only: the commit still runs fail-closed below.
            }
            const started = await session.pointerDown(at, kind, mode, style)
            const preReloadScopeCurrent = preReloadScope ? isBitmapReloadCommitScopeCurrent(preReloadScope) : false
            if (!preReloadScope || (preReloadScope && bitmapPendingCommitBarrier === preReloadScope.barrier)) clearBitmapReloadBarrier()
            if (!started.ok) {
              bitmapPendingPainting = false
              isBitmapPainting = false
              bitmapStart = undefined
              bitmapStrokeOwner = undefined
              // A failed/superseded commit lands nothing: no skip may
              // survive (it would hide a concurrent external same-slot write
              // or the rightful owner after a switch/load). Clear it, then
              // repair the stale staged overlay via the scoped conflict
              // reload when the session quarantined.
              clearBitmapReloadSkip()
              await reloadBitmapCanvasIfPendingOwnershipLost(started as { ok: boolean; reason?: string })
              await reconcileDeferredBitmapReload()
              status = (started as { reason?: string }).reason === 'history-gap'
                ? 'history-gap: bytes committed without undo entry; explicit acknowledgement required before further paint/export/switch (Undo unavailable for last stroke)'
                : `Bitmap shape start refused (${(started as { reason?: string }).reason ?? 'unknown'}); pending retained`
              return
            }
            bitmapPendingPainting = true
            isBitmapPainting = true
            bitmapStart = at
            bitmapShapePreviewDrawn = false
            // Keep the committed selection outline cleared and the workspace
            // owner in sync when the blank-press commit landed (mirrors the
            // `guardBitmapPendingCommitFirst` post-commit bookkeeping, minus
            // the status which stays `Drawing bitmap shape` for the new draft).
            // Arm the versioned skip only from the proven live identity: the
            // consumer skips only while live still shows these bytes, so a
            // post-commit external drift (green bytes, same-bytes seq bump,
            // switch/load) fails closed to a real reload instead of hidden.
            try {
              let armWantId: string | undefined = undefined
              let armIndex = 0
              if (!preReloadScope) {
                if (selectedTarget) {
                  armWantId = stableTargetId(selectedTarget)
                  armIndex = selectedTarget.currentCostume ?? 0
                }
              } else if (preReloadScopeCurrent) {
                armWantId = preReloadScope.targetId
                armIndex = preReloadScope.index
              }
              if (armWantId !== undefined) {
                const wantId = armWantId
                const index = armIndex
                if (selectedTarget && bitmapWorkspaceOwner && bitmapWorkspaceOwner.targetId === wantId && bitmapWorkspaceOwner.index === index) {
                  const fresh = (vectorWriteTargetById(wantId, selectedTarget.name) ?? vm.getTarget(wantId) ?? vm.getTarget(selectedTarget.name))?.costumes[index] ?? selectedTarget.costumes[index]
                  bitmapWorkspaceOwner = { ...bitmapWorkspaceOwner, assetKey: fresh?.md5ext ?? fresh?.assetId ?? bitmapWorkspaceOwner.assetKey }
                }
                rememberPaintKnown(wantId, index, readLiveSlotIdentity(wantId, index))
                armBitmapReloadSkipFromLive(wantId, index)
              } else if (preReloadScope) {
                clearBitmapReloadSkip()
              }
            } catch {
              // Best effort only.
            }
            await reconcileDeferredBitmapReload()
            status = 'Drawing bitmap shape'
            return
          }
        }
      } catch {
        // Fall through to the legacy path only when the session itself is
        // unavailable; never silently drop a staged pending. The blank-press
        // commit never ran here, so no own-write skip may survive: clear any
        // barrier/skip so the legacy path (or a concurrent external write)
        // reloads instead of being hidden.
        clearBitmapReloadSkip()
        clearBitmapReloadBarrier()
      }
    }
    isBitmapPainting = true
    bitmapStart = point
    bitmapShapePreviewDrawn = false
    bitmapPreviewBase = context && bitmapCanvas ? context.getImageData(0, 0, bitmapCanvas.width, bitmapCanvas.height) : undefined
    // Store the clamped raster point so the synchronous initial stamp and all
    // later incremental segments share the exact truncated coordinates the
    // full-replay oracle uses (no raw-vs-clamped drift on edges).
    const clampedStart = clampBitmapPoint(point)
    bitmapPaperPoints = [clampedStart]
    bitmapStrokeStamps = 1
    bitmapStrokeCapped = false
    // Synchronous initial preview: stamp the down dot now so pointerdown
    // shows ink immediately (tap parity) instead of waiting for the delayed
    // paper-scope dot-ensure below. The dot stays painted: every later
    // segment is inclusive, so the down point is stamped twice — exactly like
    // the reference (`handleMouseDown` draw + inclusive drag/up walks).
    // Fail-closed: a refused dot restores the base and clears the stroke.
    if ((bitmapTool === 'brush' || bitmapTool === 'eraser') && context) {
      try {
        paintBitmapStrokeSegment(context, clampedStart, clampedStart)
      } catch (error) {
        if (error instanceof RangeError) {
          if (bitmapPreviewBase) restoreBitmapPreviewBase()
          bitmapPaperPoints = []
          bitmapStrokeStamps = 0
          bitmapStrokeCapped = false
          status = 'Bitmap stroke too long — kept original'
          return
        }
        throw error
      }
    }
    if (bitmapTool === 'rect' || bitmapTool === 'oval') {
      // Reference parity (`clearSelection` on blank mousedown): the previous
      // shape is already rasterized, so only its outline goes. The new drag
      // then starts from a clean selection and can never restamp or duplicate
      // the old one.
      bitmapSelection = undefined
    }
    if (bitmapTool === 'select') {
      status = 'Selecting bitmap area'
      return
    }
    if (bitmapTool === 'fill') {
      const filled = applyBitmapFill(event)
      isBitmapPainting = false
      bitmapStart = undefined
      // Skip history + save on no-op (out of bounds or seed already equals
      // the fill color): nothing changed, so there is nothing to commit.
      if (filled) void saveBitmapCostume('Bitmap fill saved')
      else status = 'Bitmap fill: no change'
      return
    }
    // Dead in the current UI (see `drawBitmapText`): the bitmap text tool
    // opens the inline overlay in BitmapEditor and never calls
    // `beginBitmapPaint`. Kept for the historical direct-call shape only.
    if (bitmapTool === 'text') {
      drawBitmapText(event)
      isBitmapPainting = false
      bitmapStart = undefined
      bitmapPreviewBase = undefined
      bitmapPaperPoints = []
          bitmapStrokeStamps = 0
          bitmapStrokeCapped = false
      void saveBitmapCostume('Bitmap text saved')
      return
    }
    if (bitmapTool === 'brush' || bitmapTool === 'eraser' || bitmapTool === 'line' || bitmapTool === 'rect' || bitmapTool === 'oval') {
      void ensureBitmapPaperScope().then(() => {
        // Dot-ensure only: when no moves have arrived yet the replay restores
        // the base and repaints the single dot (opaque-identical to the live
        // dot). When moves already landed, the incremental pixels — including
        // the reference-parity doubled down point — already sit on the canvas,
        // so a full restore+replay must not clobber them.
        if (isBitmapPainting && (bitmapTool === 'brush' || bitmapTool === 'eraser') && bitmapPaperPoints.length <= 1) drawBitmapPaperStroke()
      })
    }
    paintBitmap(event)
  }

  function paintBitmap(event: MouseEvent) {
    if (!isBitmapPainting || !bitmapCanvas) return
    // Pending transform drag (staged rect/oval move): history-free
    // `session.moveBy` from the frozen startBox (never live+shape, no trail,
    // no history, no VM). Ownership is re-checked inside the move helper
    // before every repaint; out-of-order pointerIds are ignored by id.
    if (bitmapPendingMoveDrag && (bitmapTool === 'rect' || bitmapTool === 'oval')) {
      moveBitmapPendingMove(event as unknown as PointerEvent)
      return
    }
    // Pending rotate drag (staged rect/oval free rotation): same absolute
    // `startRotation + gestureDelta` repaint as the handle path, so canvas-
    // level moves (capture loss, synthetic events) track identically.
    if (bitmapPendingRotateDrag && (bitmapTool === 'rect' || bitmapTool === 'oval')) {
      moveBitmapPendingRotate(event as unknown as PointerEvent)
      return
    }
    // Pending parametric draft (rect/oval): history-free overlay from the
    // draft base; ownership is re-checked synchronously inside the session
    // before every paint, so a reload/switch mid-drag leaves the live canvas
    // untouched for the reloader.
    if (bitmapPendingPainting && (bitmapTool === 'rect' || bitmapTool === 'oval')) {
      try {
        const session = ensureBitmapPendingController()?.get()
        if (session && bitmapStart) {
          const at = clampBitmapPoint(bitmapPoint(event))
          const modifiers = readShapeModifiers(event as unknown as { shiftKey?: boolean; altKey?: boolean })
          const result = session.pointerMove(at, modifiers)
          if (!result.ok && (result as { reason?: string }).reason === 'owner-mismatch') {
            bitmapPendingPainting = false
            isBitmapPainting = false
            bitmapStart = undefined
            bitmapStrokeOwner = undefined
            status = 'live canvas left untouched (draft owner changed or uncertain; reloader owns pixels)'
            return
          }
          return
        }
      } catch {
        // Fall through to the legacy path on unexpected session failure.
      }
    }
    // Mid-stroke switch/load must cancel the stroke: continuing would paint
    // old-asset pixels onto the new canvas.
    if (bitmapStrokeOwner) {
      const cur = currentBitmapIdentity()
      if (!cur || cur.targetId !== bitmapStrokeOwner.targetId || cur.index !== bitmapStrokeOwner.index || bitmapStrokeOwner.loadSerial !== bitmapCanvasReloadSerial || Boolean(bitmapWorkspacePending) || !isBitmapWorkspaceSettledFor(cur.targetId, cur.index)) {
        // Stale canvas: the live pixels already belong to another asset (or
        // a newer load). Drop the drag state + guide without touching pixels:
        // restoring the OLD committed snapshot here would corrupt the new
        // artwork. The same-target-but-unsettled case keeps the old path
        // below only when the drag owner still matches the live identity.
        if (bitmapMoveDrag && bitmapCanvas) {
          const dragOwnerMatches = selectedTarget && bitmapMoveDrag.targetName !== undefined && selectedTarget.name === bitmapMoveDrag.targetName && (selectedTarget.currentCostume ?? 0) === bitmapMoveDrag.costumeIndex && cur && cur.index === bitmapMoveDrag.costumeIndex
          if (dragOwnerMatches) {
            const committed = bitmapMoveDrag.session.committed
            bitmapCanvas.getContext('2d')?.putImageData(floatingImageToImageData(committed), 0, 0)
            bitmapSelection = { ...bitmapMoveDrag.startSelection }
          }
        } else if (bitmapPreviewBase) {
          restoreBitmapPreviewBase()
        }
        bitmapMoveDrag = undefined
        isBitmapPainting = false
        bitmapStart = undefined
        bitmapPreviewBase = undefined
        bitmapPaperPoints = []
          bitmapStrokeStamps = 0
          bitmapStrokeCapped = false
        bitmapStrokeOwner = undefined
        refuseStaleBitmapWorkspace('Bitmap paint')
        return
      }
    }
    const context = bitmapCanvas.getContext('2d')
    if (!context) return
    if (bitmapMoveDrag) {
      // Floating move/duplicate preview. Every pointermove re-renders from
      // the committed snapshot (never from the previous preview), so drags
      // cannot accumulate blending. Canvas and zoom mapping come from the
      // shared bitmapPoint (viewport-scale aware); the pointer is clamped
      // into the artboard (the live canvas) before the drag vector is built,
      // the helper clips off-canvas destinations instead of throwing, and
      // unchanged previews (sub-pixel jitter, zero delta) skip the canvas
      // write entirely. Alt stays PRESS-TIME locked (no live toggle): a
      // mid-drag Alt flip is ignored so the copy/plain decision made at
      // press time survives the whole drag. Shift projects the delta onto
      // 45 degrees live and excludes center snapping.
      const drag = bitmapMoveDrag
      // Stale-owner guard: a target/costume switch or newer load in flight
      // must never preview old-asset pixels onto the new canvas. The canvas
      // already shows (or will reload) the new asset here, so drop the drag
      // state + guide without touching pixels or history.
      const cur = currentBitmapIdentity()
      if (!cur || (drag.targetName && selectedTarget && selectedTarget.name !== drag.targetName) || (selectedTarget && (selectedTarget.currentCostume ?? 0) !== drag.costumeIndex) || Boolean(bitmapWorkspacePending) || !isBitmapWorkspaceSettledFor(cur.targetId, cur.index)) {
        bitmapMoveDrag = undefined
        refuseStaleBitmapWorkspace('Bitmap move')
        return
      }
      const rect = bitmapCanvas.getBoundingClientRect()
      const surfaceScale = rect.width > 0 && bitmapCanvas.width > 0 ? rect.width / bitmapCanvas.width : costumeViewportScale
      const rawPoint = bitmapPoint(event)
      const point = clampPointerIntoBounds(rawPoint, { left: 0, top: 0, right: bitmapCanvas.width, bottom: bitmapCanvas.height })
      const rawDx = point.x - drag.startPoint.x
      const rawDy = point.y - drag.startPoint.y
      const shiftKey = (event as PointerEvent).shiftKey === true
      const projected = shiftKey ? projectDeltaToStep({ x: rawDx, y: rawDy }) : { x: rawDx, y: rawDy }
      // Center snap (box closeness, 4 screen px): the united selection
      // center is the floating rect center; the anchor is the TRUE Scratch
      // center (tracked bitmapArtboard.canvasCenterX/Y), NOT the apparent
      // canvas middle. Union canvases diverge (1200px union: true 480 vs
      // width/2 600); res1/stage artboards differ too. Same anchor as the
      // BitmapEditor guide (bitmapTrueCenterForDrag). Shift, refused/stale/
      // resized/untracked geometry skip snapping (safe fail: plain projected
      // delta). Non-central rotationCenter, images, transparency and effects
      // never shift the anchor: only the selection union center matters.
      let dx = projected.x
      let dy = projected.y
      const bitmapSnapCenter = bitmapTrueCenterForDrag(drag)
      if (!shiftKey && bitmapSnapCenter && Number.isFinite(surfaceScale) && surfaceScale > 0) {
        try {
          const sel = drag.startSelection
          const selectionCenter = { x: sel.x + sel.width / 2, y: sel.y + sel.height / 2 }
          const artCenter = bitmapSnapCenter
          const threshold = bitmapSnapThresholdCanvasPx(clampMoveViewportScale(costumeViewportScale))
          const measuredThreshold = 4 / surfaceScale
          const useThreshold = Number.isFinite(measuredThreshold) && measuredThreshold > 0 ? measuredThreshold : threshold
          const snap = resolveCenterSnap({ selectionCenter, dragVector: { x: projected.x, y: projected.y }, artCenter, thresholdPaper: useThreshold })
          if (snap.snapped && snap.snapVector) {
            dx = snap.snapVector.x
            dy = snap.snapVector.y
          }
        } catch {
          // Safe fail: keep the projected delta without snapping.
        }
      }
      const preview = previewBitmapFloatingMove(drag.session, dx, dy, { copy: drag.copy })
      // Drag guide: center crosshair opacity over the moved bounds (full
      // inside, fading over 10 screen px outside), measured against the SAME
      // true center as the snap above. Shift, clicks/noops and
      // unusable geometry hide it (0). Updated per move, discarded on
      // pointerup/cancel/Escape/target-switch/Undo.
      let guideOpacity = 0
      if (!shiftKey && bitmapSnapCenter && (Math.abs(dx) >= 1e-9 || Math.abs(dy) >= 1e-9) && Number.isFinite(surfaceScale) && surfaceScale > 0) {
        try {
          const sel = drag.startSelection
          const selectionCenter = { x: sel.x + sel.width / 2, y: sel.y + sel.height / 2 }
          const artCenter = bitmapSnapCenter
          const fade = bitmapFadeDistanceCanvasPx(clampMoveViewportScale(costumeViewportScale))
          const measuredFade = 10 / surfaceScale
          const useFade = Number.isFinite(measuredFade) && measuredFade > 0 ? measuredFade : fade
          const movedBounds: MoveRect = { left: sel.x + dx, top: sel.y + dy, right: sel.x + sel.width + dx, bottom: sel.y + sel.height + dy }
          guideOpacity = crosshairOpacityForBounds(movedBounds, { x: selectionCenter.x + projected.x, y: selectionCenter.y + projected.y }, artCenter, useFade)
        } catch {
          guideOpacity = 0
        }
      }
      bitmapMoveDrag = { ...drag, guideOpacity }
      if (!preview.changed) return
      context.putImageData(floatingImageToImageData(preview.image), 0, 0)
      bitmapMoveDrag.destX = preview.destX
      bitmapMoveDrag.destY = preview.destY
      bitmapMoveDrag.moved = true
      bitmapSelection = { x: preview.destX, y: preview.destY, width: drag.session.patch.width, height: drag.session.patch.height }
      status = drag.copy ? 'Duplicating bitmap selection' : 'Moving bitmap selection'
      return
    }
    if (bitmapTool === 'line' || bitmapTool === 'rect' || bitmapTool === 'oval' || bitmapTool === 'select') {
      drawBitmapDraft(event)
      return
    }
    if (bitmapTool !== 'brush' && bitmapTool !== 'eraser') return
    const { x, y } = clampBitmapPoint(bitmapPoint(event))
    const last = bitmapPaperPoints.at(-1)
    if (!last) {
      // No stroke yet (should not happen after begin): start one atomically.
      bitmapPaperPoints = [{ x, y }]
      bitmapStrokeStamps = 1
      bitmapStrokeCapped = false
      try {
        paintBitmapStrokeSegment(context, { x, y }, { x, y })
      } catch (error) {
        if (error instanceof RangeError) {
          if (bitmapPreviewBase) restoreBitmapPreviewBase()
          bitmapPaperPoints = []
          bitmapStrokeStamps = 0
          bitmapStrokeCapped = false
          status = 'Bitmap stroke too long — kept original'
          return
        }
        throw error
      }
      return
    }
    if (last.x === x && last.y === y) return
    // Latched cap: refuse further points without O(N^2) replay, keep earlier
    // pixels and the cap status (no frozen UI, no history yet).
    if (bitmapStrokeCapped) return
    const refusal = bitmapStrokeRefusal(last, { x, y })
    if (refusal) {
      bitmapStrokeCapped = true
      status = 'Bitmap stroke too long — earlier pixels kept'
      return
    }
    const incoming = Math.max(Math.abs(Math.trunc(x) - Math.trunc(last.x)), Math.abs(Math.trunc(y) - Math.trunc(last.y))) + 1
    // Reference parity (`brush-tool.js` event state): `handleMouseDown` draws
    // the down point, then every drag/up runs inclusive
    // `forEachLinePoint(lastPoint, point, draw)` — so the down point and each
    // joint is stamped twice. Keep the synchronous dot and paint every segment
    // purely incrementally (no base restore), preserving that doubling exactly.
    // Opaque product stamps (hex colors, no per-stamp alpha) make the extra
    // stamp idempotent; the count stays additive (`stamps + incoming`).
    bitmapPaperPoints = [...bitmapPaperPoints, { x, y }]
    const previousStamps = bitmapStrokeStamps
    bitmapStrokeStamps = bitmapStrokeStamps + incoming
    // Incremental: stamp only the new segment (O(segment)), never the whole
    // list (O(N^2)). Atomic per segment, so a refusal paints nothing.
    try {
      paintBitmapStrokeSegment(context, last, { x, y })
    } catch (error) {
      if (error instanceof RangeError) {
        // Roll back the refused point; earlier pixels stay intact (no base
        // restore happened, so nothing needs repainting).
        bitmapPaperPoints = bitmapPaperPoints.slice(0, -1)
        bitmapStrokeStamps = previousStamps
        bitmapStrokeCapped = true
        status = 'Bitmap stroke too long — earlier pixels kept'
        return
      }
      throw error
    }
  }

  // Bitmap rect/oval commit gate (reference bit-tools parity, rect/oval only):
  // Shift squares first via `resolveShapeRect`, then the squared canvas-px
  // box is measured as a Paper area against the strict `2 / paperZoom`
  // budget (`shouldCommitBitmapShapeDrag`). Preview and commit share this
  // gate so a shown outline always commits. Bitmap line keeps the legacy
  // `isShapeDrag` gate and never calls this. Rect/oval stay armed after
  // commit (reference mode retention); only the line tool flips to `select`.
  function bitmapRectOvalShouldCommit(
    start: { x: number; y: number },
    end: { x: number; y: number },
    event: MouseEvent,
  ): boolean {
    const storedResolution = storedBitmapResolutionOf(selectedTarget, selectedTarget?.currentCostume ?? 0)
    return shouldCommitBitmapShapeDrag(start, end, readShapeModifiers(event), storedResolution, costumeViewportScale)
  }

  async function endBitmapPaint(event: MouseEvent) {
    // pointercancel / lostpointercapture is a cancel, not a commit: restore
    // the pre-stroke snapshot without history (vector parity: the vector
    // brush/eraser/shape/marquee cancel discards the draft). Committing the
    // partial stroke here would strand unwanted pixels with one Undo entry.
    const endType = (event as PointerEvent | MouseEvent | undefined)?.type
    // Pending transform drag (staged rect/oval move): pointercancel /
    // lostpointercapture / out-of-order restores the drag-start box (the
    // prior pending overlay) with no history and no VM write; pointerup
    // keeps the moved shape staged for later commit.
    if (bitmapPendingMoveDrag && (bitmapTool === 'rect' || bitmapTool === 'oval')) {
      if (endType === 'pointercancel' || endType === 'lostpointercapture') {
        cancelBitmapPendingTransformDrag(bitmapPendingMoveDrag, 'Bitmap move')
        return
      }
      endBitmapPendingMove(event as unknown as PointerEvent)
      return
    }
    // Pending rotate drag (staged rect/oval free rotation): pointercancel /
    // lostpointercapture / out-of-order reverts to the drag-start rotation
    // (the prior pending overlay) with no history and no VM write; pointerup
    // keeps the rotated shape staged for later commit.
    if (bitmapPendingRotateDrag && (bitmapTool === 'rect' || bitmapTool === 'oval')) {
      if (endType === 'pointercancel' || endType === 'lostpointercapture') {
        cancelBitmapPendingTransformDrag(bitmapPendingRotateDrag, 'Bitmap rotate')
        return
      }
      endBitmapPendingRotate(event as unknown as PointerEvent)
      return
    }
    if (endType === 'pointercancel' || endType === 'lostpointercapture') {
      // Pending drafts cancel history-free (leave-pending): the settled
      // pending (if any) is untouched, only the in-progress drag is dropped.
      try {
        const pendingSession = ensureBitmapPendingController()?.get()
        if (bitmapPendingPainting && pendingSession && (bitmapTool === 'rect' || bitmapTool === 'oval')) {
          pendingSession.cancelDraft()
          bitmapPendingPainting = false
          isBitmapPainting = false
          bitmapStart = undefined
          bitmapStrokeOwner = undefined
          status = 'Bitmap edit cancelled'
          return
        }
      } catch {
        // Fall through to the legacy cancel below.
      }
      cancelBitmapStroke()
      return
    }
    // Pending parametric commit (rect/oval): stages `base + shape` with no
    // history; restyles/moves stay history-free until deselect/switch/save.
    if (bitmapPendingPainting && (bitmapTool === 'rect' || bitmapTool === 'oval')) {
      bitmapPendingPainting = false
      isBitmapPainting = false
      const session = ensureBitmapPendingController()?.get()
      const startAt = bitmapStart
      bitmapStart = undefined
      bitmapStrokeOwner = undefined
      if (!session || !startAt) {
        bitmapPendingPainting = false
        return
      }
      try {
        const at = clampBitmapPoint(bitmapPoint(event))
        const modifiers = readShapeModifiers(event as unknown as { shiftKey?: boolean; altKey?: boolean })
        const result = await session.pointerUp(at, modifiers)
        if (!result.ok) {
          status = (result as { reason?: string }).reason === 'owner-mismatch'
            ? 'live canvas left untouched (draft owner changed before stage; reloader owns pixels)'
            : `Bitmap shape not staged (${(result as { reason?: string }).reason ?? 'refused'})`;
          return
        }
        if (result.kind === 'unchanged' || result.kind === 'nothing-pending') {
          status = 'Bitmap edit: no change'
          return
        }
        // Staged: the session repainted `base + shape` exactly once and
        // published the selection via onSelection. Keep the explicit saved
        // marker (no history yet) so retention tests observe continuity.
        status = 'Bitmap edit saved'
        return
      } catch {
        status = 'Bitmap shape not staged (internal error); original preserved'
        return
      }
    }
    if (bitmapStrokeOwner) {
      const cur = currentBitmapIdentity()
      if (!cur || cur.targetId !== bitmapStrokeOwner.targetId || cur.index !== bitmapStrokeOwner.index || bitmapStrokeOwner.loadSerial !== bitmapCanvasReloadSerial || Boolean(bitmapWorkspacePending)) {
        if (bitmapMoveDrag && bitmapCanvas) {
          const dragOwnerMatches = selectedTarget && bitmapMoveDrag.targetName !== undefined && selectedTarget.name === bitmapMoveDrag.targetName && (selectedTarget.currentCostume ?? 0) === bitmapMoveDrag.costumeIndex && cur && cur.index === bitmapMoveDrag.costumeIndex
          if (dragOwnerMatches) {
            const committed = bitmapMoveDrag.session.committed
            bitmapCanvas.getContext('2d')?.putImageData(floatingImageToImageData(committed), 0, 0)
            bitmapSelection = { ...bitmapMoveDrag.startSelection }
          }
        } else if (bitmapPreviewBase) {
          restoreBitmapPreviewBase()
        }
        bitmapMoveDrag = undefined
        isBitmapPainting = false
        bitmapStart = undefined
        bitmapPreviewBase = undefined
        bitmapPaperPoints = []
          bitmapStrokeStamps = 0
          bitmapStrokeCapped = false
        bitmapShapePreviewDrawn = false
        bitmapStrokeOwner = undefined
        refuseStaleBitmapWorkspace('Bitmap paint')
        return
      }
    }
    if (bitmapMoveDrag) {
      const drag = bitmapMoveDrag
      paintBitmap(event)
      bitmapMoveDrag = undefined
      isBitmapPainting = false
      bitmapStart = undefined
      if (!drag.moved) {
        // Click without movement: the canvas still shows the committed
        // snapshot, so restore it verbatim and record no history entry
        // (clicks and sub-pixel jitter stay undo-clean, like the vector
        // drag path).
        const committed = drag.session.committed
        bitmapCanvas?.getContext('2d')?.putImageData(floatingImageToImageData(committed), 0, 0)
        bitmapSelection = { ...drag.startSelection }
        bitmapStrokeOwner = undefined
        status = 'Bitmap selection kept'
        return
      }
      // Exactly one history entry per committed drag; the preview pixels are
      // already on the canvas.
      bitmapStrokeOwner = undefined
      await saveBitmapCostume(drag.copy ? 'Bitmap selection duplicated' : 'Bitmap selection moved')
      status = drag.copy ? 'Bitmap selection duplicated' : 'Bitmap selection moved'
      return
    }
    if (!isBitmapPainting || !bitmapCanvas || !bitmapStart) {
      isBitmapPainting = false
      return
    }
    const isShape = bitmapTool === 'line' || bitmapTool === 'rect' || bitmapTool === 'oval'
    const isBitmapRectOval = bitmapTool === 'rect' || bitmapTool === 'oval'
    // Line keeps the legacy tap gate untouched; rect/oval use the Paper-area
    // gate (Shift squared first, axis-zero discards, strict `<` boundary).
    const shapeDragged =
      isShape &&
      (isBitmapRectOval
        ? bitmapRectOvalShouldCommit(bitmapStart, clampBitmapPoint(bitmapPoint(event)), event)
        : isShapeDrag(bitmapStart, clampBitmapPoint(bitmapPoint(event))))
    // Transparent paint that changes no pixels must not record history. Bitmap
    // rect/oval are exclusive with a single fill-sourced color (reference
    // `styleRect`/`styleOval` + `bitBrushSize` parity): filled and outlined
    // both care only about the fill (solid transparent, or a gradient with
    // both ends transparent, paints nothing) and outlined additionally needs
    // a positive shared brush size. Brush/line keep the previous shared
    // no-op rule (a transparent fill stamp paints nothing); a transparent
    // brush erases via destination-out, so it stays out of this guard and
    // always commits.
    const shapeMode = normalizeBitmapShapeMode(bitmapShapeMode)
    const shapeNoop = (bitmapTool === 'rect' || bitmapTool === 'oval')
      ? resolveBitmapShapePaint(shapeMode, { fillTransparent, secondaryTransparent, strokeTransparent }, paintGradient, brushSize).noop
      : false
    const transparentNoop = bitmapTool === 'line'
      ? isBitmapPaintNoop(bitmapTool, { fillTransparent, secondaryTransparent, strokeTransparent }, paintGradient)
      : (bitmapTool === 'rect' || bitmapTool === 'oval') ? shapeNoop : false
    let shouldCommit = bitmapTool !== 'select' && (!isShape || shapeDragged) && !transparentNoop
    if (transparentNoop) {
      if (bitmapShapePreviewDrawn) restoreBitmapPreviewBase()
      bitmapShapePreviewDrawn = false
      status = 'Bitmap edit: no change'
    }
    if (isShape && !shapeDragged && bitmapShapePreviewDrawn) restoreBitmapPreviewBase()
    if (bitmapTool === 'select') {
      restoreBitmapPreviewBase()
      const point = clampBitmapPoint(bitmapPoint(event))
      const moved = point.x !== bitmapStart.x || point.y !== bitmapStart.y
      if (!moved) {
        // Mirror scratch-paint's SelectionBoxTool: a click without a drag
        // clears the selection instead of selecting an opaque region.
        if (!event.shiftKey && !event.metaKey && !event.ctrlKey) bitmapSelection = undefined
      } else {
        bitmapSelection = trimBitmapSelection(bitmapMarqueeRect(bitmapStart, point))
      }
    }
    if (bitmapTool === 'brush' || bitmapTool === 'eraser') {
      const point = clampBitmapPoint(bitmapPoint(event))
      const lastPoint = bitmapPaperPoints.at(-1)
      // Reference parity (`brush-tool.js` `handleMouseUp`): the release always
      // runs inclusive `forEachLinePoint(lastPoint, point, draw)` — even when
      // the release lands exactly on the last point (single extra stamp) or
      // arrives with no prior moves (tap down+up = dot + one more stamp).
      // Opaque product stamps make the extra stamp idempotent.
      if (lastPoint) {
        // Incremental commit: append only when the cap budget allows, then
        // stamp only the new segment (no O(N^2) full replay). Earlier pixels
        // are already on the canvas, so a refusal keeps them with an honest
        // status and still commits them below. No base restore: the release
        // segment doubles its start joint exactly like the reference.
        if (!bitmapStrokeCapped) {
          const refusal = bitmapStrokeRefusal(lastPoint, point)
          if (refusal) {
            bitmapStrokeCapped = true
            status = 'Bitmap stroke too long — earlier pixels kept'
          } else {
            const incoming = Math.max(Math.abs(Math.trunc(point.x) - Math.trunc(lastPoint.x)), Math.abs(Math.trunc(point.y) - Math.trunc(lastPoint.y))) + 1
            bitmapPaperPoints = [...bitmapPaperPoints, point]
            const previousStamps = bitmapStrokeStamps
            bitmapStrokeStamps = bitmapStrokeStamps + incoming
            const context = bitmapCanvas?.getContext('2d')
            if (context) {
              try {
                paintBitmapStrokeSegment(context, lastPoint, point)
              } catch (error) {
                if (error instanceof RangeError) {
                  bitmapPaperPoints = bitmapPaperPoints.slice(0, -1)
                  bitmapStrokeStamps = previousStamps
                  bitmapStrokeCapped = true
                  status = 'Bitmap stroke too long — earlier pixels kept'
                } else {
                  throw error
                }
              }
            }
          }
        }
      } else {
        bitmapPaperPoints = [point]
        bitmapStrokeStamps = 1
      }
      await ensureBitmapPaperScope()
      // Empty-stroke fallback: the release always appends above, so a
      // single-point list here means the init dot was refused (or the stroke
      // was capped) and the canvas already shows the kept pixels — replaying
      // from the base would only repaint them. Longer incremental strokes
      // already sit on the canvas, so no O(N^2) replay.
      if (bitmapPaperPoints.length <= 1 && !bitmapStrokeCapped) {
        drawBitmapPaperStroke()
      }
    }
    if (shapeDragged && !transparentNoop) {
      const shapeOk = (() => {
        try {
          drawBitmapShape(event, true)
          return true
        } catch (error) {
          if (error instanceof RangeError) {
            if (bitmapPreviewBase) restoreBitmapPreviewBase()
            bitmapShapePreviewDrawn = false
            status = 'Bitmap line too long — kept original'
            return false
          }
          throw error
        }
      })()
      if (!shapeOk) {
        shouldCommit = false
      } else {
      const end = clampBitmapPoint(bitmapPoint(event))
      const modifiers = readShapeModifiers(event)
      const resolved = bitmapTool === 'rect' || bitmapTool === 'oval'
        ? resolveShapeRect(bitmapStart, end, modifiers)
        : { x: Math.min(bitmapStart.x, end.x), y: Math.min(bitmapStart.y, end.y), width: Math.abs(end.x - bitmapStart.x), height: Math.abs(end.y - bitmapStart.y) }
      // The line stamp extends ceil(diameter / 2) past the endpoints, so its
      // selection margin follows the shared brush size; rect/oval keep an
      // exclusive-mode margin (filled ends at the box, outlined extends half
      // the shared brush size past it).
      const padding = bitmapTool === 'line'
        ? Math.ceil(Math.max(1, Math.trunc(brushSize)) / 2) + 1
        : resolveBitmapShapeSelectionPadding(shapeMode, brushSize)
      bitmapSelection = bitmapRect(
        { x: resolved.x - padding, y: resolved.y - padding },
        { x: resolved.x + resolved.width + padding, y: resolved.y + resolved.height + padding },
      )
      // Reference parity: rect/oval stay armed after commit (the new shape
      // stays selected under the same tool, like bit-rect/oval-mode.jsx which
      // never dispatch changeMode on commit). The line tool keeps the
      // historical flip to select (out of scope for this parity).
      if (bitmapTool === 'line') bitmapTool = 'select'
      }
    }
    const strokeWasCapped = bitmapStrokeCapped
    const lineWasRefused = shapeDragged && !transparentNoop && !shouldCommit && bitmapTool === 'line'
    isBitmapPainting = false
    bitmapStart = undefined
    bitmapPreviewBase = undefined
    bitmapPaperPoints = []
          bitmapStrokeStamps = 0
          bitmapStrokeCapped = false
    bitmapStrokeOwner = undefined
    // Status preservation: cap/line refusals already set an honest status;
    // never overwrite it with a generic selection/saved message. Snapshot /
    // history stay consistent: capped strokes still commit earlier pixels
    // (one entry), refused lines commit nothing.
    if (lineWasRefused) {
      // Keep 'Bitmap line too long — kept original' (no selection overwrite).
    } else if (strokeWasCapped) {
      if (shouldCommit) await saveBitmapCostume('Bitmap stroke too long — earlier pixels saved')
      // `saveBitmapCostume` sets the same truncation status on success; on
      // refusal (stale/oversize) it already reports honestly, so only ensure
      // the truncation note when the save left a generic message.
      if (status === 'Bitmap edit saved') status = 'Bitmap stroke too long — earlier pixels saved'
      else if (status !== 'Bitmap stroke too long — earlier pixels saved' && !status.includes('cancelled') && !status.includes('original kept') && !status.includes('too large')) {
        status = 'Bitmap stroke too long — earlier pixels saved'
      }
    } else {
      if (bitmapSelection) status = `Selected ${bitmapSelection.width} x ${bitmapSelection.height}`
      if (shouldCommit) await saveBitmapCostume('Bitmap edit saved')
    }
  }

  // Bitmap selection handles stay usable while a shape tool is retained:
  // after a rect/oval commit the tool (not `select`) owns the selection, and
  // the floating move/scale/rotate sessions are tool-agnostic raster
  // operations. The line tool is excluded (it still flips to `select`).
  function bitmapSelectionHandlesAllowed(): boolean {
    return bitmapTool === 'select' || bitmapTool === 'rect' || bitmapTool === 'oval'
  }

  // 8-handle scale drag for the bitmap selection. The pointer capture and
  // canvas mapping mirror the vector handle path: the button captures the
  // pointer, client coords map through the canvas bounding rect (so viewport
  // zoom/pan stay exact), and each move re-scales from the frozen `original`
  // patch with the diagonal fixed point pinned (Alt pins the center, Shift
  // frees a corner handle, edges scale one axis, crossing the fixed point
  // mirrors). Previews with no visible change keep the last frame; Esc
  // restores the committed snapshot via `clearCostumeSelection` without
  // history.
  function beginBitmapFloatingScale(event: PointerEvent, handle: BitmapFloatingScaleHandle = 'se') {
    // Pending staged rect/oval owns the handles: parametric `session.retarget`
    // (frozen box, no history, no VM, no `saveBitmapCostume`). The legacy
    // floating raster path is never used while staged.
    if (BITMAP_PENDING_UI_ENABLED && (bitmapTool === 'rect' || bitmapTool === 'oval')) {
      try {
        const pendingForScale = ensureBitmapPendingController()?.get()
        if (pendingForScale && pendingForScale.snapshot().hasPending) {
          startBitmapPendingScale(event, handle)
          return
        }
      } catch {
        // Fall through to the floating path only when the session is
        // unavailable; never silently drop a staged pending.
      }
      // Enabled but nothing staged and handles visible? The outline is the
      // pending outline; without a pending there is no scale target.
      if (BITMAP_PENDING_UI_ENABLED) return
    }
    if (selectedTarget) {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        refuseStaleBitmapWorkspace('Bitmap scale')
        return
      }
    }
    const context = bitmapCanvas?.getContext('2d')
    const validHandle: BitmapFloatingScaleHandle =
      handle === 'nw' || handle === 'n' || handle === 'ne' || handle === 'e' ||
      handle === 'se' || handle === 's' || handle === 'sw' || handle === 'w'
        ? handle
        : 'se'
    if (
      costumeEditMode !== 'bitmap' || !bitmapSelectionHandlesAllowed() || eyedropperActive ||
      !context || !bitmapCanvas || !bitmapSelection || bitmapScaleDrag || bitmapMoveDrag || bitmapRotateDrag
    ) {
      return
    }
    event.preventDefault()
    try {
      ;(event.currentTarget as Element | null)?.setPointerCapture?.(event.pointerId)
    } catch {
      // Pointer capture is best-effort; the drag still tracks by pointer id.
    }
    const live = context.getImageData(0, 0, bitmapCanvas.width, bitmapCanvas.height)
    const session = beginBitmapFloatingSession(live, bitmapSelection)
    if (!session) return
    bitmapScaleDrag = {
      session,
      original: {
        width: session.patch.width,
        height: session.patch.height,
        data: new Uint8ClampedArray(session.patch.data),
      },
      handle: validHandle,
      pointerId: event.pointerId,
      moved: false,
    }
    status = 'Scaling bitmap selection'
  }

  function moveBitmapFloatingScale(event: PointerEvent) {
    // Pending scale drag owns the move while staged (parametric retarget).
    if (bitmapPendingScaleDrag) {
      moveBitmapPendingScale(event)
      return
    }
    const drag = bitmapScaleDrag
    const context = bitmapCanvas?.getContext('2d')
    if (!drag || !context || !bitmapCanvas || event.pointerId !== drag.pointerId) return
    const rect = bitmapCanvas.getBoundingClientRect()
    if (!(rect.width > 0) || !(rect.height > 0)) return
    const pointerX = ((event.clientX - rect.left) / rect.width) * bitmapCanvas.width
    const pointerY = ((event.clientY - rect.top) / rect.height) * bitmapCanvas.height
    const resolved = resolveBitmapFloatingScaleForHandle(drag.session, drag.handle, pointerX, pointerY, {
      shiftKey: event.shiftKey === true,
      altKey: event.altKey === true,
    })
    if (!resolved) return
    // Absolute (not incremental): restart from the frozen patch every move.
    drag.session.patch = {
      width: drag.original.width,
      height: drag.original.height,
      data: new Uint8ClampedArray(drag.original.data),
    }
    const scaled = scaleBitmapFloatingSession(drag.session, resolved.scaleX, resolved.scaleY)
    if (!scaled.changed) return
    const preview = renderBitmapFloatingSession(drag.session, resolved.destX, resolved.destY)
    if (!preview.changed || !preview.placedRect) return
    context.putImageData(floatingImageToImageData(preview.image), 0, 0)
    bitmapSelection = {
      x: resolved.destX,
      y: resolved.destY,
      width: drag.session.patch.width,
      height: drag.session.patch.height,
    }
    drag.moved = true
    status = 'Scaling bitmap selection'
  }

  async function endBitmapFloatingScale(event: PointerEvent) {
    // Pending scale drag: pointerup keeps the staged shape (no commit);
    // pointercancel/lostpointercapture reverts to the drag-start box.
    if (bitmapPendingScaleDrag) {
      endBitmapPendingScale(event)
      return
    }
    const drag = bitmapScaleDrag
    if (!drag || event.pointerId !== drag.pointerId) return
    // pointercancel / lostpointercapture is a cancel, not a commit: restore
    // the committed snapshot without history (vector parity).
    if (event.type === 'pointercancel' || event.type === 'lostpointercapture') {
      cancelBitmapFloatingDrag(drag, 'Bitmap scale')
      return
    }
    if (selectedTarget) {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        bitmapScaleDrag = undefined
        const committed = drag.session.committed
        bitmapCanvas?.getContext('2d')?.putImageData(floatingImageToImageData(committed), 0, 0)
        bitmapSelection = { ...drag.session.sourceRect }
        refuseStaleBitmapWorkspace('Bitmap scale')
        return
      }
    }
    bitmapScaleDrag = undefined
    try {
      ;(event.currentTarget as Element | null)?.releasePointerCapture?.(event.pointerId)
    } catch {
      // Ignore release failures; the drag state is already cleared.
    }
    if (!drag.moved) {
      const committed = drag.session.committed
      bitmapCanvas?.getContext('2d')?.putImageData(floatingImageToImageData(committed), 0, 0)
      bitmapSelection = { ...drag.session.sourceRect }
      status = 'Bitmap selection kept'
      return
    }
    await saveBitmapCostume('Bitmap selection scaled')
    status = 'Bitmap selection scaled'
  }

  // Rotation-handle drag for the bitmap selection. The pointer capture and
  // canvas mapping mirror the scale path (button captures the pointer, client
  // coords map through the canvas bounding rect so viewport zoom/pan stay
  // exact). Each move resolves the absolute gesture delta from the drag-start
  // pointer around the selection center via `resolveRotationGesture` (Shift
  // snaps to 45 degrees, toggling mid-drag recomputes cleanly), restarts
  // from the frozen `original` patch through `rotateFloatingPatch`, and
  // re-centers the patch on the source rect. Snapped-to-zero / center-press
  // previews restore the committed snapshot and stay undo-clean; only a
  // pointerup with `moved === true` writes one history entry.
  function beginBitmapFloatingRotate(event: PointerEvent) {
    // Pending staged rect/oval owns the rotate action: the free-angle handle
    // drives the parametric `rotateTo` path (frozen base + single-pass
    // repaint, Shift snaps to 45 degrees, no history, no VM, no
    // `saveBitmapCostume`). The legacy floating raster path is never used
    // while staged (it would bake rotated pixels before commit).
    if (BITMAP_PENDING_UI_ENABLED && (bitmapTool === 'rect' || bitmapTool === 'oval')) {
      try {
        const pendingForHandle = ensureBitmapPendingController()?.get()
        if (pendingForHandle && pendingForHandle.snapshot().hasPending) {
          const started = startBitmapPendingRotate(event)
          if (!started && !bitmapPendingRotateDrag) {
            // The handle is genuinely unavailable right now (concurrent drag,
            // unsettled workspace, missing session): the pending stays
            // retained and no pixels change. An unsettled workspace keeps its
            // own specific stale message instead.
            let settled = true
            try {
              if (selectedTarget) {
                settled = isBitmapWorkspaceSettledFor(stableTargetId(selectedTarget), selectedTarget.currentCostume ?? 0)
              }
            } catch {
              settled = false
            }
            if (settled) status = 'Bitmap rotate handle unavailable while a shape is staged (pending retained)'
          }
          return
        }
      } catch {
        // Fall through to the floating path only when the check itself fails.
      }
      if (BITMAP_PENDING_UI_ENABLED) {
        // Enabled but nothing staged: handles belong to the pending outline,
        // so without a pending there is no rotate target on this tool.
        return
      }
    }
    if (selectedTarget) {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        refuseStaleBitmapWorkspace('Bitmap rotate')
        return
      }
    }
    const context = bitmapCanvas?.getContext('2d')
    if (
      costumeEditMode !== 'bitmap' || !bitmapSelectionHandlesAllowed() || eyedropperActive ||
      !context || !bitmapCanvas || !bitmapSelection || bitmapRotateDrag || bitmapScaleDrag || bitmapMoveDrag
    ) {
      return
    }
    event.preventDefault()
    try {
      ;(event.currentTarget as Element | null)?.setPointerCapture?.(event.pointerId)
    } catch {
      // Pointer capture is best-effort; the drag still tracks by pointer id.
    }
    const live = context.getImageData(0, 0, bitmapCanvas.width, bitmapCanvas.height)
    const session = beginBitmapFloatingSession(live, bitmapSelection)
    if (!session) return
    const rect = bitmapCanvas.getBoundingClientRect()
    if (!(rect.width > 0) || !(rect.height > 0)) return
    const start = {
      x: ((event.clientX - rect.left) / rect.width) * bitmapCanvas.width,
      y: ((event.clientY - rect.top) / rect.height) * bitmapCanvas.height,
    }
    const source = session.sourceRect
    bitmapRotateDrag = {
      session,
      original: {
        width: session.patch.width,
        height: session.patch.height,
        data: new Uint8ClampedArray(session.patch.data),
      },
      center: { x: source.x + source.width / 2, y: source.y + source.height / 2 },
      start,
      pointerId: event.pointerId,
      moved: false,
    }
    status = 'Rotating bitmap selection'
  }

  function moveBitmapFloatingRotate(event: PointerEvent) {
    // Pending rotate drag owns the move while staged (parametric rotateTo).
    if (bitmapPendingRotateDrag) {
      moveBitmapPendingRotate(event)
      return
    }
    const drag = bitmapRotateDrag
    const context = bitmapCanvas?.getContext('2d')
    if (!drag || !context || !bitmapCanvas || event.pointerId !== drag.pointerId) return
    const rect = bitmapCanvas.getBoundingClientRect()
    if (!(rect.width > 0) || !(rect.height > 0)) return
    const current = {
      x: ((event.clientX - rect.left) / rect.width) * bitmapCanvas.width,
      y: ((event.clientY - rect.top) / rect.height) * bitmapCanvas.height,
