        context.putImageData(floatingImageToImageData(drag.session.committed), 0, 0)
        bitmapSelection = { ...drag.session.sourceRect }
        drag.moved = false
        status = 'Rotating bitmap selection'
      }
      return
    }
    // Absolute (not incremental): restart from the frozen patch every move.
    const original = {
      width: drag.original.width,
      height: drag.original.height,
      data: new Uint8ClampedArray(drag.original.data),
    }
    const rotated = rotateBitmapFloatingSessionArbitrary(drag.session, original, gesture.appliedDeltaDegrees)
    if (!rotated.changed) return
    const dest = centeredBitmapFloatingDest(drag.session.sourceRect, drag.session.patch.width, drag.session.patch.height)
    const preview = renderBitmapFloatingSession(drag.session, dest.x, dest.y)
    if (!preview.changed) return
    context.putImageData(floatingImageToImageData(preview.image), 0, 0)
    bitmapSelection = {
      x: dest.x,
      y: dest.y,
      width: drag.session.patch.width,
      height: drag.session.patch.height,
    }
    drag.moved = true
    status = gesture.snapped
      ? `Rotating bitmap selection (${Math.round(gesture.appliedDeltaDegrees)}°)`
      : 'Rotating bitmap selection'
  }

  async function endBitmapFloatingRotate(event: PointerEvent) {
    // Pending rotate drag: pointerup keeps the staged shape (no commit);
    // pointercancel/lostpointercapture reverts to the drag-start rotation.
    if (bitmapPendingRotateDrag) {
      endBitmapPendingRotate(event)
      return
    }
    const drag = bitmapRotateDrag
    if (!drag || event.pointerId !== drag.pointerId) return
    // pointercancel / lostpointercapture is a cancel, not a commit: restore
    // the committed snapshot without history (vector parity).
    if (event.type === 'pointercancel' || event.type === 'lostpointercapture') {
      cancelBitmapFloatingDrag(drag, 'Bitmap rotate')
      return
    }
    if (selectedTarget) {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        bitmapRotateDrag = undefined
        const committed = drag.session.committed
        bitmapCanvas?.getContext('2d')?.putImageData(floatingImageToImageData(committed), 0, 0)
        bitmapSelection = { ...drag.session.sourceRect }
        refuseStaleBitmapWorkspace('Bitmap rotate')
        return
      }
    }
    bitmapRotateDrag = undefined
    try {
      ;(event.currentTarget as Element | null)?.releasePointerCapture?.(event.pointerId)
    } catch {
      // Ignore release failures; the drag state is already cleared.
    }
    if (!drag.moved) {
      const committed = drag.session.committed
      bitmapCanvas?.getContext('2d')?.putImageData(floatingImageToImageData(committed), 0, 0)
      bitmapSelection = { ...drag.session.sourceRect }
      status = 'Bitmap selection kept'
      return
    }
    await saveBitmapCostume('Bitmap selection rotated')
    status = 'Bitmap selection rotated'
  }

  function bitmapPoint(event: MouseEvent) {
    const rect = bitmapCanvas.getBoundingClientRect()
    return {
      x: ((event.clientX - rect.left) / rect.width) * bitmapCanvas.width,
      y: ((event.clientY - rect.top) / rect.height) * bitmapCanvas.height,
    }
  }

  function pointInBitmapWorkspace(point: { x: number; y: number }) {
    return Boolean(bitmapCanvas && point.x >= 0 && point.y >= 0 && point.x <= bitmapCanvas.width && point.y <= bitmapCanvas.height)
  }

  function clampBitmapPoint(point: { x: number; y: number }) {
    if (!bitmapCanvas) return point
    return {
      x: Math.max(0, Math.min(bitmapCanvas.width, point.x)),
      y: Math.max(0, Math.min(bitmapCanvas.height, point.y)),
    }
  }

  function restoreBitmapPreviewBase() {
    const context = bitmapCanvas?.getContext('2d')
    if (context && bitmapPreviewBase) context.putImageData(bitmapPreviewBase, 0, 0)
  }

  // Fail-closed stroke budget (O(1) per move): mirrors the helper caps
  // (`BITMAP_BRUSH_MAX_POINTS` / `_SEGMENT_STEPS` / `_STAMPS`) arithmetically
  // so the Editor refuses BEFORE mutating pixels. Clamped points always
  // satisfy the 65535 segment cap on feasible canvases; anything larger is
  // outside every valid canvas. Returns null when feasible, else a reason.
  function bitmapStrokeRefusal(last: { x: number; y: number }, next: { x: number; y: number }): string | null {
    if (bitmapPaperPoints.length + 1 > BITMAP_BRUSH_MAX_POINTS) {
      return `too many points (fail-closed): ${bitmapPaperPoints.length + 1}`
    }
    const deltaX = Math.abs(Math.trunc(next.x) - Math.trunc(last.x))
    const deltaY = Math.abs(Math.trunc(next.y) - Math.trunc(last.y))
    if (deltaX > BITMAP_BRUSH_MAX_SEGMENT_STEPS || deltaY > BITMAP_BRUSH_MAX_SEGMENT_STEPS) {
      return `segment too long (fail-closed): dx=${deltaX} dy=${deltaY}`
    }
    const incoming = Math.max(deltaX, deltaY) + 1
    // Reference parity: the down dot stays painted and every later segment is
    // inclusive, so each joint (including the down point) is stamped twice.
    // The budget is therefore always additive (`stamps + incoming`), matching
    // the reference event-state total (dot + inclusive segments + inclusive
    // release), not the full-replay total (which singles the down point).
    const projected = bitmapStrokeStamps + incoming
    if (projected > BITMAP_BRUSH_MAX_STAMPS) {
      return `stroke too long (fail-closed): >${BITMAP_BRUSH_MAX_STAMPS} stamps`
    }
    return null
  }

  function resetBitmapStrokeBudget() {
    bitmapStrokeStamps = 0
    bitmapStrokeCapped = false
  }

  // Incremental single-segment paint (O(segment) per move, O(total) per
  // stroke). Pre-validated by `bitmapStrokeRefusal`; the segment helpers are
  // themselves atomic (validate before the first drawImage), so a refusal
  // paints nothing and earlier pixels stay intact (no partial mutation).
  function paintBitmapStrokeSegment(
    context: CanvasRenderingContext2D,
    prev: { x: number; y: number },
    next: { x: number; y: number },
  ): void {
    if (bitmapTool === 'eraser') {
      drawBitmapEraserSegment(context, prev, next, bitmapEraserSize)
      return
    }
    if (fillTransparent) {
      drawBitmapEraserSegment(context, prev, next, brushSize)
      return
    }
    drawBitmapBrushSegment(context, prev, next, brushSize, paintColor)
  }

  // Bitmap stroke cancel (pointercancel / lostpointercapture / Escape): drops
  // the in-progress brush/eraser/shape/select stroke and restores the
  // `bitmapPreviewBase` snapshot taken in `beginBitmapPaint`, without writing
  // history or the VM. Vector parity: the vector brush/eraser/shape/marquee
  // cancel path discards the local draft; bitmap mirrors it by restoring the
  // pre-stroke pixels. The prior `bitmapSelection` is preserved (a select
  // marquee never mutates it until commit), the tool stays armed, and the
  // stroke owner token is cleared. When the stroke owner no longer matches
  // the live workspace (target/costume switch or newer load in flight) the
  // canvas already shows another asset, so state is cleared without touching
  // pixels and the switch path reports the stale state.
  function cancelBitmapStroke(): boolean {
    // Pending transform drag cancel (pointercancel / lostpointercapture /
    // Escape mid-drag): restores the drag-start box through the session (the
    // settled pending stays staged, no history, no VM write).
    if (bitmapPendingTransformDragActive()) {
      cancelActiveBitmapPendingTransformDrag()
      return true
    }
    // Pending draft cancel (pointercancel/lostpointercapture/Escape
    // mid-drag): drops the in-progress drag history-free; the settled
    // pending (if any) is untouched.
    if (bitmapPendingPainting) {
      try {
        ensureBitmapPendingController()?.get()?.cancelDraft()
      } catch {
        // Best effort only.
      }
      bitmapPendingPainting = false
      isBitmapPainting = false
      bitmapStart = undefined
      bitmapStrokeOwner = undefined
      status = 'Bitmap edit cancelled'
      return true
    }
    if (bitmapMoveDrag) {
      const drag = bitmapMoveDrag
      if (bitmapStrokeOwner) {
        const cur = currentBitmapIdentity()
        if (!cur || cur.targetId !== bitmapStrokeOwner.targetId || cur.index !== bitmapStrokeOwner.index || bitmapStrokeOwner.loadSerial !== bitmapCanvasReloadSerial || Boolean(bitmapWorkspacePending)) {
          bitmapMoveDrag = undefined
          isBitmapPainting = false
          bitmapStart = undefined
          bitmapPreviewBase = undefined
          bitmapPaperPoints = []
          bitmapStrokeStamps = 0
          bitmapStrokeCapped = false
          bitmapShapePreviewDrawn = false
          bitmapStrokeOwner = undefined
          refuseStaleBitmapWorkspace('Bitmap paint')
          return true
        }
      }
      if (bitmapCanvas) {
        bitmapCanvas.getContext('2d')?.putImageData(floatingImageToImageData(drag.session.committed), 0, 0)
        bitmapSelection = { ...drag.startSelection }
      }
      bitmapMoveDrag = undefined
      isBitmapPainting = false
      bitmapStart = undefined
      bitmapPreviewBase = undefined
      bitmapPaperPoints = []
          bitmapStrokeStamps = 0
          bitmapStrokeCapped = false
      bitmapShapePreviewDrawn = false
      bitmapStrokeOwner = undefined
      status = 'Bitmap edit cancelled'
      return true
    }
    if (!isBitmapPainting) return false
    if (bitmapStrokeOwner) {
      const cur = currentBitmapIdentity()
      if (!cur || cur.targetId !== bitmapStrokeOwner.targetId || cur.index !== bitmapStrokeOwner.index || bitmapStrokeOwner.loadSerial !== bitmapCanvasReloadSerial || Boolean(bitmapWorkspacePending)) {
        isBitmapPainting = false
        bitmapStart = undefined
        bitmapPreviewBase = undefined
        bitmapPaperPoints = []
          bitmapStrokeStamps = 0
          bitmapStrokeCapped = false
        bitmapShapePreviewDrawn = false
        bitmapStrokeOwner = undefined
        refuseStaleBitmapWorkspace('Bitmap paint')
        return true
      }
    }
    if (bitmapPreviewBase) restoreBitmapPreviewBase()
    isBitmapPainting = false
    bitmapStart = undefined
    bitmapPreviewBase = undefined
    bitmapPaperPoints = []
          bitmapStrokeStamps = 0
          bitmapStrokeCapped = false
    bitmapShapePreviewDrawn = false
    bitmapStrokeOwner = undefined
    status = 'Bitmap edit cancelled'
    return true
  }

  function cancelBitmapFloatingDrag(
    drag: { session: BitmapFloatingSession } | undefined,
    kind: 'Bitmap scale' | 'Bitmap rotate',
  ): boolean {
    if (!drag) return false
    if (selectedTarget) {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        if (drag === bitmapScaleDrag) bitmapScaleDrag = undefined
        if (drag === bitmapRotateDrag) bitmapRotateDrag = undefined
        refuseStaleBitmapWorkspace(kind)
        return true
      }
    }
    const committed = drag.session.committed
    bitmapCanvas?.getContext('2d')?.putImageData(floatingImageToImageData(committed), 0, 0)
    if (drag === bitmapScaleDrag) bitmapScaleDrag = undefined
    if (drag === bitmapRotateDrag) {
      bitmapRotateDrag = undefined
      bitmapSelection = { ...drag.session.sourceRect }
    }
    status = 'Bitmap edit cancelled'
    return true
  }

  function drawBitmapDraft(event: MouseEvent) {
    if (!bitmapStart) return
    if (bitmapTool === 'select') {
      restoreBitmapPreviewBase()
      const preview = bitmapMarqueeRect(bitmapStart, clampBitmapPoint(bitmapPoint(event)))
      if (preview.width > 0 && preview.height > 0) drawBitmapSelectionOutline(preview)
      return
    }
    if (bitmapShapePreviewDrawn) restoreBitmapPreviewBase()
    // Preview shares the commit gate exactly (rect/oval: Paper-area gate with
    // the live modifiers; line: legacy drag gate untouched).
    bitmapShapePreviewDrawn =
      bitmapTool === 'rect' || bitmapTool === 'oval'
        ? bitmapRectOvalShouldCommit(bitmapStart, clampBitmapPoint(bitmapPoint(event)), event)
        : isShapeDrag(bitmapStart, clampBitmapPoint(bitmapPoint(event)))
    if (bitmapShapePreviewDrawn) drawBitmapShape(event, false)
  }

  function drawBitmapSelectionOutline(rect: { x: number; y: number; width: number; height: number }) {
    const context = bitmapCanvas?.getContext('2d')
    if (!context) return
    context.save()
    context.strokeStyle = '#2563eb'
    context.lineWidth = 1
    context.setLineDash([5, 4])
    context.strokeRect(rect.x + 0.5, rect.y + 0.5, Math.max(1, rect.width - 1), Math.max(1, rect.height - 1))
    context.restore()
  }

  function drawBitmapShape(event: MouseEvent, fromPreviewBase = false) {
    const context = bitmapCanvas?.getContext('2d')
    if (!context || !bitmapStart) return
    if (fromPreviewBase && bitmapShapePreviewDrawn) restoreBitmapPreviewBase()
    const end = clampBitmapPoint(bitmapPoint(event))
    if (bitmapTool !== 'line' && bitmapTool !== 'rect' && bitmapTool !== 'oval') return
    if (bitmapTool === 'line') {
      // Bitmap straight line is a brush-stamp line, not a vector stroke:
      // single fill color with the shared brush size (matches the reference
      // line tool), so gradients and the outline width stay out of this path.
      // A transparent fill stamp paints nothing (transparent is `null`, not a
      // color), which endBitmapPaint treats as a no-op without history.
      // Fail-closed: pre-validate before painting so a refusal paints nothing;
      // on RangeError restore the preview base (undo the partial preview, if
      // any) and report without crashing or committing history. The helper
      // itself is atomic, but an earlier preview frame may already be visible.
      try {
        validateBitmapLine(bitmapStart, end)
      } catch (error) {
        if (error instanceof RangeError) {
          if (bitmapPreviewBase) restoreBitmapPreviewBase()
          bitmapShapePreviewDrawn = false
          status = 'Bitmap line too long — kept original'
          return
        }
        throw error
      }
      try {
        drawBitmapLine(context, bitmapStart, end, brushSize, fillTransparent ? 'rgba(0, 0, 0, 0)' : paintColor)
      } catch (error) {
        if (error instanceof RangeError) {
          if (bitmapPreviewBase) restoreBitmapPreviewBase()
          bitmapShapePreviewDrawn = false
          status = 'Bitmap line too long — kept original'
          return
        }
        throw error
      }
      return
    }
    // Bitmap rect/oval are exclusive with a single fill-sourced color
    // (reference `styleRect`/`styleOval` parity: Shift squares and Alt
    // centers via resolveShapeRect for both preview and commit). Filled paints
    // the interior with the fill style (gradient-aware); outlined strokes the
    // contour with the SAME fill style and the shared brush size
    // (`bitBrushSize`). The filled pass reuses the previous fill geometry
    // byte-for-byte (fill-only via a zero outline width); the outlined pass
    // reuses the previous stroke geometry alone, so neither mode paints the
    // old fill+outline stack.
    const rect = resolveShapeRect(bitmapStart, end, readShapeModifiers(event))
    const mode = normalizeBitmapShapeMode(bitmapShapeMode)
    if (mode === 'outlined') {
      context.strokeStyle = bitmapPaintStyle(context, rect.x, rect.y, rect.width, rect.height)
      paintBitmapRectOvalExclusive(
        context,
        bitmapTool,
        rect.x,
        rect.y,
        rect.width,
        rect.height,
        mode,
        { fillStyle: context.strokeStyle as string | CanvasGradient, strokeStyle: context.strokeStyle as string, lineWidth: brushSize },
      )
      return
    }
    context.fillStyle = bitmapPaintStyle(context, rect.x, rect.y, rect.width, rect.height)
    paintBitmapShape(context, bitmapTool, { x: rect.x, y: rect.y }, { x: rect.x + rect.width, y: rect.y + rect.height }, 0)
  }

  // Full-replay fallback (single-point init / commit repair only): restores
  // the preview base, then replays the whole point list. Atomic + fail-closed:
  // pre-validates before painting (helpers paint nothing on refusal), and on
  // `RangeError` restores the base again so no partial stamps remain, reports
  // without crashing, and latches the cap flag. Returns false on refusal.
  // Per-move painting does NOT use this (it would be O(N^2)); moves use the
  // incremental `paintBitmapStrokeSegment` path above.
  function drawBitmapPaperStroke(): boolean {
    const context = bitmapCanvas?.getContext('2d')
    if (!context || bitmapPaperPoints.length === 0) return true
    // Fail-closed gate before touching pixels (no partial mutation).
    try {
      if (bitmapTool === 'eraser') validateBitmapEraserStroke(bitmapPaperPoints)
      else if (fillTransparent) validateBitmapEraserStroke(bitmapPaperPoints)
      else validateBitmapBrushStroke(bitmapPaperPoints)
    } catch (error) {
      if (error instanceof RangeError) {
        if (bitmapPreviewBase) restoreBitmapPreviewBase()
        bitmapStrokeCapped = true
        status = 'Bitmap stroke too long — earlier pixels kept'
        return false
      }
      throw error
    }
    restoreBitmapPreviewBase()
    try {
      if (bitmapTool === 'eraser') {
        // scratch-paint stamps an eraser brush mark along a Bresenham line with
        // `destination-out` (square at small sizes, crisp circle above that),
        // using the eraser's own size.
        drawBitmapEraserStroke(context, bitmapPaperPoints, bitmapEraserSize)
        return true
      }
      // Bitmap brush: stamp a pre-rendered brush mark (square at diameters of
      // 5 or less, crisp filled circle above that) at every integer pixel along
      // the drag. The mark diameter is the integer brush size in canvas pixels.
      // A transparent fill erases with destination-out at the same brush size
      // (reference brush-tool.js draws a null-color brush with
      // destination-out), reusing the eraser stamp path.
      if (fillTransparent) {
        drawBitmapEraserStroke(context, bitmapPaperPoints, brushSize)
        return true
      }
      drawBitmapBrushStroke(context, bitmapPaperPoints, brushSize, paintColor)
      return true
    } catch (error) {
      if (error instanceof RangeError) {
        // Helpers are atomic (nothing painted), but an earlier preview frame
        // may already be visible: restore to leave no partial mutation.
        if (bitmapPreviewBase) restoreBitmapPreviewBase()
        bitmapStrokeCapped = true
        status = 'Bitmap stroke too long — earlier pixels kept'
        return false
      }
      throw error
    }
  }

  // Bitmap marquee quantization (select tool only): Paper-parity rounding of
  // normalized drag corners (`Math.round(edge + 0.5 / paperZoom)` in Paper
  // units, half-screen offset in canvas px) with no minimum size, so
  // fractional drags and sub-half-pixel jitter collapse to empty instead of
  // gaining an outward floor/ceil ring. Shape/text padding boxes keep
  // `bitmapRect` below.
  function bitmapMarqueeRect(start: { x: number; y: number }, end: { x: number; y: number }) {
    if (!bitmapCanvas) return { x: 0, y: 0, width: 0, height: 0 }
    const storedResolution = storedBitmapResolutionOf(selectedTarget, selectedTarget?.currentCostume ?? 0)
    const paperZoom = bitmapShapePaperZoom(costumeViewportScale, storedResolution)
    return quantizeBitmapMarqueeRect(start, end, bitmapCanvas.width, bitmapCanvas.height, paperZoom, storedResolution)
  }

  function bitmapRect(start: { x: number; y: number }, end: { x: number; y: number }) {
    const left = Math.max(0, Math.floor(Math.min(start.x, end.x)))
    const top = Math.max(0, Math.floor(Math.min(start.y, end.y)))
    const right = Math.min(bitmapCanvas.width, Math.ceil(Math.max(start.x, end.x)))
    const bottom = Math.min(bitmapCanvas.height, Math.ceil(Math.max(start.y, end.y)))
    return { x: left, y: top, width: Math.max(1, right - left), height: Math.max(1, bottom - top) }
  }

  function selectedBitmapRect() {
    return bitmapSelection ?? { x: 0, y: 0, width: bitmapCanvas?.width ?? 0, height: bitmapCanvas?.height ?? 0 }
  }

  function pointInBitmapRect(point: { x: number; y: number }, rect: { x: number; y: number; width: number; height: number }) {
    return point.x >= rect.x && point.x <= rect.x + rect.width && point.y >= rect.y && point.y <= rect.y + rect.height
  }

  // Wrap a floating-helper result for `putImageData`. The helper buffers are
  // typed as generic `Uint8ClampedArray<ArrayBufferLike>`; copying into a
  // fresh ArrayBuffer-backed array satisfies the `ImageData` constructor
  // without retaining helper internals.
  function floatingImageToImageData(image: BitmapFloatingImage): ImageData {
    return new ImageData(new Uint8ClampedArray(image.data), image.width, image.height)
  }

  function trimBitmapSelection(rect: { x: number; y: number; width: number; height: number }) {
    const context = bitmapCanvas?.getContext('2d')
    const image = context && bitmapCanvas ? context.getImageData(0, 0, bitmapCanvas.width, bitmapCanvas.height) : undefined
    if (!image) return rect
    return trimBitmapRectToOpaque(image, rect)
  }

  async function copyBitmapSelection(cut = false) {
    // Pending commit-first (B-3 copy/cut gap): while a bitmap session is
    // active/staged, commit BEFORE any clipboard read or deletion. In-memory
    // `bitmapClipboard` needs no async OS permission, so commit-then-copy is
    // safe (a sync-permission clipboard would prefer block). Disabled path
    // stays await-free (legacy ordering untouched).
    if (BITMAP_PENDING_UI_ENABLED && costumeEditMode === 'bitmap') {
      // Cut never uses the copy commit-first fallback: with a staged shape
      // there is no committed selection to cut, so a direct cut-copy blocks
      // before any clipboard read or deletion (pending retained). Plain copy
      // (`cut === false`) still commits first below.
      if (cut) {
        try {
          const cutCopySession = ensureBitmapPendingController()?.get()
          if (cutCopySession && cutCopySession.snapshot().hasPending) {
            status =
              'Bitmap cut blocked (pending shape not committed; press Escape to commit or Delete to discard first; pending retained)'
            return
          }
        } catch {
          status = 'Bitmap cut blocked (pending state unreadable; op blocked, original preserved)'
          return
        }
      }
      const epochTargetId = selectedTarget ? stableTargetId(selectedTarget) : ''
      const epochIndex = selectedTarget?.currentCostume ?? 0
      const epochSerial = bitmapCanvasReloadSerial
      const epochGeneration = bitmapWorkspaceGeneration
      const epochCanvas = bitmapCanvas
      const epochRect = bitmapSelection ? { ...bitmapSelection } : undefined
      const epochScope = selectedTarget ? captureDiscreteSaveScope(epochTargetId, epochIndex) : undefined
      const epochLive = epochTargetId && epochScope ? discreteSaveLiveOf(epochScope) : undefined
      const ok = await guardBitmapPendingCommitFirst('paint-copy')
      if (!ok) return
      const liveTargetId = selectedTarget ? stableTargetId(selectedTarget) : ''
      if (liveTargetId !== epochTargetId || (selectedTarget?.currentCostume ?? 0) !== epochIndex) {
        status = 'Bitmap copy blocked (target switched during pending commit; original preserved)'
        return
      }
      if (bitmapCanvasReloadSerial !== epochSerial || bitmapWorkspaceGeneration !== epochGeneration || bitmapCanvas !== epochCanvas) {
        status = 'Bitmap copy blocked (canvas reloaded during pending commit; original preserved)'
        return
      }
      if (epochScope && epochLive && !isDiscreteSaveScopeCurrent(epochScope, discreteSaveLiveOf(epochScope))) {
        status = 'Bitmap copy blocked (workspace changed during pending commit; original preserved)'
        return
      }
      // The gate clears the committed outline; restore the captured rect so
      // the committed bytes are copied (not an empty selection).
      if (!bitmapSelection && epochRect && epochRect.width > 0 && epochRect.height > 0) bitmapSelection = { ...epochRect }
    }
    // Copying a stale canvas would poison the clipboard with the wrong
    // asset's pixels; refuse while unsettled and keep the old clipboard.
    if (selectedTarget) {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        refuseStaleBitmapWorkspace('Bitmap copy')
        return
      }
    }
    if (cut && bitmapFloatingDragActive()) {
      status = 'Finish the bitmap selection drag first'
      return
    }
    const context = bitmapCanvas?.getContext('2d')
    if (!context || !bitmapCanvas) {
      if (!cut) status = 'Nothing to copy'
      return
    }
    // Cutting an empty selection leaves the clipboard untouched
    // (keyboard-shortcuts-hoc.jsx only cuts when something is selected).
    // Copying with no selection instead copies the trimmed opaque bitmap
    // (copy-paste-hoc.jsx getTrimmedRaster); an empty canvas copies nothing.
    let rect = bitmapSelection
    if (!rect || rect.width <= 0 || rect.height <= 0) {
      if (cut) return
      const full = { x: 0, y: 0, width: bitmapCanvas.width, height: bitmapCanvas.height }
      const image = context.getImageData(0, 0, bitmapCanvas.width, bitmapCanvas.height)
      const fallback = resolveBitmapCopyRect(undefined, image, full)
      if (!fallback) {
        status = 'Nothing to copy'
        return
      }
      rect = fallback
    }
    bitmapClipboard = context.getImageData(rect.x, rect.y, rect.width, rect.height)
    bitmapClipboardRect = { x: rect.x, y: rect.y, width: rect.width, height: rect.height }
    // Bundle the copy-time world frame with the pixels so a later paste on a
    // different target / costume / stage-vs-sprite / res1-vs-res2 destination
    // keeps the source's real size and copied position (Scratch parity):
    // live artboard resolution at copy time (equals the stored asset
    // resolution), the tracked origin / canvas-center, the stored rotation
    // center, and the reset stagger base. The snapshot survives target and
    // costume switches (clipboard is never cleared there) and bitmap->vector
    // conversion (which flips the destination to bitmapResolution=1).
    {
      const copyTarget = selectedTarget
      const copyIndex = copyTarget?.currentCostume ?? 0
      const copyCostume = copyTarget?.costumes[copyIndex]
      const track = liveBitmapArtboard()
      const destFallback = storedBitmapResolutionOf(copyTarget, copyIndex)
      const liveResolution = track.resolution > 0 ? track.resolution : destFallback
      const storedCx =
        typeof copyCostume?.rotationCenterX === 'number' && Number.isFinite(copyCostume.rotationCenterX)
          ? (copyCostume.rotationCenterX as number)
          : track.canvasCenterX - track.originX
      const storedCy =
        typeof copyCostume?.rotationCenterY === 'number' && Number.isFinite(copyCostume.rotationCenterY)
          ? (copyCostume.rotationCenterY as number)
          : track.canvasCenterY - track.originY
      bitmapClipboardSource = createBitmapClipboardSourceSnapshot({
        resolution: liveResolution,
        destFallbackResolution: destFallback,
        originX: track.originX,
        originY: track.originY,
        canvasCenterX: track.canvasCenterX,
        canvasCenterY: track.canvasCenterY,
        rotationCenterX: storedCx,
        rotationCenterY: storedCy,
        isStage: track.isStage,
        copyPasteOffset: 1,
      })
    }
    clipboardRecency = 'bitmap'
    pasteOffset = 1
    if (cut) {
      context.clearRect(rect.x, rect.y, rect.width, rect.height)
      await saveBitmapCostume('Bitmap cut saved')
      status = 'Bitmap selection cut'
    } else {
      status = 'Bitmap selection copied'
    }
  }

  async function pasteBitmapSelection() {
    // Pending commit-first (B-3 paste gap): commit the staged shape BEFORE
    // any selection/tool/canvas mutation. Capture the stable slot + canvas
    // identity + saved selection + clipboard synchronously, revalidate after
    // the async commit; on refuse/owner change retain pending/clipboard and
    // do not touch the new canvas. No ghost paste after async. Disabled path
    // stays await-free (legacy ordering untouched).
    if (BITMAP_PENDING_UI_ENABLED && costumeEditMode === 'bitmap') {
      const pasteEpochTargetId = selectedTarget ? stableTargetId(selectedTarget) : ''
      const pasteEpochIndex = selectedTarget?.currentCostume ?? 0
      const pasteEpochSerial = bitmapCanvasReloadSerial
      const pasteEpochGeneration = bitmapWorkspaceGeneration
      const pasteEpochCanvas = bitmapCanvas
      const pasteEpochRect = bitmapSelection ? { ...bitmapSelection } : undefined
      const pasteEpochScope = selectedTarget ? captureDiscreteSaveScope(pasteEpochTargetId, pasteEpochIndex) : undefined
      const pasteEpochClipboard = bitmapClipboard
      const pasteEpochClipboardRect = bitmapClipboardRect ? { ...bitmapClipboardRect } : undefined
      const pasteOk = await guardBitmapPendingCommitFirst('paint-paste')
      if (!pasteOk) return
      const pasteLiveId = selectedTarget ? stableTargetId(selectedTarget) : ''
      if (pasteLiveId !== pasteEpochTargetId || (selectedTarget?.currentCostume ?? 0) !== pasteEpochIndex) {
        status = 'Bitmap paste blocked (target switched during pending commit; original preserved)'
        return
      }
      if (bitmapCanvasReloadSerial !== pasteEpochSerial || bitmapWorkspaceGeneration !== pasteEpochGeneration || bitmapCanvas !== pasteEpochCanvas) {
        status = 'Bitmap paste blocked (canvas reloaded during pending commit; original preserved)'
        return
      }
      if (pasteEpochScope && !isDiscreteSaveScopeCurrent(pasteEpochScope, discreteSaveLiveOf(pasteEpochScope))) {
        status = 'Bitmap paste blocked (workspace changed during pending commit; original preserved)'
        return
      }
      // Clipboard preserved: the commit never touches it; a lost clipboard
      // (external clear raced the commit) blocks instead of ghost-pasting.
      if (!bitmapClipboard || bitmapClipboard !== pasteEpochClipboard) {
        if (!bitmapClipboard) {
          status = 'Bitmap paste blocked (clipboard lost during pending commit; original preserved)'
          return
        }
      }
      void pasteEpochClipboardRect
      // The commit clears the staged outline; restore the captured anchor so
      // the paste lands where the pre-commit selection was (committed bytes
      // anchor, not an empty selection).
      if (!bitmapSelection && pasteEpochRect && pasteEpochRect.width > 0 && pasteEpochRect.height > 0) bitmapSelection = { ...pasteEpochRect }
    }
    if (selectedTarget) {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        if (bitmapWorkspacePending) {
          status = 'Loading bitmap…'
        } else {
          refuseStaleBitmapWorkspace('Bitmap paste')
        }
        return
      }
    }
    if (bitmapFloatingDragActive()) {
      status = 'Finish the bitmap selection drag first'
      return
    }
    if (isBitmapEditRefused()) {
      status = 'Image too large to edit safely — original kept unchanged'
      return
    }
    const context = bitmapCanvas?.getContext('2d')
    if (!context || !bitmapCanvas || !bitmapClipboard) return
    const rect = resolveBitmapPasteRect(
      { width: bitmapCanvas.width, height: bitmapCanvas.height },
      { width: bitmapClipboard.width, height: bitmapClipboard.height },
      bitmapSelection,
      pasteOffset,
    )
    // Source-over paste (not verbatim putImageData): transparent clipboard
    // pixels preserve the artwork underneath instead of erasing it.
    const live = context.getImageData(0, 0, bitmapCanvas.width, bitmapCanvas.height)
    const stamped = compositeFloatingPatch(
      { width: live.width, height: live.height, data: live.data },
      { width: bitmapClipboard.width, height: bitmapClipboard.height, data: bitmapClipboard.data },
      rect.x,
      rect.y,
    )
    bitmapSelection = { ...rect }
    bitmapTool = 'select'
    pasteOffset = nextPasteOffset(pasteOffset)
    if (!stamped.changed) {
      // Fully-transparent or fully-offscreen paste: outline only, no pixels,
      // no history entry.
      status = 'Bitmap selection pasted'
      return
    }
    context.putImageData(floatingImageToImageData(stamped.image), 0, 0)
    await saveBitmapCostume('Bitmap paste saved')
    status = 'Bitmap selection pasted'
  }

  async function cropBitmapSelection() {
    // Pending block: the staged shape owns the selection outline; a commit
    // would clear it, so the original crop box cannot be preserved safely.
    // Block BEFORE any selection/canvas mutation (no commit, no history),
    // retained until Escape (commit) or Delete (discard). Disabled path
    // stays await-free.
    if (BITMAP_PENDING_UI_ENABLED && costumeEditMode === 'bitmap') {
      try {
        const cropPendingSession = ensureBitmapPendingController()?.get()
        if (cropPendingSession && cropPendingSession.snapshot().hasPending) {
          status =
            'Bitmap crop blocked (pending shape not committed; press Escape to commit or Delete to discard first; pending retained)'
          return
        }
      } catch {
        status = 'Bitmap crop blocked (pending state unreadable; op blocked, original preserved)'
        return
      }
      const cropEpochTargetId = selectedTarget ? stableTargetId(selectedTarget) : ''
      const cropEpochIndex = selectedTarget?.currentCostume ?? 0
      const cropEpochSerial = bitmapCanvasReloadSerial
      const cropEpochGeneration = bitmapWorkspaceGeneration
      const cropEpochCanvas = bitmapCanvas
      const cropEpochScope = selectedTarget ? captureDiscreteSaveScope(cropEpochTargetId, cropEpochIndex) : undefined
      const cropOk = await guardBitmapPendingCommitFirst('paint-crop')
      if (!cropOk) return
      const cropLiveId = selectedTarget ? stableTargetId(selectedTarget) : ''
      if (cropLiveId !== cropEpochTargetId || (selectedTarget?.currentCostume ?? 0) !== cropEpochIndex) {
        status = 'Bitmap crop blocked (target switched during pending commit; original preserved)'
        return
      }
      if (bitmapCanvasReloadSerial !== cropEpochSerial || bitmapWorkspaceGeneration !== cropEpochGeneration || bitmapCanvas !== cropEpochCanvas) {
        status = 'Bitmap crop blocked (canvas reloaded during pending commit; original preserved)'
        return
      }
      if (cropEpochScope && !isDiscreteSaveScopeCurrent(cropEpochScope, discreteSaveLiveOf(cropEpochScope))) {
        status = 'Bitmap crop blocked (workspace changed during pending commit; original preserved)'
        return
      }
    }
    if (selectedTarget) {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        refuseStaleBitmapWorkspace('Bitmap crop')
        return
      }
    }
    if (bitmapFloatingDragActive()) {
      status = 'Finish the bitmap selection drag first'
      return
    }
    const context = bitmapCanvas?.getContext('2d')
    if (!context || !bitmapCanvas || !bitmapSelection) return
    if (isBitmapEditRefused()) {
      status = 'Image too large to edit safely — original kept unchanged'
      return
    }
    const cropTarget = selectedTarget ? stableTargetId(selectedTarget) : ''
    const cropIndex = selectedTarget?.currentCostume ?? 0
    const cropSel = { ...bitmapSelection }
    const cropTrack = liveBitmapArtboard()
    const cropCcX = cropTrack.canvasCenterX
    const cropCcY = cropTrack.canvasCenterY
    const cropIsStage = cropTrack.isStage
    const cropResolution = cropTrack.resolution > 0 ? cropTrack.resolution : cropIsStage ? 1 : 2
    const selection = context.getImageData(bitmapSelection.x, bitmapSelection.y, bitmapSelection.width, bitmapSelection.height)
    resizeBitmapCanvas(selection.width, selection.height)
    // World anchor preserved: the new canvas center is the old center shifted
    // by the crop origin, so the follow-up cropped save keeps the VM position.
    bitmapArtboard = {
      originX: 0,
      originY: 0,
      canvasCenterX: cropCcX - cropSel.x,
      canvasCenterY: cropCcY - cropSel.y,
      isStage: cropIsStage,
      width: selection.width,
      height: selection.height,
      resolution: cropResolution,
      refused: false,
    }
    // Same binding race as conversion/Undo loads: flush the resized binding
    // before stamping, or Chrome wipes the cropped pixels. A switch during
    // the tick aborts instead of writing into the newly selected costume.
    await tick()
    if (!selectedTarget || stableTargetId(selectedTarget) !== cropTarget) return
    if ((selectedTarget.currentCostume ?? 0) !== cropIndex) return
    if (!isBitmapWorkspaceSettledFor(cropTarget, cropIndex)) {
      refuseStaleBitmapWorkspace('Bitmap crop')
      return
    }
    if (!bitmapCanvas) return
    bitmapCanvas.getContext('2d')?.putImageData(selection, 0, 0)
    bitmapSelection = { x: 0, y: 0, width: selection.width, height: selection.height }
    await saveBitmapCostume('Bitmap crop saved')
    status = 'Bitmap cropped'
  }

  // LEGACY / UNREACHABLE (documented, intentionally unmodified): the bitmap
  // canvas never reaches this function — BitmapEditor opens the inline text
  // overlay for the text tool and returns before `beginBitmapPaint`, so the
  // `bitmapTool === 'text'` branch below is dead in the current UI. The
  // brushSize-derived size and fixed Arial here are superseded by
  // `commitBitmapInlineText` (toolbar font/size via `resolveBitmapTextFont`,
  // multiline, RTL, IME). Kept only so the `beginBitmapPaint` text branch
  // keeps its historical shape; do not route new callers here.
  function drawBitmapText(event: MouseEvent) {
    const context = bitmapCanvas?.getContext('2d')
    if (!context) return
    const { x, y } = bitmapPoint(event)
    const fontSize = Math.max(12, brushSize * 4)
    context.fillStyle = bitmapPaintStyle(context, x - fontSize * vectorText.length * 0.25, y - fontSize, Math.max(fontSize, fontSize * vectorText.length * 0.55), fontSize * 1.25)
    context.strokeStyle = strokeTransparent ? 'rgba(0, 0, 0, 0)' : strokeColor
    context.lineWidth = 1
    context.font = `${fontSize}px Arial, sans-serif`
    context.textAlign = 'center'
    context.textBaseline = 'middle'
    if (!strokeTransparent) context.strokeText(vectorText, x, y)
    context.fillText(vectorText, x, y)
  }

  // Bitmap fill tool: strict-RGBA fills via the shared helpers. Plain click
  // flood-fills the connected region; Shift replaces every pixel matching the
  // seed color. The solid mode paints a single color: opaque from the hex
  // picker, or alpha 0 (erase) when the transparent fill toggle is on. Any
  // selected gradient is rendered onto an offscreen canvas sized to the fill
  // region's tight mask bounds (the same gradient geometry shapes/text use)
  // and kept only where the mask is set via a `destination-in` composite
  // before being drawn back; transparent gradient ends fade only opacity via
  // the shared stops (surviving end's RGB with alpha 0). Returns false when
  // nothing changed; callers must skip save/history in that case.
  function applyBitmapFill(event: MouseEvent): boolean {
    const context = bitmapCanvas?.getContext('2d')
    if (!context || !bitmapCanvas) return false
    const point = bitmapPoint(event)
    const x = Math.floor(point.x)
    const y = Math.floor(point.y)
    if (x < 0 || y < 0 || x >= bitmapCanvas.width || y >= bitmapCanvas.height) return false
    const image = context.getImageData(0, 0, bitmapCanvas.width, bitmapCanvas.height)
    const source = { width: image.width, height: image.height, data: image.data }
    if (paintGradient === 'solid') {
      const [r, g, b, a] = resolveBitmapSolidFill(fillTransparent, paintColor)
      const result = event.shiftKey
        ? floodFillAllBitmap(source, x, y, [r, g, b, a])
        : floodFillBitmapRegion(source, x, y, [r, g, b, a])
      if (!result.changed) return false
      const filled = new ImageData(result.image.width, result.image.height)
      filled.data.set(result.image.data)
      context.putImageData(filled, 0, 0)
      return true
    }
    const maskResult = event.shiftKey
      ? floodFillAllMaskBitmap(source, x, y)
      : floodFillMaskBitmap(source, x, y)
    const result = maskResult
    if (!result.changed) return false
    const bounds = result.bounds ?? { x: 0, y: 0, width: bitmapCanvas.width, height: bitmapCanvas.height }
    const gradientLayer = document.createElement('canvas')
    gradientLayer.width = bitmapCanvas.width
    gradientLayer.height = bitmapCanvas.height
    const gradientContext = gradientLayer.getContext('2d')
    if (!gradientContext) return false
    gradientContext.fillStyle = bitmapPaintStyle(gradientContext, bounds.x, bounds.y, Math.max(1, bounds.width), Math.max(1, bounds.height), { x, y })
    gradientContext.fillRect(0, 0, gradientLayer.width, gradientLayer.height)
    const maskLayer = document.createElement('canvas')
    maskLayer.width = bitmapCanvas.width
    maskLayer.height = bitmapCanvas.height
    const maskContext = maskLayer.getContext('2d')
    if (!maskContext) return false
    const maskImage = maskContext.createImageData(maskLayer.width, maskLayer.height)
    for (let i = 0; i < result.mask.length; i += 1) {
      if (result.mask[i] === 1) {
        const offset = i * 4
        maskImage.data[offset] = 255
        maskImage.data[offset + 1] = 255
        maskImage.data[offset + 2] = 255
        maskImage.data[offset + 3] = 255
      }
    }
    maskContext.putImageData(maskImage, 0, 0)
    // Keep the gradient only where the fill region mask is opaque, then paint
    // it back. The mask region is erased first (`destination-out`) so the
    // gradient *replaces* the region instead of blending over it: opaque
    // stops repaint identically to before, while transparent/semitransparent
    // stops leave the correct alpha behind instead of a source-over blend
    // over the old pixels (which could never erase).
    gradientContext.globalCompositeOperation = 'destination-in'
    gradientContext.drawImage(maskLayer, 0, 0)
    gradientContext.globalCompositeOperation = 'source-over'
    context.save()
    context.globalCompositeOperation = 'destination-out'
    context.drawImage(maskLayer, 0, 0)
    context.restore()
    context.drawImage(gradientLayer, 0, 0)
    return true
  }

  function bitmapPaintStyle(context: CanvasRenderingContext2D, x: number, y: number, width: number, height: number, click?: { x: number; y: number }): string | CanvasGradient {
    if (paintGradient === 'solid') return fillTransparent ? 'rgba(0, 0, 0, 0)' : paintColor
    const [from, to] = resolveBitmapGradientStops(fillTransparent, paintColor, secondaryTransparent, secondaryPaintColor)
    if (paintGradient === 'radial') {
      // Click-seeded radial geometry (connected mask bounds, or Shift-global
      // mask bounds): highlight follows the fill seed, radius follows the
      // longest side. Transparent ends only change stops, never geometry;
      // Shift/history guards live in `applyBitmapFill` (mask + no-op check).
      const geometry = resolveBitmapFillRadialGeometry({ x, y, width, height }, click)
      const gradient = context.createRadialGradient(geometry.centerX, geometry.centerY, 0, geometry.centerX, geometry.centerY, Math.max(1, geometry.radius))
      gradient.addColorStop(0, from.css)
      gradient.addColorStop(1, to.css)
      return gradient
    }
    const gradient = paintGradient === 'vertical'
      ? context.createLinearGradient(x, y, x, y + height)
      : context.createLinearGradient(x, y, x + width, y)
    gradient.addColorStop(0, from.css)
    gradient.addColorStop(1, to.css)
    return gradient
  }

  // Commit an eyedropper sample to the effective target. A fully transparent
  // pixel sets the transparent toggle (the stored hex is kept so untoggling
  // restores it); anything else becomes the opaque hex and clears the toggle.
  // Picking never writes history: it only arms the next paint, exactly like
  // the reference fill/stroke picker callbacks.
  function applyEyedropperColor(pixel: { r: number; g: number; b: number; a: number }, target: 'fill' | 'stroke') {
    commitHsvLivePendingSync()
    const picked = resolveEyedropperPixel({ r: pixel.r, g: pixel.g, b: pixel.b, a: pixel.a })
    if (target === 'stroke') {
      if (picked.transparent) {
        strokeTransparent = true
        markVectorStyleDirty('stroke')
        status = 'Transparent stroke picked'
        return
      }
      strokeTransparent = false
      strokeColor = picked.hex
      markVectorStyleDirty('stroke')
      status = 'Stroke color picked'
      return
    }
    if (picked.transparent) {
      fillTransparent = true
      markVectorStyleDirty('fill')
      status = 'Transparent picked'
      return
    }
    fillTransparent = false
    paintColor = picked.hex
    markVectorStyleDirty('fill')
    status = 'Color picked'
  }

  function cancelEyedropper() {
    if (!eyedropperActive) return
    eyedropperActive = false
    status = 'Eyedropper cancelled'
  }

  function closedKindOf(root: ParentNode | null | undefined): 'fill' | 'stroke' | null {
    try {
      const node = root?.querySelector?.('[data-paint-popover-open="true"]') as HTMLElement | null
      const kind = node?.getAttribute?.('data-paint-popover-root') ?? node?.getAttribute?.('data-testid') ?? ''
      if (kind.includes('outline')) return 'stroke'
      if (kind.includes('fill')) return 'fill'
    } catch {
      // Best effort only.
    }
    return 'fill'
  }

  function focusPopoverTrigger(kind: 'fill' | 'stroke' | null | undefined) {
    // Return focus to the swatch that owned the dialog (popover parity):
    // input-focus Escape removes the dialog, so focus must not be lost to
    // the body. Scoped to this editor only; missing triggers are a no-op.
    try {
      if (!editorRootNode || kind === null || kind === undefined) return
      const selector = kind === 'stroke' ? '[data-testid="outline-style"]' : '[data-testid="fill-style"]'
      const trigger = editorRootNode.querySelector?.(selector) as HTMLElement | null
      trigger?.focus?.()
    } catch {
      // Best effort only.
    }
  }

  function pickBitmapColor(event: MouseEvent) {
    // Legacy double-click shortcut stays bitmap-only and never double-applies
    // while the dedicated overlay owns picking.
    if (eyedropperActive) return
    const context = bitmapCanvas?.getContext('2d')
    if (!context) return
    const rect = bitmapCanvas.getBoundingClientRect()
    const x = Math.floor(((event.clientX - rect.left) / rect.width) * bitmapCanvas.width)
    const y = Math.floor(((event.clientY - rect.top) / rect.height) * bitmapCanvas.height)
    const [r, g, b, a] = context.getImageData(x, y, 1, 1).data
    // A fully transparent pixel yields transparent (the stored hex is kept so
    // untoggling restores it); anything else becomes the opaque hex and
    // clears the transparent toggle.
    const picked = resolveEyedropperPixel({ r: r ?? 0, g: g ?? 0, b: b ?? 0, a: a ?? 0 })
    if (picked.transparent) {
      fillTransparent = true
      status = 'Transparent picked'
      return
    }
    fillTransparent = false
    paintColor = picked.hex
    status = 'Color picked'
  }

  // Stale-save sentinel: build detected an unsettled workspace (decode
  // pending or owner mismatch) before/after the async toBlob encode. Callers
  // must abort with no history entry and no VM write (safe cancel).
  const BITMAP_SAVE_STALE = { stale: true as const }
  // Refused-save sentinel: the live raster or its encode cannot faithfully
  // hold the pixels (extreme side, unreadable raster, null encode). Callers
  // must surface the explicit oversize refusal with no history entry and no
  // VM write — never a success status and never a transparent overwrite.
  const BITMAP_SAVE_REFUSED = { refused: true as const }
  type BitmapSaveResult = CroppedBitmapSave | undefined | typeof BITMAP_SAVE_STALE | typeof BITMAP_SAVE_REFUSED
  function isBitmapSaveStale(value: BitmapSaveResult): value is typeof BITMAP_SAVE_STALE {
    return typeof value === 'object' && value !== null && 'stale' in value
  }
  function isBitmapSaveRefused(value: BitmapSaveResult): value is typeof BITMAP_SAVE_REFUSED {
    return typeof value === 'object' && value !== null && 'refused' in value
  }

  function bitmapSaveEntryValid(
    entryTargetId: string,
    entryIndex: number,
    entrySerial: number,
    entryRevision: number,
    entryScopeKey: string,
    entryScopeGeneration: number,
  ): boolean {
    if (!selectedTarget) return false
    if (stableTargetId(selectedTarget) !== entryTargetId) return false
    if ((selectedTarget.currentCostume ?? 0) !== entryIndex) return false
    if (paintScopeKey !== entryScopeKey || paintScopeGeneration !== entryScopeGeneration) return false
    if (revisionGuardChanged(entrySerial, entryRevision)) return false
    if (!isBitmapWorkspaceSettledFor(entryTargetId, entryIndex)) return false
    return true
  }

  function revisionGuardChanged(entrySerial: number, entryRevision: number): boolean {
    return entrySerial !== bitmapCanvasReloadSerial || entryRevision !== assetPreviewRevision || Boolean(bitmapWorkspacePending)
  }

  async function saveBitmapCostume(nextStatus = 'Bitmap costume saved') {
    if (!selectedTarget || !bitmapCanvas) return
    // Pending rect/oval (B-3): commit-first BEFORE reading the canvas. The
    // session commit already contains the displayed shape + exactly one
    // history entry; the cropped save below then becomes a byte-identical
    // no-op (no duplicate history, no second VM write).
    try {
      const pendingSession = ensureBitmapPendingController()?.get()
      if (pendingSession) {
        let snap: { hasPending: boolean; commitInFlight: boolean } | undefined
        try {
          snap = pendingSession.snapshot()
        } catch {
          snap = undefined
        }
        if (snap && (snap.hasPending || snap.commitInFlight)) {
          // The live canvas already shows the committed pixels once the CAS
          // proves the write; the barrier below covers the `await` window so
          // a concurrent external write is never swallowed.
          let preReloadScope: BitmapReloadCommitScope | undefined = undefined
          try {
            if (selectedTarget) {
              captureBitmapReloadBarrierForSlot(stableTargetId(selectedTarget), selectedTarget.currentCostume ?? 0)
              preReloadScope = captureBitmapReloadCommitScope(stableTargetId(selectedTarget), selectedTarget.currentCostume ?? 0)
            }
          } catch {
            // Best effort only.
          }
          const result = await pendingSession.commitPending()
          const preReloadScopeCurrent = preReloadScope ? isBitmapReloadCommitScopeCurrent(preReloadScope) : false
          if (!preReloadScope || (preReloadScope && bitmapPendingCommitBarrier === preReloadScope.barrier)) clearBitmapReloadBarrier()
          if (result.ok && (result.kind === 'committed' || result.kind === 'committed-without-history')) {
            try {
              if (preReloadScope && preReloadScopeCurrent) {
                const wantId = preReloadScope.targetId
                const index = preReloadScope.index
                if (selectedTarget && bitmapWorkspaceOwner && bitmapWorkspaceOwner.targetId === wantId && bitmapWorkspaceOwner.index === index) {
                  const fresh = (vectorWriteTargetById(wantId, selectedTarget.name) ?? vm.getTarget(wantId) ?? vm.getTarget(selectedTarget.name))?.costumes[index] ?? selectedTarget.costumes[index]
                  bitmapWorkspaceOwner = { ...bitmapWorkspaceOwner, assetKey: fresh?.md5ext ?? fresh?.assetId ?? bitmapWorkspaceOwner.assetKey }
                }
                rememberPaintKnown(wantId, index, readLiveSlotIdentity(wantId, index))
                armBitmapReloadSkipFromLive(wantId, index)
              } else {
                clearBitmapReloadSkip()
              }
            } catch {
              // Best effort only.
            }
            bitmapSelection = undefined
            status = result.kind === 'committed-without-history'
              ? 'history-gap: bytes committed without undo entry; explicit acknowledgement required before further paint/export/switch (Undo unavailable for last stroke)'
              : nextStatus
            await reconcileDeferredBitmapReload()
            return
          }
          if (!result.ok) {
            // Ownership loss: reload the live latest bytes (scoped).
            clearBitmapReloadSkip()
            await reloadBitmapCanvasIfPendingOwnershipLost(result)
            await reconcileDeferredBitmapReload()
            status = `Bitmap shape commit ${(result as { reason?: string }).reason ?? 'refused'} (save blocked; pending retained, original preserved)`
            return
          }
        }
      }
    } catch {
      clearBitmapReloadBarrier()
      clearBitmapReloadSkip()
      await reconcileDeferredBitmapReload()
      status = 'Bitmap save blocked (pending gate failed); original preserved'
      return
    }
    if (isBitmapEditRefused()) {
      status = 'Image too large to edit safely — original kept unchanged'
      return
    }
    // Workspace owner gate at entry: decode pending or owner mismatch means
    // the live canvas does not show this asset yet. Reading it now would save
    // stale pixels into the new asset, so refuse before any read/encode.
    const entryTarget = selectedTarget
    const entryTargetId = stableTargetId(entryTarget)
    const index = entryTarget.currentCostume ?? 0
    const entryScopeKey = paintScopeKey
    const entryScopeGeneration = paintScopeGeneration
    const entrySerial = bitmapCanvasReloadSerial
    const entryRevision = assetPreviewRevision
    if (!isBitmapWorkspaceSettledFor(entryTargetId, index)) {
      refuseStaleBitmapWorkspace('Bitmap save')
      return
    }
    // ベクター回転の Esc 復元とビットマップ確定が同じコスチューム履歴に
    // 書き込む競合を避けるため、復元完了まで待ってから capture する。
    // 待機自体は履歴に触れないため redo/他操作の履歴を消さない。
    // 待機中に切替/Undo/Redoが入ったら post-await で検証して安全中止.
    if (vectorRotateCancelPromise) await vectorRotateCancelPromise
    if (!bitmapSaveEntryValid(entryTargetId, index, entrySerial, entryRevision, entryScopeKey, entryScopeGeneration)) {
      refuseStaleBitmapWorkspace('Bitmap save')
      return
    }
    // Same-content Save guard: build the cropped bytes first and compare
    // against the stored asset. Identical bytes+center (or both fully
    // transparent) skip capture+write so the explicit Save button stays
    // idempotent and never pushes an empty Undo entry.
    const target = entryTarget
    const pending = await buildCroppedBitmapSave(target, index, bitmapCanvas)
    if (isBitmapSaveRefused(pending)) {
      refuseBitmapOversize()
      return
    }
    if (isBitmapSaveStale(pending)) {
      refuseStaleBitmapWorkspace('Bitmap save')
      return
    }
    if (!bitmapSaveEntryValid(entryTargetId, index, entrySerial, entryRevision, entryScopeKey, entryScopeGeneration)) {
      refuseStaleBitmapWorkspace('Bitmap save')
      return
    }
    if (!pending) {
      // Fully transparent workspace: no-op when the stored asset is already
      // transparent (empty upload left untouched); a real deletion (stored
      // ink -> empty) writes a minimal transparent asset with one history
      // entry so explicit clear / erase-to-empty is undoable.
      // A blank live canvas over a huge (over-cap) surface is a raster
      // refusal, not a user deletion: the environment cannot show the
      // stored ink, so probe nothing and refuse with the stored bytes
      // untouched instead of a transparent overwrite.
      if (bitmapCanvas && isBitmapSourceSizeRefused(bitmapCanvas.width, bitmapCanvas.height)) {
        refuseBitmapOversize()
        return
      }
      // Post-await re-validation: the opaque probe reads the store
      // asynchronously, so a switch/undo in between must abort.
      const hasOpaque = await storedBitmapHasOpaque(target, index)
      if (!bitmapSaveEntryValid(entryTargetId, index, entrySerial, entryRevision, entryScopeKey, entryScopeGeneration)) {
        refuseStaleBitmapWorkspace('Bitmap save')
        return
      }
      if (hasOpaque) {
        // A blank live canvas over a huge (over-cap) surface is a raster
        // refusal, not a user deletion: the environment cannot show the
        // stored ink, so a transparent overwrite would destroy it. Refuse
        // with the stored bytes untouched instead of writing 1x1.
        if (bitmapCanvas && isBitmapSourceSizeRefused(bitmapCanvas.width, bitmapCanvas.height)) {
          refuseBitmapOversize()
          return
        }
        const entry = await peekCostumeHistory(target, index)
        if (!bitmapSaveEntryValid(entryTargetId, index, entrySerial, entryRevision, entryScopeKey, entryScopeGeneration)) {
          refuseStaleBitmapWorkspace('Bitmap save')
          return
        }
        if (!entry) {
          refuseStaleBitmapWorkspace('Bitmap save')
          return
        }
        commitPaintHistory(entry)
        // Commit may drop on a concurrent clear: verify it landed, otherwise
        // refuse the write so a stale canvas never writes without history.
        const guard = historyGuardOf(entry)
        if (guard && !isGuardCurrent(paintScopeKey, paintScopeGeneration, guard)) {
          refuseStaleBitmapWorkspace('Bitmap save')
          return
        }
        if (!bitmapSaveEntryValid(entryTargetId, index, entrySerial, entryRevision, entryScopeKey, entryScopeGeneration)) {
          refuseStaleBitmapWorkspace('Bitmap save')
          return
        }
        await writeTransparentBitmapSave(target, index)
      }
      status = nextStatus
      return
    }
    if (await isBitmapSaveNoop(target, index, pending)) {
      if (!bitmapSaveEntryValid(entryTargetId, index, entrySerial, entryRevision, entryScopeKey, entryScopeGeneration)) {
        refuseStaleBitmapWorkspace('Bitmap save')
        return
      }
      status = nextStatus
      return
    }
    if (!bitmapSaveEntryValid(entryTargetId, index, entrySerial, entryRevision, entryScopeKey, entryScopeGeneration)) {
      refuseStaleBitmapWorkspace('Bitmap save')
      return
    }
    const entry = await peekCostumeHistory(target, index)
    if (!bitmapSaveEntryValid(entryTargetId, index, entrySerial, entryRevision, entryScopeKey, entryScopeGeneration)) {
      refuseStaleBitmapWorkspace('Bitmap save')
      return
    }
    if (!entry) {
      refuseStaleBitmapWorkspace('Bitmap save')
      return
    }
    commitPaintHistory(entry)
    const guard = historyGuardOf(entry)
    if (guard && !isGuardCurrent(paintScopeKey, paintScopeGeneration, guard)) {
      refuseStaleBitmapWorkspace('Bitmap save')
      return
    }
    if (!bitmapSaveEntryValid(entryTargetId, index, entrySerial, entryRevision, entryScopeKey, entryScopeGeneration)) {
      refuseStaleBitmapWorkspace('Bitmap save')
      return
    }
    const wrote = await writeCroppedBitmapSave(target, index, pending)
    if (!wrote) return
    status = nextStatus
  }

  type CroppedBitmapSave = {
    bytes: Uint8Array
    width: number
    height: number
    rotationCenterX: number
    rotationCenterY: number
    bitmapResolution: number
    /** Persistent center offset carried by this save (see state comment). */
    centerOffsetX: number
    centerOffsetY: number
  }

  async function buildCroppedBitmapSave(
    target: ScratchTarget,
    index: number,
    source: HTMLCanvasElement,
  ): Promise<BitmapSaveResult> {
    // Pre-read gate: the live canvas must show this asset. A pending decode
    // or an owner mismatch means stale pixels — refuse before reading.
    if (source === bitmapCanvas) {
      const wantId = stableTargetId(target)
      if (!isBitmapWorkspaceSettledFor(wantId, index)) return BITMAP_SAVE_STALE
      if (isBitmapEditRefused()) return BITMAP_SAVE_REFUSED
    }
    // Over-cap surfaces can never rasterize/encode faithfully: refuse before
    // reading or allocating a cropped canvas (a blank read persisted here
    // would silently blank the stored asset).
    if (isBitmapSourceSizeRefused(source.width, source.height)) return BITMAP_SAVE_REFUSED
    const entrySerial = bitmapCanvasReloadSerial
    const entryRevision = assetPreviewRevision
    const context = source.getContext('2d')
    if (!context) return BITMAP_SAVE_REFUSED
    let image: ImageData
    try {
      image = context.getImageData(0, 0, source.width, source.height)
    } catch {
      // Unreadable raster (too large for this environment's 2D readback):
      // never treat as transparent — that misclassification would overwrite
      // stored ink with empty bytes under a success status.
      return BITMAP_SAVE_REFUSED
    }
    const costume = target.costumes[index]
    // Pure preparation (bitmap-cropped-save): same synchronous validation +
    // geometry as the inline gates below, without DOM/VM/history/status.
    const prepared = prepareCroppedBitmapSave({
      rgba: image.data,
      imageWidth: image.width,
      imageHeight: image.height,
      isStage: target.isStage,
      storedResolution: storedBitmapResolutionOf(target, index),
      track: liveBitmapArtboard(),
      storedCenterX: costume?.rotationCenterX,
      storedCenterY: costume?.rotationCenterY,
      centerOffset: bitmapArtboardCenterOffset,
      placementCenter: bitmapArtboardPlacementCenter,
    })
    if (prepared.kind === 'refused') {
      // Over-cap/unreadable raster: never a transparent overwrite.
      return BITMAP_SAVE_REFUSED
    }
    if (prepared.kind === 'transparent') {
      // Fully transparent workspace: the caller decides between a no-op
      // (stored asset already transparent: empty upload left untouched) and
      // a minimal transparent write (real ink deleted: explicit clear stays
      // undoable).
      return undefined
    }
    const trim = prepared.trim
    const saved = {
      width: prepared.width,
      height: prepared.height,
      rotationCenterX: prepared.rotationCenterX,
      rotationCenterY: prepared.rotationCenterY,
      bitmapResolution: prepared.bitmapResolution,
    }
    const offsetX = prepared.centerOffsetX
    const offsetY = prepared.centerOffsetY
    const cropped = document.createElement('canvas')
    cropped.width = trim.width
    cropped.height = trim.height
    const croppedContext = cropped.getContext('2d')
    if (!croppedContext) return BITMAP_SAVE_REFUSED
    croppedContext.clearRect(0, 0, trim.width, trim.height)
    try {
      croppedContext.drawImage(source, trim.x, trim.y, trim.width, trim.height, 0, 0, trim.width, trim.height)
    } catch {
      return BITMAP_SAVE_REFUSED
    }
    let blob: Blob | null
    try {
      blob = await encodeCanvasToPngBlob(cropped)
    } catch {
      return BITMAP_SAVE_REFUSED
    }
    // Post-encode gate: a switch/load/undo during the async toBlob must not
    // let stale pixels through. The caller re-validates too; fail closed here.
    if (source === bitmapCanvas) {
      if (entrySerial !== bitmapCanvasReloadSerial || entryRevision !== assetPreviewRevision || Boolean(bitmapWorkspacePending)) return BITMAP_SAVE_STALE
      const wantIdAfter = stableTargetId(target)
      if (!isBitmapWorkspaceSettledFor(wantIdAfter, index)) return BITMAP_SAVE_STALE
      if (selectedTarget && (stableTargetId(selectedTarget) !== wantIdAfter || (selectedTarget.currentCostume ?? 0) !== index)) return BITMAP_SAVE_STALE
    }
    // A null/empty encode is an environment refusal (huge-side toBlob null),
    // never a transparent no-op: misclassifying it would overwrite stored ink
    // with empty bytes under a success status.
    if (!blob || blob.size === 0) return BITMAP_SAVE_REFUSED
    return { bytes: new Uint8Array(await blob.arrayBuffer()), ...saved, centerOffsetX: offsetX, centerOffsetY: offsetY }
  }

  async function isBitmapSaveNoop(target: ScratchTarget, index: number, pending: CroppedBitmapSave): Promise<boolean> {
    try {
      const costume = target.costumes[index]
      const key = costume?.md5ext ?? costume?.assetId
      const stored = key ? await vm.loadAsset(key, costume?.dataFormat ?? '') : undefined
      // Pure comparison (bitmap-cropped-save): same bytes+center verdict as
      // the inline gates below, without changing the VM read timing.
      return isCroppedBitmapSaveUnchanged(
        {
          bytes: stored,
          rotationCenterX: costume?.rotationCenterX,
          rotationCenterY: costume?.rotationCenterY,
          bitmapResolution: costume?.bitmapResolution,
        },
        pending,
      )
    } catch {
      return false
    }
  }

  async function writeCroppedBitmapSave(target: ScratchTarget, index: number, pending: CroppedBitmapSave): Promise<boolean> {
    // Final gate: never write stale canvas into the wrong asset. Only the
    // currently selected asset may be written; cross-target writes (e.g. an
    // old-asset in-flight save completing after a switch) safely cancel.
    // Returns false when nothing was written so the caller never reports a
    // success status for a cancelled/refused write.
    const wantId = stableTargetId(target)
    if (!selectedTarget || stableTargetId(selectedTarget) !== wantId || (selectedTarget.currentCostume ?? 0) !== index) {
      refuseStaleBitmapWorkspace('Bitmap save')
      return false
    }
    if (!isBitmapWorkspaceSettledFor(wantId, index)) {
      if (isBitmapEditRefused()) refuseBitmapOversize()
      else refuseStaleBitmapWorkspace('Bitmap save')
      return false
    }
    let preReloadScope: BitmapReloadCommitScope | undefined = undefined
    if (target.name === selectedTarget?.name && index === (selectedTarget.currentCostume ?? 0)) {
      captureBitmapReloadBarrierForSlot(wantId, index)
      try {
        preReloadScope = captureBitmapReloadCommitScope(wantId, index)
      } catch {
        preReloadScope = undefined
      }
    }
    try {
      await vm.updateCostume(
        target.name,
        index,
        {
          dataFormat: 'png',
          bitmapResolution: pending.bitmapResolution,
          rotationCenterX: pending.rotationCenterX,
          rotationCenterY: pending.rotationCenterY,
        },
        pending.bytes,
      )
    } catch (error) {
      if (!preReloadScope || (preReloadScope && bitmapPendingCommitBarrier === preReloadScope.barrier)) clearBitmapReloadBarrier()
      clearBitmapReloadSkip()
      await reconcileDeferredBitmapReload()
      throw error
    }
    const preReloadScopeCurrent = preReloadScope ? isBitmapReloadCommitScopeCurrent(preReloadScope) : true
    if (preReloadScope && !preReloadScopeCurrent) {
      clearBitmapReloadSkip()
      if (bitmapPendingCommitBarrier === preReloadScope.barrier) clearBitmapReloadBarrier()
      await reconcileDeferredBitmapReload()
      refuseStaleBitmapWorkspace('Bitmap save')
      return false
    }
    if (!preReloadScope || (preReloadScope && bitmapPendingCommitBarrier === preReloadScope.barrier)) clearBitmapReloadBarrier()
    // Proven own write: arm the versioned skip from fresh live (unpredictable
    // new md5 is re-read here, never guessed before the await).
    armBitmapReloadSkipFromLive(wantId, index)
    await reconcileDeferredBitmapReload()
    // Persist the center bookkeeping only after the write lands, so a failed
    // write never advances the baseline a later save measures its drag delta
    // against. Pure re-saves then reproduce the center exactly (idempotent
    // Save pushes no empty Undo entry via the caller's noop guard).
    bitmapArtboardCenterOffset = { x: pending.centerOffsetX, y: pending.centerOffsetY }
    bitmapArtboardPlacementCenter = { x: pending.rotationCenterX, y: pending.rotationCenterY }
    // The stored asset key changed: refresh the workspace owner so an
    // immediate second save still matches its own canvas. Read the fresh
    // costume from the VM (the `target` snapshot predates the write), then
    // re-baseline the paint slot identity so the CAS Undo pre-check sees
    // this own write instead of mistaking it for an external change.
    if (bitmapWorkspaceOwner && bitmapWorkspaceOwner.targetId === wantId && bitmapWorkspaceOwner.index === index) {
      const fresh = (vectorWriteTargetById(wantId, target.name) ?? vm.getTarget(wantId) ?? vm.getTarget(target.name))?.costumes[index] ?? target.costumes[index]
      bitmapWorkspaceOwner = { ...bitmapWorkspaceOwner, assetKey: fresh?.md5ext ?? fresh?.assetId ?? bitmapWorkspaceOwner.assetKey }
    }
    rememberPaintKnown(wantId, index, readLiveSlotIdentity(wantId, index))
    return true
  }

  async function updateBitmapCostumeFromCanvas(target: ScratchTarget, index: number, source: HTMLCanvasElement) {
    // Legacy verbatim entry kept for non-interactive callers: route through
    // the cropped artboard save so stored bytes/center stay world-stable.
    // Fully transparent canvases mirror saveBitmapCostume: no-op when the
    // stored asset is already transparent, minimal transparent write when
    // real ink was deleted (nudge previews never hit this: they move ink).
    // Refused (over-budget) workspaces never write: the asset stays untouched.
    // Owner gate: only the selected asset may be written; stale cross-target
    // writes safely cancel with no history entry.
    if (isBitmapEditRefused() && source === bitmapCanvas) {
      status = 'Image too large to edit safely — original kept unchanged'
      return
    }
    if (source === bitmapCanvas) {
      const wantId = stableTargetId(target)
      if (!selectedTarget || stableTargetId(selectedTarget) !== wantId || (selectedTarget.currentCostume ?? 0) !== index) return
      if (!isBitmapWorkspaceSettledFor(wantId, index)) return
    }
    const pending = await buildCroppedBitmapSave(target, index, source)
    if (isBitmapSaveRefused(pending)) {
      if (source === bitmapCanvas) refuseBitmapOversize()
      return
    }
    if (isBitmapSaveStale(pending)) return
    if (source === bitmapCanvas) {
      const wantId = stableTargetId(target)
      if (!selectedTarget || stableTargetId(selectedTarget) !== wantId || (selectedTarget.currentCostume ?? 0) !== index) return
      if (!isBitmapWorkspaceSettledFor(wantId, index)) return
    }
    if (!pending) {
      if (await storedBitmapHasOpaque(target, index)) {
        if (source === bitmapCanvas) {
          const wantId = stableTargetId(target)
          if (!selectedTarget || stableTargetId(selectedTarget) !== wantId || (selectedTarget.currentCostume ?? 0) !== index) return
          if (!isBitmapWorkspaceSettledFor(wantId, index)) return
          if (isBitmapSourceSizeRefused(source.width, source.height)) {
            refuseBitmapOversize()
            return
          }
        }
        await writeTransparentBitmapSave(target, index)
      }
      return
    }
    await writeCroppedBitmapSave(target, index, pending)
  }

  async function storedBitmapDimensions(target: ScratchTarget, index: number): Promise<{ width: number; height: number } | undefined> {
    try {
      const costume = target.costumes[index]
      const key = costume?.md5ext ?? costume?.assetId
      if (!key) return undefined
      const stored = await vm.loadAsset(key, costume?.dataFormat ?? '')
      if (!stored || stored.length === 0) return undefined
      const type = costume?.dataFormat === 'jpg' || costume?.dataFormat === 'jpeg' ? 'image/jpeg' : 'image/png'
      const url = URL.createObjectURL(new Blob([new Uint8Array(stored)], { type }))
      try {
        const image = new Image()
        await new Promise<void>((resolve, reject) => {
          image.onload = () => resolve()
          image.onerror = reject
          image.src = url
        })
        const width = Math.round(image.naturalWidth || image.width || 0)
        const height = Math.round(image.naturalHeight || image.height || 0)
        return width > 0 && height > 0 ? { width, height } : undefined
      } finally {
        URL.revokeObjectURL(url)
      }
    } catch {
      return undefined
    }
  }

  async function storedBitmapHasOpaque(target: ScratchTarget, index: number): Promise<boolean> {
    try {
      const costume = target.costumes[index]
      const key = costume?.md5ext ?? costume?.assetId
      if (!key) return false
      const stored = await vm.loadAsset(key, costume?.dataFormat ?? '')
      if (!stored || stored.length === 0) return false
      const type = costume?.dataFormat === 'jpg' || costume?.dataFormat === 'jpeg' ? 'image/jpeg' : 'image/png'
      const url = URL.createObjectURL(new Blob([new Uint8Array(stored)], { type }))
      try {
        const image = new Image()
        await new Promise<void>((resolve, reject) => {
          image.onload = () => resolve()
          image.onerror = reject
          image.src = url
        })
        const probe = document.createElement('canvas')
        probe.width = Math.round(image.naturalWidth || image.width || 0)
        probe.height = Math.round(image.naturalHeight || image.height || 0)
        if (!(probe.width > 0 && probe.height > 0)) return false
        const probeContext = probe.getContext('2d')
        if (!probeContext) return false
        probeContext.clearRect(0, 0, probe.width, probe.height)
        probeContext.drawImage(image, 0, 0)
        const pixels = probeContext.getImageData(0, 0, probe.width, probe.height)
        return opaqueTrimFromRgba(pixels.data, pixels.width, pixels.height) !== undefined
      } finally {
        URL.revokeObjectURL(url)
      }
    } catch {
      return false
    }
  }

  async function writeTransparentBitmapSave(target: ScratchTarget, index: number) {
    // Owner gate: transparent deletes must also address the selected asset.
    const wantId = stableTargetId(target)
    if (!selectedTarget || stableTargetId(selectedTarget) !== wantId || (selectedTarget.currentCostume ?? 0) !== index) {
      refuseStaleBitmapWorkspace('Bitmap save')
      return
    }
    if (!isBitmapWorkspaceSettledFor(wantId, index) && bitmapCanvas) {
      refuseStaleBitmapWorkspace('Bitmap save')
      return
    }
    // Minimal fully-transparent asset (1x1) with the rotation center at its
    // top-left corner: reload places the single pixel at the workspace
    // center, and future centered brush strokes crop back world-stable.
    // The stored resolution is preserved so a res1 deletion stays res1.
    const transparentResolution = storedBitmapResolutionOf(target, index)
    const probe = document.createElement('canvas')
    probe.width = 1
    probe.height = 1
    probe.getContext('2d')?.clearRect(0, 0, 1, 1)
    const blob = await new Promise<Blob | null>((resolve) => probe.toBlob(resolve, 'image/png'))
    if (!blob) return
    let preReloadScope: BitmapReloadCommitScope | undefined = undefined
    if (target.name === selectedTarget?.name && index === (selectedTarget.currentCostume ?? 0)) {
      captureBitmapReloadBarrierForSlot(wantId, index)
      try {
        preReloadScope = captureBitmapReloadCommitScope(wantId, index)
      } catch {
        preReloadScope = undefined
      }
    }
    try {
      await vm.updateCostume(
        target.name,
        index,
        { dataFormat: 'png', bitmapResolution: transparentResolution, rotationCenterX: 0, rotationCenterY: 0 },
        new Uint8Array(await blob.arrayBuffer()),
      )
    } catch (error) {
      if (!preReloadScope || (preReloadScope && bitmapPendingCommitBarrier === preReloadScope.barrier)) clearBitmapReloadBarrier()
      clearBitmapReloadSkip()
      await reconcileDeferredBitmapReload()
      throw error
    }
    {
      const preReloadScopeCurrent = preReloadScope ? isBitmapReloadCommitScopeCurrent(preReloadScope) : true
      if (preReloadScope && !preReloadScopeCurrent) {
        clearBitmapReloadSkip()
        if (bitmapPendingCommitBarrier === preReloadScope.barrier) clearBitmapReloadBarrier()
        await reconcileDeferredBitmapReload()
        return
      }
      if (!preReloadScope || (preReloadScope && bitmapPendingCommitBarrier === preReloadScope.barrier)) clearBitmapReloadBarrier()
    }
    armBitmapReloadSkipFromLive(wantId, index)
    await reconcileDeferredBitmapReload()
    bitmapArtboardCenterOffset = { x: 0, y: 0 }
    bitmapArtboardPlacementCenter = { x: 0, y: 0 }
    if (bitmapWorkspaceOwner && bitmapWorkspaceOwner.targetId === wantId && bitmapWorkspaceOwner.index === index) {
      const fresh = (vectorWriteTargetById(wantId, target.name) ?? vm.getTarget(wantId) ?? vm.getTarget(target.name))?.costumes[index] ?? target.costumes[index]
      bitmapWorkspaceOwner = { ...bitmapWorkspaceOwner, assetKey: fresh?.md5ext ?? fresh?.assetId ?? bitmapWorkspaceOwner.assetKey }
    }
    rememberPaintKnown(wantId, index, readLiveSlotIdentity(wantId, index))
  }

  async function rasterizeSvgToBitmapSize(bytes: Uint8Array, width: number, height: number) {
    // 1:1 conversion raster (clean-room, no reference copy): sanitized SVG
    // bytes -> <img> -> canvas sized to SVG units x resolution. Transparency
    // (clearRect, no fill), translucency (alpha-preserving drawImage/PNG),
    // clipping (SVG viewport clip scales with the draw), and empty SVGs
    // (transparent placeholder raster) all ride the browser <img> path.
    const safeWidth = Number.isFinite(width) && width > 0 ? Math.round(width) : 1
    const safeHeight = Number.isFinite(height) && height > 0 ? Math.round(height) : 1
    const body = svgWithCrispRendering(bytes)
    const url = URL.createObjectURL(new Blob([body], { type: 'image/svg+xml' }))
    try {
      const image = new Image()
      await new Promise<void>((resolve, reject) => {
        image.onload = () => resolve()
        image.onerror = reject
        image.src = url
      })
      const canvas = document.createElement('canvas')
      canvas.width = safeWidth
      canvas.height = safeHeight
      const context = canvas.getContext('2d')
      if (!context) return undefined
      context.imageSmoothingEnabled = true
      context.clearRect(0, 0, safeWidth, safeHeight)
      context.drawImage(image, 0, 0, safeWidth, safeHeight)
      return canvas
    } finally {
      URL.revokeObjectURL(url)
    }
  }

  /** Fail-closed canvas encode: null/empty/throw (huge-side toBlob null included) never throws. */
  function encodeCanvasToPngBlob(canvas: HTMLCanvasElement): Promise<Blob | null> {
    return new Promise<Blob | null>((resolve) => {
      try {
        canvas.toBlob(resolve, 'image/png')
      } catch {
        resolve(null)
      }
    }).then(
      (blob) => (blob && blob.size > 0 ? blob : null),
      () => null,
    )
  }

  async function bitmapTrimmedDataUrl(source: HTMLCanvasElement, trim: { x: number; y: number; width: number; height: number }) {
    try {
      if (isConversionRasterSizeRefused(trim.width, trim.height)) return ''
      if (isConversionRasterSizeRefused(source.width, source.height)) return ''
      const cropped = document.createElement('canvas')
      cropped.width = trim.width
      cropped.height = trim.height
      const context = cropped.getContext('2d')
      if (!context) return ''
      try {
        context.drawImage(source, trim.x, trim.y, trim.width, trim.height, 0, 0, trim.width, trim.height)
      } catch {
        return ''
      }
      const blob = await encodeCanvasToPngBlob(cropped)
      if (!blob) return ''
      return `data:image/png;base64,${bytesToLocalBase64(new Uint8Array(await blob.arrayBuffer()))}`
    } catch {
      return ''
    }
  }

  function svgWithCrispRendering(bytes: Uint8Array) {
    // Rasterize boundary: sanitize untrusted/persisted SVG bytes before they
    // reach the blob-URL + <img> bitmap path. Persisted bytes are normally
    // VM-sanitized, but this path must not trust that implicitly: a future
    // loader change (or a non-<img> draw path) would otherwise inherit remote
    // fetches (`<image href="https://...">`, `url(...)`, `image-set(...)`).
    // `sanitizeSvgForDisplay` preserves allowlisted paint (local gradients,
    // embedded PNG data:, transforms, sizes) while stripping remote vectors
    // fail-closed; the constant `crispEdges` write afterwards is trusted.
    const text = new TextDecoder().decode(bytes)
    const clean = sanitizeSvgForDisplay(text)
    if (clean === SVG_PLACEHOLDER) return new TextEncoder().encode(clean)
    const doc = new DOMParser().parseFromString(clean, 'image/svg+xml')
    const svg = doc.documentElement
    if (svg.nodeName.toLowerCase() !== 'svg' || doc.getElementsByTagName('parsererror').length > 0) {
      return new TextEncoder().encode(clean)
    }
    svg.setAttribute('shape-rendering', 'crispEdges')
    return new TextEncoder().encode(new XMLSerializer().serializeToString(svg))
  }

  function trimmedBitmapBounds(source: HTMLCanvasElement) {
    const context = source.getContext('2d')
    if (!context) return undefined
    const image = context.getImageData(0, 0, source.width, source.height)
    let left = source.width
    let top = source.height
    let right = -1
    let bottom = -1
    for (let y = 0; y < source.height; y += 1) {
      for (let x = 0; x < source.width; x += 1) {
        if ((image.data[(y * source.width + x) * 4 + 3] ?? 0) === 0) continue
        left = Math.min(left, x)
        top = Math.min(top, y)
        right = Math.max(right, x)
        bottom = Math.max(bottom, y)
      }
    }
    return right >= left ? { x: left, y: top, width: right - left + 1, height: bottom - top + 1 } : undefined
  }

  async function convertCurrentCostumeToBitmap() {
    if (!selectedTarget) return
    try {
      const pendingSession = ensureBitmapPendingController()?.get()
      if (pendingSession) {
        let snap: { hasPending: boolean; commitInFlight: boolean } | undefined
        try {
          snap = pendingSession.snapshot()
        } catch {
          return
        }
        if (snap && (snap.hasPending || snap.commitInFlight)) {
          const ok = await guardBitmapPendingCommitFirst('convert-to-bitmap')
          if (!ok) return
        }
      }
    } catch {
      return
    }
    await flushHsvLive()
    const targetId = stableTargetId(selectedTarget)
    const index = selectedTarget.currentCostume ?? 0
    const costume = selectedTarget.costumes[index]
    const key = costume?.md5ext ?? costume?.assetId
    const bytes = key ? await vm.loadAsset(key, costume.dataFormat ?? '') : undefined
    if (!costume || !bytes) return
    // No-op: already a bitmap (source bytes stay untouched, no history).
    if ((costume.dataFormat ?? '') !== 'svg') {
      status = 'Already a bitmap costume'
      return
    }
    // Same-costume conversion: the slot keeps its scope, so history is
    // preserved. Guard the async rasterize: a switch mid-conversion aborts
    // instead of writing converted bytes into the newly selected costume.
    // History is captured only after a successful raster (failures and
    // no-ops stay undo-clean).
    const scopeKey = paintScopeKey
    const scopeGeneration = paintScopeGeneration
    // Preserve the VM stage appearance (scratch-unit bounds + rotation
    // center): the bitmap is sized to SVG units x resolution (sprite 2x,
    // stage 1x) with the center scaled by the same factor, so W/R and cx/R
    // are invariant. This replaces the previous fixed 2400x1800 workspace
    // stretch (96x96 sprite -> 1200x900 scratch units, center unscaled).
    const svgText = new TextDecoder().decode(bytes)
    const geometry = parseConversionSvgGeometry(svgText, selectedTarget.isStage)
    const spec = resolveVectorToBitmapSpec({
      svgWidth: geometry.width,
      svgHeight: geometry.height,
      rotationCenterX: costume.rotationCenterX,
      rotationCenterY: costume.rotationCenterY,
      isStage: selectedTarget.isStage,
    })
    // Over-cap conversions refuse before allocating/history/writes.
    if (isVectorToBitmapSpecRefused(spec)) {
      refuseBitmapOversize()
      return
    }
    const canvas = await rasterizeSvgToBitmapSize(bytes, spec.bitmapWidth, spec.bitmapHeight)
    if (!canvas || isConversionRasterSizeRefused(canvas.width, canvas.height)) {
      // Unreachable for over-cap specs (refused above), but fail closed.
      if (canvas) refuseBitmapOversize()
      return
    }
    if (paintScopeKey !== scopeKey || paintScopeGeneration !== scopeGeneration) return
    const liveTarget = vm.getTarget(targetId)
    if (!liveTarget || stableTargetId(liveTarget) !== targetId) return
    if ((liveTarget.currentCostume ?? 0) !== index) return
    // Encode before history: failed encodes stay undo-clean.
    const blob = await encodeCanvasToPngBlob(canvas)
    if (!blob) {
      refuseBitmapOversize()
      return
    }
    // Post-encode gate: a switch/undo during toBlob must not write converted
    // bytes into the newly selected costume.
    if (paintScopeKey !== scopeKey || paintScopeGeneration !== scopeGeneration) return
    {
      const cur = vm.getTarget(targetId)
      if (!cur || stableTargetId(cur) !== targetId) return
      if ((cur.currentCostume ?? 0) !== index) return
    }
    if (!selectedTarget || stableTargetId(selectedTarget) !== targetId || (selectedTarget.currentCostume ?? 0) !== index) return
    await captureCostumeHistory(selectedTarget, index)
    if (paintScopeKey !== scopeKey || paintScopeGeneration !== scopeGeneration) return
    const liveTargetAfterHistory = vm.getTarget(targetId)
    if (!liveTargetAfterHistory || stableTargetId(liveTargetAfterHistory) !== targetId) return
    if ((liveTargetAfterHistory.currentCostume ?? 0) !== index) return
    let preReloadScope: BitmapReloadCommitScope | undefined = undefined
    if (liveTargetAfterHistory.name === selectedTarget?.name && index === (selectedTarget.currentCostume ?? 0)) {
      captureBitmapReloadBarrierForSlot(targetId, index)
      try {
        preReloadScope = captureBitmapReloadCommitScope(targetId, index)
      } catch {
        preReloadScope = undefined
      }
    }
    try {
      await vm.updateCostume(
        liveTargetAfterHistory.name,
        index,
        {
          dataFormat: 'png',
          bitmapResolution: spec.bitmapResolution,
          rotationCenterX: spec.rotationCenterX,
          rotationCenterY: spec.rotationCenterY,
        },
        new Uint8Array(await blob.arrayBuffer()),
      )
    } catch (error) {
      if (!preReloadScope || (preReloadScope && bitmapPendingCommitBarrier === preReloadScope.barrier)) clearBitmapReloadBarrier()
      clearBitmapReloadSkip()
      await reconcileDeferredBitmapReload()
      throw error
    }
    {
      const preReloadScopeCurrent = preReloadScope ? isBitmapReloadCommitScopeCurrent(preReloadScope) : true
      if (preReloadScope && !preReloadScopeCurrent) {
        clearBitmapReloadSkip()
        if (bitmapPendingCommitBarrier === preReloadScope.barrier) clearBitmapReloadBarrier()
        await reconcileDeferredBitmapReload()
        return
      }
      if (!preReloadScope || (preReloadScope && bitmapPendingCommitBarrier === preReloadScope.barrier)) clearBitmapReloadBarrier()
    }
    armBitmapReloadSkipFromLive(targetId, index)
    await reconcileDeferredBitmapReload()
    if (bitmapCanvas) {
      const placed = placeSourceOnArtboard(spec.bitmapWidth, spec.bitmapHeight, spec.rotationCenterX, spec.rotationCenterY, selectedTarget.isStage, spec.bitmapResolution)
      if (placed.refused) {
        // Fail closed: bytes are stored, so mark the live workspace refused.
        bitmapArtboard = { originX: 0, originY: 0, canvasCenterX: placed.canvasCenterX, canvasCenterY: placed.canvasCenterY, isStage: selectedTarget.isStage, width: bitmapCanvas.width, height: bitmapCanvas.height, resolution: spec.bitmapResolution, refused: true }
        bitmapArtboardPlacementCenter = { x: spec.rotationCenterX, y: spec.rotationCenterY }
        bitmapArtboardCenterOffset = { x: 0, y: 0 }
        {
          const converted = vm.getTarget(targetId)?.costumes[index]
          bitmapWorkspaceGeneration += 1
          bitmapWorkspaceOwner = {
            targetId,
            index,
            assetKey: converted?.md5ext ?? converted?.assetId ?? '',
            loadSerial: bitmapCanvasReloadSerial,
            generation: bitmapWorkspaceGeneration,
            revision: assetPreviewRevision,
          }
          bitmapStrokeOwner = undefined
          rememberPaintKnown(targetId, index, readLiveSlotIdentity(targetId, index))
        }
        refuseBitmapOversize()
        return
      } else {
        resizeBitmapCanvas(placed.width, placed.height)
        bitmapArtboard = { originX: placed.originX, originY: placed.originY, canvasCenterX: placed.canvasCenterX, canvasCenterY: placed.canvasCenterY, isStage: selectedTarget.isStage, width: placed.width, height: placed.height, resolution: placed.resolution, refused: false }
      bitmapArtboardPlacementCenter = { x: spec.rotationCenterX, y: spec.rotationCenterY }
      bitmapArtboardCenterOffset = { x: 0, y: 0 }
      // Let the `width={bitmapCanvasWidth}` binding land before drawing:
      // Chrome resets the raster even on a same-value `width` assignment, so
      // drawing before Svelte flushes the resized binding would be wiped.
      await tick()
      if (paintScopeKey !== scopeKey || paintScopeGeneration !== scopeGeneration) return
      // The tick yields to user input: only draw when the editor still shows
      // the converted costume (otherwise the reactive refresh for the new
      // selection loads the correct bytes).
      if (!selectedTarget || stableTargetId(selectedTarget) !== targetId) return
      if ((selectedTarget.currentCostume ?? 0) !== index) return
      const context = bitmapCanvas.getContext('2d')
      context?.clearRect(0, 0, bitmapCanvas.width, bitmapCanvas.height)
      context?.drawImage(canvas, placed.originX, placed.originY)
      // Workspace owner gate: the versioned skip (armed above) means no load
      // will follow, so commit the owner here. Otherwise
      // the canvas would show the converted asset while the owner still names
      // the pre-conversion bytes and every later paint/save would be refused.
      // The stored key is read after the write above, so immediate re-saves
      // stay settled.
      {
        const converted = vm.getTarget(targetId)?.costumes[index]
        bitmapWorkspaceGeneration += 1
        bitmapWorkspaceOwner = {
          targetId,
          index,
          assetKey: converted?.md5ext ?? converted?.assetId ?? '',
          loadSerial: bitmapCanvasReloadSerial,
          generation: bitmapWorkspaceGeneration,
          revision: assetPreviewRevision,
        }
        bitmapStrokeOwner = undefined
        rememberPaintKnown(targetId, index, readLiveSlotIdentity(targetId, index))
      }
      }
    }
    status = 'Converted to bitmap'
  }

  async function convertCurrentCostumeToVector() {
    if (!selectedTarget || !bitmapCanvas) return
    try {
      const pendingSession = ensureBitmapPendingController()?.get()
      if (pendingSession) {
        let snap: { hasPending: boolean; commitInFlight: boolean } | undefined
        try {
          snap = pendingSession.snapshot()
        } catch {
          return
        }
        if (snap && (snap.hasPending || snap.commitInFlight)) {
          const ok = await guardBitmapPendingCommitFirst('convert-to-vector')
          if (!ok) return
        }
      }
    } catch {
      return
    }
    if (isBitmapEditRefused()) {
      refuseBitmapOversize()
      return
    }
    {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        refuseStaleBitmapWorkspace('Bitmap convert')
        return
      }
    }
    await flushHsvLive()
    const targetId = stableTargetId(selectedTarget)
    const index = selectedTarget.currentCostume ?? 0
    const costume = selectedTarget.costumes[index]
    if (!costume) return
    if (!isBitmapWorkspaceSettledFor(targetId, index)) {
      refuseStaleBitmapWorkspace('Bitmap convert')
      return
    }
    // No-op: already a vector (no history, source bytes untouched).
    if ((costume.dataFormat ?? '') === 'svg') {
      status = 'Already a vector costume'
      return
    }
    const scopeKey = paintScopeKey
    const scopeGeneration = paintScopeGeneration
    // Preserve the VM stage appearance: the vector is sized to the drawing
    // bounds (trimmed opaque pixels / resolution, 1:1) with the center
    // shifted by the trim origin, so scratch-unit ink position and bounds are
    // invariant. Legacy full-bleed 2400 canvases therefore stay (compatibly)
    // oversized instead of jumping; correctly sized assets shrink to their
    // 1:1 bounds. Fully transparent (empty: no opaque pixel anywhere) sizes
    // from the STORED asset dims/center (not the artboard workspace), so an
    // empty round-trip keeps its geometry (transparent 192x192 -> 96x96
    // vector) instead of blowing up to the 480x360 artboard bounds.
    const sourceResolution =
      costume.bitmapResolution && Number.isFinite(costume.bitmapResolution) && costume.bitmapResolution > 0
        ? costume.bitmapResolution
        : selectedTarget.isStage ? 1 : 2
    // Over-cap live surfaces can never encode faithfully: refuse before any
    // read/encode/history/write, with the stored PNG bytes untouched. This
    // also covers the silent-blank raster (a blank live canvas over stored
    // ink would otherwise persist as an empty SVG, destroying the asset).
    if (isBitmapToVectorSourceRefused(bitmapCanvas.width, bitmapCanvas.height)) {
      refuseBitmapOversize()
      return
    }
    let trim: { x: number; y: number; width: number; height: number } | undefined
    try {
      trim = trimmedBitmapBounds(bitmapCanvas)
    } catch {
      refuseBitmapOversize()
      return
    }
    if (trim && isBitmapToVectorSourceRefused(bitmapCanvas.width, bitmapCanvas.height, trim)) {
      refuseBitmapOversize()
      return
    }
    // Artboard placement via the shared helper: stored center (asset px)
    // maps onto the live canvas through the tracked origin; a fully
    // transparent canvas falls back to the decoded stored dims/center so
    // empty round-trips keep their geometry instead of blowing up to the
    // artboard bounds.
    const artIsStage = selectedTarget.isStage
    const artTrack = liveBitmapArtboard()
    if (!isBitmapWorkspaceSettledFor(targetId, index)) {
      refuseStaleBitmapWorkspace('Bitmap convert')
      return
    }
    if (!selectedTarget || stableTargetId(selectedTarget) !== targetId || (selectedTarget.currentCostume ?? 0) !== index) return
    // Blank live canvas with stored ink means the raster cannot hold the
    // pixels (silent-blank refusal the static caps missed): an empty SVG
    // here would destroy the stored asset, so refuse with bytes untouched.
    // A genuinely transparent stored asset still converts to an empty
    // (transparent) vector, preserving the empty round-trip geometry.
    let storedSize: { width: number; height: number } | undefined
    if (!trim) {
      storedSize = await storedBitmapDimensions(selectedTarget, index)
      if (paintScopeKey !== scopeKey || paintScopeGeneration !== scopeGeneration) return
      if (!selectedTarget || stableTargetId(selectedTarget) !== targetId || (selectedTarget.currentCostume ?? 0) !== index) return
      if (!isBitmapWorkspaceSettledFor(targetId, index)) {
        refuseStaleBitmapWorkspace('Bitmap convert')
        return
      }
      if (storedSize && (await storedBitmapHasOpaque(selectedTarget, index))) {
        if (paintScopeKey !== scopeKey || paintScopeGeneration !== scopeGeneration) return
        if (!selectedTarget || stableTargetId(selectedTarget) !== targetId || (selectedTarget.currentCostume ?? 0) !== index) return
        refuseBitmapOversize()
        return
      }
    }
    if (paintScopeKey !== scopeKey || paintScopeGeneration !== scopeGeneration) return
    if (!selectedTarget || stableTargetId(selectedTarget) !== targetId || (selectedTarget.currentCostume ?? 0) !== index) return
    if (!isBitmapWorkspaceSettledFor(targetId, index)) {
      refuseStaleBitmapWorkspace('Bitmap convert')
      return
    }
    const fallbackArtVector = artboardForTarget(artIsStage, sourceResolution)
    const placement = resolveBitmapVectorConvertPlacement({
      trim: trim ?? undefined,
      storedWidth: storedSize?.width,
      storedHeight: storedSize?.height,
      storedCenterX: costume.rotationCenterX,
      storedCenterY: costume.rotationCenterY,
      liveWidth: bitmapCanvas.width,
      liveHeight: bitmapCanvas.height,
      artCenterX: artTrack.isStage === artIsStage ? artTrack.canvasCenterX : fallbackArtVector.centerX,
      artCenterY: artTrack.isStage === artIsStage ? artTrack.canvasCenterY : fallbackArtVector.centerY,
      artOriginX: artTrack.isStage === artIsStage ? artTrack.originX : 0,
      artOriginY: artTrack.isStage === artIsStage ? artTrack.originY : 0,
    })
    const spec = resolveBitmapToVectorSpec({
      canvasWidth: placement.canvasWidth,
      canvasHeight: placement.canvasHeight,
      trim: trim ?? undefined,
      rotationCenterX: placement.rotationCenterX,
      rotationCenterY: placement.rotationCenterY,
      bitmapResolution: sourceResolution,
    })
    let href = ''
    if (spec.image) {
      href = await bitmapTrimmedDataUrl(bitmapCanvas, trim!)
      if (paintScopeKey !== scopeKey || paintScopeGeneration !== scopeGeneration) return
      if (!selectedTarget || stableTargetId(selectedTarget) !== targetId || (selectedTarget.currentCostume ?? 0) !== index) return
      if (!isBitmapWorkspaceSettledFor(targetId, index)) {
        refuseStaleBitmapWorkspace('Bitmap convert')
        return
      }
      // A failed trim encode (null/empty blob, e.g. huge-side toBlob null)
      // must refuse with the stored bytes untouched — never an empty SVG
      // under a success status.
      if (!href) {
        refuseBitmapOversize()
        return
      }
    }
    const rawSvg = buildConvertedVectorSvg(spec, href)
    if (!rawSvg) return
    // Rasterize boundary: the generated markup is allowlisted data: + geometry
    // only, but still round it through the display sanitizer fail-closed (no
    // external href/url()/image-set(), no network) before persisting.
    const cleanSvg = sanitizeSvgForDisplay(rawSvg)
    if (!cleanSvg || cleanSvg === SVG_PLACEHOLDER) return
    if (paintScopeKey !== scopeKey || paintScopeGeneration !== scopeGeneration) return
    const liveTarget = vm.getTarget(targetId)
    if (!liveTarget || stableTargetId(liveTarget) !== targetId) return
    if ((liveTarget.currentCostume ?? 0) !== index) return
    await captureCostumeHistory(selectedTarget, index)
    if (paintScopeKey !== scopeKey || paintScopeGeneration !== scopeGeneration) return
    const liveTargetAfterHistory = vm.getTarget(targetId)
    if (!liveTargetAfterHistory || stableTargetId(liveTargetAfterHistory) !== targetId) return
    if ((liveTargetAfterHistory.currentCostume ?? 0) !== index) return
    await vm.updateCostume(liveTargetAfterHistory.name, index, {
      dataFormat: 'svg',
      bitmapResolution: 1,
      rotationCenterX: spec.rotationCenterX,
      rotationCenterY: spec.rotationCenterY,
    }, new TextEncoder().encode(cleanSvg))
    vectorObjects = await paperVectorObjectList(cleanSvg)
    rememberPaintKnown(targetId, index, readLiveSlotIdentity(targetId, index))
    status = 'Converted to vector'
  }

  async function flipBitmap(horizontal: boolean) {
    // Pending block: the staged shape owns the selection outline; a commit
    // would clear it, so the original flip box cannot be preserved safely.
    // Block BEFORE any selection/canvas mutation (no commit, no history),
    // retained until Escape (commit) or Delete (discard). Disabled path
    // stays await-free.
    if (BITMAP_PENDING_UI_ENABLED && costumeEditMode === 'bitmap') {
      try {
        const flipPendingSession = ensureBitmapPendingController()?.get()
        if (flipPendingSession && flipPendingSession.snapshot().hasPending) {
          status =
            'Bitmap flip blocked (pending shape not committed; press Escape to commit or Delete to discard first; pending retained)'
          return
        }
      } catch {
        status = 'Bitmap flip blocked (pending state unreadable; op blocked, original preserved)'
        return
      }
      const flipEpochTargetId = selectedTarget ? stableTargetId(selectedTarget) : ''
      const flipEpochIndex = selectedTarget?.currentCostume ?? 0
      const flipEpochSerial = bitmapCanvasReloadSerial
      const flipEpochGeneration = bitmapWorkspaceGeneration
      const flipEpochCanvas = bitmapCanvas
      const flipEpochRect = bitmapSelection ? { ...bitmapSelection } : undefined
      const flipEpochScope = selectedTarget ? captureDiscreteSaveScope(flipEpochTargetId, flipEpochIndex) : undefined
      const flipOk = await guardBitmapPendingCommitFirst('paint-flip')
      if (!flipOk) return
      const flipLiveId = selectedTarget ? stableTargetId(selectedTarget) : ''
      if (flipLiveId !== flipEpochTargetId || (selectedTarget?.currentCostume ?? 0) !== flipEpochIndex) {
        status = 'Bitmap flip blocked (target switched during pending commit; original preserved)'
        return
      }
      if (bitmapCanvasReloadSerial !== flipEpochSerial || bitmapWorkspaceGeneration !== flipEpochGeneration || bitmapCanvas !== flipEpochCanvas) {
        status = 'Bitmap flip blocked (canvas reloaded during pending commit; original preserved)'
        return
      }
      if (flipEpochScope && !isDiscreteSaveScopeCurrent(flipEpochScope, discreteSaveLiveOf(flipEpochScope))) {
        status = 'Bitmap flip blocked (workspace changed during pending commit; original preserved)'
        return
      }
      // The commit clears the staged outline; restore the captured box so the
      // flip lands on the intended selection instead of the whole canvas.
      if (!bitmapSelection && flipEpochRect && flipEpochRect.width > 0 && flipEpochRect.height > 0) bitmapSelection = { ...flipEpochRect }
    }
    if (selectedTarget && costumeEditMode === 'bitmap') {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        refuseStaleBitmapWorkspace('Bitmap flip')
        return
      }
    }
    if (bitmapFloatingDragActive() && costumeEditMode === 'bitmap') {
      status = 'Finish the bitmap selection drag first'
      return
    }
    if (isBitmapEditRefused()) {
      status = 'Image too large to edit safely — original kept unchanged'
      return
    }
    const context = bitmapCanvas?.getContext('2d')
    if (!context) return
    // A selection flips in place through the floating session (source-over
    // stamp on the punched base, one history entry); without a selection the
    // whole canvas flips as before.
    if (costumeEditMode === 'bitmap' && bitmapCanvas && bitmapSelection) {
      const live = context.getImageData(0, 0, bitmapCanvas.width, bitmapCanvas.height)
      const session = beginBitmapFloatingSession(live, bitmapSelection)
      if (!session) {
        status = 'Bitmap flip: no change'
        return
      }
      const flipped = flipBitmapFloatingSession(session, horizontal ? { horizontal: true } : { vertical: true })
      if (!flipped.changed) {
        status = 'Bitmap flip: no change'
        return
      }
      const preview = renderBitmapFloatingSession(session, session.sourceRect.x, session.sourceRect.y)
      if (!preview.changed) {
        status = 'Bitmap flip: no change'
        return
      }
      context.putImageData(floatingImageToImageData(preview.image), 0, 0)
      await saveBitmapCostume(horizontal ? 'Bitmap horizontal flip saved' : 'Bitmap vertical flip saved')
      status = horizontal ? 'Bitmap flipped horizontally' : 'Bitmap flipped vertically'
      return
    }
    const image = context.getImageData(0, 0, bitmapCanvas.width, bitmapCanvas.height)
    const copy = new ImageData(bitmapCanvas.width, bitmapCanvas.height)
    for (let y = 0; y < bitmapCanvas.height; y += 1) {
      for (let x = 0; x < bitmapCanvas.width; x += 1) {
        const sourceX = horizontal ? bitmapCanvas.width - 1 - x : x
        const sourceY = horizontal ? y : bitmapCanvas.height - 1 - y
        const source = (sourceY * bitmapCanvas.width + sourceX) * 4
        const dest = (y * bitmapCanvas.width + x) * 4
        copy.data[dest] = image.data[source] ?? 0
        copy.data[dest + 1] = image.data[source + 1] ?? 0
        copy.data[dest + 2] = image.data[source + 2] ?? 0
        copy.data[dest + 3] = image.data[source + 3] ?? 0
      }
    }
    context.putImageData(copy, 0, 0)
    await saveBitmapCostume(horizontal ? 'Bitmap horizontal flip saved' : 'Bitmap vertical flip saved')
    status = horizontal ? 'Bitmap flipped horizontally' : 'Bitmap flipped vertically'
  }

  async function rotateBitmap(clockwise: boolean) {
    if (selectedTarget && costumeEditMode === 'bitmap') {
      const gid = stableTargetId(selectedTarget)
      const gidx = selectedTarget.currentCostume ?? 0
      if (!isBitmapWorkspaceSettledFor(gid, gidx)) {
        refuseStaleBitmapWorkspace('Bitmap rotate')
        return
      }
    }
    if ((bitmapFloatingDragActive() || bitmapPendingTransformDragActive()) && costumeEditMode === 'bitmap') {
      status = 'Finish the bitmap selection drag first'
      return
    }
    // Pending staged rect/oval owns the rotate buttons: parametric `rotate90`
    // about the shape center (frozen base + single-pass repaint, no history,
    // no VM, no `saveBitmapCostume`). The legacy floating raster path is
    // never used while staged.
    if (BITMAP_PENDING_UI_ENABLED && costumeEditMode === 'bitmap' && (bitmapTool === 'rect' || bitmapTool === 'oval')) {
      try {
        const pendingForRotate = ensureBitmapPendingController()?.get()
        if (pendingForRotate && pendingForRotate.snapshot().hasPending) {
          const result = pendingForRotate.rotate90(clockwise ? 'cw' : 'ccw')
          if (!result.ok) {
            const reason = (result as { reason?: string }).reason ?? 'refused'
            if (reason === 'owner-mismatch' || reason === 'superseded' || reason === 'invalid-scope') {
              status = 'live canvas left untouched (draft owner changed or uncertain; reloader owns pixels)'
            } else {
              status = `Bitmap rotate: no change (${reason})`
            }
            return
          }
          if (result.kind === 'unchanged') {
            status = 'Bitmap rotate: no change'
            return
          }
          status = clockwise ? 'Bitmap rotated right' : 'Bitmap rotated left'
          return
        }
      } catch {
        status = 'Bitmap rotate: no change (internal error); original preserved'
        return
      }
    }
    if (isBitmapEditRefused()) {
      status = 'Image too large to edit safely — original kept unchanged'
      return
    }
    const context = bitmapCanvas?.getContext('2d')
    if (!context || !bitmapCanvas) return
    // A selection rotates in place (centered 90-degree turn through the
    // floating session, one history entry, canvas size untouched); without a
    // selection the whole canvas rotates as before (which swaps its size).
    if (costumeEditMode === 'bitmap' && bitmapSelection) {
      const live = context.getImageData(0, 0, bitmapCanvas.width, bitmapCanvas.height)
      const session = beginBitmapFloatingSession(live, bitmapSelection)
      if (!session) {
        status = 'Bitmap rotate: no change'
        return
      }
      const rotated = rotateBitmapFloatingSession(session, clockwise ? 90 : -90)
      if (!rotated.changed) {
        status = 'Bitmap rotate: no change'
        return
      }
      const dest = centeredBitmapFloatingDest(session.sourceRect, session.patch.width, session.patch.height)
      const preview = renderBitmapFloatingSession(session, dest.x, dest.y)
      if (!preview.changed) {
        status = 'Bitmap rotate: no change'
        return
      }
      context.putImageData(floatingImageToImageData(preview.image), 0, 0)
      bitmapSelection = { x: dest.x, y: dest.y, width: session.patch.width, height: session.patch.height }
      await saveBitmapCostume(clockwise ? 'Bitmap rotated right saved' : 'Bitmap rotated left saved')
      status = clockwise ? 'Bitmap rotated right' : 'Bitmap rotated left'
      return
    }
    const source = document.createElement('canvas')
    source.width = bitmapCanvas.width
    source.height = bitmapCanvas.height
    source.getContext('2d')?.putImageData(context.getImageData(0, 0, bitmapCanvas.width, bitmapCanvas.height), 0, 0)
    const rotateTrack = liveBitmapArtboard()
    const rotateCcX = rotateTrack.canvasCenterX
    const rotateCcY = rotateTrack.canvasCenterY
    const rotateOriginX = rotateTrack.originX
    const rotateOriginY = rotateTrack.originY
    const rotateIsStage = rotateTrack.isStage
    const rotateResolution = rotateTrack.resolution > 0 ? rotateTrack.resolution : rotateIsStage ? 1 : 2
    const rotateTarget = selectedTarget ? stableTargetId(selectedTarget) : ''
    const rotateIndex = selectedTarget?.currentCostume ?? 0
    resizeBitmapCanvas(source.height, source.width)
    // Same binding race as conversion/Undo loads: flush the resized binding
    // before drawing, or the flush wipes the rotated pixels. The source is
    // offscreen (unaffected by the reset); a switch during the tick aborts.
    await tick()
    if (!selectedTarget || stableTargetId(selectedTarget) !== rotateTarget) return
    if ((selectedTarget.currentCostume ?? 0) !== rotateIndex) return
    if (!isBitmapWorkspaceSettledFor(rotateTarget, rotateIndex)) {
      refuseStaleBitmapWorkspace('Bitmap rotate')
      return
    }
    if (!bitmapCanvas) return
    const nextContext = bitmapCanvas.getContext('2d')
    if (!nextContext) return
    nextContext.save()
    if (clockwise) {
      nextContext.translate(bitmapCanvas.width, 0)
      nextContext.rotate(Math.PI / 2)
    } else {
      nextContext.translate(0, bitmapCanvas.height)
      nextContext.rotate(-Math.PI / 2)
    }
    nextContext.drawImage(source, 0, 0)
    nextContext.restore()
    // Whole-canvas rotation around the old center: the world anchor stays at
    // the new canvas center and the tracked origin rotates with the pixels
    // (CW: (vx,vy)->(-vy,vx); CCW: (vx,vy)->(vy,-vx)), so the cropped save
    // keeps the rotated artwork world-stable.
    {
      const newCcX = bitmapCanvas.width / 2
      const newCcY = bitmapCanvas.height / 2
      const vx = rotateOriginX - rotateCcX
      const vy = rotateOriginY - rotateCcY
      const rotated = clockwise ? { x: -vy, y: vx } : { x: vy, y: -vx }
      bitmapArtboard = {
        originX: newCcX + rotated.x,
        originY: newCcY + rotated.y,
        canvasCenterX: newCcX,
        canvasCenterY: newCcY,
        isStage: rotateIsStage,
        width: bitmapCanvas.width,
        height: bitmapCanvas.height,
        resolution: rotateResolution,
        refused: false,
      }
    }
    bitmapSelection = undefined
    await saveBitmapCostume(clockwise ? 'Bitmap rotated right saved' : 'Bitmap rotated left saved')
    status = clockwise ? 'Bitmap rotated right' : 'Bitmap rotated left'
  }

  async function addSound() {
    if (!selectedTarget) return
    selectedSoundIndex = await createBlankSound(selectedTarget.name)
    status = 'Sound added'
  }

  async function createBlankSound(targetName: string) {
    const target = vm.getTarget(targetName)
    const index = target?.sounds.length ?? 0
    const bytes = floatSamplesToWav(new Float32Array(Math.floor(44100 * 0.5)), 44100)
    const asset = await vm.storeAsset(bytes, 'wav')
    vm.addSound(targetName, {
      name: `sound${index + 1}`,
      dataFormat: 'wav',
      assetId: asset.assetId,
      md5ext: asset.md5ext,
      format: '',
      rate: 44100,
      sampleCount: Math.max(0, Math.floor((bytes.length - 44) / 2)),
    })
    return index
  }

  async function uploadSound(event: Event) {
    if (!selectedTarget) return
    const targetId = selectedTarget.id ?? selectedTarget.name
    const input = event.currentTarget as HTMLInputElement
    const files = [...(input.files ?? [])]
    if (files.length === 0) return
    try {
      let uploaded = 0
      for (const file of files) {
        const bytes = new Uint8Array(await file.arrayBuffer())
        await new Promise<void>((resolve, reject) => {
          vmSoundUpload(bytes, file.type || mimeFromFilename(file.name), uploadStorage, async (sound) => {
            const uploadedBytes = assetBytes(sound.asset.data)
            const editableBytes = await bytesAsEditableWav(uploadedBytes, sound.dataFormat)
            const stored = await vm.storeAsset(editableBytes, 'wav')
            const target = vm.getTarget(targetId)
            vm.addSound(targetId, {
              name: file.name.replace(/\.[^.]+$/, ''),
              dataFormat: 'wav',
              assetId: stored.assetId,
              md5ext: stored.md5ext,
              rate: wavSampleRate(editableBytes),
              sampleCount: wavSampleCount(editableBytes),
            })
            if (targetId === (selectedTarget?.id ?? selectedTarget?.name)) selectedSoundIndex = Math.max(0, (target?.sounds.length ?? 1) - 1)
            uploaded += 1
            resolve()
          }, reject)
        })
      }
      status = `${uploaded} sound${uploaded === 1 ? '' : 's'} uploaded`
    } catch (error) {
      status = error instanceof Error ? error.message : 'Could not upload sound'
    } finally {
      input.value = ''
    }
  }

  function renameSound(index: number) {
    if (!selectedTarget) return
    const current = selectedTarget.sounds[index]
    const name = window.prompt('Sound name', current?.name ?? '')
    if (!name) return
    vm.renameSound(selectedTarget.name, index, name)
    status = 'Sound renamed'
  }

  function updateSoundName(index: number, event: Event) {
    if (!selectedTarget) return
    const name = (event.currentTarget as HTMLInputElement).value.trim()
    if (!name || name === selectedTarget.sounds[index]?.name) return
    vm.renameSound(selectedTarget.name, index, name)
    status = 'Sound renamed'
  }

  async function selectSound(index: number) {
    selectedSoundIndex = index
    if (selectedTarget) await refreshSoundWaveform(selectedTarget)
    status = 'Sound selected'
  }

  async function deleteSound(index: number) {
    if (!selectedTarget) return
    const soundCount = selectedTarget.sounds.length
    lastDeletedSound = await currentHistoryEntry({ kind: 'sound', targetName: selectedTarget.name, index, meta: selectedTarget.sounds[index]!, bytes: new Uint8Array() })
    lastDeletedSoundRestore = vm.deleteSound(selectedTarget.name, index)
    if (index < selectedSoundIndex) selectedSoundIndex -= 1
    else if (index === selectedSoundIndex) selectedSoundIndex = Math.max(0, Math.min(index, soundCount - 2))
    // Same-slot safety: removing a slot at or before the active one can leave
    // the active index occupied by a different sound.
    clearSoundOnSoundSlotChange(index)
    status = 'Sound deleted'
  }

  async function restoreDeletedSound() {
    if (!selectedTarget) return
    if (lastDeletedSoundRestore) {
      lastDeletedSoundRestore()
    } else if (lastDeletedSound) {
      const asset = await vm.storeAsset(lastDeletedSound.bytes, lastDeletedSound.meta.dataFormat ?? 'wav')
      vm.addSound(selectedTarget.name, { ...lastDeletedSound.meta, assetId: asset.assetId, md5ext: asset.md5ext })
    } else {
      return
    }
    lastDeletedSound = undefined
    lastDeletedSoundRestore = undefined
    // Re-insertion shifts slots; drop sound history unconditionally (rare op).
    clearSoundHistory()
    status = 'Sound restored'
  }

  function duplicateSound(index: number) {
    if (!selectedTarget) return
    vm.duplicateSound(selectedTarget.name, index)
    selectedSoundIndex = index + 1
    // Duplication inserts a slot, shifting later indices on the global sound
    // stack; drop sound history unconditionally (rare op, always safe).
    clearSoundHistory()
    status = 'Sound duplicated'
  }

  async function copySound(index: number) {
    if (!selectedTarget) return
    const editIndex = await ensureSoundForEditing(selectedTarget.name, index)
    const target = vm.getTarget(selectedTarget.name)
    if (!target) return
    const sound = target.sounds[editIndex]
    const loaded = await editableSoundBuffer(target, editIndex)
    if (!sound || !loaded) return
    const range = soundSelectionByteRange(loaded.wav)
    soundClipboard = new Uint8Array(loaded.wav.slice(range.start, range.end))
    soundClipboardMeta = structuredClone(sound)
    selectedSoundIndex = editIndex
    status = 'Sound copied'
  }

  async function pasteSound(index: number) {
    if (!selectedTarget || !soundClipboard || !soundClipboardMeta) return
    const editIndex = await ensureSoundForEditing(selectedTarget.name, index)
    const target = vm.getTarget(selectedTarget.name)
    if (!target) return
    await captureSoundHistory(target, editIndex)
    const loaded = await editableSoundBuffer(target, editIndex)
    const current = loaded?.wav ?? floatSamplesToWav(new Float32Array(0), 44100)
    const merged = replaceSoundSelection(current, soundClipboard)
    await vm.updateSoundBuffer(target.name, editIndex, merged, {
      ...soundClipboardMeta,
      name: target.sounds[editIndex]?.name ?? soundClipboardMeta.name ?? 'sound',
      dataFormat: 'wav',
      rate: wavSampleRate(merged),
      sampleCount: Math.max(0, Math.floor((merged.length - 44) / 2)),
    })
    selectedSoundIndex = editIndex
    await refreshSoundWaveform(target)
    status = 'Sound pasted'
  }

  async function copySoundToNew(index: number) {
    if (!selectedTarget) return
    const editIndex = await ensureSoundForEditing(selectedTarget.name, index)
    const target = vm.getTarget(selectedTarget.name)
    if (!target) return
    const sound = target.sounds[editIndex]
    const loaded = await editableSoundBuffer(target, editIndex)
    if (!sound || !loaded) return
    const range = soundSelectionByteRange(loaded.wav)
    const selectedBytes = wavWithSamples(loaded.wav, loaded.wav.slice(range.start, range.end))
    const asset = await vm.storeAsset(selectedBytes, 'wav')
    vm.addSound(target.name, {
      ...structuredClone(sound),
      name: `${sound.name} copy`,
      dataFormat: 'wav',
      assetId: asset.assetId,
      md5ext: asset.md5ext,
      rate: wavSampleRate(selectedBytes),
      sampleCount: Math.max(0, Math.floor((selectedBytes.length - 44) / 2)),
    })
    selectedSoundIndex = target.sounds.length
    status = 'Sound copied to new'
  }

  async function exportSound(index: number) {
    if (!selectedTarget) return
    const sound = selectedTarget.sounds[index]
    const bytes = await vm.getSoundBuffer(selectedTarget.name, index)
    if (!sound || !bytes) return
    const type = sound.dataFormat === 'mp3' ? 'audio/mpeg' : sound.dataFormat === 'wav' ? 'audio/wav' : 'application/octet-stream'
    const href = URL.createObjectURL(new Blob([new Uint8Array(bytes)], { type }))
    const link = document.createElement('a')
    link.href = href
    link.download = `${sound.name}.${sound.dataFormat ?? 'wav'}`
    link.click()
    URL.revokeObjectURL(href)
    status = 'Sound exported'
  }

  function moveSound(index: number, direction: -1 | 1) {
    if (!selectedTarget) return
    vm.reorderSound(selectedTarget.name, index, index + direction)
    selectedSoundIndex = Math.max(0, Math.min((selectedTarget.sounds.length ?? 1) - 1, index + direction))
    // Reordering the active target can shift the selected sound; drop sound
    // history unconditionally (rare op, always safe).
    clearSoundHistory()
    status = 'Sound reordered'
  }

  async function generateTone() {
    if (!selectedTarget) return
    const bytes = makeToneWav()
    if (selectedTarget.sounds.length === 0) {
      const asset = await vm.storeAsset(bytes, 'wav')
      vm.addSound(selectedTarget.name, {
        name: 'tone',
        dataFormat: 'wav',
        assetId: asset.assetId,
        md5ext: asset.md5ext,
        rate: 44100,
        sampleCount: 4410,
      })
      selectedSoundIndex = 0
    } else {
      await captureSoundHistory(selectedTarget, selectedSoundIndex)
      await vm.updateSoundBuffer(selectedTarget.name, selectedSoundIndex, bytes, {
        name: selectedTarget.sounds[selectedSoundIndex]?.name ?? 'tone',
        dataFormat: 'wav',
        rate: 44100,
        sampleCount: 4410,
      })
    }
    status = 'Tone generated'
  }

  async function startRecordingSound() {
    if (!selectedTarget || isRecordingSound) return
    try {
      recordingStream = await navigator.mediaDevices.getUserMedia({ audio: true })
      recordingContext = new AudioContext()
      recordingSampleRate = recordingContext.sampleRate
      recordingChunks = []
      const source = recordingContext.createMediaStreamSource(recordingStream)
      recordingProcessor = recordingContext.createScriptProcessor(4096, 1, 1)
      recordingProcessor.onaudioprocess = (event) => {
        const input = event.inputBuffer.getChannelData(0)
        recordingChunks.push(new Float32Array(input))
        let sum = 0
        for (const sample of input) sum += sample * sample
        recordingLevel = Math.min(1, Math.sqrt(sum / Math.max(1, input.length)) * 3)
      }
      source.connect(recordingProcessor)
      recordingProcessor.connect(recordingContext.destination)
      isRecordingSound = true
      status = 'Recording'
    } catch (error) {
      status = error instanceof Error ? error.message : 'Could not start recording'
    }
  }

  async function stopRecordingSound(save = true) {
    if (!isRecordingSound && !recordingContext && !recordingStream) return
    recordingProcessor?.disconnect()
    recordingProcessor = undefined
    recordingStream?.getTracks().forEach((track) => track.stop())
    recordingStream = undefined
    await recordingContext?.close().catch(() => undefined)
    recordingContext = undefined
    isRecordingSound = false
    recordingLevel = 0
    if (!save || !selectedTarget || recordingChunks.length === 0) {
      status = save ? 'Recording cancelled' : status
      recordingChunks = []
      return
    }
    const samples = trimSilence(mergeFloatSamples(recordingChunks))
    const wav = floatSamplesToWav(samples.length > 0 ? samples : mergeFloatSamples(recordingChunks), recordingSampleRate)
    const asset = await vm.storeAsset(wav, 'wav')
    vm.addSound(selectedTarget.name, {
      name: `recording${selectedTarget.sounds.length + 1}`,
      dataFormat: 'wav',
      assetId: asset.assetId,
      md5ext: asset.md5ext,
      rate: recordingSampleRate,
      sampleCount: Math.max(0, Math.floor((wav.length - 44) / 2)),
    })
    selectedSoundIndex = selectedTarget.sounds.length
    recordingChunks = []
    status = 'Recording added'
  }

  async function editSound(index: number, effect: SoundEffect) {
    if (!selectedTarget) return
    const editIndex = await ensureSoundForEditing(selectedTarget.name, index)
    const target = vm.getTarget(selectedTarget.name)
    if (!target) return
    const sound = target.sounds[editIndex]
    const loaded = await editableSoundBuffer(target, editIndex)
    if (!sound || !loaded) return
    selectedSoundIndex = editIndex
    await captureSoundHistory(target, editIndex, loaded.original)
    const selectionStart = soundTrimStart
    const selectionEnd = soundTrimEnd
    const edited = transformWavBytes(loaded.wav, effect, selectionStart, selectionEnd, (message) => {
      status = message
    })
    await vm.updateSoundBuffer(target.name, editIndex, edited, {
      name: sound.name,
      dataFormat: 'wav',
      rate: wavSampleRate(edited),
      sampleCount: Math.max(0, Math.floor((edited.length - 44) / 2)),
    })
    if (selectedTarget?.name === target.name && selectedSoundIndex === editIndex && soundTrimStart === selectionStart && soundTrimEnd === selectionEnd) {
      const selection = selectionAfterTransform(loaded.wav, edited, selectionStart, selectionEnd)
      soundTrimStart = selection.start
      soundTrimEnd = selection.end
    }
    await refreshSoundWaveform(target)
    status = `Sound ${effect}`
  }

  async function deleteSoundSelection(index: number, keepSelection = false) {
    if (!selectedTarget) return
    const editIndex = await ensureSoundForEditing(selectedTarget.name, index)
    const target = vm.getTarget(selectedTarget.name)
    if (!target) return
    const sound = target.sounds[editIndex]
    const loaded = await editableSoundBuffer(target, editIndex)
    if (!sound || !loaded) return
    selectedSoundIndex = editIndex
    await captureSoundHistory(target, editIndex, loaded.original)
    const range = soundSelectionByteRange(loaded.wav)
    const nextSamples = keepSelection
      ? loaded.wav.slice(range.start, range.end)
      : concatBytes(loaded.wav.slice(44, range.start), loaded.wav.slice(range.end))
    const edited = wavWithSamples(loaded.wav, nextSamples)
    await vm.updateSoundBuffer(target.name, editIndex, edited, {
      name: sound.name,
      dataFormat: 'wav',
      rate: wavSampleRate(edited),
      sampleCount: Math.max(0, Math.floor((edited.length - 44) / 2)),
    })
    soundTrimStart = 0
    soundTrimEnd = 1
    await refreshSoundWaveform(target)
    status = keepSelection ? 'Sound cropped' : 'Sound selection deleted'
  }

  async function ensureSoundForEditing(targetName: string, index: number) {
    const target = vm.getTarget(targetName)
    if (target?.sounds[index]) return index
    return createBlankSound(targetName)
  }

  function activePaintScopeKey(): string {
    if (!selectedTarget) return ''
    return paintScopeFor(selectedTarget, selectedTarget.currentCostume ?? 0)
  }

  function activeSoundScopeKey(): string {
    if (!selectedTarget) return ''
    return soundScopeFor(selectedTarget, selectedSoundIndex)
  }

  function clearPaintHistory(): void {
    paintScopeGeneration += 1
    paintUndoStack = []
    paintRedoStack = []
    // New baseline: drop last-known slot versions (next peek re-baselines).
    paintKnownBySlot.clear()
    // Prune selection snapshots on history invalidation (no stale retarget).
    committedReshapeSelectionBySlot.clear()
  }

  function clearSoundHistory(): void {
    soundScopeGeneration += 1
    soundUndoStack = []
    soundRedoStack = []
  }

  // Track the active paint scope. The key (`stableTargetId:index`, never the
  // content hash) detects target/costume switches. Saves, renames and
  // bitmap/vector conversions keep the same key and preserve history;
  // same-slot structural changes are cleared explicitly by their handlers.
  function syncPaintScope(): void {
    const key = activePaintScopeKey()
    if (!paintScopeInitialized) {
      paintScopeKey = key
      paintScopeInitialized = true
      return
    }
    if (key !== paintScopeKey) {
      paintScopeKey = key
      clearPaintHistory()
    }
  }

  function syncSoundScope(): void {
    // Track-only: sound history is GLOBAL, so selection switches (sound or
    // target) never clear it. The key follows the selection for diagnostics;
    // only explicit structural clears bump the generation.
    const key = activeSoundScopeKey()
    if (!soundScopeInitialized) {
      soundScopeKey = key
      soundScopeInitialized = true
      return
    }
    if (key !== soundScopeKey) {
      soundScopeKey = key
    }
  }

  // Structural safety net for paint: deleting/restoring/reordering the
  // costume list can leave the same numeric slot occupied by different
  // artwork. Handlers call this for the affected slot; only slots at or
  // before the active one can shift it, so unrelated-list edits preserve
  // history.
  function clearPaintOnCostumeSlotChange(index: number): void {
    if (!selectedTarget) return
    if (index <= (selectedTarget.currentCostume ?? 0)) clearPaintHistory()
  }

  // Structural safety net for the GLOBAL sound history: any sound-list
  // change (delete/restore/reorder/duplicate, any index) can shift slots, so
  // the whole sound history is dropped unconditionally instead of risking a
  // rewrite of the wrong sound. Appends at the end (record/add/share) keep
  // history because existing indices are unaffected.
  function clearSoundOnSoundSlotChange(index: number): void {
    void index
    clearSoundHistory()
  }

  function attachHistoryMeta(
    entry: AssetHistoryEntry,
    scopeKey: string,
    scopeGeneration: number,
    targetId: string,
    observed?: VectorHistoryObserved,
  ): void {
    historyEntryMeta.set(entry, { scopeKey, scopeGeneration, targetId, observed })
  }

  function historyGuardOf(entry: AssetHistoryEntry): HistoryScopeGuard | undefined {
    const meta = historyEntryMeta.get(entry)
    return meta ? createScopeGuard(meta.scopeKey, meta.scopeGeneration) : undefined
  }

  function readProjectGenerationSafe(): number {
    try {
      const value = (vm as unknown as { getProjectGeneration?: () => number }).getProjectGeneration?.()
      if (typeof value === 'number' && Number.isInteger(value) && value >= 0) return value
    } catch {
      // Fall through to 0 below.
    }
    return 0
  }

  // Builds the selection snapshot for `bytes`. The snapshot owns a PRIVATE
  // copy (`buildSelectionSnapshot` copies at the boundary), so the caller may
  // reuse/mutate its buffer afterwards and sibling consumers mutating their
  // own buffers never corrupt this snapshot. Freshness later compares the
  // private copy against a DISTINCT live buffer (same-object fails closed).
  function snapshotCurrentReshapeSelectionForHistory(
    targetId: string,
    index: number,
    bytes: Uint8Array | undefined,
  ): ReshapeSelectionSnapshot | undefined {
    try {
      if (!targetId) return undefined
      if (!Number.isInteger(index) || index < 0) return undefined
      // Bitmap paths never participate (avoid editing bitmap).
      if (costumeEditMode !== 'vector') return undefined
      const owned = bytes ? bytes.slice() : undefined
      const snapshot = buildSelectionSnapshot({
        targetId,
        index,
        projectGeneration: readProjectGenerationSafe(),
        writeSeq: readLiveSlotIdentity(targetId, index).writeSeq ?? null,
        bytes: owned ?? undefined,
        objectIndex: selectedVectorObjectIndex,
        selectedObjectIndices: normalizeSelectedObjectIndices([...selectedVectorObjectIndices]),
        masks: vectorReshapeHandleMasks,
        leafIndices: vectorReshapeLeafIndices,
      })
      return snapshot ? cloneSelectionSnapshot(snapshot) : undefined
    } catch {
      return undefined
    }
  }

  function priorCommittedReshapeSelectionForSlot(targetId: string, index: number): ReshapeSelectionSnapshot | undefined {
    try {
      const slotKey = reshapeSelectionSlotKey(targetId, index)
      const prior = committedReshapeSelectionBySlot.get(slotKey)
      const normalized = normalizeSelectionSnapshot(cloneSelectionSnapshot(prior))
      if (!normalized) return undefined
      if (!isSelectionSnapshotForSlot(normalized, targetId, index, readProjectGenerationSafe())) return undefined
      // CAS freshness: a same-bytes/metadata-only external write bumps the
      // per-slot writeSeq without changing the hash. A stale prior must never
      // retarget a later delete/redo (fail-closed to selection-lost).
      try {
        const liveSeq = readLiveSlotIdentity(targetId, index).writeSeq ?? null
        if (isSelectionSnapshotStale(normalized, liveSeq)) return undefined
      } catch {
        return undefined
      }
      return cloneSelectionSnapshot(normalized)
    } catch {
      return undefined
    }
  }

  function rememberCommittedReshapeSelection(targetId: string, index: number, bytes: Uint8Array | undefined): void {
    try {
      if (!targetId || !Number.isInteger(index) || index < 0) return
      if (costumeEditMode !== 'vector') return
      const slotKey = reshapeSelectionSlotKey(targetId, index)
      // Private copy at the boundary: the committed prior owns its bytes, so
      // later mutations of the caller buffer (or of any history entry that
      // happened to share content) never retarget a stale prior. Bounded to
      // one snapshot per slot (64 slots max, each <= 64 KiB, <= 4 MiB total
      // outside the 24 MiB history budget).
      const owned = bytes ? bytes.slice() : undefined
      const snapshot = buildSelectionSnapshot({
        targetId,
        index,
        projectGeneration: readProjectGenerationSafe(),
        writeSeq: readLiveSlotIdentity(targetId, index).writeSeq ?? null,
        bytes: owned,
        objectIndex: selectedVectorObjectIndex,
        selectedObjectIndices: normalizeSelectedObjectIndices([...selectedVectorObjectIndices]),
        masks: vectorReshapeHandleMasks,
        leafIndices: vectorReshapeLeafIndices,
      })
      if (!snapshot) {
        committedReshapeSelectionBySlot.delete(slotKey)
        return
      }
      committedReshapeSelectionBySlot.set(slotKey, snapshot)
      // Memory cap: one snapshot per slot is already bounded; drop any slot
      // whose key no longer matches the stable scheme (fail-closed prune).
      if (committedReshapeSelectionBySlot.size > 64) {
        const first = committedReshapeSelectionBySlot.keys().next().value as string | undefined
        if (first && first !== slotKey) committedReshapeSelectionBySlot.delete(first)
      }
    } catch {
      // Best-effort only; bytes/history already committed.
    }
  }

  // Fill-tool history parity (scratch `fill-tool.js` oracle): the reference
  // never sets Paper `selected` on fill (hover only recolors, `handleMouseUp`
  // clears hover + calls `onUpdateImage` which snapshots `exportJSON` with no
  // selection; `_restore` re-imports that JSON + `setSelectedItems` stays
  // empty; `fill-mode.jsx` clears selection on tool activate). Undo/redo
  // therefore restore empty selection, never the new overlay / recolored body.
  // The Editor keeps the immediate blue outline for UX, but both the peek
  // (undo) entry and the committed prior (redo) must carry the actual
  // reference set (empty). Rect/brush paths below are untouched (V7 gap).
  function buildEmptyFillSelectionSnapshot(
    targetId: string,
    index: number,
    bytes: Uint8Array | undefined,
  ): ReshapeSelectionSnapshot | undefined {
    try {
      if (!targetId || !Number.isInteger(index) || index < 0) return undefined
      const owned = bytes ? bytes.slice() : undefined
      const snapshot = buildSelectionSnapshot({
        targetId,
        index,
        projectGeneration: readProjectGenerationSafe(),
        writeSeq: readLiveSlotIdentity(targetId, index).writeSeq ?? null,
        bytes: owned,
        objectIndex: -1,
        selectedObjectIndices: [],
        masks: {},
        leafIndices: [],
      })
      return snapshot ? cloneSelectionSnapshot(snapshot) : undefined
    } catch {
      return undefined
    }
  }

  function rememberEmptyFillCommittedSelection(targetId: string, index: number, bytes: Uint8Array | undefined): void {
    try {
      if (!targetId || !Number.isInteger(index) || index < 0) return
      if (costumeEditMode !== 'vector') return
      const slotKey = reshapeSelectionSlotKey(targetId, index)
      const snapshot = buildEmptyFillSelectionSnapshot(targetId, index, bytes ? bytes.slice() : undefined)
      if (!snapshot) {
        committedReshapeSelectionBySlot.delete(slotKey)
        return
      }
      committedReshapeSelectionBySlot.set(slotKey, snapshot)
      if (committedReshapeSelectionBySlot.size > 64) {
        const first = committedReshapeSelectionBySlot.keys().next().value as string | undefined
        if (first && first !== slotKey) committedReshapeSelectionBySlot.delete(first)
      }
    } catch {
      // Best-effort only; bytes/history already committed.
    }
  }

  function attachEmptyFillSelectionToHistoryEntry(entry: AssetHistoryEntry | undefined): void {
    try {
      if (!entry || entry.kind !== 'costume') return
      const targetId = historyEntryMeta.get(entry)?.targetId ?? entry.targetName
      if (!targetId) return
      const bytes = (entry.bytes as Uint8Array | undefined)?.slice()
      const snapshot = buildEmptyFillSelectionSnapshot(targetId, entry.index, bytes)
      if (snapshot) historyReshapeSelection.set(entry, snapshot)
      else historyReshapeSelection.delete(entry)
    } catch {
      // Best-effort only; bytes/history already committed.
    }
  }

  function applyReshapeSelectionSnapshotForUndoRedo(
    snapshot: ReshapeSelectionSnapshot | undefined,
    targetId: string,
    index: number,
  ): void {
    try {
      if (!snapshot) {
        // No snapshot (legacy/bitmap/invalid): drop point state and object
        // selection fail-closed so a stale wave can never linger as selected.
        selectedVectorObjectIndex = -1
        selectedVectorObjectIndices = []
        clearReshapeSelection()
        return
      }
      if (snapshot.targetId !== targetId || snapshot.index !== index) return
      if (snapshot.slotKey !== reshapeSelectionSlotKey(targetId, index)) return
      if (snapshot.projectGeneration !== readProjectGenerationSafe()) {
        selectedVectorObjectIndex = -1
        selectedVectorObjectIndices = []
        clearReshapeSelection()
        return
      }
      // Full object selection first (no phantom wrong object): indices are
      // used verbatim against live units, never rebased by coordinates.
      const liveObjectIndices = vectorObjects.map((item) => item.index)
      const validatedObjects = validateSelectionSnapshotForObjects(snapshot, liveObjectIndices)
      if (!validatedObjects) {
        selectedVectorObjectIndex = -1
        selectedVectorObjectIndices = []
        clearReshapeSelection()
        return
      }
      const owner = vectorObjects.find((item) => item.index === validatedObjects.objectIndex)
      const liveAnchors = (owner?.points ?? [])
        .filter((point) => point.kind !== 'control')
        .map((point) => ({ index: point.index, x: point.x, y: point.y }))
      if (validatedObjects.objectIndex >= 0 && !owner) {
        selectedVectorObjectIndex = -1
        selectedVectorObjectIndices = []
        clearReshapeSelection()
        return
      }
      const validated = validateSelectionSnapshotForAnchors(validatedObjects, liveAnchors)
      if (!validated) {
        selectedVectorObjectIndex = -1
        selectedVectorObjectIndices = []
        clearReshapeSelection()
        return
      }
      // Restore the exact per-slot object selection snapshot (post-other rect /
      // brush selected, not the stale nudged wave). Empty stays empty.
      selectedVectorObjectIndex = validated.objectIndex
      selectedVectorObjectIndices = [...validated.selectedObjectIndices]
      // Keep primary consistent with the restored array (fail-closed: a live
      // primary missing from the array clears to no selection).
      if (validated.objectIndex >= 0 && validated.selectedObjectIndices.length > 0 && !validated.selectedObjectIndices.includes(validated.objectIndex)) {
        selectedVectorObjectIndex = -1
        selectedVectorObjectIndices = []
      } else if (validated.selectedObjectIndices.length === 0) {
        // Cleared object selection (e.g. select-only clear before rect): keep
        // the stored primary only for anchor ownership, outlines stay empty.
        // When the primary is -1 this is fully cleared; otherwise the object
        // stays addressable for reshape without a blue outline.
        if (validated.objectIndex < 0) {
          selectedVectorObjectIndex = -1
        } else {
          selectedVectorObjectIndex = validated.objectIndex
        }
        selectedVectorObjectIndices = []
      }
      setReshapeSelectionWithMasks(validated.masks)
      if (validated.leafIndices.length > 0) setReshapeLeafSelection(validated.leafIndices)
      else clearReshapeLeafSelection()
    } catch {
      try {
        selectedVectorObjectIndex = -1
        selectedVectorObjectIndices = []
        clearReshapeSelection()
      } catch {
        // Ignore.
      }
    }
  }

  async function captureCostumeHistory(target: ScratchTarget, index: number) {
    const entry = await peekCostumeHistory(target, index)
    if (!entry) return
    commitPaintHistory(entry)
  }

  // no-op 巻き戻し用: スタックに触れずに事前状態だけ読む。成功時のみ
  // commitPaintHistory(entry) で積むことで、非同期で並走する別編集の
  // エントリを誤って捨てたり、redo を復元/消去したりしない。Guard は
  // commit 時に検証され、切替/CLEAR 後の遅延 commit は破棄される
  // (redo 温存)。ベクター回転の Esc 復元中は先に復元を待つ: 復元前の古い
  // バイトを peek して別編集が commit すると履歴がずれるため、完了まで
  // 排他する (redo 温存)。
  async function peekCostumeHistory(target: ScratchTarget, index: number): Promise<AssetHistoryEntry | undefined> {
    if (vectorRotateCancelPromise) await vectorRotateCancelPromise
    const costume = target.costumes[index]
    const key = costume?.md5ext ?? costume?.assetId
    const bytes = key ? await vm.loadAsset(key, costume.dataFormat ?? '') : undefined
    if (!costume || !bytes) return undefined
    const entry: AssetHistoryEntry = { kind: 'costume', targetName: target.name, index, meta: structuredClone(costume), bytes: new Uint8Array(bytes) }
    // Guard binds the peeked asset's own scope at resolve time: a late
    // completion after a switch/clear mismatches and is dropped on commit.
    const targetId = stableTargetId(target)
    const observed = observeVectorHistoryIdentity(readLiveSlotIdentity(targetId, index))
    attachHistoryMeta(entry, paintScopeId(targetId, index), paintScopeGeneration, targetId, observed)
    // Selection snapshot for the entry's bytes: default to the current UI at
    // peek (vector only; bitmap never writes). Delete paths override this with
    // the prior committed selection (oracle parity) after the peek resolves.
    try {
      if (costume.dataFormat === 'svg') {
        // Private copy via `snapshotCurrent...` (never `entry.bytes` by
        // reference): mutating the snapshot never corrupts the authoritative
        // entry bytes and vice versa; evicted together, never independently.
        const current = snapshotCurrentReshapeSelectionForHistory(targetId, index, entry.bytes.slice())
        if (current) historyReshapeSelection.set(entry, current)
      }
    } catch {
      // Best-effort only.
    }
    // New intake baseline: the next Undo compares live against this observed.
    rememberPaintKnown(targetId, index, observed)
    return entry
  }

  // Commit to the PAINT side only: clears paint redo, never touches sound.
  // Guarded: entries peeked before a switch/clear are dropped with redo
  // preserved. Cap 100 + encoded-bytes budget (see `paint-history.ts`).
  function commitPaintHistory(entry: AssetHistoryEntry) {
    if (entry.kind !== 'costume') return
    const guard = historyGuardOf(entry)
    if (guard && !isGuardCurrent(paintScopeKey, paintScopeGeneration, guard)) return
    const trimmed = trimHistoryStacks([...paintUndoStack, entry], [], PAINT_HISTORY_MAX_ENTRIES, PAINT_HISTORY_MAX_BYTES)
    paintUndoStack = trimmed.undo
    paintRedoStack = trimmed.redo
  }

  // Commit to the SOUND side only: clears sound redo, never touches paint.
  // Generation-guarded (key intentionally ignored): entries peeked for
  // another sound/target still land, so cross-sound edits accumulate on the
  // one global stack. Entries peeked before an explicit clear carry a stale
  // generation and are dropped with redo preserved. Cap 100 + encoded-bytes
  // budget (see `paint-history.ts`).
  function commitSoundHistory(entry: AssetHistoryEntry) {
    if (entry.kind !== 'sound') return
    const guard = historyGuardOf(entry)
    if (guard && guard.scopeGeneration !== soundScopeGeneration) return
    const trimmed = trimHistoryStacks([...soundUndoStack, entry], [], SOUND_HISTORY_MAX_ENTRIES, SOUND_HISTORY_MAX_BYTES)
    soundUndoStack = trimmed.undo
    soundRedoStack = trimmed.redo
  }

  async function captureSoundHistory(target: ScratchTarget, index: number, existingBytes?: Uint8Array) {
    const sound = target.sounds[index]
    const bytes = existingBytes ?? (await vm.getSoundBuffer(target.name, index))
    if (!sound || !bytes) return
    const entry: AssetHistoryEntry = { kind: 'sound', targetName: target.name, index, meta: structuredClone(sound), bytes: new Uint8Array(bytes) }
    const targetId = stableTargetId(target)
    attachHistoryMeta(entry, soundScopeId(targetId, index), soundScopeGeneration, targetId)
    commitSoundHistory(entry)
  }

  async function editableSoundBuffer(target: ScratchTarget, index: number) {
    const sound = target.sounds[index]
    const bytes = await vm.getSoundBuffer(target.name, index)
    if (!sound || !bytes) return undefined
    try {
      return {
        sound,
        original: bytes,
        wav: await bytesAsEditableWav(bytes, sound.dataFormat),
      }
    } catch (error) {
      status = error instanceof Error ? error.message : 'Could not decode sound'
      return undefined
    }
  }

  async function bytesAsEditableWav(bytes: Uint8Array, dataFormat = 'wav') {
    const decodedAdpcm = decodeImaAdpcmWav(bytes)
    if (decodedAdpcm) return decodedAdpcm
    if (dataFormat === 'wav' && isWav(bytes)) return bytes
    if (typeof AudioContext === 'undefined') throw new Error('Audio editing is not available in this browser')
    const context = new AudioContext()
    try {
      const audioBytes = new Uint8Array(bytes)
      const buffer = await context.decodeAudioData(audioBytes.buffer)
      const samples = new Float32Array(buffer.length)
      for (let channel = 0; channel < buffer.numberOfChannels; channel += 1) {
        const source = buffer.getChannelData(channel)
        for (let i = 0; i < source.length; i += 1) samples[i] = (samples[i] ?? 0) + (source[i] ?? 0) / buffer.numberOfChannels
      }
      return floatSamplesToWav(samples, buffer.sampleRate)
    } finally {
      await context.close().catch(() => undefined)
    }
  }

  function isWav(bytes: Uint8Array) {
    return bytes.length >= 44 && String.fromCharCode(...bytes.slice(0, 4)) === 'RIFF' && String.fromCharCode(...bytes.slice(8, 12)) === 'WAVE'
  }

  function wavSampleRate(bytes: Uint8Array) {
    return isWav(bytes) ? new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength).getUint32(24, true) : 44100
  }

  function wavSampleCount(bytes: Uint8Array) {
    return Math.max(0, Math.floor(Math.max(0, bytes.length - 44) / 2))
  }

  // Undo/redo route by tab: costumes rewinds paint only, sounds rewinds
  // sound only. The other side's stacks are never touched, so a costume Undo
  // can no longer rewind a sound edit (or another costume's edit: scopes are
  // cleared on switch) and vice versa.
  async function undoAssetEdit() {
    // Pending rect/oval (B-3): Undo discards the staged shape (base restore,
    // no history) and never touches the history stacks.
    try {
      const pendingSession = ensureBitmapPendingController()?.get()
      if (pendingSession && costumeEditMode === 'bitmap' && pendingSession.snapshot().hasPending) {
        const discarded = pendingSession.discardForDeleteOrUndo()
        if (discarded.ok) {
          bitmapSelection = undefined
          bitmapPendingPainting = false
          status = 'Asset undo'
          return
        }
      }
    } catch {
      // Fall through to the history path on unexpected failure.
    }
    if (vectorRotateCancelPromise) await vectorRotateCancelPromise
    // An active point/rotate/leaf drag owns uncommitted previews: cancel it
    // first (barrier restore, no history) and wait for the restore so Undo
    // rewinds the settled bytes instead of racing them.
    cancelVectorRotateDrag()
    cancelVectorPathPointDrag()
    cancelVectorLeafTranslateDrag()
    if (vectorRotateCancelPromise) await vectorRotateCancelPromise
    // An active drag owns uncommitted preview state: discard its center guide
    // first so Undo never restores under a stale crosshair. Bitmap floating
    // previews are uncommitted canvas pixels, so restore the committed
    // snapshot (same-target only) before undoing; vector moves apply live,
    // so only the drag state + guide are dropped (applied moves undo normally).
    if (bitmapMoveDrag && bitmapCanvas) {
      const drag = bitmapMoveDrag
      bitmapMoveDrag = undefined
      const cur = currentBitmapIdentity()
      if (cur && selectedTarget && selectedTarget.name === drag.targetName && (selectedTarget.currentCostume ?? 0) === drag.costumeIndex) {
        bitmapCanvas.getContext('2d')?.putImageData(floatingImageToImageData(drag.session.committed), 0, 0)
        bitmapSelection = { ...drag.startSelection }
      }
      isBitmapPainting = false
      bitmapStart = undefined
      bitmapStrokeOwner = undefined
    }
    if (vectorDrag && !vectorDrag.committing) vectorDrag = undefined
    if (vectorResizeDrag && !vectorResizeDrag.committing) vectorResizeDrag = undefined
    // A mid-press Undo first closes the nudge cycle so the coalesced entry
    // lands before the undo restores (never interleave or lose previews).
    await flushNudgePending()
    await flushHsvLive()
    if (selectedTab === 'sounds') {
      await undoHistorySide('sound')
      return
    }
    await undoHistorySide('costume')
  }

  async function redoAssetEdit() {
    // Pending rect/oval (B-3): redo is commit-first; on refusal the redo is
    // blocked and the pending is retained.
    try {
      const pendingSession = ensureBitmapPendingController()?.get()
      if (pendingSession && costumeEditMode === 'bitmap' && pendingSession.snapshot().hasPending) {
        const ok = await guardBitmapPendingCommitFirst('paint-redo')
        if (!ok) return
      }
    } catch {
      return
    }
    if (vectorRotateCancelPromise) await vectorRotateCancelPromise
    // Same drag-cancel ordering as Undo.
    cancelVectorRotateDrag()
    cancelVectorPathPointDrag()
    cancelVectorLeafTranslateDrag()
    if (vectorRotateCancelPromise) await vectorRotateCancelPromise
    // Same drag-discard ordering as Undo.
    if (bitmapMoveDrag && bitmapCanvas) {
      const drag = bitmapMoveDrag
      bitmapMoveDrag = undefined
      const cur = currentBitmapIdentity()
      if (cur && selectedTarget && selectedTarget.name === drag.targetName && (selectedTarget.currentCostume ?? 0) === drag.costumeIndex) {
        bitmapCanvas.getContext('2d')?.putImageData(floatingImageToImageData(drag.session.committed), 0, 0)
        bitmapSelection = { ...drag.startSelection }
      }
      isBitmapPainting = false
      bitmapStart = undefined
      bitmapStrokeOwner = undefined
    }
    if (vectorDrag && !vectorDrag.committing) vectorDrag = undefined
    if (vectorResizeDrag && !vectorResizeDrag.committing) vectorResizeDrag = undefined
    // Same ordering as Undo: close the nudge cycle before restoring.
    await flushNudgePending()
    await flushHsvLive()
    if (selectedTab === 'sounds') {
      await redoHistorySide('sound')
      return
    }
    await redoHistorySide('costume')
  }

  function historySideStacks(kind: 'costume' | 'sound'): { undo: AssetHistoryEntry[]; redo: AssetHistoryEntry[] } {
    return kind === 'costume'
      ? { undo: paintUndoStack, redo: paintRedoStack }
      : { undo: soundUndoStack, redo: soundRedoStack }
  }

  function activeScopeForKind(kind: 'costume' | 'sound'): { key: string; generation: number } {
    return kind === 'costume'
      ? { key: paintScopeKey, generation: paintScopeGeneration }
      : { key: soundScopeKey, generation: soundScopeGeneration }
  }

  async function undoHistorySide(kind: 'costume' | 'sound') {
    const stacks = historySideStacks(kind)
    const entry = stacks.undo.at(-1)
    if (!entry || entry.kind !== kind) return
    // Fail-closed external pre-check (costume only): when the live slot
    // diverged from the Editor's last known identity, an external write
    // landed — keep both stacks intact and surface the conflict instead of
    // deleting the external. The next intake starts a new history baseline.
    if (kind === 'costume' && entry.kind === 'costume') {
      const entryTargetId = historyEntryMeta.get(entry)?.targetId ?? entry.targetName
      const livePre = readLiveSlotIdentity(entryTargetId, entry.index)
      const knownPre = paintKnownBySlot.get(paintKnownSlotKey(entryTargetId, entry.index))
      if (knownPre && isVectorHistoryStale(livePre, knownPre)) {
        bumpPaintGenerationForExternal()
        await refreshVectorPreviewFromLive(entryTargetId, selectedTarget ?? undefined)
        status = vectorExternalConflictStatus('Undo')
        return
      }
    }
    // Capture the active scope before the async read: a switch/clear/undo in
    // between aborts the whole undo (no pop, no redo push, no restore) so a
    // stale entry can never rewind the newly selected asset.
    const entryScopeBefore = activeScopeForKind(kind)
    const current = await currentHistoryEntry(entry)
    const entryScopeAfter = activeScopeForKind(kind)
    if (kind === 'costume') {
      if (entryScopeBefore.key !== entryScopeAfter.key || entryScopeBefore.generation !== entryScopeAfter.generation) return
    } else {
      if (entryScopeBefore.generation !== entryScopeAfter.generation) return
    }
    // The entry must still be on top: a concurrent clear/pop in between aborts.
    const liveTop = historySideStacks(kind).undo.at(-1)
    if (liveTop !== entry) return
    // Snapshot for fail-closed revert: a conflicted restore must leave both
    // stacks untouched (external kept + status).
    const undoBefore = kind === 'costume' ? [...paintUndoStack] : [...soundUndoStack]
    const redoBefore = kind === 'costume' ? [...paintRedoStack] : [...soundRedoStack]
    if (kind === 'costume') paintUndoStack = paintUndoStack.slice(0, -1)
    else soundUndoStack = soundUndoStack.slice(0, -1)
    // Redo push is scope-local and guarded: a stale `current` (captured
    // across a switch) is dropped instead of polluting the redo side.
    if (current && current.kind === kind) {
      const guard = historyGuardOf(current)
      let allowPush = true
      if (guard) {
        if (kind === 'costume') {
          allowPush = guard.scopeKey === activeScopeForKind(kind).key && guard.scopeGeneration === activeScopeForKind(kind).generation
        } else {
          allowPush = guard.scopeGeneration === activeScopeForKind(kind).generation
        }
      }
      // Cross-target redo capture must also address the active asset: a
      // `current` for another target/index never lands on this side.
      if (allowPush && kind === 'costume' && selectedTarget) {
        const meta = historyGuardOf(current)
        const wantKey = paintScopeId(stableTargetId(selectedTarget), selectedTarget.currentCostume ?? 0)
        if (meta && meta.scopeKey !== wantKey) allowPush = false
      }
      if (allowPush) {
        const maxEntries = kind === 'costume' ? PAINT_HISTORY_MAX_ENTRIES : SOUND_HISTORY_MAX_ENTRIES
        const maxBytes = kind === 'costume' ? PAINT_HISTORY_MAX_BYTES : SOUND_HISTORY_MAX_BYTES
        const undoSide = kind === 'costume' ? paintUndoStack : soundUndoStack
        const redoSide = kind === 'costume' ? paintRedoStack : soundRedoStack
        const trimmed = trimHistoryStacks(undoSide, [...redoSide, current], maxEntries, maxBytes)
        if (kind === 'costume') {
          paintUndoStack = trimmed.undo
          paintRedoStack = trimmed.redo
        } else {
          soundUndoStack = trimmed.undo
          soundRedoStack = trimmed.redo
        }
      }
    }
    const restored = await restoreHistoryEntry(entry)
    if (kind === 'costume' && restored !== true) {
      // Fail closed: external won — restore both stacks, surface the conflict.
      paintUndoStack = undoBefore
      paintRedoStack = redoBefore
      status = typeof restored === 'string' && restored.includes('external') ? vectorExternalConflictStatus('Undo') : `Asset undo: ${restored}`
      return
    }
    status = restored === true ? 'Asset undo' : `Asset undo: ${restored}`
  }

  async function redoHistorySide(kind: 'costume' | 'sound') {
    const stacks = historySideStacks(kind)
    const entry = stacks.redo.at(-1)
    if (!entry || entry.kind !== kind) return
    if (kind === 'costume' && entry.kind === 'costume') {
      const entryTargetId = historyEntryMeta.get(entry)?.targetId ?? entry.targetName
      const livePre = readLiveSlotIdentity(entryTargetId, entry.index)
      const knownPre = paintKnownBySlot.get(paintKnownSlotKey(entryTargetId, entry.index))
      if (knownPre && isVectorHistoryStale(livePre, knownPre)) {
        bumpPaintGenerationForExternal()
        await refreshVectorPreviewFromLive(entryTargetId, selectedTarget ?? undefined)
        status = vectorExternalConflictStatus('Redo')
        return
      }
    }
    const entryScopeBefore = activeScopeForKind(kind)
    const current = await currentHistoryEntry(entry)
    const entryScopeAfter = activeScopeForKind(kind)
    if (kind === 'costume') {
      if (entryScopeBefore.key !== entryScopeAfter.key || entryScopeBefore.generation !== entryScopeAfter.generation) return
    } else {
      if (entryScopeBefore.generation !== entryScopeAfter.generation) return
    }
    const liveTop = historySideStacks(kind).redo.at(-1)
    if (liveTop !== entry) return
    const undoBefore = kind === 'costume' ? [...paintUndoStack] : [...soundUndoStack]
    const redoBefore = kind === 'costume' ? [...paintRedoStack] : [...soundRedoStack]
    if (kind === 'costume') paintRedoStack = paintRedoStack.slice(0, -1)
    else soundRedoStack = soundRedoStack.slice(0, -1)
    if (current && current.kind === kind) {
      const guard = historyGuardOf(current)
      let allowPush = true
      if (guard) {
        if (kind === 'costume') {
          allowPush = guard.scopeKey === activeScopeForKind(kind).key && guard.scopeGeneration === activeScopeForKind(kind).generation
        } else {
          allowPush = guard.scopeGeneration === activeScopeForKind(kind).generation
        }
      }
      if (allowPush && kind === 'costume' && selectedTarget) {
        const meta = historyGuardOf(current)
        const wantKey = paintScopeId(stableTargetId(selectedTarget), selectedTarget.currentCostume ?? 0)
        if (meta && meta.scopeKey !== wantKey) allowPush = false
      }
      if (allowPush) {
        const maxEntries = kind === 'costume' ? PAINT_HISTORY_MAX_ENTRIES : SOUND_HISTORY_MAX_ENTRIES
        const maxBytes = kind === 'costume' ? PAINT_HISTORY_MAX_BYTES : SOUND_HISTORY_MAX_BYTES
        const undoSide = kind === 'costume' ? paintUndoStack : soundUndoStack
        const redoSide = kind === 'costume' ? paintRedoStack : soundRedoStack
        const trimmed = trimHistoryStacks([...undoSide, current], redoSide, maxEntries, maxBytes)
        if (kind === 'costume') {
          paintUndoStack = trimmed.undo
          paintRedoStack = trimmed.redo
        } else {
          soundUndoStack = trimmed.undo
          soundRedoStack = trimmed.redo
        }
      }
    }
    const restored = await restoreHistoryEntry(entry)
    if (kind === 'costume' && restored !== true) {
      paintUndoStack = undoBefore
      paintRedoStack = redoBefore
      status = typeof restored === 'string' && restored.includes('external') ? vectorExternalConflictStatus('Redo') : `Asset redo: ${restored}`
      return
    }
    status = restored === true ? 'Asset redo' : `Asset redo: ${restored}`
  }

  // Redo-side capture of the live bytes. Resolves the target by the stable
  // id recorded at capture time (rename-safe) and attaches fresh scope meta
  // for the active scope, so a cross-switch completion is dropped on push.
  async function currentHistoryEntry(entry: AssetHistoryEntry): Promise<AssetHistoryEntry | undefined> {
    const storedTargetId = historyEntryMeta.get(entry)?.targetId ?? entry.targetName
    const target = vm.getTarget(storedTargetId)
    if (!target) return undefined
    if (entry.kind === 'costume') {
      const costume = target.costumes[entry.index]
      const key = costume?.md5ext ?? costume?.assetId
      const bytes = key ? await vm.loadAsset(key, costume.dataFormat ?? '') : undefined
      if (!costume || !bytes) return undefined
      const next: AssetHistoryEntry = { kind: 'costume', targetName: target.name, index: entry.index, meta: structuredClone(costume), bytes: new Uint8Array(bytes) }
      const targetId = stableTargetId(target)
      attachHistoryMeta(next, paintScopeId(targetId, entry.index), activeScopeForKind('costume').generation, targetId, observeVectorHistoryIdentity(readLiveSlotIdentity(targetId, entry.index)))
      // Redo-side selection corresponds to the live post-state bytes (usually
      // post-delete survivors / post-nudge live anchors). Prefer the prior
      // post-edit snapshot when it is fresh for the live bytes (post-edit
      // semantics, not the selection-only polluted current UI); fall back to
      // the current UI only when the prior is missing/stale. Bitmap never
      // writes reshape snapshots.
      try {
        if (costume.dataFormat === 'svg') {
          // Private copies on both sides (never `next.bytes` by reference):
          // `prior` already owns its bytes; the freshness check below
          // requires DISTINCT buffers (same-object fails closed), and the
          // fallback capture copies again via `snapshotCurrent...`.
          const liveBytes = next.bytes.slice()
          let usedPrior = false
          try {
            const prior = priorCommittedReshapeSelectionForSlot(targetId, entry.index)
            if (prior && isSelectionSnapshotFreshForBytes(prior, liveBytes)) {
              const staleness = (() => {
                try {
                  return isSelectionSnapshotStale(prior, readLiveSlotIdentity(targetId, entry.index).writeSeq ?? null)
                } catch {
                  return true
                }
              })()
              if (!staleness) {
                const cloned = cloneSelectionSnapshot(prior)
                if (cloned) {
                  historyReshapeSelection.set(next, cloned)
                  usedPrior = true
                }
              }
            }
          } catch {
            // Fall through to current-UI capture below.
          }
          if (!usedPrior) {
            const current = snapshotCurrentReshapeSelectionForHistory(targetId, entry.index, liveBytes)
            if (current) historyReshapeSelection.set(next, current)
          }
        }
      } catch {
        // Best-effort only.
      }
      return next
    }
    const sound = target.sounds[entry.index]
    const bytes = sound ? await vm.getSoundBuffer(target.name, entry.index) : undefined
    if (!sound || !bytes) return undefined
    const next: AssetHistoryEntry = { kind: 'sound', targetName: target.name, index: entry.index, meta: structuredClone(sound), bytes: new Uint8Array(bytes) }
    const targetId = stableTargetId(target)
    attachHistoryMeta(next, soundScopeId(targetId, entry.index), activeScopeForKind('sound').generation, targetId)
    return next
  }

  // Restores an entry to its own asset: rename-safe via the stable target id
  // recorded at capture time. Paint restores only into the active paint scope
  // (switch/clear, or an explicit structural clear after delete/reorder, is
  // rejected with a reason instead of rewinding a different costume). Sound
  // history is global: any entry may restore its own target/index regardless
  // of the current sound selection; only a generation mismatch (explicit
  // clear after delete/reorder/restore/project load) is rejected, plus
  // missing target/slot. Returns true on write.
  async function restoreHistoryEntry(entry: AssetHistoryEntry): Promise<true | string> {
    const meta = historyEntryMeta.get(entry)
    if (entry.kind === 'costume') {
      const scope = activeScopeForKind('costume')
      // Entries without meta predate this scheme; entries with meta must still
      // belong to the active scope, otherwise they address another asset.
      if (meta && (meta.scopeKey !== scope.key || meta.scopeGeneration !== scope.generation)) return 'scope changed'
    } else {
      // Global sound stack: the active sound key is irrelevant, but a clear
      // after capture (stale generation) must not resurrect bytes.
      if (meta && meta.scopeGeneration !== soundScopeGeneration) return 'history cleared'
    }
    const target = vm.getTarget(meta?.targetId ?? entry.targetName)
    if (!target) return 'target gone'
    if (entry.kind === 'costume') {
      if (!target.costumes[entry.index]) return 'costume gone'
      const targetId = stableTargetId(target)
      // Fail-closed external check: the live slot must still match the
      // Editor's last known identity. A metadata-only / same-bytes external
      // write bumps writeSeq without changing hashes, so the version is
      // required — hash-only comparison would miss it and delete it.
      const live = readLiveSlotIdentity(targetId, entry.index)
      const known = paintKnownBySlot.get(paintKnownSlotKey(targetId, entry.index))
      if (known && isVectorHistoryStale(live, known)) {
        bumpPaintGenerationForExternal()
        await refreshVectorPreviewFromLive(targetId, target)
        return 'external change kept'
      }
      // Ordered CAS `edit` write on the same per-slot FIFO: lands after any
      // in-flight cancel barrier instead of racing it, keeps a concurrent
      // external write instead of deleting it, and never erases a newer
      // legitimate edit enqueued after it. Format priority
      // (`patch.dataFormat ?? live`) is preserved by the VM; bitmap/sound
      // paths are untouched. Stable-id only (never the display-name alias).
      const slotKey = vectorWriteSlotKey(targetId, entry.index)
      // Paint owns bytes + geometry metadata only: strip the display name so
      // the restore rewinds the drawing while the live (possibly renamed)
      // name survives, matching scratch-paint (undo never rewrites names).
      const entryMetaPatch = historyCostumeRestorePatch(entry.meta)
      // Private copies at the VM boundary: the restore must not hand the
      // authoritative history buffer to the VM by reference. `storeAsset`
      // copies synchronously today, but the copy here defends the history
      // against any future aliasing or in-place VM transform.
      const bytes = entry.bytes.slice()
      let applied = false
      // CAS expected is the last editor-known identity captured BEFORE the
      // queue (not a fresh read inside): a concurrent external write that
      // lands after the pre-check but before execution bumps writeSeq, so the
      // versioned compare fails closed and keeps the external instead of
      // deleting it. Re-reading fresh inside would always match live and
      // silently overwrite the external.
      const restoreExpected = vectorSlotIdentityOf(known ?? live)
      await enqueueVectorCostumeWrite(slotKey, undefined, 'edit', async () => {
        const writer = vm as unknown as {
          updateCostumeIfMatch?: (
            t: string, i: number, e: VectorSlotIdentity | undefined,
            p: Partial<ScratchCostume>, d?: Uint8Array,
          ) => Promise<{ applied: boolean; current?: VectorSlotIdentity }>
        }
        if (typeof writer.updateCostumeIfMatch === 'function') {
          const result = await writer.updateCostumeIfMatch(targetId, entry.index, restoreExpected, entryMetaPatch, new Uint8Array(bytes))
          if (result.applied) {
            applied = true
            // Undo/redo restore adopts only its own `result.current` seq
            // (fail-closed: never a fresh external read that would hide a
            // same-bytes/metadata-only external landing in between).
            if (result.current) rememberPaintKnown(targetId, entry.index, result.current)
          } else {
            bumpPaintGenerationForExternal()
            await refreshVectorPreviewFromLive(targetId, target)
          }
          return result
        }
        await vm.updateCostume(target.name, entry.index, entryMetaPatch, bytes.slice())
        applied = true
        rememberPaintKnown(targetId, entry.index, readLiveSlotIdentity(targetId, entry.index))
      })
      if (!applied) return 'external change kept'
      // Direct plain-object VM mutation / plugin VM-API bypass never reaches
      // the slot queue and is therefore unsupported (documented boundary).
    } else {
      if (!target.sounds[entry.index]) return 'sound gone'
      await vm.updateSoundBuffer(target.name, entry.index, entry.bytes.slice(), entry.meta)
    }
    await refreshAssetEditorPreviews()
    // Undo/redo rewinds the artwork under the current selection: unapplied
    // selection-derived intent is stale even when the selection key survives
    // (the watcher only fires on key changes), so drop it. Deselected
    // presets survive, matching the selection-change rule.
    if (entry.kind === 'costume') dropSelectionOwnedVectorStyleDirty()
    // Accurate selection restore (oracle parity): bytes are authoritative;
    // the entry's selection snapshot is validated against the restored
    // artwork (stable id/index/generation + live anchors, duplicate coords
    // fail-closed). Bitmap restores never touch reshape selection.
    try {
      if (entry.kind === 'costume' && costumeEditMode === 'vector') {
        const meta = historyEntryMeta.get(entry)
        const targetForSelection = vm.getTarget(meta?.targetId ?? entry.targetName)
        const selectionTargetId = targetForSelection ? stableTargetId(targetForSelection) : (meta?.targetId ?? '')
        const snapshot = historyReshapeSelection.get(entry)
        if (snapshot && selectionTargetId) {
          applyReshapeSelectionSnapshotForUndoRedo(snapshot, selectionTargetId, entry.index)
          // Re-baseline the prior from the restored entry bytes via a private
          // copy (`remember...` copies again): mutating the prior never
          // corrupts the authoritative entry and vice versa.
          rememberCommittedReshapeSelection(selectionTargetId, entry.index, entry.bytes.slice())
        } else if (selectionTargetId) {
          // No snapshot (legacy entries / bitmap / invalid): preserve the
          // existing coordinate-rebase behavior in refreshCostumePreview and
          // re-baseline the prior to the current UI to avoid stale retarget.
          const liveKey = targetForSelection?.costumes[entry.index]?.md5ext ?? targetForSelection?.costumes[entry.index]?.assetId
          const liveBytes = undefined
          void liveKey
          void liveBytes
        }
      }
    } catch {
      // Best-effort only; bytes already restored.
    }
    return true
  }

  function createRuntimeAudioEngine() {
    return {
      playSound: (targetName: string, sound: ScratchSound) => playRuntimeSound(targetName, sound),
      stopAllSounds: stopRuntimeSounds,
      stopSoundsForTarget: stopRuntimeSounds,
      setVolume: (targetName: string, volume: number) => {
        runtimeAudioVolumes.set(targetName, volume)
      },
      setEffects: (targetName: string, effects: Record<string, number>) => {
        runtimeAudioEffects.set(targetName, effects)
      },
    }
  }

  async function playRuntimeSound(targetName: string, sound: ScratchSound) {
    try {
      const context = ensureRuntimeAudioContext()
      await context.resume().catch(() => undefined)
      const key = sound.md5ext ?? sound.assetId
      const bytes = key ? await vm.loadAsset(key, sound.dataFormat ?? '') : undefined
      if (!bytes || bytes.byteLength === 0) return
      const audioBytes = new Uint8Array(bytes)
      const buffer = await decodeRuntimeAudio(context, audioBytes, sound.dataFormat)
      return playDecodedRuntimeBuffer(targetName, buffer)
    } catch (error) {
      status = error instanceof Error ? `Could not play sound: ${error.message}` : 'Could not play sound'
      return
    }
  }

  async function decodeRuntimeAudio(context: AudioContext, bytes: Uint8Array, dataFormat = '') {
    try {
      return await context.decodeAudioData(audioDecodeBuffer(bytes))
    } catch {
      const decodedAdpcm = decodeImaAdpcmWav(bytes)
      if (decodedAdpcm) return context.decodeAudioData(audioDecodeBuffer(decodedAdpcm))
      if (dataFormat && dataFormat !== 'wav') {
        const editable = await bytesAsEditableWav(bytes, dataFormat)
        return context.decodeAudioData(audioDecodeBuffer(editable))
      }
      throw new Error('Unable to decode audio data')
    }
  }

  function audioDecodeBuffer(bytes: Uint8Array) {
    const buffer = new ArrayBuffer(bytes.byteLength)
    new Uint8Array(buffer).set(bytes)
    return buffer
  }

  async function playDecodedRuntimeBuffer(targetName: string, buffer: AudioBuffer) {
    const context = ensureRuntimeAudioContext()
    const source = context.createBufferSource()
    const gain = context.createGain()
    const panner = new StereoPannerNode(context)
    const effects = runtimeAudioEffects.get(targetName) ?? {}
    const target = vm.getTarget(targetName)
    const volume = runtimeAudioVolumes.get(targetName) ?? target?.volume ?? 100
    source.buffer = buffer
    source.detune.value = effects.PITCH ?? effects.pitch ?? 0
    gain.gain.value = Math.max(0, Math.min(1, volume / 100))
    panner.pan.value = Math.max(-1, Math.min(1, (effects.PAN ?? effects.pan ?? 0) / 100))
    source.connect(gain)
    gain.connect(panner)
    panner.connect(context.destination)
    runtimeAudioSources = [...runtimeAudioSources, source]
    return new Promise<void>((resolve) => {
      source.onended = () => {
        runtimeAudioSources = runtimeAudioSources.filter((item) => item !== source)
        resolve()
      }
      source.start()
    })
  }

  function stopRuntimeSounds() {
    for (const source of runtimeAudioSources) {
      source.onended = null
      try {
        source.stop()
      } catch {
        // The source may already have ended.
      }
    }
    runtimeAudioSources = []
  }

  async function previewSound(index: number) {
    if (!selectedTarget) return
    stopPreviewSound()
    const request = previewRequest
    const selectionStart = Math.min(soundTrimStart, soundTrimEnd)
    const selectionEnd = Math.max(soundTrimStart, soundTrimEnd)
    const context = ensurePreviewAudioContext()
    void context.resume()
    const target = vm.getTarget(selectedTarget.name)
    if (!target?.sounds[index]) return
    const editIndex = index
    const sound = target.sounds[editIndex]
    const loaded = await editableSoundBuffer(target, editIndex)
    if (!sound || !loaded || request !== previewRequest) return
    selectedSoundIndex = editIndex
    const range = wavSelectionByteRange(loaded.wav, selectionStart, selectionEnd)
    const sampleBytes = Math.max(1, loaded.wav.length - 44)
    const playBytes = extractSoundSelection(loaded.wav, selectionStart, selectionEnd)
    try {
      const audioBytes = new Uint8Array(playBytes)
      const buffer = await context.decodeAudioData(audioBytes.buffer)
      if (request !== previewRequest) return
      const source = context.createBufferSource()
      source.buffer = buffer
      source.connect(context.destination)
      previewSelectionStart = (range.start - 44) / sampleBytes
      previewSelectionEnd = (range.end - 44) / sampleBytes
      previewAudioDuration = buffer.duration
      previewAudioStartedAt = context.currentTime
      soundPlayhead = previewSelectionStart
      previewAudio = source
      previewPlayheadTimer = setInterval(updatePreviewPlayhead, 16)
      source.onended = stopPreviewSound
      source.start(previewAudioStartedAt)
    } catch (error) {
      if (request !== previewRequest) return
      status = error instanceof Error ? error.message : 'Could not play sound'
      stopPreviewSound()
    }
  }

  function stopPreviewSound() {
    previewRequest += 1
    if (previewPlayheadTimer) {
      clearInterval(previewPlayheadTimer)
      previewPlayheadTimer = undefined
    }
    if (previewAudio) {
      previewAudio.onended = null
      try {
        previewAudio.stop()
      } catch {
        // The source may already have ended.
      }
      previewAudio = undefined
    }
    soundPlayhead = 0
  }

  function ensurePreviewAudioContext() {
    previewAudioContext ??= new AudioContext()
    return previewAudioContext
  }

  function ensureRuntimeAudioContext() {
    runtimeAudioContext ??= new AudioContext()
    return runtimeAudioContext
  }

  function updatePreviewPlayhead() {
    if (!previewAudioContext || previewAudioDuration <= 0) return
    const elapsed = Math.max(0, previewAudioContext.currentTime - previewAudioStartedAt)
    const progress = Math.min(1, elapsed / previewAudioDuration)
    soundPlayhead = previewSelectionStart + progress * Math.max(0, previewSelectionEnd - previewSelectionStart)
  }

  function soundSelectionByteRange(bytes: Uint8Array) {
    return wavSelectionByteRange(bytes, soundTrimStart, soundTrimEnd)
  }

  function replaceSoundSelection(bytes: Uint8Array, insertSamples: Uint8Array) {
    return replaceWavSelection(bytes, insertSamples, soundTrimStart, soundTrimEnd)
  }

  function updateSoundTrim(which: 'start' | 'end', event: Event) {
    const value = Number((event.currentTarget as HTMLInputElement).value) / 100
    if (which === 'start') soundTrimStart = Math.max(0, Math.min(1, Math.min(value, soundTrimEnd)))
    else soundTrimEnd = Math.max(0, Math.min(1, Math.max(value, soundTrimStart)))
  }

  function soundWaveformPosition(event: MouseEvent) {
    const rect = (event.currentTarget as HTMLElement).getBoundingClientRect()
    return Math.max(0, Math.min(1, (event.clientX - rect.left) / Math.max(1, rect.width)))
  }

  function soundWaveformPointerPosition(event: PointerEvent, host: HTMLElement) {
    const rect = host.getBoundingClientRect()
    return Math.max(0, Math.min(1, (event.clientX - rect.left) / Math.max(1, rect.width)))
  }

  function beginSoundWaveformSelection(event: MouseEvent) {
    if (soundTrimDrag) return
    isSelectingSoundRange = true
    soundSelectionAnchor = soundWaveformPosition(event)
    soundTrimStart = soundSelectionAnchor
    soundTrimEnd = soundSelectionAnchor
    soundPlayhead = soundSelectionAnchor
  }

  function updateSoundWaveformSelection(event: MouseEvent) {
    if (!isSelectingSoundRange) return
    const current = soundWaveformPosition(event)
    soundTrimStart = Math.min(soundSelectionAnchor, current)
    soundTrimEnd = Math.max(soundSelectionAnchor, current)
    soundPlayhead = current
  }

  function endSoundWaveformSelection(event: MouseEvent) {
    if (!isSelectingSoundRange) return
    updateSoundWaveformSelection(event)
    isSelectingSoundRange = false
    if (Math.abs(soundTrimEnd - soundTrimStart) < 0.01) {
      soundTrimStart = 0
      soundTrimEnd = 1
    }
    status = 'Sound selection updated'
  }

  function beginSoundTrimHandle(which: 'start' | 'end', event: PointerEvent) {
    event.preventDefault()
    event.stopPropagation()
    soundTrimDrag = which
    const element = event.currentTarget as HTMLElement
    element.setPointerCapture(event.pointerId)
    dragSoundTrimHandle(event)
  }

  function dragSoundTrimHandle(event: PointerEvent) {
    if (!soundTrimDrag) return
    const host = (event.currentTarget as HTMLElement).parentElement
    if (!host) return
    const value = soundWaveformPointerPosition(event, host)
    if (soundTrimDrag === 'start') soundTrimStart = Math.max(0, Math.min(value, soundTrimEnd - 0.005))
    else soundTrimEnd = Math.min(1, Math.max(value, soundTrimStart + 0.005))
    soundPlayhead = value
  }

  function endSoundTrimHandle(event: PointerEvent) {
    if (!soundTrimDrag) return
    dragSoundTrimHandle(event)
    soundTrimDrag = undefined
    status = 'Sound selection updated'
  }

  function stagePosition(target: ScratchTarget) {
    const left = 50 + ((target.x ?? 0) / 480) * 100
    const top = 50 - ((target.y ?? 0) / 360) * 100
    return `left:${left}%;top:${top}%;transform:translate(-50%,-50%) rotate(${(target.direction ?? 90) - 90}deg);`
  }

  function stagePointerPosition(event: MouseEvent | PointerEvent): { x: number; y: number } {
    const data = stagePointerData(event)
    return { x: data.scratchX, y: data.scratchY }
  }

  function stagePointerData(event: MouseEvent | PointerEvent) {
    const rect = stageCanvas.getBoundingClientRect()
    const canvasX = event.clientX - rect.left
    const canvasY = event.clientY - rect.top
    return {
      x: canvasX,
      y: canvasY,
      scratchX: (canvasX / rect.width) * 480 - 240,
      scratchY: 180 - (canvasY / rect.height) * 360,
      canvasWidth: rect.width,
      canvasHeight: rect.height,
    }
  }

  function pickSprite(event: MouseEvent) {
    if (suppressNextStageClick) {
      suppressNextStageClick = false
      event.preventDefault()
      return
    }
    const { x, y } = stagePointerPosition(event)
    const picked = renderer.pick(x, y)
    if (picked) {
      vm.selectTarget(picked)
    }
  }

  function updateMouse(event: MouseEvent | PointerEvent, patch: Record<string, unknown> = {}) {
    const data = {
      ...stagePointerData(event),
      isDown: event.buttons > 0,
      down: event.buttons > 0,
      buttons: event.buttons,
      ...patch,
    }
    if (runtimeInWorker) runtimeWorker.postMouse(data)
    else vm.postMouse(data)
  }

  function beginStageSpriteDrag(event: PointerEvent) {
    suppressNextStageClick = false
    updateMouse(event)
    if (stageSpriteDrag) cancelStageSpriteDrag()
    if (event.button !== 0) return
    const { x, y } = stagePointerPosition(event)
    const picked = renderer.pick(x, y)
    if (!picked) return
    const target = vm.getTarget(picked)
    if (!target || target.isStage) return
    vm.selectTarget(target.id ?? target.name)
    if (runtimeInWorker) runtimeWorker.startDrag(target.id ?? target.name)
    else vm.startDrag(target.id ?? target.name)
    stageCanvas.setPointerCapture(event.pointerId)
    stageSpriteDrag = {
      targetId: target.id ?? target.name,
      pointerId: event.pointerId,
      startClientX: event.clientX,
      startClientY: event.clientY,
      offsetX: x - (target.x ?? 0),
      offsetY: y - (target.y ?? 0),
      moved: false,
    }
  }

  function dragStageSprite(event: PointerEvent) {
    updateMouse(event)
    if (!stageSpriteDrag || stageSpriteDrag.pointerId !== event.pointerId) return
    if (!stageSpriteDrag.moved && Math.hypot(event.clientX - stageSpriteDrag.startClientX, event.clientY - stageSpriteDrag.startClientY) < 4) return
    const { x, y } = stagePointerPosition(event)
    const next = renderer.getFencedPositionOfDrawable(stageSpriteDrag.targetId, [
      x - stageSpriteDrag.offsetX,
      y - stageSpriteDrag.offsetY,
    ])
    const target = vm.getTarget(stageSpriteDrag.targetId)
    if (!target) return
    if (Math.abs((target.x ?? 0) - next[0]) > 0.01 || Math.abs((target.y ?? 0) - next[1]) > 0.01) {
      stageSpriteDrag.moved = true
      const data = { targetId: stageSpriteDrag.targetId, x: next[0], y: next[1] }
      if (runtimeInWorker) runtimeWorker.postSpriteInfo(data)
      else vm.postSpriteInfo(data)
    }
  }

  function endStageSpriteDrag(event: PointerEvent) {
    updateMouse(event, { wasDragged: stageSpriteDrag?.moved === true })
    if (!stageSpriteDrag || stageSpriteDrag.pointerId !== event.pointerId) return
    suppressNextStageClick = true
    if (runtimeInWorker) runtimeWorker.stopDrag(stageSpriteDrag.targetId)
    else vm.stopDrag(stageSpriteDrag.targetId)
    if (stageCanvas.hasPointerCapture(event.pointerId)) stageCanvas.releasePointerCapture(event.pointerId)
    stageSpriteDrag = undefined
  }

  function cancelStageSpriteDrag(event?: PointerEvent | Event) {
    if (!stageSpriteDrag) return
    if (runtimeInWorker) runtimeWorker.stopDrag(stageSpriteDrag.targetId)
    else vm.stopDrag(stageSpriteDrag.targetId)
    const pointerId = event instanceof PointerEvent ? event.pointerId : stageSpriteDrag.pointerId
    if (stageCanvas?.hasPointerCapture?.(pointerId)) stageCanvas.releasePointerCapture(pointerId)
    stageSpriteDrag = undefined
  }

  const questionKeys = new Set<string>()
  const runtimeKeys = new Set<string>()
  function clearQuestionKeys() { questionKeys.clear(); runtimeKeys.clear() }
  // Focus loss closes the nudge cycle (reference keyup parity): commit what
  // moved without waiting for a keyup that may never arrive.
  function handleWindowBlurForNudge() { void flushNudgePending() }
  function isQuestionInput(target: EventTarget | null): boolean {
    return target instanceof HTMLInputElement && target.dataset.testid === 'stage-answer-input'
  }
  function handleKeyDown(event: KeyboardEvent) {
    if (isQuestionInput(event.target)) {
      questionKeys.add(event.code || event.key)
      return
    }
    if (libraryPanel && event.key === 'Escape') {
      event.preventDefault()
      closeLibraryFromButton()
      return
    }
    const target = event.target
    if (selectedTab === 'costumes' && isPlainEscapeKey(event)) {
      // Popover-first Escape (compact toolbar fix): one plain Escape closes
      // the active Fill/Outline dialog and retains the selection; the next
      // Escape runs the normal deselect below. Scoped per editor instance so
      // two simultaneous Editors never cross-cancel. Runs before the typing
      // guard because an input-focus Escape must still close first (the old
      // button-focus path deselected before the bubble close).
      // IME composition and an open inline-text draft own the key.
      const inScope = !editorRootNode || !(target instanceof Node) || editorRootNode.contains(target)
      if (inScope) {
        if (!shouldDeferPopoverEscapeToIme(event, false) && !isPopoverEscapeInTextDraft(target)) {
          const draftInScope = editorRootNode ? hasTextDraftInScope(editorRootNode) : false
          if (!draftInScope) {
            const popoverOpenInScope =
              paintPopoverOpen ??
              (editorRootNode?.querySelector?.('[data-paint-popover-open="true"]') ? 'fill' : null)
            if (eyedropperActive) {
              event.preventDefault()
              event.stopPropagation()
              const closedKind = paintPopoverOpen
              if (paintPopoverOpen !== null) {
                paintPopoverOpen = null
                void flushHsvLive()
              }
              cancelEyedropper()
              focusPopoverTrigger(closedKind)
              return
            }
            if (popoverOpenInScope !== null && paintPopoverOpen !== null) {
              event.preventDefault()
              event.stopPropagation()
              const closedKind = paintPopoverOpen
              paintPopoverOpen = null
              void flushHsvLive()
              focusPopoverTrigger(closedKind)
              return
            }
            // DOM-hook fallback: the bound state can lag one tick behind the
            // child toggle (or a remount race); the scoped attribute is the
            // same single source, never a global query.
            if (popoverOpenInScope !== null && editorRootNode?.querySelector?.('[data-paint-popover-open="true"]')) {
              event.preventDefault()
              event.stopPropagation()
              paintPopoverOpen = null
              void flushHsvLive()
              focusPopoverTrigger(closedKindOf(editorRootNode))
              return
            }
          } else {
            // Text draft owns Escape: commit path lives in the overlay, never
            // close the popover nor deselect from here.
            return
          }
        } else {
          // IME composition owns the key (no close, no deselect) and a
          // draft-target Escape belongs to the draft commit path.
          return
        }
      }
    }
    if (isShortcutTypingTarget(target)) return
    if (selectedTab === 'costumes') {
      // The eyedropper overlay owns Escape (cancel without touching colors)
      // and swallows canvas-mutating shortcuts while active so one stray key
      // can never reshape the artwork mid-pick. Undo/redo stay available.
      // Typing targets already returned above, so text drafts are unaffected.
      if (eyedropperActive) {
        if (event.key === 'Escape' && !event.metaKey && !event.ctrlKey) {
          event.preventDefault()
          cancelEyedropper()
          return
        }
        const peek = resolveCostumeShortcut({
          key: event.key,
          ctrlOrMeta: event.metaKey || event.ctrlKey,
          shift: event.shiftKey,
        })
        if (peek === 'undo') {
          event.preventDefault()
          void undoAssetEdit()
          return
        }
        if (peek === 'redo') {
          event.preventDefault()
          void redoAssetEdit()
          return
        }
        if (peek === 'deselect' || peek === 'delete' || peek === 'select-all' || peek === 'copy' || peek === 'cut' || peek === 'paste' || peek === 'group' || peek === 'ungroup') {
          event.preventDefault()
          return
        }
        if (!event.metaKey && !event.ctrlKey && event.key.startsWith('Arrow')) {
          event.preventDefault()
          return
        }
      }
      const action = resolveCostumeShortcut({
        key: event.key,
        ctrlOrMeta: event.metaKey || event.ctrlKey,
        shift: event.shiftKey,
      })
      // A pending nudge press-release cycle owns exactly one history entry
      // committed on keyup. Any other costume action first finalizes it (via
      // the same keyup path) and then re-enters this handler, so the nudge
      // entry lands before the action's own entry and no preview is lost.
      if (action && nudgePending) {
        event.preventDefault()
        void flushNudgePending().then(() => handleKeyDown(event))
        return
      }
      if (action) {
        // Keep shortcuts inside the costume editor: never fall through to the
        // runtime keyboard path, and never steal keys from other tabs.
        if (action === 'undo') {
          event.preventDefault()
          void undoAssetEdit()
          return
        }
        if (action === 'redo') {
          event.preventDefault()
          void redoAssetEdit()
          return
        }
        if (action === 'deselect') {
          event.preventDefault()
          // An active reshape drag owns Escape: cancel the drag and restore
          // the start snapshot, keeping the pre-drag object/point selection.
          // Without an active drag this falls through to the normal
          // deselect (which also cancels any stray drag before clearing).
          if (vectorPathPointDrag) {
            cancelVectorPathPointDrag()
            return
          }
          if (vectorLeafTranslateDrag) {
            cancelVectorLeafTranslateDrag()
            return
          }
          clearCostumeSelection()
          return
        }
        if (action === 'delete') {
          event.preventDefault()
          void deleteEditorSelection()
          return
        }
        if (action === 'select-all') {
          event.preventDefault()
          if (costumeEditMode === 'bitmap' && bitmapTool !== 'select') bitmapTool = 'select'
          selectAllCostume()
          return
        }
        if (action === 'copy') {
          event.preventDefault()
          void copyCostumeSelection()
          return
        }
        if (action === 'cut') {
          event.preventDefault()
          void cutCostumeSelection()
          return
        }
        if (action === 'paste') {
          event.preventDefault()
          // Pending gate BEFORE the synchronous rect->select tool switch: the
          // switch itself auto-commits via the paint-tool-switch watcher, so
          // switching first would start an async commit and then paste on
          // stale state (ghost paste). Gate first; on success switch + paste,
          // on refuse retain pending/clipboard with no canvas touch. Disabled
          // path keeps the legacy order with no extra await.
          if (BITMAP_PENDING_UI_ENABLED && costumeEditMode === 'bitmap') {
            let hasPastePending = false
            try {
              const pasteKeySession = ensureBitmapPendingController()?.get()
              hasPastePending = Boolean(
                pasteKeySession &&
                  (pasteKeySession.snapshot().hasPending || pasteKeySession.snapshot().commitInFlight),
              )
            } catch {
              status = 'Bitmap paste blocked (pending state unreadable; op blocked, original preserved)'
              return
            }
            if (hasPastePending) {
              void (async () => {
                const keyEpochTargetId = selectedTarget ? stableTargetId(selectedTarget) : ''
                const keyEpochIndex = selectedTarget?.currentCostume ?? 0
                const keyEpochSerial = bitmapCanvasReloadSerial
                const keyEpochGeneration = bitmapWorkspaceGeneration
                const keyEpochCanvas = bitmapCanvas
                const keyEpochScope = selectedTarget ? captureDiscreteSaveScope(keyEpochTargetId, keyEpochIndex) : undefined
                const keyOk = await guardBitmapPendingCommitFirst('paint-paste')
                if (!keyOk) return
                const keyLiveId = selectedTarget ? stableTargetId(selectedTarget) : ''
                if (keyLiveId !== keyEpochTargetId || (selectedTarget?.currentCostume ?? 0) !== keyEpochIndex) {
                  status = 'Bitmap paste blocked (target switched during pending commit; original preserved)'
                  return
                }
                if (bitmapCanvasReloadSerial !== keyEpochSerial || bitmapWorkspaceGeneration !== keyEpochGeneration || bitmapCanvas !== keyEpochCanvas) {
                  status = 'Bitmap paste blocked (canvas reloaded during pending commit; original preserved)'
                  return
                }
                if (keyEpochScope && !isDiscreteSaveScopeCurrent(keyEpochScope, discreteSaveLiveOf(keyEpochScope))) {
                  status = 'Bitmap paste blocked (workspace changed during pending commit; original preserved)'
                  return
                }
                // Commit already landed; the reactive tool-switch watcher now
                // sees nothing-to-commit, so switching here cannot double-commit.
                if (costumeEditMode === 'bitmap' && bitmapTool !== 'select') bitmapTool = 'select'
                await pasteCostumeSelection()
              })()
              return
            }
          }
          if (costumeEditMode === 'bitmap' && bitmapTool !== 'select') bitmapTool = 'select'
          void pasteCostumeSelection()
          return
        }
        if (action === 'group' || action === 'ungroup') {
          if (costumeEditMode !== 'vector') {
            event.preventDefault()
            return
          }
          event.preventDefault()
          void editVectorObject(action)
          return
        }
      }
      if (!event.metaKey && !event.ctrlKey && event.key.startsWith('Arrow')) {
        const hasVectorSelection = selectedVectorObjectIndex >= 0 || selectedVectorObjectIndices.length > 0
        if (costumeEditMode === 'vector' && hasVectorSelection) {
          if (isNudgeArrowKey(event.key)) {
            event.preventDefault()
            void handleArrowNudge(event.key, event.shiftKey)
            return
          }
        } else if (costumeEditMode === 'bitmap' && bitmapSelection) {
          if (isNudgeArrowKey(event.key)) {
            event.preventDefault()
            void handleArrowNudge(event.key, event.shiftKey)
            return
          }
        }
      }
    }
    if (selectedTab === 'sounds' && selectedTarget?.sounds[selectedSoundIndex]) {
      if (event.key === ' ') {
        event.preventDefault()
        if (previewAudio) stopPreviewSound()
        else void previewSound(selectedSoundIndex)
        return
      }
      if (event.key === 'Delete' || event.key === 'Backspace') {
        event.preventDefault()
        void deleteSoundSelection(selectedSoundIndex, event.shiftKey)
        return
      }
      if (event.key === 'Escape') {
        event.preventDefault()
        soundTrimStart = 0
        soundTrimEnd = 1
        return
      }
      if (event.metaKey || event.ctrlKey) {
        const key = event.key.toLowerCase()
        if (key === 'z') {
          event.preventDefault()
          void (event.shiftKey ? redoAssetEdit() : undoAssetEdit())
          return
        }
        if (key === 'c') {
          event.preventDefault()
          void copySound(selectedSoundIndex)
          return
        }
        if (key === 'v') {
          event.preventDefault()
          void pasteSound(selectedSoundIndex)
          return
        }
        if (key === 'a') {
          event.preventDefault()
          soundTrimStart = 0
          soundTrimEnd = 1
          return
        }
      }
    }
    if (isScratchRuntimeKey(event)) event.preventDefault()
    runtimeKeys.add(event.code || event.key)
    const data = { key: scratchKeyName(event), isDown: true, pressed: true }
    if (runtimeInWorker) runtimeWorker.postKeyboard(data)
    else vm.postKeyboard(data)
  }

  function handleKeyUp(event: KeyboardEvent) {
    // Reference parity: one history entry per press-release cycle. The commit
    // runs for arrow keyups regardless of focus (typing guards live on the
    // keydown side; a keyup landing in an input must still close the cycle),
    // while runtime-key bookkeeping below keeps its existing guards.
    if (isNudgeArrowKey(event.key)) void flushNudgePending()
    const key = event.code || event.key
    const questionKey = questionKeys.delete(key)
    const runtimeKey = runtimeKeys.delete(key)
    if (!runtimeKey && (questionKey || isQuestionInput(event.target))) return
    // Keydown already ignores typing targets, so an untracked key released
    // from an input must not leak a key-up press into the running project.
    if (!runtimeKey && isShortcutTypingTarget(event.target)) return
    if (isScratchRuntimeKey(event)) event.preventDefault()
    const data = { key: scratchKeyName(event), isDown: false, pressed: false }
    if (runtimeInWorker) runtimeWorker.postKeyboard(data)
    else vm.postKeyboard(data)
  }

  function isScratchRuntimeKey(event: KeyboardEvent) {
    return event.key === 'ArrowUp' || event.key === 'ArrowDown' || event.key === 'ArrowLeft' || event.key === 'ArrowRight' || event.key === ' '
  }

  function trimSilence(samples: Float32Array) {
    const threshold = 0.012
    let start = 0
    let end = samples.length
    while (start < end && Math.abs(samples[start] ?? 0) < threshold) start += 1
    while (end > start && Math.abs(samples[end - 1] ?? 0) < threshold) end -= 1
    const padding = Math.floor(recordingSampleRate * 0.03)
    return samples.slice(Math.max(0, start - padding), Math.min(samples.length, end + padding))
  }

  function zoomBlockly(amount: number) {
    workspace?.zoomCenter(amount)
  }

  function resetBlocklyZoom() {
    if (!workspace) return
    const zoom = Math.log(0.86 / workspace.scale) / Math.log(1.1)
    workspace.beginCanvasTransition()
    workspace.zoomCenter(zoom)
    workspace.scrollCenter()
    setTimeout(() => workspace?.endCanvasTransition(), 500)
  }

  function mountBlockly() {
    workspace = Blockly.inject(blocklyHost, {
      toolbox: makeToolbox(selectedTarget, project.extensions, stage, targets, project.monitors),
      renderer: 'zelos',
      theme: colorScheme === 'dark' ? darkBlocklyTheme : scratchBlocklyTheme,
      trashcan: true,
      scrollbars: true,
      sounds: false,
      move: {
        scrollbars: true,
        drag: true,
        wheel: false,
      },
      zoom: {
        controls: true,
        wheel: true,
        startScale: 0.86,
        maxScale: 2,
        minScale: 0.35,
        scaleSpeed: 1.1,
      },
      grid: {
        spacing: 38,
        length: 2,
        colour: '#d9d9d9',
        snap: false,
      },
    })
    workspace.registerButtonCallback('CREATE_VARIABLE', createVariable)
    workspace.registerButtonCallback('CREATE_LIST', createList)
    workspace.registerButtonCallback('CREATE_BLOCK', createProcedure)
    workspace.registerButtonCallback('OPEN_EXTENSIONS', () => openLibrary('extension'))
    registerDataMonitorCallbacks()
    tick().then(() => {
      keepToolboxExpanded()
      renderMonitorCheckboxesInFlyout()
    })
    blocklyPointerUpHandler = () => requestAnimationFrame(() => {
      keepToolboxExpanded()
      renderMonitorCheckboxesInFlyout()
    })
    blocklySelectedCategoryPointerDownHandler = suppressSelectedToolboxCategoryClick
    blocklyHost.addEventListener('pointerup', blocklyPointerUpHandler)
    blocklyHost.addEventListener('pointerdown', blocklySelectedCategoryPointerDownHandler, { capture: true })
    workspace.addChangeListener((event) => {
      if (loadingBlockly) return
      if (event.type === Blockly.Events.CLICK) {
        handleBlocklyClick(event)
        tick().then(() => {
          keepToolboxExpanded()
          renderMonitorCheckboxesInFlyout()
        })
        return
      }
      if (event.isUiEvent || event.type === Blockly.Events.FINISHED_LOADING) return
      if (event.type === Blockly.Events.MOVE && !event.group) return
      if (event.type === Blockly.Events.VIEWPORT_CHANGE) {
        requestAnimationFrame(() => {
          keepToolboxExpanded()
          renderMonitorCheckboxesInFlyout()
        })
        return
      }
      if (runtimeInWorker && snapshot.running) return
      if (!selectedTarget || selectedTarget.isStage) return
      vm.applyWorkspaceChange(selectedTarget.id ?? selectedTarget.name, {
        blocks: workspaceToScratchBlocks(workspace!, selectedTarget, stage),
      })
    })
    resizeObserver = new ResizeObserver(() => {
      if (!workspace) return
      Blockly.svgResize(workspace)
      // Blockly can reposition the flyout scrollbar while resizing the host.
      // Reapply the fixed-width palette layout after Blockly finishes its resize.
      requestAnimationFrame(() => {
        if (!editorDestroyed) normalizeToolboxFlyoutWidth()
      })
    })
    resizeObserver.observe(blocklyHost)
    if (!selectedExternalTabId && selectedTab === 'code' && selectedTarget) loadTargetWorkspace(selectedTarget)
  }

  function selectedToolboxCategoryName() {
    if (!workspace) return undefined
    const toolbox = workspace.getToolbox() as unknown as {
      getSelectedItem?: () => unknown
    } | null
    return toolboxItemName(toolbox?.getSelectedItem?.())
  }

  function flyoutScrollPosition() {
    const flyoutWorkspace = workspace?.getFlyout()?.getWorkspace()
    return flyoutWorkspace ? { x: flyoutWorkspace.scrollX, y: flyoutWorkspace.scrollY } : undefined
  }

  function restoreFlyoutScrollPosition(position: { x: number; y: number } | undefined) {
    if (!position) return
    const flyoutWorkspace = workspace?.getFlyout()?.getWorkspace()
    flyoutWorkspace?.scroll(position.x, position.y)
  }

  function renderMonitorCheckboxesInFlyout() {
    const flyoutWorkspace = workspace?.getFlyout()?.getWorkspace()
    if (!flyoutWorkspace || selectedExternalTabId || selectedTab !== 'code') return
    flyoutWorkspace.getCanvas().querySelectorAll('.hikkaku-monitor-checkbox').forEach((node) => node.remove())
    const blocks = flyoutWorkspace.getTopBlocks(false) as Blockly.BlockSvg[]
    for (const block of blocks) {
      const action = monitorActionForFlyoutBlock(block)
      if (!action) continue
      const root = block.getSvgRoot() as SVGGElement | null
      if (!root) continue
      const shiftedRoot = root as SVGGElement & { __hikkakuMonitorCheckboxShifted?: boolean }
      if (!shiftedRoot.__hikkakuMonitorCheckboxShifted) {
        block.moveBy(40, 0, ['hikkaku-monitor-checkbox'])
        shiftedRoot.__hikkakuMonitorCheckboxShifted = true
      }
      const position = block.getRelativeToSurfaceXY()
      const size = block.getHeightWidth()
      const checkbox = createFlyoutMonitorCheckbox(action.checked)
      checkbox.setAttribute('transform', `translate(${position.x - 30},${position.y + Math.max(2, (size.height - 16) / 2)})`)
      checkbox.addEventListener('pointerdown', (event) => {
        event.preventDefault()
        event.stopPropagation()
      })
      checkbox.addEventListener('click', (event) => {
        event.preventDefault()
        event.stopPropagation()
        action.toggle()
        requestAnimationFrame(() => renderMonitorCheckboxesInFlyout())
      })
      flyoutWorkspace.getCanvas().appendChild(checkbox)
    }
  }

  function ensureFlyoutBottomPadding() {
    const flyoutWorkspace = workspace?.getFlyout()?.getWorkspace()
    if (!flyoutWorkspace || selectedExternalTabId || selectedTab !== 'code') return
    const canvas = flyoutWorkspace.getCanvas()
    canvas.querySelectorAll('.hikkaku-flyout-bottom-padding').forEach((node) => node.remove())
    let contentBottom = 0
    try {
      const box = (canvas as unknown as SVGGraphicsElement).getBBox()
      if (Number.isFinite(box.y) && Number.isFinite(box.height)) contentBottom = box.y + box.height
    } catch {
      contentBottom = 0
    }
    // The flyout measures scrollable content from rendered SVG bounds, so a
    // virtual trailing separator alone cannot extend the scroll range. Append a
    // transparent spacer so the last section (usually ブロック定義) can scroll
    // to the top of the pane: it needs at least one pane height below its label.
    const flyoutSvg = blocklyHost?.querySelector<SVGSVGElement>('.blocklyToolboxFlyout')
    const paneHeight = flyoutSvg?.getBoundingClientRect().height ?? blocklyHost?.clientHeight ?? 0
    const scale = flyoutWorkspace.scale || 1
    const paddingHeight = Math.max(0, Math.ceil((paneHeight > 0 ? paneHeight : 600) / scale))
    if (paddingHeight <= 0) return
    const spacer = document.createElementNS('http://www.w3.org/2000/svg', 'rect')
    spacer.classList.add('hikkaku-flyout-bottom-padding')
    spacer.setAttribute('x', '0')
    spacer.setAttribute('y', String(contentBottom))
    spacer.setAttribute('width', '1')
    spacer.setAttribute('height', String(paddingHeight))
    spacer.setAttribute('fill', 'transparent')
    spacer.setAttribute('pointer-events', 'none')
    canvas.appendChild(spacer)
    try {
      ;(flyoutWorkspace.scrollbar as unknown as { resize?: () => void } | undefined)?.resize?.()
    } catch {
      // Scrollbar refresh is best-effort; the next resize/scroll updates it.
    }
  }

  function monitorActionForFlyoutBlock(block: Blockly.BlockSvg): { checked: boolean; toggle: () => void } | undefined {
    if (block.type === 'data_variable') {
      const variableName = String(block.getFieldValue('VARIABLE_NAME') ?? '')
      const record = dataOwnerForVariableName(variableName)
      if (!record) return undefined
      return {
        checked: variableMonitorVisible(record.owner, record.id),
        toggle: () => toggleVariableMonitor(record.id),
      }
    }
    if (block.type === 'data_listcontents') {
      const listName = String(block.getFieldValue('LIST_NAME') ?? '')
      const record = dataOwnerForListName(listName)
      if (!record) return undefined
      return {
        checked: listMonitorVisible(record.owner, record.id),
        toggle: () => toggleListMonitor(record.id),
      }
    }
    const spec = monitorableReporterSpecs.find((candidate) => candidate.opcode === block.type)
    if (!spec) return undefined
    const params = spec.params ?? {}
    return {
      checked: blockMonitorVisible(block.type, params),
      toggle: () => toggleBlockMonitor(block.type, params),
    }
  }

  function variableMonitorVisible(owner: ScratchTarget, id: string) {
    const monitorId = `${owner.id ?? owner.name}:${id}`
    return project.monitors.some((monitor) => monitor.opcode === 'data_variable' && monitor.visible && (monitor.id === monitorId || monitor.id.endsWith(`:${id}`)))
  }

  function listMonitorVisible(owner: ScratchTarget, id: string) {
    const monitorId = `${owner.id ?? owner.name}:${id}`
    return project.monitors.some((monitor) => monitor.opcode === 'data_listcontents' && monitor.visible && (monitor.id === monitorId || monitor.id.endsWith(`:${id}`)))
  }

  function blockMonitorVisible(opcode: string, params: Record<string, string>) {
    const owner = selectedTarget ?? stage
    return project.monitors.some((monitor) =>
      monitor.opcode === opcode
      && monitor.visible
      && (!monitor.spriteName || !owner || monitor.spriteName === owner.name)
      && Object.entries(params).every(([key, value]) => String(monitor.params[key] ?? '') === value))
  }

  function createFlyoutMonitorCheckbox(checked: boolean) {
    const group = document.createElementNS('http://www.w3.org/2000/svg', 'g')
    group.classList.add('hikkaku-monitor-checkbox')
    group.setAttribute('role', 'button')
    group.setAttribute('aria-pressed', checked ? 'true' : 'false')
    group.style.cursor = 'pointer'
    const box = document.createElementNS('http://www.w3.org/2000/svg', 'rect')
    box.setAttribute('width', '16')
    box.setAttribute('height', '16')
    box.setAttribute('rx', '2')
    box.setAttribute('fill', checked ? '#4c97ff' : '#ffffff')
    box.setAttribute('stroke', checked ? '#3373cc' : '#c8c8d0')
    box.setAttribute('stroke-width', '1')
    group.appendChild(box)
    if (checked) {
      const mark = document.createElementNS('http://www.w3.org/2000/svg', 'path')
      mark.setAttribute('d', 'M4 8.2 7 11.2 12.5 4.8')
      mark.setAttribute('fill', 'none')
      mark.setAttribute('stroke', '#ffffff')
      mark.setAttribute('stroke-width', '2')
      mark.setAttribute('stroke-linecap', 'round')
      mark.setAttribute('stroke-linejoin', 'round')
      group.appendChild(mark)
    }
    return group
  }

  function toolboxItemName(item: unknown) {
    const candidate = item as { getName?: () => string } | undefined
    return candidate?.getName?.()
  }

  function makeWorkspaceToolboxSignature(
    target: ScratchTarget,
    stageTarget: ScratchTarget | undefined,
    allTargets: readonly ScratchTarget[],
    extensions: readonly string[],
  ) {
    const stageVariables = Object.entries(stageTarget?.variables ?? {}).map(([id, variable]) => `${id}:${variable[0]}`).join('|')
    const stageLists = Object.entries(stageTarget?.lists ?? {}).map(([id, list]) => `${id}:${list[0]}`).join('|')
    const targetVariables = Object.entries(target.variables).map(([id, variable]) => `${id}:${variable[0]}`).join('|')
    const targetLists = Object.entries(target.lists).map(([id, list]) => `${id}:${list[0]}`).join('|')
    return [
      target.id ?? target.name,
      extensions.join('|'),
      allTargets.map((nextTarget) => `${nextTarget.id ?? nextTarget.name}:${nextTarget.name}`).join('|'),
      stageVariables,
      stageLists,
      targetVariables,
      targetLists,
      target.costumes.map((costume) => costume.name).join('|'),
      stageTarget?.costumes.map((costume) => costume.name).join('|') ?? '',
      target.sounds.map((sound) => sound.name).join('|'),
      targetProcedureSignature(target),
    ].join(':')
  }

  function targetProcedureSignature(target: ScratchTarget) {
    const parts: string[] = []
    for (const [id, block] of Object.entries(target.blocks)) {
      if (block.opcode !== 'procedures_definition' && block.opcode !== 'procedures_prototype') continue
      const customBlockId = block.inputs?.custom_block?.[1]
      parts.push([
        id,
        block.opcode,
        typeof customBlockId === 'string' ? customBlockId : '',
        typeof block.mutation?.proccode === 'string' ? block.mutation.proccode : '',
        typeof block.mutation?.argumentids === 'string' ? block.mutation.argumentids : '',
        typeof block.mutation?.argumentnames === 'string' ? block.mutation.argumentnames : '',
        typeof block.mutation?.argumentdefaults === 'string' ? block.mutation.argumentdefaults : '',
        typeof block.mutation?.warp === 'string' ? block.mutation.warp : '',
      ].join(','))
    }
    return parts.join('|')
  }

  function toolboxCategoryNameFromEventTarget(target: EventTarget | null) {
    if (!(target instanceof Element)) return undefined
    const categoryElement = target.closest<HTMLElement>('.blocklyToolboxCategoryContainer, .blocklyToolboxCategory, .blocklyTreeRow')
    if (!categoryElement || !blocklyHost?.contains(categoryElement)) return undefined
    return categoryElement
      .querySelector<HTMLElement>('.blocklyToolboxCategoryLabel, .blocklyTreeLabel')
      ?.textContent
      ?.trim()
  }

  function suppressSelectedToolboxCategoryClick(event: PointerEvent) {
    if (!workspace || event.button !== 0) return
    const categoryName = toolboxCategoryNameFromEventTarget(event.target)
    if (!categoryName || categoryName !== selectedToolboxCategoryName()) return
    event.preventDefault()
    event.stopImmediatePropagation()
    requestAnimationFrame(() => {
      normalizeToolboxFlyoutWidth()
      scrollContinuousFlyoutToCategory(categoryName)
    })
  }

  function keepToolboxExpanded(preferredCategoryName?: string, forceRefresh = false) {
    if (!workspace || selectedExternalTabId || selectedTab !== 'code') return
    const toolbox = workspace.getToolbox() as unknown as {
      clearSelection?: () => void
      getFlyout?: () => { isVisible?: () => boolean; setAutoClose?: (autoClose: boolean) => void } | null
      getSelectedItem?: () => unknown
      getToolboxItems?: () => unknown[]
      setSelectedItem?: (item: unknown) => void
    } | null
    if (!toolbox?.setSelectedItem || !toolbox.getToolboxItems) return
    lockToolboxPaletteScale(toolbox)
    keepContinuousToolboxFlyoutStable(toolbox)
    keepToolboxCategorySyncedToFlyoutScroll(toolbox)
    ensureFlyoutBottomPadding()
    const items = toolbox.getToolboxItems()
    const selected = toolbox.getSelectedItem?.()
    const flyout = toolbox.getFlyout?.()
    flyout?.setAutoClose?.(false)
    const flyoutVisible = flyout?.isVisible?.() === true
    if (selected && flyoutVisible && !forceRefresh) {
      const selectedName = toolboxItemName(selected)
      requestAnimationFrame(() => {
        normalizeToolboxFlyoutWidth()
        ensureFlyoutBottomPadding()
        renderMonitorCheckboxesInFlyout()
        if (selectedName && selectedName !== lastToolboxScrollCategoryName) {
          scrollContinuousFlyoutToCategory(selectedName)
          lastToolboxScrollCategoryName = selectedName
        }
      })
      return
    }
    const selectedName = toolboxItemName(selected)
    const targetName = preferredCategoryName ?? selectedName
    const namedItem = targetName ? items.find((entry) => toolboxItemName(entry) === targetName) : undefined
    const item = namedItem ?? selected ?? items.find((entry) => {
      const candidate = entry as { isSelectable?: () => boolean }
      return candidate.isSelectable?.() !== false
    })
    if (!item) return
    if (selected && (forceRefresh || !flyoutVisible)) toolbox.clearSelection?.()
    toolbox.setSelectedItem(item)
    Blockly.svgResize(workspace)
    requestAnimationFrame(() => {
      normalizeToolboxFlyoutWidth()
      ensureFlyoutBottomPadding()
      renderMonitorCheckboxesInFlyout()
      const itemName = toolboxItemName(item)
      scrollContinuousFlyoutToCategory(itemName)
      lastToolboxScrollCategoryName = itemName ?? ''
    })
  }

  function lockToolboxPaletteScale(toolbox: {
    getFlyout?: () => unknown
  }) {
    const flyout = toolbox.getFlyout?.() as {
      getFlyoutScale?: () => number
      getWorkspace?: () => Blockly.WorkspaceSvg
      setAutoClose?: (autoClose: boolean) => void
      __hikkakuPaletteScaleLocked?: boolean
    } | null
    flyout?.setAutoClose?.(false)
    if (!flyout || flyout.__hikkakuPaletteScaleLocked) return
    flyout.getFlyoutScale = () => toolboxPaletteScale
    flyout.getWorkspace?.().setScale(toolboxPaletteScale)
    flyout.__hikkakuPaletteScaleLocked = true
  }

  function keepContinuousToolboxFlyoutStable(toolbox: {
    getFlyout?: () => { isVisible?: () => boolean } | null
    updateFlyout_?: (oldItem: unknown, newItem: unknown) => void
    __hikkakuStableContinuousFlyout?: boolean
  }) {
    if (toolbox.__hikkakuStableContinuousFlyout || !toolbox.updateFlyout_) return
    const updateFlyout = toolbox.updateFlyout_.bind(toolbox)
    toolbox.updateFlyout_ = (oldItem: unknown, newItem: unknown) => {
      const oldName = toolboxItemName(oldItem)
      const newName = toolboxItemName(newItem)
      const oldContents = toolboxItemContents(oldItem)
      const newContents = toolboxItemContents(newItem)
      if (
        oldName &&
        newName &&
        toolbox.getFlyout?.()?.isVisible?.() === true &&
        oldContents &&
        newContents &&
        toolboxContentsMatch(oldContents, newContents)
      ) {
        return
      }
      updateFlyout(oldItem, newItem)
    }
    toolbox.__hikkakuStableContinuousFlyout = true
  }

  function keepToolboxCategorySyncedToFlyoutScroll(toolbox: {
    getFlyout?: () => unknown
    getSelectedItem?: () => unknown
    getToolboxItems?: () => unknown[]
    setSelectedItem?: (item: unknown) => void
  }) {
    const flyout = toolbox.getFlyout?.() as {
      getWorkspace?: () => Blockly.WorkspaceSvg & {
        scrollbar?: { setY?: (y: number) => void; __hikkakuCategorySyncInstalled?: boolean }
      }
    } | null
    const scrollbar = flyout?.getWorkspace?.().scrollbar
    if (!scrollbar?.setY || scrollbar.__hikkakuCategorySyncInstalled) return
    const setY = scrollbar.setY.bind(scrollbar)
    scrollbar.setY = (y: number) => {
      setY(y)
      scheduleToolboxCategorySync()
    }
    scrollbar.__hikkakuCategorySyncInstalled = true
  }

  function scheduleToolboxCategorySync() {
    if (toolboxCategorySyncAnimation !== undefined) return
    toolboxCategorySyncAnimation = requestAnimationFrame(() => {
      toolboxCategorySyncAnimation = undefined
      syncToolboxCategoryToFlyoutScroll()
    })
  }

  function syncToolboxCategoryToFlyoutScroll() {
    if (!workspace || selectedExternalTabId || selectedTab !== 'code') return
    const currentName = currentFlyoutCategoryName()
    if (!currentName || currentName === selectedToolboxCategoryName()) return
    const toolbox = workspace.getToolbox() as unknown as {
      getFlyout?: () => { isVisible?: () => boolean } | null
      getToolboxItems?: () => unknown[]
      setSelectedItem?: (item: unknown) => void
    } | null
    if (toolbox?.getFlyout?.()?.isVisible?.() !== true || !toolbox.setSelectedItem || !toolbox.getToolboxItems) return
    const item = toolbox.getToolboxItems().find((entry) => toolboxItemName(entry) === currentName)
    if (!item) return
    toolbox.setSelectedItem(item)
    lastToolboxScrollCategoryName = currentName
  }

  function currentFlyoutCategoryName() {
    const flyoutRect = blocklyHost?.querySelector<SVGSVGElement>('.blocklyToolboxFlyout')?.getBoundingClientRect()
    const labels = [...(blocklyHost?.querySelectorAll<SVGGElement>('.blocklyFlyoutLabel') ?? [])]
      .map((label) => ({ name: label.textContent?.trim() ?? '', top: label.getBoundingClientRect().top }))
      .filter((label) => label.name)
      .sort((a, b) => a.top - b.top)
    if (!flyoutRect || labels.length === 0) return undefined
    const threshold = flyoutRect.top + 12
    let current = labels[0]
    for (const label of labels) {
      if (label.top > threshold) break
      current = label
    }
    return current.name
  }

  function cancelToolboxCategorySync() {
    if (toolboxCategorySyncAnimation === undefined) return
    cancelAnimationFrame(toolboxCategorySyncAnimation)
    toolboxCategorySyncAnimation = undefined
  }

  function toolboxItemContents(item: unknown) {
    const candidate = item as { getContents?: () => unknown[] } | undefined
    return candidate?.getContents?.()
  }

  function toolboxContentsMatch(left: unknown[], right: unknown[]) {
    if (left.length !== right.length) return false
    return left.every((entry, index) => toolboxContentKey(entry) === toolboxContentKey(right[index]))
  }

  function toolboxContentKey(entry: unknown) {
    const item = entry as { kind?: unknown; text?: unknown; type?: unknown; callbackKey?: unknown } | undefined
    return `${String(item?.kind ?? '')}:${String(item?.text ?? '')}:${String(item?.type ?? '')}:${String(item?.callbackKey ?? '')}`
  }

  function normalizeToolboxFlyoutWidth() {
    const flyout = blocklyHost?.querySelector<SVGSVGElement>('.blocklyToolboxFlyout')
    const background = flyout?.querySelector<SVGPathElement>('.blocklyFlyoutBackground')
    if (!flyout) return
    flyout.style.width = `${toolboxFlyoutWidth}px`
    flyout.style.minWidth = `${toolboxFlyoutWidth}px`
    flyout.style.maxWidth = `${toolboxFlyoutWidth}px`
    flyout.style.overflow = 'hidden'
    flyout.setAttribute('width', String(toolboxFlyoutWidth))
    if (!background) return
    const height = flyout.getBoundingClientRect().height
    const radius = 8
    const widthWithoutRadius = toolboxFlyoutWidth - radius
    background.setAttribute('d', `M 0,0 h ${widthWithoutRadius} a ${radius} ${radius} 0 0 1 ${radius} ${radius} v ${Math.max(0, height - radius * 2)} a ${radius} ${radius} 0 0 1 -${radius} ${radius} h -${widthWithoutRadius} z`)
    const flyoutRect = flyout.getBoundingClientRect()
    const scrollbar = [...blocklyHost.querySelectorAll<SVGSVGElement>('.blocklyFlyoutScrollbar')]
      .find((candidate) => {
        const rect = candidate.getBoundingClientRect()
        return rect.height > 0 && rect.left > flyoutRect.left
      })
    if (!scrollbar) return
    const scrollbarRect = scrollbar.getBoundingClientRect()
    const targetLeft = flyoutRect.left + toolboxFlyoutWidth - scrollbarRect.width - 3
    const [currentX, currentY] = svgTranslate(scrollbar)
    scrollbar.style.transform = `translate(${currentX + targetLeft - scrollbarRect.left}px, ${currentY}px)`
  }

  function scrollContinuousFlyoutToCategory(categoryName?: string) {
    if (!workspace || !categoryName) return
    ensureFlyoutBottomPadding()
    const flyout = workspace.getToolbox()?.getFlyout?.() as {
      getWorkspace?: () => Blockly.WorkspaceSvg & {
        getMetrics?: () => { viewTop?: number } | null
        scrollbar?: { setY?: (y: number) => void }
      }
    } | null
    const flyoutWorkspace = flyout?.getWorkspace?.()
    const flyoutSvg = blocklyHost?.querySelector<SVGSVGElement>('.blocklyToolboxFlyout')
    const label = [...(blocklyHost?.querySelectorAll<SVGGElement>('.blocklyFlyoutLabel') ?? [])]
      .find((candidate) => candidate.textContent?.trim() === categoryName)
    if (!flyoutWorkspace || !flyoutSvg || !label) return
    const labelRect = label.getBoundingClientRect()
    const flyoutRect = flyoutSvg.getBoundingClientRect()
    const delta = labelRect.top - flyoutRect.top - 8
    if (Math.abs(delta) < 2) return
    const currentTop = flyoutWorkspace.getMetrics?.()?.viewTop ?? 0
    smoothScrollContinuousFlyout(flyoutWorkspace, Math.max(0, currentTop + delta))
  }

  function smoothScrollContinuousFlyout(
    flyoutWorkspace: Blockly.WorkspaceSvg & {
      getMetrics?: () => { viewTop?: number } | null
      scrollbar?: { setY?: (y: number) => void }
    },
    targetTop: number,
  ) {
    const scrollbar = flyoutWorkspace.scrollbar
    if (!scrollbar?.setY) return
    const startTop = flyoutWorkspace.getMetrics?.()?.viewTop ?? 0
    const distance = targetTop - startTop
    if (Math.abs(distance) < 2 || (typeof window !== 'undefined' && window.matchMedia('(prefers-reduced-motion: reduce)').matches)) {
      cancelContinuousFlyoutScroll()
      scrollbar.setY(Math.max(0, targetTop))
      return
    }
    cancelContinuousFlyoutScroll()
    const startTime = performance.now()
    const duration = 220
    const step = (time: number) => {
      const progress = Math.min(1, (time - startTime) / duration)
      const eased = 1 - (1 - progress) ** 3
      scrollbar.setY(Math.max(0, startTop + distance * eased))
      if (progress < 1) {
        toolboxFlyoutScrollAnimation = requestAnimationFrame(step)
        return
      }
      toolboxFlyoutScrollAnimation = undefined
    }
    toolboxFlyoutScrollAnimation = requestAnimationFrame(step)
  }

  function cancelContinuousFlyoutScroll() {
    if (toolboxFlyoutScrollAnimation === undefined) return
    cancelAnimationFrame(toolboxFlyoutScrollAnimation)
    toolboxFlyoutScrollAnimation = undefined
  }

  function svgTranslate(element: SVGElement): [number, number] {
    const transform = getComputedStyle(element).transform
    if (transform === 'none') return [0, 0]
    const matrix = transform.match(/matrix\(([^)]+)\)/)?.[1]?.split(',').map((value) => Number(value.trim()))
    if (matrix && matrix.length >= 6) return [matrix[4] ?? 0, matrix[5] ?? 0]
    const translate = transform.match(/translate\(([-.\d]+)px,\s*([-.\d]+)px\)/)
    return [Number(translate?.[1] ?? 0), Number(translate?.[2] ?? 0)]
  }

  function handleBlocklyClick(event: Blockly.Events.Abstract) {
    if (!selectedTarget || selectedTarget.isStage || !workspace) return
    const click = event as Blockly.Events.Abstract & { blockId?: string; targetType?: string }
    if (click.targetType !== 'block' || !click.blockId) return
    const block = workspace.getBlockById(click.blockId) as Blockly.BlockSvg | null
    if (!block || block.isInFlyout) return
    const targetId = selectedTarget.id ?? selectedTarget.name
    if (block.outputConnection) {
      if (runtimeInWorker) runtimeWorker.reportBlockValue(block.id, targetId)
      else {
        try {
          vm.reportBlockValue(block.id, targetId)
        } catch (error) {
          status = error instanceof Error ? error.message : String(error)
        }
      }
      return
    }
    const rootBlock = (block?.getRootBlock() ?? block) as Blockly.BlockSvg | null
    if (!rootBlock || rootBlock.isInFlyout) return
    if (runtimeInWorker) runtimeWorker.toggleScript(rootBlock.id, targetId)
    else {
      try {
        vm.toggleScript(rootBlock.id, targetId)
      } catch (error) {
        status = error instanceof Error ? error.message : String(error)
        return
      }
    }
    status = 'Script toggled'
  }

  function showVisualReport(blockId: string, value: string) {
    status = `Value: ${value}`
    if (!workspace || !blocklyHost) return
    const block = workspace.getBlockById(blockId) as Blockly.BlockSvg | null
    const blockRoot = block?.getSvgRoot()
    if (!blockRoot) return
    const hostRect = blocklyHost.getBoundingClientRect()
    const blockRect = blockRoot.getBoundingClientRect()
    visualReportBubble = {
      id: blockId,
      value,
      left: Math.max(8, blockRect.right - hostRect.left + 8),
      top: Math.max(8, blockRect.top - hostRect.top + blockRect.height / 2),
    }
    if (visualReportTimer) clearTimeout(visualReportTimer)
    visualReportTimer = setTimeout(() => {
      visualReportBubble = undefined
      visualReportTimer = undefined
    }, 2600)
  }

  function syncRuntimeBlockHighlights() {
    if (!workspace || !selectedTarget) return
    const targetName = selectedTarget.name
    const nextIds = new Set(
      snapshot.threads
        .filter((thread) => thread.targetName === targetName && thread.status !== 'done')
        .map((thread) => thread.topBlockId)
        .filter((blockId) => Boolean(workspace?.getBlockById(blockId)))
    )
    for (const blockId of highlightedRuntimeBlockIds) {
      if (!nextIds.has(blockId)) workspace.highlightBlock(blockId, false)
    }
    for (const blockId of nextIds) {
      if (!highlightedRuntimeBlockIds.has(blockId)) workspace.highlightBlock(blockId, true)
    }
    highlightedRuntimeBlockIds = nextIds
  }

  function clearRuntimeBlockHighlights() {
    if (workspace) workspace.highlightBlock(null)
    highlightedRuntimeBlockIds = new Set()
  }

  function loadTargetWorkspace(target: ScratchTarget) {
    if (!workspace) return
    const loadSerial = ++workspaceLoadSerial
    loadingBlockly = true
    const targetId = target.id ?? target.name
    Blockly.Events.disable()
    workspace.setResizesEnabled(false)
    try {
      clearRuntimeBlockHighlights()
      workspace.clear()
      const created = new Map<string, Blockly.BlockSvg>()
      const literalInputs = new Set<Blockly.BlockSvg>()
      for (const [id, block] of Object.entries(target.blocks)) {
        if (!Blockly.Blocks[block.opcode]) continue
        if (isProcedurePrototypeArgumentShadow(block, target.blocks)) continue
        const next = workspace.newBlock(block.opcode, id) as Blockly.BlockSvg
        if (block.shadow) next.setShadow(true)
        applyScratchFields(next, block, { connectLiteralInputs: false })
        attachScratchBlockState(next, block)
        if (block.x !== undefined && block.y !== undefined) next.moveBy(block.x, block.y)
        next.initSvg()
        created.set(id, next)
      }
      for (const [id, block] of Object.entries(target.blocks)) {
        if (isProcedurePrototypeArgumentShadow(block, target.blocks)) continue
        const source = created.get(id)
        if (!source) continue
        if (block.next) {
          const next = created.get(block.next)
          if (next && source.nextConnection && next.previousConnection) {
            source.nextConnection.connect(next.previousConnection)
          }
        }
        for (const [name, input] of Object.entries(block.inputs ?? {})) {
          const shadowValue = input[0] === 3 ? input[2] : undefined
          const shadow = typeof shadowValue === 'string' ? created.get(shadowValue) : undefined
          const childValue = input[1]
          const child = typeof childValue === 'string'
            ? created.get(childValue)
            : Array.isArray(childValue)
              ? createLiteralInputBlock(childValue, input[0] === 1 && literalInputIsShadow(childValue), block.opcode, name, false)
              : undefined
          if (Array.isArray(childValue) && child) literalInputs.add(child)
          const connection = source.getInput(name)?.connection
          if (shadow && connection && child && !child.isShadow()) {
            connection.setShadowState?.(blocklyShadowState(shadow))
            rememberScratchShadow(connection, String(shadowValue))
            shadow.dispose(false)
            created.delete(String(shadowValue))
          } else if (Array.isArray(shadowValue) && connection && child && !child.isShadow()) {
            const shadowState = blocklyShadowStateFromLiteral(shadowValue, block.opcode, name)
            if (shadowState) connection.setShadowState?.(shadowState)
          }
          if (child && connection && child.outputConnection) connection.connect(child.outputConnection)
          if (child && connection && child.previousConnection) connection.connect(child.previousConnection)
          if (Array.isArray(childValue) && child && !child.getParent()) child.dispose(false)
        }
      }
      workspaceTargetId = targetId
      workspace.render()
      cleanupFloatingImportLiterals(literalInputs)
      Blockly.svgResize(workspace)
      keepToolboxExpanded()
    } finally {
      workspace.setResizesEnabled(true)
      Blockly.Events.enable()
    }
    requestAnimationFrame(() => {
      if (loadSerial !== workspaceLoadSerial) return
      loadingBlockly = false
      syncRuntimeBlockHighlights()
    })
  }

  function syncSelectedTargetWorkspace(target: ScratchTarget) {
    const targetId = target.id ?? target.name
    if (shouldDeferBlocklyLoad(target)) {
      if (deferredBlocklyTargetId === targetId) return
      workspaceLoadSerial += 1
      loadingBlockly = false
      deferredBlocklyTargetId = targetId
      workspaceTargetId = ''
      clearRuntimeBlockHighlights()
      Blockly.Events.disable()
      try {
        workspace?.clear()
      } finally {
        Blockly.Events.enable()
      }
      return
    }
    if (workspaceTargetId === targetId && deferredBlocklyTargetId !== targetId) return
    deferredBlocklyTargetId = ''
    loadTargetWorkspace(target)
  }

  function shouldDeferBlocklyLoad(target: ScratchTarget) {
    const targetId = target.id ?? target.name
    return !forcedBlocklyTargetIds.has(targetId) && Object.keys(target.blocks).length > LARGE_WORKSPACE_BLOCK_LIMIT
  }

  function loadDeferredCodeWorkspace() {
    if (!selectedTarget) return
    const targetId = selectedTarget.id ?? selectedTarget.name
    forcedBlocklyTargetIds = new Set([...forcedBlocklyTargetIds, targetId])
    deferredBlocklyTargetId = ''
    loadTargetWorkspace(selectedTarget)
  }

  function isProcedurePrototypeArgumentShadow(block: ScratchBlock, blocks: Record<string, ScratchBlock>) {
    if (!block.shadow || !block.opcode.startsWith('argument_reporter_')) return false
    const parent = typeof block.parent === 'string' ? blocks[block.parent] : undefined
    return parent?.opcode === 'procedures_prototype'
  }

  function cleanupFloatingImportLiterals(literalInputs: Set<Blockly.BlockSvg>) {
    for (const literal of literalInputs) {
      if (!literal.getParent() && !literal.isDisposed()) literal.dispose(false)
    }
  }

	  function createLiteralInputBlock(value: unknown[], shadow: boolean, ownerOpcode?: string, inputName?: string, renderBlock = true) {
    const info = literalInputBlockInfo(value, ownerOpcode, inputName)
    if (!workspace || !info || !Blockly.Blocks[info.type]) return undefined
    const block = workspace.newBlock(info.type) as Blockly.BlockSvg
    block.setShadow(shadow)
    block.setFieldValue(info.value, info.field)
    attachScratchBlockState(block, {
      opcode: info.type,
      fields: info.scratchField ? { [info.scratchField]: [info.value, info.id ?? info.value] } : {},
      inputs: {},
      shadow,
      topLevel: false,
    } as ScratchBlock)
    block.initSvg()
    if (renderBlock) block.render()
    return block
  }

  function blocklyShadowStateFromLiteral(value: unknown[], ownerOpcode?: string, inputName?: string) {
    const info = literalInputBlockInfo(value, ownerOpcode, inputName)
    return info ? { type: info.type, fields: { [info.field]: info.value } } : undefined
  }

  function literalInputBlockInfo(value: unknown[], ownerOpcode?: string, inputName?: string) {
    const code = Number(value[0])
    const text = String(value[1] ?? '')
    const id = value[2] === undefined ? undefined : String(value[2])
    const contextualType = ownerOpcode && inputName ? literalShadowTypeForInput(ownerOpcode, inputName, code) : undefined
    if (contextualType) {
      const menuField = scratchMenuShadowFieldName(contextualType)
      if (menuField) return { type: contextualType, field: menuField, scratchField: menuField, value: text, id }
      if (contextualType === 'colour_picker') return { type: 'colour_picker', field: 'COLOUR', value: text }
      if (contextualType === 'data_variable') return { type: 'data_variable', field: 'VARIABLE_NAME', scratchField: 'VARIABLE', value: text, id }
      if (contextualType === 'data_listcontents') return { type: 'data_listcontents', field: 'LIST_NAME', scratchField: 'LIST', value: text, id }
      if (contextualType === 'text') return { type: 'text', field: 'TEXT', value: text }
      if (contextualType === 'math_number') return { type: 'math_number', field: 'NUM', value: text }
    }
    if (code === 4) return { type: 'math_number', field: 'NUM', value: text }
    if (code === 9) return { type: 'colour_picker', field: 'COLOUR', value: text }
    if (code === 10) return { type: 'text', field: 'TEXT', value: text }
    if (code === 11) return { type: 'event_broadcast_menu', field: 'BROADCAST_OPTION', scratchField: 'BROADCAST_OPTION', value: text, id }
    if (code === 12) return { type: 'data_variable', field: 'VARIABLE_NAME', scratchField: 'VARIABLE', value: text, id }
    if (code === 13) return { type: 'data_listcontents', field: 'LIST_NAME', scratchField: 'LIST', value: text, id }
    return undefined
  }

  function literalInputIsShadow(value: unknown[]) {
    const info = literalInputBlockInfo(value)
    return !!info && info.type !== 'data_variable' && info.type !== 'data_listcontents'
  }

  function blocklyShadowState(block: Blockly.BlockSvg) {
    const fields: Record<string, string> = {}
    for (const input of block.inputList) {
      for (const field of input.fieldRow) {
        if (field.name) fields[field.name] = String(field.getValue())
      }
    }
    return Object.keys(fields).length > 0 ? { type: block.type, fields } : { type: block.type }
  }

  function rememberScratchShadow(connection: Blockly.Connection, blockId: string) {
    ;(connection as Blockly.Connection & { __hikkakuScratchShadowId?: string }).__hikkakuScratchShadowId = blockId
  }
</script>


