              {/if}
              <div class="grid grid-cols-2 gap-2">
                <label class="text-xs font-semibold">Fill<input class="mt-1 h-9 w-full rounded border border-slate-200" type="color" bind:value={paintColor} onchange={() => markVectorStyleDirty('fill')} />{#if vectorSelectionSummary && isMixedSelectionValue(vectorSelectionSummary.fill)}<span class="ml-1 text-[10px] font-bold text-slate-500">MIXED</span>{/if}</label>
                <label class="text-xs font-semibold">Fill 2<input class="mt-1 h-9 w-full rounded border border-slate-200" type="color" bind:value={secondaryPaintColor} onchange={() => markVectorStyleDirty('fillSecondary')} />{#if vectorSelectionSummary && isMixedSelectionValue(vectorSelectionSummary.fillSecondary)}<span class="ml-1 text-[10px] font-bold text-slate-500">MIXED</span>{/if}</label>
                <label class="text-xs font-semibold">Stroke<input class="mt-1 h-9 w-full rounded border border-slate-200" type="color" bind:value={strokeColor} onchange={() => markVectorStyleDirty('stroke')} />{#if vectorSelectionSummary && isMixedSelectionValue(vectorSelectionSummary.stroke)}<span class="ml-1 text-[10px] font-bold text-slate-500">MIXED</span>{/if}</label>
                <label class="text-xs font-semibold">Stroke 2<input class="mt-1 h-9 w-full rounded border border-slate-200" type="color" bind:value={strokeSecondaryColor} onchange={() => markVectorStyleDirty('strokeSecondary')} />{#if vectorSelectionSummary && isMixedSelectionValue(vectorSelectionSummary.strokeSecondary)}<span class="ml-1 text-[10px] font-bold text-slate-500">MIXED</span>{/if}</label>
                <label class="text-xs font-semibold">Fill gradient
                  <select class="mt-1 w-full rounded border border-slate-200 px-2 py-1.5 text-sm" bind:value={paintGradient} onchange={() => markVectorStyleDirty('fillGradient')}>
                    <option value="solid">solid</option>
                    <option value="horizontal">horizontal</option>
                    <option value="vertical">vertical</option>
                    <option value="radial">radial</option>
                  </select>
                  {#if vectorSelectionSummary && isMixedSelectionValue(vectorSelectionSummary.fillGradient)}<span class="ml-1 text-[10px] font-bold text-slate-500">MIXED</span>{/if}
                </label>
                <label class="text-xs font-semibold">Stroke gradient
                  <select class="mt-1 w-full rounded border border-slate-200 px-2 py-1.5 text-sm" bind:value={strokeGradient} onchange={() => markVectorStyleDirty('strokeGradient')} data-testid="legacy-stroke-gradient">
                    <option value="solid">solid</option>
                    <option value="horizontal">horizontal</option>
                    <option value="vertical">vertical</option>
                    <option value="radial">radial</option>
                  </select>
                  {#if vectorSelectionSummary && isMixedSelectionValue(vectorSelectionSummary.strokeGradient)}<span class="ml-1 text-[10px] font-bold text-slate-500">MIXED</span>{/if}
                </label>
                <label class="text-xs font-semibold">Line<input class="mt-1 w-full rounded border border-slate-200 px-2 py-1.5 text-sm" type="number" min="0" max="100" bind:value={strokeWidth} onchange={() => markVectorStyleDirty('strokeWidth')} />{#if vectorSelectionSummary && isMixedSelectionValue(vectorSelectionSummary.strokeWidth)}<span class="ml-1 text-[10px] font-bold text-slate-500">MIXED</span>{/if}</label>
                <label class="text-xs font-semibold">Opacity<input class="mt-1 w-full rounded border border-slate-200 px-2 py-1.5 text-sm" type="number" min="0" max="100" bind:value={vectorOpacity} onchange={() => markVectorStyleDirty('opacity')} />{#if vectorSelectionSummary && isMixedSelectionValue(vectorSelectionSummary.opacity)}<span class="ml-1 text-[10px] font-bold text-slate-500">MIXED</span>{/if}</label>
              </div>
              <!-- First/second fill-color swap (Scratch Paint parity): exchanges
                the hex pickers together with their transparent flags, so a
                transparent primary round-trips exactly. Pure paint state only,
                always enabled. -->
              <button aria-label="Swap fill colors" title="Swap the first and second fill colors (with transparency)" data-testid="legacy-swap-fill-colors" class="mt-2 w-full rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold" onclick={swapFillPaint}>Swap fill colors</button>
              <button aria-label="Swap stroke colors" title="Swap the first and second stroke colors (with transparency)" data-testid="legacy-swap-stroke-colors" class="mt-2 w-full rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold" onclick={swapStrokePaint}>Swap stroke colors</button>
              <div class="grid grid-cols-2 gap-2">
                <label class="text-xs font-semibold">
                  Center X
                  <input class="mt-1 w-full rounded border border-slate-200 px-2 py-1.5 text-sm" type="number" value={selectedTarget?.costumes[selectedTarget?.currentCostume ?? 0]?.rotationCenterX ?? (selectedTarget?.isStage ? 240 : 48)} onchange={(event) => updateCostumeRotationCenter('x', event)} />
                </label>
                <label class="text-xs font-semibold">
                  Center Y
                  <input class="mt-1 w-full rounded border border-slate-200 px-2 py-1.5 text-sm" type="number" value={selectedTarget?.costumes[selectedTarget?.currentCostume ?? 0]?.rotationCenterY ?? (selectedTarget?.isStage ? 180 : 48)} onchange={(event) => updateCostumeRotationCenter('y', event)} />
                </label>
              </div>
              <div class={`relative flex aspect-square items-center justify-center rounded-md border bg-white p-2 ${selectedVectorObjectIndex >= 0 ? 'border-blue-300 ring-2 ring-blue-100' : 'border-slate-200'}`}>
                {#if costumePreviewUrl}
                  <img class="max-h-full max-w-full object-contain" src={costumePreviewUrl} alt="Costume preview" />
                {:else}
                  <div class="h-16 w-16 rounded-full border-4 border-orange-700 bg-orange-300"></div>
                {/if}
                {#each vectorObjects as object}
                  <button
                    class={`absolute border-2 bg-transparent ${selectedVectorObjectIndices.includes(object.index) || selectedVectorObjectIndex === object.index ? 'border-blue-500' : 'border-transparent hover:border-blue-300'}`}
                    style={vectorObjectOverlayStyle(object)}
                    aria-label={`Select ${object.label}`}
                    onpointerdown={(event) => beginVectorObjectDrag(object, event)}
                    onpointermove={dragVectorObject}
                    onpointerup={endVectorObjectDrag}
                    onpointercancel={() => (vectorDrag = undefined)}
                  ></button>
                {/each}
                {#if vectorObjects.find((object) => object.index === selectedVectorObjectIndex) && selectedVectorObjectIndices.length <= 1}
                  {@const selectedObject = vectorObjects.find((object) => object.index === selectedVectorObjectIndex)!}
                  {#each vectorResizeHandles as handle}
                    <button
                      class={`absolute h-4 w-4 rounded-sm border-2 border-white bg-blue-600 shadow ${handle.cursor}`}
                      style={vectorResizeHandleStyle(selectedObject, handle.id)}
                      aria-label={`Resize selected vector object ${handle.id}`}
                      onpointerdown={(event) => beginVectorObjectResize(selectedObject, handle.id, event)}
                      onpointermove={dragVectorObjectResize}
                      onpointerup={endVectorObjectResize}
                      onpointercancel={() => {
                        if (vectorResizeDrag?.committing) return
                        vectorResizeDrag = undefined
                      }}
                    ></button>
                  {/each}
                {/if}
                {#if vectorMultiSelectionBoundsState}
                  {@const multiBounds = vectorMultiSelectionBoundsState!}
                  <div
                    data-vector-multi-selection
                    class="pointer-events-none absolute border-2 border-blue-500 bg-transparent"
                    style={vectorMultiSelectionOutlineStyle(multiBounds)}
                    aria-hidden="true"
                  ></div>
                  {#each vectorResizeHandles as handle}
                    <button
                      class={`absolute h-4 w-4 rounded-sm border-2 border-white bg-blue-600 shadow ${handle.cursor}`}
                      style={vectorMultiResizeHandleStyle(multiBounds, handle.id)}
                      aria-label={`Resize vector selection ${handle.id}`}
                      onpointerdown={(event) => beginVectorMultiResize(handle.id, event)}
                      onpointermove={dragVectorObjectResize}
                      onpointerup={endVectorObjectResize}
                      onpointercancel={() => {
                        if (vectorResizeDrag?.committing) return
                        vectorResizeDrag = undefined
                      }}
                    ></button>
                  {/each}
                {/if}
                {#if selectedTarget?.costumes[selectedTarget.currentCostume ?? 0]}
                  <button
                    class="absolute h-5 w-5 rounded-full border-2 border-white bg-blue-600 shadow ring-2 ring-blue-200"
                    style={rotationCenterOverlayStyle()}
                    aria-label="Move rotation center"
                    onpointerdown={beginRotationCenterDrag}
                    onpointermove={dragRotationCenter}
                    onpointerup={endRotationCenterDrag}
                    onpointercancel={() => (rotationCenterDrag = undefined)}
                  ></button>
                {/if}
                {#if vectorObjects.find((object) => object.index === selectedVectorObjectIndex)}
                  <div class="absolute left-2 top-2 rounded bg-blue-600 px-2 py-1 text-[10px] font-bold text-white">
                    {vectorObjects.find((object) => object.index === selectedVectorObjectIndex)?.label}
                  </div>
                {/if}
              </div>
              <div class="rounded-md border border-slate-200 bg-white p-2">
                <div class="mb-2 flex items-center justify-between">
                  <h3 class="text-xs font-bold uppercase text-slate-500">Objects</h3>
                  <span class="text-[11px] font-semibold text-slate-500">{vectorObjects.length}</span>
                </div>
                <div class="max-h-32 space-y-1 overflow-auto">
                  {#each vectorObjects as object}
                    <button title={object.label} class={`flex w-full items-center justify-between rounded px-2 py-1 text-left text-xs font-semibold ${selectedVectorObjectIndices.includes(object.index) || selectedVectorObjectIndex === object.index ? 'bg-blue-100 text-blue-700' : 'bg-slate-50 text-slate-600'}`} onclick={(event) => selectVectorObject(object.index, event.shiftKey || event.metaKey || event.ctrlKey)}>
                      <span class="truncate">{object.label}</span>
                      <span class="ml-2 h-3 w-3 rounded-sm border border-slate-300" style={`background:${object.fill ?? object.stroke ?? '#fff'}`}></span>
                    </button>
                  {:else}
                    <p class="text-xs text-slate-500">No editable vector objects.</p>
                  {/each}
                </div>
                {#if selectedVectorObjectIndices.length > 1}
                  <p class="mt-2 text-[11px] font-semibold text-blue-700">{selectedVectorObjectIndices.length} objects selected</p>
                {/if}
                <div class="mt-2 grid grid-cols-4 gap-1">
                  <button title="Duplicate the selected objects" aria-label="Duplicate selection" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndex < 0} onclick={() => editVectorObject('duplicate')}>Copy</button>
                  <button title="Delete the selected objects" aria-label="Delete selection" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndex < 0} onclick={() => editVectorObject('delete')}>Delete</button>
                  <button title="Bring the selection to the front" aria-label="Bring to front" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndex < 0} onclick={() => editVectorObject('front')}>Front</button>
                  <button title="Send the selection to the back" aria-label="Send to back" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndex < 0} onclick={() => editVectorObject('back')}>Back</button>
                  <button title="Bring the selection one step forward" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndex < 0} onclick={() => editVectorObject('forward')}>Fwd</button>
                  <button title="Send the selection one step backward" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndex < 0} onclick={() => editVectorObject('backward')}>Backwd</button>
                  <button title="Group the selected objects" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndices.length < 2} onclick={() => editVectorObject('group')}>Group</button>
                  <button title="Ungroup the selected group" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndex < 0} onclick={() => editVectorObject('ungroup')}>Ungroup</button>
                  <button title="Move the selection left" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndex < 0} onclick={() => editVectorObject('left')}>Left</button>
                  <button title="Move the selection right" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndex < 0} onclick={() => editVectorObject('right')}>Right</button>
                  <button title="Move the selection up" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndex < 0} onclick={() => editVectorObject('up')}>Up</button>
                  <button title="Move the selection down" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndex < 0} onclick={() => editVectorObject('down')}>Down</button>
                </div>
                <!-- Mode-dispatching selection clipboard (both modes): copy in
                  vector mode falls back to every object when nothing is
                  selected; bitmap copy falls back to the trimmed raster. Paste
                  needs a clipboard entry for the active mode. Disabled while
                  the eyedropper overlay owns the canvas and (paste) while a
                  floating bitmap drag owns the preview. A bitmap destination
                  that is still loading/verifying (pending owner) disables both
                  copy and paste: the canvas still shows the previous asset, so
                  even a click would only safe-refuse. Text drafts live in
                  BitmapEditor and already swallow these shortcuts; the legacy
                  panel keeps the same guards as the toolbar. -->
                <div class="mt-2 grid grid-cols-2 gap-1">
                  <button
                    title="Copy the selection to the clipboard"
                    aria-label="Copy selection to clipboard"
                    data-testid="legacy-copy-costume-selection"
                    class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40"
                    disabled={eyedropperActive || (costumeEditMode === 'vector' ? vectorObjects.length === 0 : bitmapDestinationLocked)}
                    onclick={() => copyCostumeSelection()}>Copy selection</button>
                  <button
                    title={costumeEditMode === 'bitmap' && bitmapDestinationBusy ? 'Loading bitmap…' : 'Paste the clipboard selection'}
                    aria-label="Paste selection from clipboard"
                    data-testid="legacy-paste-costume-selection"
                    class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40"
                    aria-disabled={costumeEditMode === 'bitmap' && bitmapDestinationLocked ? 'true' : undefined}
                    disabled={eyedropperActive || (costumeEditMode === 'bitmap' && (bitmapFloatingDragActive() || bitmapDestinationLocked)) || (vectorClipboard.length === 0 && !bitmapClipboard)}
                    onclick={() => pasteCostumeSelection()}>Paste selection</button>
                </div>
                <div class="mt-2 grid grid-cols-3 gap-1">
                  <button title="Align left edges" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndices.length < 2} onclick={() => editVectorObject('align-left')}>Align L</button>
                  <button title="Align horizontal centers" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndices.length < 2} onclick={() => editVectorObject('align-center')}>Align C</button>
                  <button title="Align right edges" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndices.length < 2} onclick={() => editVectorObject('align-right')}>Align R</button>
                  <button title="Align top edges" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndices.length < 2} onclick={() => editVectorObject('align-top')}>Align T</button>
                  <button title="Align vertical centers" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndices.length < 2} onclick={() => editVectorObject('align-middle')}>Align M</button>
                  <button title="Align bottom edges" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndices.length < 2} onclick={() => editVectorObject('align-bottom')}>Align B</button>
                </div>
                <button title="Apply the current fill, stroke and opacity to the selection" class="mt-2 w-full rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold disabled:opacity-40" disabled={selectedVectorObjectIndex < 0} onclick={() => editVectorObject('style')}>Apply fill and stroke</button>
                {#if vectorSelectionHasUnresolvable && selectedVectorObjectIndex >= 0}
                  <p class="mt-1 text-[11px] font-semibold text-amber-700" data-testid="legacy-unresolvable-paint-note">Some sides show MIXED because their paint (inline style, class, inherited, semi-transparent, or url() fallback) could not be resolved. Applying edits only the fields you changed on resolvable sides; unknown sides are left untouched.</p>
                {/if}
                {#if vectorObjects.find((object) => object.index === selectedVectorObjectIndex)}
                  {@const selectedObject = vectorObjects.find((object) => object.index === selectedVectorObjectIndex)!}
                  <div class="mt-2 grid grid-cols-2 gap-2">
                    <label class="text-[11px] font-semibold text-slate-500">X<input class="mt-1 w-full rounded border border-slate-200 px-2 py-1 text-xs" type="number" value={selectedObject.x ?? 0} onchange={(event) => updateVectorObjectNumber('x', event)} /></label>
                    <label class="text-[11px] font-semibold text-slate-500">Y<input class="mt-1 w-full rounded border border-slate-200 px-2 py-1 text-xs" type="number" value={selectedObject.y ?? 0} onchange={(event) => updateVectorObjectNumber('y', event)} /></label>
                    <label class="text-[11px] font-semibold text-slate-500">W<input class="mt-1 w-full rounded border border-slate-200 px-2 py-1 text-xs" type="number" value={selectedObject.width ?? 100} onchange={(event) => updateVectorObjectNumber('width', event)} /></label>
                    <label class="text-[11px] font-semibold text-slate-500">H<input class="mt-1 w-full rounded border border-slate-200 px-2 py-1 text-xs" type="number" value={selectedObject.height ?? 100} onchange={(event) => updateVectorObjectNumber('height', event)} /></label>
                    <label class="text-[11px] font-semibold text-slate-500">Line<input class="mt-1 w-full rounded border border-slate-200 px-2 py-1 text-xs" type="number" min="0" value={selectedObject.strokeWidth ?? strokeWidth} onchange={updateVectorObjectStrokeWidth} /></label>
                    <label class="text-[11px] font-semibold text-slate-500">Opacity<input class="mt-1 w-full rounded border border-slate-200 px-2 py-1 text-xs" type="number" min="0" max="100" value={Math.round((selectedObject.opacity ?? 1) * 100)} onchange={updateVectorObjectOpacity} /></label>
                    <label class="col-span-2 text-[11px] font-semibold text-slate-500">Rotation<input class="mt-1 w-full rounded border border-slate-200 px-2 py-1 text-xs" type="number" value={selectedObject.rotation ?? 0} onchange={updateVectorObjectRotation} /></label>
                  </div>
                  {#if selectedObject.tag === 'text'}
                    <input class="mt-2 w-full rounded border border-slate-200 px-2 py-1 text-xs" value={selectedObject.text ?? ''} aria-label="Selected vector text" onchange={updateVectorObjectText} />
                  {/if}
                  <div class="mt-2 grid grid-cols-2 gap-1">
                    <button title="Scale the selection up by 10%" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold" onclick={() => scaleSelectedVectorObject(1.1)}>Grow</button>
                    <button title="Scale the selection down by 10%" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold" onclick={() => scaleSelectedVectorObject(0.9)}>Shrink</button>
                    <button title="Rotate the selection -15 degrees" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold" onclick={() => rotateSelectedVectorObject(-15)}>Rotate -15</button>
                    <button title="Rotate the selection +15 degrees" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold" onclick={() => rotateSelectedVectorObject(15)}>Rotate +15</button>
                    <button title="Flip the selection horizontally" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold" onclick={() => flipSelectedVectorObject(true)}>Flip H</button>
                    <button title="Flip the selection vertically" class="rounded border border-slate-200 bg-white px-2 py-1 text-xs font-semibold" onclick={() => flipSelectedVectorObject(false)}>Flip V</button>
                  </div>
                {/if}
              </div>
              <button data-testid="legacy-save-vector-costume" class="w-full rounded-md bg-blue-500 px-3 py-2 text-sm font-semibold text-white" onclick={saveVectorCostume}>Save vector</button>
            </div>
          </div>
            {#key projectViewportIdentity}
            <!-- Fresh BitmapEditor instance per project generation: viewport
              state (project + slot + costume + mode) lives inside BitmapEditor
              and its same-slot rollover would otherwise carry the previous
              project's settled zoom into the new project's identical slot
              (same target/index, same asset bytes). Remounting on the
              generation token guarantees a fresh fit per project while every
              same-project operation (save/undo/redo/rename/reorder/target
              switch/conversion) keeps the instance and its viewports. -->
            <BitmapEditor
              bind:bitmapCanvas
              {bitmapCanvasWidth}
              {bitmapCanvasHeight}
              bitmapResolution={storedBitmapResolutionOf(selectedTarget, selectedTarget?.currentCostume ?? 0)}
              bitmapFitState={bitmapFitState}
              bitmapWorkspaceBusy={bitmapDestinationBusy}
              bitmapDestructiveDisabled={bitmapDestinationLocked}
              bitmapPendingHas={bitmapPendingHas}
              bitmapPendingGap={bitmapPendingGap || bitmapPendingRecoveryGap}
              bitmapPendingQuarantined={bitmapPendingQuarantined}
              bitmapPendingRecoveryHas={bitmapPendingRecoveryHas}
              bitmapPendingKind={bitmapPendingKind}
              bitmapPendingMode={bitmapPendingMode}
              exportBitmapPendingQuarantined={exportBitmapPendingQuarantined}
              discardBitmapPendingQuarantine={discardBitmapPendingQuarantine}
              acknowledgeBitmapPendingGap={acknowledgeBitmapPendingGap}
              bind:costumeEditMode
              bind:bitmapTool
              bind:bitmapShapeMode
              bind:openStylePopover={paintPopoverOpen}
              bind:eyedropperActive
              bind:eyedropperTarget
              {applyEyedropperColor}
              bind:vectorShape
              bind:brushSize
              bind:vectorBrushSize
              bind:bitmapEraserSize
              bind:vectorEraserSize
              bind:paintColor
              bind:secondaryPaintColor
              bind:paintGradient
              bind:fillTransparent
              bind:secondaryTransparent
              bind:strokeTransparent
              bind:strokeColor
              bind:strokeSecondaryColor
              bind:secondaryStrokeTransparent
              bind:strokeGradient
              bind:strokeWidth
              bind:vectorOpacity
              bind:vectorText
              bind:vectorTextFontSize
              bind:vectorTextFontFamily
              bind:viewportScale={costumeViewportScale}
              vectorSelectionSummary={vectorSelectionSummary}
              markVectorStyleDirty={markVectorStyleDirty}
              applyHsvLive={handleHsvInput}
              commitHsvLive={handleHsvCommit}
              flushHsvLive={flushHsvLive}
              viewportKey={`${selectedTarget?.id ?? selectedTarget?.name ?? 'target'}:${selectedTarget?.currentCostume ?? 0}`}
              projectIdentity={projectViewportIdentity}
              costumeIdentity={costumeViewportIdentity}
              currentCostumeName={selectedTarget?.costumes[selectedTarget?.currentCostume ?? 0]?.name ?? ''}
              currentCostumePreviewUrl={costumePreviewUrl}
              currentCostumePreviewSvg={costumePreviewSvg}
              currentCostumeIndex={selectedTarget?.currentCostume ?? 0}
              updateCurrentCostumeName={(event) => selectedTarget && updateCostumeName(selectedTarget.currentCostume ?? 0, event)}
              canUndo={paintUndoStack.length > 0}
              canRedo={paintRedoStack.length > 0}
              {undoAssetEdit}
              {redoAssetEdit}
              {bitmapSelection}
              {bitmapClipboard}
              bitmapFloatingActive={Boolean(bitmapMoveDrag) || Boolean(bitmapScaleDrag) || Boolean(bitmapRotateDrag) || bitmapPendingTransformDragActive()}
              vectorClipboard={vectorClipboard}
              {vectorObjects}
              {selectedVectorObjectIndex}
              {selectedVectorObjectIndices}
              vectorCanvasWidth={480}
              vectorCanvasHeight={360}
              {beginBitmapPaint}
              {paintBitmap}
              {endBitmapPaint}
              {beginBitmapFloatingScale}
              {moveBitmapFloatingScale}
              {endBitmapFloatingScale}
              {beginBitmapFloatingRotate}
              {moveBitmapFloatingRotate}
              {endBitmapFloatingRotate}
              {pickBitmapColor}
              {clearBitmapCanvas}
              {copyBitmapSelection}
              {pasteBitmapSelection}
              {copyCostumeSelection}
              {pasteCostumeSelection}
              {cropBitmapSelection}
              {flipBitmap}
              {rotateBitmap}
              deleteCurrentCostume={() => selectedTarget && deleteCostume(selectedTarget.currentCostume ?? 0)}
              duplicateCurrentCostume={() => selectedTarget && duplicateCostume(selectedTarget.currentCostume ?? 0)}
              {deleteEditorSelection}
              {refreshAssetEditorPreviews}
              {convertCurrentCostumeToVector}
              {convertCurrentCostumeToBitmap}
              {saveVectorCostume}
              {findVectorTextIndexAtPoint}
              {commitVectorInlineText}
              {commitBitmapInlineText}
              {prepareVectorInlineTextFont}
              {saveVectorBrushStroke}
              {saveVectorShapeInRect}
              {fillVectorObjectAtPoint}
              {eraseVectorStroke}
              saveBitmapCostume={() => saveBitmapCostume()}
              {beginVectorObjectDragAtPoint}
              {beginVectorSelectedDragAtPoint}
              {dragVectorObject}
              {endVectorObjectDrag}
              {beginVectorObjectResize}
              {dragVectorObjectResize}
              {endVectorObjectResize}
              vectorMultiBounds={vectorMultiSelectionBoundsState}
              vectorCenterGuideOpacity={vectorDrag?.guideOpacity ?? 0}
              bitmapCenterGuideOpacity={bitmapMoveDrag?.guideOpacity ?? bitmapPendingMoveDrag?.guideOpacity ?? 0}
              bitmapArtCenterX={bitmapGuideArtCenterState?.x}
              bitmapArtCenterY={bitmapGuideArtCenterState?.y}
              {beginVectorMultiResize}
              {beginVectorObjectRotate}
              {dragVectorObjectRotate}
              {endVectorObjectRotate}
              {beginVectorMultiRotate}
              {beginVectorPathPointDrag}
              {dragVectorPathPoint}
              {endVectorPathPointDrag}
              beginVectorLeafTranslateDragAtPoint={beginVectorLeafTranslateDragAtPoint}
              dragVectorLeafTranslate={dragVectorLeafTranslate}
              endVectorLeafTranslateDrag={endVectorLeafTranslateDrag}
              {selectVectorObjectsInRect}
              {clearVectorObjectSelection}
              vectorReshapePointIndex={vectorReshapePointIndex}
              vectorReshapePointIndices={vectorReshapePointIndices}
              vectorReshapeHandleMasks={vectorReshapeHandleMasks}
              vectorReshapeLeafIndices={vectorReshapeLeafIndices}
              {selectVectorReshapePoint}
              {selectVectorReshapePoints}
              {selectVectorReshapeLeaves}
              {normalizeReshapeLeafToSelectRoot}
              {selectVectorReshapeLeafAtPoint}
              {toggleVectorReshapePoint}
              {selectVectorReshapePointsInRect}
              {addVectorPathPointAt}
              {deleteVectorReshapePoint}
              {deleteVectorReshapePoints}
              {curveVectorReshapePoint}
              {pointVectorReshapePoint}
              {updateVectorObjectStrokeWidth}
              applyVectorStyle={() => editVectorObject('style')}
              groupVectorSelection={() => editVectorObject('group')}
              ungroupVectorSelection={() => editVectorObject('ungroup')}
              bringVectorSelectionToFront={() => editVectorObject('front')}
              bringVectorSelectionForward={() => editVectorObject('forward')}
              sendVectorSelectionBackward={() => editVectorObject('backward')}
              sendVectorSelectionToBack={() => editVectorObject('back')}
              flipVectorSelection={(horizontal) => flipSelectedVectorObject(horizontal)}
            />
            {/key}
        {:else if !selectedExternalTabId && selectedTab === 'sounds'}
          <SoundEditor
            {selectedTarget}
            {selectedSoundIndex}
            assetUndoStack={soundUndoStack}
            assetRedoStack={soundRedoStack}
            {soundClipboard}
            {soundWaveform}
            bind:soundTrimStart
            bind:soundTrimEnd
            {soundPlayhead}
            {previewAudio}
            bind:soundTrimDrag
            {undoAssetEdit}
            {redoAssetEdit}
            {updateSoundName}
            {addSoundToBackpack}
            {restoreSoundFromBackpack}
            {generateTone}
            {previewSound}
            {stopPreviewSound}
            {copySound}
            {pasteSound}
            {copySoundToNew}
            {exportSound}
            {deleteSoundSelection}
            {editSound}
            {beginSoundWaveformSelection}
            {updateSoundWaveformSelection}
            {endSoundWaveformSelection}
            {beginSoundTrimHandle}
            {dragSoundTrimHandle}
            {endSoundTrimHandle}
            {updateSoundTrim}
          />
        {:else if activeContextTab?.plugin}
          <div class="h-full min-h-0 overflow-hidden" use:pluginView={activeContextTab.plugin}></div>
        {:else if activeContextTab}
          <div class="h-full min-h-0 overflow-hidden" use:mountElement={activeContextTab.content}></div>
        {:else if !selectedExternalTabId && selectedTab !== 'code'}
          <div class="flex min-h-[28rem] items-center justify-center text-sm text-slate-500">
            Select a tab to edit assets.
          </div>
        {/if}
        </div>
      </div>
    </section>

    <button
      class={`stage-pane-resizer min-h-0 w-2 cursor-col-resize border-x border-[#b8c6d8] bg-[#d7e5f6] transition-colors hover:bg-[#b8d3f5] focus:outline-none focus:ring-2 focus:ring-inset focus:ring-[#855cd6] ${stageFullscreen ? 'stage-pane-resizer--hidden' : ''}`}
      type="button"
      aria-label="Resize stage pane"
      title="Resize stage pane"
      onpointerdown={beginStagePaneResize}
      onkeydown={adjustStagePaneWidth}
    ></button>

    <aside data-testid="stage-pane" class={`flex min-h-0 flex-col overflow-hidden border-t border-[#b8c6d8] bg-[#e8f1fc] lg:border-t-0 ${stageFullscreen ? 'fixed inset-0 z-50 border-0 lg:border-0' : ''}`}>
      <StagePanel
        bind:stageCanvas
        {stageFullscreen}
        {snapshot}
        {fps}
        {llvmStats}
        {visibleMonitors}
        question={stageQuestion}
        questionId={stageQuestionId}
        answerQuestion={(answer) => {
          if (runtimeInWorker) { stageQuestion = null; runtimeWorker.answerPrompt(answer) }
          else vm.answerPrompt(answer)
        }}
        {toggleStageFullscreen}
        {pickSprite}
        {updateMouse}
        {beginStageSpriteDrag}
        {dragStageSprite}
        {endStageSpriteDrag}
        {cancelStageSpriteDrag}
        {cycleMonitorMode}
        {setMonitorMode}
        {hideMonitor}
        {editMonitorSliderLimit}
        {updateMonitorSlider}
        greenFlag={startProject}
        stopAll={stopProject}
        stepRuntime={stepProjectRuntime}
      />

      <SpritePane
        {selectedTarget}
        {stage}
        {sprites}
        {targetThumbnailUrls}
        {spriteContextMenu}
        {targetThumbnailKey}
        {activateOnEnter}
        {paintNewSprite}
        {openLibrary}
        {openSpritePicker}
        {surpriseSprite}
        {addSprite}
        {paintNewBackdrop}
        {openBackdropPicker}
        {surpriseBackdrop}
        {addLibrarySprite}
        selectTarget={(name) => void guardedSelectTarget(name)}
        {beginSpriteDrag}
        {dropSpriteOn}
        {clearSpriteDrag}
        {openSpriteContextMenu}
        {duplicateSpriteByName}
        {exportSpriteByName}
        {deleteSpriteByName}
        libraryItems={spriteLibrary}
        {updateTargetName}
        {updateNumber}
        {setDirection}
        {updateDirectionDial}
        {setRotationStyle}
        {setVisible}
      />
    </aside>
  </section>

  {#if pluginToasts.length > 0}
    <div class="plugin-toasts" aria-live="polite" aria-relevant="additions">
      {#each pluginToasts as toast (toast.id)}
        <div class="plugin-toast" data-kind={toast.kind} role="status">{toast.message}</div>
      {/each}
    </div>
  {/if}
</main>
